	public AdvisorPanel(ItemManager itemManager, Actions actions)
	{
		this.itemManager = itemManager;
		this.actions = actions;
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setBackground(Brand.BG_BASE);

		JPanel north = new JPanel(new BorderLayout(6, 0));
		north.setOpaque(false);

		/* A plain JButton.setBackground() is silently ignored by a lot of
		   Swing look-and-feels unless the button is ALSO told to actually
		   paint its content area — without these three calls this button
		   rendered as RuneLite's default (dark, easy to miss) button chrome
		   no matter what color was set here, which is almost certainly why
		   this kept reading as "invisible" despite being gold in the source.
		   Small and icon-only (Copilot puts its own gear in a corner, not a
		   full-width bar) — the fix was never needing the extra width, just
		   these three flags. */
		gearBtn.setText("⚙");
		/* Names the thing, then says what is in it. It listed five nouns and
		   never the word that tells you what pressing it does. */
		gearBtn.setToolTipText("<html><b>Settings</b><br>Advisor on/off, how often it re-checks, minimum profit,"
			+ "<br>blocked items, the website link, and a colour key.</html>");
		gearBtn.setOpaque(true);
		gearBtn.setContentAreaFilled(true);
		gearBtn.setBorderPainted(true);
		gearBtn.setFocusPainted(false);
		gearBtn.setFont(gearBtn.getFont().deriveFont(Font.BOLD, 13f));
		gearBtn.setMargin(new Insets(2, 6, 2, 6));
		gearBtn.setPreferredSize(new Dimension(26, 22));
		gearBtn.setMaximumSize(new Dimension(26, 22));
		/* Captured BEFORE anything is painted on top, so closing the menu can
		   put the look-and-feel's own colours back rather than a guess at
		   them — same approach as the pause button's idle pair. */
		gearIdleBackground = gearBtn.getBackground();
		gearIdleForeground = gearBtn.getForeground();
		setGearOpen(false);
		gearBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		/* Toggle, not just open. Swing dismisses an open JPopupMenu on the
		   mouse PRESS anywhere outside it, and the gear is outside it \u2014 so by
		   the time the button's action fires the popup is already gone, the
		   action opens a fresh one, and the menu looks like it cannot be
		   closed by the control that opened it.
		   isVisible() cannot see this: it is false by then. The dismissal
		   timestamp can, because that press hid the popup microseconds
		   earlier. Anything within the window is the click that closed it, so
		   it opens nothing. */
		gearBtn.addActionListener(e ->
		{
			if (System.currentTimeMillis() - settingsClosedAt < POPUP_REOPEN_GUARD_MS)
			{
				return;
			}
			showSettingsPopup();
		});
		// Lives in MainPanel's pinned top bar instead of up here — not added to
		// `north` itself, just built and kept as a field so MainPanel can
		// place the actual button wherever it wants.

		status.setForeground(Brand.TEXT_STRUCTURAL);
		status.setFont(status.getFont().deriveFont(11.5f));
		north.add(status, BorderLayout.CENTER);
		// Hidden while it has nothing to say. An empty JLabel still claims a
		// line's height plus this panel's gap, and the status is blank in
		// normal running — that was a strip of dead space under the toolbar.
		north.setVisible(false);
		statusBar = north;
		add(north, BorderLayout.NORTH);

		recommendationWrap.setOpaque(false);
		recommendationWrap.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));

		JPanel center = new JPanel();
		center.setLayout(new BoxLayout(center, BoxLayout.Y_AXIS));
		center.setOpaque(false);
		/* One box, not two. A watchlist click used to open a SECOND card
		   underneath the recommendation, so the panel showed two items at
		   once and you had to work out which number belonged to which — and
		   the two cards weren't even the same shape. There is one card now
		   and whatever you last pointed at owns it. */
		center.add(recommendationWrap);
		/* NORTH, not CENTER: BorderLayout.CENTER stretches its child to fill
		   the panel, which hands the BoxLayout above spare height to spread
		   across its children — the empty-space bug. NORTH gives it exactly
		   its preferred height instead, so nothing stretches. */
		JPanel centerHolder = new JPanel(new BorderLayout());
		centerHolder.setOpaque(false);
		centerHolder.add(center, BorderLayout.NORTH);
		add(centerHolder, BorderLayout.CENTER);
	}

	/** Builds a fresh popup on every open so it always reflects the latest
	 *  state stashed by update() — cheaper than keeping a live popup synced
	 *  while it's closed, and the popup is thrown away on dismiss anyway.
	 *  Everything that otherwise lives only in RuneLite's own plugin config
	 *  screen (the wrench icon, several clicks away) is here too, so routine
	 *  tweaks never require leaving this panel. */
	/** When the settings popup last closed. See the gear's action listener:
	 *  this is what lets a second click on the gear close the menu instead of
	 *  reopening it. */
	private long settingsClosedAt;
	/** Long enough to cover the gap between Swing hiding the popup and the
	 *  button firing (both inside one click), short enough that a deliberate
	 *  second click is never swallowed. */
	private static final long POPUP_REOPEN_GUARD_MS = 250;
	/** The look-and-feel's own colours for the gear, kept so closing the
	 *  settings menu can restore them exactly. See setGearOpen. */
	private Color gearIdleBackground;
	private Color gearIdleForeground;

	/**
	 * Gold only while the settings menu is actually open.
	 *
	 * It used to be gold always, which made the one button that opens a menu
	 * you rarely need the brightest object in the sidebar — brighter than the
	 * profit figure, and sitting first in a strip of five otherwise plain
	 * buttons, so the eye went to it every time the panel redrew. A
	 * permanently highlighted control is not highlighting anything.
	 *
	 * Lit while open, it is doing the job highlighting is for: saying which
	 * thing on screen this menu belongs to.
	 */
	private void setGearOpen(boolean open)
	{
		gearBtn.setBackground(open ? GOLD : gearIdleBackground);
		gearBtn.setForeground(open ? Color.BLACK : gearIdleForeground);
		/* A 1px line either way, only the colour changes. Restoring the
		   look-and-feel's own border for the idle state was the obvious
		   thing and it was wrong: that border carries several pixels of
		   inset, which inside a 26px button left the gear glyph no room and
		   Swing drew "…" in its place. */
		gearBtn.setBorder(BorderFactory.createLineBorder(open ? GOLD.darker() : Brand.BORDER_LIGHT, 1));
	}

	private void showSettingsPopup()
	{
		JPopupMenu popup = new JPopupMenu();
		popup.addPopupMenuListener(new javax.swing.event.PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(javax.swing.event.PopupMenuEvent e)
			{
				setGearOpen(true);
			}

			@Override
			public void popupMenuWillBecomeInvisible(javax.swing.event.PopupMenuEvent e)
			{
				settingsClosedAt = System.currentTimeMillis();
				setGearOpen(false);
			}

			@Override
			public void popupMenuCanceled(javax.swing.event.PopupMenuEvent e)
			{
				settingsClosedAt = System.currentTimeMillis();
				setGearOpen(false);
			}
		});
		popup.setBackground(Brand.BG_PANEL);
		popup.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));

		JPanel content = new JPanel();
		final List<JPanel> sections = new ArrayList<>();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setOpaque(false);

		/*
		 * Every setting the plugin has, here.
		 *
		 * RuneLite's own wrench menu lists them too, but it is a long way
		 * from the panel and it also showed the plugin's stored data — the
		 * favourite lists as raw JSON — which nobody should be editing by
		 * hand ("this wrench menu is unusable ... send all important settings
		 * to our other settings in plugin menu"). Those are hidden there
		 * now, and this popup is the complete set, grouped.
		 */
		final JPanel advisorSec = section(content, "Advisor", "advisor", sections);
		JCheckBox advisorBox = checkbox("Flip advisor (needs live prices)", settings.advisorOn);
		advisorBox.setToolTipText(tip("The only feature that goes online",
			"Suggestions, offer nudges and watchlist prices come from the OSRS "
				+ "Wiki's price API. Off makes no requests at all; tracking, "
				+ "history and stats keep working."));
		advisorBox.addActionListener(e -> actions.setAdvisorEnabled(advisorBox.isSelected()));
		advisorBox.setAlignmentX(0f);
		advisorSec.add(advisorBox);
		advisorSec.add(Box.createVerticalStrut(8));

		advisorSec.add(controlRow("Re-check every", intervalRow()));
		advisorSec.add(Box.createVerticalStrut(8));

		advisorSec.add(controlRow("Min. profit per suggestion", minProfitRow()));
		advisorSec.add(Box.createVerticalStrut(8));

		advisorSec.add(controlRow("Alert on big price moves", priceAlertRow()));
		content.add(sectionDivider());

		final JPanel displaySec = section(content, "Display", "display", sections);
		displaySec.add(controlRow("Buy / sell colours", colourThemeRow()));
		displaySec.add(Box.createVerticalStrut(8));

		/* First of the switches: the one most likely to be looked for. */
		final JCheckBox chartBox = checkbox("Price chart over the chat", settings.priceChart);
		chartBox.setToolTipText(tip("The pocketge.com chart, on the Grand Exchange",
			"While an offer is open, the item's chart sits over the chat: its "
				+ "prices, volume by price, the target and your offer. Off hides it."));
		chartBox.addActionListener(e -> actions.setPriceChart(chartBox.isSelected()));
		chartBox.setAlignmentX(0f);
		displaySec.add(chartBox);

		final JCheckBox scoreBox = checkbox("Score line on cards", settings.showFlipScore);
		scoreBox.setToolTipText(tip("The line under the item name",
			"On a buy, the 0–100 flip score and verdict. On a sell, how many "
				+ "days of the item's demand your stack is. Off hides the row; "
				+ "the ranking underneath is unchanged."));
		scoreBox.addActionListener(e -> actions.setShowFlipScore(scoreBox.isSelected()));
		scoreBox.setAlignmentX(0f);
		displaySec.add(scoreBox);

		final JCheckBox badgesBox = checkbox("Watchlist badges", settings.showBadges);
		badgesBox.setToolTipText(tip("The ▲/▼ chips and pulsing rows",
			"The range chips, the big-swing percentage and the pulsing row "
				+ "borders in your watchlist. Off gives a plain list; prices "
				+ "stay exactly as they are."));
		badgesBox.addActionListener(e -> actions.setShowBadges(badgesBox.isSelected()));
		badgesBox.setAlignmentX(0f);
		displaySec.add(badgesBox);

		final JCheckBox glowBox = checkbox("Watchlist glow borders", settings.rowGlow);
		glowBox.setToolTipText(tip("The glowing row borders",
			"Rows at a 5-day edge pulse and rows in a big swing are outlined. "
				+ "Off keeps the ▲/▼ chips and the swing %, in colour, without "
				+ "the borders. A row's right-click menu switches it too."));
		glowBox.addActionListener(e -> actions.setRowGlow(glowBox.isSelected()));
		glowBox.setAlignmentX(0f);
		displaySec.add(glowBox);

		final JCheckBox marksBox = checkbox("Mark bank stacks worth selling", settings.bankHighlights);
		marksBox.setToolTipText(tip("Outlines in your bank and inventory",
			"Stacks worth selling right now, priced to sell and worth enough "
				+ "after tax to bother. Hover a marked slot for what it is worth."));
		marksBox.addActionListener(e -> actions.setBankHighlights(marksBox.isSelected()));
		marksBox.setAlignmentX(0f);
		displaySec.add(marksBox);

		final JCheckBox holdBox = checkbox("Price and profit on hover over stacks", settings.holdingTips);
		holdBox.setToolTipText(tip("Any stack in your bank or inventory",
			"Hover it: what it sells for now. On one the plugin watched you "
				+ "buy, also what you paid and the profit available or the loss."));
		holdBox.addActionListener(e -> actions.setHoldingTips(holdBox.isSelected()));
		holdBox.setAlignmentX(0f);
		displaySec.add(holdBox);

		final JCheckBox alchBox = checkbox("High alch profit", settings.alchProfit);
		alchBox.setToolTipText(tip("What one high alch makes, when it pays",
			"On the hover over a stack and on the cards: its alch value, less a "
				+ "nature rune and what one cost you (on a buy, your bid), and when "
				+ "alching beats selling. Nothing when it does not pay."));
		alchBox.addActionListener(e -> actions.setAlchProfit(alchBox.isSelected()));
		alchBox.setAlignmentX(0f);
		displaySec.add(alchBox);

		final JCheckBox popsBox = checkbox("Profit pops on GE slots", settings.profitPops);
		popsBox.setToolTipText(tip("+2,000 gp off the slot that sold",
			"What a sell made floats up off its slot on the Exchange screen, "
				+ "red on a loss, and gold coins for something never bought, "
				+ "like sharks you cooked. Sold while you were away? It pops "
				+ "the next time you open the Exchange."));
		popsBox.addActionListener(e -> actions.setProfitPops(popsBox.isSelected()));
		popsBox.setAlignmentX(0f);
		displaySec.add(popsBox);


		final JCheckBox legendBox = checkbox("Key beside the bank", settings.bankLegend);
		legendBox.setToolTipText(tip("The small box next to the open bank",
			"Names the two marks: your current suggestion and the other stacks "
				+ "worth selling. Hovering a marked slot says the same thing."));
		legendBox.addActionListener(e -> actions.setBankLegend(legendBox.isSelected()));
		legendBox.setAlignmentX(0f);
		displaySec.add(legendBox);
		displaySec.add(Box.createVerticalStrut(8));

		content.add(sectionDivider());

		final JPanel blockedSec = section(content, "Never recommend", "blocked", sections);
		/*
		 * Rows of chips, wrapped by hand to the popup's own width.
		 *
		 * One FlowLayout panel never wraps inside a BoxLayout — it has no
		 * width to wrap to, so it asks for every chip on one line — and it
		 * was centre-aligned among left-aligned rows. Two blocked items were
		 * enough to widen the whole popup and push every other setting off
		 * to the right.
		 */
		final JPanel blockChips = new JPanel();
		blockChips.setLayout(new BoxLayout(blockChips, BoxLayout.Y_AXIS));
		blockChips.setOpaque(false);
		blockChips.setAlignmentX(0f);
		if (settings.blocked.isEmpty())
		{
			JLabel empty = new JLabel("Nothing blocked");
			empty.setForeground(Brand.TEXT_STRUCTURAL);
			empty.setAlignmentX(0f);
			empty.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 0));
			blockChips.add(empty);
		}
		else
		{
			JPanel row = null;
			int used = 0;
			for (String name : settings.blocked)
			{
				final JPanel c = chip(name);
				final int w = c.getPreferredSize().width + 4;
				if (row == null || (used + w > CHIP_ROW_WIDTH && used > 0))
				{
					row = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
					row.setOpaque(false);
					row.setAlignmentX(0f);
					blockChips.add(row);
					used = 0;
				}
				row.add(c);
				used += w;
			}
		}
		blockedSec.add(blockChips);
		final JCheckBox confirmBox = checkbox("Ask before blocking an item", settings.confirmBlock);
		confirmBox.setToolTipText(tip("A confirmation before the block button",
			"Blocking is silent and permanent until you undo it here. Turn "
				+ "this off if you block items often and would rather it just happen."));
		confirmBox.addActionListener(e ->
		{
			settings.confirmBlock = confirmBox.isSelected();
			actions.setConfirmBlock(confirmBox.isSelected());
		});
		confirmBox.setAlignmentX(0f);
		blockedSec.add(confirmBox);
		content.add(sectionDivider());

		final JPanel websiteSec = section(content, "Website link", "website", sections);
		JCheckBox bridgeBox = checkbox("Local website bridge", settings.bridgeOn);
		bridgeBox.setToolTipText(tip("Lets pocketge.com on this computer show your session",
			"Your flips, favourites and bank summary, served on 127.0.0.1 "
				+ "only. Other websites are refused. Off by default."));
		bridgeBox.setAlignmentX(0f);
		websiteSec.add(bridgeBox);
