	/** The gear/settings button itself, so MainPanel can place it at the
	 *  bottom of the sidebar (next to the website link) instead of here. */
	public JButton settingsButton()
	{
		return gearBtn;
	}

	/**
	 * Pause, for the pinned top bar.
	 *
	 * It moved out of the card's control row for the same reason Share did,
	 * with one addition: pausing is a mode, not an action on this card. The
	 * card it was attached to is exactly the thing that disappears when the
	 * advisor moves on, so the control for "stop moving on" travelled with
	 * the content it was meant to hold still. Up here it is in one fixed
	 * place whatever is on screen.
	 *
	 * Because the top bar is built once and never rebuilt, the button has to
	 * carry its own state — hence the field. It goes gold while paused, the
	 * same "this is on" language the gear uses, so the mode is legible from
	 * the strip without reading the card's footnote.
	 */
	public JButton pauseButton()
	{
		if (pauseBtn.getActionListeners().length > 0)
		{
			/* Already built. Returning it wired twice would toggle the mode
			   back to where it started on every click, which reads as a dead
			   button rather than as a double-fire. */
			return pauseBtn;
		}
		pauseBtn.setIcon(PAUSE_ICON);
		/* Pinned rather than inherited: the idle glyph is the panel's own
		   text colour, so it cannot pick up whatever the look-and-feel hands
		   a default JButton. */
		pauseBtn.setForeground(TEXT_MAIN);
		pauseBtn.setOpaque(true);
		pauseBtn.setContentAreaFilled(true);
		pauseBtn.setFocusPainted(false);
		pauseBtn.setMargin(new Insets(2, 6, 2, 6));
		pauseBtn.setPreferredSize(new Dimension(30, 22));
		pauseBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		pauseIdleBackground = pauseBtn.getBackground();
		pauseIdleForeground = pauseBtn.getForeground();
		syncPauseButton();
		pauseBtn.addActionListener(e ->
		{
			paused = !paused;
			syncPauseButton();
			if (!paused && heldBack != null)
			{
				setRecommendations(heldBack);
				return;
			}
			renderRecommendation();
		});
		return pauseBtn;
	}

	/** Keep the top-bar button telling the truth about the mode it toggles. */
	private void syncPauseButton()
	{
		pauseBtn.setToolTipText(paused
			? "<html><b>Paused</b><br>The card is being held on screen. Click to let it"
				+ "<br>start moving with the market again.</html>"
			: "<html><b>Pause the suggestions</b><br>Holds the current card on screen so it does not change"
				+ "<br>under you while you place the offer.</html>");
		/*
		 * Orange while paused, not gold and not the sell colour.
		 *
		 * Gold is the BUY colour on every card in the panel, so wearing it on
		 * a mode switch made the top strip look like it was saying something
		 * about a trade. Orange is what the rest of the plugin already uses
		 * for "read this, a state is on rather than a number" — the advisory
		 * line at the foot of every card, and the line where a profit figure
		 * would be when there is none. Pausing is exactly that kind of state.
		 */
		pauseBtn.setBackground(paused ? ADJUST : pauseIdleBackground);
		pauseBtn.setForeground(paused ? Color.BLACK : pauseIdleForeground);
	}

	/** Rebuild everything. Call on the EDT.
	 *  {@code favoriteIds} decides whether a
	 *  card's star renders filled or hollow. {@code settings} is stashed for
	 *  the next time the gear-icon popup opens — that's where every field on
	 *  it (advisor on/off, interval, blocklist, bridge, flip count)
	 *  gets edited. */
	/**
	 * A settings-only refresh, for preferences that change how the panel
	 * DRAWS rather than what it is drawing.
	 *
	 * Changing the colour theme wrote the config and repainted, and nothing
	 * moved: the panel only ever receives a Settings object from the advisor
	 * cycle, so the new colours did not arrive until the next recompute — up
	 * to five minutes later, or never while the advisor was paused. Reported
	 * as "I'm clicking settings and changing my colors and it's not changing
	 * anything plugin side".
	 *
	 * Separate from update() because the suggestions list is not available at
	 * the call site and passing an empty one would clear the card to make it
	 * change colour.
	 */
	public void applySettings(Settings next)
	{
		if (next == null)
		{
			return;
		}
		/* Same floor invalidation update() does: the score row is part of the
		   tallest shape, so toggling it has to send the floor back to be
		   re-measured or every card keeps the old height. */
		if (settings != null && next.showFlipScore != settings.showFlipScore)
		{
			cardFloor = -1;
		}
		settings = next;
		renderRecommendation();
		repaint();
	}

	public void update(List<Advisor.Suggestion> suggestions, Set<Integer> favoriteIds, Settings settings)
	{
		this.favoriteIds = favoriteIds != null ? favoriteIds : Set.of();
		/* The card floor is measured from the tallest shape a card can take,
		   and the score row is part of that shape — so a change to whether it
		   is drawn has to send the floor back for re-measuring. See cardFloor. */
		if (settings != null && this.settings != null && settings.showFlipScore != this.settings.showFlipScore)
		{
			cardFloor = -1;
		}
		this.settings = settings != null ? settings : this.settings;

		// Kept for the bank/GE overlays and the inspection card's rating
		// lookup. The sidebar itself no longer renders this ranked list
		// directly: it splits into "sell what you hold" and "deploy your
		// cash", which are the two decisions actually being made.
		renderRecommendation();

		revalidate();
		repaint();
	}

	/** Called when a Favorites row is clicked. The clicked item TAKES OVER
	 *  the one recommendation box until another row is clicked, Next is
	 *  pressed, or it's dismissed with the card's own close button. Pass null
	 *  to dismiss.
	 *
	 *  This BEATS an open GE offer screen. Both want the same box, but only
	 *  one of them is something you just did: opening an offer screen is
	 *  passive context, clicking a row is a request. While the offer card
	 *  outranked it, clicking Diamond necklace in the watchlist with an
	 *  Emerald necklace offer open simply did nothing, with no hint as to
	 *  why. Reuses the offer card's own Next dismissal, so opening a screen
	 *  for a different item still takes over as normal. */
	public void setSelectedItem(FavoritesPanel.Row r)
	{
		final int previous = this.selectedFavoriteId;
		this.selectedFavorite = r;
		this.selectedFavoriteId = r != null ? r.id : -1;
		if (previous != this.selectedFavoriteId)
		{
			inspectAsIdea = false;
		}
		if (r != null && geContextItemId != null)
		{
			this.geContextDismissedFor = geContextItemId;
		}
		/* Every route in and out of the inspection card comes through here —
		   a watchlist click, the ✕, and refreshSelectedFrom giving up on an
		   unfavorited item — so this is the one place that can tell the plugin
		   which item now needs a price series. */
		if (previous != this.selectedFavoriteId)
		{
			actions.onSelectedItemChanged(r != null ? r.id : null);
		}
		renderRecommendation();
	}

	/**
	 * Re-point the inspection card at the freshest Row for the same item.
	 *
	 * The Row a click hands us is a snapshot: FavoritesPanel.update()
	 * rebuilds every row object on each refresh, and the click closure
	 * captured whichever one existed at the time. Holding that original
	 * meant the card kept rendering what was known when you clicked — so a
	 * row clicked before the first price fetch landed (or before its rating
	 * was computed) stayed blank forever, showing nothing but the item name
	 * no matter how many refreshes went by. Look the item up again by id
	 * instead, every time the list is rebuilt.
	 */
	/** itemId -> {qty, gp} of buys older than the stack you hold, which
	 *  PAID @ leaves out — see FlipTracker.getHeldCost. Each card it applies
	 *  to says so and offers to forget them. */
	private java.util.Map<Integer, long[]> olderBuys = java.util.Collections.emptyMap();

	/** Call on the EDT, before the update that redraws the cards. */
	public void setOlderBuys(java.util.Map<Integer, long[]> older)
	{
		olderBuys = older != null ? older : java.util.Collections.emptyMap();
	}

	/** itemId -> high alchemy value, for every item the plugin has had a
	 *  card or a hover for; see setAlch. */
	private java.util.Map<Integer, Integer> alchValues = java.util.Collections.emptyMap();
	/** A nature rune's insta-buy; 0 when unknown. */
	private long naturePrice;

	/** The high alchemy values the plugin knows and a nature rune's price,
	 *  for the cards' ALCH EA figure. Taken up by the next draw. */
	public void setAlch(java.util.Map<Integer, Integer> valueByItem, long naturePrice)
	{
		this.alchValues = valueByItem != null ? valueByItem : java.util.Collections.emptyMap();
		this.naturePrice = naturePrice;
	}

	/** As setAlch, for a value looked up as its item came on screen — the
	 *  card is redrawn with it now rather than at the next round. */
	public void alchArrived(java.util.Map<Integer, Integer> valueByItem, long naturePrice)
	{
		setAlch(valueByItem, naturePrice);
		renderRecommendation();
	}

	/**
	 * The ALCH EA cell, or null: what one cast makes after a nature rune,
	 * against what one costs — on a sell, what you paid when tracked and
	 * otherwise the price on the card, the sale alching gives up; on a buy,
	 * the bid. The same figure as the stack's hover (HighAlch).
	 *
	 * "thouights on putting high alch ea profit on the flip trade idea cards
	 * too in this area" — the space beside VALUE on a sell. And on a buy:
	 * "where the high alch on this?" — Rune kiteshield bid at 31,730 alchs
	 * for 32,400, a floor under the flip if it never sells. Only when a cast
	 * makes something, as on the hover — "dont have it say negative".
	 */
	Card.Stat alchStat(Rec r)
	{
		final Integer value = alchValues.get(r.itemId);
		final boolean paid = r.sell && r.hasTrackedCost && r.unitCost > 0;
		final long cost = paid ? r.unitCost : r.unitPrice;
		if (!settings.alchProfit || value == null || !HighAlch.known(value, naturePrice, cost))
		{
			return null;
		}
		final long each = HighAlch.perCast(value, naturePrice, cost);
		if (each <= 0)
		{
			return null;
		}
		return new Card.Stat("ALCH EA", HighAlch.compact(each),
			tip(HighAlch.signed(each) + " gp a high alch",
				"Alchs for " + String.format("%,d", value) + ", less a nature rune at " + String.format("%,d", naturePrice)
					+ " and the " + String.format("%,d", cost)
					+ (!r.sell ? " you would bid: what it makes if the flip never sells." : paid ? " you paid." : " it sells for.")),
			TipStyle.GOOD);
	}

	private static int indexOfStat(List<Card.Stat> stats, String label)
	{
		for (int i = 0; i < stats.size(); i++)
		{
			if (label.equals(stats.get(i).label))
			{
				return i;
			}
		}
		return -1;
	}

	/** Whether {@code stats} fit across the card at the stat row's fonts and
	 *  gaps — the row does not wrap, and a cell pushed past the edge is cut. */
	static boolean statsFit(List<Card.Stat> stats)
	{
		int w = 0;
		for (int i = 0; i < stats.size(); i++)
		{
			final JLabel label = new JLabel(stats.get(i).label);
			label.setFont(label.getFont().deriveFont(Font.BOLD, 9f));
			final JLabel value = new JLabel(stats.get(i).value);
			value.setFont(value.getFont().deriveFont(Font.BOLD, 13f));
			w += Math.max(label.getPreferredSize().width, value.getPreferredSize().width) + (i > 0 ? statGap(stats) : 0);
		}
		return w <= CARD_INNER;
	}

	/** The space between stat cells: 16, or 12 with three across — the
	 *  ALCH EA cell beside QUANTITY and VALUE missed "130 / 81.6K gp" by a
	 *  few pixels at 16. Two across, as every card had before, unchanged. */
	static int statGap(List<Card.Stat> stats)
	{
		return stats.size() > 2 ? 12 : 16;
	}

	/** The footnote for a sell card whose item has older buys left over. */
	static String olderBuysNote(long qty)
	{
		return String.format("%,d", qty) + " older buys not counted";
	}

	/** Show the inspected item as your stack (false) or as a new trade
	 *  (true). Call on the EDT. */
	public void setInspectView(boolean asIdea)
	{
		inspectAsIdea = asIdea;
		renderRecommendation();
	}

	/**
	 * For the item's right-click menu, read on the client thread: null when
	 * this item's card is not up or there is nothing to swap (you hold none
	 * of it), otherwise which view a swap would go TO — true for the trade
	 * idea.
	 */
	public Boolean inspectSwapTarget(int itemId)
	{
		final FavoritesPanel.Row r = selectedFavorite;
		if (selectedFavoriteId != itemId || r == null || r.id != itemId || r.heldQty <= 0)
		{
			return null;
		}
		return !inspectAsIdea;
	}

	/** Whether the inspection card is up for this item. */
	public boolean inspecting(int itemId)
	{
		return selectedFavorite != null && selectedFavoriteId == itemId;
	}

	public void refreshSelectedFrom(List<FavoritesPanel.Row> rows)
	{
		if (selectedFavoriteId < 0 || rows == null)
		{
			return;
		}
		for (FavoritesPanel.Row r : rows)
		{
			if (r.id == selectedFavoriteId)
			{
				selectedFavorite = r;
				renderRecommendation();
				return;
			}
		}
		/*
		 * Not in this list: keep the card as it is.
		 *
		 * This used to end the inspection — for an item taken off the
		 * watchlist while inspected. But the plugin builds a row for whatever
		 * is inspected, favourite or not, on every refresh; the only list
		 * without it is one built before the click, still on its way here.
		 * One of those landing just after "PocketGE inspect" dropped the card
		 * for good, and with the offer screen's card already stood aside for
		 * the inspection, the box fell back to the ranked list mid-trade:
		 * "it flipped its focus off dragonstone bolt tips ... to uncut
		 * diamonds while i was making my trade". The ✕ and a new pick are
		 * what end an inspection.
		 */
	}

	/** The watchlist takeover: the item you clicked, in the same card as
	 *  everything else, with Next still on it so one press puts you back in
	 *  the flip stream. */
	/**
	 * The watchlist item you clicked, as a trade rather than as a quote.
	 *
	 * This card used to be built by hand, and it only knew one story: "here
	 * is a flip you could start on this item". So an account holding 4,811
	 * Diamond amulets — bought on this plugin's own recommendation — clicked
	 * the row and was told to buy ten thousand more, for 18.3M, with no
	 * mention of the ones already owned and no count of the ones to buy.
	 *
	 * The held position was never missing. FavoritesPanel.Row has carried
	 * heldQty, sellValue, heldProfit, hasCostBasis and pricedQty all along,
	 * and the plugin fills them for the inspected item on every refresh. This
	 * card simply never read any of them.
	 *
	 * It goes through {@link #cardFor} now, like the ranked cards and like the
	 * offer-screen takeover, which is also why it stops looking different from
	 * them: it was never a different design, just a different set of fields.
	 * The verb, the boxed pair, QUANTITY, the footnote and the white rim all
	 * arrive for free — including the quantity whose absence was reported,
	 * which is Rec.quantity and needed no work of its own once the card knew
	 * whether it was buying or selling.
	 */
	private JPanel favoriteBody()
	{
		final FavoritesPanel.Row r = selectedFavorite;
		final Rec shown = recFor(r);
		final Card c = cardFor(shown);

		/* The 5-day badge, which no ranked card has. The watchlist row pulses
		   for this and the glow does not survive the click, so it has to be
		   said in words here — the website says it the same way.

		   On the VERB row, which is the only slot that costs no height: it is
		   an X_AXIS BoxLayout already holding the verb and the provenance, and
		   its height is set by the tallest of them. A row of its own would put
		   this card over the card floor and move its buttons below every other
		   card's. */
		final String badge = extremeBadgeText(r.tier);
		if (badge != null)
		{
			c.provenance = c.provenance == null ? badge : c.provenance + "   \u00b7   " + badge;
			c.provenanceColor = r.tier.isHigh() ? FavoritesPanel.HIGH5D : FavoritesPanel.LOW5D;
		}

		/* The trade idea for something you hold says so, or a BUY card for an
		   item sitting in your bank reads as the plugin forgetting it. */
		if (!shown.sell && r.heldQty > 0)
		{
			c.provenance = "you hold " + String.format("%,d", r.heldQty);
		}

		c.close = smallBtn("✕", "Stop watching — back to the recommended flip",
			e -> setSelectedItem(null));

		JPanel controls = controlsRow();
		final boolean fav = favoriteIds.contains(r.id);
		addControl(controls, bigIconBtn(fav ? STAR_FILLED_ICON : STAR_HOLLOW_ICON,
			fav ? "Remove " + r.name + " from favorites" : "Add " + r.name + " to favorites",
			e -> actions.toggleFavorite(r.id, r.name)));
		/* Hold, when this is a sell — the same control the ranked sell cards
		   carry. You cannot hold something you do not own, so it appears for
		   the same reason it does there and on the same condition. */
		if (r.heldQty > 0)
		{
			addControl(controls, bigIconBtn(HOLD_ICON,
				"Hold your " + r.name + " — skip it for this session",
				e -> actions.skip(r.id)));
		}
		// The pager rides the right edge, as it does on the website.
		if (!recommendations.isEmpty())
		{
			c.pager = pagerBlock();
		}
		c.controls = controls;
		final JPopupMenu menu = cardPopup(r.id, r.name, r.hasCostBasis,
			() -> "inspected item (\u2715 card, " + (shown.sell ? "my stack" : "trade idea") + ")\n"
				+ describeRec(shown) + describeRow(r));
		if (r.heldQty > 0)
		{
			/* First, because it is the thing this card can do that no other
			   can: the same item, the other question. */
			final JMenuItem swap = new JMenuItem(shown.sell ? "Show as a new trade" : "Show my stack");
			swap.setToolTipText(shown.sell
				? "What buying " + r.name + " now would make, as if you held none"
				: "What selling the " + String.format("%,d", r.heldQty) + " you hold makes or loses");
			swap.addActionListener(e -> setInspectView(shown.sell));
			menu.insert(swap, 0);
		}
		c.contextMenu = menu;
		/* No "From your watchlist" footnote: you got here by clicking your
		   watchlist, so it only ever told you something you had just done. */
		return buildCard(c);
	}

	/**
	 * A watchlist row as a Rec, so the inspect card can be built by the same
	 * method every other card is.
	 *
	 * SELLING WINS WHEN YOU HOLD ANY. Asked for directly — "hard to say now
	 * because you may want to buy more, you may want to sell ... maybe default
	 * to selling what you have" — and it is the right default for a reason
	 * beyond preference: the sell is about gold you already have at risk,
	 * while the buy is a hypothetical. Buying more is still one right-click
	 * away on the card, and the ranked stream proposes buys of its own.
	 */
	private Rec recFor(FavoritesPanel.Row r)
	{
		final Rec rec = new Rec();
		rec.itemId = r.id;
		rec.name = r.name;
		rec.sell = r.heldQty > 0 && !(inspectAsIdea && r.id == selectedFavoriteId);
		rec.heldWhere = r.heldWhere;

		if (rec.sell)
		{
			rec.quantity = r.heldQty;
			rec.clearance = r.clearance;
			rec.tier = r.tier;
			/* The ask, not the bid: heldSell is what this card is telling you
			   to list at — the price the sell cards, the stack hovers and
			   the bank marks name for the same stack (Advisor.heldSellPrice),
			   the insta-buy when there is no series. The flip pair's ask and
			   the bid are only for a row built before it existed. It was
			   targetSell then row.price, the insta-SELL, so on a crossed book
			   this card asked 102 beside a hover at 100.

			   Already listed, though, and the price that matters is the one
			   you listed at — the card is then about what that offer makes,
			   the same "+200K" the slot's own tooltip shows, not a second
			   opinion on where to list. */
			rec.unitPrice = r.listedQty > 0 && r.listedPrice > 0 ? r.listedPrice
				: r.heldSell > 0 ? r.heldSell : r.targetSell > 0 ? r.targetSell : r.price;
			if (r.listedQty > 0)
			{
				rec.listingNote = "Listed at " + String.format("%,d", r.listedPrice) + " \u2014 "
					+ String.format("%,d", r.listedSold) + " of " + String.format("%,d", r.listedTotal) + " sold";
				rec.listingShort = new String[]{
					"Sold " + String.format("%,d", r.listedSold) + " of " + String.format("%,d", r.listedTotal)
						+ " at " + String.format("%,d", r.listedPrice),
					"Sold " + String.format("%,d", r.listedSold) + " of " + String.format("%,d", r.listedTotal),
				};
				rec.note = "listed at " + String.format("%,d", r.listedPrice) + " gp \u2014 "
					+ String.format("%,d", r.listedSold) + " of " + String.format("%,d", r.listedTotal) + " sold"
					+ (r.heldQty > r.listedQty
						? ", " + String.format("%,d", r.heldQty - r.listedQty) + " more not listed"
						: "");
			}
			rec.hasTrackedCost = r.hasCostBasis;
			if (r.hasCostBasis && r.pricedQty > 0)
			{
				/* heldProfit is the gain over the units the plugin actually
				   watched being bought — the same split every ranked sell card
				   makes, so the card's own footnote about scope is true here
				   without any extra work. */
				/*
				 * Paid, and the gain, from what those units actually cost and
				 * the price THIS card says to sell at.
				 *
				 * The paid figure was (sellValue - heldProfit) / pricedQty —
				 * the whole stack's proceeds less the gain on part of it,
				 * divided by that part. With 173 of 639 Mithril bars tracked
				 * that came to 3,252 gp each for bars bought at 876. And the
				 * gain was priced at the live insta-buy (900) under a SELL @
				 * box saying 896, so the two numbers on one card disagreed.
				 */
				final long netEach = rec.unitPrice - FlipTracker.taxPerItem(rec.unitPrice, rec.itemId);
				rec.unitCost = Math.round(r.pricedCost / (double) r.pricedQty);
				rec.profit = (long) r.pricedQty * netEach - r.pricedCost;
				rec.untrackedQty = Math.max(0, r.heldQty - r.pricedQty);
				rec.untrackedValue = (long) rec.untrackedQty * Math.max(0, netEach);
			}
			else
			{
				/* Bought before the plugin was watching. profit here is the
				   stack's proceeds, which is what cardFor expects on an
				   untracked sell — it prints no figure and says so. */
				rec.profit = r.sellValue;
			}
			return rec;
		}

		/* Nothing held: the buy pitch, but now with the quantity it never
		   stated. r.limit is the 4h buy limit, and it is the count the two
		   figures already on this card were always derived from —
		   potentialProfit is edge x limit and the capital line was
		   targetBuy x limit. Printing it makes the card's own arithmetic
		   checkable instead of implied. */
		/* What is left of it this window, when some has been bought: the
		   game will not fill more until the four hours are up, and a card
		   offering the whole limit again straight after a flip of it was
		   "still reccomending me that i buy this flip". Used up, the card
		   keeps the whole limit's figures — it is still the item's — and
		   says when it can be bought again. */
		final int left = r.limit > 0 ? Math.max(0, r.limit - r.limitUsed) : 0;
		final boolean partly = r.limitUsed > 0 && left > 0;
		/* Used up, the card sizes as the offer screen does: nothing to buy,
		   so no quantity, profit or capital to act on. It used to keep the
		   whole limit's figures — a BUY of 25,000 with "press E to fill it"
		   beside an offer screen that would fill nothing. */
		final boolean usedUp = r.limit > 0 && r.limitUsed > 0 && left == 0;
		final int qty = usedUp ? 0 : partly ? left : r.limit;
		rec.quantity = qty;
		/* So the card's advisory line says something about the ITEM rather
		   than falling through to "Arrows cycle 17 ideas" — which is both
		   useless and wrong here, since you arrived by clicking one row and
		   are not cycling anything. r.limit IS the 4h buy limit, so this is
		   simply true.

		   A used-up limit first, even over a live bid: a bid that cannot fill
		   until the limit is back is explained by the clock, not by where it
		   stands. Earned, so it is the card's warned footnote and wins over
		   "No margin right now". */
		rec.note = usedUp
			? FlipTracker.limitUsedNote(r.limitResetsAt - System.currentTimeMillis())
			: r.bidQty > 0
			/* Already buying it: where that offer is beats a fact about the
			   limit. */
			? "you're bidding " + String.format("%,d", r.bidPrice) + " gp \u2014 "
				+ String.format("%,d", r.bidFilled) + " of " + String.format("%,d", r.bidQty) + " bought"
			: partly
				? FlipTracker.limitLeftNote(left, r.limitResetsAt - System.currentTimeMillis())
			: "capped by the 4h buy limit";
		rec.noteEarned = usedUp;
		rec.unitPrice = r.targetBuy;
		rec.exitPrice = r.targetSell;
		rec.profit = usedUp ? 0 : partly && r.limit > 0 ? r.potentialProfit * qty / r.limit : r.potentialProfit;
		rec.capital = r.targetBuy > 0 && qty > 0 ? (long) r.targetBuy * qty : 0;
		/* Not the plan's sizing, so not its tooltip: this is one 4h limit
		   (or what is left of it) at the card's bid, whatever your purse
		   holds. */
		rec.capitalBasis = partly
			? "What is left of the 4h buy limit at this bid — not sized to your cash."
			: "One full 4h buy limit at this bid — not sized to your cash.";
		return rec;
	}

	/** Same card shell as everything else so the sidebar reads as "waiting"
	 *  rather than "empty" before login. */
	private JPanel loginPrompt()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setAlignmentX(0f);
		p.setBackground(OBSIDIAN_BG);
		p.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, GOLD),
			BorderFactory.createEmptyBorder(11, 12, 11, 10)));
		// Two plain labels rather than one <html> one. An HTML JLabel here
		// rendered its box but no visible text in the client, and a message
		// whose whole job is explaining an empty panel cannot itself be the
		// thing that fails to draw.
		/* The ONE logged-out message in the sidebar. It used to be a heading
		   plus a subtitle here, and then the watchlist, the finder and the
		   history each said their own version underneath — four blocks
		   explaining the same single fact, which made a logged-out panel look
		   broken rather than idle. One line, and everything below it simply
		   goes quiet. */
		JLabel title = new JLabel("Log in to the game to track flips");
		title.setForeground(GOLD);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 12f));
		title.setAlignmentX(0f);
		p.add(title);
		return p;
	}


	/** The offer on screen, as the figures a card is built from; null when
	 *  the screen closed. */
	public void setGeContext(Rec r)
	{
		final Integer itemId = r != null ? r.itemId : null;
		if (itemId == null || !itemId.equals(geContextDismissedFor))
		{
			/* A different item, or the screen closed: whatever you dismissed
			   is no longer what is on screen, so the takeover is earned
			   again. Without this, pressing Next once would suppress the
			   offer card for every subsequent offer too. */
			this.geContextDismissedFor = null;
		}
		this.geContextRec = r;
		this.geContextItemId = itemId;
		this.geContextName = r != null && r.name != null ? r.name : "";
		renderRecommendation();
	}

	/** The offer-screen takeover: what to type, for the item actually on
	 *  screen. Same shell as a recommendation so the box doesn't visibly
	 *  change shape when it switches over. */
	private JPanel geContextBody()
	{
		final int itemId = geContextItemId;
		final String name = geContextName;
		final Rec r = geContextRec;

		/* The same card as a recommendation, for the trade you are actually
		   about to place. This was three lines — "Sell at 779 gp each / also
		   written on the offer screen / Offer screen open" — in small grey
		   over an empty box, at the one moment you are committing gold. Now
		   it says what you paid, what to ask, what that makes and how many,
		   from the same figures and in the same places as every other card,
		   so nothing has to be re-learned on the offer screen. */
		final Card c = cardFor(r);
		/* The side's colour on the accent, unlike the ranked cards' constant
		   gold: this box has been taken over by the screen you have open,
		   and the stripe is what says so. */
		c.accent = r.sell ? sellColor() : buyColor();
		c.provenance = "offer screen open";
		/* Replaces the generic caveat, never an earned one. The footnote
		   chain has a default now, so "is it null" stopped being the right
		   question — it was always non-null, and this line simply vanished
		   from the offer card. A loss warning or "cost unknown" still wins;
		   "Profit if both offers fill" does not. */
		if (c.footnote == null || c.footnoteIsDefault)
		{
			c.footnote = "Written onto the offer screen";
			c.footnoteWarn = false;
			c.footnoteIsDefault = false;
		}

		JPanel controls = controlsRow();
		/* Next is here for the misclick: you opened an offer screen for the
		   wrong item and want the suggestion stream back without having to
		   close the screen first. Before this the takeover was a one-way
		   door for as long as the screen stayed up. No Back beside it: this
		   card is not a place in the stream, so there is nothing to go back
		   from. */
		final boolean fav = favoriteIds.contains(itemId);
		addControl(controls, bigIconBtn(fav ? STAR_FILLED_ICON : STAR_HOLLOW_ICON,
			fav ? "Remove " + name + " from favorites" : "Add " + name + " to favorites",
			e -> actions.toggleFavorite(itemId, name)));
		c.pager = pagerBlock();
		c.controls = controls;
		c.contextMenu = cardPopup(itemId, name, r.sell && r.hasTrackedCost,
			() -> "offer-screen card\n" + describeRec(r));
		return buildCard(c);
	}

	/** Matches the site's text-overflow ellipsis on the collapsed flip
	 *  card — long names get cut with an ellipsis; the full name is still
	 *  reachable via the row's tooltip. */
	/** A duration in seconds as the coarsest unit that still says something:
	 *  "18m", "2h", "1d". Only ever used for a price age, where the reader
	 *  wants to know the order of magnitude and never the seconds. */
	static String agoText(long seconds)
	{
		final long mins = Math.max(1, seconds / 60);
		if (mins < 60)
		{
			return mins + "m";
		}
		final long hours = mins / 60;
		return hours < 24 ? hours + "h" : (hours / 24) + "d";
	}


	private static String truncateName(String name, int max)
	{
		return name.length() > max ? name.substring(0, max - 1) + "…" : name;
	}


	/** Shared shell for the three top-of-panel sections — a small caps
	 *  title, an optional trailing control (only Recommended Flip uses this,
	 *  for its Next button — matches the website's own header-row Next
	 *  placement), and a chevron that toggles the body's visibility. Rebuilt
	 *  on every render() call like everything else in this panel, so the
	 *  toggle just flips the tracked boolean and re-renders. */
	private JPanel collapsibleSection(String title, JButton extra, boolean open, Runnable onToggle, JPanel body)
	{
		/* Clamped to its own preferred height on purpose. These sections
		   live in a BoxLayout.Y_AXIS column, and a JPanel reports an
		   unbounded maximum height, so BoxLayout hands every one of them a
		   share of whatever viewport height is left over and stretches them
		   — which is what turned this whole area into mostly empty space
		   with the content floating in it. */
		JPanel wrap = new JPanel()
		{
			@Override
			public java.awt.Dimension getMaximumSize()
			{
				return new java.awt.Dimension(Short.MAX_VALUE, getPreferredSize().height);
			}
		};
		wrap.setLayout(new BoxLayout(wrap, BoxLayout.Y_AXIS));
		wrap.setOpaque(false);
		wrap.setAlignmentX(0f);

		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setOpaque(false);
		/* A JPanel defaults to alignmentX 0.50, but `body` reports 0.00 —
		   Container.getAlignmentX() delegates to BoxLayout.getLayoutAlignmentX(),
		   which derives it from ITS children, and those are all left-aligned.
		   BoxLayout resolves a mixed column by summing max-ascent and
		   max-descent, so the column claims 343px for a 265px card and offsets
		   the 0.00 child by alignment x allocated-width. Measured: the body
		   landed at x=7451 in a 225px sidebar — every number painted far off
		   the right edge while the 0.50-aligned header stayed at x=0. That is
		   exactly "the header is there but the card is blank". */
		header.setAlignmentX(0f);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		header.setBorder(BorderFactory.createEmptyBorder(0, 2, 5, 2));
		JLabel titleLabel = new JLabel(title);
		titleLabel.setForeground(Brand.TEXT_STRUCTURAL);
		titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 10.5f));
		header.add(titleLabel, BorderLayout.WEST);

		JPanel headerRight = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		headerRight.setOpaque(false);
		if (extra != null)
		{
			headerRight.add(extra);
		}
		JLabel chevron = new JLabel(open ? "▾" : "▸");
		chevron.setForeground(Brand.TEXT_STRUCTURAL);
		chevron.setFont(chevron.getFont().deriveFont(10f));
		headerRight.add(chevron);
		header.add(headerRight, BorderLayout.EAST);

		/*
		 * On the children as well as the row, because Swing does not bubble.
		 *
		 * A mouse event goes to the deepest component under the pointer and
		 * stops there; a JLabel with no listener simply swallows it. So the
		 * header row was clickable everywhere EXCEPT on the two things that
		 * look like the control — its title and its chevron. That was a dead
		 * spot nobody noticed while the rows carried wide titles and you
		 * could hit the gap beside them. It stopped being survivable when the
		 * recommendation's title came off: the row was then empty apart from
		 * a chevron that did nothing, so a collapsed box could not be
		 * reopened by clicking the only mark on it.
		 */
		final MouseAdapter toggleOnClick = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e) { onToggle.run(); }
		};
		header.addMouseListener(toggleOnClick);
		titleLabel.addMouseListener(toggleOnClick);
		chevron.addMouseListener(toggleOnClick);
		/* `extra` is deliberately left out: it is a button with its own
		   action, and it sits in this row rather than belonging to it. */

		wrap.add(header);
		if (open)
		{
			body.setAlignmentX(0f);
			wrap.add(body);
		}
		return wrap;
	}

	/** A short placeholder for a section with nothing to show yet, in the
	 *  same bordered card shell as a real one. */
	/** Box.createVerticalStrut returns a Filler aligned 0.5, which puts a
	 *  centre-aligned child back into a left-aligned column and revives the
	 *  offset bug. Always use this instead. */
	private static java.awt.Component leftStrut(int h)
	{
		final Box.Filler f = (Box.Filler) Box.createVerticalStrut(h);
		f.setAlignmentX(0f);
		return f;
	}

	private JPanel emptyMiniBody(String text)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setBackground(OBSIDIAN_BG);
		p.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, Brand.BORDER_LIGHT),
			BorderFactory.createEmptyBorder(9, 12, 9, 10)));
		// Plain, not <html>. Wrapped HTML labels in this column rendered
		// their box but no visible text in the client, and an empty-state
		// message that itself fails to draw is worse than no box at all —
		// so these strings are kept short enough not to need wrapping.
		JLabel label = new JLabel(text);
		label.setForeground(Brand.TEXT_STRUCTURAL);
		label.setFont(label.getFont().deriveFont(12f));
		p.add(label, BorderLayout.CENTER);
		return p;
	}

	/** Before you're logged in there's no bank, no inventory and no offers,
	 *  so every box would sit empty and read as broken — which is exactly
	 *  how it looked. Say what's actually going on instead. */
	public void setLoggedIn(boolean loggedIn)
	{
		if (this.loggedIn == loggedIn)
		{
			return;
		}
		this.loggedIn = loggedIn;
		renderRecommendation();
	}

	/** Called whenever the plugin recomputes the recommendation stream —
	 *  sells out of your bank/inventory and buys sized to your liquid cash,
	 *  already ranked. Keeps your place in the list across refreshes where it
	 *  can, so a background tick doesn't yank the card you were reading. */
	public void setRecommendations(List<Rec> recs)
	{
		if (paused)
		{
			heldBack = recs; // holding the current card on screen deliberately
			return;
		}
		heldBack = null;
		final List<Rec> before = recommendations;
		final int at = recIndex;
		this.recommendations = recs != null ? recs : List.<Rec>of();
		recIndex = placeOf(before, at, recommendations);
		renderRecommendation();
	}

	/**
	 * Where the card you were on is in a new list: the same idea if it is
	 * still there, otherwise the one that came after it — "after i have a
	 * rune dart trade in, the rune dart reccomendation trade idea should
	 * automatically go to the next trade idea". An idea leaves the list once
	 * its offer is in, and going back to the first card made you page back
	 * to where you were. The first card when none of those survive.
	 */
	static int placeOf(List<Rec> before, int at, List<Rec> after)
	{
		if (before == null || at < 0 || at >= before.size())
		{
			return 0;
		}
		for (int k = at; k < before.size(); k++)
		{
			final Rec want = before.get(k);
			for (int i = 0; i < after.size(); i++)
			{
				if (after.get(i).itemId == want.itemId && after.get(i).sell == want.sell)
				{
					return i;
				}
			}
		}
		return 0;
	}

	/**
	 * An offer has just been placed for {@code itemId}, on the side
	 * {@code buy} says. Call on the EDT.
	 *
	 * Pause holds a card "so it does not change under you while you place
	 * the offer" — so once the offer for that card is in, the hold has done
	 * its job. It lifts, and the panel moves on to the next idea rather than
	 * sitting on one already placed: the rune dart card stayed up, paused,
	 * after the rune darts were bought. Any other offer leaves a pause alone.
	 */
	public void offerPlaced(int itemId, boolean buy)
	{
		final Rec showing = (recIndex >= 0 && recIndex < recommendations.size())
			? recommendations.get(recIndex) : null;
		if (!paused || showing == null || showing.itemId != itemId || showing.sell == buy)
		{
			return;
		}
		paused = false;
		syncPauseButton();
		/* Off the list it was on, and off any newer one held back: either may
		   predate the offer, and the idea is placed now whichever it is. */
		final List<Rec> before = recommendations;
		final int at = recIndex;
		final List<Rec> next = new ArrayList<>();
		for (Rec r : heldBack != null ? heldBack : before)
		{
			if (r.itemId != itemId || r.sell == buy)
			{
				next.add(r);
			}
		}
		heldBack = null;
		recommendations = next;
		recIndex = placeOf(before, at, next);
		renderRecommendation();
	}

	private void renderRecommendation()
	{
		recommendationWrap.removeAll();
		recommendationWrap.setVisible(true);
		if (recIndex >= recommendations.size())
		{
			recIndex = 0;
		}
		/* Logged out is a full stop — no bank, no offers, nothing to rank —
		   so it replaces the box outright, header and all, rather than
		   sitting under a "RECOMMENDED FLIP" title that can't be true yet. */
		if (!loggedIn)
		{
			recommendationWrap.add(loginPrompt(), BorderLayout.NORTH);
			recommendationWrap.revalidate();
			recommendationWrap.repaint();
			return;
		}
		/* Three things can own this box, in this order: the offer screen you
		   have open right now (that price is the only one that matters while
		   it's up), the watchlist item you deliberately clicked, then the
		   ranked stream. Each one TAKES OVER — none of them adds a second
		   card underneath, which is what the panel used to do. */
		final Runnable toggle = () -> { recommendationOpen = !recommendationOpen; renderRecommendation(); };
		/* Handed to whichever of the four builders below runs, without
		   threading a parameter through all four \u2014 none of them otherwise
		   cares which section it is inside. Set for the duration of the build
		   and cleared after; this is the EDT, and buildCard consumes it once.
		   See Card.collapse. */
		cardCollapse = recommendationOpen ? collapseChevron(toggle) : null;
		final JPanel body;
		final boolean offerOwnsBox = geContextItemId != null
			&& !geContextItemId.equals(geContextDismissedFor);
		try
		{
			if (offerOwnsBox)
			{
				body = geContextBody();
			}
			else if (selectedFavorite != null)
			{
				body = favoriteBody();
			}
			else
			{
				body = recommendations.isEmpty()
					? emptyMiniBody(settings.advisorOn
						? "Looking for flips\u2026"
						: "Advisor is off (\u2699 above).")
					: recommendationBody(recommendations.get(recIndex));
			}
		}
		finally
		{
			cardCollapse = null;
		}
		/* Tell the overlays what the card ended up showing. Announced here
		   rather than from Next/Back, because the card also changes when a
		   refresh re-ranks the list under you, and this is the one place that
		   every one of those routes passes through.
		   Deduped: this method runs on every rebuild, and an unchanged
		   recommendation is not news. */
		announceShownRecommendation(offerOwnsBox || selectedFavorite != null
			? null : (recommendations.isEmpty() ? null : recommendations.get(recIndex)));
		announceCardsAhead(offerOwnsBox || selectedFavorite != null || recommendations.isEmpty()
			? java.util.List.of() : cardsAhead(recommendations, recIndex));
		/* And the GE item search's chip, which has its own rule. Left alone
		   while the offer screen owns the box: that card is the offer you
		   are already making, and the chip keeps the idea from before it. */
		if (!offerOwnsBox)
		{
			announceSearchItem(searchItemFor(selectedFavorite != null ? recFor(selectedFavorite)
				: (recommendations.isEmpty() ? null : recommendations.get(recIndex))));
		}
		/*
		 * No title, in any state.
		 *
		 * "RECOMMENDED FLIP" and "SELL FROM YOUR BANK" went first: both named
		 * the box rather than saying anything about the idea in it, and this
		 * box is the recommendation area, which is not in doubt when you are
		 * looking at it.
		 *
		 * YOUR OFFER and WATCHING were kept back on the argument that they
		 * mark the box being taken over by something else. They do — but each
		 * one spends a whole row of a 225px sidebar saying what its own card
		 * says anyway: the watching card is the only one with a dismiss ✕ on
		 * it, and the offer card carries "also written on the offer screen"
		 * and an "Offer screen open" footnote. A caption that repeats the
		 * thing underneath it is not orientation, it is a line of pixels.
		 *
		 * The collapse chevron keeps the row, which is why this is still a
		 * titled section and not a bare panel.
		 */
		if (recommendationOpen)
		{
			/* No header row at all. With the titles gone it held nothing but
			   a chevron, and 27px of empty strip above the one thing on the
			   panel you actually read is not a price worth paying for a 10px
			   glyph. The chevron went onto the card itself — see Card.collapse
			   and the EAST slot in buildCard.
			   Collapsed it comes back, because then there is no card to put it
			   on and it is the only way left to reopen the box. */
			body.setAlignmentX(0f);
			recommendationWrap.add(body, BorderLayout.NORTH);
		}
		else
		{
			/* Named, not blank.
			 *
			 * The title was "" because open the box has no header at all —
			 * the chevron rides on the card. Collapsed, the header is the
			 * only thing left, and with an empty title it was a bare strip
			 * with a chevron at the far end: nothing to say what had gone,
			 * or that anything had. Closing a box should leave a label
			 * behind, not a gap with a control in it. */
			recommendationWrap.add(collapsibleSection("Recommendations hidden", null, false, toggle, body),
				BorderLayout.NORTH);
		}
		recommendationWrap.revalidate();
		recommendationWrap.repaint();
	}

	/**
	 * The card for one trade, minus its buttons: name, verb, score, the
	 * boxed pair, profit, the labelled figures, and whichever footnote the
	 * numbers earn. Shared by the ranked stream and the offer-screen
	 * takeover, so the item you are about to price on the Exchange is drawn
	 * exactly the way the one the plugin proposed was.
	 */
	private Card cardFor(Rec r)
	{
		final boolean untracked = r.sell && !r.hasTrackedCost;

		Card c = new Card();
		/*
		 * The side of the trade, in the side of the card.
		 *
		 * This was pinned to gold for a while, on the argument that most cards
		 * are sells so a teal stripe would read as permanently teal and stop
		 * carrying anything. That argument was weak — a stripe that is usually
		 * teal because you are usually selling is correct, not broken — and it
		 * left the ranked cards disagreeing with the offer-screen takeover,
		 * which has always coloured its accent by side (see geContextBody).
		 *
		 * There is also more carrying the distinction now than there was when
		 * it was pinned: the verb is upper case and coloured, and the box you
		 * are acting on takes a white rim. The stripe agrees with both rather
		 * than being the one element on the card that says nothing.
		 */
		c.accent = r.sell ? sellColor() : buyColor();
		c.itemId = r.itemId;
		c.name = r.name;
		/* "Target sell" / "Target buy" in white, then the numbers in the
		   site's sell/buy colour \u2014 the same wording and the same hues the
		   website's own target row uses, so the two read as one product. */
		/* Name, then the verb under it, then the numbers — each in its own
		   place. This card has been a sentence ("Buy 13,000 / Tin ore / for
		   15 gp ea") and a spec sheet ("Target buy / 13,000 @ 15 gp ea")
		   before now, and the sentence lost its own quantity: written in the
		   buy colour above the name it read as a label, and the report came
		   back as "include the quantity", about a card that had it in bold on
		   line one. So: the name leads, as it does on the site; a one-word
		   verb says which way; the two prices are the boxed pair; and the
		   quantity is a labelled figure beside capital, where a number you
		   are about to type is looked for. */
		c.actionLabel = null;
		c.actionText = null;
		c.actionLead = null;
		c.actionTrail = null;
		c.verb = r.sell ? "Sell" : "Buy";
		c.actionColor = r.sell ? sellColor() : buyColor();
		c.pair = new Card.PricePair();
		if (r.sell)
		{
			/* What you paid on the left, in the buy colour, because it IS the
			   buy half of this flip — just one that already happened. A dash
			   when the plugin never saw it. */
			c.pair.buyLabel = "PAID @";
			c.pair.buy = r.unitCost;
			c.pair.buyTip = r.unitCost > 0
				? tip("You paid " + String.format("%,d", r.unitCost) + " gp each", "Average over the units tracked.")
				: tip("Cost unknown", "The plugin never watched you buy this stack.");
			c.pair.sellLabel = "SELL @";
			c.pair.sell = r.unitPrice;
			c.pair.sellTip = tip("Ask " + String.format("%,d", r.unitPrice) + " gp each",
				"Click to copy it. In the game's price box, press E to fill it.");
			/* PAID @ is history, not a price to place — see PricePair. */
			c.pair.sellFills = true;
			/* On a sell, SELL @ is the instruction. */
			c.pair.sellLead = true;
		}
		else
		{
			c.pair.buyLabel = "BUY @";
			c.pair.buy = r.unitPrice;
			c.pair.buyTip = tip("Bid " + String.format("%,d", r.unitPrice) + " gp each",
				"Click to copy it. In the game's price box, press E to fill it.");
			c.pair.buyFills = true;
			/* And on a buy it is BUY @ — the number you are being told to
			   place. The other box is what the profit assumes. */
			c.pair.buyLead = true;
			c.pair.sellLabel = "SELL @";
			c.pair.sell = r.exitPrice;
			c.pair.sellFills = true;
			c.pair.sellTip = r.exitPrice > 0
				? tip("Sell back at " + String.format("%,d", r.exitPrice) + " gp",
					"What the profit assumes. Click to copy it.")
				: tip("No exit price yet", null);
		}
		/* Buys the engine has scored, when the row is wanted. Sells are not
		   scored: the site rates ideas it is proposing, and a stack you
		   already hold is not one. */
		c.score = r.sell || !settings.showFlipScore ? null : r.score;
		/* A sell gets the measurement in the same slot. One setting governs
		   both rows: they occupy the same place on the card and a player who
		   turned "on cards" off does not want one of them back. */
		c.clearance = r.sell && settings.showFlipScore ? r.clearance : null;
		/* The figures you type, labelled. Capital is HERE now rather than in
		   the stacked block further down, so the two sit side by side as the
		   pair they are — how many, and what that costs. */
		c.stats = new ArrayList<>();
		c.stats.add(new Card.Stat("QUANTITY", String.format("%,d", r.quantity),
			tip(String.format("%,d", r.quantity) + (r.sell ? " to sell" : " to buy"),
				r.sell ? "The stack in your bank." : "In the game's quantity box, press E to fill it.")));
		if (!r.sell && r.capital > 0)
		{
			/*
			 * Beside QUANTITY again, not stacked under it.
			 *
			 * It was moved to its own line so it could not read as a second
			 * count, and the accent on its figure does that job on its own.
			 * What the stacked version cost was two extra rows on every buy,
			 * which made a buy card 49-73px taller than any sell — so paging
			 * between them moved the chevrons by that much, which is the
			 * bouncing reported twice. The website's own card puts its two
			 * figures side by side for the same reason.
			 *
			 * It fits: QUANTITY's cell is ~50px, the gap 16, and
			 * "20,160,000 gp" at 13f is ~98px — 164 of the 182 available.
			 * statsRow sizes each cell to its own content rather than
			 * splitting the width evenly, which is why this works now and
			 * did not when it was a GridLayout.
			 */
			c.stats.add(new Card.Stat("CAPITAL NEEDED", String.format("%,d", r.capital) + " gp",
				tip(String.format("%,d", r.capital) + " gp tied up",
					r.capitalBasis != null ? r.capitalBasis
						: "Sized to the cash you have free and the slots you have spare."),
				buyColor()));
		}
		if (r.sell)
		{
			/*
			 * What the whole stack fetches, on EVERY sell rather than only
			 * the untracked ones.
			 *
			 * "how much money would you get, how much is the stack worth at
			 * that sell price would be usefull" — and it was the one figure
			 * the card made you work out. The profit line answers "what did I
			 * make", which is a different question from "what do I walk away
			 * with", and on a partly tracked stack the two are wildly apart.
			 *
			 * Beside QUANTITY at stat size, deliberately not near the profit
			 * figure: "profit is the most important so smaller than profit,
			 * same size as that quantity maybe and to the right".
			 *
			 * Always quantity x price after tax, never the profit field —
			 * that is a gain on the tracked units only and would print a
			 * fraction of the stack's worth on a partly tracked card.
			 */
			final long net = r.unitPrice - FlipTracker.taxPerItem(r.unitPrice, r.itemId);
			final long worth = Math.max(0, net) * (long) r.quantity;
			if (worth > 0)
			{
				c.stats.add(new Card.Stat("VALUE", QuantityFormatter.quantityToStackSize(worth) + " gp",
					tip(String.format("%,d", worth) + " gp after tax",
						"What the whole stack fetches at " + String.format("%,d", r.unitPrice)
							+ " gp. Not profit.")));
			}
		}
		final Card.Stat alch = alchStat(r);
		if (alch != null)
		{
			c.stats.add(alch);
			/* A buy's capital is the wide one: "CAPITAL NEEDED" over
			   "2,221,100 gp". With a third cell beside it the label is
			   CAPITAL and the figure drops its " gp" — the same number in
			   full, never abbreviated. */
			final int capAt = r.sell ? -1 : indexOfStat(c.stats, "CAPITAL NEEDED");
			final Card.Stat wideCap = capAt >= 0 ? c.stats.get(capAt) : null;
			if (!statsFit(c.stats) && wideCap != null)
			{
				c.stats.set(capAt, new Card.Stat("CAPITAL", String.format("%,d", r.capital), wideCap.tip, wideCap.valueColor));
			}
			if (!statsFit(c.stats))
			{
				c.stats.remove(alch); // a quantity or capital in the millions: the hover still has it
				if (wideCap != null)
				{
					c.stats.set(capAt, wideCap);
				}
			}
		}
		/* Where the stack IS, not where stacks usually are. This was the
		   constant "from your bank" on every sell — see heldWhere. */
		/* A sell says "from your bank"; a buy said nothing, leaving a gap
		   beside the verb on every buy card. "from the Exchange" is the
		   honest parallel — it is where the item comes from, stated the same
		   way, and it needs nothing the plugin has to guess. Deliberately
		   NOT a fill-time estimate: how long an offer takes to fill is a
		   forecast, and the card does not make those. */
		c.provenance = r.sell ? r.heldWhere : "from the Exchange";
		/* What it cost is the other half of the decision on a held stack, so
		   it stays. The "-14 gp/item margin at today's spread" line that used
		   to appear instead on an untracked stack is gone: a NEGATIVE margin
		   under a sell suggestion reads as "this is a bad idea" when the
		   actual message is "you already own it, sell it anyway". */
		/* The quantity goes in when only part of the stack is tracked, because
		   then this line is also the scope of the P&L below it: "bought at 517"
		   next to "sell 18,000" invites you to read the P&L as covering all
		   18,000, and it doesn't. */
		/* Exact, with separators, like every other per-unit price on the card.
		   quantityToStackSize prints 1141 beside a "for 1,144 gp ea" that has
		   a comma, and above ten thousand it abbreviates — so a cost basis of
		   12,500 rendered "12.5K" directly under an exact asking price. Two
		   prices on adjacent lines in two different notations invite the
		   reader to compare them, which is the one thing they must be able to
		   do at a glance. */
		/* The plain "bought at 950 gp ea" line is gone — the PAID @ box above
		   is that number. The partly-tracked form survives, because there the
		   line is doing a second job the box cannot: saying HOW MANY of the
		   stack the price applies to, which is also the scope of the P&L. */
		/*
		 * The row under the price pair says where the PAID figure came from,
		 * on every sell.
		 *
		 * A partly tracked stack says how many units that price covers. An
		 * untracked one says why there is a dash there instead — which is
		 * the same sentence that used to sit two rows lower, in the profit
		 * slot. Moving it up puts it beside the thing it explains and leaves
		 * this row filled on both, which is what "add words here in every
		 * card to keep consisted, that daimond exmaple has none" asked for.
		 */
		/*
		 * A buy has one too now. Every sell card carries a line under the
		 * price pair and the buy carried nothing, so the figure below it
		 * started a row higher — "diambond necklace is missing text above the
		 * profit 144k in that examppleevery other card has text there".
		 *
		 * It says the condition the projection rests on, which is the same
		 * job the sell's line does for the PAID box: that number is not money
		 * you have, it is money you get IF both sides fill.
		 */
		c.subText = !r.sell ? (r.profit != 0 ? "If both offers fill" : null)
			: r.unitCost > 0
				/*
				 * "Paid on 1,456 of 8,944", and the per-unit price is NOT
				 * repeated here.
				 *
				 * It read "bought 1,456 at 2,495 gp ea" over "QUANTITY 8,944"
				 * and never said the 1,456 was part of the 8,944 — "whys ti
				 * say i bought 1,456 and also 8000 tho thats confusing". The
				 * first fix said so in full and came to 275px on a 182px
				 * card, which clips silently: the line has been truncated for
				 * as long as it has existed, and saying MORE made it worse.
				 *
				 * Dropping the price is what makes it fit, and it costs
				 * nothing — 2,495 is in the PAID @ box one row above. This
				 * row's job, per its own reason for existing, is to say how
				 * many of the stack that box covers.
				 */
				? paidOn(r)
				/* Explains the dash in the PAID box directly above it. The
				   profit slot two rows down says the consequence — that there
				   is no P&L to show — so the two lines do different jobs
				   rather than repeating one. */
				: untracked ? "no buy price on record" : null;
		c.profitValue = r.profit;
		/* Three different claims, three different words, so none can be
		   mistaken for another: a buy projects "profit", a sell with a known
		   cost measures "P&L", and a sell without one can only report what
		   the sale brings in. That last one is green now \u2014 money arriving
		   IS good news \u2014 but it is never called profit, because the plugin
		   has no idea what the stack cost you. */
		/* "profit", not "P&L", on a tracked sell. The distinction P&L was
		   drawn for — measured versus projected — is not something the
		   abbreviation actually conveys, and it is jargon in a card whose
		   whole job is to read as plain instruction. */
		/* "available" on a sell: the gain is there to be taken, not taken —
		   "its saying profit 1038 ... maybe it should say profit available.
		   i havent sold it for profit yet". */
		/* And none of that on a loss: "-110K gp profit available" was the
		   card's way of putting it, beside a hover that said "-110K gp if
		   you sell" about the same stack. */
		c.profitSuffix = !r.sell ? "gp profit" : r.profit < 0 ? "gp if you sell" : "gp profit available";
		/*
		 * No headline figure at all when the cost is unknown.
		 *
		 * That slot said "30.3M gp sale value" — a number every other card
		 * uses for profit, wearing a different word. It was green once and
		 * read as 30.3M of upside; plain text and a footnote were the next
		 * two attempts, and it still read as a gain, because a large figure
		 * in the position where gains live is a strong claim and quiet words
		 * beside it are a weak correction.
		 *
		 * So it goes. There is no profit to report on a stack the plugin
		 * never watched you buy, and the honest card says nothing where the
		 * others say a number. What the stack fetches is still on it, as a
		 * labelled VALUE beside the quantity — the same shape every other
		 * card's figures take.
		 */
		if (untracked)
		{
			/* No figure — there is no profit to report on a stack the plugin
			   never watched you buy — but the row is not empty. A card with a
			   blank here is shorter than every other card by the tallest row
			   on it, which is what "to keep all car[d] sizes same" is about. */
			c.profitValue = null;
			c.profitNote = "Held before PocketGE";
		}
		c.profitTooltip = untracked
			? tip("Proceeds, not profit", "What the stack fetches after tax. The plugin never saw what you paid.")
			: r.untrackedQty > 0
				? tip("Covers " + String.format("%,d", r.quantity - r.untrackedQty) + " units",
					"The other " + String.format("%,d", r.untrackedQty) + " cost an unknown amount.")
				: r.sell
					? tip("Profit after the 2% tax", "Measured against what you paid.")
					: tip("Profit after the 2% tax", "Projected, if it fills at both prices.");
		/* Buys only. On a sell the action line above already IS the sell
		   price, and printing the same number twice on one card is the note
		   that came back about the watching card. */
		c.exitPrice = r.sell ? 0 : r.exitPrice;
		/*
		 * Its own line under the stats, not a third stat cell.
		 *
		 * As a cell it sat immediately right of QUANTITY in the same 9f grey
		 * label over the same 13f near-white figure, so "10,000" and
		 * "100,000 gp" read as a matched pair of counts — and they are not:
		 * one is how many you are buying, the other is gold leaving your
		 * bank. Reported as "move capital needed down, put it in a different
		 * color than white maybe".
		 *
		 * The stacked renderer for this already existed further down and had
		 * simply been orphaned when the stat cell was added, so this is the
		 * dormant path coming back rather than a new one.
		 */
		c.capital = 0;   // a stat cell now — see above
		/* Into the footnote slot, which is free on a buy card and already
		   renders at 10f grey. footnoteWarn stays FALSE deliberately: warn
		   paints it bold orange, and an orange caution under a green profit
		   figure is the plugin arguing with its own recommendation on the same
		   card — which is exactly what got Analyst Rating removed. This is a
		   measurement, so it is styled like one.

		   Paused wins the slot when paused: that is a state of the whole
		   panel, and it outranks a fact about one item. */
		if (r.rangeNote != null)
		{
			c.footnote = r.rangeNote;
			c.footnoteWarn = false;
		}
		/* The rest of the stack, on a sell the plugin only partly watched.
		   This is proceeds and the figure above it is a gain, so they get
		   separate lines and separate words; the alternative was adding them,
		   and adding them is what made a card offering to sell 18,000
		   necklaces at a loss announce "+6.81M gp P&L".

		   Sells never carry a range note, so this is not competing for the
		   slot — see rangeNote, which is buys only. */
		if (r.noteEarned && r.note != null && !r.note.isEmpty())
		{
			/* The 4h limit is used up: the quantity is 0 and so is the
			   profit, and "No margin right now" would blame the market for
			   what is the game's clock. Warned, because the trade cannot be
			   made yet. */
			c.footnote = r.note;
			c.footnoteWarn = true;
			c.footnoteIsDefault = false;
		}
		else if (!r.sell && r.profit <= 0)
		{
			/*
			 * The buy the engine cannot make a case for.
			 *
			 * A card proposing a buy whose projected profit is zero or
			 * negative is still a perfectly good thing to act on — "im buying
			 * it anyway because i want them for me" — but it must not be the
			 * one card that says nothing about it. The figure above is
			 * already red; this says what it means in words.
			 *
			 * Warned, like the sell-at-a-loss line, because it is the same
			 * kind of statement: the trade in front of you does not pay.
			 */
			c.footnote = "No margin right now";
			c.footnoteWarn = true;
		}
		else if (r.sell && r.hasTrackedCost && r.profit < 0)
		{
			/*
			 * Wins the slot over the untracked remainder below, because a card
			 * telling you to sell at a loss has one thing worth saying and
			 * that is not an accounting footnote.
			 *
			 * footnoteWarn TRUE here, unlike everywhere else. The rule that
			 * kept it off was that bold orange under a GREEN profit is the
			 * plugin arguing with its own recommendation — but the figure
			 * above this is red, so the caution agrees with it rather than
			 * contradicting it.
			 *
			 * It says what selling now means and what the button does. It does
			 * NOT say the price will recover, because the plugin has no idea
			 * whether it will, and "hold, it'll come back" is the single most
			 * expensive thing a trading tool can tell someone.
			 */
			c.footnote = "At a loss — Hold to keep it";
			c.footnoteWarn = true;
		}
		else if (r.sell && r.listingNote != null)
		{
			/* Already listed: where that offer has got to is the thing to
			   know — "i have 25k of them in ge waiting to sell at 374 ...
			   thats way more important". Under the loss warning, which is
			   still the one thing worth saying when it applies. */
			String line = String.format("%,d", r.quantity) + " listed";
			if (fitsCard(r.listingNote, false))
			{
				line = r.listingNote;
			}
			else if (r.listingShort != null)
			{
				for (String shorter : r.listingShort)
				{
					if (fitsCard(shorter, false))
					{
						line = shorter;
						break;
					}
				}
			}
			c.footnote = line;
			c.footnoteWarn = false;
		}
		else if (r.sell && r.hasTrackedCost && olderBuys.containsKey(r.itemId))
		{
			/* PAID @ is the stack you hold, from your newest buys; there are
			   more buys on record, older, that you no longer have. Said here,
			   under the loss warning and the listing (each the one thing
			   worth saying when it applies), because left alone they are
			   what your next sale gets matched against. Right-click forgets
			   them. */
			c.footnote = olderBuysNote(olderBuys.get(r.itemId)[0]);
			c.footnoteWarn = false;
			c.footnoteIsDefault = true;
		}
		else if (r.sell && r.hasTrackedCost && r.profit >= 0)
		{
			/* The counterpart to "At a loss". Both say the same kind of thing
			   — what the figure above means for the decision in front of you
			   — so a stack in profit should not be the one card that goes
			   quiet. Says what selling DOES, not that you should: the plugin
			   knows the position is up, it does not know what you want the
			   gold for. */
			/*
			 * How far up, when that can be said in the width available.
			 *
			 * "In profit" is a fact you can already read off the green figure
			 * above; the percentage against what you PAID is the thing the
			 * card alone knows and the actual reason to think about selling.
			 * Advisor computes the same line for the bank tooltip (whyNow),
			 * but that field also carries an Analyst Rating verdict on some
			 * paths — a grade that was pulled from this panel for reading
			 * "sell" under a buy — so the measurement is derived here from
			 * the two numbers the card already holds rather than by
			 * surfacing a field that sometimes means something else.
			 */
			final long netEach = r.unitPrice - FlipTracker.taxPerItem(r.unitPrice, r.itemId);
			/* Up, down or level — never "Up -73%". */
			final long change = r.unitCost > 0 ? Math.round((netEach - r.unitCost) * 100.0 / r.unitCost) : 0;
			final String pct = r.unitCost <= 0 ? null
				: change > 0 ? "Up " + String.format("%,d", change) + "% on what you paid"
				: change < 0 ? "Down " + String.format("%,d", -change) + "% on what you paid"
				: "About what you paid, after tax";
			c.footnote = fitsCard(pct, false) ? pct : "In profit — selling locks it in";
			c.footnoteWarn = false;
			/* Guidance, not a warning, so the offer-screen takeover replaces
			   it with the line that matters at that moment — the price has
			   been typed for you. The rule across this chain: a WARNING is
			   earned and survives, general guidance yields. */
			c.footnoteIsDefault = true;
		}
		else if (r.sell && r.untrackedQty > 0)
		{
			/*
			 * Nothing. This used to read "Profit covers 12,735 of 17,303",
			 * and before that "+11.7M gp more, cost unknown".
			 *
			 * Both existed to stop one misreading: the profit figure covers
			 * only the units the plugin watched you buy, so "+76.4K gp
			 * profit" sitting above "QUANTITY 17,303" can be read as "sell
			 * all 17,303 and make 76.4K".
			 *
			 * That job is done now, and done better, by the subText two rows
			 * up: "bought 12,735 at 961 gp ea" fires on the same condition,
			 * names the same count, and sits directly ABOVE the figure it
			 * scopes instead of three rows below it. Keeping both printed
			 * 12,735 twice on one card — reported as "get rid of this profit
			 * covers xyz text. meanningless", which it had become.
			 */
			c.footnoteWarn = false;
		}
		/*
		 * An untracked sell gets NO footnote of its own, and falls through.
		 *
		 * It had "No cost on record" here, which made three lines on one card
		 * say the same thing: "no buy price on record" beside the dash it
		 * explains, "Held before PocketGE" where the profit figure would be,
		 * and this. Two of those were asked for by name and sit next to the
		 * absence each one explains; the third was just the fact a third time.
		 */
		else if (r.sell && r.quoteAgeSec > 0)
		{
			/*
			 * How old the price is, and last in the chain on purpose.
			 *
			 * A sell is allowed to price off a bid up to two hours old,
			 * because the alternative is never being able to talk about a
			 * Twisted bow at all — it trades a few dozen times a day, so its
			 * bid is routinely half an hour stale. The cost of that window is
			 * that the number on the card may not be current, and a price
			 * shown without its age is a price presented as current.
			 *
			 * It takes this slot only when nothing else wants it. Every
			 * footnote above is a stronger claim about the same trade — that
			 * it loses money, that part of it is unpriced, that none of it is
			 * — and none should be displaced by a timestamp.
			 */
			c.footnote = "Last traded " + agoText(r.quoteAgeSec) + " ago";
			c.footnoteWarn = false;
		}
		/*
		 * A last-resort line, so the bottom of every card says something.
		 *
		 * This slot had a default once — "Profit if both offers fill" on a
		 * buy, "Measured against what you paid" on a sell — and it was
		 * removed because it said the same thing on every card and so carried
		 * nothing. The ask that brings one back is different: "add orange
		 * text reccomendation at the bottom of every card ... other cards
		 * coulkd say in orange cycle with arrows to next reccoendation, or
		 * other useful info".
		 *
		 * So it is not a restatement of the card. It is the one thing the
		 * card cannot say about itself — how many other ideas are queued
		 * behind it — and it changes as the list does. Suppressed when there
		 * is nothing to page to, because then it would be false as well as
		 * dull.
		 */
		else if (!r.sell && r.note != null && !r.note.isEmpty())
		{
			/* A buy with no range note says why the QUANTITY is what it is —
			   capped by the 4h limit, by the cash you have free, or by how
			   much the item actually trades. That is the thing most likely to
			   change what you do, and it was only ever in the tooltip. Just
			   the reason: r.note carries " · 2.5M traded a day" after it,
			   which does not fit and is on the card elsewhere. */
			final int dot = r.note.indexOf(" · ");
			final String raw = dot > 0 ? r.note.substring(0, dot) : r.note;
			final String why = Character.toUpperCase(raw.charAt(0)) + raw.substring(1);
			/* The longest of these — "Capped by how much actually trades in a
			   day" — is 259px against a 182px card, so it is not a candidate
			   for this slot at all. It is still on the tooltip in full. */
			if (fitsCard(why, false))
			{
				c.footnote = why;
				c.footnoteWarn = false;
			}
			else
			{
				lastResort(c, r);
			}
			/* Generic enough that the offer-screen takeover should replace it
			   with its own line — see the geContextBody guard, which asks
			   exactly this. An earned footnote, like a loss warning or "No
			   margin right now", is not flagged and so survives. */
			c.footnoteIsDefault = !r.noteEarned;
		}
		else
		{
			lastResort(c, r);
		}
		c.tooltip = wrapTip(r.note);
		/* Block moved off the control row and onto a right-click. */
		c.contextMenu = cardPopup(r.itemId, r.name, r.sell && r.hasTrackedCost,
			() -> "suggestion " + (recIndex + 1) + " of " + recommendations.size() + "\n" + describeRec(r));
		return c;
	}

	/** One idea, Copilot-shaped: what to do, at what price, what it makes,
	 *  and the controls that matter — move on, hold it, or stop being told
	 *  about this item. */
	private JPanel recommendationBody(Rec r)
	{
		final Card c = cardFor(r);
		if (recommendations.size() > 1)
		{
			/* Only with somewhere to go: "1/1" is a pager reporting that it
			   is not one. */
			c.position = new int[]{recIndex + 1, recommendations.size()};
		}

		/* Big icon buttons rather than the cramped text ones this had. The
		   fill button is gone from here entirely: the price is written onto
		   the GE offer screen itself now (see GeOfferPriceOverlay) and
		   auto-filled when the prompt opens, so a sidebar button for it was a
		   worse version of something already happening. No chart button
		   either — clicking the item opens the chart, which costs no width,
		   and this row has none to spare. */
		JPanel controls = controlsRow();
		/* Always, not just when there are two or more. Next asks for a fresh
		   batch once it walks off the end, so on a one-suggestion list it is
		   the button that GETS you more \u2014 exactly when hiding it left you
		   with no way forward at all. */
		/* Pause is in the pinned top bar now — see pauseButton(). It was the
		   odd one out here: Next and Hold act on THIS item, while pause acts
		   on the advisor. */
		/* Hold is "I'm keeping this one for now" — a session skip, so it
		   comes back next login. Only sells can be held: you cannot hold
		   something you do not own.

		   Block used to sit beside it and no longer does. Two adjacent icon
		   buttons that both mean "not this one", differing only in how long
		   it lasts, is a choice you have to stop and read the tooltips to
		   make — and the permanent one was the easier of the two to hit by
		   accident. Block is a right-click on the card now. */
		/* The star, on every card and not just the ones you reached from the
		   watchlist — "always add the star availble to click and unclick i
		   iike that". It was on the inspect and offer-screen cards only, so
		   the one place you meet an item you have never seen before was the
		   one place you could not add it. */
		final boolean fav = favoriteIds.contains(r.itemId);
		addControl(controls, bigIconBtn(fav ? STAR_FILLED_ICON : STAR_HOLLOW_ICON,
			fav ? "Remove " + r.name + " from your watchlist"
				: "Add " + r.name + " to your watchlist",
			e -> actions.toggleFavorite(r.itemId, r.name)));
		if (r.sell)
		{
			addControl(controls, bigIconBtn(HOLD_ICON, "Hold your " + r.name + " — skip it for this session",
				e -> actions.skip(r.itemId)));
		}
		/* The pager last and hard right, the way the website's card carries
		   it: everything left of the gap acts on THIS item, the two chevrons
		   move you off it. Next is drawn even on a one-suggestion list,
		   because it is what asks for a fresh batch once it walks off the
		   end -- exactly when hiding it would leave no way forward at all. */
		c.controls = controls;
		c.pager = pagerBlock();

		/* Where you are in the queue is on the pager now — see pagerCount.
		   What came off was "3 of 20". The count was never something to act on, it cost a
		   whole line, and it framed the list as finite when Next now just
		   fetches more once it runs out. */
		/* Paused outranks the range note — it is a state of the whole panel,
		   and a card that looks live while the stream is frozen is worse than
		   one missing a footnote. Note this reads c.footnote rather than
		   clearing it: the range line is set above, and assigning null here
		   unconditionally would have silently thrown it away. */
		if (paused)
		{
			c.footnote = "Paused";
			c.footnoteWarn = true;
		}
		/* Was `c.footnoteWarn = paused;` unconditionally, which quietly reset
		   the flag every card that had set one. Harmless while nothing but
		   Paused ever used it; it swallowed the at-a-loss caution the moment
		   something did. */
		return buildCard(c);
	}

	/** The controls strip along the bottom of a card.
	 *
	 *  BoxLayout, not FlowLayout: FlowLayout pads BOTH ends with its hgap and
	 *  silently wraps to a second row when it runs out of width — and because
	 *  the panel's preferred height is still measured for one row, that
	 *  second row is simply clipped away. Next + Pause + Hold + Block did not
	 *  fit a 225px sidebar with FlowLayout's padding, so on any SELL
	 *  suggestion the Block button was being cut off. It fits without. */
	private static JPanel controlsRow()
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setOpaque(false);
		row.setAlignmentX(0f);
		return row;
	}

	/** Adds a control, with a gap before it if it isn't the first. The
	 *  explicit alignmentY keeps every child on one baseline — a default
	 *  Box.Filler and a JButton disagree otherwise, and an X_AXIS BoxLayout
	 *  resolves that disagreement by making the row taller. */
	/**
	 * Pushes whatever is added next to the right-hand end of the row.
	 *
	 * The website's card puts its pager on the far edge of the bottom row,
	 * clear of everything that acts on the item — which is most of what
	 * makes two chevrons read as ONE pager rather than as two more buttons
	 * in a line of five. Copied here for the same reason.
	 */
	/**
	 * The two chevrons, pushed hard right on the card's last row.
	 *
	 * Bottom-right of the card, not on the tool row — "can the arrows be down
	 * bottom right", which is also where pocketge.com's own card keeps them.
	 *
	 * The count used to be stacked directly above them, in here. It is on the
	 * footnote's line now — "move all these buttons up and the 1/17 to be on
	 * same line as orange text" — which is a row the card was already paying
	 * for: the footnote is one short sentence and leaves 60-100px empty at its
	 * right end on every card measured. Moving the count there took a whole
	 * row plus its strut out of the bottom of every card.
	 *
	 * Back is always drawn and merely disabled at the start of the list, so
	 * the row cannot change width under the cursor — see backButtonAlways.
	 */
	private JPanel pagerBlock()
	{
		final JPanel arrows = controlsRow();
		arrows.setAlignmentX(1f);
		/* Bottom, not centre: the tools on the other side of the footer's glue
		   are one row of the same height, and this keeps the two sets of
		   buttons on one baseline whatever either side does. */
		arrows.setAlignmentY(1f);
		addControl(arrows, backButtonAlways());
		addControl(arrows, nextButton());
		/*
		 * Held to its own WIDTH as well as its height.
		 *
		 * A JPanel's maximum width is unbounded, so inside the footer's
		 * X_AXIS the row was being handed a share of the card's spare width
		 * alongside the glue instead of sitting flush at the card's edge.
		 * Bounded, every spare pixel goes to the glue.
		 */
		arrows.setMaximumSize(arrows.getPreferredSize());
		return arrows;
	}

	private static void addSpacer(JPanel row)
	{
		final Box.Filler glue = (Box.Filler) Box.createHorizontalGlue();
		glue.setAlignmentY(0.5f);
		row.add(glue);
	}

	/**
	 * "1/4" — where the card you are looking at sits in the shortlist.
	 *
	 * On the verb line, right-aligned — NOT beside the chevrons it describes,
	 * which is where it belongs and where it does not fit. Measured: a sell
	 * card with a trail behind it already puts its last button within 1px of
	 * the card edge, so a count between them clips the moment the shortlist
	 * reaches double figures. The website hit the same wall from the other
	 * side and moved its own count out of the pager for the same reason.
	 *
	 * The verb line is the card's sub-header and carries one short word, so
	 * there is room at its right end no shortlist can exhaust.
	 *
	 * The plugin carried "3 of 20" once, on its own line, and it came off on
	 * the grounds that it was not something to act on and cost a whole row.
	 * Both were true of THAT: a line of its own above the card, spelled out,
	 * framing a list as finite when Next just fetches more. This is four
	 * characters riding a control you are already looking at, and it answers
	 * the one question paging raises — how far in am I, and is there more
	 * behind me.
	 *
	 * Position bold and bright, total muted, 11px: the site's .fc-count.
	 */
	/** An empty label in the count's own font, so a card without a count is
	 *  exactly as tall as one with it. See where it is used. */
	private JLabel countSpacer()
	{
		final JLabel l = new JLabel(" ");
		l.setFont(l.getFont().deriveFont(Font.BOLD, 12f));
		l.setAlignmentY(0.5f);
		l.setMaximumSize(l.getPreferredSize());
		return l;
	}

	private JLabel pagerCount(int pos, int total)
	{
		/* Bold throughout, so the whole label carries; the position is
		   distinguished by COLOUR alone. The <b> that used to sit round it
		   was doing nothing a plain 11px Swing label could express against
		   an already-plain body. */
		final JLabel l = new JLabel("<html><font color='" + hex(TEXT_MAIN) + "'>"
			+ pos + "</font>/" + total + "</html>");
		l.setForeground(Brand.TEXT_STRUCTURAL);
		l.setFont(l.getFont().deriveFont(Font.BOLD, 12f));
		l.setToolTipText(tip("Flip " + pos + " of " + total, "A fresh scan starts a new shortlist."));
		l.setAlignmentY(0.5f);
		/* Pinned, or the glue beside it does nothing.
		   Component.getMaximumSize defaults to Short.MAX_VALUE in both axes,
		   so a plain JLabel in an X_AXIS BoxLayout is just as willing to
		   absorb spare width as the glue is — and BoxLayout splits the slack
		   between them. Measured: the row stretched to 160px and this label
		   took 135 of it, leaving the text drawn hard against the verb
		   ("Buy1/2") with the glue holding nothing. Same trap as the card's
		   own rows; see holdHeight. */
		l.setMaximumSize(l.getPreferredSize());
		return l;
	}

	private static String hex(Color c)
	{
		return String.format("#%02X%02X%02X", c.getRed(), c.getGreen(), c.getBlue());
	}

	private static void addControl(JPanel row, JButton b)
	{
		if (row.getComponentCount() > 0)
		{
			final Box.Filler gap = (Box.Filler) Box.createHorizontalStrut(CONTROL_GAP);
			gap.setAlignmentY(0.5f);
			gap.setAlignmentX(0f); // irrelevant on an X_AXIS row, but keeps the
			                       // whole panel's alignment audit clean
			row.add(gap);
		}
		b.setAlignmentY(0.5f);
		row.add(b);
	}

	/** Paging. On the watchlist takeover it ALSO drops the inspection: the
	 *  item you clicked isn't part of the ranked stream, so "next" there can
	 *  only sensibly mean "back to the flips, one further along". */
	/** Push whatever is on screen onto the browsing trail. */
	private void rememberCurrentRec()
	{
		if (recIndex < 0 || recIndex >= recommendations.size())
		{
			return;
		}
		final Rec cur = recommendations.get(recIndex);
		final int[] top = recTrail.peekLast();
		if (top != null && top[0] == cur.itemId && top[1] == (cur.sell ? 1 : 0))
		{
			return; // already the last thing we left; don't stack duplicates
		}
		recTrail.addLast(new int[]{cur.itemId, cur.sell ? 1 : 0});
		while (recTrail.size() > MAX_REC_TRAIL)
		{
			recTrail.removeFirst();
		}
	}

	/** Where {@code entry} sits in the list as it stands now, or -1 if that
	 *  flip is no longer being recommended. */
	private int indexOfRec(int[] entry)
	{
		for (int i = 0; i < recommendations.size(); i++)
		{
			final Rec r = recommendations.get(i);
			if (r.itemId == entry[0] && (r.sell ? 1 : 0) == entry[1])
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * True when Back would actually do something: a card on the trail is
	 * still on offer, or there is a card before this one in the list.
	 *
	 * The trail alone left Back greyed out under "2/20": the card moves on by
	 * itself when the idea you placed leaves the list, and nothing had been
	 * paged past — "why it show 2/20 but i cant click to whatever 1/20 is".
	 */
	private boolean canGoBack()
	{
		for (int[] entry : recTrail)
		{
			final int at = indexOfRec(entry);
			if (at >= 0 && at != recIndex)
			{
				return true;
			}
		}
		return recIndex > 0 && recIndex < recommendations.size();
	}

	/**
	 * Back to the last card you paged past that is still being recommended;
	 * with none, to the card before this one in the list — the one the
	 * counter says is there.
	 *
	 * Entries that have gone stale are discarded as they are popped rather
	 * than skipped over and kept: if a flip has dropped out of the ranking,
	 * pressing Back twice should not keep offering to look for it.
	 */
	private JButton backButton()
	{
		final JButton back = pagerButton(true, "Back to the previous suggestion", e ->
		{
			while (!recTrail.isEmpty())
			{
				final int[] entry = recTrail.removeLast();
				final int at = indexOfRec(entry);
				if (at >= 0 && at != recIndex)
				{
					/* Leaving the offer-screen takeover and the favourite
					   selection the same way Next does — otherwise Back would
					   change the card underneath an overlay still showing the
					   item you were on. */
					selectedFavorite = null;
					selectedFavoriteId = -1;
					recIndex = at;
					renderRecommendation();
					return;
				}
			}
			if (recIndex > 0 && recIndex < recommendations.size())
			{
				selectedFavorite = null;
				selectedFavoriteId = -1;
				recIndex--;
			}
			renderRecommendation();
		});
		return back;
	}

	private JButton nextButton()
	{
		final JButton next = pagerButton(false,
			geContextItemId != null || selectedFavorite != null
				? "Back to flips — show the next suggestion"
				: "Next suggestion", e ->
		{
			if (selectedFavorite != null)
			{
				selectedFavorite = null;
				selectedFavoriteId = -1;
			}
			/* Step out of the offer-screen takeover too, for the item that is
			   on screen right now. One button, one meaning wherever it
			   appears: "stop showing me this, show me the next flip." */
			if (geContextItemId != null)
			{
				geContextDismissedFor = geContextItemId;
			}
			if (!recommendations.isEmpty())
			{
				/* Remember what you are stepping off, so Back can return to
				   it. Pushed here rather than in renderRecommendation because
				   only a deliberate Next is "browsing" — a refresh landing a
				   new card under you is not something you asked to leave. */
				rememberCurrentRec();
				/* Walking off the end asks for a new batch rather than
				   quietly starting the same ring over. The wrap to 0 stays as
				   the fallback: the refresh is asynchronous, so there has to
				   be something to show on the very next paint, and if it
				   returns the same list this is exactly the old behaviour. */
				final int nextIndex = recIndex + 1;
				if (nextIndex >= recommendations.size())
				{
					actions.refreshSuggestions();
				}
				recIndex = nextIndex % recommendations.size();
			}
			renderRecommendation();
		});
		/* No word on it any more.
		   It carried "Next" on the argument that the control you press most
		   should be the easiest to hit. The website's card answered that
		   differently and better: a PAIR of chevron squares reads as a pager
		   at a glance, where one worded button and one bare arrow read as two
		   unrelated controls. The pair is also narrower than the single
		   worded button was, which is where the room for the rest of the row
		   came from. */
		return next;
	}

	/**
	 * Dresses a control as one of the site's pager squares: a rounded
	 * gold-tinted tile that brightens under the cursor.
	 *
	 * Painted rather than bordered because Swing's border is square and the
	 * corner radius is most of what makes these read as the site's. The fill
	 * is translucent, so the card's own hover tint still shows through it
	 * rather than the button punching a flat hole in the card.
	 */
	private static JButton asPager(JButton b)
	{
		b.setContentAreaFilled(false);
		b.setBorderPainted(false);
		b.setOpaque(false);
		b.setFocusPainted(false);
		b.setText(null);
		b.setRolloverEnabled(true);
		sizeExactly(b, CONTROL_H, CONTROL_H);
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		return b;
	}

	/** A pager square carrying {@code glyph}, which is swapped for its
	 *  brighter self while the cursor is on it. */
	private JButton pagerButton(boolean back, String tip, java.awt.event.ActionListener a)
	{
		final JButton b = new JButton(buildChevron(back, PAGER_FG))
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				final Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				final boolean hot = getModel().isRollover() || getModel().isPressed();
				g2.setColor(new Color(PAGER_FG.getRed(), PAGER_FG.getGreen(), PAGER_FG.getBlue(),
					hot ? PAGER_FILL_ALPHA_HOVER : PAGER_FILL_ALPHA));
				g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, PAGER_RADIUS, PAGER_RADIUS);
				g2.setColor(hot ? PAGER_FG
					: new Color(PAGER_FG.getRed(), PAGER_FG.getGreen(), PAGER_FG.getBlue(), PAGER_RIM_ALPHA));
				g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, PAGER_RADIUS, PAGER_RADIUS);
				g2.dispose();
				super.paintComponent(g);
			}
		};
		b.setRolloverIcon(buildChevron(back, PAGER_FG_HOVER));
		b.setPressedIcon(buildChevron(back, PAGER_FG_HOVER));
		b.setDisabledIcon(buildChevron(back, new Color(
			PAGER_FG.getRed(), PAGER_FG.getGreen(), PAGER_FG.getBlue(), 70)));
		b.setToolTipText(tip);
		b.addActionListener(a);
		return asPager(b);
	}

	/**
	 * Back, always present, and greyed out when there is nowhere to go.
	 *
	 * It used to be left out entirely on the first card, so the row was one
	 * button narrower there and everything in it shifted sideways the moment
	 * you pressed Next — with the arrow you had just used sliding out from
	 * under the cursor. Reported as "the shifing and arrow appearing is odd
	 * to me".
	 *
	 * A disabled button also says something the missing one could not: that
	 * there IS a way back, and you are at the start of the list. Swing skips
	 * the listener and paints the dimmed icon on its own once enabled is
	 * false, so nothing else has to know.
	 */
	private JButton backButtonAlways()
	{
		final JButton back = backButton();
		if (!canGoBack())
		{
			back.setEnabled(false);
			back.setToolTipText(tip("Nothing to go back to",
				"This is the first suggestion in the list."));
		}
		return back;
	}

	/** Everything one card can show.
	 *
	 *  A spec object rather than a ten-argument method, because there is now
	 *  exactly ONE card shape in this panel — the recommended flip, the
	 *  watchlist item you clicked, and the offer screen you have open all
	 *  render through it, and the only difference between them is which
	 *  fields are filled in. Two differently-shaped cards stacked on top of
	 *  each other was the thing that made this panel hard to read. */
	/** Widest the headline profit may draw before it steps its font down —
	 *  the card's inner width, with room for the padding either side. */
	private static final int PROFIT_LINE_MAX_WIDTH = 184;

	/** The card's money line. Shared by the panel and the share image so a
	 *  pasted card cannot word its own headline differently. */
	private static String moneyLine(Card c)
	{
		final String sign = c.profitValue >= 0 ? "+" : "";
		return sign + QuantityFormatter.quantityToStackSize(c.profitValue) + " " + c.profitSuffix;
	}

	/** The watchlist row's badge, said in words for the card headline. Longer
	 *  than the row's own version because there is room here, and because a
	 *  bare ▲ next to a price would read as a price arrow rather than a
	 *  range one. */
	private static String extremeBadgeText(PriceExtremes.Tier tier)
	{
		switch (tier)
		{
			case HIGH_5D:
				return "▲ 5D HIGH";
			case LOW_5D:
				return "▼ 5D LOW";
			case HIGH_1D:
				return "▲ DAY HIGH";
			case LOW_1D:
				return "▼ DAY LOW";
			default:
				return null;
		}
	}

	static class Card
	{
		Color accent = GOLD;
		int itemId;
		String name = "";
		/** A white lead-in printed before {@link #actionText} and NOT taking
		 *  its colour — "Target sell", "Target buy". The label says which
		 *  side you are on; the coloured half is the numbers. Null for a
		 *  headline that is all one colour. */
		String actionLabel;
		/** The headline under the name — "8,917 @ 729 gp ea",
		 *  "▲ 5D HIGH · 958 gp". */
		String actionText;
		/** Colour for {@link #actionText}. Null means "use the accent", which
		 *  is right for a buy/sell instruction (the accent already encodes
		 *  that direction) and wrong for a range badge, where green/gold mean
		 *  high/low instead. */
		Color actionColor;
		/**
		 * Recommendation cards only: the two coloured lines that SANDWICH the
		 * item name — "Sell 17,303" above it, "for 984 gp ea" below — so the
		 * card reads as one instruction top to bottom instead of a name
		 * followed by a spec sheet.
		 *
		 * Null everywhere else, which leaves those cards on the single
		 * {@link #actionText} line above the name. {@link #actionText} stays
		 * populated either way: the share image renders from it, and it is
		 * what keeps the picture's headline identical to the card's.
		 */
		String actionLead;
		String actionTrail;
		/** Where the goods are, under the instruction — "from your bank" on
		 *  a sell. Null on a buy, which is not from anywhere yet. */
		String provenance;
		/** Colour for {@link #provenance}, or null for the usual grey. The
		 *  inspect card puts its 5-day badge here, and a HIGH is green while a
		 *  LOW is gold — the same pairing the watchlist rows and the website
		 *  use, so the colour agrees with the arrow rather than contradicting
		 *  it. */
		Color provenanceColor;
		/** Muted second line: what it cost, the target pair, no-margin. */
		String subText;
		/** The card's own right-click menu — Block lives here now. Null on a
		 *  card with no item behind it. See buildCard, which also has to hand
		 *  it down to every child. */
		JPopupMenu contextMenu;
		Long profitValue;
		/**
		 * Words where the profit figure goes, when there is no figure.
		 *
		 * An untracked sell leaves that slot empty, and since the card is
		 * padded to a fixed floor the gap does not close up — two cards side
		 * by side, one with a big red number and one with a hole, read as two
		 * different layouts.
		 *
		 * A TEXT stand-in, never a number. A figure in this slot read as
		 * profit through three attempts (green, then plain, then footnoted),
		 * which is why profitValue is null here in the first place; a
		 * sentence cannot be mistaken for a P&L the same way.
		 */
		String profitNote;
		String profitSuffix = "gp profit";
		String profitTooltip;
		/** The sell price the profit assumes, 0 to hide. Rendered beside the
		 *  money line, small and grey: it is the number that makes the green
		 *  one true, not a second headline. */
		long exitPrice;
		/** gp the position ties up, 0 to hide. */
		long capital;
		/** Buttons along the bottom. Null for none. */
		JPanel controls;
		JButton close;
		/** The enclosing section's collapse chevron, rendered in this card's
		 *  own top-right rather than on a header row of its own. Null for
		 *  cards that are not the whole of a collapsible section. */
		JLabel collapse;
		/** Small grey line at the very bottom — "3 of 12", "From your
		 *  watchlist". */
		String footnote;
		/** Colours the footnote as a warning instead of grey ("Paused"). */
		boolean footnoteWarn;
		/** True when {@link #footnote} is the generic caveat the chain ends
		 *  in rather than something this card earned. The offer-screen
		 *  takeover replaces that one and only that one: its own line is
		 *  more use there, but "At a loss" or "cost unknown" outrank it. */
		boolean footnoteIsDefault;
		String tooltip;
		/** The site card's score row — verdict, number and meter — under
		 *  the instruction. Null for cards that are not scored buys. */
		TradeEngine.FlipScore score;
		/** The count and the two chevrons, bottom-right of the card. Separate
		 *  from {@link #controls} because they do a different job: the tools
		 *  act on THIS item, the pager moves you off it — and the website
		 *  keeps them at opposite ends for that reason. */
		JPanel pager;
		/** A sell card's answer to the same slot: how big the stack is against
		 *  what the item actually trades. Never set together with
		 *  {@link #score} — a buy is scored, a sell is measured. Null when
		 *  there are not enough prints to say. See {@link Clearance}. */
		Clearance clearance;
		/** Recommendation cards: the instruction word under the name — "Buy"
		 *  or "Sell" — in the side's colour, with {@link #provenance} after
		 *  it in grey when there is one. The quantity that used to ride in
		 *  this line is a labelled figure in {@link #stats} now. */
		String verb;
		/** Where this card sits in the shortlist, at the right end of the
		 *  verb line — {@code {position, total}}. Null when there is nothing
		 *  to page through. See pagerCount. */
		int[] position;
		/** Small labelled figures along the bottom — QUANTITY, CAPITAL — in
		 *  the site card's stat-cell shape. Null for none. */
		List<Stat> stats;

		static final class Stat
		{
			final String label;
			final String value;
			final String tip;
			/** Non-null to paint the FIGURE something other than the shared
			 *  parchment. Only capital uses it: it is the one number in this
			 *  row that is money going OUT, and sitting in the same colour
			 *  beside a count made the two read as a matched pair. */
			final Color valueColor;

			Stat(String label, String value, String tip)
			{
				this(label, value, tip, null);
			}

			Stat(String label, String value, String tip, Color valueColor)
			{
				this.label = label;
				this.value = value;
				this.tip = tip;
				this.valueColor = valueColor;
			}
		}
		/** The two prices, boxed side by side the way the site's card draws
		 *  its Buy @ / Sell @. Replaces {@link #actionTrail} and the "Sell
		 *  at" row when set: the same two numbers, in one shape. */
		PricePair pair;

		static final class PricePair
		{
			String buyLabel;
			/** 0 means unknown, rendered as a dash: a sell of a stack the
			 *  plugin never watched you buy has no price to put here. */
			long buy;
			String buyTip;
			String sellLabel;
			long sell;
			String sellTip;
			/** Whether clicking the box copies that number for the offer
			 *  screen. True for the two prices you actually place — never for
			 *  PAID @, which is what a past trade cost and not a price
			 *  anything is waiting for. */
			boolean buyFills;
			boolean sellFills;
		/** Which of the two boxes IS this card's instruction — BUY @ on a
		 *  buy, SELL @ on a sell. Drawn at a heavier tint so the direction
		 *  reads before the words do: "Buy" set small next to an item name
		 *  was the quietest thing on a card whose whole job is to say which
		 *  of two things to do. Colour only, deliberately — a bolder or
		 *  larger label would change the box's height, and tallestShape
		 *  (which sets the card floor) does not set this flag, so every real
		 *  card would then sit a pixel over the floor. */
		boolean buyLead;
		boolean sellLead;
		}
	}

	/** Shared shell for every card in this panel — colored left accent
	 *  (pocketge.com's own obsidian background behind it, not RuneLite's
	 *  neutral gray), an icon+name headline row, then each optional line in
	 *  turn. Splitting name, action and price onto their own lines — rather
	 *  than one combined "Buy N Item for X gp" string — is deliberate: a
	 *  single JLabel doesn't wrap, so a longer item name (Helm of neitiznot,
	 *  say) combined with the price used to push the price itself past the
	 *  card's edge, clipped and invisible. Each line now only ever needs to
	 *  fit ONE piece of information. */
	/**
	 * The height every recommendation card is held to, so paging with Next
	 * does not move the card's own buttons or shunt the whole panel below it.
	 *
	 * Measured rather than chosen: the four card shapes came out at 331, 347,
	 * 347 and 351 pixels, because a buy carries an exit price and a capital
	 * block where a sell carries a provenance line, a cost line and a
	 * footnote — nearly the same height by coincidence, never exactly. An
	 * untracked sell has no cost line at all and is a row shorter again.
	 *
	 * Held to the tallest of them, with the slack going to a glue above the
	 * buttons. Cards that genuinely need more still grow; nothing is
	 * truncated. The cost is a few pixels of dark background on the shortest
	 * card, which is a better trade than a control that moves under the
	 * cursor between presses.
	 *
	 * Not a pixel constant any more. 236 was measured in the headless
	 * harness, whose JRE default font is a size or two larger than the font
	 * RuneLite's look-and-feel actually draws with — so in the client every
	 * card came out shorter than the number and the floor left a band of
	 * nothing above the buttons on all of them. A height tuned in one font
	 * cannot be right in another.
	 *
	 * So the floor is MEASURED, once, in whatever font is live: the first
	 * card built lays out a probe in the tallest shape a card can take
	 * (scored buy, two stats, a footnote, buttons) and takes its preferred
	 * height. Same fonts, same rows, same insets — by construction the
	 * tallest real card lands on the floor exactly and the rest sit within
	 * one row of it. Reset when the score row is switched off, since that
	 * changes the tallest shape.
	 */
	/**
	 * The most dead space any one card may be given to reach the floor.
	 *
	 * This is a dial, not a constant with a right answer, and it is worth
	 * saying which way it turns. The shapes a card can take differ by about
	 * 80px of content — an untracked sell has four rows where a partly
	 * tracked one with a clearance line and a footnote has eight. That 80px
	 * has to go somewhere: into blank space at the bottom of the short cards,
	 * or into the buttons sitting at different heights.
	 *
	 *   cap = 80+  no movement, up to 80px of void   (originally shipped)
	 *   cap = 40   up to 40px of each
	 *   cap = 0    no void, buttons move the full 80  (here)
	 *
	 * Set to 0, after the blank space was reported three times running —
	 * "huge blank area on this card", "big area on all cards that should be
	 * reduced", and finally "kill this wasted space on these cards". The
	 * intermediate values were an attempt to keep some of the floor's
	 * benefit; the reports did not stop, and the floor's benefit was never
	 * asked for. A card is exactly as tall as what is on it now.
	 *
	 * What that costs is real and is the reason the floor existed: Back and
	 * Next sit lower on a tall card than a short one, so paging can move them
	 * under the cursor. If that turns out to be the worse annoyance, the
	 * dial is this one constant — or, to have both, lift the pager out of
	 * the card into a fixed strip so its position stops depending on card
	 * height at all.
	 */
	private static final int MAX_CARD_PAD = 0;

	private int cardFloor = -1;
	/** True while the probe card is being built, so its own preferred
	 *  height is not clamped to a floor that does not exist yet. */
	private boolean probingFloor;

	private int cardFloor()
	{
		if (cardFloor < 0 && !probingFloor)
		{
			probingFloor = true;
			try
			{
				/*
				 * Two probes, not one.
				 *
				 * This measured the buy shape alone for as long as only buys
				 * carried a row above the price pair. Once a sell carries the
				 * clearance line it can be the taller of the two — it has a
				 * cost line ("bought 3,888 at 517 gp ea") that no buy has —
				 * and a floor measured from buys only would sit under it, so
				 * the sell would overrun and take its own Back/Next buttons
				 * down with it. Measured before this was fixed: 258px against
				 * a 242px floor, with the chevron and everything below it
				 * 16px lower on that one card.
				 *
				 * Still measured rather than chosen, and still both shapes
				 * measured in the live font — see the note above about 236.
				 */
				cardFloor = Math.max(
					buildCard(tallestShape()).getPreferredSize().height,
					buildCard(tallestSellShape()).getPreferredSize().height);
			}
			finally
			{
				probingFloor = false;
			}
		}
		return Math.max(0, cardFloor);
	}

	/** Every optional row present at once. Values are placeholders; only the
	 *  rows and their fonts matter, and a "1" is as tall as "20,160,000". */
	private Card tallestShape()
	{
		final Card c = new Card();
		c.name = "Probe";
		c.verb = "Buy";
		c.actionColor = buyColor();
		c.score = settings == null || settings.showFlipScore
			? TradeEngine.FlipScore.of(0.02, 1_000_000, false) : null;
		c.pair = new Card.PricePair();
		c.pair.buyLabel = "BUY @";
		c.pair.buy = 1;
		c.pair.sellLabel = "SELL @";
		c.pair.sell = 1;
		c.profitValue = 1L;
		/* One stat cell and the stacked capital block below it, which is the
		   shape a buy actually has since capital came off the stats row. A
		   probe carrying two cells and no capital block measures a card that
		   no longer exists and under-measures this one by two rows. */
		c.stats = List.of(new Card.Stat("QUANTITY", "1", null));
		c.capital = 1;
		/*
		 * The probe KEEPS its footnote, and this was tried the other way.
		 *
		 * The floor is the height every card is padded up to, so it looked
		 * like the row a footnote-less card reserves and does not use — take
		 * it off the probe and the card tightens. Measured, that is not what
		 * happens: three of the four real shapes are naturally 417px, because
		 * a buy carries a score, two stats AND a range note. The probe is not
		 * padding them, it IS them. Dropping its footnote lowered the floor
		 * below the real cards, which stopped it equalising anything — the
		 * partly-tracked sell came out 52px shorter than the rest and its
		 * Next button moved 12px, which is the exact problem the floor exists
		 * to prevent.
		 *
		 * So the useless LINE is gone from real cards and the height is not,
		 * because the height is set by the fullest card rather than by this.
		 */
		c.footnote = "probe";
		final JPanel controls = controlsRow();
		addControl(controls, nextButton());
		c.controls = controls;
		return c;
	}

	/**
	 * The same, for the tallest a SELL can be: the clearance line above the
	 * pair, a cost line under it, one stat and a footnote.
	 *
	 * Two details are load-bearing and were both got wrong first time.
	 * {@code profitValue} rather than {@code profitNote}: they are mutually
	 * exclusive and the figure renders at 19f against the note's 15f, so the
	 * note would under-measure the row. And a real {@code subText}, because
	 * the cost line is the row a sell has and a buy does not — it is the
	 * whole reason this probe has to exist.
	 */
	private Card tallestSellShape()
	{
		final Card c = new Card();
		c.name = "Probe";
		c.verb = "Sell";
		c.actionColor = sellColor();
		c.clearance = settings == null || settings.showFlipScore
			? Clearance.of(1, Clearance.MIN_PRINTS, Clearance.MIN_PRINTS) : null;
		c.pair = new Card.PricePair();
		c.pair.buyLabel = "PAID @";
		c.pair.buy = 1;
		c.pair.sellLabel = "SELL @";
		c.pair.sell = 1;
		c.profitValue = 1L;
		c.subText = "probe";
		c.stats = List.of(new Card.Stat("QUANTITY", "1", null));
		c.footnote = "probe";
		final JPanel controls = controlsRow();
		addControl(controls, nextButton());
		c.controls = controls;
		return c;
	}

	/** See the assignment in renderRecommendation: live only while the
	 *  recommendation body is being built, consumed once by buildCard. */
	private JLabel cardCollapse;

	/** The section chevron as it appears on the card: same glyph, colour and
	 *  size the header row used, so moving it changed where it is and nothing
	 *  about what it looks like. */
	private JLabel collapseChevron(Runnable onToggle)
	{
		final JLabel chevron = new JLabel("\u25BE");
		chevron.setForeground(Brand.TEXT_STRUCTURAL);
		chevron.setFont(chevron.getFont().deriveFont(10f));
		chevron.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		chevron.setToolTipText("Hide the recommendation");
		chevron.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e) { onToggle.run(); }
		});
		return chevron;
	}

	private JPanel buildCard(Card c)
	{
		JPanel p = new JPanel()
		{
			@Override
			public java.awt.Dimension getPreferredSize()
			{
				final java.awt.Dimension d = super.getPreferredSize();
				if (probingFloor || MAX_CARD_PAD <= 0)
				{
					/* No padding at all: the card is exactly as tall as what
					   is on it. Skipped before cardFloor() so the probes are
					   never built when nothing will use them. */
					return d;
				}
				/*
				 * Padded UP to the floor, but never by more than MAX_CARD_PAD.
				 *
				 * The floor is the tallest shape a card can take, and holding
				 * every card to it is what keeps Next still. The cost is that
				 * a short card — an untracked sell has four content rows where
				 * the tallest shape has eight — was padded with most of a
				 * card's worth of nothing. Reported twice, as "huge blank area
				 * on this card" and "big area on all cards that should be
				 * reduced".
				 *
				 * So the padding is capped. A card within MAX_CARD_PAD of the
				 * floor still lands exactly on it, which is most of them and
				 * is where Next staying put actually matters; a card further
				 * down than that stops short rather than growing a void. Next
				 * can now move, but by at most MAX_CARD_PAD rather than by the
				 * full difference between the shortest and tallest shapes.
				 */
				final int floor = cardFloor();
				return new java.awt.Dimension(d.width,
					Math.max(d.height, Math.min(floor, d.height + MAX_CARD_PAD)));
			}
		};
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setAlignmentX(0f);
		p.setBackground(OBSIDIAN_BG);
		p.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, c.accent),
			BorderFactory.createEmptyBorder(9, CARD_PAD_L, 9, CARD_PAD_R)));

		/*
		 * The card's right-click menu, on the card AND on everything in it.
		 *
		 * setComponentPopupMenu alone covers the panel's own bare pixels and
		 * nothing else: Swing does not bubble mouse events, so every label,
		 * box and figure on the card — which is most of its area — would be a
		 * dead spot. getInheritsPopupMenu is the supported way to say "use my
		 * parent's", and it is off by default. The chart button keeps its own
		 * menu, because a component that HAS one is never asked its parent.
		 */
		if (c.contextMenu != null)
		{
			p.setComponentPopupMenu(c.contextMenu);
		}

		if (c.collapse == null && cardCollapse != null)
		{
			c.collapse = cardCollapse;
			cardCollapse = null;
		}
		JPanel row1 = new JPanel(new BorderLayout(6, 0));
		row1.setOpaque(false);
		/* Every child of this BoxLayout must share one alignmentX. A JPanel
		   defaults to 0.5 (CENTER) while the labels below are set to 0f
		   (LEFT); BoxLayout resolves a mixed column by widening it to fit
		   both interpretations and offsetting the members, which inside a
		   fixed 225px PluginPanel pushed the left-aligned parts — the price
		   line and the whole rating gauge — outside the visible width. They
		   still contributed height, so the card rendered as a tall box with
		   nothing in it but the item name. */
		row1.setAlignmentX(0f);
		final String itemName = c.name != null ? c.name : "";
		final JLabel icon = iconLabel(c.itemId, CARD_ICON);
		wireOpenChartOnClick(icon, itemName);
		row1.add(icon, BorderLayout.WEST);
		// Just the name in CENTER — a lone JLabel truncates safely via
		// truncateName() when it's the squeezed slot. The chart button used
		// to share this slot with the name; that worked until a close button
		// (EAST, always gets its full preferred width) showed up too, which
		// squeezed CENTER enough that the chart button rendered clipped.
		// Moving it into the same always-full-width EAST slot fixes that
		// outright rather than fighting the layout for room.
		/* EAST always gets its full preferred width, so every button here is
		   width taken straight off the name. Measured in a 225px sidebar: one
		   button leaves the name 132px, two leave it ~103.
		   The chart button has now followed share down to the controls row,
		   which is where every other verb on this card already lives. That
		   gives a card with no close button the whole row for its name, so
		   "Diamond necklace" stops arriving as "Diamond n…". Clicking the
		   icon or the name still opens the chart, so nothing moved out of
		   reach — only the button did.
		   The budget is characters that actually FIT, not a round number:
		   Swing ellipsizes a second time on its own if the label overflows,
		   which is how "Bandos chestplate" once rendered as "Bandos ches"
		   with even the ellipsis cut off. */
		JLabel nameLabel = new JLabel(truncateName(itemName, c.close != null ? 14 : 22));
		/* Two jobs, because the click has two meanings — see the plugin's
		   openChart. With the Exchange asking which item to trade it types
		   the name in; otherwise it opens the chart. */
		nameLabel.setToolTipText(tip(itemName,
			"Click for its chart. While the Exchange asks which item, it names the item to type instead."));
		nameLabel.setForeground(TEXT_MAIN);
		nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD, 15f));
		wireOpenChartOnClick(nameLabel, itemName);
		if (c.actionLead != null || c.verb != null)
		{
			final JPanel stack = new JPanel();
			stack.setLayout(new BoxLayout(stack, BoxLayout.Y_AXIS));
			stack.setOpaque(false);
			final Color lineFg = c.actionColor != null ? c.actionColor : c.accent;
			if (c.actionLead != null)
			{
				stack.add(actionLine(c.actionLead, lineFg));
			}
			nameLabel.setAlignmentX(0f);
			stack.add(nameLabel);
			if (c.actionTrail != null)
			{
				stack.add(actionLine(c.actionTrail, lineFg));
			}
			if (c.verb != null)
			{
				/* Name first, verb under it — the site card's order. This was
				   the other way round, as a sentence: "Buy 13,000 / Tin ore".
				   The trouble with a sentence is that the number inside it is
				   read as part of the phrase and not as a figure, and the one
				   figure you have to type into the offer screen was going
				   unseen on a card that had it in bold on the first line. The
				   verb stays, small and coloured; the quantity moved down to
				   the stats, labelled, where a number is looked for. */
				final JPanel verbRow = new JPanel();
				verbRow.setLayout(new BoxLayout(verbRow, BoxLayout.X_AXIS));
				verbRow.setOpaque(false);
				verbRow.setAlignmentX(0f);
				/* Upper case and a size up. "Buy" set 11px beside the item's
				   own name was the quietest thing on a card whose entire job
				   is to tell you which of two things to do. */
				final JLabel verb = new JLabel(c.verb.toUpperCase(java.util.Locale.ROOT));
				verb.setForeground(lineFg);
				verb.setFont(verb.getFont().deriveFont(Font.BOLD, 13f));
				verb.setAlignmentY(0.5f);
				verbRow.add(verb);
				if (c.provenance != null)
				{
					final JLabel from = new JLabel(" · " + c.provenance);
					from.setForeground(c.provenanceColor != null ? c.provenanceColor : Brand.TEXT_STRUCTURAL);
					from.setFont(from.getFont().deriveFont(10f));
					from.setAlignmentY(0.5f);
					verbRow.add(from);
				}
				stack.add(holdHeight(verbRow));
			}
			else if (c.provenance != null)
			{
				/* What the "SELL FROM YOUR BANK" header used to say, now on the
				   card with the rest of the idea. Small and grey: it is context
				   for the instruction above, not part of it. */
				final JLabel from = new JLabel(c.provenance);
				from.setForeground(c.provenanceColor != null ? c.provenanceColor : Brand.TEXT_STRUCTURAL);
				from.setFont(from.getFont().deriveFont(10f));
				from.setAlignmentX(0f);
				stack.add(from);
			}
			row1.add(stack, BorderLayout.CENTER);
		}
		else
		{
			row1.add(nameLabel, BorderLayout.CENTER);
		}
		if (c.close != null || c.collapse != null)
		{
			JPanel eastWrap = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
			eastWrap.setOpaque(false);
			if (c.close != null)
			{
				eastWrap.add(c.close);
			}
			if (c.collapse != null)
			{
				/* The section's collapse handle, on the card instead of on a
				   header row above it. That row held nothing but this chevron
				   once the titles came off, and an empty strip 27px tall over
				   the one thing you actually read is the sidebar spending its
				   scarcest resource on a 10px glyph. */
				eastWrap.add(c.collapse);
			}
			row1.add(eastWrap, BorderLayout.EAST);
		}
		/* Held to its own height. A BorderLayout panel reports no maximum,
		   and BoxLayout hands a column's spare height to every child that
		   will take it — so on a card shorter than MIN_CARD_HEIGHT the slack
		   was being split between this row and the glue above the buttons,
		   and the gap under the item name grew and shrank from one card to
		   the next. Measured: 19px under "Leather", 13px under "Uncut
		   diamond". All of it goes to the glue now, where it was meant to. */
		p.add(holdHeight(row1));

		/* The chart button leads the controls row on every card, so it sits
		   in the same place each time and costs the title nothing. Done here
		   rather than in each card builder so none of them can forget it. */
		if (c.controls != null)
		{
			final JPanel withChart = controlsRow();
			addControl(withChart, chartButton(itemName));
			for (java.awt.Component existing : c.controls.getComponents())
			{
				withChart.add(existing);
			}
			c.controls = withChart;
		}
		/* ...and it has to happen BEFORE the row is placed, because that
		   swaps c.controls for a NEW panel. Placing first added the old one
		   and then pinned it, empty, to zero height — the buttons vanished
		   off every card. */


		if (c.score != null)
		{
			p.add(leftStrut(6));
			p.add(scoreRow(c.score));
		}
		else if (c.clearance != null)
		{
			p.add(leftStrut(6));
			p.add(clearanceRow(c.clearance));
		}
		if (c.pair != null)
		{
			p.add(leftStrut(8));
			p.add(pairRow(c.pair));
		}

		/* Skipped when the sandwich above already said it — actionText stays
		   set for the share image, which renders from it. */
		if (c.actionText != null && c.actionLead == null)
		{
			p.add(leftStrut(3));
			final Color actionFg = c.actionColor != null ? c.actionColor : c.accent;
			if (c.actionLabel != null)
			{
				/* Stacked, not side by side. Measured: "Target sell" plus a
				   four-digit quantity and price comes to 252px against the
				   204 a card has, and no readable font size rescues it \u2014 a
				   large price ("100,000 @ 2,147,483 gp") is still over at
				   12pt. So the white label takes its own line and the numbers
				   get the full width beneath it, which also puts the figure
				   you are about to type on a line of its own. */
				final JLabel lead = new JLabel(c.actionLabel.trim());
				lead.setForeground(Color.WHITE);
				lead.setFont(lead.getFont().deriveFont(Font.BOLD, 11f));
				lead.setAlignmentX(0f);
				p.add(lead);
				final JLabel rest = new JLabel(c.actionText);
				rest.setForeground(actionFg);
				rest.setFont(rest.getFont().deriveFont(Font.BOLD, 14f));
				rest.setAlignmentX(0f);
				p.add(rest);
			}
			else
			{
				JLabel actionLabel = new JLabel(c.actionText);
				actionLabel.setForeground(actionFg);
				actionLabel.setFont(actionLabel.getFont().deriveFont(Font.BOLD, 14f));
				actionLabel.setAlignmentX(0f);
				p.add(actionLabel);
			}
		}

		if (c.subText != null)
		{
			p.add(leftStrut(2));
			JLabel sub = new JLabel(c.subText);
			sub.setForeground(Brand.TEXT_STRUCTURAL);
			sub.setFont(sub.getFont().deriveFont(11f));
			sub.setAlignmentX(0f);
			p.add(sub);
		}

		if (c.profitValue == null && c.profitNote != null)
		{
			/*
			 * The same slot, the same 19f weight and the same row height as a
			 * real profit figure, so a card that has no figure is exactly as
			 * tall as one that does — asked for as "put in big orange text
			 * where those numbers are in same font size as that green ... to
			 * keep all car[d] sizes same". It was 15f, which left this row
			 * four pixels shorter than every other card's.
			 *
			 * Orange, and deliberately NOT the profit colours: red would say
			 * you are down and green that you are up, and the whole point of
			 * this card is that the plugin does not know which. It is the same
			 * orange as the advisory line at the foot, which is the card's
			 * colour for "read this, it is not a number".
			 */
			final JLabel note = new JLabel(c.profitNote);
			note.setForeground(ADJUST);
			note.setFont(note.getFont().deriveFont(Font.BOLD, 19f));
			note.setAlignmentX(0f);
			if (c.profitTooltip != null)
			{
				note.setToolTipText(c.profitTooltip);
			}
			/* 4, matching the strut before a real profit figure. It was 6,
			   which made a card carrying this line 2px taller than one
			   carrying a number — "super minor height changes betweeen
			   cycling between these two card types". The two rows occupy the
			   same slot and must lead in identically. */
			p.add(leftStrut(4));
			p.add(holdHeight(note));
		}
		if (c.profitValue != null)
		{
			/* Order: what you pay, then what you sell at, then what that leaves.
			   The profit used to sit between the buy price and the sell price,
			   which put the conclusion in the middle of its own working — the
			   green number is only true at the price on the line BELOW it. Read
			   top to bottom it is now the arithmetic in the order you would say
			   it out loud. */
			/* Not when the boxed pair above already carries the exit — the
			   SELL @ box is this row, in the site's shape. */
			if (c.exitPrice > 0 && c.pair == null)
			{
				/* Readable, and in the SELL colour.
				   This was 11f grey — small enough to read as a footnote when
				   it is half the trade: the gold line above says what you pay,
				   this says what you have to get back out at, and the green
				   number between them is only true if you do. The card already
				   uses gold for the buy side and teal for the sell side on its
				   action line, so the same teal here lets the pair be read
				   without reading the words. */
				/* Its OWN row, not tacked onto the money line.
				   Measured: at a readable 13f, "+296M gp profit" plus
				   "@ 1,250,000 gp" comes to 253px against the card's 211px, so
				   on an expensive item the price would be clipped — and a
				   clipped exit price is worse than a small one. On its own row
				   it has the whole width, so it stays legible no matter how
				   big the number gets.

				   Labelled "Sell at", matching the card's existing
				   white-word/coloured-number idiom, and in the same teal the
				   action line uses for a sell — so gold above is what you pay
				   and teal below is what you have to get back out at. */
				final JPanel exit = new JPanel();
				exit.setLayout(new BoxLayout(exit, BoxLayout.X_AXIS));
				exit.setOpaque(false);
				exit.setAlignmentX(0f);
				final JLabel sellWord = new JLabel("Sell at ");
				sellWord.setForeground(Color.WHITE);
				sellWord.setFont(sellWord.getFont().deriveFont(Font.BOLD, 11f));
				sellWord.setAlignmentY(0.5f);
				final JLabel at = new JLabel(String.format("%,d", c.exitPrice) + " gp");
				at.setForeground(sellColor());
				at.setFont(at.getFont().deriveFont(Font.BOLD, 14f));
				at.setAlignmentY(0.5f);
				final String tip = "The sell price this profit assumes — today's insta-buy. Bid "
					+ String.format("%,d", c.exitPrice) + " gp back out and the green number above is what you keep after the 2% tax.";
				sellWord.setToolTipText(tip);
				at.setToolTipText(tip);
				exit.add(sellWord);
				exit.add(at);
				exit.add(Box.createHorizontalGlue());
				p.add(holdHeight(exit));
			}
			p.add(leftStrut(4));
			/* The money and the price that produces it, side by side but not
			   the same weight: a buy card names the price to BID at, then a
			   green number that is only true at some other price. Without the
			   exit there is nothing on the card to check the profit against.

			   A row rather than one string, because the two want different
			   sizes — 15f bold for the money, 11f grey for the price — and
			   because a long price then costs the layout a wrap rather than
			   widening the sidebar. */
			final JPanel money = new JPanel();
			money.setLayout(new BoxLayout(money, BoxLayout.X_AXIS));
			money.setOpaque(false);
			money.setAlignmentX(0f);
			JLabel profitLabel = new JLabel(moneyLine(c));
			profitLabel.setForeground(c.profitValue >= 0 ? POSITIVE : NEGATIVE);
			/* The biggest thing on the card, by a clear margin.
			   It was 15f, the same size as the item name and a point over the
			   price boxes, so the one number the whole card exists to produce
			   was competing on equal terms with the label above it. At 19f it
			   wins outright and the card has an obvious place for the eye to
			   land. Checked against the widest figure the panel can print —
			   "+296M gp profit" — inside a 204px card. */
			profitLabel.setFont(profitLabel.getFont().deriveFont(Font.BOLD, 19f));
			/* "+296M gp profit available" is wider than the card at 19f.
			   Step down until it fits rather than letting Swing clip it to
			   "+296M gp prof…", which would cut off the word that says what
			   the number is. */
			for (float size = 18f; size >= 13f
				&& profitLabel.getPreferredSize().width > PROFIT_LINE_MAX_WIDTH; size -= 1f)
			{
				profitLabel.setFont(profitLabel.getFont().deriveFont(Font.BOLD, size));
			}
			profitLabel.setAlignmentY(0.5f);
			if (c.profitTooltip != null)
			{
				profitLabel.setToolTipText(c.profitTooltip);
			}
			money.add(profitLabel);
			money.add(Box.createHorizontalGlue());
			p.add(holdHeight(money));
		}

		if (c.stats != null && !c.stats.isEmpty())
		{
			/* The site card's stat cells: a 9pt label over a bold figure, as
			   many across as there are figures. QUANTITY and CAPITAL for a
			   buy, QUANTITY alone for a sell. Exact with separators, never
			   abbreviated \u2014 1.77M and 177M are one dot apart at this size and
			   these are the two numbers you type. */
			p.add(leftStrut(6));
			p.add(statsRow(c.stats));
		}

		if (c.capital > 0)
		{
			/* "1.77M gp capital" in small grey was unreadable at a glance \u2014
			   1.77M and 177M are one misread apart, and that is a hundredfold
			   error in the only number that says whether you can afford this.
			   Named, brightened, and the exact figure on the tooltip so the
			   abbreviation never has to be trusted on its own. */
			/* Stacked, for the same reason the action line is: side by side,
			   the label plus an exact figure came to exactly the 204px a card
			   has, leaving nothing for a bigger number — and capital can run
			   to billions. Label above, figure below, the same shape as the
			   target line so the two read as a pair.

			   Exact, with separators, because the abbreviation was the whole
			   problem: 1.77M and 177M differ by a decimal point at 11px, and
			   reading that wrong by a factor of a hundred is the difference
			   between affording a flip and not. */
			p.add(leftStrut(4));
			final String tip = tip(String.format("%,d", c.capital) + " gp tied up",
				"Sized to the cash you have free and the slots you have spare.");
			/* Caps at 9f, like QUANTITY and VALUE. The card's rule is that a
			   LABEL is upper case and small so it recedes, and the figure it
			   names is not — so this one follows it even though it is no
			   longer a stat cell. The line stays visually distinct by being
			   stacked on its own and by the accent on its figure, not by
			   breaking the one typographic convention the card has. */
			final JLabel capName = new JLabel("CAPITAL NEEDED");
			capName.setForeground(Brand.TEXT_STRUCTURAL);
			capName.setFont(capName.getFont().deriveFont(Font.BOLD, 9f));
			capName.setAlignmentX(0f);
			capName.setToolTipText(tip);
			p.add(capName);
			final JLabel capValue = new JLabel(String.format("%,d", c.capital) + " gp");
			/* Gold, not the near-white every other figure uses. This is the
			   only number on the card that is money going OUT, and it now
			   sits under two figures that are not — so it gets the buy
			   accent rather than the shared parchment. */
			capValue.setForeground(buyColor());
			capValue.setFont(capValue.getFont().deriveFont(Font.BOLD, 13f));
			capValue.setAlignmentX(0f);
			capValue.setToolTipText(tip);
			p.add(capValue);
		}

		/*
		 * Footnote ABOVE the buttons, and the buttons last on every card.
		 *
		 * This was the other way round, which meant the two kinds of small
		 * print sat on opposite sides of the button row: "Capital needed"
		 * above it on a buy, "At a loss — Hold to keep it" below it on a
		 * sell. Measured, that put Next 27px further down on a buy card than
		 * on a sell — so paging through ideas moved the button out from under
		 * the cursor, on a control whose entire purpose is being pressed
		 * repeatedly.
		 *
		 * All the reading matter above, all the verbs below.
		 */
		if (c.footnote != null || c.position != null)
		{
			p.add(leftStrut(6));
			/*
			 * The footnote and the pager count share this row.
			 *
			 * The count was stacked above the chevrons, which cost the card a
			 * row and a strut for four characters, while the footnote — one
			 * short sentence — left 60-100px of empty line beside it. Asked
			 * for directly: "move all these buttons up and the 1/17 to be on
			 * same line as orange text, then remove the empty space that
			 * creates underneeth".
			 *
			 * The two never collide: the footnote is width-checked against
			 * CARD_INNER (see fitsCard) and the longest one measured leaves
			 * room for "18/20" with a gap. If one ever did, the glue collapses
			 * first and the count keeps its pinned width.
			 */
			final JPanel footRow = new JPanel();
			footRow.setLayout(new BoxLayout(footRow, BoxLayout.X_AXIS));
			footRow.setOpaque(false);
			footRow.setAlignmentX(0f);
			JLabel foot = new JLabel(c.footnote == null ? "" : c.footnote);
			/* Orange on every card, asked for directly: "add orange text
			   reccomendation at the bottom of every card like at a loss hold
			   to keep it". Bold is still reserved for the ones that are a
			   warning, so "At a loss" does not lose its weight by everything
			   around it wearing the same colour. */
			foot.setForeground(ADJUST);
			/* 11f, like subText and the capital line. At 10f it was the one
			   plain-10 thing on a buy card, which is what made "Profit if
			   both offers fill" hard to read — it is the caveat on the number
			   above it, so it has to be legible or it should not be there. */
			foot.setFont(foot.getFont().deriveFont(c.footnoteWarn ? Font.BOLD : Font.PLAIN, 11f));
			foot.setAlignmentX(0f);
			/* Pinned, or BoxLayout hands this label a share of the spare width
			   the glue is meant to take — same trap as pagerCount's own. */
			foot.setAlignmentY(0.5f);
			foot.setMaximumSize(foot.getPreferredSize());
			footRow.add(foot);
			footRow.add(Box.createHorizontalGlue());
			/*
			 * The count's height is reserved whether or not there is a count.
			 *
			 * A shortlist of one carries no count — "1/1" is a pager reporting
			 * that it is not one — and neither does a card opened from the
			 * watchlist. The count is 12px bold against the footnote's 11px,
			 * so a row without one came out a pixel shorter and every button
			 * below it moved: "when /16 ideas shown vs no numbers, it messed
			 * up spacing". That was 19px before the count came onto this row
			 * and 1px after, and 1px is still the buttons moving under the
			 * cursor for a reason the player cannot see.
			 *
			 * An empty label in the same font holds the row open instead.
			 */
			footRow.add(c.position != null
				? pagerCount(c.position[0], c.position[1])
				: countSpacer());
			if (c.position != null)
			{
				/*
				 * One pixel of right inset, and it is not arbitrary.
				 *
				 * The card's content box ends at x=231 (measured), but nothing
				 * the player can see reaches it: the price pair splits an odd
				 * width between two boxes and each rounds down, and the arrows
				 * row is pinned to its preferred width, so the SELL box and the
				 * Next chevron both land on 230. Flush to the true edge, the
				 * count alone sat a pixel proud of the column it is supposed to
				 * line up with — "right align these with the blue box above".
				 */
				footRow.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 1));
			}
			p.add(holdHeight(footRow));
		}


		if (c.controls != null || c.pager != null)
		{
			/*
			 * One footer row: the tools hard left, the pager hard right, and
			 * the card's spare width between them.
			 *
			 * The tools used to sit under the item name. They moved down with
			 * the pager — "may as well move all butons downn but keep
			 * separate from arrows" — which is also how the website's card
			 * reads: nothing between the title and the numbers.
			 *
			 * The glue is what keeps them separate. Everything left of it
			 * acts on THIS item; the two chevrons right of it move you off
			 * it, and they are far enough apart that a misclick lands on
			 * neither.
			 *
			 * Bottom-aligned, because the pager is two rows tall when it
			 * carries a count and the tools are one: without this the buttons
			 * would centre against the count instead of sitting on the same
			 * baseline as the chevrons.
			 */
			/* 3px, not 6. The count no longer sits between the footnote and
			   the chevrons, so the two rows can close up — "this could all be
			   tighted up a little". */
			p.add(leftStrut(c.footnote != null || c.position != null ? 3 : 6));
			final JPanel footer = new JPanel();
			footer.setLayout(new BoxLayout(footer, BoxLayout.X_AXIS));
			footer.setOpaque(false);
			footer.setAlignmentX(0f);
			if (c.controls != null)
			{
				c.controls.setAlignmentY(1f);
				footer.add(holdHeight(c.controls));
			}
			footer.add(Box.createHorizontalGlue());
			if (c.pager != null)
			{
				footer.add(c.pager);
			}
			p.add(holdHeight(footer));
		}

		if (c.tooltip != null)
		{
			p.setToolTipText(c.tooltip);
		}

		wireHover(p, OBSIDIAN_BG);
		/* Last, so it reaches everything added above. */
		if (c.contextMenu != null)
		{
			inheritPopup(p);
		}
		return p;
	}

	/** Let every child of {@code root} use the card's right-click menu. A
	 *  component that already has its own keeps it — Swing only consults the
	 *  parent when getComponentPopupMenu() is null. */
	private static void inheritPopup(java.awt.Container root)
	{
		for (Component child : root.getComponents())
		{
			if (child instanceof JComponent)
			{
				((JComponent) child).setInheritsPopupMenu(true);
			}
			if (child instanceof java.awt.Container)
			{
				inheritPopup((java.awt.Container) child);
			}
		}
	}

	/**
	 * The card's right-click menu.
	 *
	 * Block was an icon button next to Hold. Two adjacent buttons that both
	 * mean "not this one", differing only in whether it lasts the session or
	 * forever, is a choice you have to stop and read the tooltips to make —
	 * and the permanent one was the easier of the two to hit by accident.
	 *
	 * Behind a right-click it is deliberate, it costs the row no width, and
	 * the confirm step it always had still runs.
	 */
	/** The card's right-click: "Never recommend", the diagnostic report,
	 *  and — when the card prices a stack at what you paid — a way to
	 *  forget that price. */
	private JPopupMenu cardPopup(int itemId, String itemName, boolean costed,
		java.util.function.Supplier<String> card)
	{
		final JPopupMenu menu = blockPopup(itemName);
		final JMenuItem report = new JMenuItem("Copy PocketGE report");
		report.setToolTipText("Copies what the plugin knows about " + itemName
			+ " to the clipboard, to paste to whoever is helping you. No account names; nothing is sent anywhere.");
		report.addActionListener(e -> actions.copyReport(itemId, itemName, card.get()));
		menu.add(report);
		final long[] older = costed ? olderBuys.get(itemId) : null;
		if (older != null && older[0] > 0)
		{
			final JMenuItem forgetOlder = new JMenuItem("Forget the " + String.format("%,d", older[0]) + " older buys");
			forgetOlder.setToolTipText("Buys of " + itemName + " from before the stack you hold, which you no longer have."
				+ " A sale only reaches them if you sell more than you bought since; it asks first.");
			forgetOlder.addActionListener(e ->
			{
				if (confirmForgetOlder(itemName, older))
				{
					actions.forgetOlder(itemId, itemName, older[0]);
				}
			});
			menu.add(forgetOlder);
		}
		if (costed)
		{
			final JMenuItem forget = new JMenuItem("Forget what I paid for " + itemName);
			forget.setToolTipText("For when PAID @ is wrong. Clears the purchases the plugin recorded for "
				+ itemName + "; it asks first.");
			forget.addActionListener(e ->
			{
				final long[] paid = actions.paidRecord(itemId);
				if (confirmForget(itemName, paid))
				{
					actions.forgetPaid(itemId, itemName, paid[2]);
				}
			});
			menu.add(forget);
		}
		return menu;
	}

	/** Always asks, like confirmForget. */
	private boolean confirmForgetOlder(String itemName, long[] older)
	{
		final JLabel ask = new JLabel("<html><div style='width:230px'>Forget <b>" + String.format("%,d", older[0])
			+ "</b> older buys of <b>" + itemName + "</b>, at <b>"
			+ String.format("%,d", Math.round(older[1] / (double) older[0])) + "</b> gp each?"
			+ "<br><br>PocketGE has them on record from before the stack you hold, but they were not in your bank"
			+ " when you last opened it, your inventory or your GE slots — most likely sold where the plugin"
			+ " didn't see it. Left alone they stay on record, and in this note; a sale only reaches them if"
			+ " you sell more than you have bought since."
			+ "<br><br><span style='color:#8a8274'>What you paid for the stack you hold is kept. If another of your"
			+ " characters holds these, cancel. This can't be undone.</span></div></html>");
		final int choice = javax.swing.JOptionPane.showConfirmDialog(this, ask, "Forget older buys",
			javax.swing.JOptionPane.OK_CANCEL_OPTION, javax.swing.JOptionPane.WARNING_MESSAGE);
		return choice == javax.swing.JOptionPane.OK_OPTION;
	}

	/** Always asks — unlike blocking, this cannot be undone from settings. */
	private boolean confirmForget(String itemName, long[] paid)
	{
		if (paid == null || paid.length < 3 || paid[0] <= 0)
		{
			/* A card built before the record went — say so, rather than an
			   entry that promised to ask and then did nothing. */
			javax.swing.JOptionPane.showMessageDialog(this,
				"PocketGE has nothing recorded for " + itemName + " any more.",
				"Forget what I paid", javax.swing.JOptionPane.INFORMATION_MESSAGE);
			return false;
		}
		final JLabel ask = new JLabel("<html><div style='width:230px'>Forget what PocketGE recorded paying for <b>"
			+ itemName + "</b>?<br><br>It counts <b>" + String.format("%,d", paid[0]) + "</b> bought at <b>"
			+ String.format("%,d", Math.round(paid[1] / (double) paid[0])) + "</b> gp each and not yet sold"
			+ " on this character (and any bought before PocketGE kept them apart)."
			+ "<br><br><span style='color:#8a8274'>Do this when that is wrong. Until you buy more, cards show "
			+ itemName + " with no cost and selling it books no flip. This can't be undone.</span></div></html>");
		final int choice = javax.swing.JOptionPane.showConfirmDialog(this, ask, "Forget what I paid",
			javax.swing.JOptionPane.OK_CANCEL_OPTION, javax.swing.JOptionPane.WARNING_MESSAGE);
		return choice == javax.swing.JOptionPane.OK_OPTION;
	}

	/** Every field a card is built from, one per line — the numbers on the
	 *  card and the ones it was derived from. For the diagnostic report. */
	static String describeRec(Rec r)
	{
		if (r == null)
		{
			return "(no card)\n";
		}
		return "  verb " + (r.sell ? "SELL" : "BUY") + ", item " + r.name + " (" + r.itemId + ")\n"
			+ "  unitPrice " + r.unitPrice + ", unitCost " + r.unitCost + ", exitPrice " + r.exitPrice + "\n"
			+ "  quantity " + r.quantity + ", profit " + r.profit + ", capital " + r.capital
			+ ", hasTrackedCost " + r.hasTrackedCost + "\n"
			+ "  untrackedQty " + r.untrackedQty + ", untrackedValue " + r.untrackedValue + "\n"
			+ "  heldWhere " + r.heldWhere + ", listing " + r.listingNote + "\n"
			+ "  note " + r.note + "\n";
	}

	/** The watchlist row behind an inspected card, for the same report. */
	static String describeRow(FavoritesPanel.Row r)
	{
		if (r == null)
		{
			return "";
		}
		return "  row: price " + r.price + ", targetBuy " + r.targetBuy + ", targetSell " + r.targetSell
			+ ", limit " + r.limit + ", potentialProfit " + r.potentialProfit + "\n"
			+ "  row: heldQty " + r.heldQty + ", sellValue " + r.sellValue + ", hasCostBasis " + r.hasCostBasis
			+ ", pricedQty " + r.pricedQty + ", pricedCost " + r.pricedCost + ", heldProfit " + r.heldProfit + "\n"
			+ "  row: listed " + r.listedQty + " (" + r.listedSold + "/" + r.listedTotal + " @ " + r.listedPrice + ")"
			+ ", bidding " + r.bidFilled + "/" + r.bidQty + " @ " + r.bidPrice + "\n";
	}

	private JPopupMenu blockPopup(String itemName)
	{
		final JPopupMenu menu = new JPopupMenu();
		/* Focusable popups become heavyweight windows that steal focus once
		   they leave the parent — the search box learned that the hard way. */
		menu.setFocusable(false);
		final JMenuItem block = new JMenuItem("Never recommend " + itemName + " again");
		block.setToolTipText("Hides it from every future suggestion. Undo it in \u2699 \u2192 Blocked items.");
		block.addActionListener(e -> { if (confirmBlock(itemName)) { actions.block(itemName); } });
		menu.add(block);
		return menu;
	}

	private JLabel iconLabel(int itemId, int size)
	{
		JLabel label = new JLabel();
		label.setPreferredSize(new Dimension(size, size));
		label.setMinimumSize(new Dimension(size, size));
		label.setHorizontalAlignment(SwingConstants.CENTER);
		if (itemManager != null && itemId > 0)
		{
			/* Null-checked. ItemManager.getImage builds from the client's
			   item sprites, which are not loaded on the login screen — and
			   these panels render there. An NPE here does not just lose one
			   icon: it is thrown inside a row builder called from update(),
			   so it aborts the whole rebuild mid-list and takes the rest of
			   the panel with it. Same failure the getItemStats guard nearby
			   exists for. A missing icon is a blank square; a missing panel
			   reads as the plugin being broken. */
			final AsyncBufferedImage img = itemManager.getImage(itemId);
			if (img != null)
			{
				img.addTo(label);
			}
		}
		return label;
	}

	/** A hover tint on the whole card, nothing more — clicking anywhere on
	 *  the card used to also open the browser, which meant tapping the
	 *  profit/rating text just to read it (or, now that this card has a
	 *  Share and a favorite-toggle button too, missing one of those by a
	 *  few pixels) fired off a browser tab you didn't ask for. Opening the
	 *  chart is chartButton's job specifically now, not the card's. */
	/** Clicking the item itself opens its chart — the same affordance the
	 *  favorites rows have, so the gesture is consistent wherever an item
	 *  name appears. Scoped to the name and the sprite rather than the whole
	 *  card: the controls row sits a few pixels away, and a card-wide click
	 *  target put "open a browser tab" one slip away from every button. */
	private void wireOpenChartOnClick(java.awt.Component c, String itemName)
	{
		c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		c.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getButton() == MouseEvent.BUTTON1)
				{
					actions.openChart(itemName);
				}
			}
		});
	}

	private static void wireHover(JPanel row, Color normalBg)
	{
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(HOVER_BG);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(normalBg);
			}
		});
	}

	private JButton smallBtn(String label, String tip, java.awt.event.ActionListener a)
	{
		JButton b = new JButton(label);
		b.setToolTipText(tip);
		b.setFocusPainted(false);
		b.setFont(b.getFont().deriveFont(11f));
		b.setMargin(new Insets(2, 6, 2, 6));
		b.addActionListener(a);
		return b;
	}

	/** The ONLY way this card opens the live chart — mirroring Flipping
	 *  Copilot's own graph icon next to item names — gold and sized up a
	 *  notch from the rest of the card's chrome so it reads as an obvious,
	 *  clickable affordance rather than a subtle decoration. Clicking
	 *  elsewhere on the card no longer does this (see wireOpenChart) — with
	 *  a Share and a favorite-toggle button also living on this card now, a
	 *  whole-card click target meant any of those was one stray pixel away
	 *  from opening a browser tab instead. Drawn with Java2D rather than an
	 *  emoji glyph — emoji font fallback support is inconsistent across the
	 *  JREs RuneLite runs on, so a relied-on affordance icon needs to
	 *  render the same everywhere. */
	/**
	 * Left-click hands the item to a PocketGE tab you already have open;
	 * right-click forces a new browser tab instead.
	 *
	 * Right-click rather than a second button because the controls row has
	 * no width to give — Next, Hold and Block already fought over it, and
	 * Pause had to leave for the top bar. A second chart icon would cost a
	 * visible, frequently-pressed control to serve the rarer case.
	 *
	 * Rare, but not unwanted: the handoff deliberately reuses the tab you
	 * were looking at, so comparing two items means losing the first. This
	 * is the escape hatch, and the tooltip says it exists since a right-click
	 * on a toolbar button is not something anyone discovers by accident.
	 */
	/**
	 * Ask before blocking, unless told not to.
	 *
	 * Blocking is the only action on the card that is silent, permanent and
	 * easy to hit by accident: the icon sits in the same row as Next, nothing
	 * on screen changes when it lands, and the item just never appears again.
	 * Someone who fat-fingers it has no way to know what happened, let alone
	 * which item it was — so the dialog names the item, and says where to undo
	 * it. That last part is the half that matters: a confirmation that only
	 * says "are you sure" leaves you no better off if you were wrong.
	 *
	 * The tick is a real preference, not a session flag, so it survives a
	 * restart for people who block deliberately and often.
	 *
	 * @return true if the block should go ahead
	 */
	private boolean confirmBlock(String itemName)
	{
		if (!settings.confirmBlock)
		{
			return true;
		}
		final JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		final JLabel ask = new JLabel("<html>Never recommend <b>" + itemName + "</b> again?</html>");
		ask.setAlignmentX(0f);
		body.add(ask);
		body.add(Box.createVerticalStrut(8));
		final JLabel how = new JLabel("<html><span style='color:#8a8274'>To unblock it later, open "
			+ "settings (\u2699) and edit the never-recommend list.</span></html>");
		how.setAlignmentX(0f);
		body.add(how);
		body.add(Box.createVerticalStrut(10));
		final javax.swing.JCheckBox dontAsk = new javax.swing.JCheckBox("Don't ask me again");
		dontAsk.setAlignmentX(0f);
		dontAsk.setOpaque(false);
		body.add(dontAsk);

		final int choice = javax.swing.JOptionPane.showConfirmDialog(this, body, "Block item",
			javax.swing.JOptionPane.OK_CANCEL_OPTION, javax.swing.JOptionPane.QUESTION_MESSAGE);
		if (choice != javax.swing.JOptionPane.OK_OPTION)
		{
			/* Cancelled. The tick is deliberately NOT saved here — someone who
			   ticks it and then backs out has not agreed to anything, and
			   silently disabling the guard on the way out of a cancelled
			   dialog is how you lose the next item by accident. */
			return false;
		}
		if (dontAsk.isSelected())
		{
			settings.confirmBlock = false;
			actions.setConfirmBlock(false);
		}
		return true;
	}

	private JButton chartButton(String itemName)
	{
		JButton b = new JButton(CHART_ICON);
		b.setToolTipText(tip("Chart on pocketge.com",
			"Opens a new tab. Right-click to send it to a tab you already have open."));
		b.setMargin(new Insets(2, 4, 2, 4));
		b.addActionListener(e -> actions.openChartTab(itemName));
		b.setComponentPopupMenu(chartPopup(itemName));
		/* Dressed like the buttons beside it. It was the one control on the
		   row left on the look-and-feel's default face — a different fill, a
		   different border, no fixed size — so it read as something that had
		   wandered in from another panel. */
		return styleAsControl(b);
	}

	/**
	 * What the GE item search should offer while {@code shown} is on the
	 * card. That search only ever buys — a sell starts from your inventory —
	 * so a buy card offers its own item, and a sell card the next buy idea
	 * in the list rather than the stack it is telling you to sell. Null when
	 * there is no buy to offer.
	 */
	Rec searchItemFor(Rec shown)
	{
		if (shown != null && !shown.sell)
		{
			return shown;
		}
		final int n = recommendations.size();
		for (int k = 1; k <= n; k++)
		{
			final Rec r = recommendations.get((Math.max(0, recIndex) + k) % n);
			if (!r.sell)
			{
				return r;
			}
		}
		return null;
	}

	/** Last item handed to {@link Actions#onSearchItemShown}. */
	private Integer announcedSearchId;

	private void announceSearchItem(Rec r)
	{
		final Integer id = r != null ? r.itemId : null;
		if (java.util.Objects.equals(id, announcedSearchId))
		{
			return;
		}
		announcedSearchId = id;
		actions.onSearchItemShown(id, r != null ? r.name : null);
	}

	/**
	 * Up to {@code AHEAD} distinct items after the card at {@code at}, in the
	 * order Next reaches them, round from the last card to the first.
	 *
	 * Only the first few flip ideas get a price series from the advisor's
	 * round, so a card further down showed the last two prints and no
	 * rating where the one before it, scored the website's way, said "Solid
	 * Flip 55": "why sometimes flip rating and sometimes not". Asked for
	 * ahead, it is priced and rated by the time it is paged to. Two, not
	 * one: an idea the engine turns down leaves the list, and the card after
	 * it is then next — already asked for.
	 */
	static java.util.List<Integer> cardsAhead(List<Rec> recs, int at)
	{
		final java.util.List<Integer> out = new ArrayList<>(AHEAD);
		final int n = recs.size();
		for (int k = 1; k < n && out.size() < AHEAD; k++)
		{
			final Rec r = recs.get((Math.max(0, at) + k) % n);
			if (r.itemId != recs.get(Math.max(0, at) % n).itemId && !out.contains(r.itemId))
			{
				out.add(r.itemId);
			}
		}
		return out;
	}

	private static final int AHEAD = 2;

	/** Last value handed to {@link Actions#onRecommendationShown}, so an
	 *  unchanged card does not re-announce itself on every rebuild. */
	private Integer announcedRecItemId;
	private boolean announcedRecSell;

	private void announceShownRecommendation(Rec r)
	{
		final Integer id = r != null ? r.itemId : null;
		final boolean sell = r != null && r.sell;
		if (java.util.Objects.equals(id, announcedRecItemId) && sell == announcedRecSell)
		{
			return;
		}
		announcedRecItemId = id;
		announcedRecSell = sell;
		actions.onRecommendationShown(id, r != null ? r.name : null, sell);
	}

	/** Last list handed to {@link Actions#onCardsAhead}. */
	private java.util.List<Integer> announcedAhead = java.util.List.of();

	/** Hand on the cards ahead whenever they change — with the card on
	 *  screen, or under it when a round re-ranks the list or an idea ahead is
	 *  turned down. How many requests that may cost is the plugin's to bound
	 *  (noteCardsAhead), not this; announced only on a page turn, a re-rank
	 *  left the new next card unasked and it was paged to raw. */
	private void announceCardsAhead(java.util.List<Integer> ahead)
	{
		if (ahead.equals(announcedAhead))
		{
			return;
		}
		announcedAhead = ahead;
		actions.onCardsAhead(ahead);
	}

	/** One of the two coloured instruction lines either side of the item name.
	 *  13f rather than the 14f the single action line used: three stacked
	 *  lines have to fit the sprite's height beside them. */
	/**
	 * The width every card tooltip wraps to.
	 *
	 * Swing lays a plain-string tooltip out on ONE line however long it is,
	 * which is how "The sell price this profit assumes — 19 gp. Ask that back
	 * out and the green number below is what you keep after the 2% tax."
	 * became a 700px ribbon lying across the middle of the screen. A width
	 * turns it into a block; the shape below turns it into something you can
	 * read at a glance.
	 */
	private static final int TIP_W = 185;

	/**
	 * One shape for every tooltip on a card: a bold first line that names the
	 * number or the thing, then at most one short sentence under it.
	 *
	 * Having a shape is most of the point. These were written one at a time
	 * and read like it — some led with the value, some with an explanation,
	 * some ran to three clauses — so hovering two of them in a row felt like
	 * reading two different products. Title, then the reason, then nothing.
	 */
	/**
	 * The same width cap, for text that has no title to lead with.
	 *
	 * The card's own hover text is the advisor's reason string — "you hold
	 * 18,608 — worth ~29,828,624 gp after tax at 1,635 gp each" — and it was
	 * the one tooltip on the card set as a bare String. Swing lays a bare
	 * String out on a single line however long it is, so it ran most of the
	 * way across the client. Reported as "long horizontal hover tool tip that
	 * could be stacked".
	 */
	/**
	 * Does this line fit the card without being clipped?
	 *
	 * The card is {@value #CARD_INNER} pixels wide inside its accent and
	 * padding, and a JLabel over that is silently truncated — no ellipsis in
	 * this look-and-feel, the text just stops. Three footnotes shipped over
	 * the limit before this existed ("Cost unknown — check the chart first"
	 * at 213px, "The only idea on the list right now" at 194px, and the
	 * longest of the buy sizing reasons at 259px), because the only check was
	 * me measuring strings by hand.
	 *
	 * Measured in the LIVE font rather than against a character count: the
	 * headless harness runs a larger default font than RuneLite's, so a
	 * budget in characters is wrong in one of the two.
	 */
	/**
	 * The line for a card that has nothing more specific to say — about the
	 * ITEM, never about the list.
	 *
	 * This slot used to fall through to "Arrows cycle 18 ideas". True, and
	 * useless: it is the same sentence on every card that reaches it, it
	 * says nothing about the thing in front of you, and it was wrong on a
	 * card you opened from the watchlist, where you are not cycling anything.
	 * Reported as "figure out more meaningful text to put there in its place".
	 *
	 * Two things the card knows and was not saying:
	 *
	 * Where the price sits in the item's own recent range, when the plugin
	 * has that series. A stack at a 5-day high is the timing case for
	 * selling; one at a 5-day low is the case for holding it, and it is said
	 * in the same words as the loss line so the two read as one kind of
	 * advice. A buy at a 5-day low is a good entry and is left as the plain
	 * fact — the card is already proposing the buy.
	 *
	 * Failing that, what ONE unit actually nets after the 2% tax. The box
	 * above shows the price before tax and the VALUE cell shows the whole
	 * stack after it; the per-unit figure in between is the one people
	 * forget and is on neither. For a buy it is the per-unit edge — the
	 * total profit is above, but not what each unit clears.
	 *
	 * Everything here is measured against the card's width before it is
	 * committed to, and the bold hold line has a shorter form for that.
	 */
	private void lastResort(Card c, Rec r)
	{
		c.footnoteWarn = false;
		c.footnoteIsDefault = true;   // guidance yields to the offer screen
		if (r.tier != null && r.tier != PriceExtremes.Tier.NONE)
		{
			final boolean fiveDay = r.tier == PriceExtremes.Tier.HIGH_5D
				|| r.tier == PriceExtremes.Tier.LOW_5D;
			final String period = fiveDay ? "5-day" : "day";
			if (r.tier.isHigh())
			{
				c.footnote = "At a " + period + " high";
				return;
			}
			if (r.sell)
			{
				for (String line : new String[]{
					"At a " + period + " low — Hold to keep it",
					period + " low — Hold to keep it",
					"At a " + period + " low"})
				{
					if (fitsCard(line, true))
					{
						c.footnote = line;
						c.footnoteWarn = true;
						c.footnoteIsDefault = false;   // a warning is earned
						return;
					}
				}
			}
			c.footnote = "At a " + period + " low";
			return;
		}
		if (r.sell && r.unitPrice > 0)
		{
			final long net = r.unitPrice - FlipTracker.taxPerItem(r.unitPrice, r.itemId);
			for (String line : new String[]{
				"Nets " + String.format("%,d", net) + " gp each after tax",
				"Nets " + QuantityFormatter.quantityToStackSize(net) + " gp each"})
			{
				if (net > 0 && fitsCard(line, false))
				{
					c.footnote = line;
					return;
				}
			}
		}
		if (!r.sell && r.exitPrice > 0 && r.unitPrice > 0)
		{
			final long edge = r.exitPrice - FlipTracker.taxPerItem(r.exitPrice, r.itemId) - r.unitPrice;
			for (String line : new String[]{
				"Clears " + String.format("%,d", edge) + " gp each after tax",
				"Clears " + QuantityFormatter.quantityToStackSize(edge) + " gp each"})
			{
				if (edge > 0 && fitsCard(line, false))
				{
					c.footnote = line;
					return;
				}
			}
		}
	}

	/** "Paid on 1,456 of 8,944", or the shortest form that fits, or nothing.
	 *  Huge stacks push even this over the card's width, and a truncated
	 *  count is worse than no count. */
	private static String paidOn(Rec r)
	{
		final String covered = String.format("%,d", r.quantity - r.untrackedQty);
		final String whole = String.format("%,d", r.quantity);
		if (r.untrackedQty <= 0)
		{
			/*
			 * A stack the plugin watched you buy ALL of still gets a line.
			 *
			 * This fired only when part of the stack was untracked, so a
			 * fully tracked sell came out one row shorter than every other
			 * sell — 16px, which is exactly what paging between them moved
			 * the chevrons by. "all" is the honest word: the PAID figure
			 * covers the whole quantity, which is what the partly-tracked
			 * form says about its own subset.
			 */
			final String all = "Paid on all " + whole;
			return fitsCard(all, true) ? all : null;
		}
		for (String s : new String[]{
			"Paid on " + covered + " of " + whole,
			"Covers " + covered + " of " + whole,
			covered + " of " + whole})
		{
			if (fitsCard(s, true))
			{
				return s;
			}
		}
		return null;
	}

	private static boolean fitsCard(String text, boolean bold)
	{
		if (text == null || text.isEmpty())
		{
			return false;
		}
		final JLabel probe = new JLabel(text);
		probe.setFont(probe.getFont().deriveFont(bold ? Font.BOLD : Font.PLAIN, 11f));
		return probe.getPreferredSize().width <= CARD_INNER;
	}

	static String wrapTip(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}
		return "<html><body style='width:" + TIP_W + "px'>" + text + "</body></html>";
	}

	static String tip(String title, String body)
	{
		final StringBuilder b = new StringBuilder("<html><body style='width:")
			.append(TIP_W).append("px'><b>").append(title).append("</b>");
		if (body != null && !body.isEmpty())
		{
			b.append("<br>").append(body);
		}
		return b.append("</body></html>").toString();
	}

	private static JLabel actionLine(String text, Color fg)
	{
		final JLabel l = new JLabel(text);
		l.setForeground(fg);
		l.setFont(l.getFont().deriveFont(Font.BOLD, 13f));
		l.setAlignmentX(0f);
		return l;
	}

	/**
	 * The site card's score, laid flat for a 225px sidebar: the verdict on
	 * the left, the number on the right, both in the band's colour, and the
	 * meter running between them. On the site the number stacks over the
	 * word with the meter beneath, in a 58px column beside the name; here
	 * that column would come straight out of the item name, which is
	 * already the thing this card truncates first — and a meter on a row of
	 * its own cost 8px that every card then had to be held to.
	 */
	private JPanel scoreRow(TradeEngine.FlipScore s)
	{
		final Color fg = new Color(s.band.color);
		final String tip = scoreTip(s);
		final JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setOpaque(false);
		row.setAlignmentX(0f);
		final JLabel word = new JLabel(s.band.word);
		word.setForeground(fg);
		word.setFont(word.getFont().deriveFont(Font.BOLD, 11f));
		word.setToolTipText(tip);
		word.setAlignmentY(0.5f);
		final JLabel num = new JLabel(String.valueOf(s.total));
		num.setForeground(fg);
		num.setFont(num.getFont().deriveFont(Font.BOLD, 15f));
		num.setToolTipText(tip);
		num.setAlignmentY(0.5f);
		final JComponent meter = scoreMeter(s);
		meter.setAlignmentY(0.5f);
		row.add(word);
		row.add(Box.createHorizontalStrut(8));
		row.add(meter);
		row.add(Box.createHorizontalStrut(8));
		row.add(num);
		return holdHeight(row);
	}

	/**
	 * The sell card's answer to the flip score row: one line of plain text
	 * where a buy card carries a verdict, a number and a meter.
	 *
	 * No number, no band word and no meter, and that is the design rather
	 * than an unfinished version of one. Four 0-100 exit scores were
	 * specified and taken apart before this line survived them; Clearance's
	 * class comment records what each of them got wrong. The short version
	 * is that a 0-100 has to be calibrated against something, and "is this a
	 * good exit" depends on what you want the gold for — which the plugin
	 * does not know. The ratio underneath depends on nothing but two counts.
	 *
	 * In the card's ordinary grey on purpose. A colour here would be a
	 * verdict by other means, and it would have to come from a palette; this
	 * row ships no new colour constant and so cannot drift from the site the
	 * way the flip score's own bands already had.
	 */
	private JComponent clearanceRow(Clearance c)
	{
		final JLabel l = new JLabel(c.label());
		l.setForeground(Brand.TEXT_STRUCTURAL);
		l.setFont(l.getFont().deriveFont(Font.BOLD, 11f));
		l.setAlignmentX(0f);
		l.setToolTipText(clearanceTip(c));
		return holdHeight(l);
	}

	/** The working, in the same bordered box as every other card tooltip —
	 *  through tip(), so it inherits the 185px width cap that scoreTip()
	 *  predates and never got. */
	private String clearanceTip(Clearance c)
	{
		final String[] lines = c.tooltipLines();
		final StringBuilder b = new StringBuilder();
		b.append(lines[0]).append(' ').append(lines[1]);
		for (int i = 2; i < lines.length; i++)
		{
			b.append("<br><br>").append(lines[i]);
		}
		return tip(c.label(), b.toString());
	}

	/**
	 * Pins a row to its own preferred height, so it cannot take a share of
	 * the card's slack.
	 *
	 * The card is a vertical BoxLayout held to MIN_CARD_HEIGHT with a glue
	 * above the buttons that is meant to take every spare pixel. BoxLayout
	 * hands spare height to EVERY child whose maximum exceeds its preferred,
	 * in proportion — and that is more of them than it looks: a BorderLayout
	 * panel reports no maximum at all, a GridLayout panel likewise, and a
	 * horizontal BoxLayout row inherits the tallest maximum among its
	 * children, which for a horizontal strut or glue is unbounded. So the
	 * name row, the price pair, the money line and the button row were all
	 * quietly stretching, and Next landed somewhere different on every card
	 * of the same height.
	 */
	private static <T extends JComponent> T holdHeight(T row)
	{
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private static final int METER_H = 3;

	/** The 3px bar under the score: a faint track, filled to the score in
	 *  the band's colour. Same proportions as the site's .fc-meter. */
	private JComponent scoreMeter(TradeEngine.FlipScore s)
	{
		final Color fg = new Color(s.band.color);
		final JComponent bar = new JComponent()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				final Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				final int w = getWidth();
				final int h = getHeight();
				g2.setColor(new Color(255, 255, 255, 26));
				g2.fillRoundRect(0, 0, w, h, h, h);
				g2.setColor(fg);
				g2.fillRoundRect(0, 0, Math.round(w * s.total / 100f), h, h, h);
				g2.dispose();
			}
		};
		bar.setOpaque(false);
		bar.setAlignmentX(0f);
		bar.setPreferredSize(new Dimension(10, METER_H));
		bar.setMinimumSize(new Dimension(10, METER_H));
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, METER_H));
		bar.setToolTipText(scoreTip(s));
		return bar;
	}

	/**
	 * The score, showing its working.
	 *
	 * A definition cannot answer "why is this one 96 and that one 70", so
	 * this prints the live arithmetic instead. What it does NOT do any more
	 * is explain each term in a sentence on the same line: that ran the
	 * widest row out past seventy characters ("Net edge 26.7% +45 / 45 —
	 * maxed: anything past a 3% edge scores the same") and left the three
	 * numbers that matter unaligned in the middle of prose. They are a
	 * column now, right-aligned, with the caps stated once underneath.
	 */
	static String scoreTip(TradeEngine.FlipScore s)
	{
		final String hex = String.format("#%06X", s.band.color);
		final String edgePct = String.format(s.edgePct < 0.1 ? "%.2f" : "%.1f", s.edgePct * 100);
		final StringBuilder b = new StringBuilder("<html>");
		b.append("<font color='").append(hex).append("'><b>").append(s.band.word)
			.append(" — ").append(s.total).append(" of 100</b></font><br>");
		b.append("How good this flip looks right now, not the item.");
		b.append("<table cellpadding=0 cellspacing=0>");
		scoreTipRow(b, "Engine-cleared", "+" + Math.round(s.base), "");
		scoreTipRow(b, "Net edge " + edgePct + "%", "+" + Math.round(s.edge),
			s.edgeMaxed ? "of 45 &nbsp;maxed" : "of 45");
		scoreTipRow(b, "Liquidity " + QuantityFormatter.quantityToStackSize(s.vol) + "/day",
			"+" + Math.round(s.liq), s.liqMaxed ? "of 35 &nbsp;maxed" : "of 35");
		if (s.lowConf)
		{
			scoreTipRow(b, "Thin tape", "−" + Math.round(s.penalty), "one side is quiet");
		}
		b.append("</table>");
		for (int i = 0; i < TradeEngine.FlipScore.BANDS.length; i++)
		{
			final TradeEngine.FlipScore.Band band = TradeEngine.FlipScore.BANDS[i];
			if (i > 0)
			{
				b.append(" &nbsp;");
			}
			final String label = band.word.replace(" Flip", "") + " " + (band.min > 0 ? "" + band.min : "&lt;55");
			b.append(band == s.band ? "<b>" + label + "</b>" : label);
		}
		b.append("<br>Edge maxes at 3%, liquidity at 10M a day.");
		return b.toString();
	}

	/** One row of the score table: name, the points right-aligned in their
	 *  own column so they can be read down, then what they are out of. */
	private static void scoreTipRow(StringBuilder b, String name, String points, String outOf)
	{
		b.append("<tr><td>").append(name).append("&nbsp;&nbsp;&nbsp;</td>")
			.append("<td align=right><b>").append(points).append("</b>&nbsp;&nbsp;</td>")
			.append("<td>").append(outOf).append("</td></tr>");
	}

	/**
	 * The stat cells side by side, each at its own width.
	 *
	 * Not a GridLayout. Equal columns gave QUANTITY and CAPITAL 98px apiece,
	 * and "20,160,000 gp" does not fit 98px at 13pt bold — so the one figure
	 * this card refuses to abbreviate was being ellipsised by the layout
	 * into "20,160,000…", which is the same misread with an extra step. Each
	 * cell takes what it needs; the gap is fixed; spare width goes to the
	 * right, where nothing is.
	 */
	private JPanel statsRow(List<Card.Stat> stats)
	{
		final JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setOpaque(false);
		row.setAlignmentX(0f);
		for (int i = 0; i < stats.size(); i++)
		{
			if (i > 0)
			{
				row.add(Box.createHorizontalStrut(statGap(stats)));
			}
			final JPanel cell = statCell(stats.get(i));
			cell.setAlignmentY(0f);
			row.add(cell);
		}
		row.add(Box.createHorizontalGlue());
		return holdHeight(row);
	}

	private JPanel statCell(Card.Stat s)
	{
		final JPanel cell = new JPanel();
		cell.setLayout(new BoxLayout(cell, BoxLayout.Y_AXIS));
		cell.setOpaque(false);
		final JLabel label = new JLabel(s.label);
		label.setForeground(Brand.TEXT_STRUCTURAL);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 9f));
		label.setAlignmentX(0f);
		final JLabel value = new JLabel(s.value);
		value.setForeground(s.valueColor != null ? s.valueColor : TEXT_MAIN);
		value.setFont(value.getFont().deriveFont(Font.BOLD, 13f));
		value.setAlignmentX(0f);
		if (s.tip != null)
		{
			cell.setToolTipText(s.tip);
			label.setToolTipText(s.tip);
			value.setToolTipText(s.tip);
		}
		cell.add(label);
		cell.add(value);
		return cell;
	}

	/** The site card's Buy @ / Sell @ row: two boxes, each tinted its side's
	 *  colour at the site's own opacities (10% fill, 30% border), the label
	 *  in the colour and the number in plain text. */
	private JPanel pairRow(Card.PricePair pp)
	{
		final JPanel row = new JPanel(new GridLayout(1, 2, 8, 0));
		row.setOpaque(false);
		row.setAlignmentX(0f);
		row.add(priceBox(pp.buyLabel, pp.buy, buyColor(), pp.buyTip, pp.buyFills, pp.buyLead));
		row.add(priceBox(pp.sellLabel, pp.sell, sellColor(), pp.sellTip, pp.sellFills, pp.sellLead));
		return holdHeight(row);
	}

	private JPanel priceBox(String label, long value, Color tint, String tip, boolean fills, boolean lead)
	{
		final JPanel box = new JPanel()
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				final Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				/* Translucent rather than pre-blended against the card's
				   background, so the tint still reads right when the card
				   takes its hover colour. */
				/* The fill does NOT change on the lead box — the site's
				   .fc-price keeps background rgba(colour,.10) either way, and
				   only the border moves. A heavier fill was the first attempt
				   here and it muddied the colour that tells buy from sell. */
				g2.setColor(new Color(tint.getRed(), tint.getGreen(), tint.getBlue(), 26));
				g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 8, 8);
				/* White rim on the box that IS the instruction, which is what
				   app.css does: .fc-price.selected { border-color:#fff }. It
				   reads at a glance without reading the words, and it cannot be
				   confused with the buy/sell colours, because it is neither. */
				g2.setColor(lead ? LEAD_RIM
					: new Color(tint.getRed(), tint.getGreen(), tint.getBlue(), 77));
				g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 8, 8);
				g2.dispose();
			}
		};
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setOpaque(false);
		box.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		box.setToolTipText(tip);
		final JLabel l = new JLabel(label);
		l.setForeground(tint);
		l.setFont(l.getFont().deriveFont(Font.BOLD, 10f));
		l.setAlignmentX(0.5f);
		l.setToolTipText(tip);
		final JLabel v = new JLabel(value > 0 ? String.format("%,d", value) : "—");
		v.setForeground(value > 0 ? TEXT_MAIN : Brand.TEXT_STRUCTURAL);
		v.setFont(v.getFont().deriveFont(Font.BOLD, 14f));
		v.setAlignmentX(0.5f);
		v.setToolTipText(tip);
		box.add(l);
		box.add(v);
		if (fills && value > 0)
		{
			/* The box copies its own number for the offer screen, and the
			   chat line says to press E in the price box. It used to type
			   the number in directly — a plugin writing to the chatbox
			   without a key press, which RuneLite does not allow. */
			box.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			final MouseAdapter fill = new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (SwingUtilities.isLeftMouseButton(e))
					{
						actions.fillGePrice(value);
					}
				}
			};
			box.addMouseListener(fill);
			/* Swing does not bubble mouse events, so the two labels filling
			   the box would otherwise be dead spots in the middle of it. */
			l.addMouseListener(fill);
			v.addMouseListener(fill);
		}
		return box;
	}

	/** The right-click menu on a chart button. Same shape as the GE slot's
	 *  own popup (see GeSlotsPanel), so the two behave alike. */
	/** The menu entry that changes the pocketge.com page already open —
	 *  the chart button's, the watchlist's and Find Opportunities' alike. */
	static final String SEND_TO_TAB = "Send to my open PocketGE tab";
	static final String SEND_TO_TAB_TIP = "<html>Change the pocketge.com page you already have open, instead of adding"
		+ "<br>another tab. It changes in the background — browsers will not let a page"
		+ "<br>raise its own window — so alt-tab to it afterwards.</html>";

	private JPopupMenu chartPopup(String itemName)
	{
		final JPopupMenu menu = new JPopupMenu();
		final JMenuItem sendToTab = new JMenuItem(SEND_TO_TAB);
		sendToTab.setToolTipText(SEND_TO_TAB_TIP);
		sendToTab.addActionListener(e -> actions.sendChartToOpenTab(itemName));
		menu.add(sendToTab);
		return menu;
	}

	private static Icon buildChartIcon(float scale)
	{
		final int w = Math.round(13 * scale);
		final int h = Math.round(11 * scale);
		BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		/* Not GOLD. Gold is the BUY colour on every card in this panel, and
		   this button opens a chart — it does not propose a trade, and it
		   sits on sell cards as often as buy ones. The panel's plain text
		   colour says "a tool" and claims nothing about the side. */
		g.setColor(TEXT_MAIN);
		g.setStroke(new BasicStroke(1.6f * scale, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		int[] xs = scalePoints(new int[]{0, 4, 7, 11}, scale);
		int[] ys = scalePoints(new int[]{9, 5, 7, 1}, scale);
		g.drawPolyline(xs, ys, 4);
		g.drawLine(xs[3], ys[3], Math.round(8 * scale), ys[3]); // arrowhead
		g.drawLine(xs[3], ys[3], xs[3], Math.round(4 * scale));
		g.dispose();
		return new ImageIcon(img);
	}

	/** Three connected nodes — the standard "share" glyph (same shape as the
	 *  website's Share button icon), drawn rather than an emoji for the same
	 *  cross-JRE-font-fallback reason as the chart icon. */
	/** A right chevron, drawn. The U+203A glyph it replaces rendered as a
	 *  stray comma in the client — the same cross-JRE font-fallback problem
	 *  the chart and share icons are drawn to avoid. */
	/** The Next chevron, mirrored. Drawn rather than flipped at paint time so
	 *  the two are pixel-identical apart from direction. */
	/**
	 * One chevron, pointing either way, in whatever colour the state wants.
	 *
	 * Drawn rather than set as text for the reason the whole icon set is
	 * drawn: the ‹ and › the website uses are U+2039/U+203A, and U+203A
	 * already rendered as a stray comma in this client once. A glyph is a
	 * request that the JRE find a font containing it; a polyline is not.
	 *
	 * 9x13 rather than the 7x10 these were, because the button around them
	 * grew to match the site's 24px target and a chevron that small inside
	 * it read as a speck.
	 */
	private static Icon buildChevron(boolean back, Color fg)
	{
		final int w = 9, h = 13;
		final BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(fg);
		g.setStroke(new BasicStroke(1.9f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		final int[] xs = back ? new int[]{6, 2, 6} : new int[]{2, 6, 2};
		g.drawPolyline(xs, new int[]{1, h / 2, h - 2}, 3);
		g.dispose();
		return new ImageIcon(img);
	}

	private static Icon buildStarIcon(boolean filled)
	{
		final int size = 13;
		final BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		final int[] xs = new int[10];
		final int[] ys = new int[10];
		final double cx = size / 2.0, cy = size / 2.0;
		for (int i = 0; i < 10; i++)
		{
			final double r = (i % 2 == 0) ? size / 2.0 - 0.5 : size / 4.6;
			final double a = -Math.PI / 2 + i * Math.PI / 5;
			xs[i] = (int) Math.round(cx + r * Math.cos(a));
			ys[i] = (int) Math.round(cy + r * Math.sin(a));
		}
		g.setColor(GOLD);
		if (filled)
		{
			g.fillPolygon(xs, ys, 10);
		}
		else
		{
			g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawPolygon(xs, ys, 10);
		}
		g.dispose();
		return new ImageIcon(img);
	}

	private static Icon buildPauseIcon()
	{
		final int w = 11, h = 11;
		final BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		g.setColor(TEXT_MAIN);
		g.fillRect(1, 0, 3, h);
		g.fillRect(7, 0, 3, h);
		g.dispose();
		return new ImageIcon(img);
	}

	/** An open hand-ish "keep this" mark: a filled square in a bracket. Kept
	 *  deliberately unlike the block glyph so the two aren't confused at a
	 *  glance — one is temporary, the other permanent. */
	private static Icon buildHoldIcon()
	{
		final int size = 12;
		final BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		/* Not SELL_COLOR. Hold is a thing you do to the CARD — keep this one
		   on screen instead of letting it move on — and it sits on buy cards
		   as often as sell ones. Wearing the sell colour made it look like it
		   was recommending a side, which is the same fault the pause button
		   and the chart glyph had. Hue means buy-or-sell in this panel now;
		   a tool takes the plain text colour. */
		g.setColor(TEXT_MAIN);
		g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawLine(2, 1, 2, size - 2);
		g.drawLine(size - 3, 1, size - 3, size - 2);
		g.fillRect(4, 4, size - 8, size - 8);
		g.dispose();
		return new ImageIcon(img);
	}


	/** Bigger and squarer than smallBtn, with a painted background so the
	 *  icon reads as a real control — the old text buttons were too cramped
	 *  to identify at a glance in a 225px column. */
	private JButton bigIconBtn(Icon icon, String tip, java.awt.event.ActionListener a)
	{
		final JButton b = new JButton(icon);
		b.setToolTipText(tip);
		b.addActionListener(a);
		return styleAsControl(b);
	}

	/** The controls-row look, applied to buttons built elsewhere (the share
	 *  button, which needs its own click behaviour) as well as to
	 *  {@link #bigIconBtn}'s. */
	private static JButton styleAsControl(JButton b)
	{
		b.setFocusPainted(false);
		b.setOpaque(true);
		b.setContentAreaFilled(true);
		b.setBorderPainted(true);
		b.setBackground(Brand.BG_INPUT);
		b.setBorder(BorderFactory.createLineBorder(Brand.BORDER_LIGHT, 1));
		sizeExactly(b, CONTROL_W, CONTROL_H);
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		return b;
	}

	/** Pins a button to one exact size in all three dimensions Swing asks
	 *  about. setPreferredSize alone is not enough inside a BoxLayout row:
	 *  JComponent.getMaximumSize falls through to the UI's own computed
	 *  preferred size when no maximum was set, so a button that "is" 34px
	 *  wide will still be stretched by the layout — and the controls row has
	 *  no spare width to give away. */
	private static void sizeExactly(JButton b, int w, int h)
	{
		final Dimension d = new Dimension(w, h);
		b.setPreferredSize(d);
		b.setMinimumSize(d);
		b.setMaximumSize(d);
	}

	private static int[] scalePoints(int[] points, float scale)
	{
		int[] out = new int[points.length];
		for (int i = 0; i < points.length; i++)
		{
			out[i] = Math.round(points[i] * scale);
		}
		return out;
	}

	private JPanel chip(String name)
	{
		JPanel c = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 1));
		c.setBackground(Brand.BORDER_LIGHT);
		c.setBorder(BorderFactory.createEmptyBorder(1, 6, 1, 4));
		JLabel n = new JLabel(name);
		n.setForeground(Color.WHITE);
		n.setFont(n.getFont().deriveFont(12f));
		JButton x = new JButton("×");
		x.setToolTipText("Remove " + name + " from the never-recommend list");
		x.setFocusPainted(false);
		x.setMargin(new Insets(0, 4, 0, 4));
		x.setForeground(Brand.TEXT_STRUCTURAL);
		x.addActionListener(e -> actions.unblock(name));
		c.add(n);
		c.add(x);
		return c;
	}


	private Color accent(Advisor.Suggestion.Type t)
	{
		switch (t)
		{
			case BUY: return buyColor();
			case SELL: return sellColor();
			/* An adjust is neither: it is a state of an offer already out
			   there, so it keeps its own orange whatever the pair is. */
			default: return ADJUST;
		}
	}

	/**
	 * The two colours that mean buy and sell right now.
	 *
	 * Read per paint rather than cached, because the setting can change under
	 * a card that is already on screen and the panel is rebuilt far more often
	 * than anyone can click a menu. Falls back to the default pair when no
	 * settings have arrived yet, which is every paint before the first
	 * refresh.
	 *
	 * The buy side used to be GOLD in two of these places and BUY_COLOR in the
	 * third — two near-identical golds, which nobody could see but which meant
	 * there was no single "buy colour" to change. Now there is.
	 */
	private Color buyColor()
	{
		return settings != null && settings.theme != null ? settings.theme.buy() : BUY_COLOR;
	}

	private Color sellColor()
	{
		return settings != null && settings.theme != null ? settings.theme.sell() : SELL_COLOR;
	}

}

package com.pocketge.tracker;

/**
 * A simplified proxy of pocketge.com's Analyst Rating gauge (0-100, Strong
 * Sell -> Strong Buy), scoped to what the plugin can cheaply fetch: the
 * live quote plus a 24h average (one extra whole-market API call, same
 * shape as /latest — no per-item history calls). The website's real rating
 * scores against a full recency-weighted price series; this is intentionally
 * coarser — "how does right now compare to today's typical price" — and is
 * documented as such rather than pretending full parity.
 */
public final class AnalystRating
{
	private AnalystRating() {}

	public static class Average
	{
		public long avgHighPrice;
		public long avgLowPrice;
		// 24h print volumes on each side — not used by grade() itself, but
		// the same /24h response carries them and the Find Opportunities
		// scanner needs them (a real move needs volume on both sides, not
		// one whale's single trade skewing the average).
		public long highPriceVolume;
		public long lowPriceVolume;
	}

	public enum Label
	{
		STRONG_SELL("Strong Sell"),
		SELL("Sell"),
		HOLD("Hold"),
		BUY("Buy"),
		STRONG_BUY("Strong Buy");

		public final String text;
		Label(String text) { this.text = text; }
	}

	public static class Grade
	{
		public int score;   // 0 (strong sell) .. 100 (strong buy)
		public Label label;
	}

	/** How far the deviation has to swing (as a fraction of the 24h typical
	 *  price) to fully saturate the 0-100 scale. 20% below typical -> ~100,
	 *  20% above -> ~0, matched to the site's rough sensitivity. */
	private static final double SATURATION = 0.20;

	public static Grade grade(Advisor.Quote live, Average avg)
	{
		Grade g = new Grade();
		if (live == null || avg == null || live.high <= 0 || live.low <= 0
			|| avg.avgHighPrice <= 0 || avg.avgLowPrice <= 0)
		{
			g.score = 50;
			g.label = Label.HOLD;
			return g;
		}
		double liveMid = (live.high + live.low) / 2.0;
		double typicalMid = (avg.avgHighPrice + avg.avgLowPrice) / 2.0;
		double deviation = (liveMid - typicalMid) / typicalMid; // negative = below typical = cheap = buy-leaning

		double raw = 50.0 - (deviation / SATURATION) * 50.0;
		g.score = (int) Math.round(Math.max(0, Math.min(100, raw)));
		g.label = labelFor(g.score);
		return g;
	}

	private static Label labelFor(int score)
	{
		if (score >= 80) return Label.STRONG_BUY;
		if (score >= 60) return Label.BUY;
		if (score > 40) return Label.HOLD;
		if (score > 20) return Label.SELL;
		return Label.STRONG_SELL;
	}
}

