/**
 * Marks the stacks in your bank that are worth SELLING right now — one
 * colour, one meaning.
 *
 * It used to draw three: gold for "buy more of this", green for "sell
 * this", and dashed teal for "you told me to ignore this". None of them
 * was labelled anywhere, and the honest report from actually using it was
 * that it was a bunch of colours that didn't mean anything. Two of the
 * three earned that:
 *
 *  - Gold answered a question you weren't asking. You are looking at what
 *    you already own; telling you to go buy more of it belongs in Find
 *    Opportunities, not on a bank slot.
 *  - Teal only ever appeared on items you had personally muted, so it told
 *    you something you already knew.
 *
 * Green answers a question nothing else can: walk into a bank of three
 * hundred stacks, and which of them should you be selling today? That is
 * worth a colour. So it is the only one left, it is on by default, and
 * hovering a marked slot says why in words — a legend you have to remember
 * is a legend that has already failed.
 *
 * Covers bank, inventory and equipment: RuneLite calls
 * {@link #renderItemOverlay} for every visible item container widget.
 */
@Singleton
public class BankHighlightOverlay extends WidgetItemOverlay
{
	/*
	 * Both marks are the SELL colour; the one the sidebar is talking about is
	 * picked out in white instead of a different hue.
	 *
	 * Two earlier tries were wrong in the same way. First a hardcoded gold
	 * and 0x1FB85C — the PROFIT green, borrowed as "the money signal", which
	 * made a border claim something about a stack the plugin had not valued
	 * that way, and neither colour moved when the theme did. Then the theme's
	 * buy/sell pair, which fixed the drift but kept the deeper problem: every
	 * marked stack in a bank is something to SELL, so painting one of them in
	 * the BUY colour said the opposite of what the square meant.
	 *
	 * White is the card's own word for "this is the one you are acting on" —
	 * LEAD_RIM, the rim it puts on whichever price box you are about to type.
	 * Reusing it here means the bank and the sidebar mark the live suggestion
	 * the same way, and the hue is left free to mean buy-or-sell everywhere.
	 *
	 * SELL_COLOR is static because drawRing is, and drawRing is shared with
	 * BankLegendOverlay — so the legend's swatches cannot drift from the
	 * squares they explain. Volatile because the client thread paints it and
	 * the Swing thread sets it.
	 */
	/* Package-private, read by the settings popup's colour key, so the key
	   is painted with the colour the bank actually wears. */
	static final Color RECOMMENDED_COLOR = new Color(0xF2, 0xF2, 0xF2);
	private static volatile Color SELL_COLOR = new Color(0x29, 0xB6, 0xF6);

	/** Called whenever the colour theme is read or changed — see
	 *  PocketGeTrackerPlugin.pushBankTheme. */
	/** The worth-selling outline as the current theme paints it. */
	static Color sellColor()
	{
		return SELL_COLOR;
	}

	public static void setTheme(Color sellable)
	{
		if (sellable != null)
		{
			SELL_COLOR = sellable;
		}
	}

	private static final int MARK_SIZE = 14;
	/**
	 * How opaque the TOP edge of the ring is, out of 255.
	 *
	 * The game prints the stack count in the top-left of the slot, in a small
	 * font whose glyphs start at the very first row of pixels — so a solid
	 * 2px gold line laid along the top of the slot sits on the tops of the
	 * digits. That is exactly where a digit's identity lives: shave three
	 * pixels off the top of "42,027" and the 4 could be a 1 and the 7 could
	 * be a 2. The report was a marked stack whose quantity could not be read.
	 *
	 * The other three sides stay solid. Only this one has anything behind it
	 * worth reading, and at this weight the box still closes — the two top
	 * corners are where the eye finishes the rectangle, and the left and
	 * right edges draw those at full strength.
	 */
	static final int TOP_EDGE_ALPHA = 110;
	/**
	 * How far down the slot the stack count reaches, in pixels.
	 *
	 * The label is not only ON the top edge — it starts at the slot's left
	 * edge too, so the ring's left side ran through the first digit. Fading
	 * the whole left edge would have been the wrong trade (a box that gives
	 * way on every side is not a box), so only the top of it does: this is
	 * the band the digits occupy, and below it the edge is full weight.
	 */
	static final int QTY_BAND_H = 10;

	/**
	 * The ring, drawn INSIDE the slot, with a see-through top edge.
	 *
	 * Static and free of the client so it can be rendered and measured on its
	 * own — see the SlotMark harness, which reads the pixels back over a
	 * mock quantity label rather than trusting that this looks right.
	 */
	static void drawRing(Graphics2D g, Rectangle bounds, boolean isRecommended)
	{
		final Color base = isRecommended ? RECOMMENDED_COLOR : SELL_COLOR;
		final Color faint = new Color(base.getRed(), base.getGreen(), base.getBlue(), TOP_EDGE_ALPHA);
		final int w = isRecommended ? 2 : 1;
		final int inset = isRecommended ? 1 : 0;
		final int x0 = bounds.x + inset;
		final int y0 = bounds.y + inset;
		final int x1 = bounds.x + bounds.width - 1 - inset;
		final int y1 = bounds.y + bounds.height - 1 - inset;
		/* Never more than a third of the slot, however tall the label is
		   reckoned to be — past that the left edge stops being an edge. */
		final int band = Math.min(QTY_BAND_H, bounds.height / 3);

		/* Right and bottom are solid, whole. Nothing is drawn behind them. */
		g.setStroke(new BasicStroke(w));
		g.setColor(base);
		g.drawLine(x1, y0, x1, y1); // right
		g.drawLine(x0, y1, x1, y1); // bottom
		/* The left edge only gives way where the label actually is, which is
		   its top corner. Below the band it is a full-weight edge like any
		   other, so three and a half of the four sides still carry the box. */
		g.drawLine(x0, y0 + band, x0, y1);

		g.setStroke(new BasicStroke(1f));
		g.setColor(faint);
		g.drawLine(x0, y0, x0, y0 + band);
		/* The top edge last: it crosses the left and right edges at their
		   corners, and at full weight it would blunt them. */
		g.drawLine(x0, y0, x1, y0);
	}

	private volatile Map<Integer, Advisor.Suggestion> suggestionsByItem = Map.of();
	/** Mirrors PocketGeTrackerConfig.bankHighlights. Checked per slot rather
	 *  than by adding/removing the overlay, so a toggle can never race a
	 *  half-drawn frame. */
	private volatile boolean enabled = true;
	/** Mirrors PocketGeTrackerConfig.holdingTips — the hover over any stack
	 *  the plugin watched you buy, marked or not. */
	private volatile boolean holdingTips = true;
	/** itemId -> {tracked units, their cost, the sell card's price}; see
	 *  PocketGeTrackerPlugin.holdingTipsFor. */
	private volatile Map<Integer, long[]> holdings = Map.of();
	/** See {@link #setRecommended}. Volatile: written on the Swing EDT when
	 *  the card changes, read on the client thread every frame. */
	private volatile Integer recommendedItemId;
	private final BufferedImage markIcon;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Client client;

	@Inject
	private TooltipManager tooltipManager;

	/** Noted to unnoted, for a test; null means ItemManager's. See
	 *  {@link #canonical}. */
	java.util.function.IntUnaryOperator canonicalizer;

	/**
	 * Guice builds this overlay. The annotation has to sit on the constructor
	 * itself — it is private, so nothing else can — and a constant declared
	 * between the two silently steals it, which is how the whole plugin
	 * vanished from the sidebar once already. See InjectionWiringTest.
	 *
	 * showOnInventory() already covers the Exchange's own inventory panel
	 * (467, GE_OFFERS_SIDE). It was registered here a second time, for a
	 * report of an unmarked stack with the Exchange open, and RuneLite keeps
	 * both registrations — so everything drew twice there and every hover
	 * stacked two identical tooltips. That stack was 18,608 noted diamonds,
	 * and the real reason was the note's id: see {@link #canonical}.
	 */
	@Inject
	private BankHighlightOverlay()
	{
		showOnInventory();
		showOnBank();
		showOnEquipment();
		markIcon = ImageUtil.resizeImage(ImageUtil.loadImageResource(getClass(), "icon.png"), MARK_SIZE, MARK_SIZE);
	}

	/** Called from the plugin whenever suggestions are recomputed. Keyed by
	 *  item id so a lookup per rendered slot is O(1). May contain BUY
	 *  entries; this overlay ignores them (see the class comment). */
	public void setSuggestions(Map<Integer, Advisor.Suggestion> byItem)
	{
		this.suggestionsByItem = byItem != null ? byItem : Map.of();
	}

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	public void setHoldingTips(boolean on)
	{
		this.holdingTips = on;
	}

	public void setHoldings(Map<Integer, long[]> byItem)
	{
		this.holdings = byItem != null ? byItem : Map.of();
	}

	/** itemId -> the batches behind the stack, {qty, spent} pairs oldest
	 *  first — see FlipTracker.heldBatches. */
	private volatile Map<Integer, long[]> batches = Map.of();

	public void setBatches(Map<Integer, long[]> byItem)
	{
		this.batches = byItem != null ? byItem : Map.of();
	}

	/** Mirrors PocketGeTrackerConfig.alchProfit. */
	private volatile boolean alchOn = true;
	/** itemId -> its high alchemy value, for every item the plugin has
	 *  looked one up for; the hover reads the stacks in {@link #holdings}. */
	private volatile Map<Integer, Integer> alchValues = Map.of();
	/** A nature rune's insta-buy; 0 when unknown. */
	private volatile long naturePrice;

	public void setAlchOn(boolean on)
	{
		this.alchOn = on;
	}

	public void setAlch(Map<Integer, Integer> valueByItem, long naturePrice)
	{
		this.alchValues = valueByItem != null ? valueByItem : Map.of();
		this.naturePrice = naturePrice;
	}

	/** The alch line for a stack, or "" — see {@link #alchText}. */
	private String alchFor(int itemId, long[] h)
	{
		final Integer value = alchValues.get(itemId);
		return alchOn && h != null && value != null ? alchText(itemId, h, value, naturePrice) : "";
	}

	/**
	 * What one high alchemy cast on this stack makes, from its {tracked
	 * units, their cost, sell price}: the alch value less a nature rune and
	 * less what one cost — paid, when the plugin saw the buy; otherwise the
	 * price it sells at, since alching it gives that sale up. A second line
	 * when alching beats selling, after the sale's tax.
	 *
	 * Only when a cast makes something: "have it only show a high alch profit
	 * if there is one, dont have it say negative". For most things it does
	 * not, and a loss on every hover is a choice nobody was making. "" then,
	 * and when the item does not alch or there is no price to say it
	 * against.
	 */
	static String alchText(int itemId, long[] h, long alchValue, long naturePrice)
	{
		final boolean paid = h[0] > 0 && h[1] > 0;
		final long cost = paid ? Math.round(h[1] / (double) h[0]) : h[2];
		if (!HighAlch.known(alchValue, naturePrice, cost))
		{
			return "";
		}
		final long each = HighAlch.perCast(alchValue, naturePrice, cost);
		if (each <= 0)
		{
			return "";
		}
		final StringBuilder sb = new StringBuilder(TipStyle.BREAK)
			.append(TipStyle.state(TipStyle.GOOD, HighAlch.signed(each) + " gp ea to high alch"))
			.append(TipStyle.muted(" (" + String.format("%,d", alchValue) + " - " + String.format("%,d", naturePrice)
				+ " rune - " + String.format("%,d", cost) + (paid ? " paid)" : " price)")));
		final long sellNet = h[2] - FlipTracker.taxPerItem(h[2], itemId);
		final long alchNet = alchValue - naturePrice;
		if (h[2] > 0 && alchNet > sellNet)
		{
			sb.append(TipStyle.BREAK).append(TipStyle.state(TipStyle.GOOD,
				"Alching beats selling by " + String.format("%,d", alchNet - sellNet) + " gp ea"));
		}
		return sb.toString();
	}

	/**
	 * The batches a stack was bought in, when there is more than one: "yes
	 * add that to the hover", after "it cant remember 2 costs paid?". Oldest
	 * to newest, as bought; the newest is what a sale uses first, so the
	 * line says so. Three at most, the newest, with the count of any older.
	 * "" for one batch or none — "Paid N gp each" already says it.
	 */
	static String batchesText(long[] b)
	{
		if (b == null || b.length < 4)
		{
			return "";
		}
		final int n = b.length / 2;
		final int from = Math.max(0, n - 3);
		final StringBuilder sb = new StringBuilder();
		if (from > 0)
		{
			sb.append("+").append(from).append(" older \u00b7 ");
		}
		for (int i = from; i < n; i++)
		{
			final long q = b[2 * i];
			if (i > from)
			{
				sb.append(" \u00b7 ");
			}
			sb.append(QuantityFormatter.quantityToStackSize(q)).append(" @ ")
				.append(String.format("%,d", q > 0 ? Math.round(b[2 * i + 1] / (double) q) : 0));
		}
		return TipStyle.BREAK + TipStyle.muted("Bought in batches, newest sells first:")
			+ TipStyle.BREAK + TipStyle.muted(sb.toString());
	}

	/**
	 * The hover over a stack that is not marked: what you paid, what it
	 * sells for, and what that comes to — "i just bought these, hovering over
	 * them should show how much profit available or losing". A stack the
	 * plugin has no cost for says what it sells for and no more: "why no
	 * hover detail on diamonds?" A marked stack has its own tooltip, which
	 * says the same and more.
	 */
	private void holdingTip(int itemId, WidgetItem widgetItem)
	{
		if (!holdingTips)
		{
			return;
		}
		final long[] h = holdings.get(itemId);
		final Rectangle bounds = widgetItem.getCanvasBounds();
		if (h == null || bounds == null || widgetItem.getQuantity() <= 0)
		{
			return;
		}
		final Point mouse = client.getMouseCanvasPosition();
		if (mouse != null && bounds.contains(mouse.getX(), mouse.getY()))
		{
			tooltipManager.add(TipStyle.tooltip(hoverText(itemId, widgetItem.getQuantity(), h)
				+ alchFor(itemId, h) + batchesText(batches.get(itemId))));
		}
	}

	/** The hover for one stack, from its {tracked units, their cost, sell
	 *  price}: the profit when there is a cost, what it fetches when not. */
	static String hoverText(int itemId, int stackQty, long[] h)
	{
		return h[0] > 0 && h[1] > 0 ? holdingText(itemId, stackQty, h[0], h[1], h[2]) : valueText(itemId, stackQty, h[2]);
	}

	/**
	 * A stack with no buy on record: what it fetches after tax, and the price
	 * that comes from. Never a profit — a cost of nothing is not the same as
	 * a cost nobody saw — and the figure in parchment, not the profit green,
	 * for the reason tooltipText gives: a number in that colour reads as
	 * profit however it is worded.
	 */
	static String valueText(int itemId, int stackQty, long sellPrice)
	{
		final long net = sellPrice - FlipTracker.taxPerItem(sellPrice, itemId);
		return "</col>" + TipStyle.figure(QuantityFormatter.quantityToStackSize(net * stackQty) + " gp")
			+ TipStyle.muted(" after tax")
			+ TipStyle.BREAK + TipStyle.muted("Sells for " + String.format("%,d", sellPrice)
				+ " (" + String.format("%,d", net) + " after tax)")
			+ TipStyle.BREAK + TipStyle.muted("No buy on record, so no profit to show");
	}

	/** What selling {@code stackQty} at {@code sellPrice} makes after tax on
	 *  the part of it the plugin has a cost for: the hover's headline, and
	 *  what decides whether a stack is marked worth selling at all. */
	static long holdingProfit(int itemId, long stackQty, long trackedQty, long trackedSpent, long sellPrice)
	{
		final long priced = Math.min(stackQty, trackedQty);
		final long cost = (long) Math.ceil(trackedSpent * (priced / (double) trackedQty));
		final long net = sellPrice - FlipTracker.taxPerItem(sellPrice, itemId);
		return priced * net - cost;
	}

	/** The hover's text for {@code stackQty} of an item, {@code trackedQty}
	 *  of which cost {@code trackedSpent}, selling at {@code sellPrice}. */
	static String holdingText(int itemId, int stackQty, long trackedQty, long trackedSpent, long sellPrice)
	{
		final long priced = Math.min(stackQty, trackedQty);
		final long paidEach = Math.round(trackedSpent / (double) trackedQty);
		final long net = sellPrice - FlipTracker.taxPerItem(sellPrice, itemId);
		final long profit = holdingProfit(itemId, stackQty, trackedQty, trackedSpent, sellPrice);
		final StringBuilder sb = new StringBuilder("</col>");
		sb.append(profit >= 0
			? TipStyle.state(TipStyle.GOOD, "+" + QuantityFormatter.quantityToStackSize(profit) + " gp profit available")
			: TipStyle.state(TipStyle.BAD, "-" + QuantityFormatter.quantityToStackSize(-profit) + " gp if you sell"));
		sb.append(TipStyle.BREAK).append(TipStyle.muted("Paid " + String.format("%,d", paidEach) + " gp each"
			+ (priced < stackQty ? " on " + String.format("%,d", priced) + " of " + String.format("%,d", stackQty) : "")));
		sb.append(TipStyle.BREAK).append(TipStyle.muted("Sells for " + String.format("%,d", sellPrice)
			+ " (" + String.format("%,d", net) + " after tax)"));
		return sb.toString();
	}

	/* Read by BankLegendOverlay, so the key and the marks come from one
	   source. A legend that disagrees with what is on the slots is worse
	   than no legend at all. */

	boolean isEnabled()
	{
		return enabled;
	}

	/** Whether a gold mark is on screen — the one stack the card names. */
	boolean hasRecommended()
	{
		return recommendedItemId != null;
	}

	/** Whether any green ring is on screen. Mirrors the gate in
	 *  renderItemOverlay: the map may also carry BUY entries, and sells at a
	 *  loss, neither of which this overlay marks. */
	boolean hasSellable()
	{
		for (Advisor.Suggestion s : suggestionsByItem.values())
		{
			if (marks(s))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether a suggestion earns the "worth selling" mark: a sell, and not
	 * one that loses money against what you paid.
	 *
	 * The ranked sell list keeps losing stacks — the card for one says "At a
	 * loss — Hold to keep it" — and the mark outlined them in the sell colour
	 * all the same, hovering "Also worth selling" over 11,000 bolt tips bought
	 * at 427 and fetching 425: "should say loss not also worth selling". A
	 * stack like that gets the plain hover instead, which leads with the loss.
	 */
	static boolean marks(Advisor.Suggestion s)
	{
		return s != null && s.type == Advisor.Suggestion.Type.SELL && !atALoss(s);
	}

	/** A sell priced against a tracked buy, coming out below it. */
	static boolean atALoss(Advisor.Suggestion s)
	{
		return s != null && s.hasTrackedCost && s.unitCost > 0 && s.trackedQty > 0 && s.expectedProfit < 0;
	}

	/** The item the recommendation card is showing, or null. Marked apart
	 *  from the rest so there is one thing to click, not a field of them. */
	public void setRecommended(Integer itemId)
	{
		this.recommendedItemId = itemId;
	}

	/**
	 * The id every map here is keyed by, for the id a slot is drawn with.
	 *
	 * A slot is drawn with the stack's own id, and a noted stack has the
	 * note's: 7,537 redwood logs in the inventory are one slot of 19670,
	 * while the suggestions, the recommended item and what you paid are all
	 * kept under 19669. So a noted stack — which is how anything that does
	 * not stack sits in an inventory in bulk — had no mark and no hover, and
	 * "i just bought these" got nothing at all.
	 */
	private int canonical(int itemId)
	{
		final java.util.function.IntUnaryOperator c = canonicalizer;
		if (c != null)
		{
			return c.applyAsInt(itemId);
		}
		/* Null only in a test that builds this bare: Guice always injects it. */
		final ItemManager items = itemManager;
		return items != null ? items.canonicalize(itemId) : itemId;
	}

	/** The trade screen's group, which shows the other player's offer as
	 *  well as yours. */
	private static final int TRADE_MAIN_GROUP = 335;

	@Override
	public void renderItemOverlay(Graphics2D graphics, int slotItemId, WidgetItem widgetItem)
	{
		/* An empty bank placeholder. canonical() maps a placeholder to its
		   item as well as a note, and the card's item would otherwise be
		   ringed twice: the stack you hold, and the grey slot it left. */
		if (widgetItem.getQuantity() <= 0)
		{
			return;
		}
		/* The trade screen: half of it is the other player's offer, and your
		   marks and your cost have nothing to say about their stack. */
		final net.runelite.api.widgets.Widget w = widgetItem.getWidget();
		if (w != null && w.getId() >>> 16 == TRADE_MAIN_GROUP)
		{
			return;
		}
		final int itemId = canonical(slotItemId);
		if (!enabled)
		{
			holdingTip(itemId, widgetItem);
			return;
		}
		final Integer rec = recommendedItemId;
		final boolean isRecommended = rec != null && rec == itemId;
		final Advisor.Suggestion s = suggestionsByItem.get(itemId);
		/*
		 * The card's own item is marked whatever the suggestion map says.
		 *
		 * Both gates below used to apply to it too, and that is why a card
		 * reading "Sell 17,303 Uncut ruby" could leave every ruby in the
		 * inventory unmarked. The map is rebuilt from Advisor's SELL
		 * suggestions each cycle, and the card is not always one of those —
		 * it can come from the plan's own sell candidate, from a stack whose
		 * suggestion has aged out, or from a cycle that has not landed yet.
		 * So the plugin was telling you to sell something and then declining
		 * to point at it, which is the one job the mark has.
		 *
		 * isMerchantStack is skipped for the same reason. It exists to keep
		 * the plain outline off single unstackable items in a bank full of
		 * them — a sensible filter for "everything worth selling", and not a
		 * second opinion the card needs. The card already decided.
		 */
		if (!isRecommended && !marks(s))
		{
			holdingTip(itemId, widgetItem);
			return;
		}
		final Rectangle bounds = widgetItem.getCanvasBounds();
		/* The slot's own id here: whether it is a note is the question. */
		if (bounds == null || (!isRecommended && !isMerchantStack(slotItemId, widgetItem)))
		{
			holdingTip(itemId, widgetItem);
			return;
		}

		/*
		 * ONE ring, drawn INSIDE the slot.
		 *
		 * A stroke is centred on the path it follows, so 2.5px laid straight
		 * along `bounds` put half of itself outside the slot — and a fat soft
		 * line sitting right against the bank's own slot border reads as two
		 * borders, not one. Adding a second ring 3px further in made it three.
		 * On a stack of uncut diamonds, which are small, pale and numerous,
		 * the result was a slot you could not read the contents of.
		 *
		 * Inset by half the stroke so the ring lands wholly within the slot
		 * and the bank's own edge stays the only line on the boundary.
		 */
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		drawRing(graphics, bounds, isRecommended);
		if (isRecommended)
		{
			/* The mark is what separates "the one on your panel" from the rest
			   now that the second ring is gone — and it is EXCLUSIVE to it.
			   It used to be stamped on every marked stack, so a bank with nine
			   sellable stacks wore nine icons over nine sprites; the thing
			   meant to pick one slot out was on all of them. Bottom-right, away
			   from the game's own quantity label in the top-left. */
			graphics.drawImage(markIcon, bounds.x + bounds.width - MARK_SIZE,
				bounds.y + bounds.height - MARK_SIZE, null);
		}

		/* Say what the border means, on the slot itself. A colour you have
		   to look up somewhere else is a colour that gets ignored, which is
		   exactly what happened to the three this replaced. */
		final Point mouse = client.getMouseCanvasPosition();
		if (mouse != null && bounds.contains(mouse.getX(), mouse.getY()))
		{
			/* s can be null on the recommended stack now — see the gate above,
			   where the card outranks the suggestion map. The headline still
			   stands on its own; the money line simply has nothing to add. */
			/* Only a SELL describes the stack. The card's own stack can have
			   a BUY in the map instead — buildBuys never excludes what you
			   hold — and its quantity and price are a purchase, not this. */
			final Advisor.Suggestion sell = s != null && s.type == Advisor.Suggestion.Type.SELL ? s : null;
			String text = tooltipText(sell, isRecommended);
			/* The card's stack with no sell behind it — a sell card paged
			   to, at a loss, is rarely in the map — still has its cost, and
			   the plain hover's lines say what selling now comes to. */
			final long[] h = holdings.get(itemId);
			if (sell == null && holdingTips && h != null)
			{
				text += TipStyle.BREAK + hoverText(itemId, widgetItem.getQuantity(), h).replaceFirst("^</col>", "");
			}
			text += alchFor(itemId, h);
			if (holdingTips)
			{
				text += batchesText(batches.get(itemId));
			}
			tooltipManager.add(TipStyle.tooltip(text));
		}
	}

	/**
	 * The hover text for a marked stack.
	 *
	 * Four lines, in the same order and the same colours whichever mark you
	 * are hovering, because the two used to be laid out differently — the
	 * recommended stack led with a header and the other trailed one, so the
	 * same facts appeared in different places depending on which square you
	 * were over.
	 *
	 *   1  which mark this is, in the legend's own words
	 *   2  what the stack fetches, leading, in profit green
	 *   3  how that number is arrived at — count times unit price
	 *   4  why this moment, when there is a real answer
	 *
	 * Line 2 leads with the FIGURE rather than "Worth selling: 29.6M". The
	 * verb is already on the square you are hovering, and burying the one
	 * number you came for behind two words is what made these hard to read
	 * at a glance.
	 *
	 * Line 3 is new. The tooltip claimed "29.6M gp" and "1,635 gp each" and
	 * left out the count between them, so the one figure that matters could
	 * not be checked against anything.
	 *
	 * RuneLite tooltips are game-markup text, not Swing: the colours are
	 * &lt;col&gt; tags and the breaks are &lt;/br&gt;. A properly drawn panel
	 * would mean a Tooltip(LayoutableRenderableEntity) and a PanelComponent,
	 * neither of which this repo can compile against — see tools/typecheck,
	 * where the stubs are hand-written and have shipped a broken client once
	 * already. Not worth that risk for a border.
	 */
	private static String tooltipText(Advisor.Suggestion s, boolean isRecommended)
	{
		final StringBuilder sb = new StringBuilder();
		/* The legend's wording, verbatim. The bank draws a legend naming
		   these two marks; a tooltip that called them something else would
		   make the player match up two vocabularies for one colour. */
		/* Each header in the colour of the square it is describing, so the
		   text and the border you are hovering cannot disagree — and so both
		   follow the theme, which is the whole point of the marks not being
		   hardcoded any more. */
		sb.append("</col>").append(TipStyle.state(isRecommended ? RECOMMENDED_COLOR : SELL_COLOR,
			isRecommended ? "Your current suggestion" : "Also worth selling"));
		if (s == null)
		{
			/* s can be null on the recommended stack — see the gate above,
			   where the card outranks the suggestion map. The header still
			   stands on its own; there is simply nothing to price. */
			return sb.toString();
		}
		/* grossValue, not expectedProfit. "Worth selling: X" is a claim about
		   what the stack fetches, and on a tracked stack expectedProfit is a
		   gain instead — which reads as a catastrophic undervaluation when
		   the position is barely up, and as a negative number when it is
		   down. What the sale brings in needs no knowledge of what you paid,
		   so it is the one figure that is right in every case. */
		final long worth = worth(s);
		if (atALoss(s))
		{
			/* Only the stack the card names gets here at a loss — any other
			   is left unmarked, with the plain hover. The card says "At a
			   loss — Hold to keep it", so this leads with the loss as well,
			   in the words the plain hover uses, not with what it fetches. */
			sb.append(TipStyle.BREAK).append(TipStyle.state(TipStyle.BAD,
				"-" + QuantityFormatter.quantityToStackSize(-s.expectedProfit) + " gp if you sell"));
		}
		else if (worth > 0)
		{
			/* And the gain, where there is a cost to measure it against —
			   "why doesnt tool tip say how much profit available as well? ...
			   should say -gp avaialble or + gp availabe". The loss led this
			   hover and the gain was left out: 6,193 Dragon darts bought at
			   955 said only what they fetch, beside a card reading "+117K gp
			   profit available". The card's words and colour; the proceeds
			   line stays under it, plain, as before. */
			if (s.hasTrackedCost && s.unitCost > 0 && s.trackedQty > 0)
			{
				sb.append(TipStyle.BREAK).append(TipStyle.state(TipStyle.GOOD,
					"+" + QuantityFormatter.quantityToStackSize(s.expectedProfit) + " gp profit available"));
			}
			/*
			 * NOT the profit green, deliberately.
			 *
			 * This figure is what the stack FETCHES, not what you made on it
			 * — worth() is grossValue. The sidebar learned this the hard way:
			 * a card printed "30.3M gp sale value" in the profit colour and
			 * read as 30.3M of upside through three attempts to word it out
			 * of that, until the figure was moved to a plain labelled cell.
			 * Painting the same number green here would reintroduce exactly
			 * that claim, on a stack the plugin may never have seen you buy.
			 */
			sb.append(TipStyle.BREAK)
				.append(TipStyle.figure(QuantityFormatter.quantityToStackSize(worth) + " gp"))
				.append(TipStyle.muted(" after tax"));
		}
		if (s.price > 0)
		{
			/* a5a5a5, not the 8a8274 this used to be. That brown was two
			   shades off the tooltip's own background and effectively
			   invisible — it is the line in the screenshot that came back as
			   hard to read. */
			sb.append(TipStyle.BREAK).append(TipStyle.muted(
				(s.quantity > 0 ? String.format("%,d", s.quantity) + " at " : "")
					+ String.format("%,d", s.price) + " gp each"));
		}
		/*
		 * What you paid, and on how many of them — "add hover over, paid x for
		 * x many, on bank stacks too i like that".
		 *
		 * Directly under the line that says what the stack fetches, because
		 * the two are the same sentence read from both ends, and the
		 * subtraction between them is the whole reason anyone hovers a stack
		 * they already own.
		 *
		 * The COUNT is not decoration. A partly tracked stack is the common
		 * case in a real bank — bought some through the plugin, had the rest
		 * before it — and "Paid 1,141 gp each" alone on an 18,608 stack reads
		 * as a claim about all 18,608. The sidebar card carries the same
		 * scope line above its profit figure for the same reason.
		 *
		 * Muted, like the count line above it. Not the buy colour, however
		 * much "paid" wants it: one hue in the bank and it is the sell
		 * colour, because everything a bank square marks is something to
		 * sell. See theBankSpeaksInTheThemesSellColourAndWhite.
		 *
		 * Silent when there is no tracked purchase, rather than printing a
		 * dash or a zero. An untracked stack has no honest "you paid" —
		 * held since before the plugin, dropped, or bought elsewhere — and
		 * the sale lines above stand on their own without one.
		 */
		if (s.unitCost > 0 && s.trackedQty > 0)
		{
			/* Clamped: trackedQty can exceed the stack you are hovering when
			   part of it has already left the bank, and "1,456 of 900" is
			   nonsense on a line whose whole job is to scope a number. */
			final long on = s.quantity > 0 ? Math.min(s.trackedQty, s.quantity) : s.trackedQty;
			sb.append(TipStyle.BREAK).append(TipStyle.muted(
				"Paid " + String.format("%,d", s.unitCost) + " gp each on "
					+ (s.quantity > 0 && on >= s.quantity
						? "all " + String.format("%,d", s.quantity)
						: String.format("%,d", on) + " of " + String.format("%,d", s.quantity))));
		}
		/* And why THIS moment. The mark said a stack was worth selling and
		   what it would fetch, and never why now rather than any other time —
		   asked as "why is this good to sell right now, is it up 30% since
		   you purchased or what". Null whenever there is no real answer. */
		if (s.whyNow != null && !s.whyNow.isEmpty())
		{
			/* The theme's sell colour, not a frozen 26a9ab. That literal was
			   Terminal's teal, so this line stayed teal under Neon, Cobalt
			   and Orchid while every other colour on the square moved with
			   the theme — the same drift the marks themselves had. */
			sb.append(TipStyle.BREAK).append(TipStyle.state(SELL_COLOR, s.whyNow));
		}
		return sb.toString();
	}

	/**
	 * What the stack fetches, with a floor under it.
	 *
	 * grossValue is the right field and is set on every path that builds a
	 * sell — except that one of them did not, and a stack of 26,000 emeralds
	 * hovered "Worth selling: 0 gp after tax". That is fixed upstream, but a
	 * zero here is ALWAYS wrong and always visible, so it is worth not being
	 * able to print one: price times quantity is the same arithmetic the
	 * missing field would have carried.
	 */
	private static long worth(Advisor.Suggestion s)
	{
		if (s.grossValue > 0)
		{
			return s.grossValue;
		}
		if (s.price > 0 && s.quantity > 0)
		{
			final long net = s.price - FlipTracker.taxPerItem(s.price, s.itemId);
			return Math.max(0, net * s.quantity);
		}
		return 0;
	}

	/** A lone unstacked individual item (quantity 1, not in noted form)
	 *  isn't something you'd bulk-flip — it's whatever single piece of gear
	 *  or loot happens to be sitting there. Without this, an unstackable
	 *  item filling a dozen inventory slots (one unit each) drew the exact
	 *  same border on every one of those slots, which reads as a dozen
	 *  separate suggestions rather than the one real one. */
	private boolean isMerchantStack(int itemId, WidgetItem widgetItem)
	{
		if (widgetItem.getQuantity() > 1)
		{
			return true;
		}
		final ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp != null && comp.getNote() != -1;
	}
}

package com.pocketge.tracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * What the coloured rings round your bank slots mean, said in the bank.
 *
 * The marks have always carried a hover tooltip, and the note next to it in
 * BankHighlightOverlay argued that a legend you have to remember is a legend
 * that has already failed. That is still true of a legend somewhere else —
 * but it turned out to be an argument against the tooltip too, because a
 * tooltip is only read by someone who already suspects there is something to
 * read. Reported as "what do the green squares mean?" by the person who asked
 * for the gold one.
 *
 * So the key is drawn where the marks are, and it explains only what is
 * actually on screen: a row appears when that colour is in use and not
 * otherwise. With nothing marked there is nothing to explain, and the bank is
 * left alone.
 *
 * And it can be switched off (the bankLegend setting, on by default). Twice
 * it ended up over something the player needed — the tool row, then the bank
 * note — and the hover tooltip already says the same words, so a layout it
 * still gets in the way of can do without it.
 */
@Singleton
public class BankLegendOverlay extends Overlay
{
	/**
	 * The bank interface's root container.
	 *
	 * Built from the group id rather than a named component constant, because
	 * there is no bank constant to name: the offline stubs carry only
	 * InterfaceID.BANKMAIN, and inventing a component id that the real client
	 * might number differently is exactly the kind of guess that compiles
	 * cleanly and fails in the game. The packing is the convention visible in
	 * the stubs themselves — GeOffers.UNIVERSE is 0x01d1_0000, which is group
	 * 0x01d1 with child 0 — so child 0 of the bank group is its root.
	 *
	 * If that is wrong, getWidget returns null and the legend simply does not
	 * draw. Nothing else depends on it.
	 */
	private static final int BANK_ROOT = InterfaceID.BANKMAIN << 16;

	/* Opaque enough to work over the 3D scene. Inside the bank it sat on
	   dark parchment; below it, what is behind it is grass, sand or a stone
	   floor, and 0xD0 over bright ground was unreadable. */
	private static final Color BG = new Color(0x12, 0x12, 0x12, 0xE8);
	private static final Color RIM = new Color(0x00, 0x00, 0x00, 0x90);
	private static final Color TEXT = new Color(0xE6, 0xE6, 0xE6);

	private static final int SWATCH = 18;
	private static final int PAD = 12;
	private static final int SWATCH_GAP = 11;
	/** Bank's bottom edge to the legend's top edge. */
	private static final int GAP_BELOW = 6;
	@Inject
	private Client client;

	@Inject
	private BankHighlightOverlay marks;

	/** The bankLegend setting, pushed by the plugin at startUp. False until
	 *  then, so nothing is drawn before the config has been read. */
	private volatile boolean enabled;

	public void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	@Inject
	private BankLegendOverlay()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!enabled || !marks.isEnabled())
		{
			return null;
		}
		final Widget bank = client.getWidget(BANK_ROOT);
		if (bank == null || bank.isHidden())
		{
			return null;
		}
		final Rectangle b = bank.getBounds();
		if (b == null || b.width <= 0 || b.height <= 0)
		{
			return null;
		}

		/* Only what is on screen. A key listing a colour the bank is not
		   currently wearing is a quiz, not a key. */
		final List<String[]> rows = new ArrayList<>();
		final boolean hasGold = marks.hasRecommended();
		if (hasGold)
		{
			/* Says what it IS, not where it happens to be shown. "On your
			   panel now" describes the sidebar; the thing you want to know
			   standing at a bank is that this stack is the one being
			   suggested. */
			rows.add(new String[]{"gold", "Your current suggestion"});
		}
		if (marks.hasSellable())
		{
			/* "Also" only when there is something for it to be also TO. With
			   no gold mark on screen these green ones are not the runners-up,
			   they are the whole list. */
			rows.add(new String[]{"green", hasGold ? "Also worth selling" : "Worth selling"});
		}
		if (rows.isEmpty())
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		/* 15f bold: the readable band this plugin already settled on for text
		   drawn on the game canvas, after 11pt was reported as mush on the
		   offer-screen chip. Inside the bank this could lean on the interface
		   around it; out here it cannot. */
		g.setFont(g.getFont().deriveFont(java.awt.Font.BOLD, 17f));
		final FontMetrics fm = g.getFontMetrics();

		int textW = 0;
		for (String[] r : rows)
		{
			textW = Math.max(textW, fm.stringWidth(r[1]));
		}
		/* Row height from the font, not a constant: a size change must not
		   start clipping descenders silently. */
		final int rowH = Math.max(SWATCH, fm.getHeight()) + 5;
		final int w = PAD + SWATCH + SWATCH_GAP + textW + PAD;
		final int h = PAD * 2 + rows.size() * rowH;

		/*
		 * Below the bank, not inside it.
		 *
		 * It was bottom-left INSIDE the bank window, which put a key on top
		 * of the slots it is a key for. Underneath is the empty band of scene
		 * you get in resizable mode, where it covers nothing.
		 *
		 * Three placements, in order, so it can never leave the canvas: under
		 * the bank, above it, or — when neither fits, which is most of fixed
		 * mode where the bank fills the viewport — back inside at the old
		 * spot. Somewhere readable beats nowhere.
		 */
		int x = b.x;
		int y = b.y + b.height + GAP_BELOW;

		final int cw = client.getCanvasWidth();
		final int ch = client.getCanvasHeight();
		/* The floor is the chat area when there is one: in fixed mode the
		   space "below the bank" IS the chat strip, and a key printed over
		   the chat log is not an improvement on one printed over the bank. */
		int floor = ch > 0 ? ch : y + h;
		final Widget chat = client.getWidget(InterfaceID.Chatbox.CHATAREA);
		final Rectangle cb = chat != null && !chat.isHidden() ? chat.getBounds() : null;
		if (cb != null && !cb.isEmpty() && cb.y > b.y)
		{
			floor = Math.min(floor, cb.y - 2);
		}
		/*
		 * Above the bank if there is room; otherwise it STAYS below it.
		 *
		 * The third placement used to be back inside the bank, bottom-left,
		 * and that is where it landed in the ordinary case — a bank that
		 * starts near the top of the screen has no room above it, and a chat
		 * box open underneath leaves no room below. So the key sat on the
		 * bank's own tool row: "make this box i circled always apear more
		 * down. it covers the bank tools".
		 *
		 * The rule is now that it never covers the bank. When the only space
		 * left is the strip the chat is using, it takes that: the chat is
		 * text you read and can scroll, the tool row is buttons you click,
		 * and a box over a button is worse than a box over a sentence. The
		 * canvas clamp below still keeps it on screen — if a layout really
		 * has nowhere at all, somewhere readable beats nowhere, but that is
		 * now the last resort rather than the common case.
		 */
		if (y + h > floor && b.y - GAP_BELOW - h >= 0)
		{
			y = b.y - GAP_BELOW - h;
		}
		/* Guarded on > 0: the offline stub reports 0 for both, and an
		   unguarded clamp would pin the box to the corner in every test and
		   on any frame before the canvas size is known. */
		if (cw > 0)
		{
			x = Math.max(0, Math.min(x, cw - w));
		}
		if (ch > 0)
		{
			y = Math.max(0, Math.min(y, ch - h));
		}

		g.setColor(BG);
		g.fillRect(x, y, w, h);
		g.setColor(RIM);
		/* w-1/h-1: fillRect covers x..x+w-1, so a rim at w/h sat a pixel
		   outside the fill on two sides. */
		g.drawRect(x, y, w - 1, h - 1);

		int ry = y + PAD;
		for (String[] r : rows)
		{
			final boolean gold = "gold".equals(r[0]);
			/* The swatch is the mark itself, at swatch size — drawn by the
			   same method that draws it on a slot, so the key cannot drift
			   out of step with the thing it is describing. */
			final int sy = ry + (rowH - 5 - SWATCH) / 2;
			BankHighlightOverlay.drawRing(g, new Rectangle(x + PAD, sy, SWATCH, SWATCH), gold);
			g.setColor(TEXT);
			/* Centred on the row rather than pinned to the swatch's bottom,
			   so swatch and text stay aligned if either size changes. */
			g.drawString(r[1], x + PAD + SWATCH + SWATCH_GAP,
				ry + (rowH - 5 + fm.getAscent() - fm.getDescent()) / 2);
			ry += rowH;
		}
		return null;
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * The never-recommend list, stored in config as a comma-separated string
 * of item names (human-editable) and mirrored to a Set of ids for the
 * advisor. Names are the source of truth so a user can type into the
 * config box; ids are resolved against the live mapping.
 */
public final class Blocklist
{
	private Blocklist() {}

	public static List<String> parse(String csv)
	{
		List<String> out = new ArrayList<>();
		if (csv == null)
		{
			return out;
		}
		for (String part : csv.split(","))
		{
			String n = part.trim();
			if (!n.isEmpty())
			{
				out.add(n);
			}
		}
		return out;
	}

	public static String toCsv(Set<String> names)
	{
		return String.join(", ", names);
	}

	/** Add a name (case-insensitive de-dupe), returning the new CSV. */
	public static String add(String csv, String name)
	{
		Set<String> names = new LinkedHashSet<>(parse(csv));
		boolean present = names.stream().anyMatch(n -> n.equalsIgnoreCase(name));
		if (!present)
		{
			names.add(name);
		}
		return toCsv(names);
	}

	/** Remove a name (case-insensitive), returning the new CSV. */
	public static String remove(String csv, String name)
	{
		Set<String> names = new LinkedHashSet<>();
		for (String n : parse(csv))
		{
			if (!n.equalsIgnoreCase(name))
			{
				names.add(n);
			}
		}
		return toCsv(names);
	}

	public static boolean contains(String csv, String name)
	{
		for (String n : parse(csv))
		{
			if (n.equalsIgnoreCase(name))
			{
				return true;
			}
		}
		return false;
	}
}

package com.pocketge.tracker;

import java.awt.Color;

/**
 * pocketge.com's own surface colours, so the sidebar and the website are one
 * product rather than two that share a name.
 *
 * <h2>Why</h2>
 * The recommendation card has been the website's {@code --bg-panel} since it
 * was built, and everything around it was RuneLite's stock neutral greys. That
 * reads exactly as what it is — a warm brown panel sitting in a grey box — and
 * was spotted from the screenshot alone: "im not crazy right, that top section
 * is brown? i like it alot, matches the website. can we apply that look to the
 * rest of the sidebar of our plugin".
 *
 * So the greys go, and the values below are lifted from {@code app.css}
 * verbatim. Each names the custom property it came from. Changing one here
 * without changing it there is the drift this class exists to make visible —
 * BrandTest pins every value.
 *
 * <h2>The ramp</h2>
 * Three surfaces, darkest at the back, exactly as the site stacks them:
 *
 * <pre>
 *   BG_BASE   0C0B09   the sidebar itself — what a card floats on
 *   BG_PANEL  1B1815   cards, boxes, popups
 *   BG_INPUT  282320   buttons, headers, fields — things you click or type in
 * </pre>
 *
 * A border sits above whichever surface it is drawn on: {@link #BORDER_MAIN}
 * for a panel's own outline, {@link #BORDER_LIGHT} for a divider that has to
 * be seen across one.
 *
 * <h2>What is deliberately NOT here</h2>
 * The buy and sell hues. Those are the player's, chosen in settings, and they
 * arrive through {@link PocketGeTrackerConfig.ColourTheme} — the site's
 * {@code --buy-color} and {@code --sell-color} are only that theme's defaults.
 * Freezing them here would put a second, unthemed copy of the two colours that
 * carry the plugin's only real meaning into the codebase, which is the exact
 * bug the bank marks and the watchlist badges have each been fixed for once.
 */
final class Brand
{
	/** {@code --bg-base}. The page, and the sidebar: the deepest surface,
	 *  what everything else is laid on. */
	static final Color BG_BASE = new Color(0x0C, 0x0B, 0x09);

	/** {@code --bg-chart}. Behind a plotted series — and the one step between
	 *  base and panel, for anything that should recede without going black. */
	static final Color BG_CHART = new Color(0x13, 0x11, 0x10);

	/** {@code --bg-panel}. Cards, boxes, popups. The colour that was already
	 *  right, and the reason the rest of this file exists. */
	static final Color BG_PANEL = new Color(0x1B, 0x18, 0x15);

	/** {@code --bg-input}. Buttons, headers, text fields: things you click or
	 *  type into, raised off the panel behind them. */
	static final Color BG_INPUT = new Color(0x28, 0x23, 0x20);

	/** {@code --border-main}. A panel's own outline — present, not loud. */
	static final Color BORDER_MAIN = new Color(0x2B, 0x26, 0x21);

	/** {@code --border-light}. A divider that has to carry across a surface,
	 *  and the outline of anything interactive. */
	static final Color BORDER_LIGHT = new Color(0x3C, 0x35, 0x2B);

	/** {@code --text-main}. Item names and figures. Identical to
	 *  AdvisorPanel.TEXT_MAIN and TipStyle.SUBJECT, which both predate this
	 *  class and both took it from the same place. */
	static final Color TEXT_MAIN = new Color(0xD9, 0xD3, 0xC7);

	/**
	 * {@code --text-structural}. The small-caps labels over a figure —
	 * QUANTITY, VALUE, PAID @.
	 *
	 * Warm, where RuneLite's LIGHT_GRAY_COLOR is neutral. It is a label on a
	 * panel, so it is read at a glance or not at all, and the site sets it
	 * two steps brighter than {@code --text-muted} for exactly that reason.
	 */
	static final Color TEXT_STRUCTURAL = new Color(0x94, 0x8A, 0x78);

	/**
	 * {@code --text-muted}. Secondary prose on a panel.
	 *
	 * Note this is 8A8274 — the colour TipStyle bans. Both are right: on the
	 * site's {@code --bg-panel} it is comfortably legible, and the thing that
	 * failed was putting it on the GAME's tooltip background, which is a
	 * different and much closer substrate. A colour is only readable against
	 * something.
	 */
	static final Color TEXT_MUTED = new Color(0x8A, 0x82, 0x74);

	/** {@code --accent-bright}. The site's gold accent. */
	static final Color ACCENT_BRIGHT = new Color(0xE5, 0xC1, 0x58);

	/**
	 * Dresses a Swing control that would otherwise arrive in RuneLite's stock
	 * grey — a text field, a combo box, a plain button.
	 *
	 * These are the components nothing in the plugin had ever painted, because
	 * they look fine until the surface behind them stops being grey too. The
	 * search box over the watchlist and the Session/Reset pair over the stats
	 * were the last two neutral rectangles in a warm sidebar.
	 *
	 * Deliberately NOT a UIManager default. Setting one would reach every
	 * Swing component in the client, including other plugins' panels, which is
	 * not this plugin's to change.
	 *
	 * @param c    the control
	 * @param text its foreground, or null to leave the existing one — a
	 *             placeholder and a typed query are different colours, and
	 *             this must not flatten them
	 */
	static void control(javax.swing.JComponent c, Color text)
	{
		c.setBackground(BG_INPUT);
		if (text != null)
		{
			c.setForeground(text);
		}
		c.setBorder(javax.swing.BorderFactory.createCompoundBorder(
			javax.swing.BorderFactory.createLineBorder(BORDER_LIGHT, 1),
			javax.swing.BorderFactory.createEmptyBorder(2, 5, 2, 5)));
		if (c instanceof javax.swing.text.JTextComponent)
		{
			/* Or the caret is the LAF's near-black on a near-black field. */
			((javax.swing.text.JTextComponent) c).setCaretColor(TEXT_MAIN);
		}
		if (c instanceof javax.swing.AbstractButton)
		{
			final javax.swing.AbstractButton b = (javax.swing.AbstractButton) c;
			b.setFocusPainted(false);
			/* A JButton ignores setBackground under several look-and-feels
			   unless it is told to fill its own content area. */
			b.setOpaque(true);
			b.setContentAreaFilled(true);
		}
	}

	private Brand()
	{
	}
}

package com.pocketge.tracker;

import java.io.File;
import java.net.URI;
import java.net.URL;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.jar.JarFile;
import java.util.zip.ZipEntry;

/**
 * Which build is running, for the report and the bottom of the gear menu.
 *
 * Every build said 0.7.1 for weeks while the code under it changed daily,
 * so a screenshot could not say whether it came from the hub's build or a
 * newer one off main — and the two priced the same stack 375K apart. The
 * version alone cannot tell two dev builds apart, so the time the classes
 * were compiled goes with it.
 */
final class BuildInfo
{
	/** Keep in step with runelite-plugin.properties (the one the hub shows)
	 *  and build.gradle; BuildInfoTest holds all three together. One patch
	 *  on per update, with tools/dev/bump-version.sh, so the footer says
	 *  which update this is — "like personal space has version 1.9.37 way
	 *  easier for me to confirm updates / latest version im on". */
	static final String VERSION = "0.7.41";

	private static final long NOT_BEFORE = 1_577_836_800_000L; // 2020-01-01: a zeroed or reproducible (1980) stamp

	private static volatile String built;

	private BuildInfo()
	{
	}

	/** When this build's classes were written, as "2026-10-20 at 14:03 UTC",
	 *  or "" when the packaging did not keep a time. UTC, like the report's
	 *  "made" line, so two players' screenshots compare. */
	static String built()
	{
		String b = built;
		if (b == null)
		{
			final long at = builtAt();
			b = at > NOT_BEFORE
				? DateTimeFormatter.ofPattern("yyyy-MM-dd 'at' HH:mm 'UTC'").format(Instant.ofEpochMilli(at).atZone(ZoneOffset.UTC))
				: "";
			built = b;
		}
		return b;
	}

	/**
	 * From a jar (the hub's build): the class ENTRY's own time. Not the jar
	 * file's — RuneLite touches every installed hub jar on each start, so
	 * that would read as "built when you launched". A packager that builds
	 * reproducibly zeroes entry times (1980), and then this reads as no
	 * time: such builds are told apart by version alone.
	 *
	 * From a classes directory (a dev build): the newest class file in the
	 * package. Gradle compiles incrementally, so BuildInfo.class alone keeps
	 * its old time when only other files changed.
	 */
	/**
	 * The time on the jar entry a {@code jar:file:…!/entry} URL names, or 0.
	 *
	 * Read by opening the jar as a file, not through the URL's connection:
	 * the plugin hub's scan refuses a URL connection anywhere in a plugin and
	 * asks for RuneLite's OkHttpClient instead — which has nothing to do with
	 * reading a file off the disk, so the file is opened directly. Our own
	 * JarFile, closed here, so the class loader's is never touched.
	 */
	static long jarEntryTime(URL url) throws Exception
	{
		if (url == null || !"jar".equals(url.getProtocol()))
		{
			return 0;
		}
		final String path = url.getPath(); // file:/.../plugin.jar!/com/.../BuildInfo.class
		final int bang = path.indexOf("!/");
		if (bang <= 0)
		{
			return 0;
		}
		try (JarFile jar = new JarFile(new File(URI.create(path.substring(0, bang)))))
		{
			final ZipEntry e = jar.getEntry(path.substring(bang + 2));
			return e != null ? e.getTime() : 0;
		}
	}

	private static long builtAt()
	{
		try
		{
			final URL url = BuildInfo.class.getResource("BuildInfo.class");
			if (url == null)
			{
				return 0;
			}
			if ("file".equals(url.getProtocol()))
			{
				final File[] classes = new File(url.toURI()).getParentFile().listFiles((d, n) -> n.endsWith(".class"));
				long newest = 0;
				for (File f : classes != null ? classes : new File[0])
				{
					newest = Math.max(newest, f.lastModified());
				}
				return newest;
			}
			return jarEntryTime(url);
		}
		catch (Exception | LinkageError ignore)
		{
			// no stamp is a fine answer
		}
		return 0;
	}

	/** "0.7.2, built 2026-10-20 at 14:03 UTC", or just the version. */
	static String label()
	{
		final String b = built();
		return b.isEmpty() ? VERSION : VERSION + ", built " + b;
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Pure capital-allocation planner (no RuneLite types — unit-testable):
 * "I have N gp liquid and S free Grand Exchange slots — what's the best way
 * to actually deploy it?"
 *
 * This exists because {@link Advisor#advise} answers a different question.
 * Its BUY suggestions are each sized against the FULL cash pile
 * independently, so with 100m in the bank it happily lists four flips that
 * would collectively need 300m+ to place. Every individual row is true; the
 * portfolio they imply is not affordable. This class allocates ONE budget
 * across the slots you actually have free, so the totals it reports are
 * ones you can really place right now.
 *
 * The scarce resource is a SLOT-WINDOW, not gp. A GE slot produces value
 * once per 4-hour buy-limit window, so what matters per slot is how much gp
 * that slot can absorb (its capacity = unit cap x unit price) and what edge
 * it earns on that. Two regimes fall out, and which one binds flips the
 * correct ranking key:
 *
 *   Cash-bound (your gp runs out before the good items do) — ranking by ROI
 *   density (edge per gp invested) is provably optimal, the textbook
 *   fractional-knapsack result.
 *
 *   Slot-bound (you run out of slots while gp is still sitting idle) —
 *   density is the WRONG key. Spending one of only three f2p slots on a
 *   high-ROI item that can absorb 200k, while 99m sits idle, is a bad trade
 *   no matter how good its percentage looks.
 *
 * Rather than switching keys on a mode flag, allocation always runs by
 * density (correct whenever quantities are what's being decided) and a
 * repair pass swaps whole positions in and out — which only ever finds an
 * improvement in the slot-bound regime. See {@link #plan}.
 *
 * Everything is after the 2% GE tax, via {@link FlipTracker#taxPerItem}.
 */
public final class CapitalPlanner
{
	private CapitalPlanner() {}

	/** Share of an item's daily flow one position may assume it can absorb.
	 *  Advisor.buildBuys uses /12 (~8% of a day) for its own sizing, but
	 *  that's ~50% of a single 4h window — far too aggressive to promise a
	 *  player their gp is really deployable. Half that rate is the honest
	 *  number for a plan whose whole point is "this is what you can
	 *  actually place right now". */
	private static final long VOLUME_SHARE_DIVISOR = 24;
	/** An unknown GE limit must never read as "unlimited". buildBuys falls
	 *  back to qtyByCash for limit==0, which is harmless when each
	 *  suggestion is sized alone but here would let one unverified item
	 *  swallow the entire bank. Cap its assumed capacity instead. */
	private static final double UNKNOWN_LIMIT_SHARE = 0.15;
	/** Below this a position isn't worth spending one of your slots on. */
	static final long MIN_POSITION_PROFIT = 2_000;
	/** Candidates considered by the repair pass, best-potential first.
	 *  Bounds the swap search (slots x pool x passes) to something trivial
	 *  while still covering every item that could plausibly earn a slot. */
	private static final int POOL_SIZE = 150;
	private static final int MAX_REPAIR_PASSES = 6;
	/** Idle gp below this isn't worth reshuffling the plan over — chasing
	 *  the last fraction of a percent would churn the panel every refresh. */
	private static final long IDLE_TOLERANCE_FLOOR = 1_000_000;

	/** What stopped a position from growing — surfaced so the panel can say
	 *  WHY your gp isn't fully deployed instead of silently under-spending. */
	public enum Bound
	{
		/** The item's 4h Grand Exchange buy limit. */
		GE_LIMIT,
		/** This item's daily traded volume — buying more would be an
		 *  unrealistic share of the day's flow. */
		DAILY_VOLUME,
		/** Ran out of gp; the item itself could have absorbed more. */
		CASH,
		/** No confirmed GE limit for this item, so a conservative share of
		 *  cash was assumed rather than trusting it to be unlimited. */
		LIMIT_UNKNOWN
	}

	/** Why a plan left gp on the table. */
	public enum IdleReason
	{
		NONE,
		/** Every GE slot is already occupied. */
		NO_FREE_SLOTS,
		/** Slots are free, but buy limits / daily volume cap how much can
		 *  be deployed into them inside one 4h window. This is the normal
		 *  answer for a large bank and the honest one. */
		LIMITS_CAP_DEPLOYMENT,
		/** Nothing currently clears the profit bar. */
		NO_VIABLE_ITEMS
	}

	/** One item the planner would consider putting in a slot. The caller
	 *  resolves prices (raw quote or TradeEngine target — see
	 *  Advisor.advise, which already reprices this way) so this class never
	 *  needs to know where they came from. */
	public static class Candidate
	{
		public int id;
		public String name;
		public long unitBuy;     // what you'd pay per unit
		public long unitEdge;    // profit per unit AFTER tax
		public int limit;        // 4h GE buy limit, 0 = unknown
		public long dailyVolume;
	}

	/** One funded position in the finished plan — a single GE slot's worth. */
	public static class Position
	{
		public int id;
		public String name;
		public int quantity;
		public long unitBuy;
		public long unitEdge;
		public long spend;           // quantity * unitBuy
		public long expectedProfit;  // quantity * unitEdge, after tax
		public double roiPct;
		public Bound boundBy;
		/** Carried through so the panel can say how risky the fill is — a
		 *  position that is a large share of a day's trade may simply sit
		 *  there. See AdvisorPanel's risk meter. */
		public long dailyVolume;
	}

	public static class Plan
	{
		public List<Position> positions = new ArrayList<>();
		public long cashAvailable;
		public long cashDeployed;
		public long cashIdle;
		public long expectedProfit;
		public int slotsAvailable;
		public int slotsUsed;
		public IdleReason idleReason = IdleReason.NONE;

		/** Deployed as a share of what you had — the "am I actually putting
		 *  my bank to work" number the whole feature exists to answer. */
		public double deployedPct()
		{
			return cashAvailable > 0 ? (cashDeployed * 100.0) / cashAvailable : 0;
		}


	}

	/** Scored candidate — capacity/density derived once, then reused by
	 *  every fill and swap evaluation. */
	private static class Scored
	{
		Candidate c;
		int unitCap;         // most units one slot may take this window
		long capacityGp;     // unitCap * unitBuy — gp this slot can absorb
		double density;      // unitEdge / unitBuy — profit per gp invested
		Bound capBound;      // what set unitCap (before cash is considered)
	}

	/**
	 * Build the best affordable plan for {@code cash} across
	 * {@code freeSlots} slots.
	 *
	 * {@code freeSlots} must count slots occupied by offers that are merely
	 * awaiting collection — a BOUGHT/SOLD/CANCELLED offer still owns its
	 * slot until you collect it, so counting only actively-BUYING/SELLING
	 * offers would over-report what's free. See
	 * PocketGeTrackerPlugin.freeGeSlots().
	 */
	public static Plan plan(long cash, int freeSlots, List<Candidate> candidates)
	{
		final Plan plan = new Plan();
		plan.cashAvailable = Math.max(0, cash);
		plan.slotsAvailable = Math.max(0, freeSlots);
		plan.cashIdle = plan.cashAvailable;

		if (plan.cashAvailable <= 0 || plan.slotsAvailable <= 0)
		{
			plan.idleReason = plan.slotsAvailable <= 0 ? IdleReason.NO_FREE_SLOTS : IdleReason.NO_VIABLE_ITEMS;
			return plan;
		}

		final List<Scored> pool = pool(plan.cashAvailable, candidates);
		if (pool.isEmpty())
		{
			plan.idleReason = IdleReason.NO_VIABLE_ITEMS;
			return plan;
		}

		// Seed by density (optimal while cash is the binding constraint),
		// then let the repair pass fix the slot-bound case where density
		// alone would strand most of the bank.
		List<Scored> chosen = new ArrayList<>();
		for (Scored s : pool)
		{
			if (chosen.size() >= plan.slotsAvailable)
			{
				break;
			}
			chosen.add(s);
		}
		List<Position> best = fill(chosen, plan.cashAvailable);
		best = repair(best, chosen, pool, plan.cashAvailable, plan.slotsAvailable);

		for (Position p : best)
		{
			plan.positions.add(p);
			plan.cashDeployed += p.spend;
			plan.expectedProfit += p.expectedProfit;
		}
		plan.slotsUsed = plan.positions.size();
		plan.cashIdle = plan.cashAvailable - plan.cashDeployed;
		plan.idleReason = idleReason(plan);
		return plan;
	}

	/** Score, filter and rank every candidate, keeping the top POOL_SIZE by
	 *  what they could earn if handed the whole bank — the frontier worth
	 *  searching. Density order within the pool is what fill() relies on. */
	private static List<Scored> pool(long cash, List<Candidate> candidates)
	{
		final List<Scored> scored = new ArrayList<>();
		if (candidates == null)
		{
			return scored;
		}
		for (Candidate c : candidates)
		{
			if (c == null || c.unitBuy <= 0 || c.unitEdge <= 0 || c.unitBuy > cash)
			{
				continue;
			}
			final long volCap = Math.max(1, c.dailyVolume / VOLUME_SHARE_DIVISOR);
			final long limitCap = c.limit > 0
				? c.limit
				: Math.max(1, (long) (cash * UNKNOWN_LIMIT_SHARE / c.unitBuy));
			final long unitCap = Math.min(limitCap, volCap);
			if (unitCap <= 0)
			{
				continue;
			}
			final Scored s = new Scored();
			s.c = c;
			s.unitCap = (int) Math.min(Integer.MAX_VALUE, unitCap);
			s.capacityGp = unitCap * c.unitBuy;
			s.density = c.unitEdge / (double) c.unitBuy;
			s.capBound = c.limit <= 0 ? Bound.LIMIT_UNKNOWN
				: (limitCap <= volCap ? Bound.GE_LIMIT : Bound.DAILY_VOLUME);
			scored.add(s);
		}
		// Rank by what each could earn given the whole bank, so the pool
		// keeps genuine big absorbers that a pure density cut would drop.
		scored.sort(Comparator
			.comparingLong((Scored s) -> potential(s, cash)).reversed()
			.thenComparingInt(s -> s.c.id));
		final List<Scored> pool = new ArrayList<>(scored.subList(0, Math.min(POOL_SIZE, scored.size())));
		pool.sort(Comparator
			.comparingDouble((Scored s) -> s.density).reversed()
			.thenComparingLong((Scored s) -> -s.capacityGp)
			.thenComparingInt(s -> s.c.id));
		return pool;
	}

	private static long potential(Scored s, long cash)
	{
		final long qty = Math.min(s.unitCap, cash / s.c.unitBuy);
		return qty * s.c.unitEdge;
	}

	/**
	 * Allocate {@code cash} across a fixed set of slots, highest density
	 * first up to each item's cap. Optimal for a chosen set — the only
	 * open question this class faces is WHICH items to choose, which is
	 * what repair() searches.
	 */
	private static List<Position> fill(List<Scored> set, long cash)
	{
		final List<Scored> ordered = new ArrayList<>(set);
		ordered.sort(Comparator
			.comparingDouble((Scored s) -> s.density).reversed()
			.thenComparingInt(s -> s.c.id));

		final List<Position> out = new ArrayList<>();
		long remaining = cash;
		for (Scored s : ordered)
		{
			if (remaining <= 0)
			{
				break;
			}
			final long byCash = remaining / s.c.unitBuy;
			final int qty = (int) Math.min(s.unitCap, byCash);
			if (qty <= 0)
			{
				continue;
			}
			final long profit = qty * s.c.unitEdge;
			if (profit < MIN_POSITION_PROFIT)
			{
				continue;
			}
			final Position p = new Position();
			p.id = s.c.id;
			p.name = s.c.name;
			p.quantity = qty;
			p.unitBuy = s.c.unitBuy;
			p.unitEdge = s.c.unitEdge;
			p.spend = qty * s.c.unitBuy;
			p.expectedProfit = profit;
			p.roiPct = (profit * 100.0) / p.spend;
			p.boundBy = qty < s.unitCap ? Bound.CASH : s.capBound;
			p.dailyVolume = s.c.dailyVolume;
			out.add(p);
			remaining -= p.spend;
		}
		out.sort(Comparator.comparingLong((Position p) -> p.expectedProfit).reversed());
		return out;
	}

	/**
	 * Swap positions in and out while it raises total profit.
	 *
	 * This is what makes the slot-bound case come out right: density order
	 * alone will happily spend all three f2p slots on high-percentage items
	 * that between them absorb a couple of million, leaving most of a large
	 * bank idle. A swap that trades one of those for a lower-ROI item able
	 * to soak up 30m wins on absolute profit, and only ever wins when gp
	 * really is going spare — in the cash-bound regime no swap improves on
	 * the density seed, so this loop finds nothing and costs one pass.
	 */
	private static List<Position> repair(List<Position> seed, List<Scored> chosen, List<Scored> pool,
		long cash, int freeSlots)
	{
		List<Position> best = seed;
		long bestProfit = totalProfit(seed);
		Set<Integer> chosenIds = idsOf(chosen);
		List<Scored> current = new ArrayList<>(chosen);

		for (int pass = 0; pass < MAX_REPAIR_PASSES; pass++)
		{
			// Only worth searching while gp is genuinely stranded — the
			// plan is already the density optimum otherwise.
			if (totalSpend(best) >= cash - idleTolerance(cash) && current.size() >= Math.min(freeSlots, pool.size()))
			{
				break;
			}
			boolean improved = false;
			List<Scored> bestSet = null;

			for (int i = 0; i < current.size(); i++)
			{
				for (Scored cand : pool)
				{
					if (chosenIds.contains(cand.c.id))
					{
						continue;
					}
					final List<Scored> trial = new ArrayList<>(current);
					trial.set(i, cand);
					final List<Position> filled = fill(trial, cash);
					final long profit = totalProfit(filled);
					if (profit > bestProfit)
					{
						bestProfit = profit;
						best = filled;
						bestSet = trial;
						improved = true;
					}
				}
			}
			// Also try simply ADDING an unused slot — the seed can come up
			// short of freeSlots when low-density items failed the profit
			// floor at the cash left over at the time.
			if (current.size() < freeSlots)
			{
				for (Scored cand : pool)
				{
					if (chosenIds.contains(cand.c.id))
					{
						continue;
					}
					final List<Scored> trial = new ArrayList<>(current);
					trial.add(cand);
					final List<Position> filled = fill(trial, cash);
					final long profit = totalProfit(filled);
					if (profit > bestProfit)
					{
						bestProfit = profit;
						best = filled;
						bestSet = trial;
						improved = true;
					}
				}
			}

			if (!improved || bestSet == null)
			{
				break;
			}
			current = bestSet;
			chosenIds = idsOf(current);
		}
		return best;
	}

	private static long idleTolerance(long cash)
	{
		return Math.max(IDLE_TOLERANCE_FLOOR, cash / 100);
	}

	private static Set<Integer> idsOf(List<Scored> set)
	{
		final Set<Integer> ids = new LinkedHashSet<>();
		for (Scored s : set)
		{
			ids.add(s.c.id);
		}
		return ids;
	}

	private static long totalProfit(List<Position> positions)
	{
		long total = 0;
		for (Position p : positions)
		{
			total += p.expectedProfit;
		}
		return total;
	}

	private static long totalSpend(List<Position> positions)
	{
		long total = 0;
		for (Position p : positions)
		{
			total += p.spend;
		}
		return total;
	}

	/** Never claim a big bank is fully deployed when buy limits are what's
	 *  really stopping it — that's the honest answer players need, and the
	 *  usual one above a few tens of millions. */
	private static IdleReason idleReason(Plan plan)
	{
		if (plan.positions.isEmpty())
		{
			return plan.slotsAvailable <= 0 ? IdleReason.NO_FREE_SLOTS : IdleReason.NO_VIABLE_ITEMS;
		}
		if (plan.cashIdle <= idleTolerance(plan.cashAvailable))
		{
			return IdleReason.NONE;
		}
		return IdleReason.LIMITS_CAP_DEPLOYMENT;
	}
}

package com.pocketge.tracker;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Best-effort extraction of "what item is this trade-chat line about" —
 * e.g. "buying venator bow 68m" -> "venator bow", "s> soul reaper axe 450m
 * ea" -> "soul reaper axe". Pure string heuristics (no RuneLite deps, no
 * knowledge of the real item list): strip known trade-chat verbs/prefixes
 * off the front, strip price-looking tokens off the back, and whatever's
 * left in the middle is the guess. Deliberately conservative — a bad guess
 * here means a right-click option that searches for the wrong thing, so
 * this returns null rather than a low-confidence guess whenever the result
 * looks implausible (empty, too long, or still price-shaped).
 */
public final class ChatTradeParser
{
	private ChatTradeParser() {}

	private static final Set<String> LEADING_WORDS = new LinkedHashSet<>(Arrays.asList(
		"buying", "buy", "selling", "sell", "wtb", "wts", "want", "wanted", "to", "for",
		"looking", "lf", "trading", "trade"
	));
	private static final Set<String> LEADING_SYMBOLS = new LinkedHashSet<>(Arrays.asList(
		"b>", "s>", ">", "-", "|"
	));
	private static final Set<String> TRAILING_UNIT_WORDS = new LinkedHashSet<>(Arrays.asList(
		"gp", "gold", "each", "ea", "/ea", "/each", "per"
	));
	/** A bare number (with optional thousands separators/decimals), an
	 *  optional k/m/b magnitude suffix, and an optional glued-on "gp" —
	 *  "68m", "450,000", "1.5b", "68", "15000gp". */
	private static final Pattern PRICE_TOKEN = Pattern.compile(
		"^[\\d][\\d,.]*(?:[kKmMbB]|[gG][pP])?[.,!?:;]*$");
	private static final int MAX_WORDS = 6;
	private static final int MIN_CHARS = 3;

	/** Returns the guessed item name, or null if the line doesn't look
	 *  confidently like "<verb> <item name> <price>". */
	public static String extractItemName(String message)
	{
		if (message == null)
		{
			return null;
		}
		List<String> tokens = new java.util.ArrayList<>(Arrays.asList(message.trim().split("\\s+")));
		if (tokens.isEmpty())
		{
			return null;
		}

		int head = 0;
		while (head < tokens.size())
		{
			final String t = tokens.get(head);
			final String lower = stripPunct(t).toLowerCase();
			if (LEADING_WORDS.contains(lower) || LEADING_SYMBOLS.contains(t))
			{
				head++;
				continue;
			}
			break;
		}

		int tail = tokens.size();
		boolean sawPrice = false;
		while (tail > head)
		{
			final String t = tokens.get(tail - 1);
			final String lower = stripPunct(t).toLowerCase();
			if (PRICE_TOKEN.matcher(t).matches())
			{
				sawPrice = true;
				tail--;
				continue;
			}
			if (TRAILING_UNIT_WORDS.contains(lower))
			{
				tail--;
				continue;
			}
			break;
		}

		/* A price is the one signal that reliably tells "buying X 68m" (real
		   trade chat) apart from an ordinary sentence that happens to start
		   with one of the leading words above ("buying groceries later",
		   "lol nice kill") — require it rather than guessing off the leading
		   word alone. */
		if (!sawPrice)
		{
			return null;
		}
		if (tail <= head)
		{
			return null; // nothing left after stripping — e.g. just "buying 68m"
		}
		final List<String> middle = tokens.subList(head, tail);
		if (middle.size() > MAX_WORDS)
		{
			return null; // too long to plausibly be one item name
		}
		final StringBuilder sb = new StringBuilder();
		for (String t : middle)
		{
			final String cleaned = stripPunct(t);
			if (cleaned.isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(cleaned);
		}
		final String result = sb.toString().trim();
		if (result.length() < MIN_CHARS || PRICE_TOKEN.matcher(result).matches())
		{
			return null;
		}
		return result;
	}

	private static String stripPunct(String s)
	{
		int start = 0, end = s.length();
		while (start < end && isEdgePunct(s.charAt(start)))
		{
			start++;
		}
		while (end > start && isEdgePunct(s.charAt(end - 1)))
		{
			end--;
		}
		return s.substring(start, end);
	}

	private static boolean isEdgePunct(char c)
	{
		return c == ',' || c == '.' || c == '!' || c == '?' || c == ':' || c == ';'
			|| c == '(' || c == ')' || c == '[' || c == ']' || c == '"' || c == '\'';
	}
}

package com.pocketge.tracker;

/**
 * How big the stack you are holding is against the number of units buyers
 * actually took off this item in the last 24 hours — "your 10,787 is 2.3 days
 * of demand".
 *
 * This is what a sell card says in the slot where a buy card shows its flip
 * score. It is deliberately NOT a score.
 *
 * <h2>Why not a score</h2>
 * Four candidate 0-100 exit scores were specified and picked apart before this
 * one line survived, and the three that lost are worth recording because each
 * failed in a way that is easy to walk back into:
 *
 * <ul>
 *   <li>A <b>price-level</b> score — "you are near the top of the range, so
 *       this is a good exit" — reduces to a one-sided drawdown penalty. Its
 *       largest term measures which way the price moved today, which is a
 *       forecast wearing a measurement's clothes. See {@link RangePosition},
 *       which refuses the same thing for the same reason.</li>
 *   <li>A <b>liquidation-cost</b> score that mixed stack size with the GE buy
 *       limit scored one twisted bow at 88 of 100 — "you are a rounding error
 *       against the flow" — because a single unit is always under any limit.
 *       It also imported Jagex's buy-limit table, which is an anti-RWT policy
 *       dial, as a quarter of a liquidity measurement.</li>
 *   <li>An <b>opportunity-cost</b> score — "this gold could be earning more in
 *       the buy ideas on this list" — comes out inversely proportional to
 *       stack size, so it whispers at small liquid junk and goes quiet on the
 *       huge dead position. It fought the panel's own sort order on screen.</li>
 * </ul>
 *
 * What was left after all three was the measurement underneath the best of
 * them, with no number wrapped around it. A 0-100 here would have to be
 * calibrated against something, and there is nothing honest to calibrate it
 * against: "is this a good exit" depends on what you want the gold for, which
 * the plugin does not know. "Your stack is 2.3 days of demand" depends on
 * nothing but two counts.
 *
 * <h2>What it deliberately does not use</h2>
 * <b>Cost basis.</b> No parameter here is what you paid, so a stack bought
 * through the plugin and a stack that came out of a drop go down identical
 * code. Every P&amp;L-shaped signal goes blank on exactly the holdings that most
 * need an exit read — the ones predating the plugin — and an exit measurement
 * that is contaminated by cost basis is a sunk-cost machine anyway: it would
 * argue for holding a loser and dumping a winner.
 *
 * <b>The live spread.</b> {@code Advisor.freshForSell} gates a sell candidate
 * on the BID leg only, over a two-hour window, so {@code q.low} on a sell may
 * be hours stale or zero. Anything computed from {@code q.high - q.low} would
 * score a fresh ask against an arbitrarily old bid. Both volumes here come out
 * of the same /24h response instead, so they are always consistent with each
 * other.
 *
 * <b>One side of the book.</b> The obvious denominator is the insta-buy volume
 * alone, since that is the side that takes your offer. It is also the side
 * that collapses in a bleed — holders stop waiting and hit the bid while
 * buyers stop lifting the ask — so a one-sided denominator quietly turns this
 * into a directional signal, spiking exactly when the price is falling. The
 * average of the two sides is used instead, which is the same figure
 * {@link FinderEngine} sums for its own volume floor.
 *
 * Pure and dependency-free, like {@link RangePosition} and
 * {@link PriceExtremes}, so the arithmetic is unit-testable without a client
 * or a network.
 */
public final class Clearance
{
	/**
	 * Below this many prints across both sides in 24 hours, this says nothing
	 * at all.
	 *
	 * Without it the measurement is at its most confident exactly where it is
	 * least supported: a blue partyhat with three held against eight insta-buys
	 * in a day is arithmetically "0.75 days of demand", which reads as a
	 * liquid position and is nonsense off a sample of eight. Silence on a rare
	 * is correct; a number off a handful of trades is not.
	 *
	 * Deliberately the same constant and the same both-sides sum as
	 * FinderEngine.LOW_VOL_THRESHOLD, which already refuses to rate an item on
	 * this much evidence.
	 */
	public static final long MIN_PRINTS = 100_000;

	/**
	 * Under a full day of demand, this says nothing.
	 *
	 * The first cut printed a line on every sell it could measure, which
	 * meant almost all of them read "under an hour of demand" — true,
	 * unhelpful, and different on adjacent cards for no reason a player could
	 * see. Reported as "get rid of this inconsistent hours of demand text its
	 * meaningless", and that is the right call: the whole point of the line is
	 * that your stack is big enough for size to be a factor in getting out.
	 * A stack that clears inside a day is not a stack you have to think about,
	 * so there is nothing to say about it.
	 *
	 * The floor also removes the hours unit entirely, so the line has exactly
	 * one form — "N days of demand" — rather than four that a reader has to
	 * tell apart.
	 */
	public static final double MIN_DAYS = 1.0;

	/** Units you are holding. */
	public final long qty;
	/** Units a day, averaged across both sides of the book. */
	public final long flowPerDay;
	/** qty / flowPerDay. Uncapped — see {@link #label()}. */
	public final double days;

	private Clearance(long qty, long flowPerDay, double days)
	{
		this.qty = qty;
		this.flowPerDay = flowPerDay;
		this.days = days;
	}

	/**
	 * @param qty         units held — the stack this card is about to list
	 * @param buySideVol  AnalystRating.Average.highPriceVolume, 24h
	 * @param sellSideVol AnalystRating.Average.lowPriceVolume, 24h
	 * @return null when it cannot be measured or is not supported by enough
	 *         prints, in which case the card shows nothing rather than a
	 *         number it cannot stand behind
	 */
	public static Clearance of(long qty, long buySideVol, long sellSideVol)
	{
		if (qty <= 0 || buySideVol < 0 || sellSideVol < 0)
		{
			return null;
		}
		final long prints = buySideVol + sellSideVol;
		if (prints < MIN_PRINTS)
		{
			return null;
		}
		final long flow = prints / 2;
		if (flow <= 0)
		{
			return null;
		}
		final double days = qty / (double) flow;
		if (days < MIN_DAYS)
		{
			return null;
		}
		return new Clearance(qty, flow, days);
	}

	/**
	 * The line the card prints.
	 *
	 * "of demand", not "to clear". The difference is not pedantry: "2.3 days
	 * to clear" says the stack WILL be gone in 2.3 days, which is a forecast
	 * this cannot support — it assumes you are the only seller listing, and
	 * two players each holding the same 2.3 days are between them 4.6 days of
	 * flow and one of them is not getting filled. "2.3 days of demand" states
	 * the ratio and claims nothing about the future.
	 *
	 * Uncapped at the top on purpose. A stack worth 41 days of demand prints
	 * "41 days", not "10+ days": the whole value of the line on a dead
	 * position is that the number keeps going. Floored at the bottom instead,
	 * where the readings were meaningless — see MIN_DAYS.
	 */
	public String label()
	{
		/* One unit, always. See MIN_DAYS — anything smaller than a day does
		   not get a line at all, so there is no hours form to tell apart. */
		return days >= 10
			? String.format("%,.0f days of demand", days)
			: String.format("%.1f days of demand", days);
	}

	/**
	 * The working, as plain lines. The panel wraps these in its own tooltip
	 * HTML; kept as text here so a test can read them.
	 *
	 * Line two is the assumption, not a footnote, because it is the single
	 * thing most likely to make the number wrong for you.
	 */
	public String[] tooltipLines()
	{
		return new String[]{
			String.format("Your %,d against %,d a day.", qty, flowPerDay),
			"Units buyers took off this item in the last 24 hours, averaged "
				+ "across both sides of the book.",
			"Assumes you are the only seller listing.",
			"Nothing here is what you paid, or where the price goes next.",
		};
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/**
 * Multiple named, color-flagged favorites lists (TradingView-style
 * watchlists) instead of one flat list. Stored as JSON in config since a
 * flat "id:name" CSV (the old {@link Favorites} format) can't carry
 * per-list membership or metadata. The Gson instance is always passed in
 * rather than constructed here — RuneLite's plugin-hub verification
 * rejects plugins that build their own Gson instead of using the injected
 * one (see LocalBridgeServer's constructor comment).
 */
public final class FavoriteLists
{
	private FavoriteLists() {}

	private static final Type LIST_TYPE = new TypeToken<List<FavoriteList>>() {}.getType();

	/**
	 * A fixed palette, TradingView-watchlist-dot style, rather than a full
	 * colour picker — choosing one is a click on a dot instead of a dialog,
	 * and every one of them stays readable as text on the dark panel, which a
	 * free picker could not promise.
	 *
	 * Twelve, for two rows of six in the list switcher. The first seven are
	 * the original palette in its original order: new lists are dealt from
	 * the front, and a list keeps the hex it was given, so nothing anyone
	 * already has changes colour.
	 */
	public static final String[] PALETTE = {
		"#E5C158", // gold
		"#26A69A", // teal
		"#EF5350", // red
		"#42A5F5", // blue
		"#AB47BC", // purple
		"#66BB6A", // green
		"#FF9F43", // orange
		"#F06292", // pink
		"#4DD0E1", // cyan
		"#C0CA33", // lime
		"#7986CB", // indigo
		"#B0BEC5", // silver
	};

	/** What each of {@link #PALETTE} is called, in the same order, for the
	 *  swatches' tooltips and the right-click menu. */
	public static final String[] PALETTE_NAMES = {
		"Gold", "Teal", "Red", "Blue", "Purple", "Green",
		"Orange", "Pink", "Cyan", "Lime", "Indigo", "Silver",
	};

	public static class FavoriteList
	{
		public String id;
		public String name;
		public String color;
		public List<Favorites.Fav> items = new ArrayList<>();

		public FavoriteList() {}

		public FavoriteList(String id, String name, String color)
		{
			this.id = id;
			this.name = name;
			this.color = color;
		}
	}

	public static List<FavoriteList> parse(Gson gson, String json)
	{
		if (json == null || json.isEmpty())
		{
			return new ArrayList<>();
		}
		try
		{
			List<FavoriteList> lists = gson.fromJson(json, LIST_TYPE);
			return lists != null ? lists : new ArrayList<>();
		}
		catch (Exception e)
		{
			return new ArrayList<>();
		}
	}

	public static String toJson(Gson gson, List<FavoriteList> lists)
	{
		return gson.toJson(lists);
	}

	public static String newListId()
	{
		return UUID.randomUUID().toString();
	}

	/** One-time migration from the old flat "id:name" CSV list ({@link
	 *  Favorites}) — wraps it in a single default list so nobody's existing
	 *  favorites vanish when this ships. */
	public static List<FavoriteList> migrateFromCsv(String csv)
	{
		List<FavoriteList> out = new ArrayList<>();
		List<Favorites.Fav> favs = Favorites.parse(csv);
		if (!favs.isEmpty())
		{
			FavoriteList def = new FavoriteList(newListId(), "Favorites", PALETTE[0]);
			def.items.addAll(favs);
			out.add(def);
		}
		return out;
	}

	public static FavoriteList findList(List<FavoriteList> lists, String id)
	{
		if (id == null)
		{
			return null;
		}
		for (FavoriteList l : lists)
		{
			if (id.equals(l.id))
			{
				return l;
			}
		}
		return null;
	}

	public static boolean contains(FavoriteList list, int itemId)
	{
		if (list == null)
		{
			return false;
		}
		for (Favorites.Fav f : list.items)
		{
			if (f.id == itemId)
			{
				return true;
			}
		}
		return false;
	}

	/** Re-adds at the end if already present, so favoriting an item you
	 *  already have (e.g. re-clicking the star with stale UI state) doesn't
	 *  duplicate it. */
	public static void addItem(FavoriteList list, int itemId, String name)
	{
		removeItem(list, itemId);
		list.items.add(new Favorites.Fav(itemId, name));
	}

	public static void removeItem(FavoriteList list, int itemId)
	{
		list.items.removeIf(f -> f.id == itemId);
	}

	/** Swap with the neighbour in that direction, clamped at both ends. */
	public static void moveItem(FavoriteList list, int itemId, int delta)
	{
		int i = -1;
		for (int idx = 0; idx < list.items.size(); idx++)
		{
			if (list.items.get(idx).id == itemId)
			{
				i = idx;
				break;
			}
		}
		int j = i + delta;
		if (i < 0 || j < 0 || j >= list.items.size())
		{
			return;
		}
		Favorites.Fav tmp = list.items.get(i);
		list.items.set(i, list.items.get(j));
		list.items.set(j, tmp);
	}

	/** Drag-to-reorder: pulls the item out and re-inserts it at
	 *  targetIndex, shifting everything in between — unlike {@link
	 *  #moveItem}'s adjacent swap, this actually lands it where a drag
	 *  visually dropped it, however far that is. No-op if itemId isn't in
	 *  the list. targetIndex is clamped to the list's bounds so a drop
	 *  past either end just lands at that end rather than throwing. */
	public static void moveItemToIndex(FavoriteList list, int itemId, int targetIndex)
	{
		int i = -1;
		for (int idx = 0; idx < list.items.size(); idx++)
		{
			if (list.items.get(idx).id == itemId)
			{
				i = idx;
				break;
			}
		}
		if (i < 0)
		{
			return;
		}
		Favorites.Fav item = list.items.remove(i);
		final int j = Math.max(0, Math.min(targetIndex, list.items.size()));
		list.items.add(j, item);
	}

	/**
	 * Rewrites the list's order to match {@code itemIds}, for two-way order
	 * sync with the website.
	 *
	 * Deliberately tolerant, because the caller's view is always slightly
	 * stale: the browser sends the order it was showing, which may predate
	 * a star you just tapped in game by a second or two. So this is a
	 * REORDER, never an edit —
	 *
	 *  - ids the list doesn't contain are ignored (the site is telling us
	 *    about an item removed in-game since it last polled),
	 *  - items the caller didn't mention keep their relative order and land
	 *    at the end (an item favorited in-game that the site hasn't seen
	 *    yet — dropping it would silently delete a favorite),
	 *  - a duplicated id is honoured once.
	 *
	 * Membership is therefore never changed by this call, only sequence.
	 * That matters: a naive "replace items with what the caller sent" makes
	 * every reorder a race that can eat a favorite.
	 */
	public static void reorderTo(FavoriteList list, List<Integer> itemIds)
	{
		if (list == null || itemIds == null || itemIds.isEmpty())
		{
			return;
		}
		final List<Favorites.Fav> remaining = new ArrayList<>(list.items);
		final List<Favorites.Fav> ordered = new ArrayList<>(remaining.size());
		for (Integer id : itemIds)
		{
			if (id == null)
			{
				continue;
			}
			for (int i = 0; i < remaining.size(); i++)
			{
				if (remaining.get(i).id == id)
				{
					ordered.add(remaining.remove(i));
					break;
				}
			}
		}
		ordered.addAll(remaining); // anything the caller didn't know about
		list.items = ordered;
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.List;

/**
 * The local favorites watchlist, stored in config as "id:name" pairs
 * (unlike the blocklist's bare names) so display never needs a
 * name-to-item-id search — favoriting always happens from a suggestion or
 * history row where both are already known, so both are just carried
 * straight through.
 */
public final class Favorites
{
	private Favorites() {}

	public static class Fav
	{
		public final int id;
		public final String name;
		public Fav(int id, String name) { this.id = id; this.name = name; }
	}

	public static List<Fav> parse(String csv)
	{
		List<Fav> out = new ArrayList<>();
		if (csv == null || csv.isEmpty())
		{
			return out;
		}
		for (String part : csv.split(","))
		{
			String p = part.trim();
			int sep = p.indexOf(':');
			if (sep <= 0 || sep == p.length() - 1)
			{
				continue; // malformed entry — skip rather than crash
			}
			try
			{
				int id = Integer.parseInt(p.substring(0, sep).trim());
				String name = p.substring(sep + 1).trim();
				if (!name.isEmpty())
				{
					out.add(new Fav(id, name));
				}
			}
			catch (NumberFormatException ignore)
			{
				// skip malformed entry
			}
		}
		return out;
	}





}

