	/** Rebuild the list-switcher chip row. Call on the Swing EDT whenever the
	 *  set of lists, the active one, or any name/color changes. */
	public void updateLists(List<ListMeta> lists, String activeListId)
	{
		this.lists = lists != null ? lists : new ArrayList<>();
		this.activeListId = activeListId;
		listBar.removeAll();
		// One dropdown showing the ACTIVE list, not a chip per list. Laying
		// every list out inline spent the sidebar's whole width on lists you
		// aren't looking at, and got worse with each one created — the point
		// of multiple watchlists is that only one is on screen at a time.
		final ListMeta active = activeList();
		if (active != null)
		{
			listBar.add(listDropdown(active), BorderLayout.CENTER);
		}
		/* No LINKED chip here.
		   It mirrored the website's own badge, which made sense while the
		   link had no other presence in the plugin — but the top strip now
		   carries a link BUTTON that shows the same state and is the thing
		   you press to change it. Two indicators for one boolean, and this
		   was the one you could not act on, sitting in the row that names
		   your watchlist. */
		listBar.add(listBarRight(), BorderLayout.EAST);
		/* The chevron is a live component that moved into a panel this method
		   rebuilds, so its text has to be re-applied after every rebuild or a
		   list switch would blank it. */
		paintListToggle();
		listBar.revalidate();
		listBar.repaint();
	}

	/** The active list, as a dropdown. Left-click opens the switcher (every
	 *  list, current one checked); right-click opens rename, recolour and
	 *  delete for the list currently shown. Text stays left-aligned since it
	 *  stretches to fill the row, so it reads as a header rather than a
	 *  mis-centered button.
	 *
	 *  Its arrow at the right-hand end, where a dropdown's arrow goes and
	 *  where every other chevron in the panel sits: "move the chevron to the
	 *  right like every other chevron". It sat straight after the name.
	 *  Painted rather than typed, so it stays at the edge however wide the
	 *  bar is; the border keeps the room for it, so a long name stops short
	 *  of it instead of running under it. */
	private JButton listDropdown(ListMeta l)
	{
		JButton chip = new JButton("\u25CF " + l.name)
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				super.paintComponent(g);
				final Graphics2D g2 = (Graphics2D) g.create();
				try
				{
					g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
					g2.setFont(getFont());
					g2.setColor(getForeground());
					final java.awt.FontMetrics fm = g2.getFontMetrics();
					g2.drawString(DROPDOWN_ARROW, getWidth() - DROPDOWN_ARROW_INSET - fm.stringWidth(DROPDOWN_ARROW),
						(getHeight() - fm.getHeight()) / 2 + fm.getAscent());
				}
				finally
				{
					g2.dispose();
				}
			}
		};
		chip.setToolTipText("Switch list or change its colour — right-click to rename, recolour or delete \"" + l.name + "\"");
		chip.setFocusPainted(false);
		chip.setOpaque(true);
		chip.setContentAreaFilled(true);
		chip.setBorderPainted(true);
		chip.setHorizontalAlignment(SwingConstants.LEFT);
		chip.setFont(chip.getFont().deriveFont(Font.BOLD, 12f));
		chip.setMargin(new java.awt.Insets(3, 7, 3, 7));
		chip.setForeground(Color.decode(l.color));
		chip.setBackground(HOVER_BG);
		chip.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Color.decode(l.color), 1),
			BorderFactory.createEmptyBorder(0, 0, 0, DROPDOWN_ARROW_INSET
				+ chip.getFontMetrics(chip.getFont()).stringWidth(DROPDOWN_ARROW) + 4)));
		chip.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		chip.addActionListener(e -> showListSwitcher(chip));
		chip.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e) { maybeShowMenu(e); }

			@Override
			public void mouseReleased(MouseEvent e) { maybeShowMenu(e); }

			private void maybeShowMenu(MouseEvent e)
			{
				if (e.isPopupTrigger())
				{
					listMenu(l).show(chip, e.getX(), e.getY());
				}
			}
		});
		return chip;
	}

	/**
	 * One list's own menu: rename it, recolour it, delete it. The dropdown's
	 * right-click opens it for the list shown, and a right-click on any list
	 * in the switcher opens it for that one.
	 *
	 * Its dialogs belong to this panel, not to the dropdown: the dropdown is
	 * rebuilt on every refresh (an inventory change, a price poll), and one
	 * thrown away while the menu was open left the rename box and the delete
	 * confirmation with no window to sit over.
	 */
	JPopupMenu listMenu(ListMeta l)
	{
		final Component parent = this;
		final JPopupMenu menu = new JPopupMenu();
		final JMenuItem rename = new JMenuItem("Rename list…");
		rename.addActionListener(a ->
		{
			String name = javax.swing.JOptionPane.showInputDialog(parent, "List name:", l.name);
			if (name != null && !name.trim().isEmpty())
			{
				actions.renameList(l.id, name.trim());
			}
		});
		menu.add(rename);
		/* Named dots, not hex codes: a dot and "#E5C158" told you the colour
		   only by the glyph's tint, and the text beside it was a number
		   nobody picks a colour by. */
		final JMenu colorMenu = new JMenu("Colour");
		for (int i = 0; i < FavoriteLists.PALETTE.length; i++)
		{
			final String hex = FavoriteLists.PALETTE[i];
			final JMenuItem swatch = new JMenuItem(FavoriteLists.PALETTE_NAMES[i],
				new Swatch(Color.decode(hex), hex.equalsIgnoreCase(l.color)));
			swatch.addActionListener(a -> actions.recolorList(l.id, hex));
			colorMenu.add(swatch);
		}
		menu.add(colorMenu);
		menu.addSeparator();
		final JMenuItem delete = new JMenuItem("Delete list…");
		final boolean deletable = lists.size() > 1;
		delete.setEnabled(deletable);
		if (!deletable)
		{
			delete.setToolTipText("There has to be at least one list");
		}
		/* Asked first. A list is all of its items, and this used to go on
		   one click from a menu that opens on a right-click. */
		delete.addActionListener(a ->
		{
			final int ok = javax.swing.JOptionPane.showConfirmDialog(parent,
				"Delete the list \"" + l.name + "\" and the items in it?", "Delete list",
				javax.swing.JOptionPane.OK_CANCEL_OPTION, javax.swing.JOptionPane.WARNING_MESSAGE);
			if (ok == javax.swing.JOptionPane.OK_OPTION)
			{
				actions.deleteList(l.id);
			}
		});
		menu.add(delete);
		return menu;
	}

	/**
	 * One list in the switcher. Left-click switches to it; right-click opens
	 * that list's own menu — "make it so you can do it from here".
	 *
	 * Not a plain JMenuItem, because Swing fires a menu item on the release
	 * of ANY button: a right-click would switch lists as well as opening the
	 * menu. The right button never reaches the item's own handling here; its
	 * release closes the switcher and opens the list's menu where it was.
	 */
	final class ListItem extends JMenuItem
	{
		private final ListMeta list;
		private final JPopupMenu switcher;

		ListItem(ListMeta list, boolean active, JPopupMenu switcher)
		{
			super((active ? "✓ " : " ") + list.name);
			this.list = list;
			this.switcher = switcher;
			setForeground(Color.decode(list.color));
			if (active)
			{
				setFont(getFont().deriveFont(Font.BOLD));
			}
			setToolTipText("Click to switch — right-click to rename, recolour or delete");
			addActionListener(a -> actions.selectList(list.id));
		}

		@Override
		protected void processMouseEvent(MouseEvent e)
		{
			final int id = e.getID();
			final boolean button = id == MouseEvent.MOUSE_PRESSED || id == MouseEvent.MOUSE_RELEASED
				|| id == MouseEvent.MOUSE_CLICKED;
			if (button && (e.getButton() == MouseEvent.BUTTON3 || SwingUtilities.isRightMouseButton(e)))
			{
				if (id == MouseEvent.MOUSE_RELEASED && contains(e.getPoint()))
				{
					openListMenu();
				}
				return;
			}
			super.processMouseEvent(e);
		}

		/** The switcher shut, and the list's menu open where the item was.
		 *  Placed against this panel, not the dropdown the switcher opened
		 *  from: a refresh while the switcher is open replaces the dropdown,
		 *  and a menu placed against the old one never appeared. */
		void openListMenu()
		{
			final Component host = FavoritesPanel.this;
			final java.awt.Point at = isShowing() && host.isShowing()
				? SwingUtilities.convertPoint(this, 0, getHeight() / 2, host) : null;
			switcher.setVisible(false);
			if (at != null)
			{
				listMenu(list).show(host, at.x, at.y);
			}
		}
	}

	/** Every list, current one marked — plus a "New list…" tail, which is
	 *  where a new list is made: the place you go to switch lists anyway. */
	private void showListSwitcher(JButton anchor)
	{
		final JPopupMenu menu = new JPopupMenu();
		for (ListMeta l : lists)
		{
			menu.add(new ListItem(l, l.id.equals(activeListId), menu));
		}
		final ListMeta current = activeList();
		if (current != null)
		{
			menu.addSeparator();
			menu.add(colourRow(current, menu));
		}
		menu.addSeparator();
		JMenuItem create = new JMenuItem("New list…");
		create.addActionListener(a -> promptNewList(this));
		menu.add(create);
		/* Says so, because nothing else would: nobody tries a right-click on
		   a menu item ("make it show you can right click delete a list"). */
		final JLabel hint = new JLabel("Right-click a list: rename, colour, delete");
		hint.setForeground(Brand.TEXT_STRUCTURAL);
		hint.setFont(hint.getFont().deriveFont(Font.PLAIN, 10.5f));
		hint.setBorder(BorderFactory.createEmptyBorder(4, 8, 3, 8));
		/* Centred like every other row of the menu, and free to fill it. A
		   label is left-aligned by default, and the menu's box layout, given
		   one row out of step, made itself wider by half its widest item and
		   pushed the hint to the right edge. */
		hint.setAlignmentX(Component.CENTER_ALIGNMENT);
		hint.setMaximumSize(new Dimension(Integer.MAX_VALUE, hint.getPreferredSize().height));
		menu.add(hint);
		menu.show(anchor, 0, anchor.getHeight());
	}

	/** The list the dropdown is showing: the active one, or the first when
	 *  the active id names no list. */
	private ListMeta activeList()
	{
		for (ListMeta l : lists)
		{
			if (l.id.equals(activeListId))
			{
				return l;
			}
		}
		return lists.isEmpty() ? null : lists.get(0);
	}

	/**
	 * The palette as dots, in the switcher, for the list it is showing.
	 *
	 * "make it so you can select the color of these lists". You always could,
	 * but only from the dropdown's RIGHT-click, a menu nothing points to, in
	 * a submenu of hex codes. The switcher is where the lists' colours are
	 * on show, so that is where choosing one goes. One click on a dot, and
	 * the menu closes on the new colour.
	 */
	JPanel colourRow(ListMeta l, JPopupMenu menu)
	{
		final JPanel wrap = new JPanel(new BorderLayout(0, 3));
		wrap.setOpaque(false);
		wrap.setBorder(BorderFactory.createEmptyBorder(3, 8, 4, 8));
		final String name = l.name.length() > 18 ? l.name.substring(0, 17) + "\u2026" : l.name;
		final JLabel caption = new JLabel("Colour of " + name);
		caption.setForeground(Brand.TEXT_STRUCTURAL);
		caption.setFont(caption.getFont().deriveFont(Font.PLAIN, 11f));
		wrap.add(caption, BorderLayout.NORTH);
		final int across = 6;
		final JPanel dots = new JPanel(new java.awt.GridLayout(
			(FavoriteLists.PALETTE.length + across - 1) / across, across, 3, 3));
		dots.setOpaque(false);
		for (int i = 0; i < FavoriteLists.PALETTE.length; i++)
		{
			final String hex = FavoriteLists.PALETTE[i];
			final JLabel dot = new JLabel(new Swatch(Color.decode(hex), hex.equalsIgnoreCase(l.color)));
			dot.setToolTipText(FavoriteLists.PALETTE_NAMES[i]);
			dot.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			/* On the release, and only if it lands on the dot: a click
			   proper is lost to the smallest wobble between press and
			   release, and these are small targets. */
			dot.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseReleased(MouseEvent e)
				{
					if (SwingUtilities.isLeftMouseButton(e) && dot.contains(e.getPoint()))
					{
						menu.setVisible(false);
						actions.recolorList(l.id, hex);
					}
				}
			});
			dots.add(dot);
		}
		/* WEST, so the dots keep their own size at the left rather than
		   spreading across however wide the longest list name made the menu. */
		wrap.add(dots, BorderLayout.WEST);
		return wrap;
	}

	/** A palette colour as a filled dot, ringed when it is the list's own.
	 *  Painted rather than a "\u25cf" glyph, so it is the same size whatever
	 *  font the menu falls back to. */
	static final class Swatch implements javax.swing.Icon
	{
		private static final int D = 12;
		private static final int PAD = 3;
		private final Color colour;
		private final boolean current;

		Swatch(Color colour, boolean current)
		{
			this.colour = colour;
			this.current = current;
		}

		boolean current()
		{
			return current;
		}

		@Override
		public int getIconWidth()
		{
			return D + 2 * PAD;
		}

		@Override
		public int getIconHeight()
		{
			return D + 2 * PAD;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			final Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(colour);
			g2.fillOval(x + PAD, y + PAD, D, D);
			if (current)
			{
				g2.setColor(Brand.TEXT_MAIN);
				g2.setStroke(new java.awt.BasicStroke(1.5f));
				g2.draw(new java.awt.geom.Ellipse2D.Float(x + 0.75f, y + 0.75f,
					D + 2 * PAD - 1.5f, D + 2 * PAD - 1.5f));
			}
			g2.dispose();
		}
	}

	private void promptNewList(java.awt.Component parent)
	{
		String name = javax.swing.JOptionPane.showInputDialog(parent, "New list name:", "Watchlist");
		if (name != null && !name.trim().isEmpty())
		{
			actions.createList(name.trim());
		}
	}

	/**
	 * Turn the range/spike badges and the row glow on or off.
	 *
	 * Both together, on purpose. The chip and the pulse are two renderings of
	 * one signal, and "quiet list" is what was asked for — a list that still
	 * breathes at you, just without saying why, is the worst of the two.
	 *
	 * Rebuilds immediately off the last rows rather than waiting for the next
	 * advisor cycle, which can be a minute away: a settings toggle that
	 * appears to do nothing for 60 seconds gets clicked again.
	 */
	public void setBadgesEnabled(boolean enabled)
	{
		if (this.badgesEnabled == enabled)
		{
			return;
		}
		this.badgesEnabled = enabled;
		rebuild(lastRows);
	}

	/** The rows' glow borders, on or off, rebuilt at once as the badges
	 *  switch is. The badges keep their colours either way. */
	public void setGlowEnabled(boolean enabled)
	{
		if (this.glowEnabled == enabled)
		{
			return;
		}
		this.glowEnabled = enabled;
		rebuild(lastRows);
	}

	/**
	 * Hide the watchlist behind a login message, the way the advisor box
	 * already is.
	 *
	 * A live-looking list under "Log in to the game" was incoherent, and it
	 * was not merely cosmetic: a Row carries what you HOLD of that item
	 * (fillHeldPosition — quantity, cost basis, what the stack would clear),
	 * and logged out there is no bank or inventory to read, so every one of
	 * those fields is silently empty. A row for a stack you own 11,000 of
	 * looked exactly like a row for something you have never touched. The
	 * prices and range badges were right; the holdings half was blank and
	 * said nothing about being blank.
	 *
	 * The GE slot strip, the search box and the list chips go with it: eight
	 * empty slots and an "add to this list" box above a list that is not shown
	 * are the same incoherence in smaller print.
	 */
	public void setLoggedIn(boolean loggedIn)
	{
		if (this.loggedIn == loggedIn)
		{
			return;
		}
		this.loggedIn = loggedIn;
		rebuild(lastRows);
	}

	/**
	 * Show these rows. Call on the Swing EDT.
	 *
	 * Rebuilt only when something on them has changed. Every inventory change
	 * lands here — each shark cooked, every few seconds — and a rebuild makes
	 * fresh rows whose glow and spike borders were bare until their timers'
	 * first tick, so the whole list flashed on every one: "every time i cook
	 * a shark, it flashes the colors on the side bar". Unchanged rows now
	 * leave the list as it is, glows and all.
	 */
	public void update(List<Row> favoriteRows)
	{
		final List<Row> next = favoriteRows != null ? favoriteRows : new ArrayList<>();
		if (built && sameRows(next, lastRows) && HIGH5D.equals(builtHigh) && LOW5D.equals(builtLow))
		{
			lastRows = next;
			return;
		}
		rebuild(next);
	}

	/** Whether the rows were built yet, and in which glow colours. */
	private boolean built;
	private Color builtHigh;
	private Color builtLow;

	/** Two lists of rows that would draw, and act, the same. */
	static boolean sameRows(List<Row> a, List<Row> b)
	{
		if (a == b)
		{
			return true;
		}
		if (a == null || b == null || a.size() != b.size())
		{
			return false;
		}
		for (int i = 0; i < a.size(); i++)
		{
			if (!sameRow(a.get(i), b.get(i)))
			{
				return false;
			}
		}
		return true;
	}

	/** Every field of a Row: the list draws some of them and a click hands
	 *  the rest to the inspection card. */
	static boolean sameRow(Row a, Row b)
	{
		if (a == b)
		{
			return true;
		}
		if (a == null || b == null)
		{
			return false;
		}
		return a.id == b.id && java.util.Objects.equals(a.name, b.name) && a.price == b.price
			&& Double.compare(a.changePct, b.changePct) == 0 && a.changeVsAverage == b.changeVsAverage && a.tier == b.tier
			&& a.targetBuy == b.targetBuy && a.targetSell == b.targetSell && a.heldSell == b.heldSell
			&& a.potentialProfit == b.potentialProfit
			&& a.limit == b.limit && a.limitUsed == b.limitUsed && a.limitResetsAt == b.limitResetsAt
			&& a.dailyVolume == b.dailyVolume && a.heldQty == b.heldQty
			&& java.util.Objects.equals(a.heldWhere, b.heldWhere) && a.listedQty == b.listedQty
			&& a.listedSold == b.listedSold && a.listedTotal == b.listedTotal && a.listedPrice == b.listedPrice
			&& a.bidQty == b.bidQty && a.bidFilled == b.bidFilled && a.bidPrice == b.bidPrice
			&& a.sellValue == b.sellValue && a.heldProfit == b.heldProfit && sameClearance(a.clearance, b.clearance)
			&& a.hasCostBasis == b.hasCostBasis && a.pricedQty == b.pricedQty && a.pricedCost == b.pricedCost;
	}

	private static boolean sameClearance(Clearance a, Clearance b)
	{
		if (a == null || b == null)
		{
			return a == b;
		}
		return a.qty == b.qty && a.flowPerDay == b.flowPerDay && Double.compare(a.days, b.days) == 0;
	}

	/** Build the list afresh from {@code favoriteRows}. */
	private void rebuild(List<Row> favoriteRows)
	{
		lastRows = favoriteRows;
		built = true;
		builtHigh = HIGH5D;
		builtLow = LOW5D;
		stopGlowTimers();
		rows.removeAll();
		north.setVisible(loggedIn);
		if (!loggedIn)
		{
			/* Silent, not captioned. The advisor's banner above already says
			   the one thing there is to say; repeating it here made the
			   logged-out sidebar a column of near-identical apologies. */
			resizeGrip.setVisible(false); // nothing to size; applyRowLimit is not reached
			revalidate();
			repaint();
			return;
		}
		if (favoriteRows.isEmpty())
		{
			JLabel empty = new JLabel("<html><center>No favorites yet.<br>Tap the star on a suggestion or flip to add one.</center></html>");
			empty.setForeground(Brand.TEXT_STRUCTURAL);
			empty.setFont(empty.getFont().deriveFont(12f));
			rows.add(empty);
		}
		// One child per row, no separate strut spacers — drag-to-reorder needs
		// rows.getComponents() to map 1:1 to favoriteRows' indices. The 2px
		// gap a strut used to provide is now baked into each row's own
		// bottom border instead (see row() / wirePulse()).
		for (int i = 0; i < favoriteRows.size(); i++)
		{
			rows.add(row(favoriteRows.get(i)));
		}
		for (java.awt.Component c : rows.getComponents())
		{
			final Object paint = c instanceof javax.swing.JComponent
				? ((javax.swing.JComponent) c).getClientProperty(PAINT_NOW) : null;
			if (paint instanceof Runnable)
			{
				((Runnable) paint).run();
			}
		}
		/* Re-apply after every rebuild, and it does the revalidate/repaint —
		   the rows are fresh components that know nothing about the limit. */
		applyRowLimit();
	}

	/** Matches the website's own .wl-item: name + price always visible, kept
	 *  lean by only revealing remove on hover (its .wl-fav-remove is
	 *  opacity:0 until :hover the same way) instead of permanently eating
	 *  row width — that's what was crushing names down to 4-5 characters. */
	private JPanel row(Row r)
	{
		// One line, readable: picture, name, and a 5-day extreme badge.
		// The LAST/EA/VOL stats line this briefly carried was 10px text in a
		// 225px sidebar — legible in a mockup, not in a running client. Those
		// numbers are one click away in the inspection card, which has the
		// room to show them at a readable size. Hover-only remove keeps the
		// name from being crushed to 4-5 characters the rest of the time.
		JPanel p = new JPanel(new BorderLayout(6, 0));
		p.setBackground(Brand.BG_PANEL);
		// Bottom padding carries the 2px gap a separate strut component used
		// to provide — dropped so rows.getComponents() maps 1:1 to
		// favoriteRows' indices, which drag-to-reorder depends on.
		p.setBorder(BorderFactory.createEmptyBorder(4, 7, 6, 6));

		p.add(iconLabel(r.id), BorderLayout.WEST);

		JPanel nameWrap = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		nameWrap.setOpaque(false);
		JLabel name = new JLabel(truncateName(r.name));
		/* Holdings live on the tooltip now, not on a second line. "8,917 ×
		   748 gp" under every stack you owned turned the watchlist into a
		   wall of digits, and the one thing this list is for — which items
		   are at an actionable price right now — got buried under arithmetic
		   you can do in the inspection card. The number is still worth
		   having, just on demand: hover the name. */
		name.setToolTipText(r.heldQty > 0 ? heldTooltip(r) : r.name);
		name.setForeground(Color.WHITE);
		name.setFont(name.getFont().deriveFont(13f));
		nameWrap.add(name);
		p.add(nameWrap, BorderLayout.CENTER);

		// Says in words what the pulsing border says in colour. The glow
		// alone can't be read at a glance once several rows are pulsing at
		// once, and it's invisible in a screenshot.
		final JPanel right = new JPanel(new BorderLayout(4, 0));
		right.setOpaque(false);
		/* The range badge owns this slot. The holdings tag used to take it and
		   lost on both counts: every held row read "\u2026 to sell", so the badges
		   stopped distinguishing anything, while the one signal that DOES vary
		   row to row \u2014 where the price sits in its own range \u2014 got crowded
		   out. Holdings are on the name's tooltip now. */
		final JLabel badge = badgeFor(r);
		if (badge != null)
		{
			right.add(badge, BorderLayout.CENTER);
		}
		p.add(right, BorderLayout.EAST);

		// Just the remove button now — reordering is drag-and-drop on the row
		// itself (see wireSelect), not a pair of ▲/▼ buttons. Those buttons
		// only ever got ADDED to `right` on hover, after the row's own
		// mouse listeners were already attached to its build-time children;
		// entering them (a component with no listener of its own) fired the
		// row's mouseExited — same background/click as leaving the row
		// entirely — which yanked the buttons back out from under the
		// cursor before a click could land. Drag sidesteps the whole class
		// of bug: no new component ever has to be entered mid-interaction.
		final JPanel actionsPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
		actionsPanel.setOpaque(false);
		JButton remove = new JButton("×");
		remove.setToolTipText("Remove " + r.name + " from favorites");
		remove.setMargin(new java.awt.Insets(0, 4, 0, 4));
		remove.addActionListener(e -> actions.remove(r.id));
		actionsPanel.add(remove);

		wireSelect(p, Brand.BG_PANEL, r, right, actionsPanel);
		/* Only the multi-day tiers glow. The day tier deliberately does not:
		   an item touches its own daily edge constantly, and a row that
		   breathes all day long stops meaning "look at this". */
		if (!badgesEnabled)
		{
			/* Nothing to wire. Left as its own branch rather than folded into
			   the conditions below so it reads as the switch it is. */
		}
		else if (Math.abs(r.changePct) >= SPIKE_THRESHOLD_PCT)
		{
			/* One timer drives the border AND the badge. Two would not just
			   cost twice the ticks; they would be free to drift out of phase,
			   and the whole point of giving the badge the border's palette is
			   that the two are the same colour at the same instant. */
			wireSpikeGlow(p, r.changePct >= 0, badge, glowEnabled);
		}
		else if (glowEnabled && r.tier != PriceExtremes.Tier.NONE
			&& r.tier != PriceExtremes.Tier.HIGH_1D && r.tier != PriceExtremes.Tier.LOW_1D)
		{
			wirePulse(p, r.tier.isHigh() ? HIGH5D : LOW5D);
		}
		return p;
	}

	/**
	 * What you hold, what it would clear, and whether that beats what you
	 * paid — the whole holdings story, on the item name's tooltip.
	 *
	 * This used to be a visible second line reading "11 \u00D7 6.79M gp". It is
	 * a tooltip now because the watchlist is where you scan for something to
	 * act on, and a quantity \u00D7 price on every stack you happen to own
	 * drowned that out. Hover keeps the number reachable without it competing
	 * with the range badges for the eye.
	 *
	 * Sale value here is the after-tax figure, and says so. The old headline
	 * deliberately showed the pre-tax unit price instead, so it would agree
	 * with what pocketge.com prints for the same item; with no headline left
	 * to match, the honest number wins.
	 */
	/**
	 * The badge for a row, or null when nothing is worth saying.
	 *
	 * Three weights, so the signal is legible without reading the words:
	 * <ul>
	 *   <li>spike — the live price is 15%+ away from its price a day ago.
	 *       Rare, and the only badge that animates: it cycles the same
	 *       palette as the row's border glow, green/gold climbing for a move
	 *       up and red/magenta for one down, so the colour says the
	 *       direction even before the number is read.
	 *   <li>5-day — bright text, in the top or bottom 8% of the 5-day range.
	 *   <li>1-day — a bare ▲ or ▼ in a muted shade. No label at all:
	 *       the arrow is the whole message, and spelling out "1D HIGH" on a
	 *       signal this common costs more width than it is worth.
	 * </ul>
	 * There is no 30-day tier. There was, briefly, and it fired on almost
	 * every row — see PriceExtremes.Tier for the arithmetic reason a wider
	 * window makes a percentage band commoner rather than rarer.
	 *
	 * Green means high and gold means low at every tier, here and on the
	 * website, so the colour never has to be re-learned per badge.
	 */
	private JLabel badgeFor(Row r)
	{
		if (!badgesEnabled)
		{
			return null;
		}
		if (Math.abs(r.changePct) >= SPIKE_THRESHOLD_PCT)
		{
			return spikeBadge(r.changePct, r.changeVsAverage);
		}
		return tierBadge(r.tier);
	}

	/**
	 * The website's multicolour "big swing" chip: how far the live price has
	 * run from its price a day ago, animated.
	 *
	 * This outranks the range tiers outright, exactly as the site's own
	 * dayState does — a 20% move in a day is a different kind of event from
	 * sitting near a 5-day edge, and while both are true the move is the one
	 * worth looking at. The row was already glowing for this; the number was
	 * the missing half, and a glow alone cannot be read in a screenshot or
	 * told apart once several rows are pulsing at once.
	 */
	private JLabel spikeBadge(double pct, boolean vsAverage)
	{
		final String on = vsAverage ? "on its 24-hour average" : "on the day";
		final boolean up = pct >= 0;
		final JLabel badge = new JLabel((up ? "▲ +" : "▼ ") + String.format("%.0f%%", pct));
		badge.setFont(badge.getFont().deriveFont(Font.BOLD, 10.5f));
		badge.setToolTipText(String.format(
			up ? "Spiking \u2014 up %.1f%% " + on : "Spiking \u2014 down %.1f%% " + on, Math.abs(pct)));
		/* Colour comes from wireSpikeGlow, which owns this row's one timer. */
		return badge;
	}

	private static JLabel tierBadge(PriceExtremes.Tier tier)
	{
		if (tier == null || tier == PriceExtremes.Tier.NONE)
		{
			return null;
		}
		final boolean high = tier.isHigh();
		final String text;
		final String why;
		if (tier == PriceExtremes.Tier.HIGH_5D || tier == PriceExtremes.Tier.LOW_5D)
		{
			text = high ? "▲ 5D HIGH" : "▼ 5D LOW";
			why = high
				? "In the top 8% of its 5-day price range"
				: "In the bottom 8% of its 5-day price range";
		}
		else
		{
			text = high ? "▲" : "▼";
			why = high
				? "At or above its 24-hour high \u2014 sell now to catch the peak"
				: "At or below its 24-hour low \u2014 buy now to catch the dip";
		}

		final JLabel badge = new JLabel(text);
		badge.setFont(badge.getFont().deriveFont(Font.BOLD, 10.5f));
		badge.setToolTipText(why);
		if (tier == PriceExtremes.Tier.HIGH_5D || tier == PriceExtremes.Tier.LOW_5D)
		{
			badge.setForeground(high ? HIGH5D : LOW5D);
		}
		else
		{
			badge.setForeground(high ? HIGH1D : LOW1D);
		}
		return badge;
	}

	private static String heldTooltip(Row r)
	{
		/* Names the item too, because this tooltip REPLACES the plain name
		   tooltip on a held row — and that tooltip is the only way to read a
		   name the row had to truncate. Escaped because Swing parses the
		   whole string as HTML: no live OSRS item name contains an ampersand
		   or an angle bracket today, but one that did would silently swallow
		   the rest of the tooltip. */
		final String safeName = r.name == null ? ""
			: r.name.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
		final StringBuilder sb = new StringBuilder("<html><b>").append(safeName)
			.append("</b><br>You hold <b>")
			.append(QuantityFormatter.quantityToStackSize(r.heldQty)).append("</b>.");
		if (r.sellValue > 0)
		{
			sb.append("<br>Selling the lot clears <b>")
				.append(QuantityFormatter.quantityToStackSize(r.sellValue))
				.append(" gp</b> after the 2% tax.");
		}
		if (r.hasCostBasis && r.heldProfit != 0)
		{
			final boolean partial = r.pricedQty > 0 && r.pricedQty < r.heldQty;
			/* The size, then the direction in words — "-550K gp less" was a
			   double negative. */
			sb.append("<br>That is <b>").append(QuantityFormatter.quantityToStackSize(Math.abs(r.heldProfit)))
				.append(" gp</b> ").append(r.heldProfit >= 0 ? "more" : "less").append(" than you paid")
				.append(partial ? " for the " + QuantityFormatter.quantityToStackSize(r.pricedQty)
					+ " the plugin watched you buy." : ".");
		}
		else if (r.heldQty > 0)
		{
			sb.append("<br>No purchase on record, so there is no profit to measure.");
		}
		return sb.append("</html>").toString();
	}


	/** Same 16-char cutoff the Top Suggestion card uses — the full name
	 *  is always still reachable via the tooltip. */
	private static String truncateName(String name)
	{
		if (name == null)
		{
			return "";
		}
		final int max = 16;
		return name.length() > max ? name.substring(0, max - 1) + "…" : name;
	}

	/** Mirrors the site's rs-pulse-green-bright / rs-pulse-gold-bright 2.2s
	 *  ease-in-out CSS animation on Favorites at a 5-day high/low: a Timer
	 *  eases the row's left accent border between a dim and full-bright
	 *  variant of the highlight color on every tick. */
	private void wirePulse(JPanel row, Color color)
	{
		final Color dim = new Color(color.getRed() / 4, color.getGreen() / 4, color.getBlue() / 4);
		final Runnable paint = () ->
		{
			final double phase = (System.currentTimeMillis() % PULSE_PERIOD_MS) / (double) PULSE_PERIOD_MS;
			final double eased = (1 - Math.cos(2 * Math.PI * phase)) / 2; // 0..1..0
			row.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 2, 0, 0, blend(dim, color, eased)),
				BorderFactory.createEmptyBorder(4, 5, 6, 6)));
		};
		/* Frame zero now, not at the first tick 60ms on: a row is never
		   painted bare. The phase runs off the clock, so a rebuilt row picks
		   the glow up exactly where the old one left it. */
		paint.run();
		final Timer timer = new Timer(60, e -> paint.run());
		timer.start();
		pulseTimers.add(timer);
	}

	private static Color blend(Color a, Color b, double t)
	{
		final int r = (int) (a.getRed() + (b.getRed() - a.getRed()) * t);
		final int g = (int) (a.getGreen() + (b.getGreen() - a.getGreen()) * t);
		final int bl = (int) (a.getBlue() + (b.getBlue() - a.getBlue()) * t);
		return new Color(r, g, bl);
	}

	/** A genuine price spike (±15%+ — see SPIKE_THRESHOLD_PCT) gets a full
	 *  border, not just the routine pulse's left accent, cycling through a
	 *  small palette rather than one color — OSRS's own rare-item shimmer
	 *  (party hats, 3rd age gear), but biased green/gold for a spike UP and
	 *  red/magenta for a spike DOWN so the color still says which way it
	 *  moved. Takes priority over the plain 5D pulse when both would apply
	 *  — a move this size is the more urgent signal of the two. */
	private void wireSpikeGlow(JPanel row, boolean up, JLabel badge, boolean border)
	{
		final Color[] palette = up ? SPIKE_UP_PALETTE : SPIKE_DOWN_PALETTE;
		if (border)
		{
			row.putClientProperty(SPIKE_ROW, Boolean.TRUE);
		}
		final Runnable paint = () ->
		{
			final double phase = (System.currentTimeMillis() % SPIKE_PERIOD_MS) / (double) SPIKE_PERIOD_MS;
			final double pos = phase * (palette.length - 1);
			final int i = Math.min(palette.length - 2, (int) pos);
			final Color c = blend(palette[i], palette[i + 1], pos - i);
			/* Asked every tick rather than once at build time: rows are
			   dragged into new orders, and the neighbour above can change
			   under a running timer. */
			if (border)
			{
				row.setBorder(spikeBorder(c, outlinedAbove(rows, row)));
			}
			if (badge != null)
			{
				badge.setForeground(c);
			}
		};
		/* Frame zero now, border and badge, not at the first tick 40ms on: a
		   rebuilt row painted bare, its badge in Swing's grey, was half of
		   the list flashing on every rebuild. The row is not in the list
		   yet, so rebuild paints it once more when it is (PAINT_NOW), for
		   the edge it shares with an outlined row above. */
		paint.run();
		if (border)
		{
			row.putClientProperty(PAINT_NOW, paint);
		}
		final Timer timer = new Timer(40, e -> paint.run());
		timer.start();
		pulseTimers.add(timer);
	}

	/** Marks a row wearing the full spike border — see outlinedAbove. */
	static final String SPIKE_ROW = "pocketge.spikeRow";
	/** A spike row's paint, run again once the row is in the list. */
	private static final String PAINT_NOW = "pocketge.paintNow";

	/**
	 * A spike row's border. Two of them stacked drew their touching edges
	 * twice, a 4px bar between them against 2px everywhere else ("these
	 * bars when stacked get double thick borders"). The lower one leaves
	 * its top edge to the row above and takes the 2px as padding instead,
	 * so every line is 2px and no row changes height.
	 */
	static javax.swing.border.Border spikeBorder(Color c, boolean shareTop)
	{
		return BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(shareTop ? 0 : 2, 2, 2, 2, c),
			BorderFactory.createEmptyBorder(shareTop ? 4 : 2, 5, 4, 4));
	}

	/** Whether the row directly above this one in the list is a spike row. */
	static boolean outlinedAbove(java.awt.Container rows, javax.swing.JComponent row)
	{
		final java.awt.Component[] all = rows.getComponents();
		for (int i = 1; i < all.length; i++)
		{
			if (all[i] == row)
			{
				final java.awt.Component above = all[i - 1];
				return above instanceof javax.swing.JComponent && above.isVisible()
					&& Boolean.TRUE.equals(((javax.swing.JComponent) above).getClientProperty(SPIKE_ROW));
			}
		}
		return false;
	}

	/** The row glows only. A rebuild must not touch the search debounce:
	 *  it would cancel the query someone typed a moment before. */
	private void stopGlowTimers()
	{
		for (Timer t : pulseTimers)
		{
			t.stop();
		}
		pulseTimers.clear();
	}

	/** Stops every glow Timer from the previous {@link #update} — otherwise
	 *  each refresh would leave the old ones ticking in the background
	 *  forever, still holding their (now-discarded) row panels alive. Also
	 *  called from the plugin's shutDown() so disabling the plugin doesn't
	 *  leave Timers running against a panel nobody can see anymore. */
	public void stopPulseTimers()
	{
		stopGlowTimers();
		/* The search debounce is a Timer too. It fires once and stops itself,
		   so it is not a leak, but on shutdown it can still be armed — and
		   running a search into a panel the user has just closed is work
		   nobody asked for. */
		if (searchDebounce != null)
		{
			searchDebounce.stop();
		}
	}

	private JLabel iconLabel(int itemId)
	{
		JLabel label = new JLabel();
		label.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
		label.setMinimumSize(new Dimension(ICON_SIZE, ICON_SIZE));
		label.setHorizontalAlignment(SwingConstants.CENTER);
		if (itemManager != null && itemId > 0)
		{
			/* Null-checked. ItemManager.getImage builds from the client's
			   item sprites, which are not loaded on the login screen — and
			   these panels render there. An NPE here does not just lose one
			   icon: it is thrown inside a row builder called from update(),
			   so it aborts the whole rebuild mid-list and takes the rest of
			   the panel with it. Same failure the getItemStats guard nearby
			   exists for. A missing icon is a blank square; a missing panel
			   reads as the plugin being broken. */
			final AsyncBufferedImage img = itemManager.getImage(itemId);
			if (img != null)
			{
				img.addTo(label);
			}
		}
		return label;
	}

	/** Clicking a row selects it as the item shown above the Recommended
	 *  Flip card (see AdvisorPanel.setSelectedItem); dragging it reorders the
	 *  list live. The list itself never changes on click, and this no longer
	 *  jumps straight to the browser either; opening the full chart is now
	 *  an explicit button in that view. Remove only gets ADDED to {@code
	 *  right} on hover (mirroring the site's opacity:0-until-:hover
	 *  .wl-fav-remove) — reclaiming that width the rest of the time is what
	 *  actually fixed names getting cut to 4-5 characters. Right-click
	 *  always works too, hover or not — the quickest way to remove a
	 *  favorite without having to land the mouse exactly on the tiny ×
	 *  button. */
	private void wireSelect(JPanel row, Color normalBg, Row r, JPanel right, JPanel actionsPanel)
	{
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setToolTipText("Click for details, drag to reorder, right-click to remove");

		// Swing mouse events target only the deepest component under the
		// cursor and don't bubble to ancestor listeners — a click (or hover)
		// landing on the remove button never reaches this (it has its own
		// listener, so that's fine), but neither does one on the icon or
		// name label, which DON'T have listeners of their own. The row
		// leaves almost no "bare background" (icon+name+change% between them
		// cover nearly the whole row), so row-only hover/click/drag was
		// really only reachable via a thin sliver of padding — register
		// interaction AND hover on every child present when the row is
		// built, not just the row itself.
		final Runnable unhover = () ->
		{
			row.setBackground(normalBg);
			right.remove(actionsPanel);
			right.revalidate();
			right.repaint();
		};
		MouseAdapter interaction = interactionAdapter(row, r, unhover);
		MouseAdapter hover = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(HOVER_BG);
				right.add(actionsPanel, BorderLayout.EAST);
				right.revalidate();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				/* Only when the pointer has really left the row. Moving from
				   the name onto the × button also "exits" the name, and acting
				   on that pulled the button out from under the cursor before a
				   click could land: the × showed, then vanished as you reached
				   it. Re-entering the button never got the chance to put it
				   back, because by then there was no button to enter. */
				java.awt.Point inRow = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), row);
				if (row.contains(inRow))
				{
					return;
				}
				unhover.run();
			}
		};

		row.addMouseListener(interaction);
		row.addMouseMotionListener(interaction);
		row.addMouseListener(hover);
		addMouseListenerToDescendants(row, interaction);
		addMouseMotionListenerToDescendants(row, interaction);
		addMouseListenerToDescendants(row, hover);
		// actionsPanel (the remove button) is added to `right` lazily on
		// hover rather than being a build-time child — attaching `hover` to
		// it too, ONCE here rather than every mouseEntered, is what actually
		// fixes "the × button appears but can't be clicked": without this,
		// moving the cursor onto the button (a component with no listener
		// of its own) registered as the mouse LEAVING the row — same
		// mouseExited that fires when you move off the row entirely — which
		// yanked the button back out from under the cursor before the click
		// could land. Re-entering it now is a no-op (already added, already
		// the hover background) instead of a removal.
		// addMouseListenerToDescendants only reaches actionsPanel's CHILDREN
		// (the button) — actionsPanel itself, i.e. the couple of pixels of
		// FlowLayout padding around the button, was still missing the
		// listener, so a click landing a hair off the button's exact bounds
		// hit that same bug again. Cover the panel itself too, not just what's
		// inside it.
		actionsPanel.addMouseListener(hover);
		addMouseListenerToDescendants(actionsPanel, hover);
	}

	/** Click selects the item, drag reorders it, right-click opens the
	 *  remove/reorder menu — one adapter so a drag can cleanly suppress the
	 *  click it would otherwise also fire on release. */
	private MouseAdapter interactionAdapter(JPanel row, Row r, Runnable unhover)
	{
		return new MouseAdapter()
		{
			private int pressY;
			private boolean dragging;

			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (dragging || SwingUtilities.isRightMouseButton(e))
				{
					return;
				}
				actions.selectItem(r);
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressY = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), rows).y;
				dragging = false;
				maybeShowMenu(e);
			}

			@Override
			public void mouseDragged(MouseEvent e)
			{
				if (!SwingUtilities.isLeftMouseButton(e))
				{
					return;
				}
				final int y = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), rows).y;
				if (!dragging)
				{
					// A few pixels of slack so an ordinary click doesn't
					// register as a drag from natural hand jitter.
					if (Math.abs(y - pressY) < 6)
					{
						return;
					}
					dragging = true;
					row.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
				}
				final int target = indexForY(y, row);
				final int current = indexOfComponent(rows, row);
				if (target >= 0 && target != current)
				{
					rows.remove(row);
					rows.add(row, target);
					rows.revalidate();
					rows.repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				if (dragging)
				{
					actions.reorderTo(r.id, indexOfComponent(rows, row));
				}
				maybeShowMenu(e);
			}

			private void maybeShowMenu(MouseEvent e)
			{
				if (!e.isPopupTrigger())
				{
					return;
				}
				final JPopupMenu menu = rowMenu(r);
				/* The pointer's move onto the menu "exits" the row at a point
				   still inside it, so mouseExited keeps the hover; if the menu
				   closes with the pointer off the row, nothing else clears it
				   now that an unchanged list is no longer rebuilt. */
				menu.addPopupMenuListener(new javax.swing.event.PopupMenuListener()
				{
					@Override
					public void popupMenuWillBecomeInvisible(javax.swing.event.PopupMenuEvent ev)
					{
						final java.awt.PointerInfo pi = java.awt.MouseInfo.getPointerInfo();
						if (pi == null)
						{
							return;
						}
						final java.awt.Point p = pi.getLocation();
						SwingUtilities.convertPointFromScreen(p, row);
						if (!row.contains(p))
						{
							unhover.run();
						}
					}

					@Override
					public void popupMenuWillBecomeVisible(javax.swing.event.PopupMenuEvent ev)
					{
					}

					@Override
					public void popupMenuCanceled(javax.swing.event.PopupMenuEvent ev)
					{
					}
				});
				// Show relative to whichever component (row or a descendant)
				// actually caught the event — e.getX()/getY() are already in
				// that component's own coordinate space, so this positions
				// correctly either way.
				menu.show(e.getComponent(), e.getX(), e.getY());
			}
		};
	}

	/** A watchlist row's right-click. */
	JPopupMenu rowMenu(Row r)
	{
		final JPopupMenu menu = new JPopupMenu();
		/* The charts first, because they are what you reach for mid-trade —
		   and because the other three all rearrange the list, which is a
		   different kind of intent. Both, as on the chart button: a new tab,
		   or the page you already have open ("lemme right click open pocket
		   ge chart here in favorites also"). */
		final JMenuItem chart = new JMenuItem("Open PocketGE chart");
		chart.addActionListener(a -> actions.openChartTab(r.name));
		menu.add(chart);
		final JMenuItem sendToTab = new JMenuItem(AdvisorPanel.SEND_TO_TAB);
		sendToTab.setToolTipText(AdvisorPanel.SEND_TO_TAB_TIP);
		sendToTab.addActionListener(a -> actions.sendChartToOpenTab(r.name));
		menu.add(sendToTab);
		menu.addSeparator();
		/* For every row, not this one: the borders are one setting, the
		   badges stay either way. */
		final JMenuItem glow = new JMenuItem(glowEnabled ? "Mute glow borders" : "Unmute glow borders");
		glow.setToolTipText(glowEnabled
			? "Stop every row's border glowing; the ▲/▼ and % badges stay, in colour"
			: "Let rows at a 5-day edge or in a big swing glow again");
		glow.addActionListener(a -> actions.setRowGlow(!glowEnabled));
		menu.add(glow);
		menu.addSeparator();
		final JMenuItem remove = new JMenuItem("Remove from favorites");
		remove.addActionListener(a -> actions.remove(r.id));
		menu.add(remove);
		final JMenuItem up = new JMenuItem("Move up");
		up.addActionListener(a -> actions.reorder(r.id, -1));
		menu.add(up);
		final JMenuItem down = new JMenuItem("Move down");
		down.addActionListener(a -> actions.reorder(r.id, 1));
		menu.add(down);
		return menu;
	}

	/** How many of rows' OTHER children (siblings, not the one being
	 *  dragged) have their vertical midpoint above y — i.e. the index a drop
	 *  at y should land at. */
	private int indexForY(int y, JPanel dragging)
	{
		int idx = 0;
		for (java.awt.Component c : rows.getComponents())
		{
			if (c == dragging)
			{
				continue;
			}
			if (y > c.getY() + c.getHeight() / 2)
			{
				idx++;
			}
			else
			{
				break;
			}
		}
		return idx;
	}

	private static int indexOfComponent(java.awt.Container container, java.awt.Component c)
	{
		java.awt.Component[] comps = container.getComponents();
		for (int i = 0; i < comps.length; i++)
		{
			if (comps[i] == c)
			{
				return i;
			}
		}
		return -1;
	}

	private static void addMouseListenerToDescendants(java.awt.Container container, MouseAdapter listener)
	{
		for (java.awt.Component child : container.getComponents())
		{
			child.addMouseListener(listener);
			if (child instanceof java.awt.Container)
			{
				addMouseListenerToDescendants((java.awt.Container) child, listener);
			}
		}
	}

	private static void addMouseMotionListenerToDescendants(java.awt.Container container, MouseAdapter listener)
	{
		for (java.awt.Component child : container.getComponents())
		{
			child.addMouseMotionListener(listener);
			if (child instanceof java.awt.Container)
			{
				addMouseMotionListenerToDescendants((java.awt.Container) child, listener);
			}
		}
	}

}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Pure logic (no RuneLite types — unit-testable) behind the plugin's "Find
 * Opportunities" panel — the same three live categories pocketge.com's
 * sidebar shows (High Vol Margins, Low Vol Margins, Biggest Losers 24H),
 * computed from data the advisor cycle already fetches every run
 * (fetchLatest/fetch24hAverages/fetchVolumes) — no extra API calls. Mirrors
 * the math in pocketge.com's finder-common.js exactly so the numbers agree
 * with the website.
 *
 * Reliable 14-Day Margins isn't computed here: it needs a 14-day historical
 * scan across many items, which would mean a much heavier one-time fetch
 * than anything else this file does — real cost for a client that's meant
 * to sit in the background during gameplay. pocketge.com's own version of
 * that one stays a methodology page rather than a live list for the same
 * reason. At 5D Highs/Lows below IS computed, but only across whatever
 * bounded candidate pool the caller already fetched 5-day extremes for
 * (see PocketGeTrackerPlugin.refreshDayExtremes) — never the whole item
 * universe.
 */
public final class FinderEngine
{
	private FinderEngine() {}

	private static final long LOW_VOL_THRESHOLD = 100_000;
	/** Same "near the extreme" definition as the Favorites list's own ▲/▼
	 *  5D badge (see PocketGeTrackerPlugin.refreshStatsAndFavorites) — kept
	 *  in sync by hand since that one runs inline against a single row
	 *  rather than through this file. */
	private static final double EXTREME_BAND_PCT = 0.08;
	private static final double EXTREME_MIN_RANGE_PCT = 0.03;

	public static class Row
	{
		public int id;
		public long margin;  // gp, after tax — set for margin rows, 0 otherwise
		public double pct;   // meaning depends on the list: mover rows use it as live-vs-24h-avg %; extreme rows use it as % distance from the 5D high/low (0 = at the exact extreme)
		public long vol;
	}

	/** High/Low Vol Margins — live insta-buy/insta-sell spread after tax,
	 *  split by daily volume tier. Both sides need a recent print (24h
	 *  volume > 0) and the margin can't be an absurd >70%-of-price outlier
	 *  (usually a stale/bad print), same filters as the website. */
	public static List<Row> marginRows(Map<Integer, Advisor.Quote> quotes, Map<Integer, AnalystRating.Average> averages,
		Map<Integer, Long> volumes, boolean wantLowVol)
	{
		final List<Row> out = new ArrayList<>();
		for (Map.Entry<Integer, Advisor.Quote> e : quotes.entrySet())
		{
			final int id = e.getKey();
			final Advisor.Quote q = e.getValue();
			if (q == null || !(q.high > 0) || !(q.low > 0) || q.high <= q.low)
			{
				continue;
			}
			final AnalystRating.Average avg = averages.get(id);
			if (avg == null || !(avg.highPriceVolume > 0) || !(avg.lowPriceVolume > 0))
			{
				continue;
			}
			final long margin = q.high - q.low - FlipTracker.taxPerItem(q.high, id);
			if (margin <= 0 || margin >= q.high * 0.7)
			{
				continue;
			}
			final long vol = volumes.getOrDefault(id, 0L);
			final boolean lowVol = vol < LOW_VOL_THRESHOLD;
			if (lowVol != wantLowVol)
			{
				continue;
			}
			final Row r = new Row();
			r.id = id;
			r.margin = margin;
			r.vol = vol;
			out.add(r);
		}
		out.sort((a, b) -> Long.compare(b.margin, a.margin));
		return out;
	}

	/** Biggest Losers (24H) — live mid price vs its 24h volume-weighted
	 *  average mid, down at least 3%. Volume floor matches the low-vol
	 *  threshold so a single seller's dump on a thin item can't fake a
	 *  drop — the same reasoning as the website's own Biggest Losers list. */
	public static List<Row> loserRows(Map<Integer, Advisor.Quote> quotes, Map<Integer, AnalystRating.Average> averages,
		Map<Integer, Long> volumes)
	{
		final List<Row> out = new ArrayList<>();
		for (Map.Entry<Integer, Advisor.Quote> e : quotes.entrySet())
		{
			final int id = e.getKey();
			final Advisor.Quote q = e.getValue();
			if (q == null || !(q.high > 0) || !(q.low > 0))
			{
				continue;
			}
			final AnalystRating.Average avg = averages.get(id);
			if (avg == null || !(avg.avgHighPrice > 0) || !(avg.avgLowPrice > 0))
			{
				continue;
			}
			final double curMid = (q.high + q.low) / 2.0;
			final double avgMid = (avg.avgHighPrice + avg.avgLowPrice) / 2.0;
			if (!(avgMid > 0))
			{
				continue;
			}
			final double pct = (curMid - avgMid) / avgMid * 100.0;
			final long vol = volumes.getOrDefault(id, 0L);
			final long printVol = avg.highPriceVolume + avg.lowPriceVolume;
			if (curMid < 100 || printVol < LOW_VOL_THRESHOLD || pct > -3)
			{
				continue;
			}
			final Row r = new Row();
			r.id = id;
			r.pct = pct;
			r.vol = vol;
			out.add(r);
		}
		out.sort((a, b) -> Double.compare(a.pct, b.pct));
		return out;
	}

	/** At 5D Highs — live insta-sell price within EXTREME_BAND_PCT of its
	 *  own 5-day high, scanned across whatever candidate pool the caller
	 *  passes in {@code extremes} for (favorites plus a bounded top-volume
	 *  pool — see PocketGeTrackerPlugin.refreshDayExtremes). Sorted closest
	 *  to the high first. */
	public static List<Row> extremeHighRows(Map<Integer, Advisor.Quote> quotes, Map<Integer, PriceExtremes> extremes,
		Map<Integer, Long> volumes)
	{
		final List<Row> out = new ArrayList<>();
		for (Map.Entry<Integer, PriceExtremes> e : extremes.entrySet())
		{
			final int id = e.getKey();
			final PriceExtremes ex = e.getValue();
			final Advisor.Quote q = quotes.get(id);
			if (ex == null || q == null || !(q.high > 0) || !(ex.hi5d > 0) || !(ex.lo5d > 0))
			{
				continue;
			}
			final double range5d = ex.hi5d - ex.lo5d;
			if (range5d < ex.lo5d * EXTREME_MIN_RANGE_PCT)
			{
				continue; // near-flat item — a small wobble shouldn't count as "at the high"
			}
			final double distance = (ex.hi5d - q.high) / range5d;
			if (distance < 0 || distance > EXTREME_BAND_PCT)
			{
				continue;
			}
			final Row r = new Row();
			r.id = id;
			r.pct = distance * 100.0;
			r.vol = volumes.getOrDefault(id, 0L);
			out.add(r);
		}
		out.sort((a, b) -> Double.compare(a.pct, b.pct));
		return out;
	}

	/** At 5D Lows — the same definition as extremeHighRows, mirrored onto
	 *  the live insta-buy price against the 5-day low. */
	public static List<Row> extremeLowRows(Map<Integer, Advisor.Quote> quotes, Map<Integer, PriceExtremes> extremes,
		Map<Integer, Long> volumes)
	{
		final List<Row> out = new ArrayList<>();
		for (Map.Entry<Integer, PriceExtremes> e : extremes.entrySet())
		{
			final int id = e.getKey();
			final PriceExtremes ex = e.getValue();
			final Advisor.Quote q = quotes.get(id);
			if (ex == null || q == null || !(q.low > 0) || !(ex.hi5d > 0) || !(ex.lo5d > 0))
			{
				continue;
			}
			final double range5d = ex.hi5d - ex.lo5d;
			if (range5d < ex.lo5d * EXTREME_MIN_RANGE_PCT)
			{
				continue;
			}
			final double distance = (q.low - ex.lo5d) / range5d;
			if (distance < 0 || distance > EXTREME_BAND_PCT)
			{
				continue;
			}
			final Row r = new Row();
			r.id = id;
			r.pct = distance * 100.0;
			r.vol = volumes.getOrDefault(id, 0L);
			out.add(r);
		}
		out.sort((a, b) -> Double.compare(a.pct, b.pct));
		return out;
	}
}

package com.pocketge.tracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The plugin-side "Find Opportunities" section — same idea as
 * pocketge.com's sidebar scanner, collapsed under one header by default so
 * it doesn't compete with Favorites for space. Every category FinderEngine
 * computes (High Vol Margins, Low Vol Margins, Biggest Losers 24H, At 5D
 * Highs, At 5D Lows) — see FinderEngine's own doc comment for why Reliable
 * 14D Margins alone isn't here.
 */
public class FinderPanel extends JPanel
{
	public interface Actions
	{
		void addFavorite(int itemId, String name);
		/** Add to a NAMED list rather than whichever is active. Null listId
		 *  means the active one, so this also covers the single-list case. */
		void addFavoriteToList(String listId, int itemId, String name);
		/** Show this item in the inspection card above, the same thing a
		 *  watchlist row's click does. The item need not be a favourite — the
		 *  plugin builds a row for it either way. */
		void inspectItem(int itemId, String name);
		/** See AdvisorPanel.Actions.openChart — routed through the plugin so
		 *  an already-open PocketGE tab is reused rather than a new one
		 *  opened over whatever you were looking at. */
		void openChart(String itemName);
		/** Open the chart, unconditionally — see FavoritesPanel.Actions. The
		 *  left-click path is gated; a menu entry that says "Open PocketGE
		 *  chart" must not be. */
		default void openChartTab(String itemName)
		{
			openChart(itemName);
		}
		/** See FavoritesPanel.Actions.sendChartToOpenTab. */
		default void sendChartToOpenTab(String itemName)
		{
			openChartTab(itemName);
		}
	}

	/** One resolved row — id/name already looked up, metric already
	 *  formatted (margin gp or a % string) so this panel doesn't need to
	 *  know which category it's rendering. */
	public static class Row
	{
		public int id;
		public String name;
		public String metricText;
		public Color metricColor;
		/** HIGH_5D or LOW_5D on the 5-day lists: the metric then takes the
		 *  theme's sell or buy colour when it is drawn, as the watchlist's
		 *  own 5D badge does, rather than a colour fixed when the row was
		 *  built. NONE uses metricColor. */
		public PriceExtremes.Tier tier = PriceExtremes.Tier.NONE;
		public long vol;
	}

	/**
	 * The colour a row's metric is drawn in.
	 *
	 * The two 5-day lists were a fixed green and amber from before there was
	 * a theme, so a favourited item at a 5-day high read "▲ 5D HIGH" in the
	 * theme's blue on the watchlist and in green a little further down, in
	 * the same sidebar.
	 */
	static Color colourOf(Row r)
	{
		if (r.tier == PriceExtremes.Tier.HIGH_5D)
		{
			return FavoritesPanel.HIGH5D;
		}
		if (r.tier == PriceExtremes.Tier.LOW_5D)
		{
			return FavoritesPanel.LOW5D;
		}
		return r.metricColor != null ? r.metricColor : Brand.TEXT_STRUCTURAL;
	}

	private static final Color POSITIVE = new Color(0x1F, 0xB8, 0x5C);
	/** The open group's heading and its accent stripe — the panel's existing
	 *  body text and brand gold, no new colours. */
	private static final Color ROW_TEXT = new Color(0xD9, 0xD3, 0xC7);
	private static final Color OPEN_ACCENT = new Color(0xE5, 0xC1, 0x58);
	private static final Color NEGATIVE = new Color(0xEF, 0x53, 0x50);
	private static final int ICON_SIZE = 18;

	private final ItemManager itemManager;
	private final Actions actions;
	/** The watchlists a row can be added to, newest snapshot from the plugin.
	 *  Empty until the first refresh, in which case the menu falls back to a
	 *  plain "Add to favorites" against the active list. */
	private java.util.List<FavoritesPanel.ListMeta> lists = new java.util.ArrayList<>();
	private String activeListId;
	private final JPanel body = new JPanel();
	/** The header's own text, so it can say why the section is empty rather
	 *  than sitting there looking broken. */
	private JLabel titleLabel;
	private boolean loggedIn = true;
	private final Group highVol = new Group("High Vol Margins");
	private final Group lowVol = new Group("Low Vol Margins");
	private final Group losers = new Group("Biggest Losers (24H)");
	private final Group at5dHigh = new Group("At 5D Highs");
	private final Group at5dLow = new Group("At 5D Lows");
	private boolean open = false;
	/** Held so the cursor over it can stop promising a click that does
	 *  nothing while logged out. */
	private final JPanel header = new JPanel(new BorderLayout());

	public FinderPanel(ItemManager itemManager, Actions actions)
	{
		this.itemManager = itemManager;
		this.actions = actions;
		setLayout(new BorderLayout());
		setOpaque(false);

		// Plain text, not an emoji glyph — font fallback for emoji is
		// inconsistent across the JREs RuneLite runs on (same reasoning as
		// AdvisorPanel's chart/share icons, which are drawn instead).
		final JLabel headerLabel = new JLabel("Find Opportunities");
		headerLabel.setForeground(Brand.TEXT_STRUCTURAL);
		headerLabel.setFont(headerLabel.getFont().deriveFont(Font.BOLD, 12f));
		header.setBorder(BorderFactory.createEmptyBorder(4, 2, 4, 2));
		header.setBackground(Brand.BG_INPUT);
		titleLabel = headerLabel;
		header.add(headerLabel, BorderLayout.WEST);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);
		body.setVisible(open);
		body.add(highVol);
		body.add(lowVol);
		body.add(losers);
		body.add(at5dHigh);
		body.add(at5dLow);

		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (!loggedIn)
				{
					/* Inert while logged out. Logging out collapsed this
					   section but left the header clickable, so it could still
					   be opened onto five sub-headings each reading "Nothing
					   qualifying right now" — an empty answer to a question
					   the plugin cannot ask, since the finder ranks against
					   what you can afford and there is no cash to read. */
					return;
				}
				open = !open;
				body.setVisible(open);
				revalidate();
				repaint();
			}
		});

		add(header, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
	}

	/** Rebuild every group. Call on the EDT. Each list should already be
	 *  capped (top 10ish) and resolved to display rows by the caller. */
	/** The watchlists the right-click menu can add to. Pushed from the plugin
	 *  on the same refresh that updates FavoritesPanel's own list chips, so
	 *  the two can never disagree about which lists exist. */
	/**
	 * Close and relabel the section between logout and the next login.
	 *
	 * These lists are built from the advisor's price snapshot, which needs a
	 * live client — logged out they are whatever was last computed, or
	 * nothing, and either way they are not opportunities. Rather than a
	 * heading over five empty groups, the heading itself says what is
	 * missing, matching what the watchlist and the stats header now do.
	 */
	public void setLoggedIn(boolean loggedIn)
	{
		if (this.loggedIn == loggedIn)
		{
			return;
		}
		this.loggedIn = loggedIn;
		if (titleLabel != null)
		{
			/* Keeps its name logged out. It collapses anyway (below), so the
			   heading is all you see — and a heading that turns into a third
			   copy of "log in" is noise next to the one banner up top. */
			titleLabel.setText("Find Opportunities");
		}
		/* The pointer stops offering a click the header will refuse. */
		header.setCursor(Cursor.getPredefinedCursor(
			loggedIn ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
		if (!loggedIn)
		{
			/* Collapsed as well as emptied. Left open it is five sub-headings
			   with "nothing right now" under each, which reads as a broken
			   scanner rather than a logged-out one. */
			open = false;
			body.setVisible(false);
			update(new java.util.ArrayList<>(), new java.util.ArrayList<>(), new java.util.ArrayList<>(),
				new java.util.ArrayList<>(), new java.util.ArrayList<>());
		}
		revalidate();
		repaint();
	}

	public void updateLists(List<FavoritesPanel.ListMeta> listMetas, String activeId)
	{
		this.lists = listMetas != null ? listMetas : new java.util.ArrayList<>();
		this.activeListId = activeId;
	}

	public void update(List<Row> highVolRows, List<Row> lowVolRows, List<Row> loserRows,
		List<Row> at5dHighRows, List<Row> at5dLowRows)
	{
		if (!loggedIn)
		{
			/* A refresh can still land after logout — the advisor cycle runs on
			   its own timer. Dropping it keeps the section empty rather than
			   letting stale rows reappear a few seconds later. */
			highVolRows = lowVolRows = loserRows = at5dHighRows = at5dLowRows = new java.util.ArrayList<>();
		}
		highVol.setRows(highVolRows);
		lowVol.setRows(lowVolRows);
		losers.setRows(loserRows);
		at5dHigh.setRows(at5dHighRows);
		at5dLow.setRows(at5dLowRows);
		drawnHigh = FavoritesPanel.HIGH5D;
		drawnLow = FavoritesPanel.LOW5D;
		revalidate();
		repaint();
	}

	/** The 5-day colours the rows on screen were drawn in. */
	private Color drawnHigh = FavoritesPanel.HIGH5D;
	private Color drawnLow = FavoritesPanel.LOW5D;

	/**
	 * Redraw the 5-day lists if the theme has changed since they were drawn.
	 * Call on the EDT after a settings change. The rows come from the advisor
	 * cycle, which can be a minute off; a theme picked now should not leave
	 * these in the old one until then.
	 */
	public void retheme()
	{
		if (FavoritesPanel.HIGH5D.equals(drawnHigh) && FavoritesPanel.LOW5D.equals(drawnLow))
		{
			return;
		}
		drawnHigh = FavoritesPanel.HIGH5D;
		drawnLow = FavoritesPanel.LOW5D;
		at5dHigh.setRows(at5dHigh.data);
		at5dLow.setRows(at5dLow.data);
		revalidate();
		repaint();
	}

	private JLabel iconLabel(int itemId)
	{
		JLabel label = new JLabel();
		label.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
		label.setMinimumSize(new Dimension(ICON_SIZE, ICON_SIZE));
		label.setHorizontalAlignment(SwingConstants.CENTER);
		if (itemManager != null && itemId > 0)
		{
			/* Null-checked. ItemManager.getImage builds from the client's
			   item sprites, which are not loaded on the login screen — and
			   these panels render there. An NPE here does not just lose one
			   icon: it is thrown inside a row builder called from update(),
			   so it aborts the whole rebuild mid-list and takes the rest of
			   the panel with it. Same failure the getItemStats guard nearby
			   exists for. A missing icon is a blank square; a missing panel
			   reads as the plugin being broken. */
			final AsyncBufferedImage img = itemManager.getImage(itemId);
			if (img != null)
			{
				img.addTo(label);
			}
		}
		return label;
	}

	private static String truncateName(String name)
	{
		final int max = 18;
		return name.length() > max ? name.substring(0, max - 1) + "…" : name;
	}

	/** One nested collapsible sub-section — its own header (name only, no
	 *  icon/chevron needed at this depth) + a stack of rows, or a small
	 *  "nothing right now" line when empty. Collapsed by default, same as
	 *  the outer Find Opportunities wrapper. */
	private class Group extends JPanel
	{
		private final JPanel rows = new JPanel();
		private boolean groupOpen = false;
		/** Held so the chevron and weight can be repainted on toggle; the bare
		 *  name is kept apart from the label text because that text carries the
		 *  chevron and would otherwise accumulate one per click. */
		private JLabel titleLabel;
		private String groupTitle;

		Group(String title)
		{
			setLayout(new BorderLayout());
			setOpaque(false);
			setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 0));

			/*
			 * The five headings were identical grey text whether open or shut,
			 * so a long expanded list left no way to tell which of them you
			 * were reading — scroll far enough and the heading that owns the
			 * rows is off-screen anyway, and the four that do not look exactly
			 * the same as the one that does.
			 *
			 * A chevron says which is open, matching the one the card section
			 * above already uses, and the open heading brightens to the row
			 * text colour so it reads as the parent of what is under it.
			 */
			this.titleLabel = new JLabel(title);
			this.groupTitle = title;
			titleLabel.setFont(titleLabel.getFont().deriveFont(11f));
			titleLabel.setBorder(BorderFactory.createEmptyBorder(3, 0, 3, 0));
			titleLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

			rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
			rows.setOpaque(false);
			rows.setVisible(groupOpen);
			/* An accent stripe down the left of the open group's rows, so the
			   block and its heading are visibly one thing even when the
			   heading has scrolled out of view. */
			rows.setBorder(BorderFactory.createMatteBorder(0, 2, 0, 0, OPEN_ACCENT));

			titleLabel.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					groupOpen = !groupOpen;
					rows.setVisible(groupOpen);
					paintTitle();
					FinderPanel.this.revalidate();
					FinderPanel.this.repaint();
				}
			});
			paintTitle();

			add(titleLabel, BorderLayout.NORTH);
			add(rows, BorderLayout.CENTER);
		}

		/** Chevron, weight and colour all following the open state. */
		private void paintTitle()
		{
			titleLabel.setText((groupOpen ? "\u25BE  " : "\u25B8  ") + groupTitle);
			titleLabel.setForeground(groupOpen ? ROW_TEXT : Brand.TEXT_STRUCTURAL);
			titleLabel.setFont(titleLabel.getFont().deriveFont(
				groupOpen ? Font.BOLD : Font.PLAIN, 11f));
			rows.setBorder(BorderFactory.createMatteBorder(0, groupOpen ? 2 : 0, 0, 0, OPEN_ACCENT));
		}

		/** What is on screen, for retheme(). */
		private List<Row> data;

		void setRows(List<Row> data)
		{
			this.data = data;
			rows.removeAll();
			if (data == null || data.isEmpty())
			{
				JLabel empty = new JLabel("Nothing qualifying right now");
				empty.setForeground(Brand.TEXT_STRUCTURAL);
				empty.setFont(empty.getFont().deriveFont(10.5f));
				empty.setBorder(BorderFactory.createEmptyBorder(2, 4, 4, 0));
				rows.add(empty);
				return;
			}
			for (Row r : data)
			{
				rows.add(row(r));
			}
		}

		private JPanel row(Row r)
		{
			JPanel p = new JPanel(new BorderLayout(6, 0));
			p.setOpaque(false);
			p.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 4));
			p.add(iconLabel(r.id), BorderLayout.WEST);
			JLabel name = new JLabel(truncateName(r.name));
			name.setToolTipText(r.name);
			name.setForeground(Color.WHITE);
			name.setFont(name.getFont().deriveFont(11.5f));
			p.add(name, BorderLayout.CENTER);
			JLabel metric = new JLabel(r.metricText);
			metric.setForeground(colourOf(r));
			metric.setFont(metric.getFont().deriveFont(Font.BOLD, 11f));
			p.add(metric, BorderLayout.EAST);
			p.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			p.setToolTipText("Open the live " + r.name + " chart on PocketGE — right-click to favorite it");
			p.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (javax.swing.SwingUtilities.isRightMouseButton(e))
					{
						return;
					}
					/* Inspect, don't launch a browser. Clicking a finder row
					   used to leave the game entirely, which is a heavy answer
					   to "what is this thing" — and it was the only list in the
					   panel that behaved that way. It now does what a watchlist
					   row does: fills the card above with the item's targets
					   and margin. The chart is still one right-click away. */
					actions.inspectItem(r.id, r.name);
				}

				@Override
				public void mousePressed(MouseEvent e) { maybeShowMenu(e); }

				@Override
				public void mouseReleased(MouseEvent e) { maybeShowMenu(e); }

				private void maybeShowMenu(MouseEvent e)
				{
					if (!e.isPopupTrigger())
					{
						return;
					}
					JPopupMenu menu = new JPopupMenu();
					JMenuItem chart = new JMenuItem("Open PocketGE chart");
					chart.addActionListener(a -> actions.openChartTab(r.name));
					menu.add(chart);
					JMenuItem sendToTab = new JMenuItem(AdvisorPanel.SEND_TO_TAB);
					sendToTab.setToolTipText(AdvisorPanel.SEND_TO_TAB_TIP);
					sendToTab.addActionListener(a -> actions.sendChartToOpenTab(r.name));
					menu.add(sendToTab);
					menu.addSeparator();
					/* One list, one menu item. Several, a submenu naming each —
					   "Add to favorites" is a lie when there are four lists and
					   it silently picks one, and the star button on cards
					   already has that problem. The active list is marked so
					   the default is never a guess. */
					if (lists.size() > 1)
					{
						final javax.swing.JMenu addTo = new javax.swing.JMenu("Add to watchlist");
						for (FavoritesPanel.ListMeta l : lists)
						{
							final JMenuItem one = new JMenuItem(
								l.id != null && l.id.equals(activeListId) ? l.name + "  (active)" : l.name);
							one.addActionListener(a -> actions.addFavoriteToList(l.id, r.id, r.name));
							addTo.add(one);
						}
						menu.add(addTo);
						menu.show(e.getComponent(), e.getX(), e.getY());
						return;
					}
					JMenuItem fav = new JMenuItem("Add to watchlist");
					fav.addActionListener(a -> actions.addFavorite(r.id, r.name));
					menu.add(fav);
					menu.show(p, e.getX(), e.getY());
				}
			});
			return p;
		}
	}
}

package com.pocketge.tracker;

/**
 * A completed (or partially completed) flip: sell fills matched against
 * earlier buy fills of the same item — the newest bought before the sell was
 * listed, this character's, none still in a GE box (FlipTracker.charge).
 * Profit is AFTER GE tax.
 */
public class Flip
{
	/**
	 * When the capital in this flip was committed — the fill time of the
	 * OLDEST buy lot it closed — or 0 when that is not known.
	 *
	 * Oldest rather than an average, because the matching already decided
	 * which lots this flip consumed and {@link #buySpent} is computed from
	 * those same lots. Reading the cost from one set of lots and the clock from another
	 * would let the two disagree; this way "held 40 minutes at 20.1M" refers
	 * throughout to the same units.
	 *
	 * 0 means genuinely unknown, never "instant": a lot bought before the
	 * plugin recorded buy times, or a stack it never watched you buy at all.
	 * Callers must show that as nothing rather than as a zero duration — see
	 * {@link #holdMillis()}, which refuses to return one.
	 */
	/**
	 * Which Grand Exchange offer this came out of, or 0 when that is not
	 * recorded — every flip booked before offers were tokenised, and every
	 * ledger line written then.
	 *
	 * The Exchange fills one sell offer in as many chunks as it finds buyers
	 * for, so one trade of 8,218 adamantite bars arrives as five separate
	 * fills and books five flips. They are five real, correctly-priced flips;
	 * the tax and the cost basis on each are exact. But they are ONE thing
	 * you did, and a history that lists them as five — "2 x Adamantite bar,
	 * +22 gp" among them — reports activity instead of trades.
	 *
	 * This is the seam. Rows sharing a token are the same offer, so the panel
	 * can show one line and the stats can count one flip, without the money
	 * path having to defer anything: matching still happens per fill, exactly
	 * when it did before, which is what keeps a crash mid-offer from losing or
	 * duplicating gold.
	 */
	public final long offerId;
	public final long openedAt;
	public final long closedAt;    // epoch millis of the closing sell fill
	public final int itemId;
	public final String itemName;
	public final int quantity;
	public final long buySpent;    // total gp paid for the matched buys
	public final long sellGross;   // total gp received before tax
	public final long tax;         // GE tax on the sale
	public final long profit;      // sellGross - tax - buySpent

	public Flip(long offerId, long openedAt, long closedAt, int itemId, String itemName, int quantity,
		long buySpent, long sellGross, long tax)
	{
		this.offerId = offerId;
		this.openedAt = openedAt;
		this.closedAt = closedAt;
		this.itemId = itemId;
		this.itemName = itemName;
		this.quantity = quantity;
		this.buySpent = buySpent;
		this.sellGross = sellGross;
		this.tax = tax;
		this.profit = sellGross - tax - buySpent;
	}

	/** A flip from no identified offer — nothing groups with it. */
	public Flip(long openedAt, long closedAt, int itemId, String itemName, int quantity,
		long buySpent, long sellGross, long tax)
	{
		this(0L, openedAt, closedAt, itemId, itemName, quantity, buySpent, sellGross, tax);
	}

	/** A flip whose buy time is not known — every flip booked before the
	 *  tracker started recording one, and every flip read back out of a
	 *  ledger line written then. */
	public Flip(long closedAt, int itemId, String itemName, int quantity, long buySpent, long sellGross, long tax)
	{
		this(0L, 0L, closedAt, itemId, itemName, quantity, buySpent, sellGross, tax);
	}

	/**
	 * The key rows group by: the offer when there is one, and otherwise the
	 * row's own identity so an untokenised flip stands alone rather than
	 * collapsing into every other untokenised flip under a shared 0.
	 *
	 * The item too. Tokens come from a counter in the saved state, so two
	 * clients started from the same state mint the same ones, and their
	 * flips meet in one list once one's are merged into the other's; on the
	 * token alone, a flip of one item folded into another item's trade.
	 */
	public Object groupKey()
	{
		return offerId != 0 ? (Object) (offerId + ":" + itemId) : (Object) this;
	}

	/**
	 * The fills of one offer, as the single trade they were.
	 *
	 * Money adds up: quantity, cost, gross and tax are sums, so the merged
	 * row's profit is exactly the sum of its parts' — no rounding is
	 * introduced, because profit is derived from the summed components rather
	 * than from summing already-derived profits.
	 *
	 * Time does not add up. closedAt is the last fill, which is when the trade
	 * finished. openedAt is the EARLIEST buy behind any part — when the gold
	 * actually went out — unless any part's is unknown, in which case the
	 * whole thing is unknown. Reporting the earliest of the parts we happen to
	 * know would quietly understate a hold that began before the tracker was
	 * watching, and a hold time is the one figure here that must never flatter.
	 */
	public static Flip merge(java.util.List<Flip> parts)
	{
		if (parts == null || parts.isEmpty())
		{
			throw new IllegalArgumentException("nothing to merge");
		}
		final Flip first = parts.get(0);
		if (parts.size() == 1)
		{
			return first;
		}
		int quantity = 0;
		long buySpent = 0, sellGross = 0, tax = 0, closedAt = 0;
		long openedAt = Long.MAX_VALUE;
		boolean openUnknown = false;
		for (Flip f : parts)
		{
			quantity += f.quantity;
			buySpent += f.buySpent;
			sellGross += f.sellGross;
			tax += f.tax;
			closedAt = Math.max(closedAt, f.closedAt);
			if (f.openedAt <= 0)
			{
				openUnknown = true;
			}
			else
			{
				openedAt = Math.min(openedAt, f.openedAt);
			}
		}
		return new Flip(first.offerId, openUnknown ? 0L : openedAt, closedAt,
			first.itemId, first.itemName, quantity, buySpent, sellGross, tax);
	}

	/** Flips as trades: consecutive fills of one offer folded into one row,
	 *  input order preserved. */
	public static java.util.List<Flip> byTrade(java.util.List<Flip> flips)
	{
		final java.util.Map<Object, java.util.List<Flip>> groups = new java.util.LinkedHashMap<>();
		for (Flip f : flips)
		{
			groups.computeIfAbsent(f.groupKey(), k -> new java.util.ArrayList<>()).add(f);
		}
		final java.util.List<Flip> out = new java.util.ArrayList<>(groups.size());
		for (java.util.List<Flip> g : groups.values())
		{
			out.add(merge(g));
		}
		return byTerms(out);
	}

	/**
	 * How long two fills of one offer may be apart and still be that offer.
	 *
	 * The website's flip-group.js uses the same fifteen minutes for the same
	 * job, and the two surfaces read the same ledger — so they have to agree
	 * or the same afternoon is six trades on one screen and nineteen on the
	 * other, which is exactly what was reported.
	 */
	static final long GROUP_WINDOW_MS = 15 * 60 * 1000L;

	/**
	 * The fallback grouping, for rows that carry no offer token.
	 *
	 * {@link #offerId} was added on 15 Sep 2026. Every flip booked before
	 * that is in the ledger with a zero, and {@link #groupKey()} deliberately
	 * keeps those apart rather than collapsing all of them together — which
	 * is right, and also means a ledger older than the feature does not group
	 * at all. Reported from a real one: nineteen rows for six trades, with the
	 * website beside it saying six, because the website never had a token to
	 * rely on and matched on the trade's own terms instead.
	 *
	 * So the same terms are used here, for untokenised rows only: same item,
	 * identical unit price on both sides, and closed within
	 * {@link #GROUP_WINDOW_MS} of the group so far. The price test is what
	 * keeps genuinely separate trades apart — two flips of the same item at
	 * the same pair of prices, hours apart, were two decisions and stay two
	 * rows.
	 *
	 * A row that HAS a token is never touched here. The token is exact; this
	 * is an inference, and an inference must not overrule a fact.
	 */
	private static java.util.List<Flip> byTerms(java.util.List<Flip> rows)
	{
		final java.util.List<Flip> out = new java.util.ArrayList<>(rows.size());
		/* Index into `out` of the open group for a set of terms. */
		final java.util.Map<String, Integer> open = new java.util.HashMap<>();
		for (Flip f : rows)
		{
			if (f.offerId != 0 || f.quantity <= 0)
			{
				out.add(f);
				continue;
			}
			final String key = f.itemId
				+ "|" + Math.round(f.buySpent / (double) f.quantity)
				+ "|" + Math.round(f.sellGross / (double) f.quantity);
			final Integer at = open.get(key);
			if (at != null)
			{
				final Flip g = out.get(at);
				if (f.closedAt - g.closedAt <= GROUP_WINDOW_MS)
				{
					out.set(at, merge(java.util.List.of(g, f)));
					continue;
				}
			}
			open.put(key, out.size());
			out.add(f);
		}
		return out;
	}

	/**
	 * How long the gold was tied up, in millis, or -1 when that cannot be
	 * said.
	 *
	 * -1 rather than 0 on purpose. Slot time is the scarce resource — three
	 * slots on a free world — so "+296K" means something quite different at
	 * eleven minutes than at three days, and a flip with no recorded buy time
	 * reporting "0" would claim the most flattering of those. It has to read
	 * as a blank.
	 */
	public long holdMillis()
	{
		if (openedAt <= 0 || closedAt <= 0 || closedAt < openedAt)
		{
			return -1;
		}
		return closedAt - openedAt;
	}

	/** Profit per hour of slot time, or 0 when the hold time is unknown or
	 *  too short to divide by. The number that says whether an item is worth
	 *  occupying a slot with, as opposed to merely profitable. */
	public long profitPerHour()
	{
		final long held = holdMillis();
		if (held < 60_000L)
		{
			return 0;
		}
		return Math.round(profit * 3_600_000.0 / held);
	}

	public long avgBuy()
	{
		return quantity > 0 ? Math.round((double) buySpent / quantity) : 0;
	}

	public long avgSell()
	{
		return quantity > 0 ? Math.round((double) sellGross / quantity) : 0;
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Every flip you have ever closed, on disk, forever.
 *
 * The 500-flip cap this exists to lift was never about 500 being enough. Flip
 * history was kept in a RuneLite CONFIG VALUE, which is one string, rewritten
 * whole on every save and synced to your RuneLite account — a place where an
 * unbounded ledger is not merely wasteful but actively hostile to the config
 * service. The cap was the honest response to that storage, so the fix is to
 * change the storage rather than raise the number.
 *
 * Hence a file, and hence this shape:
 *
 * ONE JSON OBJECT PER LINE, APPEND ONLY. A flip is a fact about something that
 * already happened, so nothing here ever needs rewriting — and an append is
 * both cheap (no rewrite of a growing file) and the only write that survives
 * a client killed mid-flush with the rest of the history intact. The worst a
 * crash can leave is a torn final line, which {@link #readAll()} drops.
 *
 * NOT the running state. The config blob keeps doing exactly what it did:
 * lifetime P/L, the open buy lots, and the recent window the sidebar renders.
 * This is purely additive — a second, durable copy of the closed flips — so a
 * user who never opens the history page is unaffected, and one who downgrades
 * loses only the long tail rather than their tracker.
 *
 * Deliberately plain: a File and a Gson, no RuneLite types, so the durability
 * rules above can be tested rather than asserted.
 */
class FlipLedger
{
	/** Skip any line longer than this rather than buffering it. A Flip
	 *  serializes to a couple hundred bytes; something a thousand times that
	 *  is a corrupted file, not a trade. */
	private static final int MAX_LINE_CHARS = 64 * 1024;

	private final File file;
	private final Gson gson;

	/**
	 * Writes, from any client on this computer, one at a time.
	 *
	 * Every RuneLite client shares this file, and a rewrite reads the whole
	 * of it and moves a new copy over it — so a row another client appended
	 * in between would be lost for good, and that client, having counted it
	 * written, would never write it again. A lock on a file beside the
	 * ledger excludes the other processes; this monitor, the other ledgers
	 * in this one (a FileLock is per process, and a second request from the
	 * same process throws rather than waits).
	 */
	private static final Object WRITERS = new Object();

	private interface Write<T>
	{
		T run() throws IOException;
	}

	private <T> T locked(Write<T> body) throws IOException
	{
		synchronized (WRITERS)
		{
			final File dir = file.getParentFile();
			if (dir != null && !dir.isDirectory() && !dir.mkdirs())
			{
				throw new IOException("no directory for the ledger");
			}
			try (java.nio.channels.FileChannel ch = java.nio.channels.FileChannel.open(
				new File(file.getPath() + ".lock").toPath(), StandardOpenOption.CREATE, StandardOpenOption.WRITE);
				java.nio.channels.FileLock ignored = ch.lock())
			{
				return body.run();
			}
		}
	}

	FlipLedger(File file, Gson gson)
	{
		this.file = file;
		this.gson = gson;
	}


	/**
	 * Append one closed flip.
	 *
	 * Returns false rather than throwing: a ledger that cannot be written is
	 * a degraded history page, and it must never be able to take down the
	 * booking of the flip itself, which is what the sidebar and the config
	 * state depend on.
	 */
	/** Whether the file is non-empty and its last byte is not a newline. */
	private boolean endsTorn() throws IOException
	{
		if (!file.isFile() || file.length() == 0)
		{
			return false;
		}
		try (java.io.RandomAccessFile raf = new java.io.RandomAccessFile(file, "r"))
		{
			raf.seek(raf.length() - 1);
			return raf.read() != '\n';
		}
	}

	synchronized boolean append(Flip flip)
	{
		if (flip == null)
		{
			return false;
		}
		try
		{
			return locked(() -> appendLocked(flip));
		}
		catch (IOException | RuntimeException e)
		{
			return false;
		}
	}

	private boolean appendLocked(Flip flip) throws IOException
	{
		/* A file that does not end in a newline ends in a torn line — a
		   crash mid-write. Finish that line first, or this record is glued
		   onto it and both are lost to the reader. */
		final boolean torn = endsTorn();
		/* One line, one flush, one close. The newline is written as part of
		   the same call so a line can never be appended without its
		   terminator — that is what makes a torn write cost one flip instead
		   of gluing two together into an unparseable one. */
		try (Writer w = new BufferedWriter(new OutputStreamWriter(
			Files.newOutputStream(file.toPath(), StandardOpenOption.CREATE, StandardOpenOption.APPEND),
			StandardCharsets.UTF_8)))
		{
			if (torn)
			{
				w.write('\n');
			}
			w.write(gson.toJson(flip));
			w.write('\n');
		}
		return true;
	}

	/** Append many, reporting how many landed. Used to seed the ledger from
	 *  the config blob on the first run after upgrading. */
	synchronized int appendAll(List<Flip> flips)
	{
		if (flips == null || flips.isEmpty())
		{
			return 0;
		}
		int n = 0;
		for (Flip f : flips)
		{
			if (append(f))
			{
				n++;
			}
		}
		return n;
	}

	/**
	 * Rewrite the rows {@code fix} changes, keeping every other line exactly
	 * as it is — the one exception to append-only, for a flip booked wrong:
	 * "it thinks i paid 359 each for these, i only paid 280 each". Written
	 * to a copy beside the file and moved over it, so a crash leaves either
	 * the old ledger or the new one, never half of each. A line that does
	 * not parse is carried over untouched; a torn last line gets its newline.
	 * Returns how many rows changed, or -1 when the file could not be
	 * rewritten (and is then as it was).
	 */
	synchronized int rewrite(java.util.function.UnaryOperator<Flip> fix)
	{
		if (!file.isFile())
		{
			return 0;
		}
		try
		{
			return locked(() -> rewriteLocked(fix));
		}
		catch (IOException | RuntimeException e)
		{
			return -1;
		}
	}

	private int rewriteLocked(java.util.function.UnaryOperator<Flip> fix) throws IOException
	{
		final File dir = file.getAbsoluteFile().getParentFile();
		final File tmp = Files.createTempFile(dir.toPath(), file.getName() + ".", ".tmp").toFile();
		int changed = 0;
		try
		{
			final List<String> lines = Files.readAllLines(file.toPath(), StandardCharsets.UTF_8);
			try (Writer w = new BufferedWriter(new OutputStreamWriter(Files.newOutputStream(tmp.toPath(),
				StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE),
				StandardCharsets.UTF_8)))
			{
				for (String line : lines)
				{
					String out = line;
					if (!line.isEmpty() && line.length() <= MAX_LINE_CHARS)
					{
						try
						{
							final Flip f = gson.fromJson(line, Flip.class);
							final Flip r = f != null ? fix.apply(f) : null;
							if (r != null && r != f)
							{
								out = gson.toJson(r);
								changed++;
							}
						}
						catch (RuntimeException unparseable)
						{
							// carried over as it is
						}
					}
					w.write(out);
					w.write('\n');
				}
			}
			if (changed == 0)
			{
				Files.deleteIfExists(tmp.toPath());
				return 0;
			}
			try
			{
				Files.move(tmp.toPath(), file.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING,
					java.nio.file.StandardCopyOption.ATOMIC_MOVE);
			}
			catch (java.nio.file.AtomicMoveNotSupportedException e)
			{
				Files.move(tmp.toPath(), file.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
			}
			return changed;
		}
		catch (IOException | RuntimeException e)
		{
			try
			{
				Files.deleteIfExists(tmp.toPath());
			}
			catch (IOException ignore)
			{
				// the ledger itself was not touched
			}
			return -1;
		}
	}

	/** True when there is nothing on disk yet — the seed condition, and the
	 *  only thing that decides whether the migration runs. */
	synchronized boolean isEmpty()
	{
		return !file.isFile() || file.length() == 0L;
	}

	/**
	 * How many rows, without parsing any of them.
	 *
	 * Counting bytes rather than deserializing matters at startup: this runs
	 * before the client has finished loading, on a file that is allowed to
	 * grow for years, and the answer is only ever used to tell the website
	 * whether its copy is stale. Parsing tens of thousands of flips to
	 * produce one integer would be a real stall for no gain.
	 */
	synchronized int count()
	{
		if (!file.isFile())
		{
			return 0;
		}
		int lines = 0;
		try (java.io.InputStream in = new java.io.BufferedInputStream(Files.newInputStream(file.toPath())))
		{
			final byte[] buf = new byte[8192];
			int read;
			int last = -1;
			while ((read = in.read(buf)) > 0)
			{
				for (int i = 0; i < read; i++)
				{
					if (buf[i] == '\n')
					{
						lines++;
					}
					last = buf[i];
				}
			}
			/* A final line with no terminator is a torn write, and readAll
			   drops it — so it must not be counted here either, or the site
			   would forever see one more row than it can fetch. */
			if (last != -1 && last != '\n')
			{
				// unterminated tail: not a row
				return lines;
			}
		}
		catch (IOException | RuntimeException e)
		{
			return lines;
		}
		return lines;
	}

	/**
	 * The whole ledger, oldest first.
	 *
	 * Sorted by close time rather than trusted in file order: appends are
	 * handed off the client thread, so two flips booked in the same instant
	 * can land in either order. The page draws a time series from this, and a
	 * cumulative line that steps backwards is a bug you can see.
	 *
	 * Unparseable lines are skipped, not fatal. A ledger with one torn line
	 * from a crash is still a year of history, and refusing to read it would
	 * be the only way that crash could actually cost anything.
	 */
	/** As readAll, but null when the read did not reach the end of the
	 *  file — for callers that must not take a partial read as the whole. */
	synchronized List<Flip> readAllOrNull()
	{
		final List<Flip> out = readAll();
		return lastReadComplete ? out : null;
	}

	/** Whether the most recent readAll got to the end of the file. */
	private boolean lastReadComplete;

	synchronized List<Flip> readAll()
	{
		lastReadComplete = false;
		final List<Flip> out = new ArrayList<>();
		if (!file.isFile())
		{
			lastReadComplete = true; // nothing written yet is a whole read of nothing
			return out;
		}
		try (BufferedReader r = new BufferedReader(new InputStreamReader(
			Files.newInputStream(file.toPath()), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				if (line.isEmpty() || line.length() > MAX_LINE_CHARS)
				{
					continue;
				}
				final String t = line.trim();
				if (t.isEmpty() || t.charAt(0) != '{')
				{
					continue;
				}
				try
				{
					final Flip f = gson.fromJson(t, Flip.class);
					/* itemId 0 means the object parsed but was not a Flip —
					   Gson is happy to hand back a blank one for any JSON
					   object at all, so the shape has to be checked here. */
					if (f != null && f.itemId > 0)
					{
						out.add(f);
					}
				}
				catch (RuntimeException ignore)
				{
					// torn or foreign line — keep reading
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			return out; // whatever was read before the failure is still real
		}
		out.sort(Comparator.comparingLong(f -> f.closedAt));
		lastReadComplete = true;
		return out;
	}
}

package com.pocketge.tracker;

import java.util.List;

/**
 * Pure time-range stats over completed flips (no RuneLite types —
 * unit-testable): total profit, flip count, ROI%, and an hourly profit rate,
 * for whichever window the user has selected in the panel — matching
 * Flipping Copilot's Session / 1h / 4h / 12h / 1d / 1w / 1m / All-time
 * dropdown, computed from data we already track (every {@link Flip} carries
 * its own close timestamp).
 */
public final class FlipStats
{
	private FlipStats() {}

	public enum Range
	{
		SESSION("Session"),
		H1("1h", 3_600_000L),
		H4("4h", 4 * 3_600_000L),
		H12("12h", 12 * 3_600_000L),
		D1("1d", 24 * 3_600_000L),
		W1("1w", 7 * 24 * 3_600_000L),
		M1("1m", 30L * 24 * 3_600_000L),
		ALL("All time");

		private final String label;
		private final long windowMillis; // 0 for SESSION/ALL (resolved separately)

		Range(String label) { this(label, 0); }
		Range(String label, long windowMillis) { this.label = label; this.windowMillis = windowMillis; }

		@Override public String toString() { return label; }
	}

	/** Where a range starts. ALL starts at the first flip, so its hourly
	 *  rate is measured over the time you have actually been flipping. */
	static long windowStart(Range range, long nowMillis, long sessionStartMillis, long firstFlipMillis)
	{
		switch (range)
		{
			case SESSION:
				return sessionStartMillis;
			case ALL:
				return firstFlipMillis;
			default:
				return nowMillis - range.windowMillis;
		}
	}

	/** The flips a range covers, oldest first — the same test compute uses,
	 *  so the list and the totals above it cannot disagree. */
	public static List<Flip> inRange(List<Flip> flips, Range range, long nowMillis, long sessionStartMillis)
	{
		final List<Flip> out = new java.util.ArrayList<>();
		if (flips == null)
		{
			return out;
		}
		final long start = range == Range.ALL ? Long.MIN_VALUE : windowStart(range, nowMillis, sessionStartMillis, 0);
		for (Flip f : flips)
		{
			if (f.closedAt >= start)
			{
				out.add(f);
			}
		}
		return out;
	}

	/** When the oldest of a rolling range's flips ages out of it, so the
	 *  list can be redrawn then; 0 for the ranges that do not roll. */
	public static long nextExpiry(List<Flip> inRange, Range range)
	{
		if (range.windowMillis <= 0 || inRange == null || inRange.isEmpty())
		{
			return 0;
		}
		long oldest = Long.MAX_VALUE;
		for (Flip f : inRange)
		{
			oldest = Math.min(oldest, f.closedAt);
		}
		return oldest + range.windowMillis + 1;
	}

	public static class Stats
	{
		public long profit;
		public long buySpent;
		public int flipCount;
		public double roiPct;      // profit / buySpent * 100, 0 if nothing bought in-window
		public long hourlyRate;    // gp/hr, extrapolated over the window's elapsed time
		public long unrealizedProfit;
	}

	/**
	 * @param nowMillis           current wall-clock time
	 * @param sessionStartMillis  when the current session began (for SESSION)
	 * @param firstFlipMillis     timestamp of the earliest known flip, or
	 *                            nowMillis if there is none (for ALL)
	 * @param unrealizedProfit    mark-to-market P/L on currently open buys,
	 *                            just passed through onto the result — it
	 *                            isn't itself time-windowed (it's a snapshot
	 *                            of right now, same for every range)
	 */
	public static Stats compute(List<Flip> flips, Range range, long nowMillis,
		long sessionStartMillis, long firstFlipMillis, long unrealizedProfit)
	{
		final long windowStart = windowStart(range, nowMillis, sessionStartMillis, firstFlipMillis);

		Stats s = new Stats();
		s.unrealizedProfit = unrealizedProfit;
		if (flips == null)
		{
			return s;
		}
		/*
		 * Trades, not fills. The Exchange fills one sell offer in as many
		 * chunks as it finds buyers for, and counting those made "Flips made"
		 * report how choppy the order book was rather than how many times you
		 * traded — 5 for one sale of 8,218 bars. Money is unaffected either
		 * way: profit and cost are sums below, taken from the fills
		 * themselves, so they were right before and are right now.
		 *
		 * Through Flip.byTrade rather than groupKey() directly, which is what
		 * this used to do. groupKey() only knows about the offer token, and a
		 * row booked before tokens existed carries a zero — so a ledger older
		 * than that feature counted every fragment. byTrade falls back to
		 * matching on the trade's own terms for exactly those rows, and doing
		 * it here as well is what keeps "Flips made" and the history panel's
		 * "N flips recorded" reporting the same number.
		 */
		final java.util.List<Flip> inWindow = new java.util.ArrayList<>();
		for (Flip f : flips)
		{
			if (f.closedAt < windowStart)
			{
				continue;
			}
			s.profit += f.profit;
			s.buySpent += f.buySpent;
			inWindow.add(f);
		}
		s.flipCount = Flip.byTrade(inWindow).size();
		s.roiPct = s.buySpent > 0 ? (double) s.profit / s.buySpent * 100.0 : 0.0;

		long elapsedMs = Math.max(1, nowMillis - windowStart);
		double hours = elapsedMs / 3_600_000.0;
		s.hourlyRate = Math.round(s.profit / hours);
		return s;
	}
}

package com.pocketge.tracker;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Pure trade-tracking logic (no RuneLite types) so it is unit-testable.
 *
 * Feed it cumulative offer snapshots (slot, itemId, qtySold, gpSpent,
 * isBuy); it emits incremental {@link TradeFill}s and matches sells
 * against earlier buys to produce {@link Flip}s with profit AFTER the 2% GE
 * tax — newest first among this character's buys from before the sell was
 * listed, leaving out units still in a buy's box: see {@link #charge}.
 *
 * Newest first, not oldest: oldest-first charged a sale of 13,418 Aether
 * catalyst bought at 277 against 24,500 left on record at 359 from an
 * earlier stack sold where the plugin did not see — -1.12M booked on a sale
 * that lost 26.8K: "its remembering an old buy price. it thinks i paid 359
 * each for these, i only paid 280 each".
 *
 * Baseline rule: the first snapshot seen for a slot (login replay, or an
 * offer that predates the tracker) sets a baseline WITHOUT emitting fills
 * — only growth we actually witness is counted, so nothing double-counts.
 */
public class FlipTracker
{
	/** Mirror of the site's tax rules: 2% == floor(price/50) per item,
	 *  nothing under 50 gp, capped at 5M per item, and a short list of
	 *  exempt items (bond + classic tools). */
	private static final Set<Integer> TAX_EXEMPT_IDS = new HashSet<>(List.of(
		13190, // Old school bond
		1755,  // Chisel
		5325,  // Gardening trowel
		11364, // Glassblowing pipe
		2347,  // Hammer
		1733,  // Needle
		233,   // Pestle and mortar
		5341,  // Rake
		8794,  // Saw
		5329,  // Secateurs
		5343,  // Seed dibber
		1735,  // Shears
		952,   // Spade
		5331   // Watering can
	));

	public static long taxPerItem(long unitPrice, int itemId)
	{
		if (unitPrice < 50 || TAX_EXEMPT_IDS.contains(itemId))
		{
			return 0;
		}
		return Math.min(unitPrice / 50, 5_000_000L);
	}

	private static class SlotState
	{
		int itemId;
		boolean buy;
		int qtySold;
		long spent;
		/** The offer's asking price and its full size. Neither can change
		 *  while an offer is live — the Exchange has no way to edit one —
		 *  so together with the item they say WHICH offer a slot is holding.
		 *  That is what tells a resumed offer apart from a different one
		 *  placed in the same slot since this baseline was written. 0 when
		 *  not supplied; see the 8-argument {@link #onOffer}. */
		long price;
		int totalQuantity;
		/** True for a baseline read back off disk that no live event has
		 *  confirmed yet. Growth measured against one of these happened at
		 *  an unknown moment while the client was closed, so the lot it
		 *  opens carries no fill time. Cleared the first time this slot is
		 *  seen live. */
		boolean restored;
		/** True for a baseline taken before the player last logged out and
		 *  not seen live since. While logged out the slot can be collected
		 *  and an identical offer placed — on mobile — so the next sighting
		 *  may be a different offer that only looks like this one grown.
		 *  See the over-bid branch of {@link #onOffer}. */
		boolean unwatched;
		/** True for a baseline written by a build that filed a character
		 *  with a negative account hash under some other character — every
		 *  build before 0.7.2. Such a row may hold another character's offer,
		 *  so it is never taken as proof that a NEW offer replaced it: the
		 *  first sighting against it measures or re-baselines, as those
		 *  builds did, and books no whole receipt. Persisted until seen. */
		boolean legacy;
		/** Identifies THIS offer, so the flips its fills book can be
		 *  recognised as one trade. Minted when the slot takes a new offer,
		 *  and kept for that offer's whole life. See {@link Flip#offerId}. */
		long offerToken;
		/** What this offer's sales have booked: units, and their profit.
		 *  Kept on the offer as it books rather than counted off the flips
		 *  list, which holds the newest 500 across every slot — a slow sell
		 *  lost its early sales from "made so far" as other slots traded. */
		long bookedQty;
		long bookedProfit;
		/** How much of the booked total has been shown as a profit figure
		 *  over the slot — see {@link #unseenBy}. Saved with the rest, so a
		 *  sale that finished with the Exchange shut still pops after a
		 *  restart, and starts at nothing with each new offer. */
		long shownQty;
		long shownProfit;
		/** What this offer sold that no buy on record could be charged for —
		 *  cooked, fished, looted, bought before the plugin — in units, and
		 *  the coins they brought in after tax. Never a flip and never
		 *  profit; only the gold figure over the square, which these and
		 *  the two after them are for — see {@link #unseenBy}. Saved after
		 *  {@link #boxedAtListing} in the row; a save without them starts
		 *  all four at 0, so an upgrade pops nothing old. */
		long looseQty;
		long looseCoins;
		long shownLooseQty;
		long shownLooseCoins;
		/** Restored from a save written before bookedQty/bookedProfit were
		 *  kept: seeded once from the flips list — see restore. */
		transient boolean seedBooked;
		/** The first lot sequence number handed out after this offer was
		 *  first seen. A lot at or past it was bought after the offer was
		 *  listed, so none of the offer's units can be in it — see
		 *  {@link #matchSell}. 0 until set: a row restored from a save that
		 *  did not record it gets one at the end of {@link #restore}. */
		long lotsBefore;
		/** A buy's collection box, live: units of the item waiting in it, or
		 *  -1 when the box has not been seen since this record was made or
		 *  since the last logout. Never saved. */
		transient long boxUnits = -1;
		/** A sell only: {lot seq, units} pairs that were waiting in a buy's
		 *  collection box when this offer was listed, so are not in it.
		 *  Saved; empty for an offer from a save without it. */
		long[] boxedAtListing = new long[0];
	}

	private static class BuyLot
	{
		int qty;
		long spent;
		/** When this lot filled, epoch millis; 0 for a lot restored from a
		 *  save written before the tracker recorded it. Survives partial
		 *  consumption — selling half a lot does not change when the other
		 *  half was bought. */
		long time;
		/** Order of creation, in memory only, so a forget can drop exactly
		 *  the lots its prompt showed and none booked after. */
		final long seq;
		/** The character that bought it; 0 = not recorded (older saves),
		 *  which any character may sell. */
		final long account;
		/** offerToken of the buy offer that booked it; 0 = not recorded. */
		final long source;

		BuyLot(int qty, long spent, long time, long seq)
		{
			this(qty, spent, time, seq, 0L, 0L);
		}

		BuyLot(int qty, long spent, long time, long seq, long account, long source)
		{
			this.qty = qty;
			this.spent = spent;
			this.time = time;
			this.seq = seq;
			this.account = account;
			this.source = source;
		}
	}

	/** Whether the character now logged in may be charged for this lot. */
	private boolean mine(BuyLot lot)
	{
		return lot.account == 0 || accountHash == 0 || lot.account == accountHash;
	}

	/**
	 * Units of each lot still waiting in a buy offer's collection box, so in
	 * no sell offer. A box holds the fills since its last collect, which are
	 * that offer's newest lots. Its count is the slot's live box when seen
	 * this login; unseen, a finished buy seen in its slot since the last
	 * gap counts as wholly uncollected (collecting a finished buy empties
	 * the slot), and anything else as wholly collected.
	 */
	private long[] boxedNow(int itemId, int exceptSlot)
	{
		final Deque<BuyLot> lots = openBuys.get(itemId);
		if (lots == null)
		{
			return new long[0];
		}
		final List<Long> out = new ArrayList<>();
		for (Map.Entry<Integer, SlotState> e : slots().entrySet())
		{
			final SlotState b = e.getValue();
			if (!b.buy || b.itemId != itemId || e.getKey() == exceptSlot)
			{
				continue;
			}
			/* Unseen box: a finished buy is still in its box only if its slot
			   has been seen holding it since the last gap — a record off disk
			   or from before a logout may be a slot already collected on
			   mobile, whose EMPTY the login clear has not delivered yet. */
			final boolean confirmed = !b.restored && !b.unwatched;
			long n = b.boxUnits >= 0 ? b.boxUnits
				: confirmed && b.totalQuantity > 0 && b.qtySold >= b.totalQuantity ? Long.MAX_VALUE : 0;
			for (java.util.Iterator<BuyLot> it = lots.descendingIterator(); n > 0 && it.hasNext(); )
			{
				final BuyLot lot = it.next();
				if (lot.source != 0 && lot.source == b.offerToken)
				{
					final int take = (int) Math.min(n, lot.qty);
					out.add(lot.seq);
					out.add((long) take);
					n -= take;
				}
			}
		}
		final long[] a = new long[out.size()];
		for (int i = 0; i < a.length; i++)
		{
			a[i] = out.get(i);
		}
		return a;
	}

	/** The live box of {@code slot}'s buy of {@code itemId}: units in it, or
	 *  -1 for unknown. Ignored for any other offer. */
	public synchronized void noteBox(int slot, int itemId, long units)
	{
		final SlotState st = slots().get(slot);
		if (st != null && st.buy && st.itemId == itemId)
		{
			st.boxUnits = units;
		}
	}

	/**
	 * What the unsold rest of {@code slot}'s sell would be charged if it sold
	 * now — {units, gp} — by the same rule a sale books with. {0, 0} when the
	 * slot has a record and nothing on record covers it: the sale will book
	 * no cost, so there is no profit to project. Null only when there is no
	 * sell record for the slot at all.
	 */
	public synchronized long[] previewSale(int slot)
	{
		final SlotState st = slots().get(slot);
		if (st == null || st.buy || st.totalQuantity <= 0)
		{
			return null;
		}
		final long[] r = charge(st.itemId, Math.max(0, st.totalQuantity - st.qtySold), st, false);
		return new long[]{r[0], r[1]};
	}

	/**
	 * The one rule for what a sale of {@code qty} from {@code offer} is
	 * charged: this character's lots (or unattributed ones), bought before
	 * the offer was listed, not waiting in a buy's box — newest first.
	 * Returns {matched, buySpent, openedAt}; consumes them when {@code take}.
	 */
	private long[] charge(int itemId, int qty, SlotState offer, boolean take)
	{
		final Deque<BuyLot> lots = openBuys.get(itemId);
		if (lots == null || lots.isEmpty() || qty <= 0)
		{
			return new long[]{0, 0, 0};
		}
		final Map<Long, Long> boxed = new HashMap<>();
		for (int i = 0; i + 1 < offer.boxedAtListing.length; i += 2)
		{
			boxed.merge(offer.boxedAtListing[i], offer.boxedAtListing[i + 1], Long::sum);
		}
		int remaining = qty;
		long buySpent = 0, openedAt = Long.MAX_VALUE;
		int matched = 0;
		boolean untimed = false;
		for (java.util.Iterator<BuyLot> it = lots.descendingIterator(); remaining > 0 && it.hasNext(); )
		{
			final BuyLot lot = it.next();
			if (!mine(lot) || (offer.lotsBefore > 0 && lot.seq >= offer.lotsBefore))
			{
				continue;
			}
			final int free = (int) (lot.qty - Math.min(lot.qty, boxed.getOrDefault(lot.seq, 0L)));
			if (free <= 0)
			{
				continue;
			}
			final int n = Math.min(remaining, free);
			final long slice = Math.round((double) lot.spent * n / lot.qty);
			buySpent += slice;
			if (lot.time <= 0)
			{
				untimed = true;
			}
			else
			{
				openedAt = Math.min(openedAt, lot.time);
			}
			if (take)
			{
				lot.qty -= n;
				lot.spent -= slice;
				if (lot.qty <= 0)
				{
					it.remove();
				}
			}
			remaining -= n;
			matched += n;
		}
		if (take && lots.isEmpty())
		{
			openBuys.remove(itemId);
		}
		return new long[]{matched, buySpent, untimed || matched == 0 ? 0L : openedAt};
	}

	/** Cap on persisted/held flip history so state stays small. */
	private static final int MAX_FLIPS = 500;
	private static final int MAX_FILLS = 1000;

	/** Baselines per character, then per slot. Keyed by account because slot 3
	 *  is a different offer for every character and this state is shared by
	 *  all of them; key 0 is "logged in as nobody yet". Kept rather than
	 *  cleared on a change of character, so switching back and forth cannot
	 *  make the same offer look new twice — which, now that a new offer gets
	 *  its filled portion booked, would be a double count rather than merely
	 *  a forgotten one. */
	private final Map<Long, Map<Integer, SlotState>> slotsByAccount = new HashMap<>();
	/** A backstop on {@link #slotsByAccount}, not a real limit — nobody plays
	 *  twenty characters, and if the account hash ever misbehaved this stops
	 *  the state blob growing without bound. */
	private static final int MAX_ACCOUNTS = 20;

	/**
	 * The Grand Exchange's buy limit runs on a four-hour clock that starts at
	 * the first purchase: buy the whole limit and the item cannot be bought
	 * again until four hours after that first unit, however long ago the rest
	 * went through.
	 */
	static final long LIMIT_WINDOW_MS = 4L * 60 * 60 * 1000;
	/**
	 * Each character's open buy-limit windows: accountHash -> itemId ->
	 * {when the window started, units bought in it}. "i just bought 25k and
	 * flipped them, and its still reccomending me that i buy this flip, it
	 * should know im on cool down for 4h". Kept in the saved state, because a
	 * restart inside the four hours does not reset the game's clock either.
	 */
	private final Map<Long, Map<Integer, long[]>> limitWindows = new HashMap<>();
	/** Members get eight offer slots; free-to-play uses the first three. */
	private static final int GE_SLOTS = 8;
	/** An item id no offer can have, marking a slot as "on record, but not as
	 *  any actual offer" — see the upgrade path in {@link #restore}. */
	private static final int NO_OFFER = -1;
	private final Map<Integer, Deque<BuyLot>> openBuys = new HashMap<>();
	private long nextLotSeq = 1;
	/** See State#negativeHashMigration. */
	private boolean negativeHashMigration;
	private final java.util.Set<Long> negativeHashesHandled = new java.util.HashSet<>();
	/** What {@link State#slotsFormat} this build writes. */
	static final int SLOTS_FORMAT = 2;
	private final List<TradeFill> fills = new ArrayList<>();
	private final List<Flip> flips = new ArrayList<>();
	private long sessionProfit = 0;
	private long lifetimeProfit = 0;
	/** Wall-clock start of the current session, for "Session" time-range
	 *  stats and the hourly-profit-rate calc. Reset alongside the session
	 *  counter, not on restore (a restored client keeps its own session). */
	private long sessionStartMillis = System.currentTimeMillis();
	/** Whose slot baselines are in play, 0 until a character logs in. See
	 *  {@link #setAccountHash}. */
	private long accountHash;
	/** Set whenever a slot baseline moves, whether or not a fill came with
	 *  it. See {@link #takeSlotsDirty}. */
	private boolean slotsDirty;
	/** Mints {@link SlotState#offerToken}. Persisted so a token is never
	 *  reused across restarts — two different offers sharing one would
	 *  merge two unrelated trades into a single history row. */
	private long nextOfferToken = 1;

	/**
	 * Told about each flip the moment it is booked, so it can be written to
	 * the permanent ledger.
	 *
	 * A callback rather than the tracker owning a file, because the whole
	 * point of this class is that it has no I/O and no RuneLite types in it —
	 * the matching below is the part that must stay unit-testable. It
	 * also means the sink sees flips that {@link #MAX_FLIPS} will later push
	 * out of the in-memory window, which is the entire reason it exists.
	 *
	 * Never null; a no-op until someone sets one.
	 */
	private java.util.function.Consumer<Flip> flipSink = f -> { };

	public synchronized void setFlipSink(java.util.function.Consumer<Flip> sink)
	{
		this.flipSink = sink != null ? sink : f -> { };
	}

	/** Serializable snapshot of everything worth keeping across client
	 *  restarts: lifetime P/L, flip history, and the open buy lots so a
	 *  flip still books correctly when the sell happens tomorrow. */
	public static class State
	{
		/** Next {@link BuyLot#seq}; absent (0) before lots kept theirs. */
		public long nextLotSeq;
		public long lifetimeProfit;
		public List<Flip> flips;
		public Map<Integer, List<long[]>> openBuys; // itemId -> [qty, spent, fillTime] lots
		/** slot -> [itemId, buy?1:0, qtySold, spent, price, totalQuantity].
		 *
		 *  Offers keep filling while you are logged out, and without this the
		 *  tracker met every one of them as a stranger on the next login: a
		 *  slot it had never seen baselines instead of booking, so an
		 *  overnight buy was silently uncosted forever. Remembering where each
		 *  slot stood turns that login replay from "no idea" into a
		 *  measurement — the growth since the last save is real growth. */
		public Map<Integer, long[]> slots;
		/** The same thing, per character: accountHash -> slot -> row. Written
		 *  instead of {@link #slots} from 0.6.5 on; {@link #slots} is still
		 *  read so a state file from the version between does not lose its
		 *  baselines on upgrade. */
		public Map<Long, Map<Integer, long[]>> slotsByAccount;
		/** Which character the slots above belong to, or 0 for a save written
		 *  before this was recorded. Slot baselines are the one piece of state
		 *  here that is meaningless on another account: slot 3 is a different
		 *  offer for every character, and this file is shared by all of them. */
		public long accountHash;
		/** Next value for {@link SlotState#offerToken}; see nextOfferToken. */
		public long nextOfferToken;
		/** 2 from 0.7.2: a character with a negative account hash has its own
		 *  slot baselines. Absent (0) in every save before, which filed such a
		 *  character under whoever logged in before it. */
		public int slotsFormat;
		/** This install's history predates 0.7.2, so a character with a
		 *  negative hash may have offers the tracker already booked, filed
		 *  under someone else. The first time each such character is seen it
		 *  gets placeholders instead of an empty record, and its first
		 *  sightings only baseline — never re-book a receipt. Kept until
		 *  every such character has been seen once; see negativeHashesHandled. */
		public boolean negativeHashMigration;
		public List<Long> negativeHashesHandled;
		/** accountHash -> itemId -> {window start millis, units bought}; see
		 *  limitWindows. Absent in saves before 0.7.2's limit tracking. */
		public Map<Long, Map<Integer, long[]>> limitWindows;
	}

	/**
	 * Tell the tracker which character is logged in.
	 *
	 * Only the slot baselines care. Everything else here — lifetime profit,
	 * flip history, open lots — has always been shared across a player's
	 * accounts, and merging those is at worst a presentation question. A slot
	 * baseline is different in kind: slot 3 holds a different offer on every
	 * character, so carrying one across would measure account B's offer
	 * against account A's numbers and book the difference as a real fill.
	 * Changing character therefore throws the baselines away and starts over,
	 * which costs nothing worse than the behaviour before they existed.
	 */
	public synchronized void setAccountHash(long hash)
	{
		/* -1 is the client's "not logged in" and 0 is this class's own
		   "unknown". Only those: a hash is a 64-bit value, and treating a
		   negative one as no account left that character measured against
		   whoever logged in before it. */
		if (hash == -1 || hash == 0 || hash == accountHash)
		{
			return;
		}
		/* Anything baselined before we knew who was logged in belongs to
		   whoever that turned out to be. In practice this is empty — the
		   offer handler learns the account before it records anything — but a
		   state file written by an older version has its slots here. */
		final Map<Integer, SlotState> unknown = slotsByAccount.remove(0L);
		accountHash = hash;
		if (unknown != null && !unknown.isEmpty())
		{
			slotsByAccount.computeIfAbsent(hash, k -> new HashMap<>()).putAll(unknown);
			slotsDirty = true;
		}
		/* A negative-hash character on an install older than 0.7.2: its
		   offers were tracked under another character, and some of what they
		   show is already booked. With no record of its own, its first
		   sighting would book every receipt again — so it starts from
		   placeholders, as a pre-baseline save does, once.

		   Not repaired: the rows those builds left under the OTHER character
		   (or under 0, shared by two negative-hash characters) may hold the
		   wrong character's offer, and a delta measured against one can book
		   twice — exactly as continuing on 0.7.1 would. Undoing that would
		   mean dropping every character's offline fills once on upgrade, for
		   everyone; it is left as it was, and Forget is the repair. */
		if (hash < 0 && negativeHashMigration && negativeHashesHandled.add(hash))
		{
			final Map<Integer, SlotState> own = slotsByAccount.computeIfAbsent(hash, k -> new HashMap<>());
			for (int slot = 0; slot < GE_SLOTS; slot++)
			{
				if (!own.containsKey(slot))
				{
					final SlotState st = new SlotState();
					st.itemId = NO_OFFER;
					st.offerToken = nextOfferToken++;
					own.put(slot, st);
				}
			}
			slotsDirty = true;
		}
		if (slotsByAccount.size() > MAX_ACCOUNTS)
		{
			slotsByAccount.keySet().removeIf(k -> k != accountHash
				&& slotsByAccount.size() > MAX_ACCOUNTS);
			slotsDirty = true;
		}
	}

	/** This character's slot baselines. */
	private Map<Integer, SlotState> slots()
	{
		return slotsByAccount.computeIfAbsent(accountHash, k -> new HashMap<>());
	}

	/**
	 * Whether a slot baseline has moved since this was last asked, clearing
	 * the flag.
	 *
	 * The caller has to persist those, and most of them produce no fill: an
	 * offer being placed, or collected, only moves a baseline. An unsaved
	 * baseline is re-taken from scratch on the next start, and re-taking one
	 * is precisely how an offline fill goes uncounted — so "nothing to show
	 * the user" and "nothing to write down" are not the same question, and
	 * this is the second one.
	 */
	public synchronized boolean takeSlotsDirty()
	{
		final boolean d = slotsDirty;
		slotsDirty = false;
		return d;
	}

	public synchronized State snapshot()
	{
		State s = new State();
		s.lifetimeProfit = lifetimeProfit;
		s.nextLotSeq = nextLotSeq;
		s.accountHash = accountHash;
		s.nextOfferToken = nextOfferToken;
		s.slotsFormat = SLOTS_FORMAT;
		s.negativeHashMigration = negativeHashMigration;
		s.negativeHashesHandled = new ArrayList<>(negativeHashesHandled);
		s.slotsByAccount = new HashMap<>();
		for (Map.Entry<Long, Map<Integer, SlotState>> acc : slotsByAccount.entrySet())
		{
			final Map<Integer, long[]> rows = new HashMap<>();
			for (Map.Entry<Integer, SlotState> e : acc.getValue().entrySet())
			{
				final SlotState st = e.getValue();
				rows.put(e.getKey(), new long[]{
					st.itemId, st.buy ? 1 : 0, st.qtySold, st.spent, st.price, st.totalQuantity,
					st.offerToken, st.legacy ? 1 : 0, st.bookedQty, st.bookedProfit, st.shownQty, st.shownProfit,
					st.lotsBefore, st.boxedAtListing.length / 2});
				/* Then the pairs, then the loose sale — after the pairs so a
				   build that reads only as far as the pairs reads what it
				   always did. */
				final long[] row = rows.get(e.getKey());
				final long[] longer = java.util.Arrays.copyOf(row, row.length + st.boxedAtListing.length + 4);
				System.arraycopy(st.boxedAtListing, 0, longer, row.length, st.boxedAtListing.length);
				final int at = row.length + st.boxedAtListing.length;
				longer[at] = st.looseQty;
				longer[at + 1] = st.looseCoins;
				longer[at + 2] = st.shownLooseQty;
				longer[at + 3] = st.shownLooseCoins;
				rows.put(e.getKey(), longer);
			}
			if (!rows.isEmpty())
			{
				s.slotsByAccount.put(acc.getKey(), rows);
			}
		}
		s.limitWindows = new HashMap<>();
		for (Map.Entry<Long, Map<Integer, long[]>> acc : limitWindows.entrySet())
		{
			final Map<Integer, long[]> rows = new HashMap<>();
			for (Map.Entry<Integer, long[]> e : acc.getValue().entrySet())
			{
				rows.put(e.getKey(), e.getValue().clone());
			}
			if (!rows.isEmpty())
			{
				s.limitWindows.put(acc.getKey(), rows);
			}
		}
		s.flips = new ArrayList<>(flips);
		s.openBuys = new HashMap<>();
		for (Map.Entry<Integer, Deque<BuyLot>> e : openBuys.entrySet())
		{
			List<long[]> lots = new ArrayList<>();
			for (BuyLot lot : e.getValue())
			{
				lots.add(new long[]{lot.qty, lot.spent, lot.time, lot.seq, lot.account, lot.source});
			}
			if (!lots.isEmpty())
			{
				s.openBuys.put(e.getKey(), lots);
			}
		}
		return s;
	}

	public synchronized void restore(State s)
	{
		if (s == null)
		{
			return;
		}
		lifetimeProfit = s.lifetimeProfit;
		accountHash = s.accountHash;
		/* Never go backwards: a save from before tokens existed reads 0, and
		   starting from 1 again would hand an old token to a new offer. */
		nextOfferToken = Math.max(nextOfferToken, Math.max(1L, s.nextOfferToken));
		final boolean oldFormat = s.slotsFormat < SLOTS_FORMAT;
		negativeHashesHandled.clear();
		if (oldFormat)
		{
			/* Any history at all means characters may have been filed under
			   each other; an empty save means a fresh install, and nothing to
			   migrate. */
			negativeHashMigration = s.lifetimeProfit != 0 || s.accountHash != 0
				|| (s.slotsByAccount != null && !s.slotsByAccount.isEmpty())
				|| (s.slots != null && !s.slots.isEmpty())
				|| (s.flips != null && !s.flips.isEmpty())
				|| (s.openBuys != null && !s.openBuys.isEmpty());
		}
		else
		{
			negativeHashMigration = s.negativeHashMigration;
			if (s.negativeHashesHandled != null)
			{
				for (Long h : s.negativeHashesHandled)
				{
					if (h != null)
					{
						negativeHashesHandled.add(h);
					}
				}
			}
		}
		slotsByAccount.clear();
		if (s.slotsByAccount != null)
		{
			for (Map.Entry<Long, Map<Integer, long[]>> acc : s.slotsByAccount.entrySet())
			{
				if (acc.getKey() == null || acc.getValue() == null)
				{
					continue;
				}
				slotsByAccount.put(acc.getKey(), readSlots(acc.getValue(), oldFormat));
			}
		}
		else if (s.slots != null)
		{
			/* A save from the one version that kept a single flat map. Those
			   baselines are the account that file recorded, so file them under
			   it rather than dropping them. */
			slotsByAccount.put(s.accountHash, readSlots(s.slots, true));
		}
		else if (s.lifetimeProfit != 0
			|| (s.flips != null && !s.flips.isEmpty())
			|| (s.openBuys != null && !s.openBuys.isEmpty()))
		{
			/*
			 * A save from before baselines were kept at all, carrying history.
			 *
			 * Its open lots may already include part of whatever is sitting in
			 * the slots right now — that version counted the growth it
			 * witnessed before the client last closed — and seeding those
			 * offers would count the same gold a second time. So every slot
			 * gets a placeholder: a record that matches no real offer, which
			 * sends the first sighting down the baseline path exactly as the
			 * old version would have, and lets normal behaviour resume from
			 * the second.
			 *
			 * One pass, on one upgrade. Filed under the unknown account, which
			 * setAccountHash hands to whoever logs in first — so a player with
			 * several characters gets this protection on the first one they
			 * open, and the others seed immediately. That is the narrow case
			 * where a single item's cost basis can come out high, once.
			 */
			final Map<Integer, SlotState> placeholders = new HashMap<>();
			for (int slot = 0; slot < GE_SLOTS; slot++)
			{
				final SlotState st = new SlotState();
				st.itemId = NO_OFFER;
				st.offerToken = nextOfferToken++;
				placeholders.put(slot, st);
			}
			slotsByAccount.put(0L, placeholders);
		}
		limitWindows.clear();
		if (s.limitWindows != null)
		{
			for (Map.Entry<Long, Map<Integer, long[]>> acc : s.limitWindows.entrySet())
			{
				if (acc.getKey() == null || acc.getValue() == null)
				{
					continue;
				}
				final Map<Integer, long[]> rows = new HashMap<>();
				for (Map.Entry<Integer, long[]> e : acc.getValue().entrySet())
				{
					final long[] w = e.getValue();
					if (e.getKey() != null && w != null && w.length >= 2 && w[1] > 0)
					{
						rows.put(e.getKey(), new long[]{w[0], w[1]});
					}
				}
				if (!rows.isEmpty())
				{
					limitWindows.put(acc.getKey(), rows);
				}
			}
		}
		flips.clear();
		if (s.flips != null)
		{
			flips.addAll(s.flips);
		}
		/* A sell already part-sold when this build first runs: its total was
		   counted off the flips list until now, and those flips are still
		   here under its token. Seeded once; the next save carries it. */
		for (Map<Integer, SlotState> account : slotsByAccount.values())
		{
			for (SlotState st : account.values())
			{
				if (!st.seedBooked)
				{
					continue;
				}
				st.seedBooked = false;
				for (Flip f : flips)
				{
					if (f.offerId == st.offerToken && f.itemId == st.itemId)
					{
						st.bookedQty += f.quantity;
						st.bookedProfit += f.profit;
					}
				}
				/* Booked under a build with no profit figures: shown as far
				   as anyone is concerned, so an upgrade pops nothing old. */
				st.shownQty = st.bookedQty;
				st.shownProfit = st.bookedProfit;
			}
		}
		openBuys.clear();
		nextLotSeq = Math.max(nextLotSeq, Math.max(1L, s.nextLotSeq));
		if (s.openBuys != null)
		{
			/* Sequence numbers are written from this build on; a save from
			   before has none, and its lots are numbered here, after every
			   number the save could have handed out, in the order they sit. */
			final boolean numbered = s.nextLotSeq > 0;
			for (Map.Entry<Integer, List<long[]>> e : s.openBuys.entrySet())
			{
				Deque<BuyLot> lots = new ArrayDeque<>();
				for (long[] l : e.getValue())
				{
					if (l == null || l.length < 2)
					{
						continue;
					}
					/* Length 2 is a save written before lots carried a time.
					   Those lots restore with time 0, so flips closed against
					   them report an unknown hold rather than a wrong one. */
					final long seq = numbered && l.length > 3 && l[3] > 0 && l[3] < s.nextLotSeq ? l[3] : nextLotSeq++;
					lots.add(new BuyLot((int) l[0], l[1], l.length > 2 ? l[2] : 0L, seq,
						l.length > 4 ? l[4] : 0L, l.length > 5 ? l[5] : 0L));
				}
				/* Newest first means highest seq first: keep the deque in seq
				   order whatever order the file had them in. */
				final List<BuyLot> sorted = new ArrayList<>(lots);
				sorted.sort((x, y) -> Long.compare(x.seq, y.seq));
				openBuys.put(e.getKey(), new ArrayDeque<>(sorted));
			}
		}
		/* A slot row from a save that did not record its bound: its offer was
		   listed before this restore, so every lot on record may be in it and
		   none bought from here on can. */
		for (Map<Integer, SlotState> account : slotsByAccount.values())
		{
			for (SlotState st : account.values())
			{
				if (st.lotsBefore <= 0 || st.lotsBefore > nextLotSeq)
				{
					st.lotsBefore = nextLotSeq;
				}
			}
		}
		if (s.limitWindows == null)
		{
			seedLimitWindows(System.currentTimeMillis());
		}
	}

	/**
	 * A save from before buy limits were tracked: rebuild the windows from
	 * what it does know — the flips it closed and the lots it still holds,
	 * each with the time it was bought — so a limit bought out just before
	 * the update is not offered again straight after it. Filed under the
	 * character the save was written for, the one most likely playing.
	 */
	private void seedLimitWindows(long now)
	{
		final List<long[]> buys = new ArrayList<>(); // {time, itemId, qty}
		for (Flip f : flips)
		{
			if (f.openedAt > 0 && f.openedAt <= now && now - f.openedAt < LIMIT_WINDOW_MS)
			{
				buys.add(new long[]{f.openedAt, f.itemId, f.quantity});
			}
		}
		for (Map.Entry<Integer, Deque<BuyLot>> e : openBuys.entrySet())
		{
			for (BuyLot lot : e.getValue())
			{
				if (lot.time > 0 && lot.time <= now && now - lot.time < LIMIT_WINDOW_MS)
				{
					buys.add(new long[]{lot.time, e.getKey(), lot.qty});
				}
			}
		}
		buys.sort((x, y) -> Long.compare(x[0], y[0]));
		for (long[] b : buys)
		{
			noteBuyForLimit((int) b[1], (int) b[2], b[0]);
		}
	}

	/** One character's saved slot rows, back into baselines. Every one is
	 *  marked restored: it came off disk, so growth measured against it
	 *  happened at a moment nobody recorded. */
	private Map<Integer, SlotState> readSlots(Map<Integer, long[]> rows, boolean oldFormat)
	{
		final Map<Integer, SlotState> out = new HashMap<>();
		for (Map.Entry<Integer, long[]> e : rows.entrySet())
		{
			final long[] l = e.getValue();
			if (e.getKey() == null || l == null || l.length < 4)
			{
				continue;
			}
			final SlotState st = new SlotState();
			st.itemId = (int) l[0];
			st.buy = l[1] != 0;
			st.qtySold = (int) l[2];
			st.spent = l[3];
			/* Terms were added after the rest. A save without them restores as
			   0, which onOffer reads as "not recorded" rather than as a
			   mismatch — see sameTerms. */
			st.price = l.length > 4 ? l[4] : 0L;
			st.totalQuantity = l.length > 5 ? (int) l[5] : 0;
			/* Carried across the restart so an offer resumed tomorrow still
			   groups with the fills it booked today. A save from before tokens
			   existed reads 0, and gets a fresh one — those earlier rows stand
			   alone, which is the honest outcome: nothing recorded says they
			   belonged together. */
			st.offerToken = l.length > 6 && l[6] != 0 ? l[6] : nextOfferToken++;
			st.restored = true;
			st.lotsBefore = l.length > 12 ? l[12] : 0L;
			final int pairs = l.length > 13 ? (int) Math.max(0, Math.min(l[13], (l.length - 14) / 2)) : 0;
			st.boxedAtListing = pairs > 0 ? java.util.Arrays.copyOfRange(l, 14, 14 + 2 * pairs) : new long[0];
			final int loose = 14 + 2 * pairs;
			if (l.length >= loose + 4)
			{
				st.looseQty = l[loose];
				st.looseCoins = l[loose + 1];
				st.shownLooseQty = l[loose + 2];
				st.shownLooseCoins = l[loose + 3];
			}
			st.legacy = oldFormat || (l.length > 7 && l[7] != 0);
			/* Added after the rest: a save without them has booked nothing
			   that this can vouch for, and starts at 0. Only with the token
			   they were booked under. */
			if (l.length > 9 && l[6] != 0)
			{
				st.bookedQty = l[8];
				st.bookedProfit = l[9];
				/* And how much of it has popped. A save from before the
				   figures counts all of it as shown: what it booked was
				   booked before there was anything to see. */
				st.shownQty = l.length > 11 ? l[10] : st.bookedQty;
				st.shownProfit = l.length > 11 ? l[11] : st.bookedProfit;
			}
			else
			{
				st.seedBooked = l.length > 6 && l[6] != 0;
			}
			out.put(e.getKey(), st);
		}
		return out;
	}

	/**
	 * Consume a cumulative offer snapshot. Returns the fill this snapshot
	 * produced, or null (baseline set / no growth / slot cleared).
	 */
	public synchronized TradeFill onOffer(long now, int slot, int itemId, String itemName,
		boolean buy, int qtySold, long spent, boolean emptied)
	{
		return onOffer(now, slot, itemId, itemName, buy, qtySold, spent, 0L, 0, emptied);
	}

	/**
	 * As above, told the offer's terms as well.
	 *
	 * {@code price} and {@code totalQuantity} are never used as numbers — only
	 * to recognise an offer. See {@link SlotState#price}.
	 */
	public synchronized TradeFill onOffer(long now, int slot, int itemId, String itemName,
		boolean buy, int qtySold, long spent, long price, int totalQuantity, boolean emptied)
	{
		final Map<Integer, SlotState> slots = slots();
		if (emptied)
		{
			slotsDirty |= slots.remove(slot) != null;
			return null;
		}
		SlotState st = slots.get(slot);
		if (st == null)
		{
			/*
			 * Never seen this slot on this character — so whatever the offer
			 * has already bought is history nobody has counted, and the offer
			 * itself is carrying the receipt: quantitySold and spent are the
			 * exact units and the exact gold, straight off the Exchange.
			 *
			 * This used to baseline at those numbers and book nothing, which
			 * threw the receipt away. That was the right call when baselines
			 * only lived in memory, because then every login looked like a
			 * first sighting and counting one would count the same offer again
			 * on every relog. Now that they persist per character, a first
			 * sighting really is the first, so the honest move is to start
			 * from zero and let the ordinary delta path book what is there.
			 *
			 * The one thing the offer does not carry is WHEN any of it filled,
			 * so this lot is marked the same way an offline one is.
			 */
			st = new SlotState();
			st.itemId = itemId;
			st.buy = buy;
			st.qtySold = 0;
			st.spent = 0;
			st.price = price;
			st.totalQuantity = totalQuantity;
			/* Only if there is history to attribute. A brand-new offer at zero
			   is about to be watched from the start, and its fills carry real
			   times. */
			st.restored = qtySold > 0;
			st.offerToken = nextOfferToken++;
			st.lotsBefore = nextLotSeq;
			if (!buy)
			{
				st.boxedAtListing = boxedNow(itemId, slot);
			}
			slots.put(slot, st);
			slotsDirty = true;
		}
		else if (st.itemId != itemId
			|| st.buy != buy
			/* Backwards is not the same offer. A slot holding less than it did
			   was emptied and refilled while we were not looking. */
			|| qtySold < st.qtySold
			|| !sameTerms(st, price, totalQuantity))
		{
			/*
			 * A DIFFERENT offer in a slot we have a record for. Baseline where
			 * it stands and book nothing — deliberately not the seeding above.
			 *
			 * "Replaced" is the ambiguous case: we may already have counted
			 * part of its predecessor, and telling a replacement apart from a
			 * misread of the same offer is exactly where a mistake would
			 * double count. "No record at all" is not ambiguous, which is why
			 * that branch is allowed to book and this one is not.
			 *
			 * The buy limit is another matter. A buy that replaced the slot's
			 * offer while nobody was watching — collected and re-placed on
			 * mobile, or with the client shut — has really bought what it
			 * shows, and the game counts it. Counted here, from now as any
			 * offline fill is, with no lot booked: for the limit an over-count
			 * costs a wait and an under-count is "still reccomending me that i
			 * buy this flip". Not for a legacy row or an upgrade placeholder,
			 * whose offers may already be in the lots the limit was seeded
			 * from, nor for a mismatch seen live, which is a misread.
			 */
			final boolean unseenGap = (st.restored || st.unwatched) && !st.legacy && st.itemId != NO_OFFER;
			st = new SlotState();
			st.itemId = itemId;
			st.buy = buy;
			st.qtySold = qtySold;
			st.spent = spent;
			st.price = price;
			st.totalQuantity = totalQuantity;
			st.offerToken = nextOfferToken++;
			st.lotsBefore = nextLotSeq;
			if (!buy)
			{
				st.boxedAtListing = boxedNow(itemId, slot);
			}
			slots.put(slot, st);
			slotsDirty = true;
			if (buy && qtySold > 0 && unseenGap)
			{
				noteBuyForLimit(itemId, qtySold, now);
			}
			return null;
		}
		int dQty = qtySold - st.qtySold;
		long dSpent = spent - st.spent;
		/* This baseline came off disk, so whatever grew against it grew while
		   the client was shut. The gold is real and the cost is exact; only
		   the moment is unknowable, and a lot that claims a fill time it does
		   not have would turn into a hold duration that was never measured. */
		boolean offline = st.restored;
		/* The slot could have changed hands since this baseline: it came off
		   disk, or from before a logout. Not when the baseline itself may be
		   another character's — see SlotState#legacy. */
		final boolean unseen = (st.restored || st.unwatched) && !st.legacy;
		st.qtySold = qtySold;
		st.spent = spent;
		st.restored = false;
		st.unwatched = false;
		st.legacy = false;
		/* Learn the terms if the save predates them, so the NEXT restart can
		   tell this offer apart from its replacement. */
		st.price = price;
		st.totalQuantity = totalQuantity;
		slotsDirty = true;
		/* One buy offer only ever spends more, and only by buying more, at no
		   more than its bid. A snapshot that breaks any of that is not the
		   baselined offer: less spent, or spent changed with nothing bought,
		   or charged over the bid. Across a gap the plugin could not see,
		   that is an identical offer collected and placed again — the routine
		   way to buy another limit's worth — and below it is booked from
		   zero. Watched live it can only be a misread, and books nothing. */
		final boolean notThisOffer = buy && price > 0
			&& (dSpent < 0 || (dQty == 0 && dSpent != 0) || (dQty > 0 && dSpent > (long) dQty * price));
		if (!notThisOffer && (dQty <= 0 || dSpent < 0))
		{
			return null;
		}
		/* A buy is never charged more than its bid. A delta that says it was
		   was measured against some other offer's baseline — a save from
		   before terms were kept matches anything — and booking it would put
		   a lot on the books above anything the player paid. The baseline has
		   already moved to this event, so the next delta is clean. Buys only:
		   whether a sell's spent is net of tax is not something to bet a
		   real sale on. */
		if (notThisOffer)
		{
			/* ...and that proves the baseline was another offer's: one offer
			   cannot charge over its own bid (nor spend less, nor spend
			   without buying). So this snapshot is a new offer
			   in the slot, and everything it shows is its own receipt. It used
			   to be dropped, which lost the replacement's whole buy — an
			   identical offer collected and re-placed while the plugin was not
			   watching (on mobile, or with the plugin off) went unrecorded.
			   Booked from zero instead, with no fill time since the moment is
			   unknown, and only if the receipt is itself within its bid.

			   Only across a gap the plugin could not see: a baseline off disk,
			   or from before a logout. Watched live, a slot cannot change
			   offers without an EMPTY in between, so there an over-bid delta
			   is a misread — and booking a whole receipt on a misread is how
			   the same purchase gets counted twice. */
			if (!unseen || qtySold <= 0 || spent > (long) qtySold * price)
			{
				return null;
			}
			st.offerToken = nextOfferToken++;
			st.bookedQty = 0;
			st.bookedProfit = 0;
			st.shownQty = 0;
			st.shownProfit = 0;
			st.looseQty = 0;
			st.looseCoins = 0;
			st.shownLooseQty = 0;
			st.shownLooseCoins = 0;
			dQty = qtySold;
			dSpent = spent;
			offline = true;
		}
		TradeFill fill = new TradeFill(now, itemId, itemName, buy, dQty, dSpent);
		fills.add(fill);
		if (fills.size() > MAX_FILLS)
		{
			fills.remove(0);
		}
		if (buy)
		{
			openBuys.computeIfAbsent(itemId, k -> new ArrayDeque<>())
				.addLast(new BuyLot(dQty, dSpent, offline ? 0L : now, nextLotSeq++, accountHash, st.offerToken));
			/* An offline fill's moment is unknown, so it is counted from now:
			   the window then ends a little later than the game's does, which
			   costs a wait, never a buy over the limit. */
			noteBuyForLimit(itemId, dQty, now);
		}
		else
		{
			matchSell(fill, st);
		}
		return fill;
	}

	/**
	 * Whether this event's terms match the ones the baseline was taken under.
	 *
	 * A 0 on either side means "not recorded" — a save written before terms
	 * were kept, or the 8-argument entry point the tests use — and is not a
	 * mismatch. Treating unknown as different would throw away a baseline
	 * that is very probably the same offer, and throwing one away is the
	 * failure this whole mechanism exists to stop.
	 */
	private static boolean sameTerms(SlotState st, long price, int totalQuantity)
	{
		if (st.price > 0 && price > 0 && st.price != price)
		{
			return false;
		}
		return !(st.totalQuantity > 0 && totalQuantity > 0 && st.totalQuantity != totalQuantity);
	}

	/**
	 * Match a sell fill against the open buy lots of its item, newest first,
	 * among the lots bought before its offer was listed, and book what it
	 * made against the offer it came from.
	 */
	private void matchSell(TradeFill sell, SlotState offer)
	{
		final long offerToken = offer.offerToken;
		final long[] c = charge(sell.itemId, sell.quantity, offer, true);
		final int matched = (int) c[0];
		final long buySpent = c[1];
		final long openedAt = c[2];
		long unitSell = Math.round((double) sell.spent / sell.quantity);
		/* Units nothing on record paid for — "oo you right i just cooked
		   these": what they brought in, after tax, at the same unit price
		   the flips are booked at. Not profit; the square pops it in gold. */
		final int loose = sell.quantity - Math.max(0, matched);
		if (loose > 0)
		{
			offer.looseQty += loose;
			offer.looseCoins += (unitSell - taxPerItem(unitSell, sell.itemId)) * loose;
		}
		if (matched <= 0)
		{
			return;
		}
		long sellGross = unitSell * matched;
		long tax = taxPerItem(unitSell, sell.itemId) * matched;
		Flip flip = new Flip(offerToken, openedAt, sell.time, sell.itemId, sell.itemName, matched, buySpent, sellGross, tax);
		offer.bookedQty += matched;
		offer.bookedProfit += flip.profit;
		flips.add(flip);
		if (flips.size() > MAX_FLIPS)
		{
			flips.remove(0);
		}
		sessionProfit += flip.profit;
		lifetimeProfit += flip.profit;
		/* Last, and swallowed. The ledger is a record OF the flip; it must
		   never be able to stop one being booked, and a sidebar that has
		   stopped counting your profit because a disk was full is a far worse
		   failure than a history page missing a row. */
		try
		{
			flipSink.accept(flip);
		}
		catch (RuntimeException ignore)
		{
			// the flip itself is booked; the ledger can miss it
		}
	}

	/**
	 * A booked trade corrected by the player: the recent flips {@code fix}
	 * changes are replaced, and lifetime and session profit move by what the
	 * correction changed — worked out by the caller over the whole ledger,
	 * which reaches further back than the flips kept here.
	 */
	public synchronized void applyCorrection(java.util.function.UnaryOperator<Flip> fix, long lifetimeDelta,
		long sessionDelta, long offerToken, int itemId)
	{
		flips.replaceAll(fix);
		lifetimeProfit += lifetimeDelta;
		sessionProfit += sessionDelta;
		/* The offer may still be in its slot, selling: its "Made X so far"
		   moves by the same amount. The shown mark by the share of it on
		   units already shown, so the correction itself never pops as a
		   sale and a part not yet shown pops at its corrected figure. */
		for (Map<Integer, SlotState> account : slotsByAccount.values())
		{
			for (SlotState st : account.values())
			{
				if (!st.buy && st.offerToken == offerToken && st.itemId == itemId && st.bookedQty > 0)
				{
					st.bookedProfit += lifetimeDelta;
					st.shownProfit += Math.round(lifetimeDelta * (Math.min(st.shownQty, st.bookedQty) / (double) st.bookedQty));
					slotsDirty = true;
				}
			}
		}
	}

	public synchronized List<Flip> getFlips()
	{
		return new ArrayList<>(flips);
	}

	/**
	 * What the offer now in {@code slot} has booked so far: {units, profit}
	 * over the flips its own sales closed, or null when it has booked none.
	 *
	 * The slot's hover priced only the part still listed — "+85.7K" on an
	 * offer that had already sold 6,162 for +295K: "it should atleast say
	 * 295k of x amount total 85k left". Units as well as profit, because a
	 * sale the plugin could not book (sold while it was not watching, or
	 * with no buy on record) is in the offer's own sold count and not here,
	 * and the hover has to say how much its figure covers.
	 */
	public synchronized long[] bookedBy(int slot)
	{
		final SlotState st = slots().get(slot);
		return st != null && st.bookedQty > 0 ? new long[]{st.bookedQty, st.bookedProfit} : null;
	}

	/**
	 * What the sell now in {@code slot} has booked that has not yet been
	 * shown as a profit figure over its square: {units, profit}, or null.
	 *
	 * "even if i missed it live, the next time i load into this ge screen,
	 * it should have said +64kgp over rune darts in that square". Kept here,
	 * on the offer and saved with it, rather than queued in the overlay:
	 * a queue in memory lost the figure to a restart, carried it across to
	 * a new offer of the same item relisted on mobile, and had to be told
	 * whose it was. The slot's record already knows all three.
	 *
	 * Only for a sell of {@code itemId}, the offer the Exchange is showing in
	 * the slot; anything else answers null.
	 *
	 * {units, gp, kind}: kind {@link #UNSEEN_PROFIT} for booked profit, or
	 * {@link #UNSEEN_COINS} for coins from units no buy on record paid for —
	 * "yes add the gold coins pop", for the sharks that were cooked, not
	 * bought. One figure a square: when both are waiting, the profit is the
	 * one shown and {@link #markShown} counts the coins as shown with it.
	 */
	public synchronized long[] unseenBy(int slot, int itemId)
	{
		final SlotState st = slots().get(slot);
		if (st == null || st.buy || st.itemId != itemId)
		{
			return null;
		}
		if (st.bookedQty > st.shownQty)
		{
			return new long[]{st.bookedQty - st.shownQty, st.bookedProfit - st.shownProfit, UNSEEN_PROFIT};
		}
		if (st.looseQty > st.shownLooseQty)
		{
			return new long[]{st.looseQty - st.shownLooseQty, st.looseCoins - st.shownLooseCoins, UNSEEN_COINS};
		}
		return null;
	}

	/** Kinds of figure {@link #unseenBy} answers with. */
	public static final long UNSEEN_PROFIT = 0;
	public static final long UNSEEN_COINS = 1;

	/** Every character's slots: all they have booked counts as shown. For
	 *  the figures being switched off — nothing waits to pop later. */
	public synchronized void markAllShown()
	{
		for (Map<Integer, SlotState> account : slotsByAccount.values())
		{
			for (SlotState st : account.values())
			{
				slotsDirty |= allShown(st);
			}
		}
	}

	/** Everything {@code slot}'s offer has sold has now been shown. */
	public synchronized void markShown(int slot)
	{
		final SlotState st = slots().get(slot);
		if (st != null)
		{
			slotsDirty |= allShown(st);
		}
	}

	/** Whether {@code slot}'s offer has sold anything not yet shown. */
	public synchronized boolean waiting(int slot)
	{
		final SlotState st = slots().get(slot);
		return st != null && (st.bookedQty != st.shownQty || st.looseQty != st.shownLooseQty);
	}

	/** {@code st}'s profit and coins all count as shown; true if that moved
	 *  either mark. */
	private static boolean allShown(SlotState st)
	{
		if (st.shownQty == st.bookedQty && st.shownProfit == st.bookedProfit
			&& st.shownLooseQty == st.looseQty && st.shownLooseCoins == st.looseCoins)
		{
			return false;
		}
		st.shownQty = st.bookedQty;
		st.shownProfit = st.bookedProfit;
		st.shownLooseQty = st.looseQty;
		st.shownLooseCoins = st.looseCoins;
		return true;
	}

	/**
	 * Count {@code qty} bought at {@code now} against this character's buy
	 * limit for the item: into the open window, or as the start of a new one
	 * when the last has run its four hours. Windows that have ended are
	 * dropped as it goes, so the map holds no more than the last four hours.
	 */
	synchronized void noteBuyForLimit(int itemId, int qty, long now)
	{
		if (qty <= 0)
		{
			return;
		}
		final Map<Integer, long[]> mine = limitWindows.computeIfAbsent(accountHash, k -> new HashMap<>());
		mine.values().removeIf(w -> now >= w[0] + LIMIT_WINDOW_MS);
		final long[] w = mine.get(itemId);
		if (w == null)
		{
			mine.put(itemId, new long[]{now, qty});
		}
		else
		{
			w[1] += qty;
		}
		if (limitWindows.size() > MAX_ACCOUNTS)
		{
			limitWindows.keySet().removeIf(k -> k != accountHash && limitWindows.size() > MAX_ACCOUNTS);
		}
	}

	/** Units of the item this character has bought in its open buy-limit
	 *  window, or 0 when there is none (never bought, or four hours up). */
	public synchronized int boughtTowardLimit(int itemId, long now)
	{
		final long[] w = openWindow(itemId, now);
		return w == null ? 0 : (int) Math.min(Integer.MAX_VALUE, w[1]);
	}

	/** When this character's buy limit on the item is whole again, or 0
	 *  when it already is. */
	public synchronized long limitResetsAt(int itemId, long now)
	{
		final long[] w = openWindow(itemId, now);
		return w == null ? 0 : w[0] + LIMIT_WINDOW_MS;
	}

	/** How long until a time {@code ms} away, for a person: "2h 14m",
	 *  "38m", "under a minute". */
	static String untilText(long ms)
	{
		final long mins = Math.max(0, ms) / 60_000;
		if (mins < 1)
		{
			return "under a minute";
		}
		return mins >= 60 ? (mins / 60) + "h " + (mins % 60) + "m" : mins + "m";
	}

	/** A card's note when the 4h limit is used up. Short, and with no
	 *  " · ", because a buy card shows its note up to that dot on one line
	 *  of a 182px card — and when it comes back is the part that matters. */
	static String limitUsedNote(long msLeft)
	{
		return "4h limit used, back in " + untilText(msLeft);
	}

	/** A card's note when some of the 4h limit is left: how much on the
	 *  card, when the rest comes back on the hover. */
	static String limitLeftNote(long left, long msLeft)
	{
		return net.runelite.client.util.QuantityFormatter.quantityToStackSize(left) + " left of 4h limit"
			+ " \u00b7 the whole limit back in " + untilText(msLeft);
	}

	private long[] openWindow(int itemId, long now)
	{
		final Map<Integer, long[]> mine = limitWindows.get(accountHash);
		final long[] w = mine != null ? mine.get(itemId) : null;
		return w != null && now < w[0] + LIMIT_WINDOW_MS ? w : null;
	}

	public synchronized List<TradeFill> getFills()
	{
		return new ArrayList<>(fills);
	}

	public synchronized long getSessionProfit()
	{
		return sessionProfit;
	}

	public synchronized long getLifetimeProfit()
	{
		return lifetimeProfit;
	}

	public synchronized long getSessionStartMillis()
	{
		return sessionStartMillis;
	}

	/** Open buy lots totalled per item (qty still unsold, gp still spent on
	 *  it) — the basis for mark-to-market "unrealized profit". Copies out so
	 *  callers can't mutate tracker state. */
	public synchronized Map<Integer, long[]> getOpenBuyTotals()
	{
		Map<Integer, long[]> out = new HashMap<>();
		for (Map.Entry<Integer, Deque<BuyLot>> e : openBuys.entrySet())
		{
			long qty = 0, spent = 0;
			for (BuyLot lot : e.getValue())
			{
				qty += lot.qty;
				spent += lot.spent;
			}
			if (qty > 0)
			{
				out.put(e.getKey(), new long[]{qty, spent});
			}
		}
		return out;
	}

	/**
	 * Open lots priced against what is actually held: per item, {qty, spent}
	 * of the NEWEST lots covering at most {@code held} units, then {qty,
	 * spent} of the older ones left over — {qty, spent, olderQty, olderSpent}.
	 *
	 * Sales are charged to the newest lots too (see {@link #charge}), so this
	 * and the booking agree. When lots add up to
	 * more than is held, the extra is older stock that left without the
	 * plugin seeing it go — sold on another client, with the plugin off, or
	 * held on another character. Averaging it in priced a stack bought at
	 * 277 at PAID @ 330: 13,418 at 277 blended with 24,500 left over from an
	 * earlier stack at 359. What you hold is what you bought last.
	 *
	 * An item with nothing held (or not in the map) gets its plain totals.
	 */
	public synchronized Map<Integer, long[]> getHeldCost(Map<Integer, Long> held)
	{
		final Map<Integer, long[]> out = new HashMap<>();
		for (Map.Entry<Integer, Deque<BuyLot>> e : openBuys.entrySet())
		{
			/* The same lots a sale listed now could be charged: this
			   character's, not waiting in a buy's box. Box units are in
			   {@code held} when the box was seen; they are priced by their
			   own lots, not the stack's. */
			final Map<Long, Long> boxed = new HashMap<>();
			final long[] pairs = boxedNow(e.getKey(), -1);
			for (int i = 0; i + 1 < pairs.length; i += 2)
			{
				boxed.merge(pairs[i], pairs[i + 1], Long::sum);
			}
			long seenInBoxes = 0;
			for (SlotState b : slots().values())
			{
				if (b.buy && b.itemId == e.getKey() && b.boxUnits > 0)
				{
					seenInBoxes += b.boxUnits;
				}
			}
			long qty = 0, spent = 0;
			final List<long[]> free = new ArrayList<>(); // newest first: {qty, spent}
			for (java.util.Iterator<BuyLot> it = e.getValue().descendingIterator(); it.hasNext(); )
			{
				final BuyLot lot = it.next();
				if (!mine(lot))
				{
					continue;
				}
				final long n = lot.qty - Math.min(lot.qty, boxed.getOrDefault(lot.seq, 0L));
				if (n <= 0)
				{
					continue;
				}
				final long sp = n == lot.qty ? lot.spent : Math.round(lot.spent * (n / (double) lot.qty));
				free.add(new long[]{n, sp});
				qty += n;
				spent += sp;
			}
			if (qty <= 0)
			{
				continue;
			}
			final long h = held != null ? Math.max(0, held.getOrDefault(e.getKey(), 0L) - seenInBoxes) : 0L;
			if (h <= 0 || qty <= h)
			{
				out.put(e.getKey(), new long[]{qty, spent, 0, 0});
				continue;
			}
			long keepQty = 0, keepSpent = 0;
			for (long[] f : free)
			{
				if (keepQty >= h)
				{
					break;
				}
				final long take = Math.min(f[0], h - keepQty);
				keepSpent += take == f[0] ? f[1] : Math.round(f[1] * (take / (double) f[0]));
				keepQty += take;
			}
			out.put(e.getKey(), new long[]{keepQty, keepSpent, qty - keepQty, spent - keepSpent});
		}
		return out;
	}

	/**
	 * The batches behind the stack you hold, for the hover: per item, {qty,
	 * spent} pairs, oldest first, flattened — the same lots {@link
	 * #getHeldCost} prices the stack from, one batch per buy offer (its fills
	 * added together). "it cant remember 2 costs paid?" It does: 10K @ 349,
	 * 10K @ 333, 10K @ 329, and a sale uses the newest first. Lots from saves
	 * before buys recorded their offer are batched by price.
	 */
	public synchronized Map<Integer, long[]> heldBatches(Map<Integer, Long> held)
	{
		final Map<Integer, long[]> out = new HashMap<>();
		for (Map.Entry<Integer, Deque<BuyLot>> e : openBuys.entrySet())
		{
			final Map<Long, Long> boxed = new HashMap<>();
			final long[] pairs = boxedNow(e.getKey(), -1);
			for (int i = 0; i + 1 < pairs.length; i += 2)
			{
				boxed.merge(pairs[i], pairs[i + 1], Long::sum);
			}
			long seenInBoxes = 0;
			for (SlotState b : slots().values())
			{
				if (b.buy && b.itemId == e.getKey() && b.boxUnits > 0)
				{
					seenInBoxes += b.boxUnits;
				}
			}
			long total = 0;
			for (BuyLot lot : e.getValue())
			{
				if (mine(lot))
				{
					total += lot.qty - Math.min(lot.qty, boxed.getOrDefault(lot.seq, 0L));
				}
			}
			final long h = held != null ? Math.max(0, held.getOrDefault(e.getKey(), 0L) - seenInBoxes) : 0L;
			final long want = h <= 0 || total <= h ? total : h;
			/* Newest first, as getHeldCost walks them, up to what is held;
			   each piece {qty, spent, batch} where batch is the buy offer, or
			   for an unrecorded one its rounded price. */
			final List<long[]> pieces = new ArrayList<>();
			long taken = 0;
			for (java.util.Iterator<BuyLot> it = e.getValue().descendingIterator(); it.hasNext() && taken < want; )
			{
				final BuyLot lot = it.next();
				if (!mine(lot))
				{
					continue;
				}
				final long n = lot.qty - Math.min(lot.qty, boxed.getOrDefault(lot.seq, 0L));
				if (n <= 0)
				{
					continue;
				}
				final long take = Math.min(n, want - taken);
				final long sp = take == lot.qty ? lot.spent : Math.round(lot.spent * (take / (double) lot.qty));
				final long batch = lot.source != 0 ? lot.source : -Math.round(lot.spent / (double) lot.qty) - 1;
				final long[] last = pieces.isEmpty() ? null : pieces.get(pieces.size() - 1);
				if (last != null && last[2] == batch)
				{
					last[0] += take;
					last[1] += sp;
				}
				else
				{
					pieces.add(new long[]{take, sp, batch});
				}
				taken += take;
			}
			if (pieces.isEmpty())
			{
				continue;
			}
			final long[] flat = new long[pieces.size() * 2];
			for (int i = 0; i < pieces.size(); i++)
			{
				final long[] pc = pieces.get(pieces.size() - 1 - i); // oldest first
				flat[2 * i] = pc[0];
				flat[2 * i + 1] = pc[1];
			}
			out.put(e.getKey(), flat);
		}
		return out;
	}

	/**
	 * Drop the oldest lots of one item until at most {@code keep} units are
	 * left — the player confirming that the older ones {@link #getHeldCost}
	 * set aside are gone. Sales are charged to the newest lots, so these are
	 * reached only by a sale bigger than everything bought since; this takes
	 * them off the record and out of the older-buys note. Returns what was
	 * dropped, {qty, spent}, or null when nothing was over.
	 */
	public synchronized long[] forgetOlderThan(int itemId, long keep)
	{
		final Deque<BuyLot> lots = openBuys.get(itemId);
		if (lots == null)
		{
			return null;
		}
		long total = 0;
		for (BuyLot lot : lots)
		{
			total += mine(lot) ? lot.qty : 0;
		}
		long excess = total - Math.max(0, keep);
		if (excess <= 0)
		{
			return null;
		}
		long qty = 0, spent = 0;
		for (java.util.Iterator<BuyLot> it = lots.iterator(); excess > 0 && it.hasNext(); )
		{
			final BuyLot lot = it.next();
			if (!mine(lot))
			{
				continue;
			}
			if (lot.qty <= excess)
			{
				it.remove();
				qty += lot.qty;
				spent += lot.spent;
				excess -= lot.qty;
			}
			else
			{
				final long cut = Math.round(lot.spent * (excess / (double) lot.qty));
				lot.qty -= (int) excess;
				lot.spent -= cut;
				qty += excess;
				spent += cut;
				excess = 0;
			}
		}
		if (lots.isEmpty())
		{
			openBuys.remove(itemId);
		}
		return new long[]{qty, spent};
	}

	/** One item's open lots totalled, {qty, spent}, or null when none. */
	public synchronized long[] getOpenBuyTotal(int itemId)
	{
		final Deque<BuyLot> lots = openBuys.get(itemId);
		long qty = 0, spent = 0;
		for (BuyLot lot : lots != null ? lots : new ArrayDeque<BuyLot>())
		{
			if (!mine(lot))
			{
				continue;
			}
			qty += lot.qty;
			spent += lot.spent;
		}
		return qty > 0 ? new long[]{qty, spent} : null;
	}

	/** One item's open lots for a forget prompt: {qty, spent, newest lot},
	 *  or null when none. The third is what {@link #forgetOpenBuys} takes. */
	public synchronized long[] getOpenBuyRecord(int itemId)
	{
		final Deque<BuyLot> lots = openBuys.get(itemId);
		long qty = 0, spent = 0, newest = 0;
		for (BuyLot lot : lots != null ? lots : new ArrayDeque<BuyLot>())
		{
			if (!mine(lot))
			{
				continue;
			}
			qty += lot.qty;
			spent += lot.spent;
			newest = Math.max(newest, lot.seq);
		}
		return qty > 0 ? new long[]{qty, spent, newest} : null;
	}

	/** The player has logged out. Every baseline is now from before a gap
	 *  in which the slots could have changed hands — see SlotState#unwatched. */
	public synchronized void markSlotsUnwatched()
	{
		for (Map<Integer, SlotState> account : slotsByAccount.values())
		{
			for (SlotState st : account.values())
			{
				st.unwatched = true;
				st.boxUnits = -1;
			}
		}
	}

	/**
	 * Drop one item's open buy lots, up to and including lot {@code upTo}
	 * from {@link #getOpenBuyRecord}: the player telling the tracker that
	 * what it says they paid is wrong. Lots booked after the prompt was
	 * read — a buy filling while it was open — are kept. Returns what was
	 * dropped, {qty, spent}, or null when there was nothing.
	 *
	 * For lots the tracker cannot be trusted on — builds before 0.7.2
	 * booked a live offer's whole receipt again after a world hop, so an
	 * item could hold the same purchase twice. Lots cannot be rebuilt from
	 * the fills (those are kept only for the session), so forgetting is the
	 * repair: the item shows as cost-unknown until it is bought again.
	 * Live offers keep their baselines, so fills after this book normally.
	 * Flip history and lifetime profit are left alone.
	 */
	public synchronized long[] forgetOpenBuys(int itemId, long upTo)
	{
		final Deque<BuyLot> lots = openBuys.get(itemId);
		if (lots == null)
		{
			return null;
		}
		long qty = 0, spent = 0;
		for (java.util.Iterator<BuyLot> it = lots.iterator(); it.hasNext(); )
		{
			final BuyLot lot = it.next();
			if (lot.seq <= upTo && mine(lot))
			{
				qty += lot.qty;
				spent += lot.spent;
				it.remove();
			}
		}
		if (lots.isEmpty())
		{
			openBuys.remove(itemId);
		}
		return qty > 0 ? new long[]{qty, spent} : null;
	}

	/** Reset the SESSION counter only — lifetime and history survive. */
	public synchronized void resetSession()
	{
		sessionProfit = 0;
		sessionStartMillis = System.currentTimeMillis();
	}

}

package com.pocketge.tracker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.Collections;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * What the plugin knows about your 8 Grand Exchange slots, drawn onto the
 * slots themselves: a coloured border (green while the offer is still
 * competitively priced, red once it has drifted and wants repricing — the
 * same call the sidebar's ADJUST_BUY/ADJUST_SELL suggestions make), and, on
 * hover, what the offer actually makes you, measured against what the plugin
 * watched you pay.
 *
 * There is deliberately NO progress bar here. The game already prints the
 * quantity in the box, and a bar drawn over Jagex's own interface is decor
 * competing with the numbers it duplicates. Progress belongs on the sidebar
 * strip, where the slot is a 32px sprite with nothing else to say — see
 * GeSlotsPanel.
 *
 * Empty slots are left alone. A slot you have told the plugin to stop
 * advising on keeps its tooltip but loses the red border — see
 * {@link SlotView#adviceSkipped}.
 */
@Singleton
public class GeOfferGridOverlay extends Overlay
{
	/* One copy of each, in GeSlotsPanel: the strip and this grid describe
	   the same slots, and two hand-written copies of a colour drift. */
	private static final Color OK_COLOR = GeSlotsPanel.OK_COLOR;
	private static final Color COLLECT_COLOR = GeSlotsPanel.COLLECT_COLOR;
	/** Brand gold, matching the ring the bank overlay puts on a recommended
	 *  stack — one colour across the whole plugin for "this is the thing the
	 *  panel is talking about, click here". */
	/*
	 * White, for a buy and for a sell alike.
	 *
	 * This was brand gold, which read as "buy" next to a card whose buy
	 * colour is gold — and there was no sell equivalent at all, so a sell
	 * card pointed at nothing. Reported as "buy advice gets a yellow buy
	 * over buy slot in ge, but the sell advice isnt doing the opposite".
	 *
	 * The ring is not classifying the trade; the button underneath it already
	 * says Buy or Sell in the game's own words. It is saying "act here", and
	 * white is what the rest of the plugin uses for that — LEAD_RIM on the
	 * price box you are about to type into, and the bank square for the stack
	 * the sidebar is talking about. Same value as both.
	 */
	private static final Color ACT_HERE_COLOR = new Color(0xF2, 0xF2, 0xF2);
	private static final int[] SLOT_WIDGETS = {
		InterfaceID.GeOffers.INDEX_0, InterfaceID.GeOffers.INDEX_1, InterfaceID.GeOffers.INDEX_2,
		InterfaceID.GeOffers.INDEX_3, InterfaceID.GeOffers.INDEX_4, InterfaceID.GeOffers.INDEX_5,
		InterfaceID.GeOffers.INDEX_6, InterfaceID.GeOffers.INDEX_7,
	};

	/** One slot, as the overlay needs it. Built on the client thread in
	 *  PocketGeTrackerPlugin and published as one immutable map, so a render
	 *  can never catch half of an update. */
	public static class SlotView
	{
		public String itemName;
		public boolean buy;
		public int filled;
		public int total;
		/** True when the advisor wants this offer repriced. */
		public boolean needsAdjust;
		/** Done — bought, sold or cancelled — with something to collect. */
		public boolean ready;
		/** True when you have right-clicked the slot and told the plugin you
		 *  are pricing this one yourself. Suppresses the red border. */
		public boolean adviceSkipped;
		/** Projected profit after tax, or null when there is no cost basis
		 *  to measure it against. Never guessed: a stack with no tracked
		 *  purchase gets null, not zero. A buy: the whole offer, if it flips.
		 *  A sell: the part still listed — what has sold is booked already,
		 *  in {@link #bookedProfit}. */
		public Long projectedProfit;
		/** A sell: what its sales so far have booked, from the flips they
		 *  closed; null before the first. */
		public Long bookedProfit;
		/** How many units {@link #bookedProfit} is over. Fewer than have
		 *  sold when some sold where the plugin could not book them. */
		public long bookedUnits;
		/** What the offer is listed at, and what it should be listed at.
		 *  Both 0 when there is nothing to say. The red border used to be the
		 *  entire message, and a red box around an offer reads as "cancel
		 *  this" long before it reads as "edit this". */
		public long offerPrice;
		public long targetPrice;
		/** True when repricing would fill you into a loser, so the honest
		 *  advice is to take a different flip rather than chase this one. */
		public boolean noMargin;
		/** A buy that fills at a loss: targetPrice is a LOWER bid, and
		 *  breakEven the most that can be bid for +0. */
		public boolean losing;
		public long breakEven;
		/**
		 * SELL only: what the whole offer fetches after tax, at the price this
		 * tooltip is talking about — the target when there is one, the listed
		 * price otherwise.
		 *
		 * Not a profit, and never painted as one. It needs no cost basis,
		 * which is the point: a stack held since before the plugin watched you
		 * buy it has no profit to show, and "Cost unknown, so no profit to
		 * show." was the whole money line on those — a sentence that answers
		 * the question by declining it. Asked for directly: "it should still
		 * say how much this trade is going to make me, in addition to asking
		 * me to adjust the porce".
		 */
		public Long grossValue;
	}

	private final Client client;
	private final TooltipManager tooltipManager;
	/** slot index (0-7) -> what to draw. A slot absent from the map draws
	 *  nothing: empty, or the advisor has nothing fresh enough to say. */
	private volatile Map<Integer, SlotView> slots = Collections.emptyMap();

	@Inject
	private GeOfferGridOverlay(Client client, TooltipManager tooltipManager)
	{
		this.client = client;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Called from the plugin whenever suggestions are recomputed. */
	public void setSlots(Map<Integer, SlotView> bySlot)
	{
		this.slots = bySlot != null ? bySlot : Collections.emptyMap();
	}

	/** The item the card is proposing you trade, or null. Volatile: written
	 *  on the Swing EDT when the card changes, read here every frame. */
	private volatile Integer actPromptItemId;
	/** …and which side, so the ring lands on Sell rather than Buy. */
	private volatile boolean actPromptSell;

	/** Whether the Exchange window is open, on any of its screens: the
	 *  squares are loaded with it, and only hidden on an offer's own screen,
	 *  where the sale's figure should still wait for its square. Client
	 *  thread. */
	static boolean exchangeOpen(Client client)
	{
		for (int id : SLOT_WIDGETS)
		{
			if (client.getWidget(id) != null)
			{
				return true;
			}
		}
		return false;
	}

	/** Tell the overlay what the panel is proposing, so it can point at where
	 *  that trade starts — an empty slot's Buy or Sell button. Null for no
	 *  card, which is what stops the ring appearing when there is nothing to
	 *  click. */
	public void setActionPrompt(Integer itemId, boolean sell)
	{
		this.actPromptItemId = itemId;
		this.actPromptSell = sell;
	}

	/** "+2,000 gp" rising off a slot as a batch of its sell goes through. */
	private final ProfitPops pops = new ProfitPops();

	/**
	 * Where the figures come from: what each slot's sell has booked and not
	 * yet shown. The plugin answers from the tracker's saved slot records,
	 * which is what makes a figure outlast a restart, belong to one
	 * character and one offer — see FlipTracker.unseenBy. Client thread,
	 * like render.
	 */
	public interface PopSource
	{
		/** {units, gp, kind} not yet shown for the sell in {@code slot} —
		 *  kind FlipTracker.UNSEEN_PROFIT or UNSEEN_COINS — or null for
		 *  nothing to show (or none of the plugin's business). */
		long[] unseen(int slot);

		/** It is on screen now: count all of it as shown. */
		void shown(int slot);
	}

	private volatile PopSource popSource;
	/** The time render works to. A field so a test can move it. */
	java.util.function.LongSupplier clock = System::currentTimeMillis;

	public void setPopSource(PopSource source)
	{
		popSource = source;
	}

	/** Every figure off the screen: the setting switched off. */
	public void clearPops()
	{
		pops.clear();
	}

	@Override
	public java.awt.Dimension render(Graphics2D graphics)
	{
		final Map<Integer, SlotView> current = slots;
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		drawActionPrompt(graphics, current);
		drawSlots(graphics, current);
		/* Last, so the figure is over the borders rather than under them. */
		drawPops(graphics);
		return null;
	}

	private void drawPops(Graphics2D graphics)
	{
		/* Only over the slot screen: a square counts as on screen while its
		   widget is loaded and showing. With the Exchange shut, or on an
		   offer's own screen, what a sell booked stays unshown on its record
		   — "even if i missed it live, the next time i load into this ge
		   screen, it should have said +64kgp over rune darts in that
		   square" — and pops the first frame its square is back. */
		final Rectangle[] square = new Rectangle[SLOT_WIDGETS.length];
		for (int slot = 0; slot < SLOT_WIDGETS.length; slot++)
		{
			final Widget w = client.getWidget(SLOT_WIDGETS[slot]);
			final Rectangle b = w == null || w.isHidden() ? null : w.getBounds();
			square[slot] = b == null || b.isEmpty() ? null : b;
		}
		final long now = clock.getAsLong();
		final PopSource source = popSource;
		if (source != null)
		{
			for (int slot = 0; slot < square.length; slot++)
			{
				final long[] unseen = square[slot] != null ? source.unseen(slot) : null;
				if (unseen != null && unseen[0] > 0)
				{
					pops.start(slot, unseen[1], coins(unseen), now);
					source.shown(slot);
				}
			}
		}
		for (ProfitPops.Pop p : pops.running(now, slot -> slot >= 0 && slot < square.length && square[slot] != null))
		{
			ProfitPops.draw(graphics, square[p.slot], p, now, FontManager.getRunescapeBoldFont());
		}
	}

	/** Whether an unseen figure is coins in rather than profit. */
	static boolean coins(long[] unseen)
	{
		return unseen.length > 2 && unseen[2] == FlipTracker.UNSEEN_COINS;
	}

	private void drawSlots(Graphics2D graphics, Map<Integer, SlotView> current)
	{
		if (current.isEmpty())
		{
			return;
		}
		final Point mouse = client.getMouseCanvasPosition();
		boolean tipShown = false;
		for (Map.Entry<Integer, SlotView> e : current.entrySet())
		{
			final int slot = e.getKey();
			final SlotView v = e.getValue();
			if (slot < 0 || slot >= SLOT_WIDGETS.length || v == null)
			{
				continue;
			}
			final Widget w = client.getWidget(SLOT_WIDGETS[slot]);
			if (w == null || w.isHidden())
			{
				continue;
			}
			final Rectangle bounds = w.getBounds();
			if (bounds == null || bounds.isEmpty())
			{
				continue;
			}

			/* A border only when there is something to say: white, "act
			   here", when it needs a new price, green when it is done — see
			   GeSlotsPanel.box, which the sidebar squares share.
			   An offer that is working gets none — the game's own box already
			   shows it working, and a ring round every busy slot would be
			   eight borders saying "nothing to see". The hover still works on
			   all of them. */
			final Color border = v.ready ? COLLECT_COLOR
				: v.adviceSkipped || !v.needsAdjust ? null
				: GeSlotsPanel.REPRICE_COLOR;
			if (border != null)
			{
				/* Green a pixel heavier than the sidebar's, white a touch
				   under full: see GeSlotsPanel.COLLECT_BOX_PX. */
				final boolean done = border == COLLECT_COLOR;
				graphics.setColor(done ? border : GeSlotsPanel.REPRICE_BOX);
				GeSlotsPanel.frame(graphics, bounds.x, bounds.y, bounds.width, bounds.height,
					done ? GeSlotsPanel.COLLECT_BOX_PX + 1 : 2);
			}

			/* One tooltip, ever. Adjacent slots can report overlapping bounds,
			   and the loop happily added a tooltip for each — two long blocks
			   of text drawn over each other and over the slots, which is how
			   they became unreadable. First match wins and the rest are
			   skipped. */
			if (!tipShown && mouse != null && bounds.contains(mouse.getX(), mouse.getY()))
			{
				tipShown = true;
				tooltipManager.add(TipStyle.tooltip(tooltipText(v)));
			}
		}
	}

	/**
	 * Ring the Buy or Sell button of a free slot, matching what the card is
	 * proposing.
	 *
	 * The Exchange screen is eight identical boxes with two identical little
	 * arrows each, and the panel telling you to trade something does not say
	 * where that starts. This does — for either side, since a sell begins in
	 * a free slot exactly as a buy does.
	 *
	 * The button has no named widget id — InterfaceID.GeOffers stops at
	 * INDEX_0..7, the slot containers — so it is found by asking each child
	 * what its right-click action says. That is sturdier than a hardcoded
	 * child index, which would silently ring the wrong arrow the first time
	 * Jagex reorders the interface. If no child admits to being Buy, the whole
	 * slot is ringed instead: still points at the right box, which is most of
	 * the value, and never points at the wrong thing.
	 */
	private void drawActionPrompt(Graphics2D graphics, Map<Integer, SlotView> active)
	{
		if (actPromptItemId == null)
		{
			return;
		}
		final net.runelite.api.GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}
		/* Only the slots this world lets you open. A free world has three;
		   the other five are drawn, report EMPTY, and cannot be used — and
		   the ring used to land on the first of them. */
		final int usable = Math.min(SLOT_WIDGETS.length,
			Math.min(offers.length, PocketGeTrackerPlugin.usableGeSlots(client)));
		for (int slot = 0; slot < usable; slot++)
		{
			final net.runelite.api.GrandExchangeOffer o = offers[slot];
			/* Free means free: empty in the client AND not something the
			   plugin is already tracking an offer in. */
			if (o == null || o.getState() != net.runelite.api.GrandExchangeOfferState.EMPTY
				|| active.containsKey(slot))
			{
				continue;
			}
			final Widget w = client.getWidget(SLOT_WIDGETS[slot]);
			if (w == null || w.isHidden())
			{
				continue;
			}
			final Rectangle target = actionButtonBounds(w, actPromptSell ? "sell" : "buy");
			if (target == null || target.isEmpty())
			{
				continue;
			}
			graphics.setColor(ACT_HERE_COLOR);
			graphics.setStroke(new BasicStroke(2f));
			graphics.drawRect(target.x - 1, target.y - 1, target.width + 1, target.height + 1);
			return; // the FIRST free slot only — one ring, one place to click
		}
	}

	/** The Buy or Sell control inside a slot, or the slot itself when it
	 *  cannot be identified. See {@link #drawActionPrompt}. */
	private static Rectangle actionButtonBounds(Widget slot, String action)
	{
		final Widget[][] families = {
			slot.getDynamicChildren(), slot.getStaticChildren(), slot.getNestedChildren()};
		for (Widget[] family : families)
		{
			if (family == null)
			{
				continue;
			}
			for (Widget child : family)
			{
				if (child == null || child.isHidden() || child.getActions() == null)
				{
					continue;
				}
				for (String a : child.getActions())
				{
					if (a != null && a.toLowerCase().contains(action))
					{
						return child.getBounds();
					}
				}
			}
		}
		return slot.getBounds();
	}

	/**
	 * Three lines at most: what it is, what to do, what it makes.
	 *
	 * This ran to six — item, "Buying N of M", projected profit, profit so
	 * far, a diagnosis and an instruction — every line true and the whole
	 * thing no easier to read than the border it was explaining. The report
	 * was simply "such a long hover tooltip"; what was wanted was the border's
	 * colour plus a couple of words.
	 *
	 * So the progress line is gone, for the reason the class comment already
	 * gives about the progress bar: the game prints the quantity in the box,
	 * and repeating it is decor competing with the numbers it duplicates.
	 * "So far" is gone too — it is the same figure as the projection until an
	 * offer is part-filled, and when it differs it is a detail, not a verdict.
	 *
	 * What is left is a VERB. "Off the market" named a problem and left you
	 * to find the number; "Lower your ask to 788 gp" is the whole thing.
	 */
	/**
	 * The hover's money line: "Profit if it flips" on a buy; on a sell that
	 * has started selling, what it has made so far and what is still to come
	 * — "295k of x amount total 85k left". One line, so this hover keeps to
	 * its three. Null when there is nothing honest to say. The sidebar square
	 * says the same: GeSlotsPanel.moneyLine.
	 */
	static String moneyLine(boolean buy, Long projected, Long booked, long bookedUnits, long sold)
	{
		if (!buy && booked != null)
		{
			/* Booked on every unit sold, or only on some: sold with the
			   plugin not watching, or with no buy on record. Then the figure
			   says what it covers, and there is no "in all" to give. */
			final boolean whole = bookedUnits >= sold;
			final StringBuilder sb = new StringBuilder()
				.append(TipStyle.muted("Made ")).append(TipStyle.money(booked))
				.append(TipStyle.muted(whole ? " so far" : " on " + String.format("%,d", bookedUnits)
					+ " of " + String.format("%,d", sold) + " sold"));
			if (projected != null)
			{
				sb.append(TipStyle.muted(", ")).append(TipStyle.money(projected))
					.append(TipStyle.muted(" to come" + (whole ? " (" + signedShort(booked + projected) + " in all)" : "")));
			}
			return sb.toString();
		}
		if (projected == null)
		{
			return null;
		}
		return TipStyle.muted(buy ? "Profit if it flips: " : "Profit: ") + TipStyle.money(projected);
	}

	private static String signedShort(long v)
	{
		return (v >= 0 ? "+" : "-") + QuantityFormatter.quantityToStackSize(Math.abs(v));
	}

	private static String tooltipText(SlotView v)
	{
		final StringBuilder sb = new StringBuilder();
		if (v.itemName != null && !v.itemName.isEmpty())
		{
			/* Parchment, the same colour the sidebar names items in — not
				   the near-gold e5c158 this used to be, which matched no
				   other colour in the plugin. See TipStyle. */
				sb.append(TipStyle.subject(v.itemName)).append(TipStyle.BREAK);
		}
		sb.append(stateLine(v));
		/* The money, and only when there is a real cost behind it. */
		final String money = moneyLine(v.buy, v.projectedProfit, v.bookedProfit, v.bookedUnits, v.filled);
		if (money != null)
		{
			sb.append(TipStyle.BREAK).append(money);
		}
		else if (!v.buy && v.grossValue != null && v.grossValue > 0)
		{
			/*
			 * Proceeds, because profit cannot be had.
			 *
			 * Never a zero profit here. The plugin not having watched you buy
			 * something is not the same as that thing having cost nothing, and
			 * "Profit: 5.3M" measured from a cost of zero is how a stack you
			 * have held for a year claims a win it never made. But the line
			 * this replaces — "Cost unknown, so no profit to show." — answered
			 * the question by declining it, on exactly the offers where the
			 * number you actually want is the simpler one: what lands in your
			 * pocket.
			 *
			 * Parchment, not the profit green. The sidebar spent three
			 * attempts learning that a figure in the profit colour reads as
			 * profit however it is worded, and the bank tooltip carries the
			 * same rule for the same figure.
			 *
			 * It reads as "at that price" because the line above it is the one
			 * naming the price — see grossValue, which is computed at whatever
			 * price this tooltip is recommending.
			 */
			sb.append(TipStyle.BREAK)
				.append(TipStyle.muted("Sells for "))
				.append(TipStyle.figure(QuantityFormatter.quantityToStackSize(v.grossValue) + " gp"))
				.append(TipStyle.muted(" after tax"));
		}
		else if (!v.buy)
		{
			sb.append(TipStyle.BREAK).append(TipStyle.muted("Cost unknown, so no profit to show."));
		}
		return sb.toString();
	}

	/**
	 * The one line that says what state this slot is in, in the fewest words
	 * that are still an instruction.
	 *
	 * It says "re-list", never "modify": the Exchange has no way to edit a
	 * live offer's price, so the real sequence is abort, collect, place
	 * again, and naming a button the game does not have is worse than saying
	 * nothing. The direction is spelled out rather than left to the colour —
	 * a buy that is mispriced is ALWAYS too low and a sell ALWAYS too high,
	 * so "raise" and "lower" are never ambiguous.
	 */
	private static String stateLine(SlotView v)
	{
		if (v.ready)
		{
			return TipStyle.state(COLLECT_COLOR, "Done \u2014 ready to collect.");
		}
		if (v.adviceSkipped)
		{
			return TipStyle.muted("You are pricing this one.");
		}
		if (!v.needsAdjust)
		{
			/* Green has always meant "not red", which is true and says
			   nothing. Reported as: I ignored the suggested price, typed my
			   own, and the box stayed green — was it listening? It was; the
			   difference was inside the drift threshold. So the green state
			   says so out loud rather than leaving it to be inferred. */
			/* OK_COLOR, the colour of the border this sentence is
				   explaining — not a hex literal that happened to match it. */
			return TipStyle.state(OK_COLOR, "Priced fine \u2014 leave it.");
		}
		if (v.losing && v.targetPrice > 0)
		{
			/* Fills, but at a loss: the fix is a LOWER bid, and the most that
			   can be bid for +0 is worth saying when the suggestion is lower
			   still. */
			final StringBuilder sb = new StringBuilder();
			sb.append(TipStyle.state(GeSlotsPanel.REPRICE_COLOR, "Loses at this bid \u2014 lower it to "))
				.append(TipStyle.figure(String.format("%,d", v.targetPrice) + " gp"));
			if (v.breakEven > v.targetPrice)
			{
				sb.append(" ").append(TipStyle.muted("(" + String.format("%,d", v.breakEven) + " at most for +0)"));
			}
			return sb.toString();
		}
		if (v.noMargin)
		{
			return TipStyle.state(GeSlotsPanel.REPRICE_COLOR, "No margin left \u2014 take a new flip.");
		}
		if (v.targetPrice > 0)
		{
			/* Exact, not abbreviated like the profit line: this is a number
			   you are about to type into the game. */
			final StringBuilder sb = new StringBuilder();
			sb.append(TipStyle.state(GeSlotsPanel.REPRICE_COLOR, GeSlotsPanel.adjustVerb(v.buy)))
				.append(TipStyle.figure(String.format("%,d", v.targetPrice) + " gp"));
			if (v.buy)
			{
				sb.append(TipStyle.state(GeSlotsPanel.REPRICE_COLOR, GeSlotsPanel.adjustTail(true)));
			}
			if (v.offerPrice > 0)
			{
				sb.append(" ").append(TipStyle.muted(
					"(yours: " + String.format("%,d", v.offerPrice) + ")"));
			}
			return sb.toString();
		}
		return TipStyle.state(GeSlotsPanel.REPRICE_COLOR, "Priced off the market \u2014 re-list.");
	}

}

package com.pocketge.tracker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Writes the recommended price directly onto the Grand Exchange "Set up
 * offer" screen, the way Flipping Copilot and Flipping Utilities do.
 *
 * The price already existed in the sidebar, but reading a number over
 * there and typing it in over here is exactly the moment a flip goes
 * wrong — you look away, come back, and the prompt has already been
 * confirmed. Putting the number on the screen you're actually looking at
 * removes that round trip. The wiki's own instant price is shown next to
 * ours so it's obvious what the recommendation is departing from, and by
 * how much.
 *
 * Draws only while that screen is open with an item chosen; every other
 * GE screen is left alone.
 */
@Singleton
public class GeOfferPriceOverlay extends Overlay
{
	/* Explicit LoggerFactory rather than lombok's @Slf4j, matching
	   PocketGeTrackerPlugin. @Slf4j does compile here, but only incidentally:
	   this project declares no lombok anywhere, and the annotation resolves
	   solely because net.runelite:client drags lombok onto the compile
	   classpath, where javac auto-discovers it as an annotation processor.
	   Not a guarantee worth leaning on in a build=standard hub plugin — the
	   hub swaps build.gradle for its own template, so the classpath it
	   compiles against is not the one this repo describes. */
	private static final Logger log = LoggerFactory.getLogger(GeOfferPriceOverlay.class);
	private static final Color GOLD = new Color(0xE5, 0xC1, 0x58);
	/**
	 * The ring that says "click this next", in the plugin's one colour for
	 * that — LEAD_RIM, the same white the card puts round the price box you
	 * are about to type into, the bank puts round the stack it is suggesting,
	 * and the slot grid puts round the button to press.
	 *
	 * It was gold, which is a HUE, and a hue in this plugin means buy or sell.
	 * A gold ring on the Confirm button of a SELL offer says the wrong word
	 * quietly, and on a buy it says the right one for the wrong reason. White
	 * carries no direction, so it is free to mean only "here".
	 *
	 * It is also simply easier to see. Sampled off a real capture, the
	 * Exchange's chrome is about #494033, against which this reads 9.1:1 and
	 * the gold it replaces 5.9:1.
	 *
	 * Always an OUTLINE, never a fill. The gold chip this plugin draws beside
	 * the ring is its own button — a surface you press — and the two appear
	 * together; painting both white would leave neither pointing at anything.
	 */
	private static final Color ACT_HERE = new Color(0xF2, 0xF2, 0xF2);
	private static final Color TEXT_MAIN = new Color(0xD9, 0xD3, 0xC7);
	private static final Color PANEL_BG = new Color(0x1B, 0x18, 0x15, 0xE8);
	/** The fill button, unlit and lit, with dark text on it. */
	private static final Color GOLD_HOVER = new Color(0xFF, 0xDA, 0x7A);
	private static final Color BUTTON_RIM = new Color(0x6B, 0x55, 0x1E);
	private static final Color BUTTON_TEXT = new Color(0x1B, 0x18, 0x15);
	/* Was 0x4A3C18, which is 3.1:1 on the gold fill — under AA for small
	   text, and this is the smallest text the plugin draws anywhere. At
	   0x2A2208 it is 6.4:1 and still reads as the quieter of the two lines
	   because it is smaller and not the price. */
	private static final Color BUTTON_SUBTEXT = new Color(0x2A, 0x22, 0x08);
	private static final int PAD = 8;
	private static final int LINE_GAP = 3;

	private final Client client;
	private final net.runelite.client.game.ItemManager itemManager;

	/** The fill key as the chips name it (the "Fill key" setting, E unless
	 *  changed), or null when it is not set: then nothing is armed, and the
	 *  chips say to click instead. Set by the plugin. */
	private volatile String fillKeyName = "E";

	/** The GE item search's chatbox mode (meslayer_mode14). */
	static final int MESLAYER_MODE_ITEM_SEARCH = 14;

	/** Whether the price chart is up over the open price or quantity box,
	 *  covering the chip: then the chip is neither drawn, clickable nor
	 *  armed, though where it would sit is still published. Set by the
	 *  plugin. */
	private volatile java.util.function.BooleanSupplier chartOver = () -> false;
	/** Where the price or quantity chip sits this frame, or null — the
	 *  chart's Chart / Price toggle goes just above it. */
	private volatile Rectangle chipBox;
	/** The item the search's own result row has been made to offer (the
	 *  plugin's fillSearchRow), while nothing has been typed; 0 for none.
	 *  Only then does the fill key pick it. */
	private volatile int searchPickItem;

	/** Everything the overlay needs, published as one immutable snapshot so
	 *  a render can never catch half of an update from the client thread. */
	private static class Context
	{
		final String name;
		final boolean buy;
		final long target;
		final long wiki;
		final long margin;
		/** How many to trade — the 4-hour limit for a buy, the stack you hold
		 *  for a sell. 0 when unknown, which hides the quantity step. */
		final long quantity;

		Context(String name, boolean buy, long target, long wiki, long margin, long quantity)
		{
			this.name = name;
			this.buy = buy;
			this.target = target;
			this.wiki = wiki;
			this.margin = margin;
			this.quantity = quantity;
		}
	}

	private volatile Context context;
	/** Where the clickable price panel ended up last frame, so the mouse
	 *  handler can hit-test it. Written on the client thread during render,
	 *  read on the same thread from the mouse callback. */
	private volatile Rectangle panelHitbox;
	/** One debug line per session, not one per frame. */
	private boolean loggedPriceControlMiss;
	/** The item to suggest while the GE "What would you like to buy?"
	 *  prompt is open. */
	private volatile int searchItemId;
	private volatile String searchItemName;
	/** Where the quantity chip landed last frame, for the same hit-testing. */
	private volatile Rectangle quantityHitbox;

	/**
	 * What pressing the fill key would put in the box open right now, or
	 * null when no price or quantity box of ours is open.
	 *
	 * Written by render on the client thread, every frame, from the same
	 * test that decides whether the chip is drawn — so the key does exactly
	 * what the chip on screen says, and nothing when there is no chip. Read
	 * by the plugin's key listener on the AWT thread; one immutable snapshot
	 * so the value and its kind cannot be read from two different frames.
	 */
	static final class Armed
	{
		final boolean quantity;
		final long value;
		/** The item the search would pick; 0 for a price or quantity box. */
		final int itemId;

		Armed(boolean quantity, long value)
		{
			this(quantity, value, 0);
		}

		private Armed(boolean quantity, long value, int itemId)
		{
			this.quantity = quantity;
			this.value = value;
			this.itemId = itemId;
		}

		/** The item search, with the suggested item to pick. */
		static Armed item(int itemId)
		{
			return new Armed(false, 0, itemId);
		}
	}

	private volatile Armed armed;

	/** See {@link Armed}. Null when the fill key should do nothing. */
	Armed armed()
	{
		return armed;
	}

	@Inject
	private GeOfferPriceOverlay(Client client, net.runelite.client.game.ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Called from the plugin whenever the offer screen's item/price changes.
	 *  Null clears it. {@code wiki} is the raw live quote we'd otherwise have
	 *  used; passing it equal to {@code target} just hides that line. */
	public void setContext(String name, boolean buy, long target, long wiki, long margin, long quantity)
	{
		this.context = name == null || target <= 0 ? null
			: new Context(name, buy, target, wiki, margin, quantity);
	}

	public void clear()
	{
		this.context = null;
		this.panelHitbox = null;
		this.quantityHitbox = null;
		this.armed = null;
	}

	void setChartOver(java.util.function.BooleanSupplier over)
	{
		this.chartOver = over != null ? over : () -> false;
	}

	/** See {@link #chipBox}. */
	Rectangle chipBox()
	{
		return chipBox;
	}

	/** See {@link #searchPickItem}. */
	void setSearchPickItem(int itemId)
	{
		this.searchPickItem = itemId;
	}

	int searchItemId()
	{
		return searchItemId;
	}

	String searchItemName()
	{
		return searchItemName;
	}

	/** See {@link #fillKeyName}: the key's name, or null for none. */
	void setFillKeyName(String name)
	{
		this.fillKeyName = name;
	}

	/** "press E to fill price", or how to use the chip without a key. */
	private String fillHint(String what)
	{
		final String key = fillKeyName;
		return key != null ? "press " + key + " to fill " + what : "click to copy " + what;
	}

	/**
	 * Whether the item search's input line is still empty — the only time
	 * the fill key may pick the suggested item. Once a letter is typed the
	 * key is a letter of the search again.
	 */
	static boolean searchUntyped(net.runelite.api.Client client)
	{
		final String typed = client.getVarcStrValue(net.runelite.api.gameval.VarClientID.MESLAYERINPUT);
		return typed == null || typed.isEmpty();
	}

	/**
	 * Whether the search's first result row picks {@code itemId} — so the
	 * fill key, handed on as Enter, picks what the chip names. A row the
	 * game has rebuilt, or another plugin rewritten, disarms the chip.
	 */
	static boolean searchRowHolds(Client client, int itemId)
	{
		final Widget res = client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS);
		final Widget row = res != null ? res.getChild(0) : null;
		final Object[] k = row != null ? row.getOnKeyListener() : null;
		return k != null && k.length >= 2 && Integer.valueOf(754).equals(k[0]) && Integer.valueOf(itemId).equals(k[1]);
	}

	/** The item the plugin currently recommends buying, offered as a chip on
	 *  the item-search prompt. 0 clears it. */
	public void setSearchSuggestion(int itemId, String name)
	{
		this.searchItemId = itemId;
		this.searchItemName = name;
	}

	/** True while the chatbox is asking which ITEM to trade, as opposed to
	 *  the price/quantity prompts. */
	private boolean itemSearchOpen()
	{
		return isItemSearchPrompt(client);
	}

	/**
	 * Whether the chatbox is asking WHICH item to trade.
	 *
	 * Reads MES_TEXT and MES_TEXT2 together, which pricePromptOpen has
	 * always done and this had not. The item search lays its chatbox out
	 * differently from the price prompt — a title line, then the hint — so
	 * reading only the first widget meant the question could be on screen
	 * with this returning false, and then neither the chip nor the click
	 * that fills from it did anything.
	 *
	 * Static and public so the plugin's own fill path applies the identical
	 * test. They were two copies of the same check and only one of them was
	 * ever fixed at a time.
	 */
	static boolean isItemSearchPrompt(net.runelite.api.Client client)
	{
		final Widget mes = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		final Widget mes2 = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
		/* Visible, not merely once-set — see pricePromptOpen. */
		final String t = ((mes != null && !mes.isHidden() && mes.getText() != null ? mes.getText() : "")
			+ " " + (mes2 != null && !mes2.isHidden() && mes2.getText() != null ? mes2.getText() : ""))
			.toLowerCase();
		return t.contains("what would you like to");
	}

	/** True when {@code point} is over the price chip — the plugin's mouse
	 *  handler turns a click there into a clipboard copy. Nothing is
	 *  clickable when we aren't drawing. */
	public boolean isOverPrice(java.awt.Point point)
	{
		final Rectangle panel = panelHitbox;
		return point != null && panel != null && panel.contains(point);
	}

	/** The price the chip shows, or 0 when there is none. */
	public long priceToFill()
	{
		final Context ctx = context;
		return ctx != null ? ctx.target : 0;
	}

	/** True when {@code point} is over the QUANTITY chip. Same contract as
	 *  isOverPrice: only true while that chip is actually drawn. */
	public boolean isOverQuantity(java.awt.Point point)
	{
		final Rectangle panel = quantityHitbox;
		return point != null && panel != null && panel.contains(point);
	}

	/** The quantity the chip shows, or 0 when there is none. */
	public long quantityToFill()
	{
		final Context ctx = context;
		return ctx != null ? ctx.quantity : 0;
	}

	/** True while the chatbox is genuinely asking for a price — the only
	 *  state in which fillGePrice does anything. */
	/**
	 * Whether the game is asking for a price RIGHT NOW.
	 *
	 * The isHidden checks are the whole method. A chatbox prompt widget keeps
	 * its last text after it closes, so reading the text alone answered "has
	 * the game ever asked for a price this session" — which stays true forever
	 * once it has. The fill panel therefore never went away after filling, and
	 * because the panel returns before the ring logic, the ring never advanced
	 * to the quantity control either: set the price, and the plugin sat there
	 * offering to set the price.
	 *
	 * quantityPromptOpen had the checks; this one and itemSearchOpen did not.
	 */
	private boolean pricePromptOpen()
	{
		return openNumberBox(client) == NumberBox.PRICE;
	}

	/** Which of the Exchange's own number boxes the chatbox is showing. */
	enum NumberBox
	{
		NONE, PRICE, QUANTITY
	}

	/**
	 * Which Exchange number box is open, judged from the game's QUESTION
	 * only — never from what the player has typed.
	 *
	 * This used to look for "price" or "how many" anywhere in the two
	 * chatbox lines, and one of those lines is the input: whatever the
	 * player is typing, followed by "*". A private message saying "what
	 * price?" with the offer screen open armed the fill key, and the next E
	 * replaced the message with a number. So the input line (the one ending
	 * in "*") is skipped, and the question has to START with the Exchange's
	 * own wording: a private-message prompt starts "Enter message to send
	 * to", whatever the friend is called.
	 *
	 * Fails closed: wording that does not match arms nothing, so the worst
	 * case is an E that does nothing, never one that lands somewhere else.
	 * Static so the plugin re-checks with the identical test before writing.
	 */
	static NumberBox openNumberBox(net.runelite.api.Client client)
	{
		for (int id : new int[]{InterfaceID.Chatbox.MES_TEXT, InterfaceID.Chatbox.MES_TEXT2})
		{
			final Widget w = client.getWidget(id);
			if (w == null || w.isHidden() || w.getText() == null)
			{
				continue;
			}
			final String t = w.getText().replaceAll("<[^>]*>", "").trim().toLowerCase(java.util.Locale.ROOT);
			if (t.endsWith("*"))
			{
				continue; // the input line: the player's own typing, never the question
			}
			if (t.startsWith("set a price"))
			{
				return NumberBox.PRICE;
			}
			if (t.startsWith("how many"))
			{
				return NumberBox.QUANTITY;
			}
		}
		return NumberBox.NONE;
	}

	/**
	 * Finds the control that opens the price box, by asking the interface
	 * rather than hardcoding where it lives.
	 *
	 * The obvious implementation is a widget id, and there isn't one:
	 * InterfaceID.GeOffers names SETUP and its labels but not the six
	 * buttons on the price row, which are unnamed children addressed by
	 * index. An index guessed from a screenshot would draw a gold box over
	 * whichever control happened to sit there, on every client layout, and
	 * be wrong silently.
	 *
	 * So this searches SETUP's descendants for a widget whose own right-click
	 * action mentions a price without being one of the percentage nudges.
	 * That is the button's self-description, so it survives the row being
	 * reordered or re-indexed, and — the point — it FAILS CLOSED: no match
	 * means no highlight, never a highlight of the wrong thing.
	 *
	 * When it finds nothing it logs the actions it did see, once per offer
	 * screen, so the strings needed to fix the match can be read out of a
	 * log rather than guessed at again.
	 */
	/** The control that opens the free-text PRICE box. */
	/**
	 * The quantity half of the same affordance: once the price is in, the
	 * game asks how many, and this offers the number the card already
	 * decided — the 4-hour limit for a buy, the stack you hold for a sell.
	 *
	 * Same panel, same place, same click as the price step, because it is the
	 * same job one field later. Drawn only while the quantity prompt is
	 * actually open, for the reason the price panel is: a box that appears
	 * early and says "go and click that other thing" is worse than the ring
	 * on the button itself.
	 */
	/**
	 * The one clickable thing the overlay draws, painted like a control.
	 *
	 * Both chips were a dark box with a gold outline and three lines of text —
	 * the shape this plugin uses for things you READ. The words said "click
	 * here" and nothing else did: no hover, no button, and it sat above the
	 * parchment rather than in it. Reported, twice, as not looking clickable.
	 *
	 * A filled gold button with dark text instead — the same treatment the
	 * sidebar gives an active segment button — that lightens under the cursor.
	 * Returns its own bounds so the caller can register the hitbox.
	 */
	private Rectangle drawFillButton(Graphics2D g, String bigLine, String hint)
	{
		return fillButton(g, bigLine, hint, true);
	}

	/** Lay out the chip and, if {@code draw}, paint it; its box either way. */
	private Rectangle fillButton(Graphics2D g, String bigLine, String hint, boolean draw)
	{
		/* Both up a size. These are drawn over the game canvas at whatever
		   scaling the client is running, next to RuneScape's own chunky
		   parchment type — 11pt for the line that tells you the button is
		   clickable came out as grey mush, and the price above it was only
		   just holding together. The button grows with them; there is room,
		   it sits in the clear right end of the chat strip. */
		final Font bigFont = g.getFont().deriveFont(Font.BOLD, 21f);
		final Font hintFont = g.getFont().deriveFont(Font.BOLD, 13f);
		final FontMetrics bm = g.getFontMetrics(bigFont);
		final FontMetrics hm = g.getFontMetrics(hintFont);

		final int w = Math.max(bm.stringWidth(bigLine), hm.stringWidth(hint)) + PAD * 3;
		final int h = PAD + bm.getHeight() + LINE_GAP + hm.getHeight() + PAD;

		/* Inside the parchment, hard right.
		   Above it — where these used to sit — is outside the box the player
		   is reading and on top of whatever another plugin writes on that
		   strip. The game's own prompt and button are centred, so the right of
		   the chat area is the one reliably clear part of it, and it puts the
		   thing to click a short move from the button you would otherwise
		   have used. */
		final Widget chat = client.getWidget(InterfaceID.Chatbox.CHATAREA);
		final Rectangle cb = chat != null && !chat.isHidden() ? chat.getBounds() : null;
		if (cb == null || cb.isEmpty())
		{
			return null; // nowhere sensible to put it
		}
		int x = Math.max(cb.x + 2, cb.x + cb.width - w - PAD);
		int y = cb.y + (cb.height - h) / 2;
		x = Math.max(0, Math.min(x, client.getCanvasWidth() - w));
		y = Math.max(0, Math.min(y, client.getCanvasHeight() - h));
		if (!draw)
		{
			return new Rectangle(x, y, w, h);
		}

		final net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		final boolean hover = mouse != null
			&& mouse.getX() >= x && mouse.getX() < x + w
			&& mouse.getY() >= y && mouse.getY() < y + h;

		g.setColor(hover ? GOLD_HOVER : GOLD);
		g.fillRect(x, y, w, h);
		/* A darker rim, not a brighter one: on a filled button the edge reads
		   as a shadow, and a second bright outline only blurs where the button
		   stops. It thickens on hover so the lift is felt as well as seen. */
		g.setStroke(new BasicStroke(hover ? 2f : 1f));
		g.setColor(BUTTON_RIM);
		g.drawRect(x, y, w - 1, h - 1);

		int ty = y + PAD + bm.getAscent();
		g.setFont(bigFont);
		g.setColor(BUTTON_TEXT);
		g.drawString(bigLine, x + (w - bm.stringWidth(bigLine)) / 2, ty);
		ty += LINE_GAP + hm.getAscent();
		g.setFont(hintFont);
		g.setColor(BUTTON_SUBTEXT);
		g.drawString(hint, x + (w - hm.stringWidth(hint)) / 2, ty);
		return new Rectangle(x, y, w, h);
	}

	private void drawQuantityChip(Graphics2D g, Context ctx)
	{
		/* Under the chart, when it has been flicked up over the box: not
		   drawn, not clickable, not armed — only where it would be. */
		final boolean covered = chartOver.getAsBoolean();
		final Rectangle r = fillButton(g, String.format("%,d", ctx.quantity), fillHint("quantity"), !covered);
		chipBox = r;
		if (covered)
		{
			return;
		}
		quantityHitbox = r;
		if (r != null && fillKeyName != null)
		{
			armed = new Armed(true, ctx.quantity);
		}
	}

	/** True while the chatbox is asking HOW MANY, as opposed to the price. */
	private boolean quantityPromptOpen()
	{
		return openNumberBox(client) == NumberBox.QUANTITY;
	}


	private Widget findPriceEntryControl(Widget setup)
	{
		return findEntryControl(setup, "price");
	}

	/** ...and the QUANTITY one. Same walk, different word: the game labels
	 *  these buttons with their own action text, so one finder serves both. */
	private Widget findQuantityEntryControl(Widget setup)
	{
		return findEntryControl(setup, "quantity");
	}

	/** The Confirm button — the third and last thing to point at. Found the
	 *  same self-describing way as the other two, so it fails closed rather
	 *  than ringing whatever sits at a guessed index. */
	private Widget findConfirmControl(Widget setup)
	{
		return findEntryControl(setup, "confirm");
	}

	/**
	 * Whether any "N coins" readout on the setup screen shows exactly
	 * {@code value}.
	 *
	 * Deliberately "any", not "the first one". The screen carries at least two
	 * — the price per item and the running total — and which the widget walk
	 * reaches first is an accident of the interface tree. Asking whether the
	 * number we want is on the screen at all is the question that actually
	 * matters and does not depend on that order.
	 */
	private boolean setupShowsCoins(Widget setup, long value)
	{
		if (value <= 0)
		{
			return false;
		}
		final java.util.List<Widget> queue = new java.util.ArrayList<>();
		queue.add(setup);
		for (int i = 0; i < queue.size() && i < 512; i++)
		{
			final Widget w = queue.get(i);
			if (w == null || w.isHidden())
			{
				continue;
			}
			for (Widget[] kids : new Widget[][]{ w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren() })
			{
				if (kids != null)
				{
					for (Widget k : kids)
					{
						if (k != null)
						{
							queue.add(k);
						}
					}
				}
			}
			final String t = w.getText();
			if (t == null || !t.toLowerCase().contains("coins"))
			{
				continue;
			}
			if (textShowsValue(t, value))
			{
				return true;
			}
		}
		return false;
	}

	/** Every run of digits in a readout, with the thousands separators taken
	 *  out first. */
	private static final java.util.regex.Pattern NUMBER =
		java.util.regex.Pattern.compile("\\d+");

	/**
	 * Whether {@code text} states {@code value} as one of its numbers.
	 *
	 * Each number separately, which is the whole point. This used to strip
	 * every non-digit from the line and parse what was left as a single
	 * number, and that works right up until a readout carries more than one:
	 *
	 * <pre>
	 *   a buy    "8,658,000 coins"                    -&gt; 8658000        ok
	 *   a sell   "8,502,000 coins (8,658,000 - 2%)"   -&gt; 850200086580002
	 * </pre>
	 *
	 * The Exchange prints a sell's total NET of the 2% tax and puts the gross
	 * and the rate in brackets after it, so the old rule silently failed on
	 * every sell — which is why the ring reached Confirm on a buy and stuck on
	 * the quantity control on a sell however much of the offer was already
	 * filled in. Reported as "it should be highlighting the confirm now in
	 * this example. i already selected price and quantity".
	 *
	 * Package-private so it can be tested on the strings the game actually
	 * prints, without a client.
	 */
	static boolean textShowsValue(String text, long value)
	{
		if (text == null || value <= 0)
		{
			return false;
		}
		final java.util.regex.Matcher m = NUMBER.matcher(text.replace(",", ""));
		while (m.find())
		{
			try
			{
				if (Long.parseLong(m.group()) == value)
				{
					return true;
				}
			}
			catch (NumberFormatException ignore)
			{
				// a run of digits too big to be one of ours; keep looking
			}
		}
		return false;
	}

	private Widget findEntryControl(Widget setup, String keyword)
	{
		final java.util.List<Widget> queue = new java.util.ArrayList<>();
		queue.add(setup);
		Widget best = null;
		final java.util.List<String> seen = new java.util.ArrayList<>();
		for (int i = 0; i < queue.size() && i < 512; i++)
		{
			final Widget w = queue.get(i);
			if (w == null || w.isHidden())
			{
				continue;
			}
			for (Widget[] kids : new Widget[][]{ w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren() })
			{
				if (kids != null)
				{
					for (Widget k : kids)
					{
						if (k != null)
						{
							queue.add(k);
						}
					}
				}
			}
			final String[] actions = w.getActions();
			if (actions == null)
			{
				continue;
			}
			for (String a : actions)
			{
				if (a == null || a.trim().isEmpty())
				{
					continue;
				}
				final String lower = a.toLowerCase();
				seen.add(a);
				if (!lower.contains(keyword) || lower.contains("%"))
				{
					continue;
				}
				/* Prefer the one that opens a free-text box over any other
				   price-mentioning control, but take a plain "price" match
				   rather than nothing. */
				if (lower.contains("enter") || lower.contains("set") || lower.contains("custom"))
				{
					return w;
				}
				if (best == null)
				{
					best = w;
				}
			}
		}
		if (best == null && !loggedPriceControlMiss)
		{
			loggedPriceControlMiss = true;
			log.debug("PocketGE: no {}-entry control matched on the GE setup screen. Actions seen: {}", keyword, seen);
		}
		return best;
	}

	/**
	 * A note on the "What would you like to buy?" prompt: the recommended
	 * item's own sprite and name.
	 *
	 * It used to type the name itself when clicked. RuneLite does not allow
	 * a plugin to put text into the chatbox input — "the only way text can
	 * get into the chatbox is if the user is pressing keys themselves" — so
	 * nothing is typed. The plugin puts the item in the search's own
	 * "previous search" row instead (fillSearchRow), which Enter or a click
	 * picks, and until a letter is typed the fill key reaches the game as
	 * Enter; the chip says so, and is armed for it, only then.
	 *
	 * Drawn ABOVE the results area rather than over it, so it never covers a
	 * row you were about to click, and only while the prompt is genuinely
	 * the item search — the price and quantity prompts share this chatbox.
	 */
	private void drawSearchChip(Graphics2D g)
	{
		final int id = searchItemId;
		final String name = searchItemName;
		if (id <= 0 || name == null || name.isEmpty() || !itemSearchOpen())
		{
			return;
		}
		final Widget results = client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS);
		final Widget anchorW = results != null && !results.isHidden()
			? results : client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		if (anchorW == null || anchorW.isHidden())
		{
			return;
		}
		final Rectangle ab = anchorW.getBounds();
		if (ab == null || ab.isEmpty())
		{
			return;
		}

		final String label = "Suggested: " + name;
		final Font f = g.getFont().deriveFont(Font.BOLD, 16f);
		final FontMetrics fm = g.getFontMetrics(f);
		final String key = fillKeyName;
		/* Pickable only once the plugin has put this item in the search's
		   own result row, and only until anything is typed: then the key
		   reaches the game as Enter and the game picks the row itself. */
		final boolean pickable = key != null && searchPickItem == id
			&& client.getVarcIntValue(net.runelite.api.gameval.VarClientID.MESLAYERMODE) == MESLAYER_MODE_ITEM_SEARCH
			&& searchUntyped(client) && searchRowHolds(client, id);
		final String hint = pickable ? "press " + key + " to pick" : null;
		final Font hf = g.getFont().deriveFont(Font.PLAIN, 13f);
		final FontMetrics hm = g.getFontMetrics(hf);
		final int icon = 28;
		final int w = icon + 6 + fm.stringWidth(label) + (hint != null ? 10 + hm.stringWidth(hint) : 0) + PAD * 2;
		final int h = Math.max(icon, fm.getHeight()) + PAD;
		int x = ab.x;
		int y = Math.max(0, ab.y - h - 3);
		x = Math.max(0, Math.min(x, client.getCanvasWidth() - w));

		g.setColor(PANEL_BG);
		g.fillRect(x, y, w, h);
		g.setStroke(new BasicStroke(2f));
		g.setColor(GOLD);
		g.drawRect(x + 1, y + 1, w - 2, h - 2);

		final java.awt.image.BufferedImage sprite = itemManager.getImage(id);
		if (sprite != null)
		{
			g.drawImage(sprite, x + PAD, y + (h - icon) / 2, icon, icon, null);
		}
		g.setFont(f);
		g.setColor(TEXT_MAIN);
		final int baseline = y + (h + fm.getAscent()) / 2 - 2;
		g.drawString(label, x + PAD + icon + 6, baseline);
		if (hint != null)
		{
			g.setFont(hf);
			g.setColor(GOLD);
			g.drawString(hint, x + PAD + icon + 6 + fm.stringWidth(label) + 10, baseline);
			armed = Armed.item(id);
		}
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		/* Cleared before anything can return early. These are hit-tested by
		   the plugin's mouse handler, which consumes the click it matches —
		   so a rectangle left over from a frame we no longer paint silently
		   eats real game clicks (confirming an offer, most damagingly). Only
		   a frame that genuinely draws may re-establish it. */
		panelHitbox = null;
		quantityHitbox = null;
		chipBox = null;
		armed = null; // re-armed below only by a frame that draws a chip
		/* Before the early returns below: the item-search chip is shown while
		   choosing WHAT to trade, which is a moment when there is no offer
		   context yet by definition. */
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		drawSearchChip(g);
		final Context ctx = context;
		if (ctx == null)
		{
			return null;
		}
		final Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (setup == null || setup.isHidden())
		{
			return null;
		}
		final Rectangle bounds = setup.getBounds();
		if (bounds == null || bounds.isEmpty())
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		/* The quantity prompt gets its own chip and nothing else. Checked
		   first, and returning here, so the two prompts can never both draw:
		   they are the same chatbox one step apart, and a price panel left
		   over the "how many?" box would offer the wrong number to click. */
		if (quantityPromptOpen())
		{
			if (ctx.quantity > 0)
			{
				drawQuantityChip(g, ctx);
			}
			return null;
		}

		/* One lookup, used by everything below: whether the game is currently
		   asking for a price decides where this panel goes, how much it says,
		   and whether it is the thing to click. Read once so two halves of
		   the same frame cannot disagree. */
		final boolean fillable = pricePromptOpen();

		/* Ring the control that opens the price box, while it is still shut.
		   Copilot does this in blue; ours is the same gold as the rest of the
		   plugin so it reads as us. Drawn before the panel so the panel can
		   never be obscured by it. Once the box is open this disappears and
		   the panel itself becomes the thing to click. */
		if (!fillable)
		{
			/* Price first, then quantity — the order the screen has to be
			   filled in, and the order the ring now follows.

			   It used to sit on the price control forever, including after the
			   price was already right, which left the second half of the job
			   unmarked: you set the price, and the plugin kept pointing at the
			   thing you had just done. Once the entered price matches the
			   target the ring moves to the quantity control, and clicking it
			   opens the prompt the chip above answers. */
			/*
			 * Price, then quantity, then Confirm — the three things the screen
			 * needs, ringed one at a time in the order it needs them.
			 *
			 * Both tests read the RUNNING TOTAL rather than the quantity box.
			 * The total is price x quantity, so a total matching target x
			 * quantity means both halves are in, and it cannot be confused
			 * with anything else on the screen. Reading the quantity field
			 * instead would have to tell 11,000 the quantity apart from
			 * "Buy limit: 11,000" printed a few pixels above it, and it
			 * cannot — which would ring Confirm on an offer for one item.
			 *
			 * When the quantity is 1 the total IS the price, so both become
			 * true together and the ring goes straight to Confirm. Correct:
			 * there is no quantity left to set.
			 */
			final long wholeOffer = ctx.target * (long) ctx.quantity;
			final boolean allDone = ctx.quantity > 0 && setupShowsCoins(setup, wholeOffer);
			final boolean priceDone = allDone
				|| (ctx.target > 0 && setupShowsCoins(setup, ctx.target));
			final Widget ring = !priceDone
				? findPriceEntryControl(setup)
				: !allDone
					? findQuantityEntryControl(setup)
					: findConfirmControl(setup);
			if (ring != null)
			{
				final Rectangle b = ring.getBounds();
				if (b != null && !b.isEmpty())
				{
					g.setStroke(new BasicStroke(2f));
					g.setColor(ACT_HERE);
					g.drawRect(b.x - 1, b.y - 1, b.width + 1, b.height + 1);
				}
			}
			/* And nothing else. The panel used to appear the moment the offer
			   screen opened, saying "click the price row first" — a box that
			   sits over the game telling you to go and click something else.
			   The gold ring already says that, on the button itself, without
			   covering anything. One cue for one step. */
			return null;
		}

		/* Thousands separators, never the abbreviating formatter. This is the
		   number about to be typed into the game, and "6.48M" is not a thing
		   you can type — the price behind one such was 6,480,851, and the two
		   differ by 851 gp an item. The button sizes itself from the string,
		   so a longer number simply makes a wider button.

		   The item name went with the redesign: the sidebar names it, and the
		   game has just asked "set a price for each item", so the only things
		   left to say are which number and that you may click for it. */
		final boolean covered = chartOver.getAsBoolean();
		final Rectangle r = fillButton(g, String.format("%,d", ctx.target) + " gp each", fillHint("price"), !covered);
		chipBox = r;
		if (covered)
		{
			return null; // under the chart: see drawQuantityChip
		}
		panelHitbox = r;
		if (panelHitbox != null && fillKeyName != null)
		{
			armed = new Armed(false, ctx.target);
		}
		return null;
	}
}

