/**
 * Your 8 Grand Exchange slots, laid out 4 x 2 like the clerk's own screen,
 * drawn as the item actually in each one with a fill bar underneath showing
 * how much of that offer has completed.
 *
 * It used to be 8 flat colour swatches. Colour alone told you a slot was
 * busy but not WHAT was in it or how close it was to done — which is the
 * whole reason you'd glance at the GE while doing something else. An empty
 * slot is still just an outline, so "how many slots are free" stays
 * readable at a glance too.
 */
public class GeSlotsPanel extends JPanel
{
	public enum SlotState
	{
		/** Nothing in this slot. */
		EMPTY,
		/** Buying or selling, and the advisor still considers the price
		 *  competitive. */
		ACTIVE_OK,
		/** Buying or selling, but the price has drifted off the market —
		 *  matches the sidebar's own ADJUST_BUY/ADJUST_SELL suggestions. */
		ACTIVE_ADJUST,
		/** Buying, and filling, but every unit loses money against the price
		 *  it sells back at after tax — Advisor.losingBuy. */
		ACTIVE_LOSING,
		/** Fully bought/sold (or cancelled with something to collect) —
		 *  nothing left to do but collect it. */
		READY_COLLECT
	}

	public static class SlotInfo
	{
		public SlotState state = SlotState.EMPTY;
		public String itemName;
		public int itemId;
		/** Units filled so far and the offer's total, for the progress bar.
		 *  Both 0 on an empty slot. */
		public int quantityFilled;
		public int quantityTotal;
		public boolean buy;
		/** True when you have right-clicked this slot and told the plugin you
		 *  are pricing this one yourself. The slot keeps its sprite and its
		 *  fill bar, and it is never boxed for a new price — as on the
		 *  in-game GE box. */
		public boolean adviceSkipped;
		/** What this offer is listed at, and what the plugin thinks it should
		 *  be listed at. Both 0 when there is nothing to say.
		 *
		 *  A red slot used to say only "needs a new price", which is half an
		 *  instruction: it names a problem and not the fix, and the obvious
		 *  reading of a red box is "cancel this". Somebody did, repriced at
		 *  the same number, and was rightly annoyed. The tooltip now names
		 *  the number to move to. */
		public long offerPrice;
		public long targetPrice;
		/** True when the flip no longer clears the tax at the new price —
		 *  i.e. repricing would fill you into a loser. Then the honest advice
		 *  is not "reprice", it is "take a different flip". */
		public boolean noMargin;
		/** What the whole offer makes: for a buy, if it flips at the price
		 *  the card would sell at; for a sell, against what you paid. Null
		 *  when there is nothing honest to say — a sell the plugin never saw
		 *  you buy. Same figure as the in-game box's tooltip. */
		public Long projectedProfit;
		/** A sell: what it has booked so far — see
		 *  GeOfferGridOverlay.SlotView.bookedProfit. */
		public Long bookedProfit;
		/** See GeOfferGridOverlay.SlotView.bookedUnits. */
		public long bookedUnits;
		/** What the offer is listed at — bid or ask — on any slot holding an
		 *  offer, 0 on an empty one. */
		public long listedPrice;
		/** ACTIVE_LOSING: the most that can be bid for +0. */
		public long breakEven;
		/** What is waiting in this slot's collection box: gp, and units of the
		 *  offer's item (bought, or handed back unsold). -1 when the plugin has
		 *  not seen the box, or saw something in it that is not this offer's. */
		public long collectCoins = -1;
		public int collectItems = -1;
		/** Units filled since you last emptied the box; -1 when unknown. */
		public int sinceCollect = -1;
	}

	/**
	 * "To collect: 461,616 gp — 12 sold since you last collected", or null.
	 *
	 * Asked for on the hover: "add how much money i have able to collect /
	 * how many additional units have sold if any since last collect". The
	 * fill count alone is the whole offer's history; this is the part that
	 * is sitting there for you now.
	 */
	/**
	 * The words around an adjust's price, shared with the in-game box so the
	 * two say the same thing. A buy the market has moved past has two
	 * answers, and the new price may not be worth paying: "it should be
	 * yellow and say adjust price or reconsider trade ... i may not even
	 * want to buy at that price". In the same line — these stay one short
	 * sentence (SlotWordingTest).
	 */
	static String adjustVerb(boolean buy)
	{
		return buy ? "Raise to " : "Lower your ask to ";
	}

	static String adjustTail(boolean buy)
	{
		return buy ? ", or cancel" : "";
	}

	static String collectLine(SlotInfo s)
	{
		if (s == null || (s.collectCoins <= 0 && s.collectItems <= 0))
		{
			return null;
		}
		final StringBuilder sb = new StringBuilder("To collect: ");
		boolean any = false;
		if (s.collectCoins > 0)
		{
			sb.append(String.format("%,d", s.collectCoins)).append(" gp");
			any = true;
		}
		if (s.collectItems > 0)
		{
			sb.append(any ? " + " : "").append(String.format("%,d", s.collectItems))
				.append(s.buy ? " bought" : " unsold");
		}
		if (s.sinceCollect > 0)
		{
			sb.append(" \u2014 ").append(String.format("%,d", s.sinceCollect))
				.append(s.buy ? " bought" : " sold").append(" since you last collected");
		}
		return sb.toString();
	}

	/** What this strip can ask the plugin to do. */
	public interface Actions
	{
		/** Turn "leave this offer's price alone" on or off for one slot. */
		void setSlotAdviceSkipped(int slot, boolean skipped);
		/** Show the item in this slot in the inspection card above — the same
		 *  thing a watchlist row or a finder row does when clicked. The eight
		 *  squares name the items you have the most riding on right now, and
		 *  until this they were the one place in the panel where clicking an
		 *  item did nothing at all. */
		void inspectItem(int itemId, String name);
	}

	/*
	 * Package-private, and the canonical copies: the in-game offer grid and
	 * the settings legend paint or explain these same colours, and a legend
	 * that drifts from what is on screen is worse than no legend.
	 *
	 * THREE meanings, in the game's own language. The Exchange's progress
	 * bar is orange while an offer works, green when it completes and red
	 * when it is aborted — and these squares used green for "priced fine"
	 * and red for "reprice", so a working offer read as finished and one
	 * wanting a new price read as cancelled: "green makes me think it means
	 * is done / red makes me think its done/canceled. + all the colors on
	 * side bar is too additional". That became grey while it works, yellow
	 * when it needs you, green when it is done.
	 *
	 * And then the boxes went: "i dont like the white boxes honestly ...
	 * boxes only appear for change? the yellow box conflicts meaning with
	 * the theme". A grey box round every busy slot was eight borders saying
	 * nothing, and the yellow one sat round SELLS in a theme whose yellow
	 * means buy. So a working slot is now just its picture and its bar, the
	 * bar filling in your buy or sell colour; a slot that wants a new price
	 * is boxed in white, the plugin's "act here"; a done one is boxed in the
	 * game's green, which no theme uses. The in-game boxes already worked
	 * this way.
	 */
	/** "Priced fine" on a hover: quiet on purpose — most slots, most of the
	 *  time, are this. Never a box. */
	static final Color OK_COLOR = new Color(0x9C, 0x95, 0x8A);
	/** Done, waiting at the Exchange — the game's own green. */
	static final Color COLLECT_COLOR = new Color(0x1F, 0xB8, 0x5C);
	/** Needs a new price: white, the plugin's "act here" — the ring on the
	 *  price box, the free slot's Buy or Sell button, the bank stack the card
	 *  names. It was the offer's buy or sell colour, which in the default
	 *  theme put the old yellow back round every buy: "this yellow i think
	 *  should be an ew color ... or white to match our theme actualy for
	 *  directing the user". */
	static final Color REPRICE_COLOR = BankHighlightOverlay.RECOMMENDED_COLOR;
	/**
	 * How the two boxes are drawn round a square: green thicker, white a
	 * touch under full strength. "calm down the white just at tad, or make
	 * the green thicker idk. green should be more niciable than white
	 * maybe?" It should: done is coins waiting at the Exchange, and a new
	 * price is a nudge. At one weight each, the white out-shouted the green
	 * on the dark tile and on the Exchange's brown alike. The colours stay
	 * the ones the legend and the hovers use; only the box is weighted.
	 */
	static final int COLLECT_BOX_PX = 2;
	static final Color REPRICE_BOX = new Color(REPRICE_COLOR.getRed(), REPRICE_COLOR.getGreen(),
		REPRICE_COLOR.getBlue(), 200);

	/**
	 * A box {@code px} deep just inside {@code x, y, w, h}, filled as one
	 * shape. Two one-pixel rings, one inside the other, are snapped to the
	 * device grid separately, so under a 125% or 150% UI scale they parted
	 * and showed the tile between them as a dark line through the green.
	 */
	static void frame(Graphics2D g, int x, int y, int w, int h, int px)
	{
		final java.awt.geom.Area a = new java.awt.geom.Area(new java.awt.Rectangle(x, y, w, h));
		a.subtract(new java.awt.geom.Area(new java.awt.Rectangle(x + px, y + px, w - 2 * px, h - 2 * px)));
		g.fill(a);
	}
	/** A slot you are pricing yourself. The plugin has nothing to say about
	 *  it, so no box — the hover still says whose it is. */
	static final Color MUTED_COLOR = OK_COLOR;
	/* The theme's buy and sell colours, pushed by the plugin with the rest
	   of the theme; High contrast, the default, until then. */
	private static volatile Color buyColour = PocketGeTrackerConfig.ColourTheme.CONTRAST.buy();
	private static volatile Color sellColour = PocketGeTrackerConfig.ColourTheme.CONTRAST.sell();
	/* Package-private, like OK_COLOR and the rest: the settings legend
	   draws a swatch for this border and must read it off the class that
	   paints it. It was the one legend row carrying a retyped colour, and
	   it drifted the moment the slot grid moved to the brand palette. */
	static final Color EMPTY_BORDER = Brand.BORDER_LIGHT;
	/** The tile behind a slot holding an offer. With no box round a working
	 *  slot, the grid was a dark field with sprites floating in it — "this
	 *  feels too plain now lol. make it subtle gray background. then we can
	 *  make white hte highlght focus". A step above the sidebar, so busy
	 *  slots read as tiles and empty ones as gaps, and nothing competes with
	 *  the white box. */
	static final Color SLOT_FILL = new Color(0x39, 0x37, 0x35);
	private static final Color TRACK = new Color(0x2B, 0x26, 0x21);
	/* 4 across, 2 down — the same arrangement the Grand Exchange clerk's own
	   interface uses. As a single row of 8 in a 225px sidebar each cell got
	   24px, narrower than the 36x32 item sprite it had to draw, so every slot
	   was a squashed thumbnail you couldn't identify without the tooltip.
	   Measured at 4 columns: 49x37 per cell, enough for the sprite at full
	   size — and, more to the point, a slot in the top-left of this panel is
	   the slot in the top-left of the GE window, so you can map one to the
	   other without counting. */
	private static final int COLS = 4;
	private static final int ROWS = 2;
	private static final int CELL = 32;
	private static final int BAR_H = 3;
	/* Both trimmed: the strip sat in more air than a row of eight 32px
	   squares needs, and the search box under it had its own strut on top
	   of this pad. Two pixels between the rows still separates them; three
	   under the strip is enough to keep the bottom bars off the box. */
	private static final int VGAP = 2;
	private static final int BOTTOM_PAD = 3;

	/* The grid's own height. The panel's open height is this plus the
	   chevron's row and the pad, all counted (see getPreferredSize): left
	   out, GridLayout quietly takes them out of the cells and each sprite
	   gets squeezed a few pixels short of its 32px height. */
	private static final int GRID_H = ROWS * (CELL + BAR_H + 2) + (ROWS - 1) * VGAP;

	private final ItemManager itemManager;
	private final Actions actions;
	private final Cell[] cells = new Cell[COLS * ROWS];
	/** The eight squares' own panel: what has to be in view for a figure to
	 *  count as seen — see {@link #noteShowing}. */
	private final JPanel grid;
	/** The grid with its fold chevron above it, and the one line that
	 *  replaces both when folded. Only one is ever added. */
	private final JPanel openView = new JPanel(new BorderLayout());
	/** The chevron's row over the grid. */
	private final JPanel topRow = new JPanel(new BorderLayout());
	private final JPanel foldedRow = new JPanel(new BorderLayout(4, 0));
	private final JLabel readyNote = new JLabel();
	private final JLabel repriceNote = new JLabel();
	/**
	 * Whether the grid is showing.
	 *
	 * "may as well add a small chevron here like above for flip ideas incase
	 * people want to collapse this". For this session only, like the flip
	 * ideas box and the watchlist: neither of those is remembered either, and
	 * one fold that outlived a restart while its neighbours did not would be
	 * the odd one out.
	 */
	private boolean open = true;
	private SlotInfo[] last;

	public GeSlotsPanel(ItemManager itemManager, Actions actions)
	{
		this.itemManager = itemManager;
		this.actions = actions;
		setLayout(new BorderLayout());
		setOpaque(false);
		setBorder(BorderFactory.createEmptyBorder(0, 0, BOTTOM_PAD, 0));
		setToolTipText("Your 8 Grand Exchange offer slots — the bar under each shows how much of that offer has filled");

		grid = new JPanel(new GridLayout(ROWS, COLS, 3, VGAP));
		grid.setOpaque(false);
		for (int i = 0; i < cells.length; i++)
		{
			cells[i] = new Cell(i);
			grid.add(cells[i]);
		}
		/* The chevron on a row of its own above the grid, at its right end.
		   It sat in a narrow column beside the grid and took that width off
		   all four columns ("this chevron pushed everything left"). The row
		   costs no height overall: it stands where the divider line between
		   the card and the slots was (see MainPanel). */
		final JLabel hide = foldChevron("▾", "Hide your GE slots");
		hide.setBorder(BorderFactory.createEmptyBorder(0, 6, 1, 2));
		topRow.setOpaque(false);
		topRow.add(hide, BorderLayout.EAST);
		openView.setOpaque(false);
		openView.add(topRow, BorderLayout.NORTH);
		openView.add(grid, BorderLayout.CENTER);

		/* Folded, the same line the flip ideas leave behind ("Recommendations
		   hidden"), plus what the squares were there to tell you: a slot
		   waiting to be collected, or one wanting a new price, should not
		   vanish because the grid did. */
		foldedRow.setOpaque(false);
		foldedRow.setBorder(BorderFactory.createEmptyBorder(0, 2, 2, 2));
		foldedRow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		foldedRow.setToolTipText("Show your GE slots");
		final JLabel title = new JLabel("GE slots hidden");
		title.setForeground(Brand.TEXT_STRUCTURAL);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 10.5f));
		foldedRow.add(title, BorderLayout.WEST);
		final JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		right.setOpaque(false);
		readyNote.setForeground(COLLECT_COLOR);
		readyNote.setFont(readyNote.getFont().deriveFont(Font.PLAIN, 10f));
		/* Neutral, not a side's colour: the slots it counts can be buys
		   and sells at once. */
		repriceNote.setForeground(Brand.TEXT_MAIN);
		repriceNote.setFont(repriceNote.getFont().deriveFont(Font.PLAIN, 10f));
		right.add(readyNote);
		right.add(repriceNote);
		right.add(foldChevron("▸", "Show your GE slots"));
		foldedRow.add(right, BorderLayout.EAST);
		/* On every child as well, because Swing does not bubble: a label with
		   no listener swallows the click — see collapsibleSection. */
		final MouseAdapter unfold = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e) { toggle(); }
		};
		foldedRow.addMouseListener(unfold);
		title.addMouseListener(unfold);
		right.addMouseListener(unfold);
		readyNote.addMouseListener(unfold);
		repriceNote.addMouseListener(unfold);

		add(openView, BorderLayout.CENTER);
		paintNotes();
		/* Showing or not as the sidebar opens, shuts or changes tab. */
		addHierarchyListener(e ->
		{
			if ((e.getChangeFlags() & java.awt.event.HierarchyEvent.SHOWING_CHANGED) != 0)
			{
				noteShowing();
			}
		});
		/* And as the sidebar scrolls: the panel scrolls its whole column, so
		   the squares can be scrolled out of sight while still "showing". */
		addHierarchyBoundsListener(new java.awt.event.HierarchyBoundsListener()
		{
			@Override
			public void ancestorMoved(java.awt.event.HierarchyEvent e)
			{
				noteShowing();
			}

			@Override
			public void ancestorResized(java.awt.event.HierarchyEvent e)
			{
				noteShowing();
			}
		});
		popTimer.setRepeats(true);
	}

	/** The chevron as the flip-ideas card draws it: same glyph, size and
	 *  colour, so the two read as the same control. */
	private JLabel foldChevron(String glyph, String tip)
	{
		final JLabel chevron = new JLabel(glyph);
		chevron.setForeground(Brand.TEXT_STRUCTURAL);
		chevron.setFont(chevron.getFont().deriveFont(10f));
		chevron.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		chevron.setToolTipText(tip);
		chevron.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e) { toggle(); }
		});
		return chevron;
	}

	private void toggle()
	{
		open = !open;
		removeAll();
		add(open ? openView : foldedRow, BorderLayout.CENTER);
		revalidate();
		repaint();
		noteShowing();
	}

	/*
	 * Preferred width 0, NOT Short.MAX_VALUE. A preferred width of 32767
	 * propagates up through FavoritesPanel into the scroll view, and a
	 * JViewport sizes a non-Scrollable view to max(viewport, preferred) — so
	 * one bad preferred width made the entire sidebar column 32767px wide.
	 * Only the MAXIMUM should be unbounded.
	 */
	@Override
	public Dimension getPreferredSize()
	{
		final int h = open
			? topRow.getPreferredSize().height + GRID_H + BOTTOM_PAD
			: super.getPreferredSize().height;
		return new Dimension(0, h);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Short.MAX_VALUE, getPreferredSize().height);
	}

	/** Call on the EDT. Fewer than 8 entries just leaves the tail empty. */
	public void update(SlotInfo[] slots)
	{
		last = slots;
		for (int i = 0; i < cells.length; i++)
		{
			cells[i].set((slots != null && i < slots.length) ? slots[i] : null);
		}
		paintNotes();
		revalidate();
		repaint();
	}

	private void paintNotes()
	{
		final int ready = readyCount(last);
		final int reprice = repriceCount(last);
		readyNote.setText(ready + " ready");
		readyNote.setVisible(ready > 0);
		repriceNote.setText(reprice + " to reprice");
		repriceNote.setVisible(reprice > 0);
	}

	/** Slots done and waiting to be collected: the green squares. */
	static int readyCount(SlotInfo[] slots)
	{
		int n = 0;
		for (SlotInfo s : slots != null ? slots : new SlotInfo[0])
		{
			if (s != null && s.state == SlotState.READY_COLLECT)
			{
				n++;
			}
		}
		return n;
	}

	/** Slots wanting a new price: the boxed ones, bar the green. Not one you
	 *  are pricing yourself, which has no box for the same reason — see
	 *  box(SlotInfo). */
	static int repriceCount(SlotInfo[] slots)
	{
		int n = 0;
		for (SlotInfo s : slots != null ? slots : new SlotInfo[0])
		{
			if (s != null && !s.adviceSkipped
				&& (s.state == SlotState.ACTIVE_ADJUST || s.state == SlotState.ACTIVE_LOSING))
			{
				n++;
			}
		}
		return n;
	}

	/** One slot: the item's sprite with a progress bar drawn beneath it.
	 *  The bar is painted rather than a JProgressBar so it can be 3px tall
	 *  and take the slot's own status colour without fighting the look and
	 *  feel. */
	/**
	 * How far along an offer is, as a percentage string.
	 *
	 * Two decimals below 1%, whole numbers above it. A 4-hour limit is often
	 * five figures, so the first fills of a big offer are a fraction of a
	 * percent — 138 of 18,000 is 0.77%, and as an integer that floored to a
	 * flat "0%", which says "nothing has happened" about an offer that has
	 * genuinely started. The two ends of the range need different precision.
	 *
	 * Nothing filled still reads "0", because 0.00% for an offer that has not
	 * moved is false precision. And anything short of complete stops at 99:
	 * 35,999 of 36,000 rounds to 100% and reads as finished when it is not,
	 * which is the one misreading that sends you to the GE for nothing.
	 *
	 * Static and package-private so the boundaries can be tested — they are
	 * where every version of this has gone wrong.
	 */
	static String percentText(int filled, int total)
	{
		if (total <= 0 || filled <= 0)
		{
			return "0";
		}
		if (filled >= total)
		{
			return "100";
		}
		final double pct = 100.0 * filled / total;
		if (pct >= 1.0)
		{
			return String.valueOf(Math.min(99, (int) pct));
		}
		/* Floors rather than rounds, but never below 0.01: a single item out
		   of a huge limit is a real fill and must not report as zero. */
		final double floored = Math.floor(pct * 100) / 100.0;
		return String.format("%.2f", Math.max(0.01, floored));
	}

	private class Cell extends JPanel
	{
		private final JLabel icon = new JLabel();
		private final int slot;
		private SlotInfo info;

		Cell(int slot)
		{
			this.slot = slot;
			setLayout(new BorderLayout());
			setOpaque(false);
			// Keeps the sprite clear of the progress bar painted along the
			// bottom edge — BorderLayout.CENTER otherwise centres the icon in
			// the cell's FULL height and a 32px sprite runs into the bar.
			setBorder(BorderFactory.createEmptyBorder(0, 0, BAR_H + 2, 0));
			icon.setHorizontalAlignment(SwingConstants.CENTER);
			icon.setPreferredSize(new Dimension(CELL, CELL));
			add(icon, BorderLayout.CENTER);
			/* Built fresh on each right-click rather than once up front,
			   because the entry has to read the slot's CURRENT state \u2014 the
			   same cell is "stop advising" one minute and "resume" the next,
			   and a menu built at construction time would be stale by then.
			   Popup triggers differ per platform (press on Linux, release on
			   Windows), so both are checked. */
			final MouseAdapter menu = new MouseAdapter()
			{
				@Override public void mousePressed(MouseEvent e) { maybeShow(e); }
				@Override public void mouseReleased(MouseEvent e) { maybeShow(e); }

				/* Left-click inspects, matching the watchlist and the finder.
				   The popup trigger is checked first because on Linux a
				   right-click arrives as a press with isPopupTrigger set, and
				   SwingUtilities.isRightMouseButton alone would let a
				   context-menu click also swap the card underneath it. */
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (e.isPopupTrigger() || SwingUtilities.isRightMouseButton(e) || !inspectable())
					{
						return;
					}
					actions.inspectItem(info.itemId, info.itemName);
				}

				private void maybeShow(MouseEvent e)
				{
					if (!e.isPopupTrigger() || actions == null
						|| info == null || info.state == SlotState.EMPTY)
					{
						return;
					}
					final boolean skipped = info.adviceSkipped;
					final JPopupMenu popup = new JPopupMenu();
					final JMenuItem toggle = new JMenuItem(skipped
						? "Resume price advice for this offer"
						: "Ignore advice \u2014 I'm pricing this one myself");
					toggle.setToolTipText(skipped
						? "Go back to being told when this offer's price has drifted off the market"
						: "Stop being told to reprice this offer. For when you are deliberately "
							+ "asking more than the market pays \u2014 an overnight sell, say \u2014 or "
							+ "bidding under it and content to wait.");
					toggle.addActionListener(a -> actions.setSlotAdviceSkipped(slot, !skipped));
					popup.add(toggle);
					popup.show(Cell.this, e.getX(), e.getY());
				}
			};
			addMouseListener(menu);
			icon.addMouseListener(menu);
		}

		/** Whether clicking this cell has anything to show. The name matters
		 *  as much as the id: the inspection card is rebuilt from a Row keyed
		 *  by name, so a nameless slot would open a card that never prices. */
		private boolean inspectable()
		{
			return actions != null && info != null && info.state != SlotState.EMPTY
				&& info.itemId > 0 && info.itemName != null && !info.itemName.isEmpty();
		}

		void set(SlotInfo next)
		{
			this.info = next;
			icon.setIcon(null);
			if (next != null && next.itemId > 0 && itemManager != null)
			{
				/* Same null guard as the other panels: no item sprites on the
				   login screen, and an NPE inside this loop would drop the
				   remaining slots rather than one icon. */
				final AsyncBufferedImage img = itemManager.getImage(next.itemId);
				if (img != null)
				{
					img.addTo(icon);
				}
			}
			final Cursor cursor = Cursor.getPredefinedCursor(
				inspectable() ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR);
			setCursor(cursor);
			icon.setCursor(cursor);
			final String tip = describe(next);
			setToolTipText(tip);
			/*
			 * The sprite needs it too, and that is not belt and braces.
			 *
			 * ToolTipManager attaches itself per component, to each one that
			 * has had setToolTipText called on it — it does NOT walk up to a
			 * parent for a component that has none. This label fills the
			 * cell's CENTER, so it is what the pointer is actually over
			 * essentially always, and the cell's own tooltip could only ever
			 * appear in the two-pixel margin around the edge. Which is why
			 * hovering an offer to see how far it had filled appeared to do
			 * nothing at all: the text was there, on a component nobody could
			 * reach.
			 */
			icon.setToolTipText(tip);
			repaint();
		}

		/**
		 * What this square is, what to do about it, and how far along it is —
		 * one short line each.
		 *
		 * This was a single run-on sentence: "Selling Ruby — 4,000 of 12,328
		 * (32%) (needs a new price). The market moved to 788 gp; yours is at
		 * 791 gp. Re-list at 788 gp — aborting keeps whatever already filled.
		 * Right-click to stop being told to reprice it. Click to inspect it."
		 * Every clause true, and nobody reads a paragraph off a 32px square.
		 *
		 * Same wording as the in-game box (GeOfferGridOverlay.stateLine), on
		 * purpose: these two describe the same eight slots, and two surfaces
		 * that disagree about what to call a state are worse than either.
		 */
		private String describe(SlotInfo s)
		{
			if (s == null || s.state == SlotState.EMPTY)
			{
				return "Empty slot";
			}
			final StringBuilder sb = new StringBuilder("<html>");
			sb.append(s.itemName != null ? s.itemName : "item");
			sb.append("<br>").append(stateLine(s));
			/* What it is listed at, every time. The game shows it on the GE
			   box; the sidebar square, which you can hover from anywhere,
			   did not. */
			if (s.listedPrice > 0)
			{
				sb.append("<br>").append(s.buy ? "Bidding " : "Asking ")
					.append(String.format("%,d", s.listedPrice)).append(" gp each");
			}
			if (s.quantityTotal > 0)
			{
				/* The percentage is the whole reason to hover: the raw pair
				   needs dividing in your head, which is exactly the work the
				   bar underneath exists to save.

				   Exact counts, NOT the abbreviated form used elsewhere.
				   35,999 of 36,000 abbreviates to "36K of 36K", which next to
				   a truthful "(99%)" reads as a contradiction and makes the
				   reader distrust both numbers. */
				sb.append("<br>").append(s.buy ? "Bought " : "Sold ")
					.append(String.format("%,d", Math.max(0, s.quantityFilled)))
					.append(" of ").append(String.format("%,d", s.quantityTotal))
					.append(" (").append(percentText(s.quantityFilled, s.quantityTotal)).append("%)");
				/* "Abort keeps it" rides with the number it is about, and
				   only when there is something to keep.

				   The long tooltip said "aborting keeps whatever already
				   filled" on every red slot. As boilerplate it was part of
				   what made the thing a paragraph — but the question it
				   answers is real and it is about money: being told to
				   re-list looks like being told to throw away a part-filled
				   offer, and someone who believes that will sit on a
				   mispriced one rather than risk it. */
				if ((s.state == SlotState.ACTIVE_ADJUST || s.state == SlotState.ACTIVE_LOSING)
					&& !s.adviceSkipped && s.quantityFilled > 0)
				{
					sb.append(" \u2014 abort keeps it");
				}
			}
			final String collect = collectLine(s);
			if (collect != null)
			{
				sb.append("<br>").append(collect);
			}
			/* The money line the in-game box carries, in the same words. */
			final String money = moneyLine(s);
			if (money != null)
			{
				sb.append("<br>").append(money);
			}
			/*
			 * The gestures, on one line, last.
			 *
			 * These were two whole sentences — "Right-click to stop being
			 * told to reprice it. Click to inspect it." — repeated on all
			 * eight squares, and a good part of what made this a paragraph.
			 * But they are the only place either gesture is discoverable:
			 * nothing on a 32px square suggests it is clickable, and an
			 * affordance nobody finds may as well not exist.
			 *
			 * So: one short line, both gestures, and only the ones that
			 * actually do something on THIS slot. The right-click is left off
			 * a slot already opted out, because the state line above it
			 * already says how to undo that.
			 */
			final List<String> gestures = new ArrayList<>();
			if (inspectable())
			{
				gestures.add("click: inspect");
			}
			if (!s.adviceSkipped
				&& (s.state == SlotState.ACTIVE_OK || s.state == SlotState.ACTIVE_ADJUST
					|| s.state == SlotState.ACTIVE_LOSING))
			{
				gestures.add("right-click: price it yourself");
			}
			if (!gestures.isEmpty())
			{
				sb.append("<br>").append(String.join("  \u00b7  ", gestures));
			}
			return sb.append("</html>").toString();
		}

		/**
		 * The instruction, not the diagnosis. "Needs a new price" on its own
		 * leaves you to go and work out WHICH price, and somebody duly
		 * cancelled an offer, re-placed it at the same number, and asked what
		 * they had cancelled for.
		 *
		 * It says re-list rather than modify, because the Exchange cannot
		 * edit a live offer's price — abort and place again is the only
		 * sequence there is.
		 */
		private String stateLine(SlotInfo s)
		{
			/* Collect first: a skip flag can outlive its offer into
			   ready-to-collect, and it must not hide the one state that wants
			   a click — the same rule box() applies to the colour. */
			if (s.state == SlotState.READY_COLLECT)
			{
				return "Ready to collect.";
			}
			if (s.adviceSkipped)
			{
				return "You are pricing this one \u2014 right-click to undo.";
			}
			if (s.state == SlotState.ACTIVE_LOSING)
			{
				final StringBuilder sb = new StringBuilder("Loses at this bid \u2014 lower it to ")
					.append(String.format("%,d", s.targetPrice)).append(" gp");
				if (s.breakEven > s.targetPrice)
				{
					sb.append(" (").append(String.format("%,d", s.breakEven)).append(" at most for +0)");
				}
				return sb.toString();
			}
			if (s.state == SlotState.ACTIVE_ADJUST)
			{
				if (s.noMargin)
				{
					return "No margin left \u2014 take a new flip.";
				}
				if (s.targetPrice > 0)
				{
					final StringBuilder sb = new StringBuilder(adjustVerb(s.buy))
						.append(String.format("%,d", s.targetPrice)).append(" gp").append(adjustTail(s.buy));
					if (s.offerPrice > 0)
					{
						sb.append(" (yours: ").append(String.format("%,d", s.offerPrice)).append(")");
					}
					return sb.toString();
				}
				return "Priced off the market \u2014 re-list.";
			}
			/* Green has only ever meant "not red", which is true and says
			   nothing — see GeOfferGridOverlay.stateLine for the report. */
			return "Priced fine \u2014 leave it.";
		}


		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			final Graphics2D g2 = (Graphics2D) g;
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			final int w = getWidth();
			final int h = getHeight();
			final SlotState state = info != null ? info.state : SlotState.EMPTY;

			if (state != SlotState.EMPTY)
			{
				g2.setColor(SLOT_FILL);
				g2.fillRect(0, 0, w, h - BAR_H - 1);
			}
			/* Every square keeps the faint frame an empty one has, so the
			   grid still reads as eight slots; a box goes over it only when
			   the slot needs you. */
			g2.setColor(EMPTY_BORDER);
			g2.drawRect(0, 0, w - 1, h - BAR_H - 2);
			final Color box = box(info);
			if (box != null)
			{
				final boolean done = box == COLLECT_COLOR;
				g2.setColor(done ? box : REPRICE_BOX);
				frame(g2, 0, 0, w, h - BAR_H - 1, done ? COLLECT_BOX_PX : 1);
			}

			final int barY = h - BAR_H;
			g2.setColor(TRACK);
			g2.fillRect(0, barY, w, BAR_H);
			if (state != SlotState.EMPTY && info != null)
			{
				// A collected-ready offer is done by definition, whatever the
				// counter says — otherwise a cancelled part-fill would show a
				// half bar next to a "ready to collect" outline.
				final double pct = state == SlotState.READY_COLLECT ? 1.0
					: (info.quantityTotal > 0 ? Math.min(1.0, info.quantityFilled / (double) info.quantityTotal) : 0.0);
				final int fill = (int) Math.round(w * pct);
				g2.setColor(barColour(info));
				g2.fillRect(0, barY, fill, BAR_H);
			}
		}

		/** Over the sprite as well as the tile, so the figure is painted
		 *  after the icon, not under it. */
		@Override
		public void paint(Graphics g)
		{
			super.paint(g);
			final long now = clock.getAsLong();
			for (ProfitPops.Pop p : pops.running(now, s -> s == slot))
			{
				ProfitPops.draw((Graphics2D) g, new java.awt.Rectangle(0, 0, getWidth(), getHeight()), p, now,
					FontManager.getRunescapeBoldFont(), ProfitPops.shortText(p));
			}
		}
	}

	/** "+2K" rising off a square in the sidebar — see {@link #pop}. */
	private final ProfitPops pops = new ProfitPops();
	/** The time the figures work to. A field so a test can move it. */
	java.util.function.LongSupplier clock = System::currentTimeMillis;
	/** Repaints while a figure is moving; stops itself when none is. */
	private final javax.swing.Timer popTimer = new javax.swing.Timer(33, e -> animate());
	/** Whether the squares are on screen: this panel showing (the PocketGE
	 *  tab open, the sidebar out) and the grid not folded away. Volatile:
	 *  set on the EDT, read by the plugin on the client thread. */
	private volatile boolean squaresShowing;

	/**
	 * A sale for {@code slot} made {@code profit}, and the squares are where
	 * you will see it: the figure rises off the square. EDT.
	 *
	 * "thoughts on adding little green +$200gp or whatever profits / lossses
	 * as well on these on side bar any time you dont have the grand exchange
	 * window open so it doesnt double repeat". The plugin decides which: a
	 * sale's figure plays once, over the Exchange's square when that is open
	 * and here when it is not — see PocketGeTrackerPlugin.popInSidebar.
	 */
	public void pop(int slot, long profit)
	{
		pop(slot, profit, false);
	}

	/** As above; with {@code coins}, {@code gp} is what a sale with no buy
	 *  on record brought in, and rises in gold — see ProfitPops. EDT. */
	public void pop(int slot, long gp, boolean coins)
	{
		if (slot < 0 || slot >= cells.length)
		{
			return;
		}
		pops.start(slot, gp, coins, clock.getAsLong());
		cells[slot].repaint();
		if (!popTimer.isRunning())
		{
			popTimer.start();
		}
	}

	private void animate()
	{
		final List<ProfitPops.Pop> live = pops.running(clock.getAsLong(), s -> true);
		for (Cell c : cells)
		{
			c.repaint();
		}
		if (live.isEmpty())
		{
			popTimer.stop();
		}
	}

	/** See {@link #squaresShowing}. Any thread. */
	public boolean squaresShowing()
	{
		return squaresShowing;
	}

	/**
	 * Whether a figure here would be seen, worked out on the EDT whenever it
	 * can change. A figure played here counts as shown, so "on screen" has
	 * to mean on screen — the review that found these: the squares scrolled
	 * out of view, or the client minimised or behind another window, all
	 * still "showing" to Swing, and each used up a sale's figure nobody saw.
	 * Those wait instead, for the sidebar or the Exchange.
	 */
	private void noteShowing()
	{
		final java.awt.Window w = SwingUtilities.getWindowAncestor(this);
		if (w != watched)
		{
			if (watched != null)
			{
				watched.removeWindowListener(windowWatch);
				watched.removeWindowStateListener(windowWatch);
				watched.removeWindowFocusListener(windowWatch);
			}
			watched = w;
			if (w != null)
			{
				w.addWindowListener(windowWatch);
				w.addWindowStateListener(windowWatch);
				w.addWindowFocusListener(windowWatch);
			}
		}
		final boolean minimised = w instanceof java.awt.Frame
			&& (((java.awt.Frame) w).getExtendedState() & java.awt.Frame.ICONIFIED) != 0;
		squaresShowing = squaresSeen(open, isShowing(), w != null && (w.isActive() || w.isFocused()), minimised,
			grid.getVisibleRect().height, grid.getHeight());
	}

	/** The rule {@link #noteShowing} applies: unfolded, showing, the client
	 *  the window in front and not minimised, and at least half the squares'
	 *  height in view. */
	static boolean squaresSeen(boolean open, boolean showing, boolean windowInFront, boolean minimised,
		int visibleHeight, int height)
	{
		return open && showing && windowInFront && !minimised && height > 0 && visibleHeight * 2 >= height;
	}

	/** The window the squares are in, watched for being minimised or left. */
	private java.awt.Window watched;
	private final java.awt.event.WindowAdapter windowWatch = new java.awt.event.WindowAdapter()
	{
		@Override
		public void windowActivated(java.awt.event.WindowEvent e)
		{
			noteShowing();
		}

		@Override
		public void windowDeactivated(java.awt.event.WindowEvent e)
		{
			noteShowing();
		}

		@Override
		public void windowIconified(java.awt.event.WindowEvent e)
		{
			noteShowing();
		}

		@Override
		public void windowDeiconified(java.awt.event.WindowEvent e)
		{
			noteShowing();
		}

		@Override
		public void windowStateChanged(java.awt.event.WindowEvent e)
		{
			noteShowing();
		}

		@Override
		public void windowGainedFocus(java.awt.event.WindowEvent e)
		{
			noteShowing();
		}

		@Override
		public void windowLostFocus(java.awt.event.WindowEvent e)
		{
			noteShowing();
		}
	};

	/** Every figure off the squares: the setting switched off. EDT. */
	public void clearPops()
	{
		pops.clear();
		popTimer.stop();
		for (Cell c : cells)
		{
			c.repaint();
		}
	}

	/**
	 * The hover's money line, as HTML, in the words GeOfferGridOverlay.
	 * moneyLine uses on the in-game box — "Profit if it flips" on a buy, and
	 * on a sell that has started selling, what it has made so far and what
	 * is still to come. Null when there is nothing honest to say.
	 */
	static String moneyLine(SlotInfo s)
	{
		if (s == null)
		{
			return null;
		}
		if (!s.buy && s.bookedProfit != null)
		{
			/* See GeOfferGridOverlay.moneyLine: a figure booked on only some
			   of what sold says so, and gives no "in all". */
			final boolean whole = s.bookedUnits >= s.quantityFilled;
			final StringBuilder sb = new StringBuilder("Made ").append(gp(s.bookedProfit))
				.append(whole ? " so far" : " on " + String.format("%,d", s.bookedUnits)
					+ " of " + String.format("%,d", s.quantityFilled) + " sold");
			if (s.projectedProfit != null)
			{
				sb.append(", ").append(gp(s.projectedProfit)).append(" to come");
				if (whole)
				{
					final long all = s.bookedProfit + s.projectedProfit;
					sb.append(" (").append(all >= 0 ? "+" : "-")
						.append(net.runelite.client.util.QuantityFormatter.quantityToStackSize(Math.abs(all)))
						.append(" in all)");
				}
			}
			return sb.toString();
		}
		if (s.projectedProfit == null)
		{
			return null;
		}
		return (s.buy ? "Profit if it flips: " : "Profit: ") + gp(s.projectedProfit);
	}

	/** A signed gp figure in the profit or loss colour. */
	private static String gp(long p)
	{
		final Color c = p >= 0 ? TipStyle.GOOD : TipStyle.BAD;
		return String.format("<font color='#%06x'>", c.getRGB() & 0xFFFFFF)
			+ (p >= 0 ? "+" : "-")
			+ net.runelite.client.util.QuantityFormatter.quantityToStackSize(Math.abs(p))
			+ " gp</font>";
	}

	/** Hand the slots the theme's buy and sell colours. Any thread; the
	 *  next paint picks them up. */
	static void setTheme(Color buy, Color sell)
	{
		if (buy != null)
		{
			buyColour = buy;
		}
		if (sell != null)
		{
			sellColour = sell;
		}
	}

	/** A buy's colour or a sell's, from the theme: the bar's. */
	/**
	 * A slot's bar: buying or selling, in the theme's colours — "if you are
	 * selling somthing ... the theme sell bar color. if you are buyingt
	 * somthing ... buy color" — done or not. Done is the green box's to say.
	 *
	 * It went green when done for a while ("turn the blue bar green as well
	 * ... once its completeed"), which made a finished buy and a finished
	 * sale look the same; a thin line of the side's colour under the green
	 * was tried and read as noise. Of the three mocked up on the player's
	 * own grid, "go with A": the bar keeps its colour, full.
	 */
	static Color barColour(SlotInfo s)
	{
		return sideColour(s != null && s.buy);
	}

	static Color sideColour(boolean buy)
	{
		return buy ? buyColour : sellColour;
	}

	/**
	 * The box round a slot, or null for none: only when it needs you.
	 *
	 * Takes the whole SlotInfo because "you are pricing this one yourself"
	 * is not a state — the offer is still perfectly active — but it does
	 * take the box away, as it does on the in-game one.
	 */
	static Color box(SlotInfo s)
	{
		final SlotState state = s != null ? s.state : SlotState.EMPTY;
		/* Collect before the skip flag: the flag outlives its offer into
		   ready-to-collect, and hiding a collectable slot would hide the one
		   state that wants a click. The in-game overlay never meets this
		   case, because buildSlotViews drops inactive offers before it gets
		   there. */
		if (state == SlotState.READY_COLLECT)
		{
			return COLLECT_COLOR;
		}
		if (s == null || s.adviceSkipped)
		{
			return null;
		}
		/* Off the market, or filling at a loss: both mean "move this price",
		   and the hover says which and to what. */
		return state == SlotState.ACTIVE_ADJUST || state == SlotState.ACTIVE_LOSING ? REPRICE_COLOR : null;
	}

	private static String label(SlotState state)
	{
		switch (state)
		{
			case ACTIVE_OK: return "priced fine";
			case ACTIVE_ADJUST: return "needs a new price";
			case ACTIVE_LOSING: return "losing at this price";
			case READY_COLLECT: return "ready to collect";
			case EMPTY:
			default: return "empty";
		}
	}
}

package com.pocketge.tracker;

/**
 * One high alchemy cast on an item you hold: what it makes after the nature
 * rune it burns, against what one of the item cost you.
 *
 * "thoughts on hover over also showing high alch profit ea alch?" — the
 * question a stack in the bank actually poses is whether to sell it or alch
 * it, and nothing on screen said what alching comes to. The cost is what
 * you paid when the plugin watched you buy, and otherwise the price the
 * stack would sell at: alching it is then giving up that sale.
 *
 * Plain arithmetic, so the hover and the card cannot work it out two ways.
 */
final class HighAlch
{
	/** The rune every cast burns; priced at its insta-buy, what one costs
	 *  you now. */
	static final int NATURE_RUNE = 561;

	private HighAlch()
	{
	}

	/** What one cast makes: the alch value, less a nature rune, less what
	 *  one of the item cost. */
	static long perCast(long alchValue, long naturePrice, long itemCost)
	{
		return alchValue - naturePrice - itemCost;
	}

	/** Whether there is anything to say: an item that alchs for something,
	 *  a nature rune with a price, and a cost to measure against. */
	static boolean known(long alchValue, long naturePrice, long itemCost)
	{
		return alchValue > 0 && naturePrice > 0 && itemCost > 0;
	}

	/** "+15", "-1,265", "+24,247": exact, always signed — the hover, which
	 *  has the room. */
	static String signed(long gp)
	{
		return (gp < 0 ? "-" : "+") + String.format("%,d", Math.abs(gp));
	}

	/** "+15", "-797", "+1.2K", "-24.2K", "+1.5M": always signed, at most
	 *  four characters of figure — the card's stat cell, which has about
	 *  fifty pixels beside QUANTITY and VALUE. */
	static String compact(long gp)
	{
		final long abs = Math.abs(gp);
		final String n = abs < 1_000 ? Long.toString(abs)
			: abs < 999_950 ? oneDecimal(abs / 1_000.0) + "K"
			: oneDecimal(abs / 1_000_000.0) + "M";
		return (gp < 0 ? "-" : "+") + n;
	}

	private static String oneDecimal(double v)
	{
		final String s = String.format(java.util.Locale.ROOT, "%.1f", v);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}
}

package com.pocketge.tracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.util.QuantityFormatter;

/**
 * The last few closed flips, and a link to all of them on pocketge.com.
 *
 * The two halves do different jobs, which is why both exist. The rows answer
 * "did that actually book, and for how much?" — a question you ask in the
 * seconds after a sell fills, standing at the Exchange, where opening a
 * browser is not a reasonable answer. The link answers "how am I doing?" —
 * sorting, charting, gp per slot-hour, a ledger thousands of rows deep, none
 * of which fits in a 225px column.
 *
 * Deliberately NOT paginated. Page arrows and a "Page 1 of 1" counter are a
 * lot of furniture for a column this narrow, and paging is browsing, which is
 * the thing the link is for. This is the tail of the ledger for the range
 * picked above it: the latest five, and the rest of the range on request.
 */
public class HistoryPanel extends JPanel
{
	/** How many recent flips get a row. Enough to cover a burst of fills
	 *  without the section growing past the watchlist beneath it. */
	private static final int RECENT = 5;
	/** "Show all" stops here: a sidebar row per trade is fine for a day's
	 *  work and silly for years of it, which the Flip history page is for. */
	static final int SHOW_ALL_CAP = 200;

	private static final Color POSITIVE = new Color(0x1F, 0xB8, 0x5C);
	private static final Color NEGATIVE = new Color(0xEF, 0x53, 0x50);
	private static final Color ROW_TEXT = new Color(0xD9, 0xD3, 0xC7);
	/** The stats rows' caption colour, so the list's heading reads as one
	 *  of them rather than as a footnote under them. */
	private static final Color HEADING = new Color(0xB8, 0xB0, 0xA2);
	/** Every line here is the size the stats rows above it are. At 11 this
	 *  list was the smallest text in the sidebar, under the biggest numbers:
	 *  "can this area be clearer to read". */
	private static final float TEXT_SIZE = 12f;
	private static final javax.swing.border.Border LIST_RULE = BorderFactory.createCompoundBorder(
		BorderFactory.createMatteBorder(1, 0, 0, 0, Brand.BORDER_LIGHT),
		BorderFactory.createEmptyBorder(1, 0, 0, 0));

	public interface Actions
	{
		/** Routed through the plugin rather than opening a URL here, so every
		 *  chart in the sidebar reuses the same tab — see
		 *  AdvisorPanel.Actions.openChart. */
		void openChart(String itemName);

		/** The player says this trade's buys cost {@code unitCost} each —
		 *  see PocketGeTrackerPlugin.correctPaid. */
		default void correctPaid(Flip trade, long unitCost)
		{
		}
	}

	private final JLabel countLabel = new JLabel();
	private final JPanel rows = new JPanel();
	private final Actions actions;
	/** False between logout and the next login. Every flip here belongs to the
	 *  character that made it, and logged out there is no character — the same
	 *  reason the stats header blanks and the watchlist hides itself. A list of
	 *  somebody's trades sitting under "Log in to the game" is the panel
	 *  claiming to know whose they are when it does not. */
	private boolean loggedIn = true;
	/** The last list handed to {@link #update}, so logging back in can redraw
	 *  without waiting for the next refresh to come round. */
	private List<Flip> lastFlips = List.of();

	public HistoryPanel(Actions actions)
	{
		this.actions = actions;
		setLayout(new BorderLayout(0, 4));
		setOpaque(false);
		/* The same side padding as the stats above it, so the flip rows
		   line up with them and stop at the same margin. */
		setBorder(BorderFactory.createEmptyBorder(8, StatsHeaderPanel.SIDE_PAD, 0, StatsHeaderPanel.SIDE_PAD));

		JPanel header = new JPanel(new BorderLayout(0, 2));
		header.setOpaque(false);

		countLabel.setForeground(HEADING);
		countLabel.setFont(countLabel.getFont().deriveFont(Font.BOLD, TEXT_SIZE));
		header.add(countLabel, BorderLayout.WEST);

		JLabel link = new JLabel("Flip history ↗", SwingConstants.RIGHT);
		link.setForeground(Brand.TEXT_STRUCTURAL);
		link.setFont(link.getFont().deriveFont(11f));
		link.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		/* Says what it needs, because the page cannot read your ledger over
		   the public internet and never will — it asks the plugin for it on
		   127.0.0.1. With the bridge off the page opens and explains that;
		   better to say so here, before the click. */
		link.setToolTipText("<html>Every flip you have ever made, on pocketge.com."
			+ "<br>Needs <b>Local website bridge</b> switched on in settings — the page"
			+ "<br>reads the ledger from this computer, not from a server.</html>");
		link.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				LinkBrowser.browse(PocketGeLinks.flips("flip_history"));
			}
		});
		header.add(link, BorderLayout.EAST);
		add(header, BorderLayout.NORTH);

		rows.setOpaque(false);
		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		add(rows, BorderLayout.CENTER);

		/* The rest of the range on request. The list keeps to the latest
		   five so the section stays short; "if you have all time, then youd
		   see all the flips youve ever made" is one click from here. */
		moreLink.setForeground(Brand.TEXT_STRUCTURAL);
		moreLink.setFont(moreLink.getFont().deriveFont(11f));
		moreLink.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		moreLink.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		moreLink.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				showAll = !showAll;
				update(lastFlips, range);
			}
		});
		add(moreLink, BorderLayout.SOUTH);

		update(List.of());
	}

	/** The range the list is showing — the one picked above the stats. */
	private FlipStats.Range range = FlipStats.Range.ALL;
	/** Whether every trade in the range is listed, not just the latest few. */
	private boolean showAll;
	private final JLabel moreLink = new JLabel();

	/** How many rows to draw of {@code n} trades. */
	static int shown(int n, boolean showAll)
	{
		return Math.min(n, showAll ? SHOW_ALL_CAP : RECENT);
	}

	/** The toggle under the rows, or "" when everything already fits. */
	static String moreText(int n, boolean showAll)
	{
		if (n <= RECENT)
		{
			return "";
		}
		if (showAll)
		{
			return n > SHOW_ALL_CAP ? "Latest " + SHOW_ALL_CAP + " shown · show fewer" : "Show fewer";
		}
		return "Show all " + Math.min(n, SHOW_ALL_CAP) + (n > SHOW_ALL_CAP ? " latest" : "");
	}

	/** "3 flips in the last hour", "No flips this session". */
	static String countText(int n, FlipStats.Range range)
	{
		final String when;
		switch (range != null ? range : FlipStats.Range.ALL)
		{
			case SESSION:
				when = "this session";
				break;
			case H1:
				when = "in the last hour";
				break;
			case H4:
				when = "in the last 4 hours";
				break;
			case H12:
				when = "in the last 12 hours";
				break;
			case D1:
				when = "in the last day";
				break;
			case W1:
				when = "in the last week";
				break;
			case M1:
				when = "in the last month";
				break;
			default:
				when = "recorded";
		}
		if (n == 0)
		{
			return range == FlipStats.Range.ALL || range == null ? "No flips recorded yet" : "No flips " + when;
		}
		return n + (n == 1 ? " flip " : " flips ") + when;
	}

	/** Call on the Swing EDT when the player logs in or out. */
	public void setLoggedIn(boolean loggedIn)
	{
		if (this.loggedIn == loggedIn)
		{
			return;
		}
		this.loggedIn = loggedIn;
		update(lastFlips);
	}

	/** Call on the Swing EDT whenever the flip list changes. */
	public void update(List<Flip> flips)
	{
		update(flips, range);
	}

	/** The flips in {@code range}, which the count says. EDT. */
	public void update(List<Flip> flips, FlipStats.Range range)
	{
		this.range = range != null ? range : FlipStats.Range.ALL;
		lastFlips = flips != null ? flips : List.of();
		if (!loggedIn)
		{
			/* Rows gone, and no caption: the advisor's banner at the top of
			   the sidebar is the single place that explains a logged-out
			   panel. The link stays live — pocketge.com is a website and does
			   not need you logged into the game to show you your history. */
			countLabel.setText("");
			moreLink.setText("");
			rows.removeAll();
			rows.setBorder(null);
			rows.revalidate();
			rows.repaint();
			return;
		}
		updateRows(lastFlips);
	}

	private void updateRows(List<Flip> flips)
	{
		/* One row per TRADE, not per fill. A sell offer is filled in as many
		   chunks as the Exchange finds buyers for, so one sale of 8,218
		   adamantite bars arrived here as five rows — "2 x Adamantite bar,
		   +22 gp" among them — which reports the shape of the order book
		   rather than what you did. The fills are still recorded and still
		   priced individually; they are only shown as the trade they were. */
		final List<Flip> trades = Flip.byTrade(flips);
		final int n = trades.size();
		countLabel.setText(countText(n, range));

		rows.removeAll();
		/* A hairline under the heading, so the rows read as its list — and
		   only over rows: with none it was a rule with nothing under it. */
		rows.setBorder(n > 0 ? LIST_RULE : null);
		/* Newest first. The tracker appends as flips close, so the tail of the
		   list is the part you have not seen yet. */
		final int show = shown(n, showAll);
		for (int i = n - 1; i >= 0 && n - i <= show; i--)
		{
			rows.add(row(trades.get(i)));
		}
		moreLink.setText(moreText(n, showAll));
		moreLink.setVisible(!moreLink.getText().isEmpty());
		rows.revalidate();
		rows.repaint();
	}

	/**
	 * Right-click a trade: "Correct what I paid…". For a sale booked against
	 * buys the player no longer had — "it thinks i paid 359 each for these,
	 * i only paid 280 each. i lost money but i didnt lose that much money".
	 * Only on a trade with an offer token, which names its fills exactly;
	 * older rows are grouped by inference, and re-pricing the wrong set of
	 * fills would be worse than none. Null for a row without one.
	 */
	private MouseAdapter correctMenu(Flip f, JPanel row)
	{
		if (f.offerId == 0 || f.quantity <= 0 || actions == null)
		{
			return null;
		}
		return new MouseAdapter()
		{
			@Override public void mousePressed(MouseEvent e) { maybeShow(e); }
			@Override public void mouseReleased(MouseEvent e) { maybeShow(e); }

			private void maybeShow(MouseEvent e)
			{
				if (!e.isPopupTrigger())
				{
					return;
				}
				final javax.swing.JPopupMenu m = new javax.swing.JPopupMenu();
				final javax.swing.JMenuItem fix = new javax.swing.JMenuItem("Correct what I paid\u2026");
				fix.addActionListener(a -> askPaid(f, row));
				m.add(fix);
				m.show(e.getComponent(), e.getX(), e.getY());
			}
		};
	}

	private void askPaid(Flip f, java.awt.Component near)
	{
		final long paidEach = Math.round(f.buySpent / (double) f.quantity);
		String note = "";
		Object prefill = String.valueOf(paidEach);
		while (true)
		{
			final String ask = "<html><div style='width:220px'>What did you pay each for these <b>"
				+ String.format("%,d", f.quantity) + " " + f.itemName + "</b>?<br><br>PocketGE has <b>"
				+ String.format("%,d", paidEach) + "</b> gp each, so this sale shows <b>" + signed(f.profit) + "</b>."
				+ "<br><br><span style='color:#a5a5a5'>Re-prices this sale in your history and totals. What it sold"
				+ " for and the tax stay as they were.</span>" + note + "</div></html>";
			final Object answer = javax.swing.JOptionPane.showInputDialog(near, ask, "Correct what I paid",
				javax.swing.JOptionPane.PLAIN_MESSAGE, null, null, prefill);
			if (answer == null)
			{
				return; // cancelled
			}
			final long unitCost = parsePaid(answer);
			if (unitCost > 0)
			{
				if (unitCost != paidEach)
				{
					actions.correctPaid(f, unitCost);
				}
				return;
			}
			/* Not left to vanish: a price typed and OK'd that did nothing
			   looked like it had worked. */
			note = "<br><br><span style='color:#ef5350'>Couldn't read \"" + escape(answer.toString())
				+ "\" as a price. Type a number like 277, 1.2k or 45m.</span>";
			prefill = answer;
		}
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** "277", "277 gp", "1,250", "1.2k", "45m", "2.1b" -> gp; anything else
	 *  -> 0. The game's own number boxes take k, m and b, so players type
	 *  them. */
	static long parsePaid(Object answer)
	{
		if (answer == null)
		{
			return 0;
		}
		final String t = answer.toString().trim().toLowerCase().replaceAll("(gp|,|\\s)", "");
		final java.util.regex.Matcher m = java.util.regex.Pattern.compile("(\\d{1,12})(?:\\.(\\d{1,3}))?([kmb]?)").matcher(t);
		if (!m.matches())
		{
			return 0;
		}
		final long scale = "k".equals(m.group(3)) ? 1_000L : "m".equals(m.group(3)) ? 1_000_000L
			: "b".equals(m.group(3)) ? 1_000_000_000L : 1L;
		final java.math.BigDecimal v = new java.math.BigDecimal(m.group(1) + (m.group(2) != null ? "." + m.group(2) : ""))
			.multiply(java.math.BigDecimal.valueOf(scale));
		if (v.signum() <= 0 || v.compareTo(java.math.BigDecimal.valueOf(Integer.MAX_VALUE)) > 0)
		{
			return 0; // no item costs that much, and a GE price is an int
		}
		return v.setScale(0, java.math.RoundingMode.HALF_UP).longValueExact();
	}

	private JPanel row(Flip f)
	{
		final JPanel p = new JPanel(new BorderLayout(10, 0))
		{
			@Override
			public Dimension getPreferredSize()
			{
				/* Width 0, real height.
				 *
				 * BoxLayout takes its container's preferred width from the
				 * widest child, so "18,000 × Sapphire necklace" next to
				 * "-666K gp" asked for 243px inside a 217px column — which
				 * does not clip, it widens the sidebar's scroll content and
				 * puts a horizontal scrollbar under the whole panel. The row
				 * is stretched to the full column width by getMaximumSize
				 * below regardless, so it never needs to ask for any. */
				return new Dimension(0, super.getPreferredSize().height);
			}
		};
		p.setOpaque(false);
		p.setBorder(BorderFactory.createEmptyBorder(4, 0, 1, 0));
		p.setAlignmentX(0f);

		/* Abbreviated, unlike the quantity on the offer chip — that one you
		   type, this one you read. "18K ×" buys back about 25px of item name
		   in a column that has none to spare, and the exact figure is a hover
		   away. Muted, and its own label: the count and the name ran
		   together in one colour, and the name is what the eye looks for. */
		final JLabel qty = new JLabel(QuantityFormatter.quantityToStackSize(f.quantity) + " × ");
		qty.setForeground(Brand.TEXT_STRUCTURAL);
		qty.setFont(qty.getFont().deriveFont(TEXT_SIZE));
		final JLabel name = new JLabel(f.itemName);
		name.setForeground(ROW_TEXT);
		name.setFont(name.getFont().deriveFont(TEXT_SIZE));

		final JLabel amount = new JLabel(signed(f.profit), SwingConstants.RIGHT);
		amount.setForeground(f.profit >= 0 ? POSITIVE : NEGATIVE);
		amount.setFont(amount.getFont().deriveFont(Font.BOLD, TEXT_SIZE));

		/* Name in CENTER and money in EAST, so a long item name ellipsizes
		   and the figure beside it never does — same priority as the stat
		   rows. The tooltip carries the full name either way. */
		final JPanel what = new JPanel(new BorderLayout(0, 0));
		what.setOpaque(false);
		what.add(qty, BorderLayout.WEST);
		what.add(name, BorderLayout.CENTER);
		p.add(what, BorderLayout.CENTER);
		p.add(amount, BorderLayout.EAST);

		final String tip = tooltip(f);
		qty.setToolTipText(tip);
		name.setToolTipText(tip);
		amount.setToolTipText(tip);
		p.setToolTipText(tip);

		p.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		final MouseAdapter open = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				/* Left click only. RuneLite's popups are heavyweight, and on
				   Windows the click that follows a right-click's menu reached
				   the row too, opening the chart under "Correct what I
				   paid…". */
				if (actions != null && !e.isPopupTrigger() && !javax.swing.SwingUtilities.isRightMouseButton(e))
				{
					actions.openChart(f.itemName);
				}
			}
		};
		/* On the labels as well as the row. A label with a tooltip has a
		   mouse listener of its own (ToolTipManager's), so a click on the
		   text went to the label and never reached the row — only the gap
		   between name and figure opened the chart. */
		final MouseAdapter menu = correctMenu(f, p);
		for (java.awt.Component c : new java.awt.Component[]{p, qty, name, amount})
		{
			c.addMouseListener(open);
			if (menu != null)
			{
				c.addMouseListener(menu);
			}
		}
		/* BoxLayout hands a component its MAXIMUM height, and a BorderLayout
		   panel's is unbounded — without this one row would swallow the
		   section. Width stays unbounded so the row still fills the column. */
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, p.getPreferredSize().height));
		return p;
	}

	private static String tooltip(Flip f)
	{
		final StringBuilder sb = new StringBuilder("<html>");
		sb.append(f.itemName).append("<br>")
			.append("Bought ").append(String.format("%,d", f.quantity))
			.append(" at ").append(QuantityFormatter.quantityToStackSize(f.avgBuy())).append(" gp<br>")
			.append("Sold at ").append(QuantityFormatter.quantityToStackSize(f.avgSell())).append(" gp<br>")
			.append("Tax ").append(QuantityFormatter.quantityToStackSize(f.tax)).append(" gp<br>")
			.append("Profit ").append(signed(f.profit)).append("<br>");
		final long held = f.holdMillis();
		if (held < 0)
		{
			/* Never "0:00:00". The plugin did not watch this stack being
			   bought, so it does not know — and an instant fill is the most
			   flattering thing a blank could be mistaken for. */
			sb.append("Held — (buy time not recorded)");
		}
		else
		{
			sb.append("Held ").append(StatsHeaderPanel.formatDuration(held));
			final long perHour = f.profitPerHour();
			if (perHour != 0)
			{
				sb.append(" · ").append(signed(perHour)).append("/hr");
			}
		}
		sb.append("<br><br>Click for the chart on pocketge.com");
		return sb.toString();
	}

	private static String signed(long v)
	{
		return (v >= 0 ? "+" : "") + QuantityFormatter.quantityToStackSize(v) + " gp";
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.SynchronousQueue;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

/**
 * Tiny opt-in HTTP listener bound to 127.0.0.1 ONLY. pocketge.com open in
 * the local browser polls GET /flips to show this session's trades, your
 * plugin-side Favorite lists, portfolio value, and current top
 * recommendation — a same-machine link between the plugin and the site with
 * no accounts and no server: data never leaves the machine. It also accepts
 * POST /favorites (add/remove an item) and POST /favoriteLists
 * (create/rename/delete a list) so the site can drive the same TradingView-
 * style watchlists the in-game panel manages — the link works both
 * directions, not just plugin -> website.
 *
 * Every request must carry a PocketGE Origin and this loopback address as
 * its Host, or it is refused with 403 before it reaches a handler — see
 * {@link #refusal}. That is what keeps OTHER WEBSITES out: a browser will
 * not let a page fake its Origin, and the Host check stops a page that
 * re-points its own hostname at 127.0.0.1. It is not a lock against
 * programs already running on the computer, which can send any header they
 * like; those already run as the player and could read RuneLite's own
 * files, so the bridge does not pretend to stop them. The
 * Private-Network-Access preflight header is answered for the Chromium
 * versions that send one; current Chrome asks the player instead, with its
 * own Local Network Access prompt, before the https page may reach
 * localhost at all.
 */
public class LocalBridgeServer
{
	private static final String[] ALLOWED_ORIGINS = {
		"https://pocketge.com",
		"https://www.pocketge.com",
		"http://localhost:8901" // local dev of the site
	};

	/** Called with (listId, itemId, name, remove) when the website POSTs a
	 *  favorite change — remove=true means unfavorite rather than add.
	 *  listId is null when the website didn't specify one, meaning
	 *  "whichever list is currently active in-game". */
	public interface FavoriteWriter
	{
		void write(String listId, int itemId, String name, boolean remove);
	}

	/** Called when the website POSTs a list-management action. create()
	 *  returns the new list's id (never null/blank name is rejected before
	 *  this is called). rename()/delete() are no-ops if listId doesn't match
	 *  any current list — same as the in-game chip menu's own guards. */
	public interface ListWriter
	{
		String create(String name);
		void rename(String listId, String name);
		void delete(String listId);
		/** Two-way order sync: the site sends the order it is showing and the
		 *  plugin's list is rewritten to match. Membership is never changed
		 *  by this — see FavoriteLists.reorderTo for why that has to be true
		 *  when both ends can edit at once. */
		void reorder(String listId, List<Integer> itemIds);
	}

	/**
	 * "Show this item" pushed from the plugin to a PocketGE tab that is
	 * already open, instead of launching a browser.
	 *
	 * Opening a new tab per chart click is the wrong default when the site
	 * is already up: depending on the desktop's URL handler it can land on
	 * whatever tab happens to be focused, which in practice means it takes
	 * over something else you were watching. If a tab is already polling us
	 * it can just navigate itself.
	 *
	 * {@code seq} keeps rising across plugin restarts (it is seeded from the
	 * clock), so a poller can tell a NEW request from one it already acted
	 * on by remembering the last seq it handled — polling is at-least-once
	 * and the same payload will be seen repeatedly. A tab left open through
	 * a restart remembers the old run's seq, so per-run numbering would put
	 * every new request below it.
	 */
	public static class NavRequest
	{
		public final long seq;
		public final String query;
		public final int itemId;
		public final long at;
		/** The plugin is waiting for the tab that takes this to say so (GET
		 *  /tab/ack), and opens a new tab itself if none does in time. A page
		 *  that sees it must act straight away or not at all — acting after
		 *  the plugin gave up would put the item up twice. */
		public final boolean ack;

		public NavRequest(long seq, String query, int itemId, long at)
		{
			this(seq, query, itemId, at, false);
		}

		public NavRequest(long seq, String query, int itemId, long at, boolean ack)
		{
			this.seq = seq;
			this.query = query;
			this.itemId = itemId;
			this.at = at;
			this.ack = ack;
		}
	}

	/* Injected from the client via the plugin — the hub's verification
	   (correctly) rejects fresh Gson instances. */
	private final Gson gson;
	private HttpServer server;
	/** The port actually bound, which is what a request's Host header has to
	 *  name. Read off the server rather than the setting so port 0 (any free
	 *  port, used by the tests) still has something to check against. */
	private volatile int boundPort;
	/** When a PocketGE page last polled us, epoch millis, 0 for never.
	   Only requests that pass {@link #refusal} reach a handler at all, so a
	   stray curl can't make the plugin believe a tab is open. Written on the
	   bridge's HTTP threads, read from the client thread — hence volatile. */
	private volatile long lastPollAt;
	/** The portfolio's value over time, for GET /portfolio; see
	 *  {@link #setPortfolioSource}. */
	private volatile Supplier<Map<String, Object>> portfolio;

	/** How many requests the bridge will serve at once. Eight covers the
	 *  ordinary traffic (one /flips poll, the odd write) plus a long-poll
	 *  from each of a few tabs, with room to spare on a loopback server that
	 *  never sees real concurrency. */
	private static final int BRIDGE_THREADS = 8;
	/** How long a /nav request parks before answering "nothing yet". Short
	 *  enough to stay inside every proxy and browser idle timeout, long
	 *  enough that the reconnect cost is negligible. It is also how long a
	 *  closed tab's park goes on looking like a listener when its goodbye
	 *  never arrives — which on https://pocketge.com is usual, see
	 *  {@link #handleTabClosed} — so it was cut from 25 seconds. */
	private static final long NAV_WAIT_MS = 10_000;
	private ThreadPoolExecutor navExecutor;
	/** The most recent "show this item" request, or null. Guarded by
	 *  {@link #navLock}, which is also what a parked /nav waits on. */
	private NavRequest nav;
	private final Object navLock = new Object();
	/** Set on stop() so parked requests return instead of waiting out their
	 *  full wait while the plugin is trying to shut down. */
	private volatile boolean stopping;
	/** How many /nav requests are parked right now. */
	private final AtomicInteger parkedNavs = new AtomicInteger();
	/**
	 * Never park more than this many at once — deliberately below
	 * BRIDGE_THREADS.
	 *
	 * The pool rejects with CallerRunsPolicy, and the caller here is the
	 * HttpServer's own dispatcher thread. So a saturated pool would hand a
	 * 25-second park straight to the thread that accepts connections, stalling
	 * every endpoint — precisely the failure the pool was introduced to
	 * prevent, just reached from the other side. Capping the parkers below the
	 * pool size means the pool can never saturate on long-polls, so that
	 * hand-off cannot happen.
	 *
	 * Past the cap a /nav is answered immediately instead of waiting, and the
	 * page asks again a moment later.
	 */
	private static final int MAX_PARKED_NAVS = 4;

	/**
	 * Tabs with a /nav parked right now, by the id each page sends, and tabs
	 * that have said they are closing. Both guarded by {@link #navLock}.
	 *
	 * A closed tab's parked request is invisible from here: the browser drops
	 * the connection, but the handler is asleep on navLock and nothing tells
	 * it. It went on counting as a listener for the rest of its 25 seconds,
	 * so the first chart click after closing the tab was handed to nobody —
	 * and the answer written to that dead connection then counted as a fresh
	 * poll, which covered the next few clicks too. Reported as "it took 4
	 * times doing that for it to finally open a new tab". The page now says
	 * goodbye on its way out (GET /tab/closed), and that wakes its park.
	 */
	private final java.util.Set<String> parkedTabs = new java.util.HashSet<>();
	/** Tab id -> when it said goodbye. Kept for {@link #CLOSED_TAB_MS} after,
	 *  because the browser can send the closed tab's /nav once more on its
	 *  way out, and that request must not park and bring the tab back. */
	private final Map<String, Long> closedTabs = new java.util.LinkedHashMap<>();
	private static final int MAX_CLOSED_TABS = 32;
	private static final long CLOSED_TAB_MS = 10_000;

	/** When a page that can act on a handoff — one running the /nav loop —
	 *  last asked /nav or confirmed a click. {@link #lastPollAt} is any
	 *  PocketGE page at all, and the Flip History page polls /flips without
	 *  ever taking a chart click: counted as a tab, every click with only
	 *  that page open was "sent to your open tab" and went nowhere. */
	private volatile long lastNavPollAt;
	/** When a page last asked /nav saying it confirms what it takes (ack=1). */
	private volatile long confirmingPollAt;
	/** When a page last asked /nav WITHOUT ack=1 — an app.js from before the
	 *  ack, still open in some tab. */
	private volatile long legacyNavPollAt;
	/** Parked /nav requests right now that do, and do not, confirm. A parked
	 *  confirming tab is better evidence than the time it last asked, and it
	 *  cannot be wiped by a timed-out handoff for some other tab. */
	private final AtomicInteger confirmingParks = new AtomicInteger();
	private final AtomicInteger legacyParks = new AtomicInteger();
	/** Told the seq of each request a tab confirms, on the HTTP thread. */
	private volatile java.util.function.LongConsumer ackListener;

	/**
	 * Hand the bridge a chart click to deliver.
	 *
	 * Wakes every parked /nav immediately, which is the entire point: the
	 * site used to learn about this on its next 5-second poll, and a hidden
	 * background tab's timers are throttled well past that. A request that is
	 * already open is not a timer, so it is answered the moment this is
	 * called.
	 */
	public void publishNav(NavRequest request)
	{
		synchronized (navLock)
		{
			nav = request;
			navLock.notifyAll();
		}
	}

	public LocalBridgeServer(Gson gson)
	{
		this.gson = gson;
	}

	/** What GET /portfolio answers: {"points": [[time, value], ...]}. Set
	 *  once at start-up; read on the server's own threads. */
	public void setPortfolioSource(Supplier<Map<String, Object>> source)
	{
		portfolio = source;
	}

	public void start(int port, Supplier<Map<String, Object>> payload, Supplier<Map<String, Object>> history,
		FavoriteWriter favoriteWriter, ListWriter listWriter) throws IOException
	{
		stop();
		server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), port), 0);
		boundPort = server.getAddress().getPort();
		server.createContext("/flips", ex -> handleGet(ex, payload));
		/* Separate from /flips on purpose. /flips is polled every few seconds
		 * forever and carries the recent window; this is the entire ledger,
		 * which is years of trades and megabytes of JSON, and is fetched only
		 * when someone opens the history page. Serving it on the poll would
		 * mean re-serializing the whole history several times a minute to
		 * render eight rows. `flipCount` in /flips is how the page knows when
		 * to come back here. */
		server.createContext("/history", ex -> handleGet(ex, history));
		server.createContext("/status", ex -> handleGet(ex, () -> {
			Map<String, Object> m = new HashMap<>();
			m.put("ok", true);
			m.put("plugin", "pocketge-flip-tracker");
			return m;
		}));
		/* Its own endpoint, like /history: a year of samples is thousands of
		   points and the /flips poll has no use for them. The page asks every
		   few minutes, which is as often as it changes. */
		server.createContext("/portfolio", ex -> handleGet(ex, () ->
		{
			final Supplier<Map<String, Object>> source = portfolio;
			final Map<String, Object> m = source != null ? source.get() : null;
			return m != null ? m : new HashMap<>();
		}));
		server.createContext("/favorites", ex -> handleFavoritePost(ex, favoriteWriter));
		server.createContext("/favoriteLists", ex -> handleFavoriteListsPost(ex, listWriter));
		server.createContext("/nav", this::handleNavLongPoll);
		/* Not under /nav: contexts match by prefix, so an older plugin would
		   route "/nav/…" to the long poll and park a closing tab's goodbye
		   for 25 seconds — the very phantom listener this exists to remove.
		   Under /tab an older plugin answers 404 at once. */
		server.createContext("/tab/ack", this::handleTabAck);
		server.createContext("/tab/closed", this::handleTabClosed);
		/* A REAL pool, not setExecutor(null).
		 *
		 * The default runs every handler on the single thread start() created,
		 * which was fine while every response was immediate — and is fatal now
		 * that /nav parks for up to 25 seconds waiting for a chart click. On
		 * the default executor one parked request would stall /flips, the
		 * favourites writes and the list reorders behind it.
		 *
		 * Capped, because these threads are only ever unblocked by a person
		 * clicking a chart button or a timeout: an unbounded pool would let a
		 * page with a reconnect bug quietly accumulate them. Past the cap a
		 * long-poll is answered immediately instead of queueing, so the site
		 * falls back to its ordinary 5-second poll rather than hanging.
		 *
		 * Daemon threads: this lives inside the RuneLite client and must never
		 * be the reason the JVM stays up. */
		navExecutor = new ThreadPoolExecutor(0, BRIDGE_THREADS, 30L, TimeUnit.SECONDS,
			new SynchronousQueue<>(), r ->
			{
				final Thread t = new Thread(r, "pocketge-bridge");
				t.setDaemon(true);
				return t;
			}, new ThreadPoolExecutor.CallerRunsPolicy());
		server.setExecutor(navExecutor);
		server.start();
	}

	private void handleGet(HttpExchange ex, Supplier<Map<String, Object>> payload) throws IOException
	{
		if (refuse(ex) || corsPreflight(ex, "GET, OPTIONS"))
		{
			return;
		}
		lastPollAt = System.currentTimeMillis();
		byte[] body = gson.toJson(payload.get()).getBytes(StandardCharsets.UTF_8);
		ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
		ex.sendResponseHeaders(200, body.length);
		try (OutputStream os = ex.getResponseBody())
		{
			os.write(body);
		}
	}

	/**
	 * GET /nav?since=N — "tell me the moment a chart is clicked in game".
	 *
	 * Parks until there is a NavRequest newer than {@code since}, or for
	 * {@link #NAV_WAIT_MS}, whichever comes first, then answers
	 * {"navRequest": …} or {"navRequest": null}. The page reconnects
	 * immediately either way.
	 *
	 * Why not just poll faster: the browser tab is behind the game, and a
	 * hidden tab's setInterval is throttled — to once a second at best, and
	 * to once a MINUTE once Chrome's intensive throttling kicks in. Shortening
	 * the interval cannot fix something the browser is deliberately slowing
	 * down. An already-open request is not a timer, so its response is
	 * delivered on the network task source and arrives promptly regardless.
	 *
	 * {@code since} of 0 (or absent) answers with whatever is current, which
	 * is how a freshly loaded page learns the seq it should dedupe from.
	 */
	private void handleNavLongPoll(HttpExchange ex) throws IOException
	{
		if (refuse(ex) || corsPreflight(ex, "GET, OPTIONS"))
		{
			return;
		}
		final long now = System.currentTimeMillis();
		final String query = ex.getRequestURI().getQuery();
		long since = 0;
		try
		{
			final String s = param(query, "since");
			since = s != null ? Long.parseLong(s) : 0;
		}
		catch (RuntimeException ignore)
		{
			since = 0; // unparseable: treat as "tell me what's current"
		}
		/* Both optional, so a page from before them still long-polls. */
		final String tab = tabId(param(query, "tab"));
		final boolean confirms = "1".equals(param(query, "ack"));
		if (tab != null)
		{
			synchronized (navLock)
			{
				final Long goneAt = closedTabs.get(tab);
				if (goneAt != null && now - goneAt < CLOSED_TAB_MS)
				{
					/* The closed tab, once more. Chromium resends a GET whose
					   connection closed before any answer, and a parked request
					   woken by the goodbye was exactly that; parking it again
					   undid the goodbye and the next click waited out the ack
					   timer. Not counted as a poll, either. */
					endQuietly(ex);
					return;
				}
				// Long after: a page the browser kept (back/forward cache) and
				// brought back. Asking again means open again.
				closedTabs.remove(tab);
			}
		}
		// A parked long-poll is still a tab being open — in fact it is
		// better evidence than a 5s tick, since it is continuous.
		lastPollAt = now;
		lastNavPollAt = now;
		if (confirms)
		{
			confirmingPollAt = now;
		}
		else
		{
			legacyNavPollAt = now;
		}

		NavRequest found = null;
		boolean closed = false;
		final long deadline = now + NAV_WAIT_MS;
		final boolean mayPark = parkedNavs.incrementAndGet() <= MAX_PARKED_NAVS;
		final AtomicInteger kind = confirms ? confirmingParks : legacyParks;
		if (mayPark)
		{
			kind.incrementAndGet();
		}
		int left;
		try
		{
		synchronized (navLock)
		{
			if (tab != null && mayPark)
			{
				parkedTabs.add(tab);
			}
			while (!stopping)
			{
				if (tab != null && closedTabs.containsKey(tab))
				{
					closed = true;
					break;
				}
				if (nav != null && nav.seq > since)
				{
					found = nav;
					break;
				}
				if (!mayPark)
				{
					// Too many already waiting — see MAX_PARKED_NAVS. Answer
					// with what we have rather than holding another thread.
					break;
				}
				final long remaining = deadline - System.currentTimeMillis();
				if (remaining <= 0)
				{
					break;
				}
				try
				{
					navLock.wait(remaining);
				}
				catch (InterruptedException e)
				{
					/* Stop waiting and answer with whatever we have. The
					   interrupt flag is deliberately NOT re-asserted: nothing
					   below this runs long enough to need to observe it — the
					   handler writes one small JSON body and returns — and the
					   plugin hub does not permit a plugin to interrupt threads
					   at all, which includes handing the flag back. */
					break;
				}
			}
			if (tab != null && mayPark)
			{
				parkedTabs.remove(tab);
			}
		}
		}
		finally
		{
			if (mayPark)
			{
				kind.decrementAndGet();
			}
			left = parkedNavs.decrementAndGet();
		}
		if (closed)
		{
			/* If that was the last tab, stop believing one is open: the
			   evidence is this tab's own last request, and it would otherwise
			   keep "a tab asked recently" true for a few more clicks sent
			   nowhere. */
			if (left == 0)
			{
				forgetClients(Long.MAX_VALUE);
			}
			endQuietly(ex);
			return;
		}
		/* No lastPollAt here. It used to be refreshed as the park ended, "to
		   keep polling alive as evidence of a tab" — but a park ends the same
		   way whether the tab is there or was closed twenty seconds ago, so
		   this was the plugin vouching for a connection nobody was on. A live
		   tab asks again the moment it reads this, and THAT request is the
		   evidence. */
		final Map<String, Object> body = new HashMap<>();
		body.put("navRequest", found);
		respondJson(ex, body);
	}

	/**
	 * An empty answer, and the connection closed.
	 *
	 * An answer, not just a close: HttpServer keeps an exchange it was never
	 * given a response for in its connection set for good, and Chromium
	 * resends a GET whose reused connection closes before any reply — the
	 * resend is what brought a closed tab straight back.
	 */
	private static void endQuietly(HttpExchange ex)
	{
		try
		{
			ex.getResponseHeaders().set("Connection", "close");
			ex.sendResponseHeaders(204, -1);
		}
		catch (IOException ignore)
		{
			// the other end has gone; nothing to tell it
		}
		ex.close();
	}

	/**
	 * GET /tab/ack?seq=N — "I took request N and I'm showing it".
	 *
	 * What lets the plugin stop guessing. Every signal it has of an open tab
	 * is a proxy — a recent poll, a parked request — and each one can outlive
	 * the tab it stands for: closed, frozen by the browser to save power, put
	 * to sleep. Without this, a handoff to any of those was a chart click that
	 * did nothing. With it, the plugin waits a moment for the word and opens a
	 * new tab when none comes.
	 *
	 * A GET, so the browser sends it without a preflight round trip — it is on
	 * the clock. It changes nothing a foreign page could want: the same
	 * Origin and Host rules apply, and all it can do is stop a tab opening.
	 */
	private void handleTabAck(HttpExchange ex) throws IOException
	{
		if (refuse(ex) || corsPreflight(ex, "GET, OPTIONS"))
		{
			return;
		}
		// A page answering is a page that is there, and one that confirms.
		final long now = System.currentTimeMillis();
		lastPollAt = now;
		lastNavPollAt = now;
		confirmingPollAt = now;
		long seq = -1;
		try
		{
			final String s = param(ex.getRequestURI().getQuery(), "seq");
			seq = s != null ? Long.parseLong(s) : -1;
		}
		catch (RuntimeException ignore)
		{
			seq = -1;
		}
		final java.util.function.LongConsumer listener = ackListener;
		if (seq > 0 && listener != null)
		{
			listener.accept(seq);
		}
		ex.sendResponseHeaders(204, -1);
		ex.close();
	}

	/**
	 * GET /tab/closed?tab=ID — sent by a page as it goes away.
	 *
	 * See {@link #parkedTabs}: a closed tab's parked /nav cannot be seen from
	 * this side, and it went on counting as an open tab until its wait ran
	 * out. This wakes it so it stops counting.
	 *
	 * Best effort, and on the live site usually not delivered: the page sends
	 * it from pagehide as a keepalive fetch, and Chrome's Local Network Access
	 * check does not let one from https://pocketge.com reach 127.0.0.1 once
	 * the page is unloading. A browser that is killed sends nothing either.
	 * The ack wait is what actually guarantees a click is not lost; this only
	 * saves it the wait when it does arrive.
	 */
	private void handleTabClosed(HttpExchange ex) throws IOException
	{
		if (refuse(ex) || corsPreflight(ex, "GET, OPTIONS"))
		{
			return;
		}
		final String tab = tabId(param(ex.getRequestURI().getQuery(), "tab"));
		if (tab != null)
		{
			final boolean hadPark;
			synchronized (navLock)
			{
				hadPark = parkedTabs.contains(tab);
				// Kept even with nothing parked: its /nav may still be on the way.
				closedTabs.put(tab, System.currentTimeMillis());
				while (closedTabs.size() > MAX_CLOSED_TABS)
				{
					final java.util.Iterator<String> oldest = closedTabs.keySet().iterator();
					oldest.next();
					oldest.remove();
				}
				if (hadPark)
				{
					navLock.notifyAll();
				}
			}
			// Between two of its polls, with nothing parked: if nothing else
			// is parked either, this was the last tab. (With a park, the woken
			// handler makes this call once it has let go.)
			if (!hadPark && parkedNavs.get() == 0)
			{
				forgetClients(Long.MAX_VALUE);
			}
		}
		ex.sendResponseHeaders(204, -1);
		ex.close();
	}

	/** One query parameter's raw value, or null. */
	static String param(String query, String name)
	{
		if (query == null)
		{
			return null;
		}
		final String key = name + "=";
		for (String part : query.split("&"))
		{
			if (part.startsWith(key))
			{
				return part.substring(key.length());
			}
		}
		return null;
	}

	/** A tab id as the page mints it — digits and dashes — or null. Anything
	 *  else is not one of ours and is not kept. */
	static String tabId(String raw)
	{
		return raw != null && !raw.isEmpty() && raw.length() <= 64 && raw.matches("[0-9-]+") ? raw : null;
	}

	private void respondJson(HttpExchange ex, Map<String, Object> body) throws IOException
	{
		final byte[] bytes = gson.toJson(body).getBytes(StandardCharsets.UTF_8);
		ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
		ex.sendResponseHeaders(200, bytes.length);
		try (OutputStream os = ex.getResponseBody())
		{
			os.write(bytes);
		}
	}

	/** POST { "id": 123, "name": "Diamond", "remove": false, "listId": "…" }
	 *  — adds (or removes) a favorite the same way the in-game star button
	 *  does. listId is optional: omit it to target whichever list is
	 *  currently active in-game. A malformed body is answered with 400
	 *  rather than silently ignored, so a website-side bug is visible
	 *  instead of just "didn't sync". */
	private void handleFavoritePost(HttpExchange ex, FavoriteWriter favoriteWriter) throws IOException
	{
		if (refuse(ex) || corsPreflight(ex, "GET, POST, OPTIONS"))
		{
			return;
		}
		if (!"POST".equalsIgnoreCase(ex.getRequestMethod()))
		{
			ex.sendResponseHeaders(405, -1);
			ex.close();
			return;
		}
		try
		{
			final JsonObject o = readJsonBody(ex);
			final int id = o.get("id").getAsInt();
			final String name = o.has("name") && !o.get("name").isJsonNull() ? o.get("name").getAsString() : ("Item " + id);
			final boolean remove = o.has("remove") && o.get("remove").getAsBoolean();
			final String listId = o.has("listId") && !o.get("listId").isJsonNull() ? o.get("listId").getAsString() : null;
			favoriteWriter.write(listId, id, name, remove);
			respondOk(ex);
		}
		catch (Exception e)
		{
			ex.sendResponseHeaders(400, -1);
			ex.close();
		}
	}

	/** POST { "action": "create"|"rename"|"delete"|"reorder", "listId": "…",
	 *  "name": "…", "itemIds": [1601, 561, …] }
	 *  — drives the same list chip-menu actions (new list / rename / delete)
	 *  the in-game panel offers, from the website. "create" only needs
	 *  name; "rename" needs both; "delete" only needs listId. Responds with
	 *  { "ok": true, "listId": "…" } — for "create" that's the new list's id,
	 *  so the site can switch straight to it without a round trip. */
	private void handleFavoriteListsPost(HttpExchange ex, ListWriter listWriter) throws IOException
	{
		if (refuse(ex) || corsPreflight(ex, "GET, POST, OPTIONS"))
		{
			return;
		}
		if (!"POST".equalsIgnoreCase(ex.getRequestMethod()))
		{
			ex.sendResponseHeaders(405, -1);
			ex.close();
			return;
		}
		try
		{
			final JsonObject o = readJsonBody(ex);
			final String action = o.get("action").getAsString();
			String resultListId = null;
			switch (action)
			{
				case "create":
				{
					final String name = o.get("name").getAsString();
					if (name == null || name.trim().isEmpty())
					{
						throw new IllegalArgumentException("blank list name");
					}
					resultListId = listWriter.create(name.trim());
					break;
				}
				case "rename":
				{
					final String name = o.get("name").getAsString();
					if (name == null || name.trim().isEmpty())
					{
						throw new IllegalArgumentException("blank list name");
					}
					listWriter.rename(o.get("listId").getAsString(), name.trim());
					break;
				}
				case "delete":
					listWriter.delete(o.get("listId").getAsString());
					break;
				case "reorder":
				{
					final com.google.gson.JsonArray arr = o.getAsJsonArray("itemIds");
					final List<Integer> ids = new java.util.ArrayList<>();
					for (int i = 0; i < arr.size(); i++)
					{
						ids.add(arr.get(i).getAsInt());
					}
					if (ids.isEmpty())
					{
						throw new IllegalArgumentException("empty itemIds");
					}
					listWriter.reorder(o.has("listId") && !o.get("listId").isJsonNull()
						? o.get("listId").getAsString() : null, ids);
					break;
				}
				default:
					throw new IllegalArgumentException("unknown action: " + action);
			}
			ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
			final JsonObject resp = new JsonObject();
			resp.addProperty("ok", true);
			if (resultListId != null)
			{
				resp.addProperty("listId", resultListId);
			}
			final byte[] body = gson.toJson(resp).getBytes(StandardCharsets.UTF_8);
			ex.sendResponseHeaders(200, body.length);
			try (OutputStream os = ex.getResponseBody())
			{
				os.write(body);
			}
		}
		catch (Exception e)
		{
			ex.sendResponseHeaders(400, -1);
			ex.close();
		}
	}

	private JsonObject readJsonBody(HttpExchange ex) throws IOException
	{
		final ByteArrayOutputStream buf = new ByteArrayOutputStream();
		try (InputStream is = ex.getRequestBody())
		{
			is.transferTo(buf);
		}
		return gson.fromJson(buf.toString(StandardCharsets.UTF_8), JsonObject.class);
	}

	private void respondOk(HttpExchange ex) throws IOException
	{
		ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
		final byte[] body = "{\"ok\":true}".getBytes(StandardCharsets.UTF_8);
		ex.sendResponseHeaders(200, body.length);
		try (OutputStream os = ex.getResponseBody())
		{
			os.write(body);
		}
	}

	/**
	 * Why a request may not be served, or null when it may.
	 *
	 * This is the bridge's whole access check, and it runs before every
	 * handler. It used to be advisory: a request from any other origin, or a
	 * plain curl with no Origin at all, was answered in full — CORS only
	 * stopped a foreign page READING the reply, so a POST from any site open
	 * in the same browser still landed and edited your lists. Three rules:
	 *
	 * <ul>
	 * <li><b>Origin</b> must be a PocketGE page. A browser always sends it on
	 * the site's cross-origin fetches, so its absence means the request did
	 * not come from the site.</li>
	 * <li><b>Host</b> must be this loopback address and port. A page that
	 * re-points its own hostname at 127.0.0.1 (DNS rebinding) sends its own
	 * hostname here, and is refused on that even before its Origin.</li>
	 * <li><b>POST bodies</b> must be declared as JSON. The site always does,
	 * and a JSON content type is what forces the browser to ask permission
	 * (the preflight) before sending a write at all.</li>
	 * </ul>
	 *
	 * Static and pure so every rule can be tested without a socket.
	 */
	static String refusal(String method, String origin, String host, String contentType, int port)
	{
		if (!isAllowedHost(host, port))
		{
			return "host";
		}
		if (!isAllowedOrigin(origin))
		{
			return "origin";
		}
		if ("POST".equalsIgnoreCase(method)
			&& (contentType == null || !contentType.toLowerCase(java.util.Locale.ROOT).startsWith("application/json")))
		{
			return "content-type";
		}
		return null;
	}

	/** Answer a refused request and report whether it was one. 403 for a
	 *  foreign host or origin, 415 for a write that is not JSON. No CORS
	 *  headers either way, so a foreign page cannot read the reason. */
	private boolean refuse(HttpExchange ex) throws IOException
	{
		final String why = refusal(ex.getRequestMethod(),
			ex.getRequestHeaders().getFirst("Origin"),
			ex.getRequestHeaders().getFirst("Host"),
			ex.getRequestHeaders().getFirst("Content-Type"),
			boundPort);
		if (why == null)
		{
			return false;
		}
		ex.sendResponseHeaders("content-type".equals(why) ? 415 : 403, -1);
		ex.close();
		return true;
	}

	private static boolean isAllowedHost(String host, int port)
	{
		if (host == null)
		{
			return false;
		}
		final String h = host.trim().toLowerCase(java.util.Locale.ROOT);
		return h.equals("127.0.0.1:" + port) || h.equals("localhost:" + port) || h.equals("[::1]:" + port);
	}

	private static boolean isAllowedOrigin(String origin)
	{
		if (origin == null)
		{
			return false;
		}
		for (String o : ALLOWED_ORIGINS)
		{
			if (o.equals(origin))
			{
				return true;
			}
		}
		return false;
	}

	/** CORS headers for an origin {@link #refusal} has already accepted, and
	 *  the whole answer to an OPTIONS preflight. Returns true if the exchange
	 *  was fully handled here and the caller should stop. */
	private boolean corsPreflight(HttpExchange ex, String allowedMethods) throws IOException
	{
		ex.getResponseHeaders().set("Access-Control-Allow-Origin", ex.getRequestHeaders().getFirst("Origin"));
		ex.getResponseHeaders().set("Vary", "Origin");
		if ("OPTIONS".equalsIgnoreCase(ex.getRequestMethod()))
		{
			ex.getResponseHeaders().set("Access-Control-Allow-Methods", allowedMethods);
			/* Named rather than "*": Content-Type is the only header the
			   site sends, and it is the one the JSON rule above depends on. */
			ex.getResponseHeaders().set("Access-Control-Allow-Headers", "Content-Type");
			/* Chromium Private Network Access: an https page fetching a
			   private address must be explicitly allowed. */
			ex.getResponseHeaders().set("Access-Control-Allow-Private-Network", "true");
			ex.sendResponseHeaders(204, -1);
			ex.close();
			return true;
		}
		return false;
	}

	/** The port the server is listening on, or 0 when it is not running. */
	int port()
	{
		return server != null ? boundPort : 0;
	}

	/** Epoch millis of the last poll from a PocketGE page, 0 for never. */
	public long lastPollAt()
	{
		return lastPollAt;
	}

	/** Best available answer to "is a PocketGE tab open right now". It is a
	 *  proxy, not a fact: the page polls on a timer, so this stays true for
	 *  up to one poll interval after the tab is closed. Callers must degrade
	 *  gracefully when a handoff turns out to have no one listening. */
	public boolean hasRecentClient(long withinMs)
	{
		final long seen = lastPollAt;
		return seen > 0 && System.currentTimeMillis() - seen <= withinMs;
	}

	/**
	 * Whether a page is parked on /nav RIGHT NOW, waiting to be handed an
	 * item.
	 *
	 * Much stronger evidence of a usable tab than {@link #hasRecentClient}:
	 * that one says a page polled at some point in the last N seconds, which
	 * stays true for a tab closed moments ago and for one the browser has
	 * since frozen in the background.
	 *
	 * Stronger, not proof. A parked request looks exactly the same from here
	 * after its tab is closed, because the browser hanging up does not wake
	 * it — hence the page's goodbye (/tab/closed) and, for a tab that could
	 * not send one, the plugin waiting for an ack before trusting a handoff.
	 */
	public boolean hasParkedNavListener()
	{
		return parkedNavs.get() > 0;
	}

	/**
	 * Whether a page that can take a handoff — one running the /nav loop —
	 * is there: one is parked right now, or one asked within {@code withinMs}.
	 * Polls of /flips alone do not count; see {@link #lastNavPollAt}.
	 */
	public boolean hasNavListener(long withinMs)
	{
		if (parkedNavs.get() > 0)
		{
			return true;
		}
		final long seen = lastNavPollAt;
		return seen > 0 && System.currentTimeMillis() - seen <= withinMs;
	}

	/**
	 * Whether the plugin should wait for a tab to confirm a click.
	 *
	 * Yes when a confirming page is parked now, or asked within one
	 * long-poll cycle. No while any page that CANNOT confirm — an app.js from
	 * before the ack, still open in a tab — is listening: if that one took
	 * the click it would show the item and say nothing, the wait would run
	 * out, and the item would open a second time in a new tab.
	 */
	public boolean hasConfirmingListener()
	{
		final long now = System.currentTimeMillis();
		final long window = NAV_WAIT_MS + 5_000;
		final long legacy = legacyNavPollAt;
		if (legacyParks.get() > 0 || (legacy > 0 && now - legacy <= window))
		{
			return false;
		}
		if (confirmingParks.get() > 0)
		{
			return true;
		}
		final long at = confirmingPollAt;
		return at > 0 && now - at <= window;
	}

	/** Who to tell when a tab confirms a request. Called on the bridge's HTTP
	 *  thread. */
	public void setAckListener(java.util.function.LongConsumer listener)
	{
		this.ackListener = listener;
	}

	/**
	 * Stop believing a tab is open, until one asks again — going only on
	 * what was seen up to {@code before}.
	 *
	 * For when the evidence has just been shown wrong: the last tab said it
	 * was closing, or a handoff went unconfirmed. A tab that IS still there
	 * asks again within one poll and is believed again from then on, so the
	 * cost of being wrong here is one click opening a new tab — which is
	 * visible — instead of one going nowhere.
	 */
	public void forgetClients(long before)
	{
		/* Only evidence from before {@code before}. A timed-out handoff used to
		   wipe everything, including a tab that had asked again after the
		   click — and the next click, seeing no confirming tab, skipped the
		   wait and could be sent nowhere. */
		if (lastPollAt <= before)
		{
			lastPollAt = 0;
		}
		if (lastNavPollAt <= before)
		{
			lastNavPollAt = 0;
		}
		if (confirmingPollAt <= before)
		{
			confirmingPollAt = 0;
		}
		if (legacyNavPollAt <= before)
		{
			legacyNavPollAt = 0;
		}
	}

	public void stop()
	{
		/* Wake the parked long-polls FIRST. server.stop(0) waits for handlers
		   to finish, and a /nav sitting on a 25-second timer would hold the
		   plugin's shutdown for as long as it had left to run. */
		stopping = true;
		synchronized (navLock)
		{
			navLock.notifyAll();
		}
		if (server != null)
		{
			server.stop(0);
			server = null;
		}
		if (navExecutor != null)
		{
			/* shutdown(), never shutdownNow(): the latter interrupts the pool's
			   threads, which a hub plugin may not do. It is also unnecessary
			   here — the notifyAll above, paired with the stopping flag the
			   wait loop tests, has already released every parked request, so
			   there is nothing left to interrupt. shutdown() does not block. */
			navExecutor.shutdown();
			navExecutor = null;
		}
		// Re-arm: start() can be called again when the setting is toggled back on.
		stopping = false;
		nav = null;
		synchronized (navLock)
		{
			parkedTabs.clear();
			closedTabs.clear();
		}
		/* All of it, lastPollAt included: with the server down, a click within
		   a few seconds of the last poll was still "sent to your open tab". */
		forgetClients(Long.MAX_VALUE);
	}

	/**
	 * One stack sitting in the bank, priced. The bridge used to publish a
	 * single portfolioValue total, so the website could show what you were
	 * worth but never what you were HOLDING — which is the half you act on.
	 * Cash is excluded (it arrives as its own `cash` field); an unpriced item
	 * carries value 0 rather than being dropped, so the composition stays
	 * honest about what it couldn't value.
	 */
	public static class BankStack
	{
		public final int id;
		public final String name;
		public final int quantity;
		public final long value; // quantity x current insta-sell, 0 if unpriced

		public BankStack(int id, String name, int quantity, long value)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
			this.value = value;
		}
	}

	/** Build the /flips payload from tracker + panel state. Static so the
	 *  plugin can also reuse it for future export features.
	 *  {@code favoriteLists} / {@code topRecommendation} are whatever was
	 *  most recently loaded/rendered — null/empty degrades cleanly, matching
	 *  how the website already treats "advisor off" or "no favorites yet".
	 *  favoriteLists carries every list's raw id/name/color/items (not
	 *  resolved prices — the website already fetches live prices itself and
	 *  only needs to know which items belong to which list). */
	public static Map<String, Object> payload(long sessionProfit, long lifetimeProfit, List<Flip> flips, List<TradeFill> fills,
		long portfolioValue, boolean bankSeen, long bankSeenAt, long cash, List<BankStack> bankStacks,
		List<FavoriteLists.FavoriteList> favoriteLists, String activeFavoriteListId, Advisor.Suggestion topRecommendation)
	{
		Map<String, Object> m = new HashMap<>();
		m.put("sessionProfit", sessionProfit);
		m.put("lifetimeProfit", lifetimeProfit);
		m.put("flips", flips);
		m.put("fills", fills);
		m.put("portfolioValue", portfolioValue);
		/* False until the player has opened their bank at least once this
		   session — RuneLite can't read bank contents any other way, so
		   portfolioValue silently excludes it until then. The website uses
		   this to say so instead of just showing a too-low total.
		   bankSeenAt (epoch millis, 0 for never) says HOW STALE that snapshot
		   is: "seen" alone can't distinguish a bank read ten seconds ago from
		   one read three hours and forty trades ago, and the site was
		   presenting both as equally current. */
		m.put("bankSeen", bankSeen);
		m.put("bankSeenAt", bankSeenAt);
		m.put("cash", cash);
		m.put("bankStacks", bankStacks);
		m.put("favoriteLists", favoriteLists);
		m.put("activeFavoriteListId", activeFavoriteListId);
		m.put("topRecommendation", topRecommendation);
		m.put("generatedAt", System.currentTimeMillis());
		return m;
	}
}

