	private final Map<Integer, Long> geSeriesAttemptAt = new java.util.concurrent.ConcurrentHashMap<>();
	private static final long GE_SERIES_RETRY_MS = 60_000;
	private volatile Map<Integer, Long> lastVolumes = new HashMap<>();
	private volatile Map<Integer, AnalystRating.Average> lastAverages = new HashMap<>();
	/** Recent price history for items with an active GE offer, feeding
	 *  TradeEngine so ADJUST_BUY/ADJUST_SELL suggestions reprice to the same
	 *  target pocketge.com would show, not just the raw live quote (see
	 *  refreshOfferSeries). Keyed by item id, at most one entry per GE slot. */
	private volatile Map<Integer, TradeEngine.Series> lastOfferSeries = new HashMap<>();
	/** Item ids with an active offer as of the last recomputeAdvice() —
	 *  offer state needs the client thread, so refreshOfferSeries() (a
	 *  background fetch) works off this rather than reading offers itself;
	 *  a newly-placed offer's reprice target uses the raw live quote for
	 *  one advisor cycle before this catches up. */
	private volatile Set<Integer> lastActiveOfferItemIds = new HashSet<>();
	/** Items the capital plan recommended last cycle, so their price series
	 *  get fetched and the headline BUY card can be priced by the engine
	 *  rather than off the raw spread. See refreshOfferSeries. */
	private volatile Set<Integer> lastPlanItemIds = new HashSet<>();
	/**
	 * The items the sidebar is currently offering to sell — folded into
	 * refreshOfferSeries()'s fetch set (like lastActiveOfferItemIds) so their
	 * asking prices come from TradeEngine rather than the raw live quote.
	 *
	 * This was ONE item: whichever SELL Advisor.advise() ranked first. But
	 * the sidebar does not show one sell, it shows the whole ranked stack and
	 * lets you page through it — so card 1 was priced by the engine and cards
	 * 2..n were priced off the last insta-buy print. That is the same "quote
	 * the actively-traded price and call it a target" mistake the GE-context
	 * path had to be talked out of, and it left two cards in one list built by
	 * two different methods with nothing on either saying which you got.
	 *
	 * Bounded like lastPlanItemIds — a GE board's worth, taken in rank order,
	 * because the cost is one /timeseries call per item per advisor cycle.
	 * Past that the cards fall back to the raw print as before.
	 */
	private volatile Set<Integer> lastSellItemIds = new HashSet<>();
	/**
	 * The first few flip ideas on the list — the Advisor buys queued behind
	 * the capital plan — so the engine can confirm or re-price them the way
	 * it does the plan's own cards. Their comment always said they were
	 * "engine-confirmed on the same terms", but nothing ever fetched their
	 * series, so every one showed the raw last-print spread. That mattered
	 * less while they sat behind twenty sells; with flips first they are
	 * pages two to five.
	 */
	private volatile Set<Integer> lastIdeaItemIds = new HashSet<>();
	/** How many ideas get that. One /timeseries per item, cached like the rest. */
	static final int IDEA_SERIES_CAP = 4;
	/** How many of the best sells keep a place at the end of the list when
	 *  flips lead — enough that the stacks worth selling are still a few
	 *  clicks away, few enough that they cannot crowd the flips out. */
	static final int SELLS_KEPT_BEHIND_FLIPS = 5;

	/**
	 * Put the buy and sell cards in the order you page through them, after
	 * whatever {@code out} already holds (the adjust nudges on a full board).
	 *
	 * New flips lead whenever there is a real one: a buy that clears the
	 * profit floor — yours, or the planner's own 2,000 gp. The best few sells
	 * keep places at the end.
	 *
	 * It used to compare the gold the best buy would DEPLOY with the gold the
	 * best sell would RAISE and put the bigger first. That was there for a
	 * real report — down to 344 gp, "Buy 40 Lobster pot for 1 gp ea" sat in
	 * front of a bank worth millions — but it meant anyone holding stock
	 * worth more than their cash was told to sell first, every time, however
	 * much they had free to flip with. 2,910 Mithril bars kept for use put
	 * twenty "sell from your bank" cards ahead of every flip: "i keep finding
	 * myself clicking 15 pages back just to find 5 recommended flips". The
	 * floor still handles the Lobster pot: a 344 gp purse cannot clear it,
	 * so with no real flip on offer the sells lead as before.
	 */
	static void orderRecommendations(List<AdvisorPanel.Rec> out, List<AdvisorPanel.Rec> buys,
		List<AdvisorPanel.Rec> sells, long leadFloor, int max)
	{
		boolean realFlip = false;
		for (AdvisorPanel.Rec b : buys)
		{
			if (b.profit >= leadFloor)
			{
				realFlip = true;
				break;
			}
		}
		final List<AdvisorPanel.Rec> first = realFlip ? buys : sells;
		/* Behind the flips, the sells for stock the plugin watched you buy
		   come first. The ranking puts a stack it knows nothing about at its
		   whole sale value but a tracked one at only its profit, so five big
		   stacks held from before could take every kept place and push out
		   the second half of a flip you are actually in. Rank order holds
		   within each group. */
		final List<AdvisorPanel.Rec> second;
		if (realFlip)
		{
			second = new ArrayList<>(sells.size());
			for (AdvisorPanel.Rec r : sells)
			{
				if (r.hasTrackedCost)
				{
					second.add(r);
				}
			}
			for (AdvisorPanel.Rec r : sells)
			{
				if (!r.hasTrackedCost)
				{
					second.add(r);
				}
			}
		}
		else
		{
			second = buys;
		}
		final int room = Math.max(0, max - out.size());
		/* Places held back for the sells only. With no real flip the buys on
		   offer are the Lobster-pot kind, and they get whatever room is left. */
		final int kept = realFlip ? Math.min(second.size(), SELLS_KEPT_BEHIND_FLIPS) : 0;
		final int firstCount = Math.min(first.size(), Math.max(0, room - kept));
		out.addAll(first.subList(0, firstCount));
		for (AdvisorPanel.Rec r : second)
		{
			if (out.size() >= max)
			{
				break;
			}
			out.add(r);
		}
	}

	/** How many of the ranked sell cards get an engine-priced ask. See above. */
	static final int SELL_SERIES_CAP = 8;

	/**
	 * Which of the sell cards get a price series fetched for the next cycle.
	 *
	 * Rank order and capped, because sellRecs runs to MAX_RECOMMENDATIONS and
	 * every id here is one more /timeseries call per advisor cycle. The cards
	 * past the cap keep the old behaviour — priced off the raw print — which
	 * is a worse answer but not a wrong one, and they are the ones you have
	 * to page a long way to reach.
	 */
	static Set<Integer> sellSeriesIds(List<AdvisorPanel.Rec> sellRecs)
	{
		return sellSeriesIds(sellRecs, sellRecs, java.util.Collections.emptySet());
	}

	/**
	 * As above, keeping {@code had} — the last round's — for any still among
	 * {@code candidates}, every sell there is a card for whether or not it
	 * made the list, up to SELL_SERIES_STICKY past the cap.
	 *
	 * Not only the listed ones: with a real flip leading, five sells are
	 * listed, and a stack its series pushed from fifth to sixth was off the
	 * list, lost the series and came straight back — the same flip-flop at
	 * the list's edge.
	 *
	 * A series can lower a sell's price now (the website's Target Sell, not
	 * raised to the insta-buy), and so its rank. Taken by rank alone, a
	 * stack at eighth got its series, priced lower, fell to ninth, lost it,
	 * priced at the insta-buy again and climbed back: one stack flipping
	 * between two prices every advisor round.
	 */
	static Set<Integer> sellSeriesIds(List<AdvisorPanel.Rec> sellRecs, List<AdvisorPanel.Rec> candidates,
		Set<Integer> had)
	{
		final Set<Integer> ids = new LinkedHashSet<>();
		for (AdvisorPanel.Rec r : sellRecs)
		{
			if (ids.size() >= SELL_SERIES_CAP)
			{
				break;
			}
			ids.add(r.itemId);
		}
		for (AdvisorPanel.Rec r : candidates)
		{
			if (ids.size() >= SELL_SERIES_CAP + SELL_SERIES_STICKY)
			{
				break;
			}
			if (had.contains(r.itemId))
			{
				ids.add(r.itemId);
			}
		}
		return ids;
	}

	/** How many past the cap keep the series they had. */
	static final int SELL_SERIES_STICKY = 4;
	/** The watchlist item the inspection card is currently showing, or null.
	 *  Its price series is fetched on demand — see onSelectedItemChanged. */
	private volatile Integer selectedFavoriteItemId = null;
	/** Name of {@link #selectedFavoriteItemId}, needed to build its Row when
	 *  the item is not in any favourites list (a Find Opportunities pick). */
	private volatile String selectedFavoriteName = null;
	/**
	 * Price series fetched ON DEMAND rather than on the advisor cycle: the
	 * watchlist item being inspected, and whatever item a GE offer screen was
	 * just opened for.
	 *
	 * Kept apart from lastOfferSeries because that map is rebuilt wholesale
	 * every cycle, which would drop an on-demand fetch moments after it
	 * landed.
	 *
	 * And the sell cards paged to — see noteShownCard — which is why it is a
	 * card list's worth: cards past SELL_SERIES_CAP live only here.
	 *
	 * Bounded: past the cap the oldest fetched go first, never one on screen
	 * now (the inspected item, the open offer, the sell card shown). It used
	 * to start fresh at the cap, which was cheap while only a click or an
	 * offer screen put anything in; paging through a dozen sells then wiped
	 * the series of every card already priced, and a card paged back to
	 * within the minute could not ask again.
	 */
	private volatile Map<Integer, TradeEngine.Series> selectedSeries = new HashMap<>();
	private static final int ON_DEMAND_SERIES_CAP = 24;
	/** How long an on-demand series may price the cards — three 5-minute
	 *  buckets. See recomputeAdvice. */
	static final long ON_DEMAND_SERIES_MAX_AGE_MS = 15 * 60 * 1000L;

	/**
	 * The series every surface prices a held stack from — the sell cards,
	 * the bank marks and stack hovers, the watchlist rows and inspect card,
	 * the header's Unrealized and the portfolio total — so they cannot read
	 * one stack two ways. The advisor round's copy, or an on-demand one
	 * while it is recent or its item is on screen (recentSeries), whichever
	 * is newer.
	 *
	 * The rows and the header used to take seriesFor, which keeps an
	 * on-demand series with no age bound, while the cards dropped it after
	 * fifteen minutes: Astral runes paged past an hour ago still read 126
	 * on the watchlist row beside a hover back at 114.
	 */
	private Map<Integer, TradeEngine.Series> pricingSeries(long now)
	{
		/* The items in an active offer count as on screen: their slots are,
		   and a slot's "if it flips" prices from seriesFor at any age. On the
		   long intervals the round's copy is hours old and a top-up from the
		   offer screen newer; the cards dropped the top-up at fifteen minutes
		   and called the bid "losing" against the live print while the slot
		   under it said "+100K if it flips". */
		final Set<Integer> onScreen = new HashSet<>(lastActiveOfferItemIds);
		for (Integer id : new Integer[]{geContextItemId, selectedFavoriteItemId})
		{
			if (id != null)
			{
				onScreen.add(id);
			}
		}
		/* The card on screen, and the cards ahead of it, keep the series they
		   are priced from — but only that: one the cards had already dropped
		   when it was paged back to is not brought back by the next rebuild,
		   which repriced the card minutes into reading it (exit 1990, then
		   1998, no market move). The offer screen and the picked item are
		   rebuilt onto theirs as they are shown (syncCardsTo); a card is not,
		   and a sell card asks afresh instead (noteShownCard), as the cards
		   ahead are asked for (noteCardsAhead). */
		final List<Integer> cards = new ArrayList<>(cardsAheadIds);
		cards.add(shownCardItemId);
		for (Integer id : cards)
		{
			if (id != null && cardsSeries.get(id) == selectedSeries.get(id))
			{
				onScreen.add(id);
			}
		}
		final Map<Integer, TradeEngine.Series> out = recentSeries(selectedSeries, selectedSeriesFetchedAt, now, onScreen);
		for (Map.Entry<Integer, TradeEngine.Series> e : lastOfferSeries.entrySet())
		{
			final Long pickedAt = out.containsKey(e.getKey()) ? selectedSeriesFetchedAt.get(e.getKey()) : null;
			final Long offerAt = offerSeriesFetchedAt.get(e.getKey());
			if (pickedAt == null || (offerAt != null && offerAt >= pickedAt))
			{
				out.put(e.getKey(), e.getValue());
			}
		}
		return out;
	}

	/** The series in {@code held} fetched no longer than
	 *  ON_DEMAND_SERIES_MAX_AGE_MS before {@code now}, by {@code fetchedAt} —
	 *  and those of {@code onScreen}, whatever their age. An item on screen
	 *  is not "shown again" to ask afresh: a sell card left up past the bound
	 *  went back to the raw print while it was being read, and on the long
	 *  advisor intervals stayed there until the next round. */
	static Map<Integer, TradeEngine.Series> recentSeries(Map<Integer, TradeEngine.Series> held,
		Map<Integer, Long> fetchedAt, long now, java.util.Collection<Integer> onScreen)
	{
		final Map<Integer, TradeEngine.Series> out = new HashMap<>();
		for (Map.Entry<Integer, TradeEngine.Series> e : held.entrySet())
		{
			final Long at = fetchedAt.get(e.getKey());
			if (onScreen.contains(e.getKey()) || (at != null && now - at <= ON_DEMAND_SERIES_MAX_AGE_MS))
			{
				out.put(e.getKey(), e.getValue());
			}
		}
		return out;
	}

	/** When each on-demand series was fetched. Executor thread writes. */
	private final Map<Integer, Long> selectedSeriesFetchedAt = new java.util.concurrent.ConcurrentHashMap<>();

	/** Add one on-demand series without letting the map grow unbounded. */
	private void cacheOnDemandSeries(int itemId, TradeEngine.Series series)
	{
		final Map<Integer, TradeEngine.Series> m = new HashMap<>(selectedSeries);
		m.put(itemId, series);
		selectedSeriesFetchedAt.put(itemId, System.currentTimeMillis());
		while (m.size() > ON_DEMAND_SERIES_CAP)
		{
			Integer oldest = null;
			long oldestAt = Long.MAX_VALUE;
			for (Integer id : m.keySet())
			{
				if (id == itemId || id.equals(selectedFavoriteItemId) || id.equals(geContextItemId)
					|| id.equals(shownCardItemId) || cardsAheadIds.contains(id))
				{
					continue;
				}
				final long at = selectedSeriesFetchedAt.getOrDefault(id, 0L);
				if (at < oldestAt)
				{
					oldestAt = at;
					oldest = id;
				}
			}
			if (oldest == null)
			{
				break;
			}
			m.remove(oldest);
		}
		selectedSeries = m;
		selectedSeriesFetchedAt.keySet().retainAll(m.keySet());
		/* Every on-demand series lands here — the offer screen's, the
		   chart's, a watchlist click's, a sell card's own — so this is where
		   the cards, the bank marks and the stack hovers take it up, whoever
		   asked. Rebuilding only for the sell card on screen left the hover
		   over a stack at the live print while the inspect card beside it,
		   priced from the series just fetched, said otherwise: Astral runes
		   "25,000 at 114 gp each" under a card at 126 and +375K. One
		   rebuild per fetch, and every fetch here is something the player
		   did. */
		rebuildCards.run();
	}

	/** The price history for one item, from either bounded cache — the
	 *  newer when both hold it, since the offer-screen chart refreshes an
	 *  open offer's series between advisor cycles. Null when neither has
	 *  it, in which case callers fall back to the raw live quote. */
	private TradeEngine.Series seriesFor(int itemId)
	{
		final TradeEngine.Series offer = lastOfferSeries.get(itemId);
		final TradeEngine.Series picked = selectedSeries.get(itemId);
		if (offer == null || picked == null)
		{
			return offer != null ? offer : picked;
		}
		final Long offerAt = offerSeriesFetchedAt.get(itemId);
		final Long pickedAt = selectedSeriesFetchedAt.get(itemId);
		return pickedAt != null && (offerAt == null || pickedAt > offerAt) ? picked : offer;
	}

	/**
	 * Rebuild the cards when {@code itemId} — the offer screen's item, or the
	 * one picked in the sidebar — is shown from a series they did not price
	 * it from. Not twice for the same series while the cards stay as they
	 * were: a rebuild that cannot run is not asked for on every re-read, and
	 * one that did run is free to be asked again. With the advisor off,
	 * nothing — see screenSeries.
	 *
	 * The offer screen prices from seriesFor; everything else — the buy and
	 * sell cards, the slots' "if it flips", bank marks, hovers, rows, the
	 * inspect card and the header — from the cards' map, which drops an
	 * on-demand series past fifteen minutes unless its item is on screen. A
	 * screen opened on a forty-minute-old series quoted 1998 beside cards at
	 * 1990, and a refused refetch left it so until the next round; a pick
	 * did the same between its inspect card and the buy card it came from.
	 * Rebuilt now, with the item on screen (recentSeries), the cards take
	 * the same series, and any later rebuild while it stays there does too:
	 * one number wherever it is shown, whether the refetch lands or not.
	 * Pricing the screen from the cards' map instead only moved the split —
	 * to the buy cards, and to the next rebuild.
	 *
	 * The guard used to be the item and series alone, never cleared: back out
	 * of a screen, let the cards rebuild without it, open it again on the
	 * same old series, and the split was back for good.
	 */
	void syncCardsTo(int itemId)
	{
		if (!config.advisor())
		{
			return; // nothing rebuilds the cards: the screen reads their map instead — screenSeries
		}
		final TradeEngine.Series series = seriesFor(itemId);
		final Map<Integer, TradeEngine.Series> cards = cardsSeries;
		if (cards.get(itemId) == series
			|| (syncedItem == itemId && syncedSeries == series && syncedCards == cards))
		{
			return;
		}
		syncedItem = itemId;
		syncedSeries = series;
		syncedCards = cards;
		rebuildCards.run();
	}

	/**
	 * The series the offer screen and its chart's target price {@code itemId}
	 * from: seriesFor, which the cards are brought onto (syncCardsTo) — or,
	 * with the advisor off, the cards' map itself. Nothing rebuilds that map
	 * then, and the watchlist rows, the inspect card and the header go on
	 * reading it: the screen at 1998 from a series the map had dropped sat
	 * beside a row at 1990 for as long as the screen stayed up.
	 */
	TradeEngine.Series screenSeries(int itemId)
	{
		return config.advisor() ? seriesFor(itemId) : cardsSeries.get(itemId);
	}

	/** What syncCardsTo last rebuilt the cards for, and the cards as they
	 *  were then. */
	private int syncedItem = -1;
	private TradeEngine.Series syncedSeries;
	private Map<Integer, TradeEngine.Series> syncedCards;

	/** When the series seriesFor returns was fetched; 0 if unknown. */
	private long seriesFetchedAt(int itemId)
	{
		final Long offerAt = lastOfferSeries.containsKey(itemId) ? offerSeriesFetchedAt.get(itemId) : null;
		final Long pickedAt = selectedSeries.containsKey(itemId) ? selectedSeriesFetchedAt.get(itemId) : null;
		return Math.max(offerAt != null ? offerAt : 0L, pickedAt != null ? pickedAt : 0L);
	}

	/* ── The offer-screen chart's data ─────────────────────────────────── */

	/** At most this many chart series held: an item's few ranges, for the
	 *  handful of items an evening's offers go through. */
	private static final int CHART_CACHE_CAP = 24;
	/** A failed chart fetch is not asked for again for this long. */
	private static final long CHART_RETRY_MS = 60_000L;

	/** "itemId/step" -> {Series, fetchedAtMillis}, least recently drawn first. */
	private final Map<String, Object[]> chartCache = java.util.Collections.synchronizedMap(
		new LinkedHashMap<String, Object[]>(32, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, Object[]> eldest)
			{
				return size() > CHART_CACHE_CAP;
			}
		});
	private final java.util.Set<String> chartInFlight = java.util.concurrent.ConcurrentHashMap.newKeySet();
	private final Map<String, Long> chartTriedAt = new java.util.concurrent.ConcurrentHashMap<>();

	/** How long a chart series stays fresh: one bucket for 5m, and for the
	 *  longer steps a fraction of one (half, a third, a quarter), so the
	 *  newest bucket is never long behind. */
	static long chartTtlMs(String step)
	{
		switch (step)
		{
			case "5m":
				return 5 * 60_000L;
			case "1h":
				return 30 * 60_000L;
			case "6h":
				return 2 * 3_600_000L;
			default:
				return 6 * 3_600_000L;
		}
	}

	/**
	 * The series the chart draws for an item and range, picked as the site
	 * picks (seriesForView): the first of the range's timesteps with five
	 * prints, else the first with any. Null while one it would need is
	 * still coming; an empty series when every step came back empty.
	 * Asks for a missing or stale one; never waits for it. Client thread,
	 * every frame: map lookups and at most a queued task per step.
	 */
	private TradeEngine.Series chartSeries(int itemId, PriceChart.Range range)
	{
		final long now = System.currentTimeMillis();
		TradeEngine.Series fallback = null;
		TradeEngine.Series empty = null;
		for (String step : range.steps)
		{
			final TradeEngine.Series s;
			if ("5m".equals(step))
			{
				/* The 5-minute series is the one the offer screen fetches
				   and the advisor refreshes: drawn from there, and topped up
				   there when it is older than a bucket. */
				s = seriesFor(itemId);
				if (s == null || now - seriesFetchedAt(itemId) > chartTtlMs(step))
				{
					requestSharedSeries(itemId);
				}
			}
			else
			{
				final Object[] held = chartCache.get(itemId + "/" + step);
				s = held != null ? (TradeEngine.Series) held[0] : null;
				if (held == null || now - (long) held[1] > chartTtlMs(step))
				{
					requestChartSeries(itemId, step);
				}
			}
			if (s == null)
			{
				return fallback; // still coming: draw what there is, or "loading"
			}
			if (PriceChart.usable(s))
			{
				return s;
			}
			if (fallback == null && PriceChart.prints(s) > 0)
			{
				fallback = s;
			}
			if (empty == null)
			{
				empty = s;
			}
		}
		return fallback != null ? fallback : empty;
	}

	/**
	 * Fetch an item's 5-minute series into the same on-demand cache, on the
	 * same attempt clock, as the offer screen's own fetch — so the two never
	 * ask twice, and the advisor's next refreshOfferSeries reuses it — then
	 * let an offer screen open for the item re-price from it, without asking
	 * for the book. A sell card showing the item takes it up as it lands —
	 * see cacheOnDemandSeries.
	 *
	 * The offer screen always, whoever asked. The clock is shared, so a fetch
	 * a sell card started holds the offer screen's own off for a minute — and
	 * the screen that card leads to is the one most likely to open while it
	 * is still on its way.
	 *
	 * The sell card on screen (noteShownCard), the cards after it
	 * (noteCardsAhead) and the item picked in the sidebar
	 * (onSelectedItemChanged) ask through here.
	 */
	private void requestSharedSeries(int itemId)
	{
		final ScheduledExecutorService ex = executor;
		final long now = System.currentTimeMillis();
		final Long tried = geSeriesAttemptAt.get(itemId);
		if (!running || ex == null || !config.advisor() || (tried != null && now - tried < GE_SERIES_RETRY_MS))
		{
			return;
		}
		if (geSeriesAttemptAt.size() > ON_DEMAND_SERIES_CAP * 4)
		{
			geSeriesAttemptAt.clear(); // bounded; worst case is one early retry
		}
		geSeriesAttemptAt.put(itemId, now);
		ex.execute(() ->
		{
			if (!running || !config.advisor())
			{
				return;
			}
			/* A fetch queued ahead of this one, the offer screen's or the
			   advisor's, may already have brought it. */
			if (seriesFor(itemId) != null && System.currentTimeMillis() - seriesFetchedAt(itemId) <= chartTtlMs("5m"))
			{
				return;
			}
			try
			{
				cacheOnDemandSeries(itemId, marketClient.fetchTimeseries5m(itemId));
			}
			catch (Exception e)
			{
				return; // backing off, or the Wiki said no: tried again after GE_SERIES_RETRY_MS
			}
			repriceOffer.accept(itemId);
		});
	}

	/**
	 * The sell card on screen, priced the way the website prices it.
	 *
	 * "website has a better sell price here ... id try to price at the
	 * website price first for sure here not for 298". A sell card is priced
	 * from the item's price series when the plugin has one, and off the last
	 * insta-buy when it does not — and it fetches series for only the first
	 * SELL_SERIES_CAP sells, a cycle after they first appear. Blighted
	 * ancient ice sack was card 20 of 20: no series, so 298, "-12.3K gp if
	 * you sell" and "At a loss — Hold to keep it", beside a website asking
	 * 310 for the same stack. Ranked by that raw price, it sat last, where
	 * the cap never reached it.
	 *
	 * So the card you are looking at asks for its own, now: one request,
	 * on the offer screen's attempt clock and into the same cache, and the
	 * cards are rebuilt from it — no other fetch. refreshOfferSeries keeps it
	 * current while the card stays up. Sells only: an engine price can only
	 * raise a sell's ask, never drop the card, whereas the engine can turn
	 * down a flip idea and take its card out from under you.
	 */
	void noteShownCard(Integer itemId, boolean sell)
	{
		shownSellItemId = sell ? itemId : null;
		shownCardItemId = itemId;
		if (!sell || itemId == null)
		{
			return;
		}
		final long fetchedAt = seriesFetchedAt(itemId);
		if (!wantsSeries(itemId))
		{
			/* Fresh — but fresh is not priced. It may have landed after the
			   cards were built while another card was up. Rebuilt from what
			   is in hand then; nothing asked for. */
			if (fetchedAt >= cardsPricedAt)
			{
				rebuildCards.run();
			}
			return;
		}
		requestSharedSeries(itemId);
	}

	/**
	 * The cards after the one on screen (AdvisorPanel.cardsAhead), handed on
	 * whenever they change. Each the cards have no series for is asked for
	 * now — on the shared attempt clock, into the same cache, and the landing
	 * rebuilds the cards — up to AHEAD_FETCHES_PER_CARD for each card shown;
	 * the advisor's round keeps them current after that (refreshOfferSeries),
	 * as it does the shown sell card. While they stay ahead, the series they
	 * are priced from stays in the cards' map (pricingSeries).
	 *
	 * Only the first few flip ideas get a series from the round, so the card
	 * after those showed the last two prints and no rating: Ascension bolts
	 * at 5/20 beside Sunfire splinters at 4/20 rated "Solid Flip 55". Asked
	 * for ahead rather than on show: an idea the engine turns down is gone
	 * before it is paged to, not taken away while it is read.
	 *
	 * The budget is what stops one press of Next becoming seven requests: a
	 * turned-down idea moves the next card on, which is handed on in turn,
	 * and each landing turned the next one down. Handing on only at a page
	 * turn stopped that but left a card a round had moved up unasked, paged
	 * to raw. Now every change is handed on, and the budget bounds the cost.
	 */
	void noteCardsAhead(List<Integer> itemIds)
	{
		cardsAheadIds = itemIds != null ? List.copyOf(itemIds) : List.of();
		final Integer shown = shownCardItemId;
		if (!java.util.Objects.equals(shown, aheadBudgetCard))
		{
			aheadBudgetCard = shown;
			aheadFetchesLeft = AHEAD_FETCHES_PER_CARD;
		}
		if (!config.priceNextCard())
		{
			return;
		}
		for (Integer id : cardsAheadIds)
		{
			if (aheadFetchesLeft > 0 && id != null && cardsSeries.get(id) == null)
			{
				aheadFetchesLeft--;
				requestSharedSeries(id);
			}
		}
	}

	/** See noteCardsAhead. */
	private volatile List<Integer> cardsAheadIds = List.of();
	/** Requests noteCardsAhead may still send for the card on screen. */
	static final int AHEAD_FETCHES_PER_CARD = 2;
	private Integer aheadBudgetCard;
	private int aheadFetchesLeft = AHEAD_FETCHES_PER_CARD;

	/** Whether {@code itemId} has no series younger than one 5-minute bucket:
	 *  the item on screen asks for one then. */
	private boolean wantsSeries(int itemId)
	{
		return seriesFor(itemId) == null || System.currentTimeMillis() - seriesFetchedAt(itemId) > chartTtlMs("5m");
	}

	/** The cards rebuilt from what is already cached — no fetch. A field so
	 *  a test can see it run. */
	Runnable rebuildCards = this::recomputeAdvice;
	/** An offer screen open for the item re-priced from what is cached — see
	 *  repriceOpenOffer. A field so a test can see it run. */
	java.util.function.IntConsumer repriceOffer = this::repriceOpenOffer;
	/** When the cards were last priced: the moment recomputeAdvice took its
	 *  copy of the series. A series fetched since is not in them. */
	private volatile long cardsPricedAt;
	/** The series the cards were last priced from — pricingSeries at
	 *  cardsPricedAt. The rows, the inspect card, the header's Unrealized and
	 *  the portfolio total read this same map, not one of their own: built
	 *  at a different moment, with a different item on screen, the two sets
	 *  read one stack two ways until the next round. Every on-demand landing
	 *  rebuilds the cards and then the rows, in that order, on the client
	 *  thread. */
	private volatile Map<Integer, TradeEngine.Series> cardsSeries = new HashMap<>();

	private void requestChartSeries(int itemId, String step)
	{
		final ScheduledExecutorService ex = executor;
		final String key = itemId + "/" + step;
		final long now = System.currentTimeMillis();
		final Long tried = chartTriedAt.get(key);
		if (!running || ex == null || !config.advisor() || chartInFlight.contains(key)
			|| (tried != null && now - tried < CHART_RETRY_MS))
		{
			return;
		}
		if (chartTriedAt.size() > 4 * CHART_CACHE_CAP)
		{
			chartTriedAt.clear();
		}
		chartTriedAt.put(key, now);
		chartInFlight.add(key);
		ex.execute(() ->
		{
			try
			{
				if (!running || !config.advisor())
				{
					return;
				}
				final TradeEngine.Series s = marketClient.fetchTimeseries(itemId, step);
				chartCache.put(key, new Object[]{s, System.currentTimeMillis()});
				chartTriedAt.remove(key);
			}
			catch (IOException e)
			{
				// backing off, or the Wiki said no: tried again after CHART_RETRY_MS
			}
			finally
			{
				chartInFlight.remove(key);
			}
		});
	}

	/**
	 * The book's quote for an item as the offer screen would use it: none
	 * with the advisor off and the book past ADVISOR_OFF_BOOK_MAX_MS, the
	 * rule that blanks the offer screen's card, so the chart does not name
	 * as the market a price the card will not.
	 */
	private Advisor.Quote chartQuote(int itemId)
	{
		if (!config.advisor() && System.currentTimeMillis() - lastQuotesAt > ADVISOR_OFF_BOOK_MAX_MS)
		{
			return null;
		}
		return lastQuotes.get(itemId);
	}

	/** The target line's number: the offer screen's own — on the Set up
	 *  offer screen the very number its card shows and E types, otherwise
	 *  worked out through the same helper. */
	private long chartTarget(int itemId, boolean buy)
	{
		final Advisor.Quote q = chartQuote(itemId);
		final Integer onScreen = geContextItemId;
		final AdvisorPanel.Rec card = geContextRec;
		if (q != null && onScreen != null && onScreen == itemId && card != null && card.itemId == itemId
			&& card.sell != buy)
		{
			return card.unitPrice;
		}
		/* Off the Set up screen — over a finished or cancelled offer's
		   status panel, where no card is up — from the cards' map, as every
		   card is: seriesFor's top-up named sell 1998 there beside a SELL
		   card the cards had priced at 1983. */
		final TradeEngine.Series series = cardsSeries.get(itemId);
		final TradeEngine.Result engine = q != null && series != null
			? TradeEngine.viewTargets(q.low, q.high, q.lowTime, q.highTime, series, itemId) : null;
		return offerScreenPrice(q, engine, buy);
	}

