	private void refreshPanel()
	{
		if (mainPanel == null)
		{
			return;
		}
		/* The flip list rides with the stats now — it shows the range they
		   are for, so both are worked out from one read of the flips. */
		refreshStatsAndFavorites();
	}

	/** Portfolio value + time-window stats + the Favorites section, all of
	 *  which need the CURRENT holdings/offers (client thread) combined with
	 *  whatever prices are cached (empty if the advisor has never fetched —
	 *  everything still degrades gracefully to "cash only", never crashes).
	 *  Runs on its own client-thread hop so it can be called from anywhere
	 *  (a completed flip, a price refresh, the range dropdown, favoriting a
	 *  row) without assuming the caller is already on that thread. */
	private void refreshStatsAndFavorites()
	{
		if (mainPanel == null)
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			/* The "did the offer screen close" check moved to onGameTick \u2014
			   here it only ever ran on the re-check interval, which is where
			   the stale "YOUR OFFER" card came from. */

			final Map<Integer, Advisor.Quote> quotes = lastQuotes;
			final Map<Integer, AnalystRating.Average> averages = lastAverages;
			final Map<Integer, Long> favVolumes = lastVolumes;

			final long cash = totalCash();
			final Map<Integer, Integer> holdings = currentHoldings();
			final Map<Integer, Integer> equipped = currentEquipped();
			final List<Advisor.OfferView> offers = currentOffers();
			/* One series map for every price below, the cards' own — see
			   pricingSeries. */
			final Map<Integer, TradeEngine.Series> pricing = cardsSeries;
			final PortfolioValuer.Result portfolio =
				PortfolioValuer.value(cash, holdings, equipped, offersInSlots(true), quotes, pricing);
			notePortfolio(portfolio.total, quotes);
			/* The one-time "see this on pocketge.com" card: for someone who
			   has a flip to see there and has not linked, until answered. */
			final boolean nudge = !config.localBridge() && !config.bridgeNudgeDone() && !tracker.getFlips().isEmpty();

			final Map<Integer, long[]> openBuys = tracker.getHeldCost(heldForCost(holdings, offers));
			final Map<Integer, long[]> olderBuys = currentOlderBuys(openBuys);

			/*
			 * Marked at the price the plugin would actually tell you to sell
			 * at, after tax — see PortfolioValuer.netExit.
			 *
			 * This was qty * q.low - spent: the wrong side of the book AND no
			 * tax, which is not conservative, just inconsistent. It put the
			 * header a whole spread plus 2% away from the sell card for the
			 * same stack, far enough to flip the sign — "unrealized -5.2K"
			 * above a card offering +12K on the very same necklaces.
			 *
			 * It also has to agree with how the flip is eventually BOOKED, or
			 * the number jumps the moment you take the advice. A closed flip
			 * is sellGross - tax - buySpent, so an open one is the same thing
			 * at today's exit.
			 */
			long unrealized = 0;
			for (Map.Entry<Integer, long[]> e : openBuys.entrySet())
			{
				final long net = PortfolioValuer.netExit(quotes.get(e.getKey()), e.getKey(), pricing.get(e.getKey()));
				if (net <= 0)
				{
					continue;
				}
				final long qty = e.getValue()[0];
				final long spent = e.getValue()[1];
				unrealized += qty * net - spent;
			}

			final FlipStats.Range range = currentRange;
			final java.util.List<Flip> flips = flipsForRanges();
			final long firstFlipMillis = flips.isEmpty() ? System.currentTimeMillis() : flips.get(0).closedAt;
			final long statsNow = System.currentTimeMillis();
			final FlipStats.Stats stats = FlipStats.compute(
				flips, range, statsNow, tracker.getSessionStartMillis(), firstFlipMillis, unrealized);
			/* The list under the stats shows the same range they add up: "if
			   you have 1h youd see the flips you made the last 1h. if you have
			   all time, then youd see all the flips youve ever made". It used
			   to show the latest 50 whatever the range said. */
			final java.util.List<Flip> flipsInRange = FlipStats.inRange(flips, range, statsNow, tracker.getSessionStartMillis());
			rangeExpiresAt = FlipStats.nextExpiry(flipsInRange, range);

			final List<FavoriteLists.FavoriteList> favLists = loadFavoriteLists();
			final FavoriteLists.FavoriteList activeList = activeFavoriteList(favLists);
			final List<FavoritesPanel.Row> favRows = new ArrayList<>();
			/* Favourites, plus whatever is being inspected if it is not one of
			   them. A Find Opportunities row is not a favourite, so nothing
			   here would otherwise ever build it a Row — and the inspection
			   card is driven entirely by Rows. Built through the same loop as
			   the favourites rather than a second code path, so an inspected
			   item cannot end up with different numbers from the same item
			   sitting in the watchlist. It is kept OUT of favRows below, so it
			   never appears in the list itself. */
			final List<Favorites.Fav> toBuild = new ArrayList<>(
				activeList != null ? activeList.items : List.<Favorites.Fav>of());
			final Integer inspectedId = selectedFavoriteItemId;
			final String inspectedName = selectedFavoriteName;
			final boolean inspectedIsFavourite = inspectedId != null
				&& toBuild.stream().anyMatch(f -> f.id == inspectedId);
			if (inspectedId != null && !inspectedIsFavourite && inspectedName != null)
			{
				toBuild.add(new Favorites.Fav(inspectedId, inspectedName));
			}
			final List<FavoritesPanel.Row> allRows = new ArrayList<>();
			final Set<Integer> dayReach = dayChangeFavourites(activeList);
			final List<Integer> missingDay = new ArrayList<>();
			final long nowSec = System.currentTimeMillis() / 1000L;
			for (Favorites.Fav f : toBuild)
			{
				/* The inspected item rides along when it is not a favourite;
				   it is shown, not watched. */
				final boolean onList = inspectedIsFavourite || inspectedId == null || f.id != inspectedId;
				final FavoritesPanel.Row row = new FavoritesPanel.Row();
				row.id = f.id;
				row.name = f.name;
				final Advisor.Quote q = quotes.get(f.id);
				if (q != null && q.low > 0)
				{
					row.price = q.low;
					/* The day's change, as the website's 1D button gives it: the
					   live mid against the mid a day ago, from the hourly
					   series the range badges are already fetched for — see
					   PriceExtremes.dayChangePct.

					   It was the live mid against the Wiki's /24h average,
					   which is the last COMPLETE day's. After a fall that
					   average still holds the day before, so Sunfire splinters
					   read -19% here beside +3.18% on the website: "which is
					   true?" Mid against mid either way — an insta-sell against
					   a midpoint sat low by half the spread on every item.
					   Nothing until the hourly series is in: no figure, rather
					   than the old one — and it is asked for now, below. */
					double change = Double.NaN;
					final AnalystRating.Average avg = averages.get(f.id);
					if (dayReach.contains(f.id))
					{
						final PriceExtremes day = dayExtremes.get(f.id);
						if (day != null)
						{
							change = day.dayChangePct(q.high, q.low, nowSec);
						}
						else
						{
							missingDay.add(f.id);
						}
					}
					/* Past the hourly series' reach — see dayChangeFavourites
					   — the /24h figure, worded as what it is; without it a
					   favourite there lost its badge and its alert. Always
					   that one, as the day's measure is always the day's. */
					else if (q.high > 0 && avg != null && avg.avgHighPrice > 0 && avg.avgLowPrice > 0)
					{
						final double typicalMid = (avg.avgHighPrice + avg.avgLowPrice) / 2.0;
						change = ((q.high + q.low) / 2.0 - typicalMid) / typicalMid * 100.0;
						row.changeVsAverage = true;
					}
					if (!Double.isNaN(change))
					{
						row.changePct = change;
						if (onList)
						{
							maybeAlertOnMove(row); // the setting is for your watchlist
						}
					}
				}
				/* Detail-view targets.
				 *
				 * The raw book first, then the trade engine when this item has
				 * a price series — the same order of preference the GE offer
				 * screen and the ADJUST suggestions already use.
				 *
				 * This used to be the raw book ALONE, gated on q.high > q.low,
				 * and that is why the card could flatly contradict the website.
				 * Emerald necklace printed an insta-buy and an insta-sell of
				 * 709 within ten minutes of each other: a zero spread, so the
				 * gate failed, no targets were set, and the card said "no
				 * margin after tax right now" — while pocketge.com, looking at
				 * the same item through the same engine this plugin already
				 * carries a port of, showed buy 709 / sell 746 and +414K over a
				 * full 4-hour limit. The engine's whole job is to find a
				 * reachable price the last two prints do not happen to show,
				 * and the card was the one place still refusing to ask it.
				 *
				 * NOT clamped to the live book, deliberately — unlike the offer
				 * screen (see onScriptPostFired, TradeEngine.sellTarget). There
				 * you have already committed to a side and must not be quoted
				 * through the standing bid; here you are still deciding, which
				 * is exactly what the website's own TARGET BUY / TARGET SELL
				 * boxes show, and parity with those is the point of this view.
				 *
				 * The reason given here used to be that clamping "would
				 * reproduce the bug: sell clamped up to a 709 bid is a zero
				 * spread again". That is not so — sellTarget only ever raises
				 * the ask and buyTarget only ever lowers the bid, so the pair
				 * can only widen and a clamp cannot collapse it. The real
				 * cost of clamping here is the one above: it would stop this
				 * card agreeing with the website. Worth writing down
				 * correctly, because a wrong reason is what stops the next
				 * person re-examining the decision. */
				if (q != null && q.high > 0)
				{
					row.heldSell = Advisor.heldSellPrice(f.id, q, pricing.get(f.id));
				}
				if (q != null && q.low > 0)
				{
					final TradeEngine.Series series = pricing.get(f.id);
					if (series != null)
					{
						final TradeEngine.Result engine =
							TradeEngine.viewTargets(q.low, q.high, q.lowTime, q.highTime, series, f.id);
						if (engine != null && engine.viable && engine.buy > 0 && engine.sell > engine.buy)
						{
							row.targetBuy = engine.buy;
							row.targetSell = engine.sell;
						}
					}
					if (row.targetBuy <= 0 && q.high > q.low)
					{
						row.targetBuy = q.low;
						row.targetSell = q.high;
					}
				}
				if (row.targetBuy > 0 && row.targetSell > row.targetBuy)
				{
					// itemManager.getItemStats() throwing for one favorited item (seen
					// elsewhere in this file with getItemComposition(), see the bank
					// highlight fix) used to abort this whole per-favorite loop before
					// row.rating ever got set below — leaving that item's card blank
					// AND silently freezing stats/favorites/bank refresh for every
					// OTHER favorite too, since the Swing update at the end of this
					// method never ran. Row.limit is already documented as "0 if
					// unknown", so falling back to that is the existing contract.
					ItemStats itemStats = null;
					try
					{
						itemStats = itemManager.getItemStats(f.id);
					}
					catch (RuntimeException ignore) { /* fall back to limit unknown */ }
					row.limit = itemStats != null ? itemStats.getGeLimit() : 0;
					if (row.limit > 0)
					{
						final long nowMs = System.currentTimeMillis();
						row.limitUsed = tracker.boughtTowardLimit(f.id, nowMs);
						row.limitResetsAt = tracker.limitResetsAt(f.id, nowMs);
						/* Tax on the price you actually SELL at, which is now
						   the target rather than the raw high — otherwise the
						   plugin's net would differ from the website's by the
						   tax on the difference between the two. */
						final long edge = row.targetSell - row.targetBuy
							- FlipTracker.taxPerItem(row.targetSell, f.id);
						row.potentialProfit = edge * row.limit;
					}
				}
				row.dailyVolume = favVolumes.getOrDefault(f.id, 0L);
				fillOfferPosition(row, offers);
				fillHeldPosition(row, q, holdings, openBuys, pricing.get(f.id));
				row.heldWhere = positionWhere(row.listedQty, heldWhere(f.id));
				/* Off the same /24h response the ranked sell cards use, so
				   the inspect card and the sidebar cannot quote different
				   figures for the same stack. Needs heldQty, so it goes
				   after fillHeldPosition. */
				final AnalystRating.Average favAvg = averages.get(f.id);
				row.clearance = favAvg == null ? null
					: Clearance.of(row.heldQty, favAvg.highPriceVolume, favAvg.lowPriceVolume);
				/* Day or 5-day, decided in one place and by the website's own
				   rules — see PriceExtremes.tier. A big intraday move outranks
				   both, and that is decided in the panel off changePct. */
				final PriceExtremes ex = dayExtremes.get(f.id);
				row.tier = ex != null && q != null
					? ex.tier(q.high, q.low) : PriceExtremes.Tier.NONE;
				allRows.add(row);
				if (onList)
				{
					favRows.add(row);
				}
			}
			requestDayExtremes(missingDay);
			// Used to float 5D-high/low items to the top of the list on every
			// refresh — the pulsing border already flags them without
			// reshuffling the list out from under a manually-arranged order
			// every time a flag flips on/off (worse now that the bridge and
			// advisor cycles refresh every 15-60s, not just occasionally).
			// Order stays exactly as saved; the glow alone is the signal.
			lastPortfolioValue = portfolio.total;
			lastCash = cash;
			lastBankStacks = bankStacks();

			final List<FavoritesPanel.ListMeta> listMetas = new ArrayList<>();
			for (FavoriteLists.FavoriteList l : favLists)
			{
				final FavoritesPanel.ListMeta lm = new FavoritesPanel.ListMeta();
				lm.id = l.id;
				lm.name = l.name;
				lm.color = l.color;
				listMetas.add(lm);
			}
			final String activeListId = activeList != null ? activeList.id : null;

			SwingUtilities.invokeLater(() ->
			{
				mainPanel.updateStats(stats, portfolio, tracker.getSessionStartMillis());
				mainPanel.setBridgeNudge(nudge);
				mainPanel.updateHistory(flipsInRange, range);
				mainPanel.updateFavoriteLists(listMetas, activeListId);
				/* The watchlist shows favourites only; the inspection card may
				   be pointed at something that is not one, so it gets the
				   wider list to re-read its own item from. */
				mainPanel.setOlderBuys(olderBuys);
				mainPanel.updateFavorites(favRows, allRows);
			});
		});
	}

	/**
	 * Ping the player when something they watch has moved far enough to be
	 * worth leaving the bank for — Flipping Copilot's "dump alerts", built on
	 * the only evidence this plugin has.
	 *
	 * That evidence is a percentage, not a trade feed: the live midpoint
	 * against the midpoint a day ago (PriceExtremes.dayChangePct), the same
	 * number the spike badge shows. It cannot tell a genuine dump from a slow drift that happened to
	 * reach the same depth, and the setting's own description says so rather
	 * than implying a volume signal that isn't there.
	 *
	 * Runs on the advisor's background thread (the favourites refresh), which
	 * is why the cooldown map is concurrent. Notifier itself is safe to call
	 * from anywhere.
	 */
	private void maybeAlertOnMove(FavoritesPanel.Row row)
	{
		final int threshold = config.priceAlerts().pct();
		if (threshold <= 0 || row.name == null)
		{
			return;
		}
		final double move = Math.abs(row.changePct);
		if (move < threshold)
		{
			/* Back inside the band, so re-arm this item. An hour of silence is
			   the right answer to a price that STAYS 20% down; it is the wrong
			   answer to one that crosses, retreats and crosses again, which is
			   two separate events and the second is the tradeable one. */
			lastAlertMillis.remove(row.id);
			return;
		}
		final long now = System.currentTimeMillis();
		final Long last = lastAlertMillis.get(row.id);
		if (last != null && now - last < ALERT_COOLDOWN_MS)
		{
			return;
		}
		lastAlertMillis.put(row.id, now);
		notifier.notify(String.format("%s is %s %.0f%% %s.",
			row.name, row.changePct >= 0 ? "up" : "down", move, row.changeVsAverage ? "on its 24-hour average" : "on the day"));
	}
}

package com.pocketge.tracker;

import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * What a character's portfolio was worth, over time, on disk: "id like to
 * see my overal progress of bank value going up and down on a chart
 * somewehre". pocketge.com draws it, over the local bridge.
 *
 * One file per character beside flips.jsonl, one "time,value" line per
 * sample, appended — for the reasons FlipLedger gives: a config value is the
 * wrong home for something that only grows, and an append is the write a
 * crash cannot hurt. A torn last line is skipped on read.
 *
 * A sample at most every {@link #EVERY_MS} while you play. The panel works
 * the value out far more often than that, and a point for every refresh
 * would be a chart of the refresh timer. Older stretches are thinned as the
 * file is read — every point for the last 30 days, the last of each hour
 * before that, the last of each day before a year — and the file rewritten
 * when that drops anything, so a year of play stays a few thousand lines.
 *
 * Plain File and long[] {time, value}, no RuneLite types, so it can be
 * tested.
 */
final class PortfolioHistory
{
	static final long EVERY_MS = 15 * 60_000L;
	private static final long HOUR = 3_600_000L;
	private static final long DAY = 24 * HOUR;
	/** Every sample is kept this long. */
	static final long FULL_FOR_MS = 30 * DAY;
	/** Then one an hour until this age; one a day after it. */
	static final long HOURLY_FOR_MS = 365 * DAY;
	/** 2100-01-01. A time past this is not a sample from a wrong clock but
	 *  two torn lines run together — those come out centuries ahead — and
	 *  is dropped. Anything nearer is kept, ahead of the clock or not: a PC
	 *  whose date is behind must not cost the samples it is behind. */
	private static final long IMPOSSIBLE = 4_102_444_800_000L;
	/** A line longer than this is a corrupted file, not a sample. */
	private static final int MAX_LINE = 64;

	private final File dir;
	/** Character -> its samples, oldest first; read from disk on first use. */
	private final Map<Long, List<long[]>> loaded = new HashMap<>();

	PortfolioHistory(File dir)
	{
		this.dir = dir;
	}

	/**
	 * Record {@code value} for {@code account} at {@code now}, unless its
	 * last sample is under {@link #EVERY_MS} old or the value is not a real
	 * one. Returns whether it was recorded. Never throws: a history that
	 * cannot be written is a gap in a chart, nothing worse.
	 */
	synchronized boolean record(long account, long now, long value)
	{
		if (value <= 0)
		{
			return false;
		}
		final List<long[]> pts = load(account, now);
		/* A last sample from the future — a clock put back — is no reason
		   to wait: "under 15 minutes ago" would hold until the clock caught
		   up with it. */
		/* In time order, and measured against the newest sample at or before
		   now: samples ahead of a clock that has been put back are neither a
		   reason to wait nor a place to put this one after. */
		int at = pts.size();
		while (at > 0 && pts.get(at - 1)[0] > now)
		{
			at--;
		}
		if (at > 0 && now - pts.get(at - 1)[0] < EVERY_MS)
		{
			return false;
		}
		pts.add(at, new long[]{now, value});
		try
		{
			Files.createDirectories(dir.toPath());
			final File f = fileFor(account);
			/* A torn last line would run into this one and read back as a
			   single sample centuries ahead; start a fresh line under it. */
			final boolean torn = endsTorn(f);
			try (Writer w = Files.newBufferedWriter(f.toPath(), StandardCharsets.UTF_8,
				StandardOpenOption.CREATE, StandardOpenOption.APPEND))
			{
				w.write((torn ? "\n" : "") + now + "," + value + "\n");
			}
		}
		catch (IOException | RuntimeException e)
		{
			// kept in memory for this session; the file just misses it
		}
		return true;
	}

	/** The character's samples, oldest first, thinned: a copy, {time, value}
	 *  per entry. Empty for a character with none. */
	synchronized List<long[]> series(long account, long now)
	{
		final List<long[]> out = new ArrayList<>();
		for (long[] p : thin(load(account, now), now))
		{
			out.add(p.clone());
		}
		return out;
	}

	/**
	 * Every sample younger than {@link #FULL_FOR_MS}; the last of each hour
	 * up to {@link #HOURLY_FOR_MS}; the last of each day beyond it. Input
	 * oldest first, and so is the output.
	 */
	static List<long[]> thin(List<long[]> pts, long now)
	{
		final List<long[]> out = new ArrayList<>();
		long[] held = null;
		long heldBucket = 0;
		for (long[] p : pts)
		{
			final long age = now - p[0];
			final boolean keep = age <= FULL_FOR_MS;
			/* Odd for an hour, even for a day, so the two never collide. */
			final long bucket = age > HOURLY_FOR_MS ? Math.floorDiv(p[0], DAY) * 2 : Math.floorDiv(p[0], HOUR) * 2 + 1;
			if (held != null && (keep || bucket != heldBucket))
			{
				out.add(held);
				held = null;
			}
			if (keep)
			{
				out.add(p);
			}
			else
			{
				held = p;
				heldBucket = bucket;
			}
		}
		if (held != null)
		{
			out.add(held);
		}
		return out;
	}

	File fileFor(long account)
	{
		return new File(dir, "portfolio-" + Long.toHexString(account) + ".csv");
	}

	/** The character whose file was written last, or null for none — who
	 *  the chart shows before anyone has logged in this session. */
	synchronized Long latestAccount()
	{
		final File[] files = dir.listFiles((d, name) -> name.startsWith("portfolio-") && name.endsWith(".csv"));
		Long best = null;
		long bestAt = Long.MIN_VALUE;
		for (File f : files != null ? files : new File[0])
		{
			final String hex = f.getName().substring("portfolio-".length(), f.getName().length() - ".csv".length());
			try
			{
				final long account = Long.parseUnsignedLong(hex, 16);
				if (f.lastModified() > bestAt)
				{
					bestAt = f.lastModified();
					best = account;
				}
			}
			catch (NumberFormatException e)
			{
				// not one of ours
			}
		}
		return best;
	}

	/** Whether the file is non-empty and does not end in a newline. */
	private static boolean endsTorn(File f) throws IOException
	{
		if (!f.isFile() || f.length() == 0)
		{
			return false;
		}
		try (java.io.RandomAccessFile raf = new java.io.RandomAccessFile(f, "r"))
		{
			raf.seek(raf.length() - 1);
			return raf.read() != '\n';
		}
	}

	private List<long[]> load(long account, long now)
	{
		final List<long[]> have = loaded.get(account);
		if (have != null)
		{
			return have;
		}
		final List<long[]> raw = new ArrayList<>();
		final File f = fileFor(account);
		if (f.isFile())
		{
			try (BufferedReader r = Files.newBufferedReader(f.toPath(), StandardCharsets.UTF_8))
			{
				String line;
				while ((line = r.readLine()) != null)
				{
					final long[] p = parse(line);
					if (p != null)
					{
						raw.add(p);
					}
				}
			}
			catch (IOException | RuntimeException e)
			{
				// what was read is kept; the rest is a gap
			}
		}
		raw.sort((a, b) -> Long.compare(a[0], b[0]));
		/* Two torn lines run together read as one sample centuries out, and
		   kept it would sit at the end of every chart — see IMPOSSIBLE. */
		final int read = raw.size();
		raw.removeIf(p -> p[0] > IMPOSSIBLE);
		final List<long[]> pts = thin(raw, now);
		if (pts.size() < read)
		{
			rewrite(f, pts);
		}
		loaded.put(account, pts);
		return pts;
	}

	/** {time, value} from one line, or null for anything that is not one —
	 *  a torn last line, a blank, a hand edit. */
	static long[] parse(String line)
	{
		if (line == null || line.length() > MAX_LINE)
		{
			return null;
		}
		final int comma = line.indexOf(',');
		if (comma <= 0)
		{
			return null;
		}
		try
		{
			final long t = Long.parseLong(line.substring(0, comma).trim());
			final long v = Long.parseLong(line.substring(comma + 1).trim());
			return t > 0 && v > 0 ? new long[]{t, v} : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** Replace the file with {@code pts}, via a temporary file so a crash
	 *  mid-write leaves the old one whole. */
	private static void rewrite(File f, List<long[]> pts)
	{
		final File tmp = new File(f.getPath() + ".tmp");
		try
		{
			final StringBuilder sb = new StringBuilder();
			for (long[] p : pts)
			{
				sb.append(p[0]).append(',').append(p[1]).append('\n');
			}
			Files.write(tmp.toPath(), sb.toString().getBytes(StandardCharsets.UTF_8));
			Files.move(tmp.toPath(), f.toPath(), StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException | RuntimeException e)
		{
			// the long file still reads; thinning again next time
		}
	}
}

package com.pocketge.tracker;

import java.util.List;
import java.util.Map;

/**
 * Pure net-worth calculator (no RuneLite types — unit-testable). Everything
 * you own, priced at {@link #netExit} — what the plugin would actually get
 * you for it if you followed its own advice and sold.
 *
 * Total = cash on hand
 *       + bank + inventory + equipped items, at netExit
 *       + open GRAND EXCHANGE offers (see {@link #offerValue}), which needs
 *         its own accounting because gp and items move between "yours
 *         directly" and "escrowed in an offer" as it fills.
 *
 * <h2>One valuation, everywhere</h2>
 * This class used to price holdings at the raw {@code low} with no tax,
 * while the sell card and the watchlist's held-profit row priced the very
 * same stack at {@code high - tax}. That is the whole spread plus two
 * percent apart, which is more than enough to flip the sign: the header
 * could report an unrealized loss on a position whose own card was showing
 * a gain. Both numbers were defensible alone and indefensible side by side,
 * and this file's own comment claimed it used "the same valuation the flip
 * advisor uses" while doing something different.
 *
 * So there is one function now and everything calls it. See {@link #netExit}
 * for why it is the ask rather than the bid.
 */
public final class PortfolioValuer
{
	private PortfolioValuer() {}

	public static final int COINS_ID = 995;
	/**
	 * Platinum tokens are cash, not stock.
	 *
	 * Anyone flipping at real scale holds most of their gp as tokens — they
	 * are how you carry more than the 2,147,483,647 a coin stack can hold,
	 * and they are common well below that too. Treating them as just another
	 * bankable item has two consequences, both bad: the advisor's idea of
	 * your LIQUID cash — the number every buy recommendation is sized
	 * against — misses the bulk of it, so a player sitting on 500M in tokens
	 * gets told they can't afford anything; and the tokens themselves become
	 * eligible to be "sold", which is not a flip, it's breaking a note.
	 *
	 * Redeemed 1:1000 at any bank with no spread and no tax, so face value
	 * is exact — no quote lookup needed or wanted.
	 */
	public static final int PLATINUM_TOKEN_ID = 13204;
	public static final int PLATINUM_VALUE = 1000;

	/** True for the item ids that ARE money rather than something you trade.
	 *  Holdings maps must exclude these and count them as cash instead —
	 *  see {@link #cashValue}. */
	public static boolean isCash(int itemId)
	{
		return itemId == COINS_ID || itemId == PLATINUM_TOKEN_ID;
	}

	/** Face value in gp of a cash stack; 0 for anything that isn't cash. */
	public static long cashValue(int itemId, long quantity)
	{
		if (quantity <= 0)
		{
			return 0;
		}
		if (itemId == COINS_ID)
		{
			return quantity;
		}
		return itemId == PLATINUM_TOKEN_ID ? quantity * PLATINUM_VALUE : 0;
	}

	/**
	 * What one unit is worth to you, after tax: the standing bid minus the
	 * 2% the Exchange takes. 0 when there is no usable price.
	 *
	 * The ask ({@code high}) rather than the bid ({@code low}) because this
	 * has to agree with the advice. A SELL card lists at {@code high} — that
	 * is what {@link Advisor#sellCandidates} prices and what the offer screen
	 * fills in — so valuing the same stack at {@code low} would mean the
	 * plugin telling you a number it had already decided not to sell at.
	 * Marking the book at a price the tool itself would not take is how the
	 * header and the card came to disagree about the same items.
	 *
	 * Per unit, not on the total: that is how the GE charges it, and the
	 * rounding genuinely differs on a big stack of cheap items.
	 */
	public static long netExit(Advisor.Quote q, int itemId)
	{
		return netExit(q, itemId, null);
	}

	/**
	 * As above, at the price the sell card, the stack hovers and the bank
	 * marks name — Advisor.heldSellPrice, the website's Target Sell where
	 * {@code series} gives one. Without it the header's Unrealized and the
	 * portfolio total marked a stack at the insta-buy while its card said
	 * the website's price: 6,193 Dragon darts "+124K" above a card at +117K.
	 */
	public static long netExit(Advisor.Quote q, int itemId, TradeEngine.Series series)
	{
		if (q == null || q.high <= 0)
		{
			return 0;
		}
		final long price = Advisor.heldSellPrice(itemId, q, series);
		return Math.max(0, price - FlipTracker.taxPerItem(price, itemId));
	}

	private static TradeEngine.Series seriesOf(Map<Integer, TradeEngine.Series> series, int itemId)
	{
		return series != null ? series.get(itemId) : null;
	}

	public static class Result
	{
		public long cash;
		public long itemsValue;     // bank + inventory + equipped, at current low
		public long offersValue;    // net value tied up in active GE offers
		public long total;
	}

	public static Result value(
		long cash,
		Map<Integer, Integer> holdings,   // bank+inventory, excl. coins
		Map<Integer, Integer> equipped,
		List<Advisor.OfferView> offers,
		Map<Integer, Advisor.Quote> quotes)
	{
		return value(cash, holdings, equipped, offers, quotes, null);
	}

	/** As above, every stack priced from its series where there is one —
	 *  see {@link #netExit(Advisor.Quote, int, TradeEngine.Series)}. */
	public static Result value(
		long cash,
		Map<Integer, Integer> holdings,
		Map<Integer, Integer> equipped,
		List<Advisor.OfferView> offers,
		Map<Integer, Advisor.Quote> quotes,
		Map<Integer, TradeEngine.Series> series)
	{
		Result r = new Result();
		r.cash = Math.max(0, cash);
		r.itemsValue = itemsValue(holdings, quotes, series) + itemsValue(equipped, quotes, series);
		r.offersValue = 0;
		if (offers != null)
		{
			for (Advisor.OfferView o : offers)
			{
				r.offersValue += offerValue(o, quotes, series);
			}
		}
		r.total = r.cash + r.itemsValue + r.offersValue;
		return r;
	}

	/** What a stack you're currently holding is worth, and how much of that
	 *  is measurable gain. See {@link #heldPosition}. */
	public static class HeldPosition
	{
		/** Units in bank + inventory. 0 means there is nothing to report. */
		public int heldQty;
		/** After-tax proceeds for all of heldQty at the current instant-buy. */
		public long sellValue;
		/** True only when the plugin actually watched the purchase. */
		public boolean hasCostBasis;
		/** How many of heldQty the cost basis covers. */
		public int pricedQty;
		/** Proceeds minus cost, over pricedQty only. Meaningless unless
		 *  hasCostBasis. May be negative — you can be underwater. */
		public long heldProfit;
		/** What the pricedQty units cost, in total. Meaningless unless
		 *  hasCostBasis. The per-unit price paid is this over pricedQty —
		 *  never sellValue minus heldProfit, which mixes the whole stack's
		 *  proceeds with the cost of only part of it. */
		public long costOfPriced;
	}

	/**
	 * Values a stack the player is holding right now.
	 *
	 * The two quantities involved are NOT the same, and conflating them is
	 * the whole trap here:
	 *
	 *  - {@code held} is what is physically in the bank and inventory. That
	 *    is the cap on what could actually be sold.
	 *  - {@code tracked} is what the plugin WATCHED being bought and has not
	 *    yet matched against a sale ({@link FlipTracker#getOpenBuyTotals},
	 *    as {@code [qty, spent]}). That is the cap on what there is a
	 *    purchase price for.
	 *
	 * They drift apart constantly: buy 1,000 nature runes through the GE and
	 * cast 400, and held is 600 while tracked is still 1,000; inherit a stack
	 * from before the plugin was installed and held is 5,000 while tracked is
	 * nothing at all. So profit is claimed only over {@code min(held,
	 * tracked)} — the units that can both be sold and priced — and anything
	 * above that line is reported as sale value, never as profit. Getting
	 * this wrong prints a large green number for a stack the player has sat
	 * on for a year, which is the same fake win the recommendation card's
	 * "gp value" wording already avoids.
	 *
	 * Items sitting in an open GE sell offer are in neither the bank nor the
	 * inventory, so they never reach this method and cannot be double counted
	 * against {@link #offerValue}'s own accounting.
	 *
	 * @param tracked {@code [qty, spent]} from getOpenBuyTotals, or null when
	 *                no purchase was ever seen.
	 */
	public static HeldPosition heldPosition(int itemId, int held, Advisor.Quote q, long[] tracked)
	{
		return heldPosition(itemId, held, q, tracked, null);
	}

	/** As above, priced from {@code series} where there is one. */
	public static HeldPosition heldPosition(int itemId, int held, Advisor.Quote q, long[] tracked,
		TradeEngine.Series series)
	{
		final HeldPosition p = new HeldPosition();
		if (held <= 0 || q == null || q.high <= 0)
		{
			return p; // hold none of it, or no live price to value it at
		}
		final long netPerItem = netExit(q, itemId, series);
		if (netPerItem <= 0)
		{
			return p; // tax eats the whole price — nothing to report
		}
		p.heldQty = held;
		p.sellValue = (long) held * netPerItem;

		if (tracked == null || tracked.length < 2 || tracked[0] <= 0 || tracked[1] <= 0)
		{
			return p; // no purchase on record — sellValue only, labelled as such
		}
		final long trackedQty = tracked[0];
		final long trackedSpent = tracked[1];
		final long priced = Math.min(held, trackedQty);
		/* Round the COST UP, which rounds the reported profit DOWN. Every
		   rounding choice here errs against us: a tag that overstates by a
		   few gp is a tag that lied, and this one is telling the player to go
		   sell something. Exact when priced == trackedQty, the common case.
		   The double is safe — the product is bounded by trackedSpent, far
		   below the 2^53 exact-integer limit. */
		final long costOfPriced = (long) Math.ceil(trackedSpent * (priced / (double) trackedQty));
		p.hasCostBasis = true;
		p.pricedQty = (int) priced;
		p.costOfPriced = costOfPriced;
		p.heldProfit = priced * netPerItem - costOfPriced;
		return p;
	}

	private static long itemsValue(Map<Integer, Integer> items, Map<Integer, Advisor.Quote> quotes,
		Map<Integer, TradeEngine.Series> series)
	{
		if (items == null)
		{
			return 0;
		}
		long total = 0;
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			int qty = e.getValue();
			if (qty <= 0)
			{
				continue;
			}
			if (isCash(e.getKey()))
			{
				/* Cash reaches value() through the `cash` argument. Callers
				   are expected to have stripped it from holdings already, but
				   a stray coin or token stack here would be counted twice —
				   and for platinum at a live quote rather than its exact
				   1:1000 face value. Belt and braces on a total the player
				   makes decisions against. */
				continue;
			}
			final long net = netExit(quotes.get(e.getKey()), e.getKey(), seriesOf(series, e.getKey()));
			if (net <= 0)
			{
				continue; // unknown/untradeable item — can't price it, don't guess
			}
			total += (long) qty * net;
		}
		return total;
	}

	/**
	 * Value still tied up in a single active offer.
	 *
	 * BUY offer: the unfilled portion sits as gp in escrow (already deducted
	 * from your coin pouch by the game, so it must be counted here or it
	 * vanishes from the total); the filled-but-not-yet-collected portion has
	 * already become items, priced at today's market like any other holding.
	 *
	 * SELL offer: the unsold portion is still your item, sitting in the
	 * offer instead of your bank — priced the same as any other holding. The
	 * sold portion has already become gp (tax already deducted at the
	 * moment of sale under current GE rules) waiting to be collected.
	 *
	 * A finished or cancelled offer not yet collected is the same sum: the
	 * coins or items are in the slot rather than the bank, and counting it
	 * as nothing dropped the total by a whole offer until you collected —
	 * a dip the portfolio chart then kept for good.
	 */
	private static long offerValue(Advisor.OfferView o, Map<Integer, Advisor.Quote> quotes,
		Map<Integer, TradeEngine.Series> series)
	{
		if (o == null || !(o.active || o.uncollected))
		{
			return 0;
		}
		int unfilled = Math.max(0, o.totalQuantity - o.quantitySold);
		int filled = Math.max(0, o.quantitySold);
		Advisor.Quote q = quotes.get(o.itemId);
		/* Items sitting in an offer are items, so they are worth what any
		   other stack of them is worth — see netExit. Falls back to the
		   offer's own price only when there is no quote at all. */
		long unitValue = netExit(q, o.itemId, seriesOf(series, o.itemId));
		if (unitValue <= 0)
		{
			unitValue = o.price;
		}

		/*
		 * The collection box, when it has been seen: what is really still in
		 * the slot. quantitySold never goes down when you collect, so priced
		 * off it a collected part was counted twice — in your inventory, and
		 * again in the offer — and a finished buy collected item-side only
		 * read as the whole position twice over.
		 *
		 * Still listed, on top: a working buy's unfilled part in escrow at
		 * your bid; a working sell's unsold part as the items they are.
		 */
		if (o.boxKnown)
		{
			final long listed = !o.active ? 0 : o.buy ? (long) unfilled * o.price : (long) unfilled * unitValue;
			return listed + o.boxCoins + o.boxUnits * unitValue;
		}

		if (o.buy)
		{
			long escrow = (long) unfilled * o.price;
			long boughtValue = (long) filled * unitValue;
			return escrow + boughtValue;
		}
		else
		{
			long unsoldValue = (long) unfilled * unitValue;
			long tax = FlipTracker.taxPerItem(o.price, o.itemId) * filled;
			long soldProceeds = (long) filled * o.price - tax;
			return unsoldValue + soldProceeds;
		}
	}
}

package com.pocketge.tracker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.LinearGradientPaint;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * The pocketge.com price chart, drawn with Java2D.
 *
 * A port of drawChart in the site's app.js, not a lookalike: the same
 * dots for each side's prints fading with age, the same Period and Recent
 * marks, the same EMA trend, target line and badge and volume-by-price
 * profile, the same tick and label rules — so a chart in the game and the
 * page beside it say the same thing in the same way. The site line each
 * rule comes from is cited beside it.
 *
 * Zoom and pan are the site's too (see PriceChartOverlay): the wheel and
 * a drag on the dates zoom time, the price axis drags up and down to scale
 * the prices, a drag on the chart moves it both ways, and a double-click
 * puts back what it is on — drawn here by handing paint the window and the
 * price scale (Style.yScale and yOffset).
 *
 * What it leaves out, and why: the volume bars and the spread fill (asked
 * for: "vp is plenty", and the chart is a strip over the chat), the box
 * zoom (the wheel and the drags cover it in a strip this size), the 5Y range (its data comes from a second host the plugin does
 * not otherwise talk to), and the legend (the site hides it below 640px,
 * and this is narrower).
 *
 * Pure: everything is worked out from the data and painted into the
 * rectangle given, so it can be tested and rendered off the client.
 */
final class PriceChart
{
	/**
	 * The range buttons, and the Wiki timesteps each draws from, first
	 * choice first — seriesForView (app.js:4767-4775) without the history
	 * source. The first step with at least five prints is used, else the
	 * first with any.
	 */
	enum Range
	{
		D1("1D", 86_400L, "5m", "1h", "6h", "24h"),
		D5("5D", 432_000L, "1h", "5m", "6h", "24h"),
		M1("1M", 2_592_000L, "6h", "24h", "1h"),
		M6("6M", 15_552_000L, "24h", "6h"),
		Y1("1Y", 31_536_000L, "24h");

		final String label;
		final long periodSec;
		final String[] steps;

		Range(String label, long periodSec, String... steps)
		{
			this.label = label;
			this.periodSec = periodSec;
			this.steps = steps;
		}

		static Range of(String name)
		{
			for (Range r : values())
			{
				if (r.name().equals(name))
				{
					return r;
				}
			}
			return D1;
		}
	}

	// ---- colours the site paints with (app.css, app.js) --------------------

	static final Color TEXT_MAIN = new Color(0xD9, 0xD3, 0xC7);
	static final Color TEXT_MUTED = new Color(0x8A, 0x82, 0x74);
	/** The price axis under the pointer: a faint lift, not a colour. */
	static final Color AXIS_HOT = new Color(255, 255, 255, 16);
	static final Color POSITIVE = new Color(0x10, 0xB9, 0x81);
	static final Color NEGATIVE = new Color(0xEF, 0x53, 0x50);

	private static final Color GRID_H = new Color(255, 255, 255, Math.round(0.05f * 255));
	private static final Color GRID_V = new Color(255, 255, 255, Math.round(0.03f * 255));
	private static final Color TREND_CASING = new Color(8, 10, 14, Math.round(0.55f * 255));
	private static final Color BADGE_PLATE = new Color(19, 17, 16, Math.round(0.92f * 255));
	private static final Color CROSSHAIR = new Color(255, 255, 255, Math.round(0.35f * 255));
	private static final Color PILL = new Color(244, 241, 232, Math.round(0.97f * 255));
	private static final Color PILL_EDGE = new Color(10, 9, 8, Math.round(0.9f * 255));
	private static final Color PILL_TEXT = new Color(0x0B, 0x0E, 0x14);
	private static final Color TIP_BG = new Color(10, 9, 8, Math.round(0.97f * 255));
	private static final Color TIP_EDGE = new Color(0x3C, 0x35, 0x2B);
	private static final Color TIP_RULE = new Color(0x2B, 0x26, 0x21);
	private static final Color SAME_PRICE = new Color(0xC2, 0xCB, 0xDC);

	private static final double DOT_ALPHA_OLD = 0.40;
	private static final double DOT_ALPHA_NEW = 1.0;

	/** A dashed line, the site's setLineDash([4,4]). */
	private static Stroke dashed(float width)
	{
		return new BasicStroke(width, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[]{4f, 4f}, 0f);
	}

	private static Color alpha(Color c, double a)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), (int) Math.round(Math.max(0, Math.min(1, a)) * 255));
	}

	// ---- data ------------------------------------------------------------

	/** One range's points, oldest first. A side with no print is 0. */
	static final class Data
	{
		final long[] t;
		final double[] lo;
		final double[] hi;
		final double[] loVol;
		final double[] hiVol;

		Data(long[] t, double[] lo, double[] hi, double[] loVol, double[] hiVol)
		{
			this.t = t;
			this.lo = lo;
			this.hi = hi;
			this.loVol = loVol;
			this.hiVol = hiVol;
		}

		int size()
		{
			return t.length;
		}
	}

	/** Prints in a series: buckets with a price on at least one side. */
	static int prints(TradeEngine.Series s)
	{
		if (s == null || s.labels == null)
		{
			return 0;
		}
		int n = 0;
		for (int i = 0; i < s.labels.length; i++)
		{
			if (s.low[i] > 0 || s.high[i] > 0)
			{
				n++;
			}
		}
		return n;
	}

	/** Enough to draw: the site takes the first source with five. */
	static boolean usable(TradeEngine.Series s)
	{
		return prints(s) >= 5;
	}

	/**
	 * A series as one range draws it: buckets with no print on either side
	 * dropped (seriesFromTS, app.js:4729), and only the last {@code period}
	 * seconds back from the newest bucket kept (filterSeries, 4748-4757).
	 * Index-spaced from here on, as the site's x axis is.
	 */
	static Data prepare(TradeEngine.Series s, long periodSec)
	{
		if (s == null || s.labels == null)
		{
			return new Data(new long[0], new double[0], new double[0], new double[0], new double[0]);
		}
		long newest = Long.MIN_VALUE;
		for (int i = 0; i < s.labels.length; i++)
		{
			if (s.low[i] > 0 || s.high[i] > 0)
			{
				newest = Math.max(newest, s.labels[i]);
			}
		}
		final List<Integer> keep = new ArrayList<>();
		for (int i = 0; i < s.labels.length; i++)
		{
			if ((s.low[i] > 0 || s.high[i] > 0) && s.labels[i] >= newest - periodSec)
			{
				keep.add(i);
			}
		}
		keep.sort((a, b) -> Long.compare(s.labels[a], s.labels[b]));
		final int n = keep.size();
		final Data d = new Data(new long[n], new double[n], new double[n], new double[n], new double[n]);
		for (int j = 0; j < n; j++)
		{
			final int i = keep.get(j);
			d.t[j] = s.labels[i];
			d.lo[j] = Math.max(0, s.low[i]);
			d.hi[j] = Math.max(0, s.high[i]);
			d.loVol[j] = s.lowVol != null ? Math.max(0, s.lowVol[i]) : 0;
			d.hiVol[j] = s.highVol != null ? Math.max(0, s.highVol[i]) : 0;
		}
		return d;
	}

	// ---- the site's maths --------------------------------------------------

	/** A bucket's mid, one side standing in for the other (app.js:4798-4802). */
	static double mid(double lo, double hi)
	{
		if (lo > 0 && hi > 0)
		{
			return (lo + hi) / 2;
		}
		return lo > 0 ? lo : hi;
	}

	/** Change from the first mid to the last, in percent (pctChange, 4787-4796). */
	static double pctChange(Data d)
	{
		double first = 0;
		double last = 0;
		for (int i = 0; i < d.size(); i++)
		{
			final double m = mid(d.lo[i], d.hi[i]);
			if (m > 0)
			{
				if (first == 0)
				{
					first = m;
				}
				last = m;
			}
		}
		return first > 0 ? (last - first) / first * 100 : 0;
	}

	/** Tick values on a price axis (niceTicks, 4828-4849). */
	static List<Long> niceTicks(double min, double max, int count)
	{
		final List<Long> out = new ArrayList<>();
		final double range = max - min;
		if (!(range > 0) || count <= 0)
		{
			return out;
		}
		final double step = tickStep(min, max, count);
		for (double v = Math.ceil(min / step) * step; v <= max + 1e-9; v += step)
		{
			final long r = Math.round(v);
			if (r >= min - 1e-9 && r <= max + 1e-9 && (out.isEmpty() || out.get(out.size() - 1) != r))
			{
				out.add(r);
			}
		}
		return out;
	}

	/**
	 * How many ticks to ask niceTicks for: one per 40px of price pane, at
	 * most 14 (app.js:8605). The site's floor is five, but its chart is
	 * never under about 230px tall; in the ~100px chat pane five, snapped
	 * down, came out at up to 13 labels 8px apart. So the floor here is two.
	 */
	static int tickCount(double hPrice)
	{
		return Math.max(2, Math.min(14, (int) Math.round(hPrice / 40)));
	}

	/** The step niceTicks uses: the base snaps DOWN to 5, 2.5 (from tens
	 *  up only), 2 or 1, and is never under 1 gp. */
	static double tickStep(double min, double max, int count)
	{
		final double rawStep = (max - min) / count;
		final double mag = Math.pow(10, Math.floor(Math.log10(rawStep)));
		final double norm = rawStep / mag;
		final double base = norm >= 5 ? 5 : norm >= 2.5 && mag >= 10 ? 2.5 : norm >= 2 ? 2 : 1;
		return Math.max(1, base * mag);
	}

	/**
	 * A price-axis label (fmtYAxis, 1418-1444): whole gp under 10,000;
	 * otherwise K, M or B with the fewest decimals (at most 5) that make
	 * the tick step whole, so a label is the gridline's own value. Rounded
	 * as toFixed rounds: the double's exact value, halves up.
	 */
	static String fmtYAxis(double v, double step)
	{
		final double a = Math.abs(v);
		if (a < 10_000)
		{
			return String.format(Locale.US, "%,d", Math.round(v));
		}
		final double unit = a >= 1e9 ? 1e9 : a >= 1e6 ? 1e6 : 1e3;
		final String suffix = unit == 1e9 ? "B" : unit == 1e6 ? "M" : "K";
		int dec = 0;
		if (step > 0)
		{
			final double su = step / unit;
			while (dec < 5 && Math.abs(su * Math.pow(10, dec) - Math.round(su * Math.pow(10, dec))) > 1e-9)
			{
				dec++;
			}
		}
		else
		{
			dec = a / unit < 100 ? 2 : 0;
		}
		String s = new java.math.BigDecimal(v / unit).setScale(dec, java.math.RoundingMode.HALF_UP).toPlainString();
		if (step <= 0 && s.contains("."))
		{
			s = s.replaceAll("0+$", "").replaceAll("\\.$", "");
		}
		return s + suffix;
	}

	/** The data's lowest and highest print, {min, max}, or null for none. */
	static double[] dataExtent(Data d)
	{
		double min = Double.MAX_VALUE;
		double max = -Double.MAX_VALUE;
		for (int i = 0; i < d.size(); i++)
		{
			for (double v : new double[]{d.lo[i], d.hi[i]})
			{
				if (v > 0)
				{
					min = Math.min(min, v);
					max = Math.max(max, v);
				}
			}
		}
		return min > max ? null : new double[]{min, max};
	}

	/**
	 * The price scale: the data's extent, widened to take in each line that
	 * is near it (the target joins on the site, app.js:8519-8524), then 5%
	 * either side, ±1 when flat (fitPriceRange, 4387-4392).
	 */
	static double[] priceScale(Data d, long... lines)
	{
		final double[] ext = dataExtent(d);
		if (ext == null)
		{
			return new double[]{0, 1};
		}
		double min = ext[0];
		double max = ext[1];
		for (long v : lines)
		{
			if (v > 0 && nearData(v, ext[0], ext[1]))
			{
				min = Math.min(min, v);
				max = Math.max(max, v);
			}
		}
		if (max - min < 1e-9)
		{
			return new double[]{min - 1, max + 1};
		}
		final double pad = (max - min) * 0.05;
		return new double[]{min - pad, max + pad};
	}

	/** Whether a line belongs on the scale: within the data's own span, or
	 *  8% of its top, of the data (app.js:4384-4386). */
	static boolean nearData(double v, double dataMin, double dataMax)
	{
		final double slack = Math.max(dataMax - dataMin, dataMax * 0.08);
		return v >= dataMin - slack && v <= dataMax + slack;
	}

	/**
	 * The trend: an EMA of the mid, each side carried forward over a gap,
	 * the pen lifted after a long run with neither (app.js:9065-9103). It
	 * starts once both sides have printed. NaN where there is no line.
	 */
	static double[] trend(Data d)
	{
		final int n = d.size();
		final double[] out = new double[n];
		java.util.Arrays.fill(out, Double.NaN);
		if (n <= 2)
		{
			return out;
		}
		final int period = Math.max(2, (int) Math.round(n * 0.08));
		final double k = 2.0 / (period + 1);
		final int carryMax = Math.max(3, (int) Math.round(n * 0.02));
		double lastLo = Double.NaN;
		double lastHi = Double.NaN;
		double ema = Double.NaN;
		int missing = 0;
		for (int i = 0; i < n; i++)
		{
			if (d.lo[i] > 0)
			{
				lastLo = d.lo[i];
			}
			if (d.hi[i] > 0)
			{
				lastHi = d.hi[i];
			}
			if (d.lo[i] <= 0 && d.hi[i] <= 0)
			{
				if (++missing > carryMax)
				{
					lastLo = Double.NaN;
					lastHi = Double.NaN;
					ema = Double.NaN;
				}
				continue;
			}
			missing = 0;
			if (Double.isNaN(lastLo) || Double.isNaN(lastHi))
			{
				continue; // nothing to average yet
			}
			final double m = (lastLo + lastHi) / 2;
			ema = Double.isNaN(ema) ? m : m * k + ema * (1 - k);
			out[i] = ema;
		}
		return out;
	}

	/** Index of the highest high and lowest low from {@code from} on, or
	 *  -1 for a side with none: {hiIdx, loIdx}. Period marks use the whole
	 *  window, Recent marks its last quarter (app.js:8575-8585). */
	static int[] extremes(Data d, int from)
	{
		int hiIdx = -1;
		int loIdx = -1;
		for (int i = Math.max(0, from); i < d.size(); i++)
		{
			if (d.hi[i] > 0 && (hiIdx < 0 || d.hi[i] > d.hi[hiIdx]))
			{
				hiIdx = i;
			}
			if (d.lo[i] > 0 && (loIdx < 0 || d.lo[i] < d.lo[loIdx]))
			{
				loIdx = i;
			}
		}
		return new int[]{hiIdx, loIdx};
	}

	static int recentStart(int n)
	{
		return (int) Math.floor(n * 0.75);
	}

	/** Zoom on the time axis, as the site's: 1 shows everything, 20 the
	 *  most (app.js:9708-9712). */
	static final double ZOOM_MAX = 20;

	/** How many points a zoom shows: max(20, n / zoom), and never more than
	 *  there are (app.js:8492). */
	static int window(int n, double zoom)
	{
		return Math.min(n, Math.max(20, (int) Math.floor(n / Math.max(1, zoom))));
	}

	/** The first point shown for a window of {@code win} starting at
	 *  {@code offset} — or ending at the newest point when offset is
	 *  negative, which is where a zoom stays pinned until panned
	 *  (anchorZoomToLatest, 9493-9502). */
	static int windowStart(int n, int win, int offset)
	{
		final int latest = Math.max(0, n - win);
		return offset < 0 ? latest : Math.max(0, Math.min(latest, offset));
	}

	/** Points {@code from} (inclusive) to {@code to} (exclusive). */
	static Data slice(Data d, int from, int to)
	{
		final int a = Math.max(0, from);
		final int b = Math.min(d.size(), to);
		if (a == 0 && b == d.size())
		{
			return d;
		}
		final int n = Math.max(0, b - a);
		final Data out = new Data(new long[n], new double[n], new double[n], new double[n], new double[n]);
		System.arraycopy(d.t, a, out.t, 0, n);
		System.arraycopy(d.lo, a, out.lo, 0, n);
		System.arraycopy(d.hi, a, out.hi, 0, n);
		System.arraycopy(d.loVol, a, out.loVol, 0, n);
		System.arraycopy(d.hiVol, a, out.hiVol, 0, n);
		return out;
	}

	/** Volume by price: {@code buckets} bands over [vmin, vmax], each
	 *  print adding its own side's volume (app.js:8791-8800). */
	static double[] volumeProfile(Data d, double vmin, double vmax, int buckets)
	{
		final double[] out = new double[buckets];
		final double span = vmax - vmin;
		if (!(span > 0))
		{
			return out;
		}
		for (int i = 0; i < d.size(); i++)
		{
			addToProfile(out, d.hi[i], d.hiVol[i], vmin, span);
			addToProfile(out, d.lo[i], d.loVol[i], vmin, span);
		}
		return out;
	}

	private static void addToProfile(double[] out, double price, double vol, double vmin, double span)
	{
		if (price <= 0 || vol <= 0)
		{
			return;
		}
		final double f = (price - vmin) / span;
		if (f < 0 || f > 1)
		{
			return;
		}
		out[Math.min(out.length - 1, (int) (f * out.length))] += vol;
	}

	// ---- painting ----------------------------------------------------------

	/** Which colours, whether to draw the volume-by-price profile, and the
	 *  price scale as the mouse has left it. */
	static final class Style
	{
		Color buy = new Color(0xFF, 0xC1, 0x07);
		Color sell = new Color(0x29, 0xB6, 0xF6);
		/** The volume-by-price profile, on by default as on the site. */
		boolean vp = true;
		/** The price axis as dragged (the site's yScale): 1 fits the data;
		 *  above 1 the range widens round its middle and the chart flattens,
		 *  below 1 it narrows and the swings grow. */
		double yScale = 1;
		/** The prices slid up or down by a drag on the plot, as a fraction
		 *  of the range shown (the site's yOffset). */
		double yOffset = 0;
		/** The pointer is on the price axis, or dragging it: the column
		 *  lights faintly, the one sign that it can be grabbed. */
		boolean axisHot;
	}

	/** How far the price axis stretches and squashes, and how many ranges
	 *  the prices slide either way (app.js:9466, 9479). */
	static final double Y_SCALE_MIN = 0.15;
	static final double Y_SCALE_MAX = 12;
	static final double Y_PAN_MAX = 2;

	/**
	 * The fitted range as the mouse has left it: scaled round its middle,
	 * then slid by {@code yOffset} of what is then shown — the scale first,
	 * so a slide is measured in the range you are looking at
	 * (app.js:8529-8540).
	 */
	static double[] manualRange(double[] fit, double yScale, double yOffset)
	{
		double min = fit[0];
		double max = fit[1];
		if (yScale != 1)
		{
			final double mid = (min + max) / 2;
			final double half = (max - min) / 2 * yScale;
			min = mid - half;
			max = mid + half;
		}
		if (yOffset != 0)
		{
			final double shift = (max - min) * yOffset;
			min += shift;
			max += shift;
		}
		return new double[]{min, max};
	}

	/** A drag of {@code dy} px on the price axis (app.js:9465-9468): down
	 *  widens the range and flattens the chart, up narrows it. */
	static double yScaleAfter(double yScale, int dy)
	{
		return Math.max(Y_SCALE_MIN, Math.min(Y_SCALE_MAX, yScale * Math.exp(dy / 150.0)));
	}

	/** A drag of {@code dy} px on the plot (app.js:9476-9481): the prices
	 *  follow the pointer, as a map does, up to two ranges either way so
	 *  the data cannot be flung somewhere it has to be hunted for. */
	static double yOffsetAfter(double yOffset, int dy, double hPrice)
	{
		if (hPrice <= 0)
		{
			return yOffset;
		}
		return Math.max(-Y_PAN_MAX, Math.min(Y_PAN_MAX, yOffset + dy / hPrice));
	}

	/** The horizontal lines: the target for the offer's side, and the
	 *  price set in the offer. 0 for none. */
	static final class Lines
	{
		long target;
		boolean targetBuy;
		long offer;
	}

	/** Where the plot ended up, for a caller that wants to place things. */
	static final class Layout
	{
		int x0;
		int y0;
		int w;
		int h;
		double stepX;
	}

	/**
	 * Draw the chart into {@code area}. {@code mouse} (in the same
	 * coordinates, or null) drives the crosshair and tooltip.
	 */
	static Layout paint(Graphics2D g0, Rectangle area, Data d, Style st, Lines ln, Point mouse)
	{
		final Graphics2D g = (Graphics2D) g0.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			return paintInto(g, area, d, st, ln != null ? ln : new Lines(), mouse);
		}
		finally
		{
			g.dispose();
		}
	}

	private static Layout paintInto(Graphics2D g, Rectangle area, Data d, Style st, Lines ln, Point mouse)
	{
		final int W = area.width;
		final int H = area.height;
		/* Layout (app.js:8470-8477): axis on the right, 8px in from the
		   left, the bottom 20px for time labels and the hover's time pill.
		   The top pad is smaller than the site's 14px: the header sits
		   directly above. One pane, prices only: the site's volume bars
		   (8567-8571, 8715-8770) are left out, the volume-by-price profile
		   says it. */
		final Layout lay = new Layout();
		lay.x0 = area.x + 8;
		lay.y0 = area.y + 6;
		lay.h = H - 6 - 20;
		final int x0 = lay.x0;
		final int y0 = lay.y0;
		final int h = lay.h;
		final double hPrice = h;
		final Font axisFont = new Font(Font.SANS_SERIF, Font.PLAIN, W >= 800 ? 12 : 10);
		g.setFont(axisFont);
		final FontMetrics fm = g.getFontMetrics();

		final int n = d.size();
		if (n == 0)
		{
			lay.w = W - 8 - 45;
			drawCentred(g, area, "No trade data for this timeframe — try a longer one.", TEXT_MUTED, 12);
			return lay;
		}

		/* The target joins the scale when it is near the data, and so does
		   the price in the offer. */
		final double[] scale = manualRange(priceScale(d, ln.target, ln.offer), st.yScale, st.yOffset);
		final double vmin = scale[0];
		final double vmax = scale[1];
		final int count = tickCount(hPrice);
		final double step = tickStep(vmin, vmax, count);
		final List<Long> ticks = niceTicks(vmin, vmax, count);
		/* The axis column fits its widest label. A tall chart asks for finer
		   ticks, and finer ticks carry more decimals ("1.2825M"), which ran
		   over the panel's edge in the site's fixed 45px. */
		int widest = 0;
		for (long v : ticks)
		{
			widest = Math.max(widest, fm.stringWidth(fmtYAxis(v, step)));
		}
		final int axisW = Math.max(W < 480 ? 38 : 45, widest + 8);
		lay.w = W - 8 - axisW;
		final int w = lay.w;

		final double dataW = w - 12;
		final double stepX = n > 1 ? dataW / (n - 1) : 0;
		lay.stepX = stepX;
		final double lo = vmin;
		final double hi = vmax;
		final java.util.function.DoubleUnaryOperator ypx = v -> y0 + (1 - (v - lo) / (hi - lo)) * hPrice;
		final java.util.function.IntToDoubleFunction xpx = i -> x0 + i * stepX;

		if (st.axisHot)
		{
			g.setColor(AXIS_HOT);
			g.fillRect(x0 + w + 1, y0, area.x + W - (x0 + w + 1), h);
		}
		// 1. price grid and labels (8597-8620)
		g.setStroke(new BasicStroke(1f));
		String prevTick = null;
		double prevTickY = Double.NaN;
		for (long v : ticks)
		{
			final double y = ypx.applyAsDouble(v);
			g.setColor(GRID_H);
			g.draw(new Line2D.Double(x0, Math.round(y) + 0.5, x0 + w, Math.round(y) + 0.5));
			/* A label that would touch the one below it, or repeat it (a
			   billion-gp axis past five decimals), is left to its gridline. */
			final String label = fmtYAxis(v, step);
			if (label.equals(prevTick) || Math.abs(prevTickY - y) < fm.getAscent() + 2)
			{
				continue;
			}
			g.setColor(TEXT_MUTED);
			g.drawString(label, x0 + w + 6, (float) (y + fm.getAscent() / 2.0 - 1));
			prevTick = label;
			prevTickY = y;
		}

		// 2. time grid and labels (8623-8680)
		final long span = d.t[n - 1] - d.t[0];
		final DateTimeFormatter fmt = DateTimeFormatter.ofPattern(
			span <= 2 * 86_400L ? "HH:mm" : span <= 180 * 86_400L ? "MMM d" : "MMM yy", Locale.US);
		final int linesX = Math.min(n, Math.max(3, Math.min(9, (int) Math.round(dataW / 170))));
		final int xStep = Math.max(1, n / Math.max(1, linesX));
		String prevLabel = null;
		double prevRight = Double.NEGATIVE_INFINITY;
		for (int i = 0; i < n; i += xStep)
		{
			final double x = xpx.applyAsDouble(i);
			g.setColor(GRID_V);
			g.draw(new Line2D.Double(Math.round(x) + 0.5, y0, Math.round(x) + 0.5, y0 + h));
			final String label = fmt.format(Instant.ofEpochSecond(d.t[i]).atZone(ZoneId.systemDefault()));
			if (label.equals(prevLabel))
			{
				continue;
			}
			final int lw = fm.stringWidth(label);
			final double half = lw / 2.0;
			final double cx = Math.max(area.x + half + 2, Math.min(area.x + W - half - 2, x));
			if (cx - half < prevRight + 6)
			{
				continue;
			}
			g.setColor(TEXT_MUTED);
			g.drawString(label, (float) (cx - half), y0 + h + 4 + fm.getAscent());
			prevLabel = label;
			prevRight = cx + half;
		}

		final Shape oldClip = g.getClip();
		/* From the top of the area given, not the site's 9px above the plot:
		   here the header sits directly above, 6px up, and data pushed high
		   by a stretched or dragged price axis drew over its buttons. The 6px
		   is still room for an orb and its ring. */
		g.clip(new Rectangle(x0 - 1, area.y, w + 2, (y0 - area.y) + (int) hPrice + 3));

		// 3. volume by price, behind everything else in the clip (8791-8898)
		if (st.vp)
		{
			drawProfile(g, d, vmin, vmax, x0, y0, w, hPrice, ypx);
		}

		/* 4. dots, each side followed by its Period orb: highs, then lows
		   over them (8947-8982, 9055-9056) */
		final double dotR = Math.max(1.5, Math.min(2.4, stepX * 0.42));
		final int[] period = extremes(d, 0);
		drawDots(g, d, d.hi, st.sell, xpx, ypx, dotR);
		orb(g, period[0] >= 0 ? xpx.applyAsDouble(period[0]) : Double.NaN,
			period[0] >= 0 ? ypx.applyAsDouble(d.hi[period[0]]) : Double.NaN, st.sell);
		drawDots(g, d, d.lo, st.buy, xpx, ypx, dotR);
		orb(g, period[1] >= 0 ? xpx.applyAsDouble(period[1]) : Double.NaN,
			period[1] >= 0 ? ypx.applyAsDouble(d.lo[period[1]]) : Double.NaN, st.buy);

		// 5. trend (9065-9159)
		drawTrend(g, d, xpx, ypx, x0, w);

		// 6. recent rings, after the trend (9161-9174)
		final int[] recent = extremes(d, recentStart(n));
		if (recent[0] >= 0)
		{
			ring(g, xpx.applyAsDouble(recent[0]), ypx.applyAsDouble(d.hi[recent[0]]), st.sell);
		}
		if (recent[1] >= 0)
		{
			ring(g, xpx.applyAsDouble(recent[1]), ypx.applyAsDouble(d.lo[recent[1]]), st.buy);
		}
		g.setClip(oldClip);

		// 7. the target, and the price in the offer (9195-9278)
		if (ln.target > 0)
		{
			final Color c = ln.targetBuy ? st.buy : st.sell;
			priceLine(g, ln.target, "Target", c, vmin, vmax, ypx, x0, y0, w, hPrice, true);
		}
		if (ln.offer > 0)
		{
			priceLine(g, ln.offer, "Your offer", TEXT_MAIN, vmin, vmax, ypx, x0, y0, w, hPrice, false);
		}

		// 8. hover (9281-9331, tooltip 9380-9410)
		if (mouse != null && mouse.x >= x0 && mouse.x <= x0 + dataW && mouse.y >= y0 && mouse.y <= y0 + h)
		{
			final int i = (int) Math.max(0, Math.min(n - 1, Math.round((mouse.x - x0) / Math.max(1e-9, stepX))));
			drawHover(g, area, d, st, i, mouse, xpx.applyAsDouble(i), x0, y0, w, h, hPrice, vmin, vmax, axisFont);
		}
		return lay;
	}

	private static void drawDots(Graphics2D g, Data d, double[] v, Color c,
		java.util.function.IntToDoubleFunction xpx, java.util.function.DoubleUnaryOperator ypx, double r)
	{
		final int n = d.size();
		for (int i = 0; i < n; i++)
		{
			if (v[i] <= 0)
			{
				continue;
			}
			final double a = n > 1 ? DOT_ALPHA_OLD + (DOT_ALPHA_NEW - DOT_ALPHA_OLD) * i / (n - 1) : DOT_ALPHA_NEW;
			g.setColor(alpha(c, a));
			g.fill(new Ellipse2D.Double(xpx.applyAsDouble(i) - r, ypx.applyAsDouble(v[i]) - r, r * 2, r * 2));
		}
	}

	/** Period mark: a solid orb with a white centre (8975-8980). */
	private static void orb(Graphics2D g, double x, double y, Color c)
	{
		if (Double.isNaN(x) || Double.isNaN(y))
		{
			return;
		}
		g.setColor(alpha(c, 0.9));
		g.fill(new Ellipse2D.Double(x - 7, y - 7, 14, 14));
		g.setColor(Color.WHITE);
		g.fill(new Ellipse2D.Double(x - 3, y - 3, 6, 6));
	}

	/** Recent mark: a hollow ring (9161-9166). */
	private static void ring(Graphics2D g, double x, double y, Color c)
	{
		g.setColor(c);
		g.setStroke(new BasicStroke(2.5f));
		g.draw(new Ellipse2D.Double(x - 7, y - 7, 14, 14));
		g.setStroke(new BasicStroke(1f));
	}

	private static void drawTrend(Graphics2D g, Data d, java.util.function.IntToDoubleFunction xpx,
		java.util.function.DoubleUnaryOperator ypx, int x0, int w)
	{
		final double[] ema = trend(d);
		final Path2D path = new Path2D.Double();
		boolean pen = false;
		boolean any = false;
		for (int i = 0; i < ema.length; i++)
		{
			if (Double.isNaN(ema[i]))
			{
				pen = false;
				continue;
			}
			final double x = xpx.applyAsDouble(i);
			final double y = ypx.applyAsDouble(ema[i]);
			if (pen)
			{
				path.lineTo(x, y);
			}
			else
			{
				path.moveTo(x, y);
				pen = true;
			}
			any = true;
		}
		if (!any)
		{
			return;
		}
		g.setStroke(new BasicStroke(4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(TREND_CASING);
		g.draw(path);
		/* #D9D3C7, fading in from the left: 0.40 x 0.90 to 1.0 x 0.90. */
		g.setPaint(new LinearGradientPaint(x0, 0, x0 + Math.max(1, w), 0, new float[]{0f, 1f},
			new Color[]{alpha(TEXT_MAIN, 0.36), alpha(TEXT_MAIN, 0.90)}));
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.draw(path);
		g.setStroke(new BasicStroke(1f));
	}

	private static void drawProfile(Graphics2D g, Data d, double vmin, double vmax, int x0, int y0, int w,
		double hPrice, java.util.function.DoubleUnaryOperator ypx)
	{
		final int nb = Math.max(12, Math.min(30, (int) Math.round(hPrice / 12)));
		final double[] vol = volumeProfile(d, vmin, vmax, nb);
		double max = 0;
		int poc = -1;
		for (int b = 0; b < nb; b++)
		{
			if (vol[b] > max)
			{
				max = vol[b];
				poc = b;
			}
		}
		if (max <= 0)
		{
			return;
		}
		final double maxLen = 0.15 * w;
		final double bandH = hPrice / nb;
		final double barH = Math.max(1, Math.min(bandH - 3, bandH * 0.72));
		/* The busiest level's band, across the whole plot (8842-8851). */
		final double pocMid = ypx.applyAsDouble(vmin + (poc + 0.5) * (vmax - vmin) / nb);
		g.setColor(new Color(255, 255, 255, Math.round(0.045f * 255)));
		g.fill(new java.awt.geom.Rectangle2D.Double(x0, pocMid - barH / 2, w, barH));
		g.setColor(new Color(255, 255, 255, Math.round(0.20f * 255)));
		g.fill(new java.awt.geom.Rectangle2D.Double(x0, Math.round(pocMid), w, 1));
		for (int b = 0; b < nb; b++)
		{
			if (vol[b] <= 0)
			{
				continue;
			}
			final boolean isPoc = b == poc;
			final double len = vol[b] / max * maxLen;
			if (len < 0.5)
			{
				continue;
			}
			final double mid = ypx.applyAsDouble(vmin + (b + 0.5) * (vmax - vmin) / nb);
			final double bx = x0 + w - len;
			final double by = mid - barH / 2;
			g.setColor(new Color(255, 255, 255, Math.round((isPoc ? 0.08f : 0.05f) * 255)));
			g.fill(new java.awt.geom.Rectangle2D.Double(bx, by, len, barH));
			g.setColor(new Color(255, 255, 255, Math.round((isPoc ? 0.55f : 0.22f) * 255)));
			g.fill(new java.awt.geom.Rectangle2D.Double(bx, by, 1, barH));
			if (isPoc)
			{
				g.setColor(new Color(255, 255, 255, Math.round(0.30f * 255)));
				g.fill(new java.awt.geom.Rectangle2D.Double(bx, by, len, 1));
				g.fill(new java.awt.geom.Rectangle2D.Double(bx, by + barH - 1, len, 1));
			}
		}
	}

	/**
	 * A dashed level across the plot with its badge (9204-9278): the word
	 * faint and small, the price bold. Off the scale, no line, and the
	 * badge pinned to the edge it is beyond with an arrow. The target's
	 * badge sits at the left as on the site; the offer's at the right, so
	 * the two never cover each other.
	 */
	private static void priceLine(Graphics2D g, long price, String word, Color c, double vmin, double vmax,
		java.util.function.DoubleUnaryOperator ypx, int x0, int y0, int w, double hPrice, boolean left)
	{
		final boolean above = price > vmax;
		final boolean below = price < vmin;
		final Font wordFont = new Font(Font.SANS_SERIF, Font.PLAIN, 9);
		final Font priceFont = new Font(Font.SANS_SERIF, Font.BOLD, 10);
		final String shown = above ? word + " ↑" : below ? word + " ↓" : word;
		final String value = String.format(Locale.US, "%,d", price);
		final int wordW = g.getFontMetrics(wordFont).stringWidth(shown);
		final int valueW = g.getFontMetrics(priceFont).stringWidth(value);
		final double padX = 5.5;
		final double bw = padX * 2 + wordW + 4 + valueW;
		final double bh = 15;
		final double bx = left ? x0 + 4 : x0 + w - bw - 4;
		double cy;
		if (above || below)
		{
			cy = above ? y0 + 2 + bh / 2 : y0 + hPrice - 2 - bh / 2;
		}
		else
		{
			final double py = ypx.applyAsDouble(price);
			g.setColor(c);
			g.setStroke(dashed(1.4f));
			g.draw(new Line2D.Double(x0, py, x0 + w, py));
			g.setStroke(new BasicStroke(1f));
			cy = py - 7.5 - 3;
			if (cy - bh / 2 < y0 + 1)
			{
				cy = py + 7.5 + 3;
			}
		}
		g.setColor(BADGE_PLATE);
		g.fill(new RoundRectangle2D.Double(bx, cy - bh / 2, bw, bh, 6, 6));
		g.setFont(wordFont);
		g.setColor(alpha(c, 0.62));
		final double base = cy + g.getFontMetrics(priceFont).getAscent() / 2.0 - 1;
		g.drawString(shown, (float) (bx + padX), (float) base);
		g.setFont(priceFont);
		g.setColor(c);
		g.drawString(value, (float) (bx + padX + wordW + 4), (float) base);
	}

	private static void drawHover(Graphics2D g, Rectangle area, Data d, Style st, int i, Point mouse, double x,
		int x0, int y0, int w, int h, double hPrice, double vmin, double vmax, Font axisFont)
	{
		g.setColor(CROSSHAIR);
		g.setStroke(dashed(1f));
		g.draw(new Line2D.Double(x, y0, x, y0 + h));
		final boolean inPrice = mouse.y <= y0 + hPrice;
		if (inPrice)
		{
			g.draw(new Line2D.Double(x0, mouse.y, x0 + w, mouse.y));
		}
		g.setStroke(new BasicStroke(1f));
		final Font pillFont = axisFont.deriveFont(Font.BOLD);
		g.setFont(pillFont);
		final FontMetrics fm = g.getFontMetrics();
		if (inPrice)
		{
			final double v = vmin + (1 - (mouse.y - y0) / hPrice) * (vmax - vmin);
			/* At the axis as on the site, or further left when a wide label
			   (51.42K, 15.12M) would run over the panel's border. */
			final String label = fmtYAxis(v, 0);
			pill(g, label, Math.min(x0 + w + 2, area.x + area.width - 2 - (fm.stringWidth(label) + 10)), mouse.y - 8, fm);
		}
		final long span = d.t[d.size() - 1] - d.t[0];
		final String when = DateTimeFormatter.ofPattern(span <= 2 * 86_400L ? "HH:mm" : "MMM d HH:mm", Locale.US)
			.format(Instant.ofEpochSecond(d.t[i]).atZone(ZoneId.systemDefault()));
		final int tw = fm.stringWidth(when) + 10;
		pill(g, when, (int) Math.max(x0, Math.min(x0 + w - tw, x - tw / 2.0)), y0 + h + 2, fm);

		final List<String[]> rows = tooltipRows(d, i);
		final Font tipFont = new Font(Font.SANS_SERIF, Font.PLAIN, 10);
		final FontMetrics tm = g.getFontMetrics(tipFont);
		/* The mark row is the site's .tip-marker, font-weight 800 (app.css:1293). */
		final Font markFont = tipFont.deriveFont(Font.BOLD);
		final FontMetrics mm = g.getFontMetrics(markFont);
		final int markW = 12;
		int tipW = 0;
		for (String[] r : rows)
		{
			tipW = Math.max(tipW, isMark(r) ? mm.stringWidth(r[0]) + markW : tm.stringWidth(r[0]));
		}
		tipW += 18;
		final int lineH = (int) Math.round(tm.getHeight() * 1.15);
		final int tipH = lineH * rows.size() + 12;
		int tx = mouse.x + 15;
		int ty = mouse.y + 15;
		/* Flipped before it would touch the area's last column or row,
		   the overlay panel's border. */
		if (tx + tipW > area.x + area.width - 1)
		{
			tx = mouse.x - 15 - tipW;
		}
		if (ty + tipH > area.y + area.height - 1)
		{
			ty = mouse.y - 15 - tipH;
		}
		tx = Math.max(area.x + 1, tx);
		ty = Math.max(area.y, ty);
		g.setColor(TIP_BG);
		g.fill(new RoundRectangle2D.Double(tx, ty, tipW, tipH, 10, 10));
		g.setColor(TIP_EDGE);
		g.draw(new RoundRectangle2D.Double(tx + 0.5, ty + 0.5, tipW - 1, tipH - 1, 10, 10));
		g.setFont(tipFont);
		int by = ty + 6 + tm.getAscent();
		for (String[] r : rows)
		{
			final String kind = r[1];
			if (kind.equals("head"))
			{
				g.setColor(Color.WHITE);
			}
			else if (kind.endsWith("buy"))
			{
				g.setColor(st.buy);
			}
			else if (kind.endsWith("sell"))
			{
				g.setColor(st.sell);
			}
			else if (kind.equals("same"))
			{
				g.setColor(SAME_PRICE);
			}
			else
			{
				g.setColor(TEXT_MUTED);
			}
			int textX = tx + 9;
			if (isMark(r))
			{
				/* ● for a Period mark, ◯ for a Recent one, as the site's row. */
				final double cy = by - tm.getAscent() / 2.0 + 1;
				final Ellipse2D dot = new Ellipse2D.Double(textX + 0.5, cy - 4, 8, 8);
				if (kind.startsWith("solid"))
				{
					g.fill(dot);
				}
				else
				{
					g.setStroke(new BasicStroke(1.3f));
					g.draw(dot);
					g.setStroke(new BasicStroke(1f));
				}
				textX += markW;
			}
			g.setFont(isMark(r) ? markFont : tipFont);
			g.drawString(r[0], textX, by);
			if ("head".equals(r[1]))
			{
				g.setColor(TIP_RULE);
				g.fillRect(tx + 9, by + 3, tipW - 18, 1);
			}
			by += lineH;
		}
	}

	/**
	 * The tooltip's rows, each {text, kind} (showTipFor, app.js:9380-9409):
	 * the time; the mark under the cursor when there is one, a Period mark
	 * winning over a Recent one (markerLabels, 8587-8595); the price, or
	 * each side with "—" for a side that did not print; the volume. A mark
	 * row's kind is "solid" or "hollow" plus its side, its glyph drawn as
	 * a shape so it does not depend on the font having one.
	 */
	static List<String[]> tooltipRows(Data d, int i)
	{
		final List<String[]> rows = new ArrayList<>();
		rows.add(new String[]{DateTimeFormatter.ofPattern("MMM d, HH:mm", Locale.US)
			.format(Instant.ofEpochSecond(d.t[i]).atZone(ZoneId.systemDefault())), "head"});
		final int[] period = extremes(d, 0);
		final int[] recent = extremes(d, recentStart(d.size()));
		if (i == period[1])
		{
			rows.add(new String[]{"Period Low", "solid-buy"});
		}
		else if (i == period[0])
		{
			rows.add(new String[]{"Period High", "solid-sell"});
		}
		else if (i == recent[1])
		{
			rows.add(new String[]{"Recent Low", "hollow-buy"});
		}
		else if (i == recent[0])
		{
			rows.add(new String[]{"Recent High", "hollow-sell"});
		}
		if (d.lo[i] > 0 && d.hi[i] > 0 && Math.abs(d.hi[i] - d.lo[i]) < 1e-9)
		{
			rows.add(new String[]{"Price: " + gp(d.hi[i]), "same"});
		}
		else
		{
			rows.add(new String[]{"Buy: " + gp(d.lo[i]), "buy"});
			rows.add(new String[]{"Sell: " + gp(d.hi[i]), "sell"});
		}
		rows.add(new String[]{"Volume: " + String.format(Locale.US, "%,d", Math.round(d.loVol[i] + d.hiVol[i])), "muted"});
		return rows;
	}

	private static boolean isMark(String[] row)
	{
		return row[1].startsWith("solid") || row[1].startsWith("hollow");
	}

	/** A price as the tooltip shows it; "—" for a side with no print (fmtGp, 1381). */
	private static String gp(double v)
	{
		return v > 0 ? String.format(Locale.US, "%,d", Math.round(v)) : "—";
	}

	private static void pill(Graphics2D g, String text, int x, int y, FontMetrics fm)
	{
		final int pw = fm.stringWidth(text) + 10;
		g.setColor(PILL);
		g.fillRect(x, y, pw, 16);
		g.setColor(PILL_EDGE);
		g.drawRect(x, y, pw, 16);
		g.setColor(PILL_TEXT);
		g.drawString(text, x + 5, y + 8 + fm.getAscent() / 2 - 1);
	}

	static void drawCentred(Graphics2D g, Rectangle area, String text, Color c, int px)
	{
		g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, px));
		final FontMetrics fm = g.getFontMetrics();
		g.setColor(c);
		g.drawString(text, area.x + (area.width - fm.stringWidth(text)) / 2,
			area.y + (area.height + fm.getAscent()) / 2 - 2);
	}

	private PriceChart()
	{
	}
}

