/**
 * The pocketge.com price chart, over the chat while a Grand Exchange offer
 * is open — the place the price is being decided.
 *
 * Asked for after seeing another plugin's chart there: "make the chart
 * match the color theme + add the volume price bar + be dotted + match all
 * chart settings you use on pocketge". So the painting is PriceChart, a
 * port of the site's own; this class only decides when and where it shows,
 * draws the header, the range buttons and VP toggle, and takes clicks: the
 * buttons, the top edge (drag to resize), and the site's own zoom — the
 * wheel zooms time toward the newest prices, a drag moves round the chart,
 * the price axis drags to scale the prices and the dates to zoom time, and
 * a double-click goes back to everything.
 *
 * It stands aside whenever the chat is wanted: during the item search and
 * while a price or quantity prompt is open (any chat input layer), and
 * when the chat itself is hidden. Over a price or quantity box a small
 * "Chart" button above PocketGE's price chip brings it back, and the same
 * button, then reading "Price", puts the box back — to flick between the
 * two while deciding.
 */
@Singleton
class PriceChartOverlay extends Overlay
{
	/** What the chart needs from the plugin. Called on the client thread,
	 *  every frame: lookups only, never a request. */
	interface Feed
	{
		/** The series to draw for an item and range, or null while it
		 *  loads (asking for it is the plugin's business). */
		TradeEngine.Series series(int itemId, PriceChart.Range range);

		/** Whether prices may be fetched at all — the advisor switch. */
		boolean pricesOn();

		Advisor.Quote quote(int itemId);

		/** The target the offer screen quotes for that side, or 0. */
		long target(int itemId, boolean buy);

		String name(int itemId);

		/** Where PocketGE's price or quantity chip sits in the chat while a
		 *  number box is open, or null — the toggle button goes above it. */
		Rectangle promptChip();
	}

	/** Header height above the plot. */
	static final int HEADER = 20;
	/** The shortest the panel can be dragged: the header and a plot still
	 *  worth reading (or the chat's own height, if that is less). */
	static final int MIN_HEIGHT = 110;
	/** Kept clear at the top of the game when the panel is dragged tall. */
	static final int TOP_MARGIN = 4;
	/** The grab strip on the panel's top edge reaches this far above it,
	 *  and this far into it — short of the header's buttons. The grip's
	 *  two bars are drawn inside it. */
	private static final int GRIP_ABOVE = 4;
	private static final int GRIP_BELOW = 4;
	/** The Chart / Price toggle over a number box. */
	private static final int TOGGLE_W = 50;
	private static final int TOGGLE_H = 15;
	/** The chat's height when it has never been seen open this session. */
	private static final int CHAT_HEIGHT = 142;
	private static final Color BG = new Color(0x13, 0x11, 0x10, 0xF5);
	private static final Color EDGE = new Color(0x2B, 0x26, 0x21);
	private static final Color BUTTON_ON = new Color(0x3C, 0x35, 0x2B);

	private final Client client;
	private final PocketGeTrackerConfig config;
	private volatile Feed feed;

	/** Set during render, read by the mouse listeners: the panel, each
	 *  button's box by its action ("D1".."Y1", "vp", "reset"), the strip
	 *  along the top edge that resizes it, the chat area it stands on, and
	 *  the Chart / Price toggle over a number box. */
	private volatile Rectangle panel;
	private volatile Map<String, Rectangle> buttons = Map.of();
	private volatile Rectangle grip;
	private volatile Rectangle chatArea;
	private volatile Rectangle toggle;
	/** The chat area as last seen open, for its height while it is shut. */
	private Rectangle lastOpenChat;

	/** A drag of the top edge in progress: the panel's height while it is
	 *  held (drawn live, saved on release), or -1. */
	private volatile int dragHeight = -1;
	private int dragStartY;
	private int dragStartHeight;

	/** Shown over an open price or quantity box, by the toggle. Cleared
	 *  when the box closes or is swapped for the other, so the next one
	 *  opens on the box. */
	private volatile boolean overPrompt;
	/** The number box open last frame. Client thread. */
	private GeOfferPriceOverlay.NumberBox lastBox = GeOfferPriceOverlay.NumberBox.NONE;

	/**
	 * The time zoom, as the site's: 1 to {@link PriceChart#ZOOM_MAX}, and
	 * the first point shown, -1 while it is pinned to the newest. Kept for
	 * one item and range; another of either starts at everything again.
	 */
	private volatile double zoom = 1;
	private volatile int zoomOffset = -1;
	private volatile String zoomFor = "";
	/** What the last frame drew, for a drag to pan by: the series' length,
	 *  the window and where it started, and px per point. */
	private volatile int viewN;
	private volatile int viewWin;
	private volatile int viewStart;
	private volatile double viewStepX;
	private int panStartX = Integer.MIN_VALUE;
	private int panStartOffset;

	/** The price scale as dragged, and the prices as slid — the site's
	 *  yScale and yOffset, kept with the time zoom for one item and range. */
	private volatile double yScale = 1;
	private volatile double yOffset = 0;
	/** Where the last frame put the price axis and the time strip, and how
	 *  tall the prices were: what a press is tested against. */
	private volatile int viewAxisX = Integer.MAX_VALUE;
	private volatile int viewPlotBottom = Integer.MAX_VALUE;
	private volatile double viewHPrice;

	/** What a press on the plot area grabs. */
	enum Zone
	{
		NONE,
		/** The chart itself: drag to move round it. */
		PLOT,
		/** The price axis: drag up or down to squash or stretch it. */
		PRICE_AXIS,
		/** The dates along the bottom: drag left or right to zoom time. */
		TIME_AXIS
	}

	private volatile Zone drag = Zone.NONE;
	private int dragLastX;
	private int dragLastY;

	@Inject
	private PriceChartOverlay(Client client, PocketGeTrackerConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void setFeed(Feed feed)
	{
		this.feed = feed;
	}

	/**
	 * Whether the chart is up over an open price or quantity box, covering
	 * PocketGE's chip — read by GeOfferPriceOverlay, which renders first.
	 * Only while the chart really drew there last frame (not when it has
	 * been switched off, or the chat is gone), and only over the box it
	 * went over: one swapped in place since is not covered.
	 */
	boolean overPrompt()
	{
		return overPrompt && panel != null && toggle != null && GeOfferPriceOverlay.openNumberBox(client) == lastBox;
	}

	/** Forget every click target: the game is leaving the screens this is
	 *  drawn on, and nothing is drawn to replace them until it is back. */
	void forget()
	{
		panel = null;
		grip = null;
		toggle = null;
		buttons = Map.of();
		dragHeight = -1;
		panStartX = Integer.MIN_VALUE;
		drag = Zone.NONE;
	}

	/** The offer on screen: item, side and the price set in it. */
	static final class Shown
	{
		final int itemId;
		final boolean buy;
		final long offerPrice;

		Shown(int itemId, boolean buy, long offerPrice)
		{
			this.itemId = itemId;
			this.buy = buy;
			this.offerPrice = offerPrice;
		}
	}

	/**
	 * What offer the screen is showing, or null when there is none. The
	 * game shows one of two panels for a selected slot
	 * (ge_offers_switchpanel): "Set up offer" for an empty slot, with the
	 * item picked in the search, the Buy/Sell side and the price in the
	 * screen's own price box; or "Offer status" for a placed offer, whose
	 * own item, side and price are read from the slot. Whether the chat is
	 * free to cover is chatFree's business.
	 */
	Shown shown()
	{
		final boolean setup = visible(InterfaceID.GeOffers.SETUP);
		if (!setup && !visible(InterfaceID.GeOffers.DETAILS))
		{
			return null;
		}
		if (setup)
		{
			final int item = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
			if (item <= 0)
			{
				return null;
			}
			/* The price box is a 64-bit varp since prices may pass max cash:
			   the int getter cannot read it. */
			return new Shown(item, client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE) == 0,
				Math.max(0L, client.getVarpLongValue(VarPlayerID.GE_NEWOFFER_PRICE)));
		}
		final int slot = client.getVarbitValue(VarbitID.GE_SELECTEDSLOT) - 1;
		final GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (slot < 0 || offers == null || slot >= offers.length || offers[slot] == null || offers[slot].getItemId() <= 0)
		{
			return null;
		}
		final GrandExchangeOffer o = offers[slot];
		final GrandExchangeOfferState st = o.getState();
		final boolean buy = st == GrandExchangeOfferState.BUYING || st == GrandExchangeOfferState.BOUGHT
			|| st == GrandExchangeOfferState.CANCELLED_BUY;
		return new Shown(o.getItemId(), buy, Math.max(0L, o.getPrice()));
	}

	private boolean visible(int component)
	{
		final Widget w = client.getWidget(component);
		return w != null && !w.isHidden();
	}

	/**
	 * RuneLite draws an ABOVE_WIDGETS overlay only after these toplevels
	 * (OverlayManager.rebuildOverlayLayers). Under any other — the welcome
	 * screen's TOPLEVEL_DISPLAY (165), the full-screen world map — render
	 * is not called, and the last frame's click targets are stale: pressed
	 * there, they ate the welcome screen's "Click here to play".
	 */
	static boolean drawnUnder(int toplevel)
	{
		return toplevel == InterfaceID.TOPLEVEL || toplevel == InterfaceID.TOPLEVEL_OSRS_STRETCH
			|| toplevel == InterfaceID.TOPLEVEL_PRE_EOC;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		/* The click targets are built here and published once, at the end:
		   the mouse listener runs on another thread, and a press landing
		   mid-frame must still find this frame's buttons, not none. */
		Rectangle drawn = null;
		Rectangle tog = null;
		Map<String, Rectangle> hit = Map.of();
		try
		{
			final Map<String, Rectangle> boxes = new LinkedHashMap<>();
			final Rectangle[] togOut = new Rectangle[1];
			drawn = draw(g, boxes, togOut);
			tog = togOut[0];
			if (drawn != null)
			{
				hit = boxes;
			}
		}
		finally
		{
			buttons = hit;
			grip = drawn != null ? gripOf(drawn) : null;
			toggle = tog;
			panel = drawn;
		}
		return null;
	}

	/**
	 * The panel's box: the chat area's width, standing on its bottom edge,
	 * {@code height} tall — 0 for the chat's own height — and kept between
	 * MIN_HEIGHT (or the chat's height, if less) and the top of the game.
	 * It grows upward over the game, never down over the chat's tabs.
	 */
	static Rectangle panelBox(Rectangle chat, int height)
	{
		final int bottom = chat.y + chat.height;
		final int min = Math.min(MIN_HEIGHT, chat.height);
		final int max = Math.max(min, bottom - TOP_MARGIN);
		final int h = Math.max(min, Math.min(max, height > 0 ? height : chat.height));
		return new Rectangle(chat.x, bottom - h, chat.width, h);
	}

	/** The strip along the panel's top edge that drags it taller or shorter. */
	static Rectangle gripOf(Rectangle box)
	{
		return new Rectangle(box.x, box.y - GRIP_ABOVE, box.width, GRIP_ABOVE + GRIP_BELOW);
	}

	/**
	 * The Chart / Price toggle: in the top-right corner of whatever is
	 * showing — the chat, above the price chip, or the chart's header,
	 * where the range buttons make room for it. It sat just over the chip,
	 * which over the chart put it on the price axis and the offer's badge
	 * ("price label in the way").
	 */
	static Rectangle toggleOf(Rectangle area)
	{
		return new Rectangle(area.x + area.width - 6 - TOGGLE_W, area.y + 5, TOGGLE_W, TOGGLE_H);
	}

	/**
	 * Where the toggle goes: the chat's top-right corner, above the price
	 * chip, in both states — so flicking to the chart and back is two clicks
	 * in one place — except over a chart dragged taller than the chat.
	 *
	 * With the chart down it is always the chat's corner. It once followed
	 * where a taller chart's header WOULD be, which with no chart drawn put a
	 * button over the game view and the Exchange window that ate the clicks
	 * meant for them.
	 *
	 * A chart taller than the chat carries it in its own header instead:
	 * there the chat's corner is part way down the price axis, and a button
	 * on the axis is "price label in the way" again. At the chat's height or
	 * shorter the chat's corner is in or above the chart's header, where the
	 * range buttons make room for it (toggleInHeader) and the drag edge
	 * stands aside (overGrip).
	 */
	static Rectangle toggleFor(Rectangle chat, Rectangle box, boolean chartUp)
	{
		return toggleOf(chartUp && box.y < chat.y ? box : chat);
	}

	/** Whether the toggle reaches into the chart's header row, where the
	 *  range buttons must leave it room. A chart a few pixels shorter than the
	 *  chat has its header just under the toggle's top, not around it. */
	static boolean toggleInHeader(Rectangle tog, Rectangle box)
	{
		return tog != null && tog.y < box.y + HEADER && tog.y + tog.height > box.y;
	}

	/** On the chart's drag edge, and not on the toggle: where the two meet
	 *  a press is the toggle's (it is tested first), so the edge must not
	 *  light up there as if it would drag. */
	static boolean overGrip(Rectangle box, Rectangle tog, int x, int y)
	{
		return gripOf(box).contains(x, y) && (tog == null || !tog.contains(x, y));
	}

	/** What the header's buttons leave free on the right for the toggle. */
	static final int TOGGLE_ROOM = TOGGLE_W + 8;

	/** Paint this frame's chart, if one should be up, filling {@code hit};
	 *  the panel's box, or null for none. The toggle over a number box, if
	 *  drawn, goes in {@code togOut[0]}. */
	private Rectangle draw(Graphics2D g, Map<String, Rectangle> hit, Rectangle[] togOut)
	{
		final Feed f = feed;
		final GeOfferPriceOverlay.NumberBox open = GeOfferPriceOverlay.openNumberBox(client);
		final boolean numberBox = open != GeOfferPriceOverlay.NumberBox.NONE;
		if (open != lastBox)
		{
			/* The box closed, or the game swapped it for the other in place
			   (the price box straight to the quantity box, with no closed
			   frame between): the next one opens on the box. */
			lastBox = open;
			overPrompt = false;
		}
		if (f == null || !config.priceChart())
		{
			return null;
		}
		final Shown s = shown();
		if (s == null)
		{
			return null;
		}
		final net.runelite.api.Point mp = client.getMouseCanvasPosition();
		/* Over a price or quantity box: the toggle above PocketGE's chip,
		   and the chart only while it is flicked on. Any other chat input —
		   the item search — and the chart stands aside. */
		final int mode = client.getVarcIntValue(VarClientID.MESLAYERMODE);
		final Rectangle cb = chatBounds();
		if (cb == null || cb.width < 200 || cb.height < 80)
		{
			return null;
		}
		final boolean toggleUp = numberBox && f.promptChip() != null;
		final int dragging = dragHeight;
		final Rectangle box = panelBox(cb, dragging >= 0 ? dragging : config.chartHeight());
		if (mode != 0 && (!toggleUp || !overPrompt))
		{
			if (toggleUp)
			{
				final Rectangle tog = toggleFor(cb, box, false);
				drawToggle(g, tog, "Chart", mp != null && tog.contains(mp.getX(), mp.getY()));
				togOut[0] = tog;
			}
			return null;
		}
		chatArea = new Rectangle(cb);
		final PriceChart.Range range = PriceChart.Range.of(config.chartRange());
		final TradeEngine.Series series = f.series(s.itemId, range);
		final PriceChart.Data data = series != null ? PriceChart.prepare(series, range.periodSec) : null;

		/* The zoom belongs to one item and range. */
		final String key = s.itemId + "/" + range.name();
		if (!key.equals(zoomFor))
		{
			zoomFor = key;
			resetZoom();
		}
		PriceChart.Data view = data;
		final boolean zoomed;
		if (data != null && data.size() > 0)
		{
			final int n = data.size();
			final int win = PriceChart.window(n, zoom);
			final int start = PriceChart.windowStart(n, win, zoomOffset);
			view = PriceChart.slice(data, start, start + win);
			viewN = n;
			viewWin = win;
			viewStart = start;
			zoomed = win < n;
		}
		else
		{
			viewN = 0;
			zoomed = false;
		}
		final boolean adjusted = zoomed || yScale != 1 || yOffset != 0;

		final Rectangle tog = toggleUp ? toggleFor(cb, box, true) : null;
		/* Over the toggle the pointer is on a button, not the chart: no
		   crosshair under it, and no lit drag edge. */
		final boolean onToggle = tog != null && mp != null && tog.contains(mp.getX(), mp.getY());
		/* Nor while dragging: a crosshair riding along with a pan or an axis
		   drag reads one price after another at nothing in particular. */
		final Point mouse = mp != null && !onToggle && drag == Zone.NONE && box.contains(mp.getX(), mp.getY())
			? new Point(mp.getX(), mp.getY()) : null;
		final boolean gripHot = dragging >= 0 || (mp != null && overGrip(box, tog, mp.getX(), mp.getY()));

		final PriceChart.Style style = new PriceChart.Style();
		final PocketGeTrackerConfig.ColourTheme theme = config.colourTheme();
		if (theme != null)
		{
			style.buy = theme.buy();
			style.sell = theme.sell();
		}
		style.vp = config.chartVolumeProfile();
		style.yScale = yScale;
		style.yOffset = yOffset;
		style.axisHot = drag == Zone.PRICE_AXIS || (drag == Zone.NONE && mouse != null
			&& zone(mouse.x, mouse.y, box.y + HEADER, viewAxisX, viewPlotBottom, viewN) == Zone.PRICE_AXIS);
		final PriceChart.Lines lines = new PriceChart.Lines();
		lines.target = f.target(s.itemId, s.buy);
		lines.targetBuy = s.buy;
		lines.offer = s.offerPrice;

		final PriceChart.Layout lay = paint(g, box, f.name(s.itemId), f.quote(s.itemId), range, data, view, adjusted,
			series == null, f.pricesOn(), style, lines, mouse, gripHot,
			toggleInHeader(tog, box) ? TOGGLE_ROOM : 0, hit);
		viewStepX = lay != null ? lay.stepX : 0;
		viewAxisX = lay != null ? lay.x0 + lay.w : Integer.MAX_VALUE;
		viewPlotBottom = lay != null ? lay.y0 + lay.h : Integer.MAX_VALUE;
		viewHPrice = lay != null ? lay.h : 0;
		if (tog != null)
		{
			/* Where Chart was, now putting the box back. */
			drawToggle(g, tog, "Price", onToggle);
			togOut[0] = tog;
		}
		return box;
	}

	/**
	 * Where the chat area is: its own box while it is open, or — when the
	 * player has shut the chat with a tab — the same box standing on the tab
	 * bar, at the height it last had open. The chart is wanted all the same
	 * ("as soon as i click uncut diamond, the chart should appear").
	 */
	private Rectangle chatBounds()
	{
		final Widget chat = client.getWidget(InterfaceID.Chatbox.CHATAREA);
		if (chat != null && !chat.isHidden())
		{
			final Rectangle cb = chat.getBounds();
			if (cb != null && cb.width >= 200 && cb.height >= 80)
			{
				lastOpenChat = new Rectangle(cb);
				return cb;
			}
		}
		final Widget tabs = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		if (tabs == null || tabs.isHidden())
		{
			return null;
		}
		final Rectangle tb = tabs.getBounds();
		if (tb == null || tb.width < 200)
		{
			return null;
		}
		final int h = lastOpenChat != null ? lastOpenChat.height : CHAT_HEIGHT;
		final int w = lastOpenChat != null ? lastOpenChat.width : tb.width;
		return new Rectangle(tb.x, tb.y - h, w, h);
	}

	/** The small Chart / Price toggle above the chip, in the chip's gold. */
	static void drawToggle(Graphics2D g0, Rectangle r, String label, boolean hover)
	{
		final Graphics2D g = (Graphics2D) g0.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setColor(hover ? new Color(0xF2, 0xD3, 0x75) : new Color(0xE5, 0xC1, 0x58));
			g.fillRect(r.x, r.y, r.width, r.height);
			g.setColor(new Color(0x6B, 0x55, 0x1C));
			g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
			final FontMetrics fm = g.getFontMetrics();
			g.setColor(new Color(0x1A, 0x14, 0x05));
			g.drawString(label, r.x + (r.width - fm.stringWidth(label)) / 2, r.y + (r.height + fm.getAscent()) / 2 - 2);
		}
		finally
		{
			g.dispose();
		}
	}

	/**
	 * The whole panel, for the overlay and for rendering off the client:
	 * background, header, then the chart or a line saying why there is
	 * none. {@code data} is the range's series, which the header's change
	 * is worked out from; {@code view} the window of it the zoom shows,
	 * which is what is drawn; {@code zoomed}, that the time zoom or the
	 * price scale has been moved, which puts up Reset zoom. Fills
	 * {@code hit} with the buttons' boxes.
	 * {@code gripHot}: the mouse is on the top edge, or dragging it. The
	 * plot's layout, or null when there was nothing to plot.
	 */
	static PriceChart.Layout paint(Graphics2D g0, Rectangle box, String name, Advisor.Quote q, PriceChart.Range range,
		PriceChart.Data data, PriceChart.Data view, boolean zoomed, boolean loading, boolean pricesOn,
		PriceChart.Style style, PriceChart.Lines lines, Point mouse, boolean gripHot, int rightReserve,
		Map<String, Rectangle> hit)
	{
		final Graphics2D g = (Graphics2D) g0.create();
		try
		{
			g.clip(box); // nothing past the chat it covers
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setColor(BG);
			g.fillRect(box.x, box.y, box.width, box.height);
			g.setColor(EDGE);
			g.drawRect(box.x, box.y, box.width - 1, box.height - 1);
			/* The top edge drags: a small grip in the middle says so, inside
			   the strip that takes the press and above the header's text, and
			   the edge lights while it is under the mouse or held. */
			if (gripHot)
			{
				g.setColor(style.buy);
				g.fillRect(box.x, box.y, box.width, 1);
			}
			g.setColor(gripHot ? style.buy : PriceChart.TEXT_MUTED);
			final int gx = box.x + box.width / 2 - 14;
			g.fillRect(gx, box.y + 1, 28, 1);
			g.fillRect(gx + 4, box.y + 3, 20, 1);

			/* buttons, right-aligned: Reset while zoomed, the ranges, a gap,
			   then VP */
			final Font bf = new Font(Font.SANS_SERIF, Font.BOLD, 10);
			g.setFont(bf);
			final FontMetrics fm = g.getFontMetrics();
			final int ranges = PriceChart.Range.values().length;
			final String[][] specs = new String[ranges + (zoomed ? 2 : 1)][];
			int k = 0;
			if (zoomed)
			{
				specs[k++] = new String[]{"reset", "Reset zoom", "off"};
			}
			final int firstRange = k;
			for (PriceChart.Range r : PriceChart.Range.values())
			{
				specs[k++] = new String[]{r.name(), r.label, r == range ? "on" : "off"};
			}
			specs[k] = new String[]{"vp", "VP", style.vp ? "on" : "off"};
			int bx = box.x + box.width - 6 - Math.max(0, rightReserve);
			for (int i = specs.length - 1; i >= 0; i--)
			{
				final int bw = fm.stringWidth(specs[i][1]) + 10;
				bx -= bw;
				if (i == firstRange + ranges - 1)
				{
					bx -= 8; // a gap between the ranges and the toggle
				}
				if (zoomed && i == 0)
				{
					bx -= 8; // and between Reset and the ranges
				}
				final Rectangle r = new Rectangle(bx, box.y + 5, bw, 14);
				hit.put(specs[i][0], r);
				bx -= 2;
			}
			for (String[] spec : specs)
			{
				final Rectangle r = hit.get(spec[0]);
				final boolean on = "on".equals(spec[2]);
				final boolean outlined = "vp".equals(spec[0]) || "reset".equals(spec[0]);
				final boolean hover = mouse != null && r.contains(mouse);
				if (on && !outlined)
				{
					g.setColor(BUTTON_ON);
					g.fillRoundRect(r.x, r.y, r.width, r.height, 4, 4);
				}
				if (outlined)
				{
					g.setColor(EDGE);
					g.drawRoundRect(r.x, r.y, r.width - 1, r.height - 1, 4, 4);
				}
				/* The toggle lights in the buy colour when on, as the site's
				   aria-pressed buttons do; the active range goes white. */
				g.setColor("vp".equals(spec[0]) ? (on ? style.buy : PriceChart.TEXT_MUTED)
					: on ? Color.WHITE : hover ? PriceChart.TEXT_MAIN : PriceChart.TEXT_MUTED);
				g.drawString(spec[1], r.x + (r.width - fm.stringWidth(spec[1])) / 2, r.y + 11);
			}

			/* header: name, the live price and the range's change, after the
			   buttons and kept left of them — a long name with a 10-digit
			   price ran under Reset zoom. The name gives way first, with an
			   ellipsis; the price and the change are what the header is for. */
			int leftmost = box.x + box.width;
			for (Rectangle r : hit.values())
			{
				leftmost = Math.min(leftmost, r.x);
			}
			final int limit = leftmost - 6;
			final int baseY = box.y + 15;
			final Font nameFont = new Font(Font.SANS_SERIF, Font.BOLD, 11);
			final Font valueFont = new Font(Font.SANS_SERIF, Font.PLAIN, 11);
			final FontMetrics vfm = g.getFontMetrics(valueFont);
			final long last = q == null ? 0 : q.high > 0 ? q.high : q.low;
			final String price = last > 0 ? String.format(Locale.US, "%,d gp", last) : null;
			final double pct = data != null && data.size() > 1 ? PriceChart.pctChange(data) : Double.NaN;
			final String change = Double.isNaN(pct) ? null : String.format(Locale.US, "%+.2f%%", pct);
			int x = box.x + 8;
			final int tail = (price != null ? vfm.stringWidth(price) + 6 : 0) + (change != null ? vfm.stringWidth(change) : 0);
			final String title = fit(name != null ? name : "", g.getFontMetrics(nameFont), limit - x - 8 - tail);
			final Graphics2D hg = (Graphics2D) g.create();
			try
			{
				hg.clipRect(box.x, box.y, Math.max(0, limit - box.x), HEADER); // a narrow chat cuts the tail, never a button
				hg.setFont(nameFont);
				hg.setColor(PriceChart.TEXT_MAIN);
				hg.drawString(title, x, baseY);
				x += hg.getFontMetrics().stringWidth(title) + 8;
				hg.setFont(valueFont);
				if (price != null)
				{
					hg.drawString(price, x, baseY);
					x += vfm.stringWidth(price) + 6;
				}
				if (change != null)
				{
					hg.setColor(pct > 0.004 ? PriceChart.POSITIVE : pct < -0.004 ? PriceChart.NEGATIVE : PriceChart.TEXT_MUTED);
					hg.drawString(change, x, baseY);
				}
			}
			finally
			{
				hg.dispose();
			}

			final Rectangle plot = new Rectangle(box.x, box.y + HEADER, box.width, box.height - HEADER);
			if (view != null && view.size() > 0)
			{
				return PriceChart.paint(g, plot, view, style, lines, mouse);
			}
			PriceChart.drawCentred(g, plot, !pricesOn && loading
				? "Prices are off — the Flip advisor switch turns them on."
				: loading ? "Loading " + range.label + " prices…"
				: "No trade data for this timeframe — try a longer one.", PriceChart.TEXT_MUTED, 12);
			return null;
		}
		finally
		{
			g.setStroke(new BasicStroke(1f));
			g.dispose();
		}
	}

	/** {@code s}, or as much of it as fits in {@code w} px with an ellipsis. */
	static String fit(String s, FontMetrics fm, int w)
	{
		if (fm.stringWidth(s) <= w)
		{
			return s;
		}
		for (int n = s.length() - 1; n > 0; n--)
		{
			final String t = s.substring(0, n).trim() + "…";
			if (fm.stringWidth(t) <= w)
			{
				return t;
			}
		}
		return "";
	}

	/** Whether the mouse may act on what the last frame drew: logged in,
	 *  under a toplevel the overlay is drawn on, and no right-click menu
	 *  open — its entries, drawn over the chart, take the press. */
	private boolean live()
	{
		return client.getGameState() == GameState.LOGGED_IN && drawnUnder(client.getTopLevelInterfaceId())
			&& !client.isMenuOpen();
	}

	/** Left presses on the chart: a button acts, the top edge drags the
	 *  panel taller or shorter (a double-click puts it back to the chat's
	 *  height), and below the header, as on the site, the price axis drags
	 *  up and down to squash or stretch the prices, the dates drag left and
	 *  right to zoom time, and the chart itself drags to move round it —
	 *  each put back by a double-click on it, everything by one on the
	 *  chart. Every press inside it is kept from the chat underneath. The
	 *  toggle above a price chip flicks the chart over the box and back. */
	final MouseAdapter mouse = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			if (dragHeight >= 0)
			{
				endDrag(); // its release never came (let go outside the window)
			}
			panStartX = Integer.MIN_VALUE;
			drag = Zone.NONE;
			if (!SwingUtilities.isLeftMouseButton(e) || !live())
			{
				return e;
			}
			final Rectangle tog = toggle;
			if (tog != null && tog.contains(e.getPoint()))
			{
				overPrompt = !overPrompt;
				e.consume();
				return e;
			}
			final Rectangle p = panel;
			if (p == null)
			{
				return e;
			}
			final Rectangle edge = grip;
			if (edge != null && edge.contains(e.getPoint()))
			{
				if (e.getClickCount() >= 2)
				{
					dragHeight = -1;
					config.setChartHeight(0);
				}
				else
				{
					dragStartY = e.getY();
					dragStartHeight = p.height;
					dragHeight = p.height;
				}
				e.consume();
				return e;
			}
			if (!p.contains(e.getPoint()))
			{
				return e;
			}
			final Map<String, Rectangle> bs = buttons;
			for (Map.Entry<String, Rectangle> b : bs.entrySet())
			{
				if (b.getValue().contains(e.getPoint()))
				{
					press(b.getKey());
					e.consume();
					return e;
				}
			}
			final Zone z = zone(e.getX(), e.getY(), p.y + HEADER, viewAxisX, viewPlotBottom, viewN);
			if (e.getClickCount() >= 2)
			{
				/* A double-click puts back what that part moves: the price
				   axis its scale, the dates the time zoom, the chart both
				   (app.js:9682-9686). */
				if (z == Zone.PRICE_AXIS)
				{
					yScale = 1;
					yOffset = 0;
				}
				else if (z == Zone.TIME_AXIS)
				{
					zoom = 1;
					zoomOffset = -1;
				}
				else if (z == Zone.PLOT)
				{
					resetZoom();
				}
			}
			else if (z != Zone.NONE)
			{
				drag = z;
				dragLastX = e.getX();
				dragLastY = e.getY();
				panStartX = e.getX();
				panStartOffset = viewStart;
			}
			e.consume();
			return e;
		}

		@Override
		public MouseEvent mouseDragged(MouseEvent e)
		{
			if (dragHeight >= 0)
			{
				final Rectangle cb = chatArea;
				if (cb != null)
				{
					/* Never 0 or less, which panelBox reads as "the chat's
					   own height": dragged down past the chat, it stays at
					   its shortest. */
					dragHeight = panelBox(cb, Math.max(1, dragStartHeight + (dragStartY - e.getY()))).height;
				}
				e.consume();
				return e;
			}
			final Zone z = drag;
			if (z == Zone.NONE)
			{
				return e;
			}
			final int dx = e.getX() - dragLastX;
			final int dy = e.getY() - dragLastY;
			dragLastX = e.getX();
			dragLastY = e.getY();
			switch (z)
			{
				case PLOT:
					/* Both ways at once, as the site's: the time window
					   follows the pointer (once zoomed, so there is
					   somewhere to go), and the prices follow it up and
					   down. */
					pan(e.getX());
					yOffset = PriceChart.yOffsetAfter(yOffset, dy, viewHPrice);
					break;
				case PRICE_AXIS:
					yScale = PriceChart.yScaleAfter(yScale, dy);
					break;
				case TIME_AXIS:
					/* Right zooms in, as the wheel's direction, and the
					   newest prices stay in view (app.js:9506-9510). */
					zoom = zoomAfter(zoom, Math.exp(dx / 150.0));
					zoomOffset = -1;
					break;
				default:
			}
			e.consume();
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			if (drag != Zone.NONE)
			{
				drag = Zone.NONE;
				panStartX = Integer.MIN_VALUE;
				e.consume();
				return e;
			}
			if (dragHeight < 0)
			{
				return e;
			}
			endDrag();
			e.consume();
			return e;
		}
	};

	/**
	 * The wheel over the chart zooms time as the site's does: each notch in
	 * by 1.2, out by 0.8, between everything and a twentieth of it, staying
	 * on the newest prices (app.js:9708-9712, anchorZoomToLatest). Taken
	 * from the game, so it neither scrolls the chat nor moves the camera.
	 */
	final MouseWheelListener wheel = new MouseWheelListener()
	{
		@Override
		public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
		{
			final Rectangle p = panel;
			if (p == null || !p.contains(e.getPoint()) || !live())
			{
				return e;
			}
			/* Nothing to zoom while it says Loading or No trade data, but
			   the turn is still not the chat's (nor the camera's). */
			if (viewN > 0)
			{
				final double factor = e.getWheelRotation() < 0 ? 1.2 : e.getWheelRotation() > 0 ? 0.8 : 1;
				zoom = zoomAfter(zoom, factor);
				zoomOffset = -1;
			}
			e.consume();
			return e;
		}
	};

	/** A zoom times {@code factor}, kept between 1 and the most. */
	static double zoomAfter(double zoom, double factor)
	{
		return Math.max(1, Math.min(PriceChart.ZOOM_MAX, zoom * factor));
	}

	/** Pan to where a drag that started at panStartX now is: the window
	 *  follows the mouse, a point per point's width. */
	private void pan(int x)
	{
		final double step = viewStepX;
		final int n = viewN;
		final int win = viewWin;
		if (step <= 0 || n <= 0 || win >= n)
		{
			return;
		}
		final int moved = (int) Math.round((x - panStartX) / step);
		zoomOffset = Math.max(0, Math.min(n - win, panStartOffset - moved));
	}

	/** Everything back: the time zoom and the price scale. */
	private void resetZoom()
	{
		zoom = 1;
		zoomOffset = -1;
		yScale = 1;
		yOffset = 0;
	}

	/**
	 * What a press at (x, y) grabs, given where the last frame drew things:
	 * the price axis first (the corner where it meets the dates reads as
	 * the price axis, as on the site), then the dates along the bottom,
	 * then the chart. Nothing above {@code plotTop} — the header — and
	 * nothing while there is no data to move.
	 */
	static Zone zone(int x, int y, int plotTop, int axisX, int plotBottom, int n)
	{
		if (n <= 0 || y < plotTop)
		{
			return Zone.NONE;
		}
		if (x >= axisX)
		{
			return Zone.PRICE_AXIS;
		}
		if (y >= plotBottom)
		{
			return Zone.TIME_AXIS;
		}
		return Zone.PLOT;
	}

	/** Keep the height the edge was let go at. */
	private void endDrag()
	{
		final int h = dragHeight;
		if (h >= 0 && h != dragStartHeight)
		{
			config.setChartHeight(h);
		}
		dragHeight = -1;
	}

	private void press(String action)
	{
		switch (action)
		{
			case "vp":
				config.setChartVolumeProfile(!config.chartVolumeProfile());
				break;
			case "reset":
				resetZoom();
				break;
			default:
				config.setChartRange(PriceChart.Range.of(action).name());
		}
	}
}

package com.pocketge.tracker;

/**
 * Where an item is sitting inside its own recent trading range, over two
 * windows at once — the last day and the last 5 days.
 *
 * This is the plugin's half of pocketge.com's ▲/▼ badge system, ported so the
 * two agree. The website computes the same thing in app.js's dayState(); the
 * thresholds and comparisons below are that function's, verbatim, because a
 * badge that fires in the browser and not in the client (or the other way
 * round) is worse than no badge — you cannot tell which one is lying.
 *
 * Deliberately free of RuneLite and okhttp imports, like {@link FinderEngine}:
 * the numbers arrive from {@link MarketClient} but the judgement about what
 * they mean is plain arithmetic, and plain arithmetic should be unit-testable
 * without a game client on the classpath.
 */
public class PriceExtremes
{
	/** Highest and lowest hourly VWAP seen in the last 24 hours. */
	public long hi1d;
	public long lo1d;
	/** …in the last 5 days. Same 1-hour series — the wiki's 1h timeseries
	 *  reaches back about 15 days, so one fetch covers both windows. */
	public long hi5d;
	public long lo5d;
	/** When the series these came from was fetched, epoch seconds; 0 if not
	 *  known. */
	public long fetchedAt;
	/** The priced hours from a day before the fetch onward, oldest first:
	 *  each hour's start, epoch seconds, and its mid — the two sides
	 *  averaged, or the one there is. What the day's change is measured
	 *  from — see {@link #midDayBefore}. */
	long[] hourTs = new long[0];
	double[] hourMid = new double[0];

	/**
	 * The mid a day before {@code nowSec}: the first priced hour at or after
	 * it, as app.js pctChange takes the first point of the day's series. 0
	 * when the hours held no longer reach back that far — about a day after
	 * the fetch.
	 *
	 * Looked up at the moment asked, not fixed at the fetch. It was one mid,
	 * a day before the fetch, given for two hours and then nothing: on the
	 * longer advisor intervals the per-item round runs once a tick, so the
	 * badges and alerts were blank six hours in every eight. The hours are
	 * history and do not change, so the mid a day before any moment the
	 * series still covers is the one a fresh fetch would give.
	 */
	public double midDayBefore(long nowSec)
	{
		final long cut = nowSec - 86400L;
		for (int i = 0; i < hourTs.length; i++)
		{
			if (hourTs[i] >= cut)
			{
				return hourMid[i];
			}
		}
		return 0;
	}

	/**
	 * The live mid against the mid a day before {@code nowSec}, as a percent:
	 * the website's 1D change, the figure beside its 1D button (app.js
	 * pctChange over the day's series), with the live quote as the day's last
	 * price. NaN when either end is missing.
	 *
	 * The watchlist's change badge measured the live mid against the Wiki's
	 * /24h average instead. That average is for the last COMPLETE day, not
	 * the last 24 hours, so after a fall it still holds the day before: Sunfire
	 * splinters read -19% in the sidebar, an average of about 322 that is
	 * nowhere on the day's chart (215 to 275), beside the website's 1D at
	 * +3.18%. "which is true?" — the website's.
	 */
	public double dayChangePct(long high, long low, long nowSec)
	{
		final double mid1dAgo = midDayBefore(nowSec);
		if (mid1dAgo <= 0 || (high <= 0 && low <= 0))
		{
			return Double.NaN;
		}
		final double mid = ((low > 0 ? low : high) + (high > 0 ? high : low)) / 2.0;
		return (mid - mid1dAgo) / mid1dAgo * 100.0;
	}
	/** Which badge, if any, the item has earned.
	 *
	 *  There is deliberately no 30-day tier, and the reason is worth keeping:
	 *  a percentage band does NOT get rarer as the window widens, it gets
	 *  commoner. The band is 8% OF THE RANGE, so a 30-day range of 1,000gp
	 *  gives an 80gp band where a 5-day range of 100gp gives an 8gp one —
	 *  ten times easier to land in. A 30-day tier stacked on top therefore
	 *  fired on nearly every row and buried the 5-day one underneath it.
	 *  The website has only these two tiers, and this is why. */
	public enum Tier
	{
		NONE,
		HIGH_1D,
		LOW_1D,
		HIGH_5D,
		LOW_5D;

		public boolean isHigh()
		{
			return this == HIGH_1D || this == HIGH_5D;
		}

	}

	/** Multi-day tiers fire anywhere in the outermost 8% of the range. A
	 *  multi-day extreme is a slow thing — insisting on touching it exactly
	 *  would mean the badge blinks off while the item is still obviously
	 *  parked at the top of its range. */
	private static final double BAND = 0.08;
	/** …but only when the range is worth having an opinion about. Without
	 *  this a near-flat item flashes on a one-gp wiggle, since 8% of almost
	 *  nothing is nothing. */
	private static final double MIN_RANGE_PCT = 0.03;
	/** The day tier is STRICT instead: the live price must actually meet or
	 *  beat the day's most extreme hourly bucket. The website tried a fuzzy
	 *  1.5% band here first and had to abandon it — intraday, almost every
	 *  favourite hangs around near its own daily edge, so nearly every row
	 *  wore an arrow all the time and the badge stopped meaning anything. */
	private static final double MIN_RANGE_PCT_1D = 0.04;

	/**
	 * @param high the live insta-buy price — what the item sells FOR right
	 *             now, hence the one to compare against range highs
	 * @param low  the live insta-sell price, compared against range lows
	 */
	public Tier tier(long high, long low)
	{
		if (inTopBand(high, hi5d, lo5d))
		{
			return Tier.HIGH_5D;
		}
		if (inBottomBand(low, hi5d, lo5d))
		{
			return Tier.LOW_5D;
		}
		/* Day tier last, and only when the day's range is at least 4% wide —
		   see MIN_RANGE_PCT_1D. */
		if (hi1d > 0 && lo1d > 0 && hi1d - lo1d >= lo1d * MIN_RANGE_PCT_1D)
		{
			if (high > 0 && high >= hi1d)
			{
				return Tier.HIGH_1D;
			}
			if (low > 0 && low <= lo1d)
			{
				return Tier.LOW_1D;
			}
		}
		return Tier.NONE;
	}

	private static boolean usableRange(long hi, long lo)
	{
		return hi > 0 && lo > 0 && hi - lo >= lo * MIN_RANGE_PCT;
	}

	private static boolean inTopBand(long high, long hi, long lo)
	{
		return usableRange(hi, lo) && high > 0 && (hi - high) / (double) (hi - lo) <= BAND;
	}

	private static boolean inBottomBand(long low, long hi, long lo)
	{
		return usableRange(hi, lo) && low > 0 && (low - lo) / (double) (hi - lo) <= BAND;
	}
}

package com.pocketge.tracker;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntPredicate;
import net.runelite.client.util.QuantityFormatter;

/**
 * "+2,000 gp" floating up off a Grand Exchange slot when a batch of its sell
 * goes through — or "-1,250 gp" in red when it lost.
 *
 * Asked for after another plugin's: "if lets say rune darts sold. it would
 * show +200gp or +2000gp or +20kgp profit. for whatever batch just sold / how
 * much profit over that square. it was very slot machine/ brain satisfying.
 * makes you want ot keep this creen open to see the money tick in", and "it
 * also showed - red gp for when you lost money on somthing".
 *
 * The figure is what the batch BOOKED: the flips its units closed, after tax,
 * against what the plugin watched you pay — the same number the flip list
 * gets. A sale with no buy on record to close is not profit, and its takings
 * dressed as profit would be the one number here that lies — so it pops the
 * coins it brought in, after tax, in gold and with no sign: "i saw sharks
 * sell but no green numkbers came up" / "oo you right i just cooked these" /
 * "yes add the gold coins pop". Green and red stay for profit and loss.
 *
 * A sale nobody saw waits for its square: "even if i missed it live, the
 * next time i load into this ge screen, it should have said +64kgp over rune
 * darts in that square". What has not been shown yet is kept on the offer's
 * own saved record — FlipTracker.unseenBy — and the overlay starts a figure
 * here the first time the square is on screen with something unshown. This
 * class is only the figures on screen and how they move.
 *
 * Holds no RuneLite types beyond the formatter, so the timing and the drawing
 * are tested without a client.
 */
final class ProfitPops
{
	/** How long one is on screen, from the pop to gone. */
	static final long LIFE_MS = 3_000;
	/** A batch this soon after the slot's last figure started is the same
	 *  sale to the eye: added to its figure, which pops again. Two game ticks —
	 *  fills on back-to-back ticks land about 600 ms apart, give or take, and
	 *  a window of exactly one tick split them at random. */
	static final long MERGE_MS = 1_200;
	/** How far it rises over its life. */
	static final int RISE_PX = 22;
	/** Fully opaque until this far through, then fades out. */
	private static final float FADE_FROM = 0.55f;
	/** Where it starts, down the slot: on the game's progress bar. */
	private static final float START_AT = 0.74f;
	private static final int[][] OUTLINE = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}, {1, 1}};
	/** One per slot, so eight; a guard, past which the oldest goes. */
	static final int MAX = 16;
	/** Brighter than TipStyle.GOOD and .BAD, which are drawn on a tooltip's
	 *  near-black: these sit on the Exchange's brown, over sprites and text,
	 *  with only a one-pixel outline to hold them off it. */
	static final Color GAIN = new Color(0x3D, 0xE0, 0x76);
	static final Color LOSS = new Color(0xFF, 0x5A, 0x55);
	static final Color EVEN = TipStyle.MUTED;
	/** Coins in, not profit: the gold of a coin stack, kept clear of the
	 *  sidebar's amber buy bar and of GAIN's green. */
	static final Color COINS = new Color(0xFF, 0xD7, 0x40);

	/** One figure on screen: which slot, when it popped, and how much —
	 *  profit, or with {@code coins} the coins a sale brought in. */
	static final class Pop
	{
		final int slot;
		final long at;
		final long profit;
		final boolean coins;

		Pop(int slot, long at, long profit)
		{
			this(slot, at, profit, false);
		}

		Pop(int slot, long at, long profit, boolean coins)
		{
			this.slot = slot;
			this.at = at;
			this.profit = profit;
			this.coins = coins;
		}
	}

	/* Started and read on the client thread, by the overlay. */
	private final List<Pop> pops = new ArrayList<>();

	/**
	 * {@code slot} has {@code profit} to show, now.
	 *
	 * One figure per slot at a time. Each rises only a line's height over its
	 * life, so two on one slot a second or so apart were drawn over each
	 * other into a smear. A batch within a moment of the slot's last figure
	 * adds to it and pops it again — the number ticking up; a later one takes
	 * the slot over with its own.
	 */
	synchronized void start(int slot, long profit, long now)
	{
		start(slot, profit, false, now);
	}

	/**
	 * As above, for a figure of {@code coins} or of profit. Only the same
	 * kind adds up — coins in and profit made are different numbers. Within
	 * that moment profit keeps the square: coins arriving just after a
	 * profit figure leave it running, as the record shows the profit when
	 * both wait at once.
	 */
	synchronized void start(int slot, long gp, boolean coins, long now)
	{
		prune(now);
		long made = gp;
		for (int i = pops.size() - 1; i >= 0; i--)
		{
			final Pop p = pops.get(i);
			if (p.slot == slot)
			{
				if (now - p.at < MERGE_MS)
				{
					if (coins && !p.coins)
					{
						return;
					}
					if (coins == p.coins)
					{
						made += p.profit;
					}
				}
				pops.remove(i);
			}
		}
		pops.add(new Pop(slot, now, made, coins));
		while (pops.size() > MAX)
		{
			pops.remove(0);
		}
	}

	/** The figures to draw at {@code now}, oldest first: those whose slot
	 *  is on screen. One whose square went away runs out unseen — it was
	 *  seen when it started. */
	synchronized List<Pop> running(long now, IntPredicate onScreen)
	{
		prune(now);
		final List<Pop> out = new ArrayList<>();
		for (Pop p : pops)
		{
			if (onScreen.test(p.slot))
			{
				out.add(p);
			}
		}
		return out;
	}

	/** Every figure off: the setting switched off. */
	synchronized void clear()
	{
		pops.clear();
	}

	private void prune(long now)
	{
		/* Gone once their life is over — and any dated ahead of now, which a
		   clock set back would otherwise leave hanging in the air for as long
		   as it was set back by. */
		pops.removeIf(p -> now - p.at >= LIFE_MS || p.at > now);
	}

	/** "+2,000 gp", "+20K gp", "-12K gp": the game's own stack-size
	 *  abbreviations, exact under 10,000 — with the comma there written
	 *  here, not left to whichever formatter is on the classpath. */
	static String text(long profit)
	{
		return (profit < 0 ? "-" : "+") + size(profit) + " gp";
	}

	/** Coins in: "1,234 gp", "24.1K gp" — no sign, it is not a gain on
	 *  anything. */
	static String coinsText(long gp)
	{
		return size(gp) + " gp";
	}

	static String text(Pop p)
	{
		return p.coins ? coinsText(p.profit) : text(p.profit);
	}

	private static String size(long gp)
	{
		final long size = gp == Long.MIN_VALUE ? Long.MAX_VALUE : Math.abs(gp);
		return size < 10_000 ? String.format(java.util.Locale.ENGLISH, "%,d", size) : QuantityFormatter.quantityToStackSize(size);
	}

	/**
	 * The figure for a square too small for "+2,000 gp" — the sidebar's
	 * 49px slots: "+200", "+2K", "+1.2K", "+64K", "-1.1M". No "gp"; the
	 * colour and the sign say what it is.
	 */
	static String shortText(long profit)
	{
		return (profit < 0 ? "-" : "+") + shortSize(profit);
	}

	/** The sidebar's figure for {@code p}: coins as "24.1K", unsigned. */
	static String shortText(Pop p)
	{
		return p.coins ? shortSize(p.profit) : shortText(p.profit);
	}

	private static String shortSize(long gp)
	{
		final long size = gp == Long.MIN_VALUE ? Long.MAX_VALUE : Math.abs(gp);
		if (size < 1_000)
		{
			return String.valueOf(size);
		}
		final String[] unit = {"K", "M", "B"};
		double v = size / 1_000.0;
		int u = 0;
		while (v >= 1_000 && u < unit.length - 1)
		{
			v /= 1_000.0;
			u++;
		}
		/* Cut, not rounded, as the game cuts a stack's "64K": 999,999 is
		   "999K", never "1000K" or "1M". */
		final String n = v >= 10 ? String.valueOf((long) Math.floor(v))
			: String.format(java.util.Locale.ENGLISH, "%.1f", Math.floor(v * 10) / 10).replace(".0", "");
		return n + unit[u];
	}

	static Color colour(long profit)
	{
		return profit > 0 ? GAIN : profit < 0 ? LOSS : EVEN;
	}

	static Color colour(Pop p)
	{
		return p.coins ? COINS : colour(p.profit);
	}

	/** How far up it has risen: quick off the slot, slowing as it goes. */
	static int rise(long age)
	{
		final float t = clamp01((float) age / LIFE_MS);
		return Math.round(RISE_PX * (1f - (1f - t) * (1f - t)));
	}

	/** Opaque, then fading over the back part of its life. */
	static float alpha(long age)
	{
		if (age < 0 || age >= LIFE_MS)
		{
			return 0f;
		}
		final float t = (float) age / LIFE_MS;
		return t <= FADE_FROM ? 1f : clamp01(1f - (t - FADE_FROM) / (1f - FADE_FROM));
	}

	/** The pop: in small, a touch past full size, then settling — the bit
	 *  that makes it read as an arrival rather than a label. */
	static float scale(long age)
	{
		if (age < 100)
		{
			return 0.6f + 0.55f * clamp01(age / 100f);
		}
		if (age < 220)
		{
			return 1.15f - 0.15f * ((age - 100) / 120f);
		}
		return 1f;
	}

	/** Draws {@code p} over the slot at {@code slot}, centred, risen and
	 *  faded for its age. Nothing once it has run its course. */
	static void draw(Graphics2D g, Rectangle slot, Pop p, long now, Font font)
	{
		draw(g, slot, p, now, font, text(p));
	}

	/** As above, with the words given — see {@link #shortText}. */
	static void draw(Graphics2D g, Rectangle slot, Pop p, long now, Font font, String s)
	{
		final long age = now - p.at;
		final float a = alpha(age);
		if (a <= 0f)
		{
			return;
		}
		final Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setFont(font.deriveFont(font.getSize2D() * scale(age)));
			final FontMetrics fm = g2.getFontMetrics();
			final int x = slot.x + (slot.width - fm.stringWidth(s)) / 2;
			/* Off the slot's progress bar — the plainest, darkest strip in the
			   box, where it reads cleanly the moment it lands — and up over the
			   item. From the middle of the box it landed on the item's name,
			   and the two smeared into each other. */
			final int y = slot.y + Math.round(slot.height * START_AT) + fm.getAscent() / 2 - rise(age);
			g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, a));
			/* Outlined, the way the game outlines its own floating text: a
			   drop shadow alone left the strokes running into the sprites. */
			g2.setColor(Color.BLACK);
			for (int[] d : OUTLINE)
			{
				g2.drawString(s, x + d[0], y + d[1]);
			}
			g2.setColor(colour(p));
			g2.drawString(s, x, y);
		}
		finally
		{
			g2.dispose();
		}
	}

	private static float clamp01(float v)
	{
		return v < 0f ? 0f : v > 1f ? 1f : v;
	}
}

package com.pocketge.tracker;

/**
 * Where a price sits inside the range an item has actually traded in over the
 * last 30 days, and how far it moved to get there.
 *
 * This is the one thing the buy ranking cannot see. A buy idea is scored
 * entirely on {@code (insta-buy - insta-sell - tax) x quantity}: today's
 * spread and how much of it you can take. Two items with the same spread rank
 * identically whether one has been flat for a month and the other has run 26%
 * in a week and is sitting on its high. The spread is real in both cases; the
 * gp you can lose getting out is not remotely the same.
 *
 * Deliberately a MEASUREMENT, not a verdict. It reports where the price has
 * been and refuses to say where it goes next — a 30-day window cannot support
 * a forecast, and a card that implied one would be worse than saying nothing.
 * A run-up is not automatically a bad flip: momentum is a real strategy, and
 * plenty of good trades happen at the top of a range. What the card owes you
 * is the fact that you are there.
 *
 * Pure and dependency-free so the arithmetic can be tested without a client
 * or a network — the same reason PriceExtremes is.
 *
 * <h2>Why 30 days and not the 15 the plugin already fetches</h2>
 * The plugin's existing per-item call is {@code timestep=1h}, which reaches
 * back about 15 days. It would have been free to widen that window instead.
 * It is not free in the way that matters: a recommended buy is essentially
 * never in the set that call covers (favourites plus the top 40 items by
 * volume), so EVERY design here costs one new per-item request per plan
 * position regardless of timestep. Given the request is being spent either
 * way, {@code timestep=6h} spends it on 30 days and on agreeing exactly with
 * the 30-DAY RANGE meter pocketge.com already shows for the same item —
 * rather than on 15 days and a number that visibly disagrees with the site.
 */
public class RangePosition
{
	/** Lowest and highest price seen in the window, 0 when unknown. */
	public long lo30;
	public long hi30;
	/** The oldest price in the window, for the "+26% in 30d" figure. 0 when
	 *  the series did not reach back far enough to have one. */
	public long openingPrice;

	/**
	 * A range narrower than this fraction of its own high is treated as no
	 * range at all.
	 *
	 * Without it, an item that has traded 100-101 all month reports a price of
	 * 101 as "100% of its 30-day range", which is arithmetically true and
	 * completely useless — every stable item on the list would wear the
	 * loudest possible version of this signal. Matches the spirit of
	 * PriceExtremes.MIN_RANGE_PCT, which exists for the same reason.
	 */
	public static final double MIN_RANGE_PCT = 0.05;

	/** At or above this share of the range, the card says so. Chosen to match
	 *  the top quarter, the same zone the website's own meter renders as the
	 *  high end. */
	public static final double HIGH_ZONE = 0.75;
	/** ...and the bottom quarter. */
	public static final double LOW_ZONE = 0.25;

	/**
	 * Build from a wiki timeseries response, already split into arrays.
	 *
	 * A pure static rather than a loop inside MarketClient on purpose: this is
	 * the arithmetic worth testing, and MarketClient is the one class in the
	 * plugin that cannot be tested at all without a network. The parse stays
	 * there; the maths lives here where a test can reach it.
	 *
	 * Buckets are the wiki's own averages, so a bucket contributes its high to
	 * the top of the range and its low to the bottom. Zero means "no print in
	 * this bucket" and is skipped on both sides — a quiet 6-hour window is not
	 * evidence that the item traded at 0.
	 */
	public static RangePosition fromBuckets(long[] timestamps, long[] avgHigh, long[] avgLow, long cutoffSec)
	{
		final RangePosition r = new RangePosition();
		if (timestamps == null || avgHigh == null || avgLow == null)
		{
			return r;
		}
		final int n = Math.min(timestamps.length, Math.min(avgHigh.length, avgLow.length));
		long lo = Long.MAX_VALUE, hi = 0;
		for (int i = 0; i < n; i++)
		{
			if (timestamps[i] < cutoffSec)
			{
				continue;
			}
			final long h = avgHigh[i];
			final long l = avgLow[i];
			if (h > hi)
			{
				hi = h;
			}
			if (l > 0 && l < lo)
			{
				lo = l;
			}
			/* The first in-window bucket with any print at all is the opening
			   price. The series arrives oldest-first (the same assumption
			   MarketClient.fetchTimeseries5m and the website's loadTS both
			   make), so the first one that qualifies is the oldest one. */
			if (r.openingPrice <= 0)
			{
				final long mid = h > 0 && l > 0 ? (h + l) / 2 : Math.max(h, l);
				if (mid > 0)
				{
					r.openingPrice = mid;
				}
			}
		}
		r.hi30 = hi;
		r.lo30 = lo < Long.MAX_VALUE ? lo : 0;
		return r;
	}

	/** True when the window is wide enough for "where in it" to mean
	 *  anything. */
	public boolean usable()
	{
		return lo30 > 0 && hi30 > lo30
			&& (hi30 - lo30) >= hi30 * MIN_RANGE_PCT;
	}

	/**
	 * Where {@code price} sits in the range, 0.0 at the low and 1.0 at the
	 * high, or -1 when there is no usable range.
	 *
	 * Clamped, because the price being measured is a LIVE quote while the
	 * range comes from completed 6-hour buckets: an item making a new high
	 * right now is legitimately above everything in the window, and reporting
	 * 108% would be both wrong-looking and unrenderable as a percentage of a
	 * bar.
	 */
	public double position(long price)
	{
		if (!usable() || price <= 0)
		{
			return -1;
		}
		final double raw = (price - lo30) / (double) (hi30 - lo30);
		return Math.max(0.0, Math.min(1.0, raw));
	}

	/**
	 * Percentage move across the window, or {@link Double#NaN} when the
	 * series had no opening price to measure from.
	 *
	 * NaN rather than 0: "this item did not move" and "we could not tell"
	 * are different statements, and only one of them belongs on a card.
	 */
	public double runPct(long price)
	{
		if (openingPrice <= 0 || price <= 0)
		{
			return Double.NaN;
		}
		return ((price - openingPrice) / (double) openingPrice) * 100.0;
	}

	/**
	 * The card's footnote line, or null when there is nothing worth saying.
	 *
	 * Null in the middle of the range on purpose. The line costs a row on a
	 * card that has had six things cut from it, and "this item is somewhere in
	 * the middle of its own range" is the default state of most items most of
	 * the time — it is not news, and printing it on every card is how a signal
	 * becomes wallpaper. It speaks at the edges, where being told is worth the
	 * pixels.
	 *
	 * The wording is flat and unqualified — a percentage and a move, no verb,
	 * no adjective, no arrow. "Overextended" or "risky" would be the plugin
	 * arguing with its own recommendation on the same card, which is exactly
	 * what got Analyst Rating removed.
	 */
	public String footnote(long price)
	{
		final double pos = position(price);
		if (pos < 0 || (pos < HIGH_ZONE && pos > LOW_ZONE))
		{
			return null;
		}
		final StringBuilder sb = new StringBuilder();
		sb.append(Math.round(pos * 100)).append("% of 30d range");
		final double run = runPct(price);
		if (!Double.isNaN(run) && Math.abs(run) >= 1.0)
		{
			sb.append(" · ").append(run >= 0 ? "+" : "")
				.append(Math.round(run)).append("% in 30d");
		}
		return sb.toString();
	}
}

package com.pocketge.tracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import javax.swing.BorderFactory;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.util.QuantityFormatter;

/**
 * The profit headline + stat grid at the top of the panel — Flipping
 * Copilot's Session/1h/4h/.../All-time dropdown, profit total, unrealized
 * P/L, flip count, ROI%, hourly rate, and portfolio value, all computed from
 * data the tracker + portfolio valuer already produce.
 */
public class StatsHeaderPanel extends JPanel
{
	/** Left and right breathing room for the stats and the flip list under
	 *  them — see the constructor. HistoryPanel uses the same figure so the
	 *  two line up. */
	static final int SIDE_PAD = 8;

	private static final Color POSITIVE = new Color(0x1F, 0xB8, 0x5C);
	private static final Color NEGATIVE = new Color(0xEF, 0x53, 0x50);
	private static final Color GOLD = new Color(0xE5, 0xC1, 0x58);
	/** Row captions. Brighter and bolder than the grey they were: a stat list
	 *  whose labels recede is a list you have to re-read to find the line you
	 *  wanted, and these six are read at a glance or not at all. Still a step
	 *  down from the white values, so the numbers keep the emphasis. */
	private static final Color CAPTION = new Color(0xB8, 0xB0, 0xA2);
	/** The single vertical rhythm of the stat grid. */
	private static final int ROW_GAP = 4;

	public interface Actions
	{
		void onRangeChanged(FlipStats.Range range);
		void onResetSession();
	}

	private final JComboBox<FlipStats.Range> rangeBox = new JComboBox<>(FlipStats.Range.values());
	private final JLabel profitLabel = new JLabel("0 gp", SwingConstants.RIGHT);
	private final JLabel profitCaption = new JLabel("Profit");
	/* GridBagLayout, not GridLayout.
	 *
	 * GridLayout gives EVERY cell the width of the widest one, so this grid
	 * asked for twice its longest caption: "Unrealized profit" is 120px, and
	 * 120 x 2 + 6 = 246px demanded inside a 225px sidebar. It was the only
	 * thing in the whole panel still overflowing. Nothing clipped, because a
	 * grid compresses when it is given less than it asked for — but it
	 * compressed the VALUE column just as hard as the caption column, so the
	 * numbers lost width to pad captions that did not need it.
	 *
	 * A caption/value list wants two columns that size independently, which is
	 * what this does: preferred width is now the widest caption plus the
	 * widest value, not double either one. */
	private final JPanel statGrid = new JPanel(new GridBagLayout());
	/** Which row statRow() is filling in. */
	private int statRows = 0;
	private final JLabel unrealizedVal = new JLabel();
	private final JLabel flipsVal = new JLabel();
	private final JLabel roiVal = new JLabel();
	private final JLabel hourlyVal = new JLabel();
	private final JLabel portfolioVal = new JLabel();
	private final JLabel sessionTimeVal = new JLabel();
	/** When the tracker says this session began, 0 for "not counting". Held
	 *  here so the clock can tick between advisor refreshes, which are up to a
	 *  minute apart — a seconds display that only moved on those would jump in
	 *  minute-long steps, which reads as broken rather than as a clock. */
	private long sessionStartMillis;
	private final javax.swing.Timer sessionClock;
	/** False between logout and the next login. Everything on this panel is
	 *  account state — profit, what you hold, what your bank is worth — and
	 *  none of it can be read with no character logged in. */
	private boolean loggedIn = true;

	public StatsHeaderPanel(Actions actions)
	{
		setLayout(new BorderLayout(0, 6));
		setOpaque(false);
		/* Side padding of its own. The column it sits in is only inset 6px
		   left and 2px right, so "Unrealized" sat on the panel's left edge
		   and "gp" on its right, with nothing either side: "its right up to
		   the edges ... no margin on either side". */
		setBorder(BorderFactory.createEmptyBorder(0, SIDE_PAD, 4, SIDE_PAD));

		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setOpaque(false);
		rangeBox.addActionListener(e -> actions.onRangeChanged((FlipStats.Range) rangeBox.getSelectedItem()));
		/* A filter strip, sized like one. Both controls came out at the
		   component default, which put a chunky combo and a chunky button
		   directly above the profit figure and made the three read as equals —
		   the row that CHANGES what you are looking at competing with the thing
		   you are looking at. Same controls, one step quieter. */
		rangeBox.setFont(rangeBox.getFont().deriveFont(11f));
		Brand.control(rangeBox, Brand.TEXT_MAIN);
		top.add(rangeBox, BorderLayout.WEST);
		javax.swing.JButton reset = new javax.swing.JButton("Reset session");
		reset.setFont(reset.getFont().deriveFont(11f));
		Brand.control(reset, Brand.TEXT_MAIN);
		reset.setMargin(new Insets(2, 6, 2, 6));
		reset.setFocusPainted(false);
		reset.addActionListener(e -> actions.onResetSession());
		JPanel resetWrap = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		resetWrap.setOpaque(false);
		resetWrap.add(reset);
		top.add(resetWrap, BorderLayout.EAST);
		add(top, BorderLayout.NORTH);

		/* "Profit", beside the number instead of implied by it.

		   The headline was a bare green figure floating above six labelled
		   rows — so the one number the whole panel exists for was the only one
		   with no word attached to it, sitting a few pixels from a card that
		   says "sale value" and a row that says "Unrealized". An unlabelled
		   number gets whatever label the reader supplies.

		   Caption in CENTER and number in EAST, not the other way round:
		   BorderLayout satisfies EAST's preferred width first, so a very wide
		   "-987.7M gp" takes its space from the word "Profit" rather than
		   clipping itself. Same priority the stat rows below use. */
		JPanel headline = new JPanel(new BorderLayout(6, 0));
		headline.setOpaque(false);
		headline.setBorder(BorderFactory.createEmptyBorder(8, 0, 10, 0));
		profitCaption.setForeground(CAPTION);
		profitCaption.setFont(profitCaption.getFont().deriveFont(Font.BOLD, 13f));
		profitCaption.setToolTipText("Profit after the 2% GE tax on flips closed in the selected range.");
		headline.add(profitCaption, BorderLayout.CENTER);
		profitLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		profitLabel.setFont(profitLabel.getFont().deriveFont(Font.BOLD, 24f));
		headline.add(profitLabel, BorderLayout.EAST);
		add(headline, BorderLayout.CENTER);

		statGrid.setOpaque(false);
		/* "Unrealized", not "Unrealized profit". GridBag sizes a column to the
		   widest cell IN THAT COLUMN, so this one caption set the width of all
		   five — and paired with the widest value ("-987.7M gp/hr") it still
		   wanted 221px inside 217. The word "profit" was the 44px that did it,
		   and it is the least load-bearing word on the panel: everything here
		   is profit, the headline above it is a profit figure, and "unrealized"
		   is the term of art on its own. The full phrase is on the tooltip. */
		statRow("Unrealized", unrealizedVal, "Unrealized profit \u2014 what your open positions are worth "
			+ "against what you paid, before you have sold anything.");
		statRow("Flips made", flipsVal, null);
		statRow("ROI", roiVal, null);
		statRow("Hourly profit", hourlyVal, null);
		/* A link: the value over time is a chart on pocketge.com, read over
		   the bridge like the flip history it sits on. */
		final JLabel portfolioKey = statRow("Portfolio value", portfolioVal,
			"<html>Everything you hold, priced: cash, bank, inventory and your offers."
				+ "<br>Click for it over time on pocketge.com — needs <b>Local website bridge</b> on,"
				+ "<br>and is recorded while the <b>Flip advisor</b> is on, for live prices.</html>");
		final java.awt.event.MouseAdapter openPortfolio = new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				LinkBrowser.browse(PocketGeLinks.portfolio("portfolio_value"));
			}
		};
		for (JLabel l : new JLabel[]{portfolioKey, portfolioVal})
		{
			l.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
			l.addMouseListener(openPortfolio);
		}
		portfolioVal.setToolTipText(portfolioKey.getToolTipText());
		statRow("Session time", sessionTimeVal,
			"How long this session has been running. Resets with Reset session, and "
				+ "stops when you log out \u2014 it counts time played, not time the client was open.");
		add(statGrid, BorderLayout.SOUTH);

		/* One second, and only ever repaints one label. Started here rather
		   than on first update() so the field reads 0:00:00 immediately
		   instead of staying blank until the first advisor cycle lands. */
		sessionClock = new javax.swing.Timer(1000, e -> tickSessionTime());
		sessionClock.start();
		tickSessionTime();
	}

	/** The session clock, as H:MM:SS. */
	private void tickSessionTime()
	{
		sessionTimeVal.setText(formatDuration(loggedIn && sessionStartMillis > 0
			? System.currentTimeMillis() - sessionStartMillis : 0));
	}

	static String formatDuration(long millis)
	{
		final long total = Math.max(0, millis) / 1000L;
		return String.format("%d:%02d:%02d", total / 3600, (total % 3600) / 60, total % 60);
	}

	/**
	 * Blank the panel between logout and the next login.
	 *
	 * Every figure here is account state. Logged out there is no bank, no
	 * inventory and no offers to read, so the plugin cannot recompute any of
	 * it — and what was on screen simply stayed there. That is how a logged-out
	 * client sat showing "Unrealized +358K": not a live number, the last one
	 * from before you logged out, presented exactly like a live one.
	 *
	 * Zeroed rather than hidden, so the panel keeps its shape and you can see
	 * what it will tell you once you are in. The clock stops too — it measures
	 * time played, not time the client was left open.
	 */
	public void setLoggedIn(boolean loggedIn)
	{
		if (this.loggedIn == loggedIn)
		{
			return;
		}
		this.loggedIn = loggedIn;
		if (!loggedIn)
		{
			blank();
		}
		tickSessionTime();
	}

	/** The zero state. Same strings update() would produce for an empty
	 *  session, so logging out and logging back in with nothing traded look
	 *  identical — as they should. */
	private void blank()
	{
		profitLabel.setText("0 gp");
		profitLabel.setForeground(POSITIVE);
		unrealizedVal.setText("+0 gp");
		unrealizedVal.setForeground(POSITIVE);
		flipsVal.setText("0");
		roiVal.setText("0.00%");
		roiVal.setForeground(POSITIVE);
		hourlyVal.setText("+0 gp/hr");
		hourlyVal.setForeground(POSITIVE);
		portfolioVal.setText("0 gp");
		portfolioVal.setForeground(GOLD);
	}

	private JLabel statRow(String label, JLabel valueLabel, String tooltip)
	{
		JLabel k = new JLabel(label);
		k.setForeground(CAPTION);
		k.setFont(k.getFont().deriveFont(Font.BOLD, 12f));
		/* The caption is the half allowed to ellipsize (see below), so it
		   always carries its own text on hover — plus a fuller explanation
		   where the visible label had to be abbreviated to fit. */
		k.setToolTipText(tooltip != null ? tooltip : label);
		valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		valueLabel.setForeground(Color.WHITE);
		valueLabel.setFont(valueLabel.getFont().deriveFont(Font.BOLD, 12f));

		/* The CAPTION column carries the weight, not the value column, and that
		   is deliberate in both directions:

		   spare width -> the caption's cell grows, so the caption stays hard
		   left and the number stays hard right, which is the shape a stat list
		   is supposed to have;

		   short width -> GridBag takes the shortfall from the weighted column
		   first, so a cramped sidebar eats into "Unrealized profit" (which
		   ellipsises, and has a tooltip) rather than into "+1.2M gp", which is
		   the thing you are actually reading. Squeezing the number to protect
		   the word for it would be exactly backwards. */
		final GridBagConstraints key = new GridBagConstraints();
		key.gridx = 0;
		key.gridy = statRows;
		key.weightx = 1;
		key.anchor = GridBagConstraints.WEST;
		/* One number for every gap in the grid. It was 5 between rows and 0
		   above the first, which is correct arithmetic and an uneven column:
		   the space between the headline and row one came only from the
		   headline's own padding, so it read as a different size from every
		   gap under it. */
		key.insets = new Insets(statRows == 0 ? 0 : ROW_GAP, 0, 0, 6);
		statGrid.add(k, key);

		final GridBagConstraints value = new GridBagConstraints();
		value.gridx = 1;
		value.gridy = statRows;
		value.weightx = 0;
		value.anchor = GridBagConstraints.EAST;
		value.insets = new Insets(statRows == 0 ? 0 : ROW_GAP, 0, 0, 0);
		statGrid.add(valueLabel, value);
		statRows++;
		return k;
	}

	/** Call on the Swing EDT after the range dropdown selection changes, so
	 *  the visible selection matches the caller's authoritative state
	 *  (e.g. after config load) without re-triggering onRangeChanged. */
	public void setSelectedRangeQuietly(FlipStats.Range range)
	{
		if (rangeBox.getSelectedItem() != range)
		{
			rangeBox.setSelectedItem(range);
		}
	}

	public void update(FlipStats.Stats stats, PortfolioValuer.Result portfolio, long sessionStartMillis)
	{
		this.sessionStartMillis = sessionStartMillis;
		tickSessionTime();
		if (!loggedIn)
		{
			/* A refresh can still land after logout — the advisor cycle runs on
			   its own timer and does not stop. Dropping it here is what keeps
			   the blanked panel blank, rather than having stale figures quietly
			   reappear a few seconds later. */
			return;
		}
		long profit = stats.profit;
		profitLabel.setText((profit >= 0 ? "+" : "") + QuantityFormatter.quantityToStackSize(profit) + " gp");
		profitLabel.setForeground(profit >= 0 ? POSITIVE : NEGATIVE);

		unrealizedVal.setText(signed(stats.unrealizedProfit));
		unrealizedVal.setForeground(stats.unrealizedProfit >= 0 ? POSITIVE : NEGATIVE);

		flipsVal.setText(String.valueOf(stats.flipCount));

		roiVal.setText(String.format("%.2f%%", stats.roiPct));
		roiVal.setForeground(stats.roiPct >= 0 ? POSITIVE : NEGATIVE);

		hourlyVal.setText(signed(stats.hourlyRate) + "/hr");
		hourlyVal.setForeground(stats.hourlyRate >= 0 ? POSITIVE : NEGATIVE);

		portfolioVal.setText(QuantityFormatter.quantityToStackSize(portfolio.total) + " gp");
		portfolioVal.setForeground(GOLD);
	}

	private static String signed(long v)
	{
		return (v >= 0 ? "+" : "") + QuantityFormatter.quantityToStackSize(v) + " gp";
	}
}

package com.pocketge.tracker;

import java.awt.Color;
import net.runelite.client.ui.overlay.components.TooltipComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.util.QuantityFormatter;

/**
 * One vocabulary for the tooltips the plugin draws INSIDE the game — the bank
 * stack marks and the Exchange slot borders.
 *
 * <h2>Why this exists</h2>
 * The two overlays grew their own palettes, spelled as bare hex inside the
 * markup, and drifted apart exactly as you would expect:
 *
 * <ul>
 *   <li>{@code 8a8274}, a brown two shades off the tooltip's own background,
 *       carried four lines of the Exchange tooltip. The bank tooltip had the
 *       same brown, it came back in a screenshot as hard to read, it was
 *       replaced there — and a test was written banning it <i>in the bank</i>.
 *       The Exchange kept it, because nothing connected the two.</li>
 *   <li>{@code e5c158} titled every Exchange tooltip. It is not the theme's
 *       buy gold ({@code E5B842}), not the parchment the sidebar names items
 *       in, and not any other colour in the plugin — a near-miss of a brand
 *       colour, which is worse than a deliberate contrast.</li>
 *   <li>Both overlays wrote {@code 1fb85c} and {@code ef5350} as string
 *       literals beside {@code Color} constants holding the same values, so
 *       the border and the sentence explaining the border could be changed
 *       apart.</li>
 * </ul>
 *
 * <h2>The rule</h2>
 * A tooltip line is one of five things, and its colour says which:
 *
 * <ol>
 *   <li>{@link #subject} — what you are hovering. Parchment, the same
 *       {@code D9D3C7} the sidebar names items in.</li>
 *   <li>{@link #figure} — the number you opened it for. Parchment too, and it
 *       LEADS its line: "29.6M gp after tax", never "Worth selling: 29.6M".</li>
 *   <li>{@link #muted} — the working. Counts, unit prices, what a figure is
 *       scoped to, parentheticals. Never a colour with a meaning.</li>
 *   <li>{@link #state} — what this mark is telling you, in the colour of the
 *       mark itself, so the text and the border you are hovering cannot
 *       disagree. The caller passes the border's own colour.</li>
 *   <li>{@link #money} — a gain or a loss, and ONLY when it is genuinely one.
 *       Proceeds are not profit; see BankHighlightOverlay, which learned that
 *       by painting a stack's sale value green.</li>
 * </ol>
 *
 * Nothing here knows about Swing. RuneLite's in-game tooltips are game-markup
 * text — {@code <col=rrggbb>} and {@code </br>} — and the colours arrive as
 * {@link Color} so they can come from the same constants the overlays paint
 * their borders with, rather than being retyped as hex beside them.
 */
final class TipStyle
{
	/** What you are hovering, and the figures on it. AdvisorPanel.TEXT_MAIN. */
	static final Color SUBJECT = new Color(0xD9, 0xD3, 0xC7);

	/**
	 * The working: counts, unit prices, what a number covers.
	 *
	 * A5A5A5, and the specific thing it is not is {@code 8a8274} — a brown
	 * that sat almost on the tooltip's background. That was reported as hard
	 * to read, fixed in the bank, and left in place in the Exchange overlay
	 * for want of a shared constant. This is that constant.
	 */
	static final Color MUTED = new Color(0xA5, 0xA5, 0xA5);

	/** A real gain. AdvisorPanel.POSITIVE. */
	static final Color GOOD = new Color(0x1F, 0xB8, 0x5C);

	/** A real loss. AdvisorPanel.NEGATIVE. */
	static final Color BAD = new Color(0xEF, 0x53, 0x50);

	/** The line break the game's tooltip markup wants. Not {@code <br>}. */
	static final String BREAK = "</br>";

	/**
	 * The background our in-game tooltips are drawn on.
	 *
	 * RuneLite's own is {@code ComponentConstants.STANDARD_BACKGROUND_COLOR},
	 * {@code Color(70, 61, 50, 156)} — 61% opaque. Over the sidebar that is
	 * fine. Over the Grand Exchange it is not: the offer box behind it is
	 * pale, busy and full of its own text, and the result was reported twice
	 * as hard to read, the second time with a screenshot showing the slot's
	 * own "Selling 8,000…" legible straight through our sentence. No choice
	 * of text colour fixes that — the interference is behind the glyphs, not
	 * in them.
	 *
	 * So: the sidebar's own panel colour, at alpha 244. Near-opaque rather
	 * than opaque so the tooltip still reads as an overlay and not as part of
	 * the interface, and the same {@code --bg-panel} the cards use, so the
	 * thing that pops up over the game is recognisably the same product as
	 * the thing in the sidebar.
	 *
	 * This deliberately ignores the client's overlayBackgroundColor setting,
	 * which is the only way to set it at all — see {@link #tooltip}.
	 */
	static final Color BACKGROUND = new Color(0x1B, 0x18, 0x15, 244);

	/**
	 * Our markup, on a background we chose.
	 *
	 * TooltipOverlay forces the background colour of a {@code Tooltip(String)}
	 * to the client's overlayBackgroundColor, and does the same to a Tooltip
	 * whose component is a PanelComponent. A TooltipComponent is neither, so
	 * handing one to {@code Tooltip(LayoutableRenderableEntity)} is the one
	 * path that renders on a background of our choosing. Everything else —
	 * position, layout, the {@code <col>} parsing — is RuneLite's own, exactly
	 * as it is for the string form.
	 */
	static Tooltip tooltip(String markup)
	{
		final TooltipComponent c = new TooltipComponent();
		c.setText(markup);
		c.setBackgroundColor(BACKGROUND);
		return new Tooltip(c);
	}

	private TipStyle()
	{
	}

	/** A colour as the six hex digits the game's {@code <col>} tag wants. */
	static String hex(Color c)
	{
		return String.format("%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}

	/** {@code text} in {@code c}, and nothing else — no break, so lines can be
	 *  built out of several colours. */
	static String col(Color c, String text)
	{
		return "<col=" + hex(c) + ">" + text + "</col>";
	}

	/** What you are hovering. */
	static String subject(String text)
	{
		return col(SUBJECT, text);
	}

	/** The number you opened the tooltip for. */
	static String figure(String text)
	{
		return col(SUBJECT, text);
	}

	/** The working behind the figure. */
	static String muted(String text)
	{
		return col(MUTED, text);
	}

	/**
	 * What this mark is saying, in the mark's own colour.
	 *
	 * The colour is the caller's because it has to be the one actually
	 * painted on screen — the bank's theme-driven sell teal or its white
	 * lead rim, the Exchange slot's green or red border. A tooltip that
	 * picked its own would be free to disagree with the square under the
	 * cursor, which is how the bank ended up with a frozen teal line under
	 * three themes that had moved.
	 */
	static String state(Color markColor, String text)
	{
		return col(markColor, text);
	}

	/**
	 * A gain or a loss, signed, abbreviated.
	 *
	 * Only for figures that really are one. "What this stack fetches" is not
	 * a gain however it is worded, and painting it green claims it is.
	 */
	static String money(long v)
	{
		return col(v >= 0 ? GOOD : BAD,
			(v >= 0 ? "+" : "") + QuantityFormatter.quantityToStackSize(v) + " gp");
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Java port of pocketge.com's flip-pricing engine (index.html's
 * computeTargets()/ENGINE_CFG — the "trade engine" that drives the
 * website's TARGET BUY / TARGET SELL boxes). Same math, same constant
 * names and structure where practical, specifically so the two can be
 * diffed side by side when the website's version changes. Pure and
 * unit-testable — no RuneLite types.
 *
 * Only the 1D/live-engine path is ported (not the 5D+ swing-anchor
 * percentile fallback, which is tied to the website's chart-timeframe
 * concept) — this is what the plugin's ADJUST_BUY/ADJUST_SELL suggestions
 * need: "what should I reprice this stale offer to, right now."
 *
 * See the website's index.html around `const ENGINE_CFG` / `function
 * computeTargets` for the original, heavily-commented source of truth —
 * comments here are trimmed to what's Java-specific; read the JS for the
 * "why" behind each constant and step.
 */
public class TradeEngine
{
	/** One item's price history, oldest-first, as returned by the OSRS
	 *  Wiki's /timeseries endpoint. A missing low/high/volume for a bucket
	 *  should be 0 — the engine treats 0/negative as "no print." */
	public static class Series
	{
		public long[] labels;   // epoch seconds, ascending (oldest -> newest)
		public double[] low;    // avgLowPrice per bucket
		public double[] high;   // avgHighPrice per bucket
		public double[] lowVol;
		public double[] highVol;
	}

	public static class Result
	{
		public final long buy;
		public final long sell;
		public final boolean viable;
		public final String reason;
		public final long edge;
		public final boolean lowConf;

		Result(long buy, long sell, boolean viable, String reason, long edge, boolean lowConf)
		{
			this.buy = Math.max(0, buy);
			this.sell = Math.max(0, sell);
			this.viable = viable;
			this.reason = reason;
			this.edge = edge;
			this.lowConf = lowConf;
		}

		private static Result no(String reason, double buy, double sell, boolean lowConf)
		{
			return new Result(Math.round(buy), Math.round(sell), false, reason, 0, lowConf);
		}
	}

	/**
	 * pocketge.com's flip score — the "87 / Prime Flip" in the corner of its
	 * Recommended Flip card. Port of app.js's recScoreParts(), REC_BANDS and
	 * recVerdict(), kept in their shape so the two can be diffed.
	 *
	 * The parts are kept separate from the total so a card can show its
	 * work: two picks can sit a few points apart for completely different
	 * reasons, and "87 out of what?" has no generic answer. The edge term
	 * SATURATES at a 3% net edge — an 11.8% edge and a flat 3.0% edge both
	 * bank the full 45 — so between two liquid picks the gap is almost
	 * entirely liquidity, not margin.
	 *
	 * This rates the FLIP in front of you, not the item, and it cannot say
	 * "don't": an engine-cleared pair is worth 20 before anything else is
	 * known, and the bands run from Thin to Prime. That is what makes it safe
	 * on a card that is itself a recommendation, where the old Analyst Rating
	 * was not — that one graded the price against its typical, and could
	 * read "sell" under a buy.
	 */
	public static final class FlipScore
	{
		/** Net edge, as a fraction of the buy, that earns the full edge points. */
		public static final double EDGE_FULL = 0.03;

		public static final class Band
		{
			public final int min;
			public final String word;
			public final int color;

			private Band(int min, String word, int color)
			{
				this.min = min;
				this.word = word;
				this.color = color;
			}
		}

		/**
		 * Ascending. The site's REC_BANDS, colours and all — app.js's
		 * REC_BANDS is the source of truth and this table tracks it.
		 *
		 * The top two used to be #4FFF8E and #10B981 here, which is what the
		 * site had when this was ported. It has since moved them to #FFEFC2
		 * and #FFFFFF, and the reason applies word for word to this plugin:
		 * #10B981 is not merely LIKE the profit green, it IS it — the card
		 * prints "+75.3K gp profit" in #1FB85C two rows under a verdict in
		 * #10B981, so a rating and a figure were making two different claims
		 * ("this is a good entry" and "this is money you make") in one
		 * colour. The site measured the replacement across normal vision and
		 * both kinds of red-green colour blindness: the closest any band
		 * comes to the profit colour goes from 0.0 to 23.5, and the tightest
		 * gap between adjacent bands from 15.6 to 40.2.
		 */
		public static final Band[] BANDS = {
			new Band(0, "Thin Flip", 0xFF9F43),
			new Band(55, "Solid Flip", 0xFFD24D),
			new Band(70, "Strong Flip", 0xFFEFC2),
			new Band(85, "Prime Flip", 0xFFFFFF),
		};

		public final double edgePct;
		public final long vol;
		public final double base;
		public final double edge;
		public final double liq;
		public final double penalty;
		public final boolean lowConf;
		public final boolean edgeMaxed;
		public final boolean liqMaxed;
		public final int total;
		public final Band band;

		private FlipScore(double edgePct, long vol, boolean lowConf)
		{
			this.edgePct = edgePct;
			this.vol = vol;
			this.lowConf = lowConf;
			base = 20;                       // engine already certified viable + reachable
			edge = clamp01(edgePct / EDGE_FULL) * 45;
			liq = clamp01((Math.log10(Math.max(1, vol)) - 4) / 3) * 35;
			final double raw = base + edge + liq;
			penalty = lowConf ? raw * 0.2 : 0;
			total = (int) Math.round(Math.max(0, Math.min(100, lowConf ? raw * 0.8 : raw)));
			edgeMaxed = edgePct >= EDGE_FULL;
			liqMaxed = vol >= 1e7;
			band = verdict(total);
		}

		/**
		 * @param edgePct the engine's net edge divided by its buy price
		 * @param vol     units traded a day
		 * @param lowConf the engine's thin-tape flag: one side has not printed recently
		 */
		public static FlipScore of(double edgePct, long vol, boolean lowConf)
		{
			return new FlipScore(edgePct, vol, lowConf);
		}

		public static Band verdict(int score)
		{
			for (int i = BANDS.length - 1; i >= 0; i--)
			{
				if (score >= BANDS[i].min)
				{
					return BANDS[i];
				}
			}
			return BANDS[0];
		}

		private static double clamp01(double v)
		{
			return Math.max(0, Math.min(1, v));
		}
	}

	private static final double TARGET_TRADES = 2000, MIN_TRADES = 200;
	private static final int MIN_BUCKETS = 8;
	private static final double MIN_AGE = 60 * 60, MAX_AGE = 24 * 3600;
	private static final double ALPHA = 0.25, MIN_SCALE = 1, MAX_SPREAD_FRAC = 0.34, ABS_CAP_FRAC = 0.05;
	private static final double VOL_FLOOR = 20, VOL_CAP_W = 200;
	private static final int NEFF_MIN = 2, NEFF_MAX = 8;
	private static final double ALPHA_LIVE = 0.6, FRESH_SEC = 120, STALE_MIN = 5 * 60, STALE_MAX = 60 * 60;
	private static final double K_MAX = 6, MAX_FRAC = 0.25, P_MIN = 0.15;
	private static final double K_SAFETY = 0.002;
	private static final double DRIFT_GATE = 0.006;
	private static final double RECENT_FRAC = 0.34;
	private static final double PATIENCE_K = 0.25;

	private TradeEngine() {}

	public static long minEdge(double b)
	{
		return (long) Math.max(2, Math.ceil(K_SAFETY * b));
	}

	/**
	 * Clamps a computed sell target to the live book: never list BELOW what
	 * buyers are already paying.
	 *
	 * {@link #compute} is picking a flip PAIR, and it will settle on a lower,
	 * denser band when that band clears the tax more reliably — for Yew logs
	 * with an insta-buy of 115 it returned a 107/111 pair, because 111 is
	 * where the day's volume actually sits and 115 is the top of the range.
	 * As a flip pair that is defensible. As the number to type into a sell
	 * offer it is not: the player has already decided to sell this item, so
	 * the only question left is the price, and asking 111 with a standing 115
	 * bid gives away 4 gp an item for nothing. It also disagreed with
	 * pocketge.com's own TARGET SELL box and with Flipping Copilot, both
	 * showing 115 — and a number that loses an argument against two other
	 * tools on the same screen doesn't just cost that trade, it costs trust
	 * in every other number the plugin prints.
	 *
	 * Applied at the call sites rather than inside compute() so the ported
	 * algorithm stays diffable line-for-line against the website's
	 * computeTargets() JS, which is that class's whole reason for existing.
	 *
	 * Now only where the question is whether to move an offer that is
	 * already working (the ADJUST_SELL nudge): an ask at what buyers are
	 * paying is never told to come down. The price a held stack is offered
	 * at — sell cards, bank marks, stack hovers, the offer screen — is the
	 * website's Target Sell as it stands; pocketge.com's 1D box no longer
	 * raises it to the insta-buy, and the plugin raising it on some surfaces
	 * and not on the inspect card put two prices on one stack. See
	 * Advisor.heldSellPrice.
	 *
	 * @param rawHigh the live insta-buy quote; 0/unknown leaves the target alone
	 */
	public static long sellTarget(long engineSell, long rawHigh)
	{
		return rawHigh > 0 ? Math.max(engineSell, rawHigh) : engineSell;
	}

	/**
	 * The mirror of {@link #sellTarget}: never bid ABOVE what sellers are
	 * already accepting. Bidding over the insta-sell price cannot fill you
	 * any faster than bidding at it — the GE matches at the resting offer's
	 * price — so the excess only ever shows a worse number on screen.
	 *
	 * @param rawLow the live insta-sell quote; 0/unknown leaves the target alone
	 */
	public static long buyTarget(long engineBuy, long rawLow)
	{
		return rawLow > 0 ? Math.min(engineBuy, rawLow) : engineBuy;
	}

	private static double median(double[] a)
	{
		if (a.length == 0)
		{
			return 0;
		}
		double[] s = a.clone();
		Arrays.sort(s);
		int m = s.length / 2;
		return s.length % 2 == 1 ? s[m] : (s[m - 1] + s[m]) / 2;
	}

	/** Weighted median over (value, weight) pairs — the value at which
	 *  cumulative weight first reaches half the total, walking values in
	 *  ascending order. Non-positive values are ignored, mirroring the
	 *  JS `r[k] > 0` filter. */
	private static double weightedMedian(double[] values, double[] weights)
	{
		Integer[] order = new Integer[values.length];
		for (int i = 0; i < values.length; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, (a, b) -> Double.compare(values[a], values[b]));
		double total = 0;
		for (int i = 0; i < values.length; i++)
		{
			if (values[i] > 0)
			{
				total += weights[i];
			}
		}
		if (total <= 0)
		{
			return 0;
		}
		double acc = 0, last = 0;
		boolean any = false;
		for (int idx : order)
		{
			if (!(values[idx] > 0))
			{
				continue;
			}
			acc += weights[idx];
			last = values[idx];
			any = true;
			if (acc >= total / 2)
			{
				return values[idx];
			}
		}
		return any ? last : 0;
	}

	private static double percentile(double[] arr, double p)
	{
		if (arr.length == 0)
		{
			return Double.NaN;
		}
		double[] sorted = arr.clone();
		Arrays.sort(sorted);
		double index = (p / 100) * (sorted.length - 1);
		int lo = (int) Math.floor(index), hi = (int) Math.ceil(index);
		double w = index - lo;
		return sorted[lo] * (1 - w) + sorted[hi] * w;
	}

	/** One robust, winsorised per-bucket record — mirrors the JS `B` array
	 *  entries built inside computeTargets(). */
	private static class Bucket
	{
		/** Index into the series — JS keeps it as {@code b.i}. */
		int i;
		double lo, hi, mid, spread;
		double wL, wH, wFreshL, wFreshH, wM, wReachL, wReachH;
		double volL, volH;
		boolean recent, fresh;
	}

	/** Blended live-anchor result: the price to use, and how much the live
	 *  quote was trusted (0..1) when producing it. */
	private static class Anchor
	{
		double price;
		double t;
	}

	/** Holds everything the JS closures (deblur/qTouch/touchEpisodes/Pfill/
	 *  tailTouches/reachable/score/argmax) capture from computeTargets()'s
	 *  enclosing scope — one instance per compute() call. */
	private static class Calc
	{
		List<Bucket> B;
		boolean buyEndangered, sellEndangered;
		int neffBuy, neffSell;
		boolean strongDrift;
		double effDrift;
		Anchor aBuy, aSell;
		double sAbs;
		int itemId;

		double deblur(Bucket b, boolean buySide)
		{
			double g = b.spread;
			double sc = Math.max(ALPHA * g, MIN_SCALE);
			double cap = Math.min(g > 0 ? MAX_SPREAD_FRAC * g : Double.POSITIVE_INFINITY, ABS_CAP_FRAC * b.mid);
			sc = Math.min(sc, cap);
			double volSide = buySide ? b.volL : b.volH;
			sc *= Math.min(1, volSide / VOL_FLOOR);
			return Math.max(0, sc);
		}

		double qTouch(double c, boolean buySide)
		{
			boolean endangered = buySide ? buyEndangered : sellEndangered;
			double acc = 0, W = 0;
			for (Bucket b : B)
			{
				if (endangered && !b.fresh)
				{
					continue;
				}
				double sc = deblur(b, buySide);
				double w = endangered
					? (buySide ? b.wFreshL : b.wFreshH)
					: (buySide ? b.wReachL : b.wReachH);
				double f;
				if (buySide)
				{
					double p = b.lo, ext = p - sc;
					f = c >= p ? 1 : (c <= ext ? 0 : (c - ext) / (p - ext));
				}
				else
				{
					double p = b.hi, ext = p + sc;
					f = c <= p ? 1 : (c >= ext ? 0 : (ext - c) / (ext - p));
				}
				acc += w * f;
				W += w;
			}
			return W > 0 ? acc / W : 0;
		}

		/** Distinct touch episodes (runs of consecutive touching buckets),
		 *  walking B oldest -> newest (its natural order). */
		int touchEpisodes(double c, boolean buySide)
		{
			int eps = 0;
			boolean inTouch = false;
			for (Bucket b : B)
			{
				double sc = deblur(b, buySide);
				boolean t = buySide ? (c >= b.lo - sc) : (c <= b.hi + sc);
				if (t && !inTouch)
				{
					eps++;
				}
				inTouch = t;
			}
			return eps;
		}

		double pFill(double c, boolean buySide)
		{
			int base = buySide ? neffBuy : neffSell;
			int n = Math.max(1, Math.min(base, touchEpisodes(c, buySide)));
			return 1 - Math.pow(1 - qTouch(c, buySide), n);
		}

		boolean tailTouches(double c, boolean buySide)
		{
			for (Bucket b : B)
			{
				if (!b.recent)
				{
					continue;
				}
				double sc = deblur(b, buySide);
				if (buySide ? (c >= b.lo - sc) : (c <= b.hi + sc))
				{
					return true;
				}
			}
			return false;
		}

		boolean reachable(double c, boolean buySide)
		{
			return qTouch(c, buySide) >= P_MIN && tailTouches(c, buySide);
		}

		private double netKept(double b, double s)
		{
			return s - FlipTracker.taxPerItem(Math.round(s), itemId) - b;
		}

		double score(boolean buySide, double c, double otherTarget)
		{
			if (!reachable(c, buySide))
			{
				return -1;
			}
			double p0 = pFill(c, buySide);
			if (p0 < P_MIN)
			{
				return -1;
			}
			double margin = buySide ? netKept(c, otherTarget) : netKept(otherTarget, c);
			if (margin <= 0)
			{
				return -1;
			}
			double p = p0;
			if (strongDrift)
			{
				if (buySide && effDrift < 0)
				{
					p *= 0.5;
				}
				if (!buySide && effDrift > 0)
				{
					p *= 0.5;
				}
			}
			double eB = aBuy.price - (buySide ? c : otherTarget);
			double eS = (!buySide ? c : otherTarget) - aSell.price;
			double patience = 1 + PATIENCE_K * (Math.max(0, eB) + Math.max(0, eS)) / Math.max(1, sAbs);
			return p * margin / patience;
		}

		Long argmax(List<Long> cands, boolean buySide, double other)
		{
			Long best = null;
			double bs = 0;
			for (long c : cands)
			{
				double sc = score(buySide, c, other);
				if (sc > bs)
				{
					bs = sc;
					best = c;
				}
			}
			return best;
		}
	}

	/** Given the live quote and a price-history series, return the target
	 *  buy/sell pair the same way pocketge.com's Target Buy/Sell boxes do
	 *  on the 1D view. `viable=false` still returns the tightest honestly-
	 *  fillable pair (never a stale/unreachable price) rather than nothing.
	 *  lowTime/highTime are the live quote's own print timestamps (epoch
	 *  seconds, 0/negative = unknown) — how stale they are relative to the
	 *  series' own clock decides how much the live print is trusted. */
	/**
	 * The day's recency-weighted dip and peak — a port of app.js's
	 * {@code computeSwingTargets}, kept line-for-line so the two can be
	 * diffed.
	 *
	 * Flat percentiles over the whole window were too ambitious on trending
	 * items: in a downtrend the 88th-percentile high comes from the start of
	 * the slide, a level the market has left behind, so the ask never fills.
	 * Each print is weighted by age with a half-life of a third of the
	 * window, which barely moves a rangebound item and pulls a trending one
	 * toward levels the price still visits.
	 *
	 * Null when the window is too sparse to trust (fewer than 8 prints a
	 * side) or the pair comes out inverted.
	 */
	/** app.js {@code filterSeries(series, getPeriod('1d'))}: the newest 24
	 *  hours, measured back from the newest label. */
	static Series lastDay(Series s)
	{
		if (s == null || s.labels == null || s.labels.length == 0)
		{
			return s;
		}
		final int n = s.labels.length;
		final long minT = s.labels[n - 1] - 86_400;
		int start = 0;
		while (start < n && s.labels[start] < minT)
		{
			start++;
		}
		if (start == 0)
		{
			return s;
		}
		final Series o = new Series();
		o.labels = Arrays.copyOfRange(s.labels, start, n);
		o.low = Arrays.copyOfRange(s.low, start, n);
		o.high = Arrays.copyOfRange(s.high, start, n);
		o.lowVol = s.lowVol != null ? Arrays.copyOfRange(s.lowVol, start, n) : null;
		o.highVol = s.highVol != null ? Arrays.copyOfRange(s.highVol, start, n) : null;
		return o;
	}

	static long[] swingTargets(Series series)
	{
		if (series == null || series.labels == null || series.labels.length == 0)
		{
			return null;
		}
		final List<double[]> lows = new ArrayList<>();   // {value, time}
		final List<double[]> highs = new ArrayList<>();
		double tLast = Double.NEGATIVE_INFINITY;
		double tFirst = Double.POSITIVE_INFINITY;
		for (int i = 0; i < series.labels.length; i++)
		{
			final double t = series.labels[i];
			final double lo = series.low != null && i < series.low.length ? series.low[i] : 0;
			final double hi = series.high != null && i < series.high.length ? series.high[i] : 0;
			if (lo > 0)
			{
				lows.add(new double[]{lo, t});
			}
			if (hi > 0)
			{
				highs.add(new double[]{hi, t});
			}
			if (lo > 0 || hi > 0)
			{
				tLast = Math.max(tLast, t);
				tFirst = Math.min(tFirst, t);
			}
		}
		if (lows.size() < 8 || highs.size() < 8 || !(tLast > tFirst))
		{
			return null;
		}
		final double halfLife = (tLast - tFirst) / 3.0;
		final long buy = Math.round(weightedPercentile(lows, 0.12, tLast, halfLife));
		final long sell = Math.round(weightedPercentile(highs, 0.88, tLast, halfLife));
		return sell > buy ? new long[]{buy, sell} : null;
	}

	/** Ascending by value, then the value at which cumulative age-weight
	 *  first reaches {@code p} of the total. */
	private static double weightedPercentile(List<double[]> pts, double p, double tLast, double halfLife)
	{
		pts.sort((a, b) -> Double.compare(a[0], b[0]));
		double total = 0;
		for (double[] e : pts)
		{
			total += Math.pow(0.5, (tLast - e[1]) / halfLife);
		}
		double acc = 0;
		for (double[] e : pts)
		{
			acc += Math.pow(0.5, (tLast - e[1]) / halfLife);
			if (acc >= p * total)
			{
				return e[0];
			}
		}
		return pts.get(pts.size() - 1)[0];
	}

	/**
	 * What every price on a card should actually come from — a port of
	 * app.js's {@code computeViewTargets} on its 1D branch, which is the
	 * window the plugin works in.
	 *
	 * {@link #compute} alone was not the whole of what the website does, and
	 * the difference is not cosmetic. When the LIVE spread cannot clear the
	 * 2% tax the engine honestly reports "not viable" and converges both
	 * targets on the live quote — and every caller here then fell back to
	 * the raw print, which means quoting the last actively-traded price and
	 * calling it a target. That is the exact complaint that has now come in
	 * three times.
	 *
	 * Ruby is the worked example: insta-sell 767, insta-buy 779, tax on 779
	 * is 15, so the live spread is 767 -> 779 - 15 = minus three gp. Dead.
	 * The plugin said "sell at 779" — the traded price. The website said 788,
	 * because its day prints still showed a real range and it anchors to
	 * them instead. 758 / 788 clears the tax by 15.
	 *
	 * The day pair is used ONLY when the live spread is dead AND the day
	 * pair itself beats the tax. Otherwise the engine's honest no-margin
	 * answer stands — a fabricated margin would be worse than none.
	 */
	public static Result viewTargets(long rawLow, long rawHigh, long lowTime, long highTime,
		Series series, int itemId)
	{
		final Result engine = compute(rawLow, rawHigh, lowTime, highTime, series, itemId);
		if (engine == null)
		{
			return null;
		}
		final long tax = FlipTracker.taxPerItem(engine.sell, itemId);
		if (engine.sell - engine.buy - tax > 0)
		{
			return engine; // the live spread is alive; nothing to fall back to
		}
		/* The site's 1D view reads the newest 24 hours (currentSeries =
		   filterSeries(ts5m, one day)); the 5m response runs to about 30.
		   Six extra hours of tape moved this pair 1-3 gp off the site's on
		   the same data, which is exactly when the two get compared — a
		   dead spread is when this fallback runs. */
		final long[] day = clampToLive(swingTargets(lastDay(series)), rawLow, rawHigh);
		if (day == null)
		{
			return engine;
		}
		final long dayEdge = day[1] - day[0] - FlipTracker.taxPerItem(day[1], itemId);
		if (dayEdge <= 0)
		{
			return engine;
		}
		return new Result(day[0], day[1], true, "", dayEdge, engine.lowConf);
	}

	/** Port of app.js's {@code clampToLive}: never ask under the standing
	 *  bid, never bid over the standing ask — and if clamping inverts the
	 *  pair, keep the unclamped one rather than returning nonsense. */
	private static long[] clampToLive(long[] t, long rawLow, long rawHigh)
	{
		if (t == null)
		{
			return null;
		}
		long buy = t[0];
		long sell = t[1];
		if (rawHigh > 0)
		{
			sell = Math.max(sell, rawHigh);
		}
		if (rawLow > 0)
		{
			buy = Math.min(buy, rawLow);
		}
		return sell > buy ? new long[]{buy, sell} : t;
	}

	public static Result compute(long rawLowIn, long rawHighIn, long lowTime, long highTime, Series series, int itemId)
	{
		double rawLow = rawLowIn > 0 ? rawLowIn : 0;   // insta-sell price = you BUY at
		double rawHigh = rawHighIn > 0 ? rawHighIn : 0; // insta-buy  price = you SELL into

		if (series == null || series.labels == null || series.labels.length < MIN_BUCKETS)
		{
			return Result.no("insufficient data", rawLow, rawHigh, true);
		}
		long[] L = series.labels;
		double now = L[L.length - 1];
		if (!(now > 0))
		{
			return Result.no("insufficient data", rawLow, rawHigh, true);
		}

		List<Double> gaps = new ArrayList<>();
		for (int i = 1; i < L.length; i++)
		{
			double g = L[i] - L[i - 1];
			if (g > 0)
			{
				gaps.add(g);
			}
		}
		double dt = gaps.isEmpty() ? 300 : median(toArray(gaps));

		// ---- adaptive, liquidity-sized window (walk newest -> oldest) ----
		List<Integer> idx = new ArrayList<>();
		double cum = 0, oldest = now;
		int usable = 0;
		for (int i = L.length - 1; i >= 0; i--)
		{
			double age = now - L[i];
			if (age < 0)
			{
				continue;
			}
			if (age > MAX_AGE)
			{
				break;
			}
			idx.add(i);
			if (series.low[i] > 0 && series.high[i] > 0)
			{
				usable++;
			}
			cum += nz(series.lowVol, i) + nz(series.highVol, i);
			oldest = L[i];
			double span0 = now - oldest;
			if (cum >= TARGET_TRADES && span0 >= MIN_AGE && usable >= MIN_BUCKETS)
			{
				break;
			}
		}
		if (usable < MIN_BUCKETS)
		{
			return Result.no("insufficient buckets", rawLow, rawHigh, true);
		}
		java.util.Collections.reverse(idx); // oldest -> newest
		double span = Math.max(dt, now - L[idx.get(0)]);
		boolean lowConf = cum < MIN_TRADES;
		double halfLife = Math.max(dt, span / 4);

		// ---- robust, winsorised per-bucket records ----
		List<Double> loList = new ArrayList<>(), hiList = new ArrayList<>();
		for (int i : idx)
		{
			if (series.low[i] > 0)
			{
				loList.add(series.low[i]);
			}
			if (series.high[i] > 0)
			{
				hiList.add(series.high[i]);
			}
		}
		if (loList.size() < 4 || hiList.size() < 4)
		{
			return Result.no("thin data", rawLow, rawHigh, true);
		}
		double[] loArr = toArray(loList), hiArr = toArray(hiList);
		double P1lo = percentile(loArr, 1), P99lo = percentile(loArr, 99);
		double P1hi = percentile(hiArr, 1), P99hi = percentile(hiArr, 99);

		double[] bucketVols = new double[idx.size()];
		for (int k = 0; k < idx.size(); k++)
		{
			bucketVols[k] = nz(series.lowVol, idx.get(k)) + nz(series.highVol, idx.get(k));
		}
		double volMed = median(bucketVols);
		if (volMed <= 0)
		{
			volMed = 1;
		}

		List<Bucket> B = new ArrayList<>();
		for (int i : idx)
		{
			double lo = series.low[i], hi = series.high[i];
			if (!(lo > 0) || !(hi > 0))
			{
				continue;
			}
			lo = Math.min(Math.max(lo, P1lo), P99lo);
			hi = Math.min(Math.max(hi, P1hi), P99hi);
			if (hi < lo)
			{
				double t = lo; lo = hi; hi = t;
			}
			double mid = (lo + hi) / 2, spread = Math.max(0, hi - lo);
			double age = now - L[i];
			double decay = Math.pow(0.5, age / halfLife);
			double decayReach = Math.pow(0.5, age / span);
			double volL = Math.min(nz(series.lowVol, i, 1), 5 * volMed);
			double volH = Math.min(nz(series.highVol, i, 1), 5 * volMed);
			double wL = decay * Math.sqrt(Math.min(volL, VOL_CAP_W));
			double wH = decay * Math.sqrt(Math.min(volH, VOL_CAP_W));
			double decayFresh = Math.pow(0.5, age / dt);

			Bucket b = new Bucket();
			b.i = i;
			b.lo = lo; b.hi = hi; b.mid = mid; b.spread = spread;
			b.wL = wL; b.wH = wH;
			b.wFreshL = decayFresh * Math.sqrt(Math.min(volL, VOL_CAP_W));
			b.wFreshH = decayFresh * Math.sqrt(Math.min(volH, VOL_CAP_W));
			b.wM = wL + wH;
			b.wReachL = decayReach * Math.sqrt(Math.min(Math.min(volL, volMed), VOL_CAP_W));
			b.wReachH = decayReach * Math.sqrt(Math.min(Math.min(volH, volMed), VOL_CAP_W));
			b.volL = volL; b.volH = volH;
			b.recent = age <= Math.max(halfLife, 3 * dt);
			b.fresh = age <= 3 * dt;
			B.add(b);
		}
		if (B.size() < MIN_BUCKETS)
		{
			return Result.no("thin data", rawLow, rawHigh, true);
		}

		double refMid = weightedMedian(mapD(B, b -> b.mid), mapD(B, b -> b.wM));
		double relSpread = weightedMedian(mapD(B, b -> b.spread / b.mid), mapD(B, b -> b.wL + b.wH));

		// realized step-vol (MAD of log-returns), gap-skipped
		List<Double> rets = new ArrayList<>();
		for (int k = 1; k < B.size(); k++)
		{
			/* The buckets' own series positions, as JS's L[B[k].i]. This read
			   idx.get(k), but B skips one-sided buckets and idx does not, so
			   past the first one-sided bucket each return was gated on the
			   time gap between two unrelated buckets. */
			int iPrev = B.get(k - 1).i, iCur = B.get(k).i;
			if (L[iCur] - L[iPrev] <= 2 * dt && B.get(k).mid > 0 && B.get(k - 1).mid > 0)
			{
				rets.add(Math.log(B.get(k).mid / B.get(k - 1).mid));
			}
		}
		double medR = median(toArray(rets));
		double sigma = 0;
		if (!rets.isEmpty())
		{
			double[] devs = new double[rets.size()];
			for (int k = 0; k < rets.size(); k++)
			{
				devs[k] = Math.abs(rets.get(k) - medR);
			}
			sigma = 1.4826 * median(devs);
		}
		sigma = Math.max(sigma, Math.max(0.5 * relSpread, 1 / Math.max(1, refMid)));

		// ---- DRIFT (level change), independent of sigma ----
		List<Bucket> recentB = new ArrayList<>(), freshB = new ArrayList<>();
		for (Bucket b : B)
		{
			if (b.recent)
			{
				recentB.add(b);
			}
			if (b.fresh)
			{
				freshB.add(b);
			}
		}
		int third = Math.max(1, (int) Math.round(B.size() * RECENT_FRAC));
		List<Bucket> newestThird = B.subList(B.size() - third, B.size());
		List<Bucket> oldestThird = B.subList(0, third);
		double midNew = weightedMedian(mapD(newestThird, b -> b.mid), mapD(newestThird, b -> b.wM));
		double midOld = weightedMedian(mapD(oldestThird, b -> b.mid), mapD(oldestThird, b -> b.wM));
		double driftFrac = refMid > 0 ? (midNew - midOld) / refMid : 0;
		double midTail = !recentB.isEmpty() ? weightedMedian(mapD(recentB, b -> b.mid), mapD(recentB, b -> b.wM)) : refMid;
		double driftTail = refMid > 0 ? (midTail - refMid) / refMid : 0;
		boolean bothBreachDown = rawLow > 0 && rawHigh > 0 && rawLow < P1lo && rawHigh < P1hi;
		boolean bothBreachUp = rawLow > 0 && rawHigh > 0 && rawLow > P99lo && rawHigh > P99hi;

		boolean sellEndangered = driftFrac <= -DRIFT_GATE * 0.7 || 2 * driftTail <= -DRIFT_GATE || bothBreachDown;
		boolean buyEndangered = driftFrac >= DRIFT_GATE * 0.7 || 2 * driftTail >= DRIFT_GATE || bothBreachUp;
		double effDrift = Math.abs(driftFrac / 0.7) >= Math.abs(2 * driftTail) ? driftFrac / 0.7 : 2 * driftTail;

		int neffBuy = (int) Math.min(NEFF_MAX, Math.max(NEFF_MIN, Math.round((span / dt) / 3)));
		int neffSell = neffBuy;
		if (sellEndangered)
		{
			neffSell = 1;
		}
		if (buyEndangered)
		{
			neffBuy = 1;
		}

		Calc calc = new Calc();
		calc.B = B;
		calc.buyEndangered = buyEndangered;
		calc.sellEndangered = sellEndangered;
		calc.neffBuy = neffBuy;
		calc.neffSell = neffSell;
		calc.effDrift = effDrift;
		calc.itemId = itemId;

		// ---- live-anchor blend (staleness trust + slew cap) ----
		double tradesPerMin = cum / Math.max(1, span / 60);
		double A = Math.min(STALE_MAX, Math.max(STALE_MIN, 10 * (60 / Math.max(1e-6, tradesPerMin))));
		double distBuy = weightedMedian(mapD(B, b -> b.lo), mapD(B, b -> b.wL));
		double distSell = weightedMedian(mapD(B, b -> b.hi), mapD(B, b -> b.wH));
		double delta = Math.max(Math.round(0.003 * refMid), Math.round(sigma * refMid * 0.75));

		double ageLow = lowTime > 0 ? now - lowTime : -1;
		double ageHigh = highTime > 0 ? now - highTime : -1;
		Anchor aBuy = blend(distBuy, rawLow, ageLow, P1lo, P99lo, A, delta, bothBreachDown, bothBreachUp);
		Anchor aSell = blend(distSell, rawHigh, ageHigh, P1hi, P99hi, A, delta, bothBreachDown, bothBreachUp);
		calc.aBuy = aBuy;
		calc.aSell = aSell;

		double sAbs = sigma * ((aBuy.price + aSell.price) / 2);
		calc.sAbs = sAbs;
		calc.strongDrift = Math.abs(effDrift) >= 3 * DRIFT_GATE;

		double eMax = Math.max(1, Math.min(K_MAX * sAbs, MAX_FRAC * aBuy.price));
		double step = Math.max(1, Math.round(eMax / 40));
		double buyCapLive = (rawLow > 0 && aBuy.t >= 0.5) ? rawLow : Double.POSITIVE_INFINITY;

		List<Long> buyCands = new ArrayList<>(), sellCands = new ArrayList<>();
		for (double e = 0; e <= eMax; e += step)
		{
			long bb = Math.round(aBuy.price - e);
			if (bb >= 1 && bb <= buyCapLive)
			{
				buyCands.add(bb);
			}
			sellCands.add(Math.round(aSell.price + e));
		}

		List<Bucket> loEvid = !(buyEndangered ? freshB : B).isEmpty() ? (buyEndangered ? freshB : B) : B;
		List<Bucket> hiEvid = !(sellEndangered ? freshB : B).isEmpty() ? (sellEndangered ? freshB : B) : B;
		double buyFloor = Math.min(rawLow > 0 ? rawLow : Double.POSITIVE_INFINITY,
			percentile(!loEvid.isEmpty() ? mapD(loEvid, b -> b.lo) : loArr, 2));
		double sellCap = Math.max(rawHigh, percentile(!hiEvid.isEmpty() ? mapD(hiEvid, b -> b.hi) : hiArr, 98));

		// ---- coupled 2-sweep fixed point ----
		Long s = Math.round(Math.min(Math.max(distSell, aSell.price), sellCap));
		Long b = calc.argmax(buyCands, true, s);
		if (b != null)
		{
			Long s2 = calc.argmax(sellCands, false, b);
			s = s2 != null ? s2 : s;
		}
		if (b != null)
		{
			Long b2 = calc.argmax(buyCands, true, s);
			b = b2 != null ? b2 : b;
			Long s3 = calc.argmax(sellCands, false, b);
			s = s3 != null ? s3 : s;
		}
		if (s != null && !calc.reachable(s, false))
		{
			s = null;
		}
		if (b != null && (!calc.reachable(b, true) || b > buyCapLive))
		{
			b = null;
		}

		long edgeReq = lowConf
			? Math.max(minEdge(b != null ? b : rawLow), (long) Math.ceil(2 * K_SAFETY * (b != null ? b : rawLow)))
			: minEdge(b != null ? b : rawLow);

		if (b != null && s != null && calc.netKept(b, s) >= edgeReq)
		{
			if (calc.netKept(b, s - 1) >= edgeReq && calc.reachable(s - 1, false))
			{
				s -= 1;
			}
			return new Result(b, s, true, "", Math.round(calc.netKept(b, s)), lowConf);
		}

		// widen minimally, staying inside the recent fillable band + recency gate
		if (b == null)
		{
			b = (long) Math.max(1, Math.min(Math.round(aBuy.price), buyCapLive));
		}
		if (s == null)
		{
			s = Math.round(aSell.price);
		}
		int seedGuard = 0;
		while (s > Math.max(rawHigh, 1) && !calc.reachable(s, false) && ++seedGuard < 20000)
		{
			s--;
		}
		if (rawHigh > 0 && s < rawHigh)
		{
			s = Math.round(rawHigh);
		}
		int guard = 0;
		while (calc.netKept(b, s) < edgeReq)
		{
			boolean canLower = (b - 1) >= buyFloor && (b - 1) >= 1 && calc.reachable(b - 1, true);
			boolean canRaise = (s + 1) <= sellCap && calc.reachable(s + 1, false);
			if (canLower && (!canRaise || calc.qTouch(b - 1, true) >= calc.qTouch(s + 1, false)))
			{
				b -= 1;
			}
			else if (canRaise)
			{
				s += 1;
			}
			else
			{
				break; // can't reach a tax-clearing pair without leaving the fillable band
			}
			if (++guard > 20000)
			{
				break;
			}
		}
		if (calc.netKept(b, s) >= edgeReq)
		{
			return new Result(b, s, true, "", Math.round(calc.netKept(b, s)), lowConf);
		}

		// No clean flip — tightest CURRENTLY-FILLABLE honest pair.
		long honestBuy = (long) Math.min(Math.round(aBuy.price), buyCapLive);
		long honestSell = (long) Math.max(Math.round(aSell.price), rawHigh);
		if (aSell.t < 0.5)
		{
			honestSell = Math.round(aSell.price);
		}
		else if (sellEndangered && rawHigh > 0)
		{
			honestSell = Math.round(rawHigh);
		}
		return Result.no("spread does not clear the 2% tax right now", honestBuy, honestSell, lowConf);
	}

	private static Anchor blend(double dist, double live, double ageSec, double p1, double p99,
		double staleA, double delta, boolean bothBreachDown, boolean bothBreachUp)
	{
		Anchor out = new Anchor();
		if (!(live > 0))
		{
			out.price = Math.round(dist);
			out.t = 0;
			return out;
		}
		double t = trust(ageSec, staleA);
		if ((live < p1 || live > p99) && !(bothBreachDown || bothBreachUp))
		{
			t = 0;
		}
		double clamped = Math.max(dist - delta, Math.min(dist + delta, live));
		double a = ALPHA_LIVE * t;
		out.price = Math.round((1 - a) * dist + a * clamped);
		out.t = t;
		return out;
	}

	private static double trust(double ageSec, double A)
	{
		if (!(ageSec >= 0))
		{
			return 0.5; // unknown timestamp -> blend half
		}
		double t = Math.max(0, Math.min(1, 1 - ageSec / A));
		if (ageSec < FRESH_SEC)
		{
			t = Math.max(t, 0.5);
		}
		return t;
	}

	private static double nz(double[] arr, int i)
	{
		return arr != null && i < arr.length ? arr[i] : 0;
	}

	private static double nz(double[] arr, int i, double fallbackIfZero)
	{
		double v = nz(arr, i);
		return v > 0 ? v : fallbackIfZero;
	}

	private static double[] toArray(List<Double> list)
	{
		double[] out = new double[list.size()];
		for (int i = 0; i < list.size(); i++)
		{
			out[i] = list.get(i);
		}
		return out;
	}

	private interface ToDouble { double apply(Bucket b); }

	private static double[] mapD(List<Bucket> list, ToDouble f)
	{
		double[] out = new double[list.size()];
		for (int i = 0; i < list.size(); i++)
		{
			out[i] = f.apply(list.get(i));
		}
		return out;
	}
}

package com.pocketge.tracker;

/**
 * One partial or complete fill of a GE offer: "N items actually traded at
 * this moment, for this much total gp". Fills are the ground truth the
 * flip matcher consumes — offers can fill in many increments over hours.
 */
public class TradeFill
{
	public final long time;        // epoch millis
	public final int itemId;
	public final String itemName;
	public final boolean buy;      // true = bought, false = sold
	public final int quantity;     // items in THIS fill (delta, not cumulative)
	public final long spent;       // gp moved in THIS fill (delta, not cumulative)

	public TradeFill(long time, int itemId, String itemName, boolean buy, int quantity, long spent)
	{
		this.time = time;
		this.itemId = itemId;
		this.itemName = itemName;
		this.buy = buy;
		this.quantity = quantity;
		this.spent = spent;
	}

	public long unitPrice()
	{
		return quantity > 0 ? Math.round((double) spent / quantity) : 0;
	}
}

package com.pocketge.tracker;

import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JButton;
import org.junit.Assert;
import org.junit.Test;

/** The ✕ on the inspection card must hand the box back, and the next refresh must not undo it. */
public class AdvisorPanelCloseTest
{
	private final List<String> calls = new ArrayList<>();

	private AdvisorPanel panel()
	{
		AdvisorPanel.Actions actions = (AdvisorPanel.Actions) Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(proxy, method, args) ->
			{
				calls.add(method.getName() + (args == null ? "()" : "(" + java.util.Arrays.toString(args) + ")"));
				Class<?> t = method.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				if (t == int.class || t == long.class || t == double.class || t == float.class)
				{
					return 0;
				}
				return null;
			});
		return new AdvisorPanel(null, actions);
	}

	private static JButton find(Component c, String text)
	{
		if (c instanceof JButton && text.equals(((JButton) c).getText()))
		{
			return (JButton) c;
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				JButton b = find(child, text);
				if (b != null)
				{
					return b;
				}
			}
		}
		return null;
	}

	private static Object field(Object o, String name) throws Exception
	{
		Field f = o.getClass().getDeclaredField(name);
		f.setAccessible(true);
		return f.get(o);
	}

	@Test
	public void theCloseButtonDismissesTheCardAndTellsThePlugin() throws Exception
	{
		AdvisorPanel panel = panel();
		FavoritesPanel.Row row = new FavoritesPanel.Row();
		row.id = 555;
		row.name = "Water rune";
		panel.setSelectedItem(row);
		Assert.assertEquals(row, field(panel, "selectedFavorite"));
		JButton close = find(panel, "✕");
		Assert.assertNotNull("the card has its ✕", close);
		calls.clear();
		close.doClick();
		Assert.assertNull("the card is dismissed", field(panel, "selectedFavorite"));
		Assert.assertTrue("the plugin is told: " + calls, calls.contains("onSelectedItemChanged([null])"));
		Assert.assertNull("no ✕ left on the box", find(panel, "✕"));

		// The plugin's next refresh still carries a row for the item; that must not bring it back.
		List<FavoritesPanel.Row> rows = new ArrayList<>();
		rows.add(row);
		panel.refreshSelectedFrom(rows);
		Assert.assertNull("still dismissed after a refresh", field(panel, "selectedFavorite"));
	}
}

