	@Test
	public void sellFallsBackToRawQuoteWithoutSeries()
	{
		Advisor.Suggestion sell = sellSuggestion(null, new HashMap<>());
		Assert.assertNotNull(sell);
		Assert.assertEquals(2000, sell.price); // raw q.high, no engine series supplied
	}

	/**
	 * Every figure on a repriced sell has to be costed at the price the card
	 * actually names.
	 *
	 * Repricing used to happen in advise(), AFTER sellCandidates had built
	 * the suggestion — so it moved the price and patched the reason string by
	 * search-and-replace, while profit, gross proceeds and the untracked
	 * remainder stayed costed at the old one. The card then read "sell 1,000
	 * at 2,004" over a profit worked out at 2,000. Doing the whole job in one
	 * place is what fixes that, and this is the assertion that says so.
	 */
	@Test
	public void arepricedSellCostsEveryFigureAtTheNewPrice()
	{
		final TradeEngine.Series series = syntheticSeries(NOW, 200, 1900, 2000, 11);
		final Map<Integer, TradeEngine.Series> seriesByItem = new HashMap<>();
		seriesByItem.put(1601, series);

		final Map<Integer, long[]> basis = new HashMap<>();
		basis.put(1601, new long[]{100, 100 * 1_500L}); // 100 bought at 1,500

		final Advisor.Suggestion sell = sellSuggestion(basis, seriesByItem);
		Assert.assertNotNull(sell);

		final long net = sell.price - FlipTracker.taxPerItem(sell.price, 1601);
		Assert.assertEquals("gross proceeds are at the named price",
			net * sell.quantity, sell.grossValue);
		Assert.assertEquals("and so is the profit, against what was actually paid",
			net * 100 - 100 * 1_500L, sell.expectedProfit);
		Assert.assertTrue("the reason quotes that same price",
			sell.reason.contains(String.format("%,d", sell.price)));
	}

	@Test
	public void adjustSellUsesEngineTargetWhenSeriesAvailable()
	{
		Map<Integer, Advisor.Quote> q = quotes(2000, 1900); // high=2000, low=1900
		TradeEngine.Series series = syntheticSeries(NOW, 200, 1900, 2000, 11);
		Map<Integer, TradeEngine.Series> seriesByItem = new HashMap<>();
		seriesByItem.put(1601, series);
		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(sellOffer(1601, "Diamond", 2500)); // way above market -> triggers ADJUST_SELL

		TradeEngine.Result expected = TradeEngine.compute(1900, 2000, NOW, NOW, series, 1601);
		Assert.assertTrue("synthetic series should be viable for this test to be meaningful", expected.viable);

		List<Advisor.Suggestion> out = Advisor.advise(NOW, q, meta(), 0, new HashMap<>(), offers,
			new HashSet<>(), new HashSet<>(), 0, 0.01, 4, null, seriesByItem, 0);
		Advisor.Suggestion adjust = out.stream().filter(s -> s.type == Advisor.Suggestion.Type.ADJUST_SELL).findFirst().orElse(null);
		Assert.assertNotNull(adjust);
		Assert.assertEquals(TradeEngine.sellTarget(expected.sell, 2000), adjust.price);
		Assert.assertTrue("a sell must never be quoted under the bid", adjust.price >= 2000);
	}

	/** A no-margin day: the card and the offer screen say list at the
	 *  engine's honest sell (Advisor.heldSellPrice, the website's box), so a
	 *  sell listed there is not then told to come down to the insta-buy. */
	@Test
	public void aNoMarginSellListedAtTheCardsPriceIsLeftAlone()
	{
		final int n = 200;
		final TradeEngine.Series flat = new TradeEngine.Series();
		flat.labels = new long[n];
		flat.low = new double[n];
		flat.high = new double[n];
		flat.lowVol = new double[n];
		flat.highVol = new double[n];
		for (int i = 0; i < n; i++)
		{
			flat.labels[i] = NOW - (n - 1 - i) * 300L;
			flat.low[i] = 1000;
			flat.high[i] = 1010;
			flat.lowVol[i] = 50;
			flat.highVol[i] = 50;
		}
		final Map<Integer, Advisor.Quote> q = quotes(995, 1001);
		final TradeEngine.Result r = TradeEngine.viewTargets(1001, 995, NOW, NOW, flat, 1601);
		Assert.assertFalse("the case in hand: no margin", r.viable);
		final long card = Advisor.heldSellPrice(1601, q.get(1601), flat);
		Assert.assertEquals(r.sell, card);
		Assert.assertTrue("above the insta-buy", card > 995);

		final Map<Integer, TradeEngine.Series> seriesByItem = new HashMap<>();
		seriesByItem.put(1601, flat);
		final List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(sellOffer(1601, "Diamond", card));
		final List<Advisor.Suggestion> out = Advisor.advise(NOW, q, meta(), 0, new HashMap<>(), offers,
			new HashSet<>(), new HashSet<>(), 0, 0.01, 4, null, seriesByItem, 0);
		Assert.assertTrue("not told to drop to the insta-buy",
			out.stream().noneMatch(s -> s.type == Advisor.Suggestion.Type.ADJUST_SELL));
	}

	@Test
	public void adjustSellKeepsAnEngineTargetThatSitsAboveTheBid()
	{
		/* The companion to the clamp: when the engine's target is ABOVE the
		   standing bid it must pass through untouched. Without this, a clamp
		   bug that simply returned q.high every time would still pass the
		   tests above, since there the two happen to coincide. */
		Map<Integer, Advisor.Quote> q = quotes(1990, 1900); // bid below the series' own range
		TradeEngine.Series series = syntheticSeries(NOW, 200, 1900, 2000, 11);
		Map<Integer, TradeEngine.Series> seriesByItem = new HashMap<>();
		seriesByItem.put(1601, series);
		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(sellOffer(1601, "Diamond", 2500));

		TradeEngine.Result expected = TradeEngine.compute(1900, 1990, NOW, NOW, series, 1601);
		Assert.assertTrue("synthetic series should be viable", expected.viable);
		Assert.assertTrue("engine target must exceed the bid for this test to mean anything",
			expected.sell > 1990);

		List<Advisor.Suggestion> out = Advisor.advise(NOW, q, meta(), 0, new HashMap<>(), offers,
			new HashSet<>(), new HashSet<>(), 0, 0.01, 4, null, seriesByItem, 0);
		Advisor.Suggestion adjust = out.stream().filter(s -> s.type == Advisor.Suggestion.Type.ADJUST_SELL).findFirst().orElse(null);
		Assert.assertNotNull(adjust);
		Assert.assertEquals("the engine's own target survives when it is above the bid",
			expected.sell, adjust.price);
	}

	@Test
	public void adjustSellFallsBackToRawQuoteWithoutSeries()
	{
