	}

	/* ── Where a bank sell sits in the stream ────────────────────────────── */

	private static List<Advisor.Suggestion> streamWith(Map<Integer, long[]> costBasis)
	{
		final Map<Integer, Advisor.Quote> q = new HashMap<>();
		final Map<Integer, Advisor.ItemMeta> m = new HashMap<>();
		put(q, m, 1601, "Fresh idea", 2000, 1900);      // a real buy, ~6k profit
		put(q, m, 1602, "Old bank stock", 4000, 3800);  // a big held stack

		final Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(1602, 20_000);                     // ~78M of gross sale value

		return Advisor.advise(NOW, q, m, 10_000_000L, holdings, new ArrayList<>(),
			new HashSet<>(), new HashSet<>(), 0, 0.01, 4, costBasis, new HashMap<>(), 0);
	}

	private static int indexOfType(List<Advisor.Suggestion> out, Advisor.Suggestion.Type t)
	{
		for (int i = 0; i < out.size(); i++)
		{
			if (out.get(i).type == t) { return i; }
		}
		return -1;
	}

	/**
	 * The new-user case. Everything in a fresh install's bank predates the
	 * plugin, so every holding is untracked — and an untracked stack is ranked
	 * on gross SALE VALUE, which is not the same kind of number as a flip's
	 * profit. 78M of bank stock outscored a 6k flip by four orders of
	 * magnitude and led the stream every time, so a flip advisor read as a
	 * bank-clearing tool.
	 */
	@Test
	public void anUntrackedBankStackDoesNotLeadTheStream()
	{
		final List<Advisor.Suggestion> out = streamWith(null);
		final int sell = indexOfType(out, Advisor.Suggestion.Type.SELL);
		final int buy = indexOfType(out, Advisor.Suggestion.Type.BUY);
		Assert.assertTrue("the bank sell is still offered", sell >= 0);
		Assert.assertTrue("a buy is still offered", buy >= 0);
		Assert.assertTrue("buys must come before an untracked bank sell", buy < sell);
	}

	/**
	 * A sell the plugin DID watch you buy keeps its place ahead of the buys.
	 * There the profit is measured rather than assumed, and closing a position
	 * it can actually price is the more urgent of the two.
	 */
	@Test
	public void aTrackedSellStillLeadsTheStream()
	{
		final Map<Integer, long[]> basis = new HashMap<>();
		basis.put(1602, new long[]{20_000, 20_000L * 3000});  // bought at 3000 each
		final List<Advisor.Suggestion> out = streamWith(basis);
		final int sell = indexOfType(out, Advisor.Suggestion.Type.SELL);
		final int buy = indexOfType(out, Advisor.Suggestion.Type.BUY);
		Assert.assertTrue("a tracked sell is offered", sell >= 0);
		Assert.assertTrue("a buy is offered", buy >= 0);
		Assert.assertTrue("a MEASURED profit still outranks a buy idea", sell < buy);
	}

	/* ── Buy ordering ────────────────────────────────────────────────────── */

	private static void put(Map<Integer, Advisor.Quote> q, Map<Integer, Advisor.ItemMeta> m,
		int id, String name, long high, long low)
	{
		final Advisor.Quote quote = new Advisor.Quote();
		quote.high = high;
		quote.low = low;
		quote.highTime = NOW;
		quote.lowTime = NOW;
		q.put(id, quote);
		final Advisor.ItemMeta meta = new Advisor.ItemMeta();
		meta.id = id;
		meta.name = name;
		meta.limit = 100;
		meta.dailyVolume = 1_000_000L;
		m.put(id, meta);
	}

	/**
	 * A fresh idea outranks a bigger one you are already holding.
	 *
	 * The held item here makes strictly MORE money, so profit alone would put
	 * it first. It goes last anyway: you may have spent the 4-hour limit
	 * acquiring the stack already, and buying more of what you carry is a
	 * different bet from the new one underneath it.
	 */
	@Test
	public void buyIdeasForThingsYouAlreadyOwnSortLast()
	{
		final Map<Integer, Advisor.Quote> q = new HashMap<>();
		final Map<Integer, Advisor.ItemMeta> m = new HashMap<>();
		put(q, m, 1601, "Fresh idea", 2000, 1900);   // smaller edge
		put(q, m, 1602, "Already held", 4000, 3800); // bigger edge

		final Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(1602, 50);

		final List<Advisor.Suggestion> buys = Advisor.advise(NOW, q, m, 10_000_000L, holdings,
			new ArrayList<>(), new HashSet<>(), new HashSet<>(), 0, 0.01, 4, null, new HashMap<>(), 0)
			.stream().filter(s -> s.type == Advisor.Suggestion.Type.BUY)
			.collect(java.util.stream.Collectors.toList());

		Assert.assertEquals("both items are still offered — this reorders, it never drops",
			2, buys.size());
		Assert.assertEquals("the item you do not own comes first", 1601, buys.get(0).itemId);
		Assert.assertEquals("the one in your bank comes last, despite the bigger margin",
			1602, buys.get(1).itemId);
		Assert.assertTrue("...and it really was the more profitable of the two",
			buys.get(1).expectedProfit > buys.get(0).expectedProfit);
	}

	/** Within a group, nothing changed: profit still decides. */
	@Test
	public void amongUnheldIdeasProfitStillRanks()
	{
		final Map<Integer, Advisor.Quote> q = new HashMap<>();
		final Map<Integer, Advisor.ItemMeta> m = new HashMap<>();
		put(q, m, 1601, "Thin", 2000, 1900);
		put(q, m, 1602, "Fat", 4000, 3800);

		final List<Advisor.Suggestion> buys = Advisor.advise(NOW, q, m, 10_000_000L, new HashMap<>(),
			new ArrayList<>(), new HashSet<>(), new HashSet<>(), 0, 0.01, 4, null, new HashMap<>(), 0)
			.stream().filter(s -> s.type == Advisor.Suggestion.Type.BUY)
			.collect(java.util.stream.Collectors.toList());

		Assert.assertEquals(1602, buys.get(0).itemId);
		Assert.assertEquals(1601, buys.get(1).itemId);
	}

	/* ── Min. profit floor ───────────────────────────────────────────────── */

	private static List<Advisor.Suggestion> buysWithFloor(long floor)
	{
		return Advisor.advise(NOW, quotes(2000, 1900), meta(), 10_000_000L, new HashMap<>(), new ArrayList<>(),
			new HashSet<>(), new HashSet<>(), 0, 0.01, 4, null, new HashMap<>(), floor);
	}

	private static long buyProfit(List<Advisor.Suggestion> out)
	{
		return out.stream().filter(s -> s.type == Advisor.Suggestion.Type.BUY)
			.mapToLong(s -> s.expectedProfit).max().orElse(-1);
	}

	/** The only buy on offer clears ~6k, so it survives Auto and dies under a
	 *  20k floor. Both halves matter: the floor has to actually bind, and
	 *  passing 0 has to leave the old behaviour untouched. */
	@Test
	public void aProfitFloorRemovesIdeasThatDoNotClearIt()
	{
		Assert.assertTrue("the sample flip clears the advisor's own default floor",
			buyProfit(buysWithFloor(0)) > 0);
		Assert.assertEquals("nothing survives a floor above what the flip makes",
			-1, buyProfit(buysWithFloor(20_000)));
	}

	/**
	 * The relax-and-retry that keeps the panel from ever being empty must not
	 * relax past a floor the player set by hand.
	 *
	 * This is the whole bug the setting would otherwise have: advise() drops
	 * its volume and profit bars to nothing when the first pass finds no buys,
	 * which is right for "the market is thin" and exactly wrong for "don't
	 * show me anything under 500k" — the second pass would hand back the very
	 * idea the first pass just rejected.
	 */
	@Test
	public void theEmptyListFallbackStillRespectsAFloorTheUserSet()
	{
		final List<Advisor.Suggestion> out = buysWithFloor(20_000);
		Assert.assertTrue("the fallback pass must not resurrect a sub-floor idea",
			out.stream().noneMatch(s -> s.type == Advisor.Suggestion.Type.BUY));
	}

	// ---- freshness, per leg --------------------------------------------

	private static Map<Integer, Advisor.Quote> quotesAged(long high, long low, long highAgeSec, long lowAgeSec)
	{
		final Map<Integer, Advisor.Quote> m = quotes(high, low);
		m.get(1601).highTime = NOW - highAgeSec;
		m.get(1601).lowTime = NOW - lowAgeSec;
		return m;
	}

	private static List<Advisor.Suggestion> adviseWith(Map<Integer, Advisor.Quote> q, long cash,
		Map<Integer, Integer> holdings)
	{
		return Advisor.advise(NOW, q, meta(), cash, holdings, new ArrayList<>(),
			new HashSet<>(), new HashSet<>(), 0, 0.01, 4, new HashMap<>(), new HashMap<>(), 0);
	}

	/**
	 * The falling-knife case, and the reason freshness is per leg.
	 *
	 * On an item the market is walking down, the BID keeps printing — sellers
	 * are hitting it — while the ask goes quiet. So a three-hour-old high sits
	 * next to a one-minute-old low, and the gap between them is mostly the
	 * market having moved since. Scored as edge it is enormous, which sorted
	 * it straight to the top of the buy list.
	 */
	@Test
	public void aBuyIdeaNeedsBothSidesOfTheSpreadToBeLive()
	{
		final Map<Integer, Integer> none = new HashMap<>();
		Assert.assertTrue("both legs live is still a buy idea",
			adviseWith(quotesAged(2000, 1900, 60, 60), 10_000_000L, none).stream()
				.anyMatch(s -> s.type == Advisor.Suggestion.Type.BUY));
		Assert.assertTrue("a stale HIGH must not be scored against a live low",
			adviseWith(quotesAged(2000, 1900, 3 * 3600, 60), 10_000_000L, none).stream()
				.noneMatch(s -> s.type == Advisor.Suggestion.Type.BUY));
		Assert.assertTrue("and the mirror case, a stale low against a live high",
			adviseWith(quotesAged(2000, 1900, 60, 3 * 3600), 10_000_000L, none).stream()
				.noneMatch(s -> s.type == Advisor.Suggestion.Type.BUY));
	}

	/**
	 * The expensive, thin archetype: a Twisted bow trades a few dozen times a
	 * day, so its bid is routinely half an hour old. Under the buy window it
	 * was never a sell candidate at all — while the portfolio total and the
	 * watchlist row priced it off that very print without complaint.
	 */
	@Test
	public void aStackYouHoldStaysSellableOnAnOlderPrint()
	{
		final Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(1601, 100);
		final Advisor.Suggestion s = adviseWith(quotesAged(2000, 1900, 40 * 60, 40 * 60), 0, holdings)
			.stream().filter(x -> x.type == Advisor.Suggestion.Type.SELL).findFirst().orElse(null);
		Assert.assertNotNull("a 40-minute-old bid still prices a stack you own", s);
		Assert.assertEquals("and the card is told how old it is", 40 * 60, s.quoteAgeSec);

		final Advisor.Suggestion fresh = adviseWith(quotesAged(2000, 1900, 60, 60), 0, holdings)
			.stream().filter(x -> x.type == Advisor.Suggestion.Type.SELL).findFirst().orElse(null);
		Assert.assertNotNull(fresh);
		Assert.assertEquals("a current price says nothing about its age", 0, fresh.quoteAgeSec);

		Assert.assertTrue("but three hours is past arguing about",
			adviseWith(quotesAged(2000, 1900, 3 * 3600, 3 * 3600), 0, holdings).stream()
				.noneMatch(x -> x.type == Advisor.Suggestion.Type.SELL));
	}

	// ---- the adjust gate -----------------------------------------------

	/**
	 * The 972 wine case, reported from live play: an offer that is FILLING at
	 * 972 was told "your ask is above the market — re-list at 975".
	 *
	 * The gate asked whether the last print had moved past the offer's price;
	 * the advice came from the engine, which knows the last print is not the
	 * only fillable level. When they disagree the card told you to cancel a
	 * working offer and ask for MORE. One number answers both questions now.
	 */
	@Test
	public void noRepriceWhenTheTargetIsNotBelowYourAsk()
	{
		final Map<Integer, Advisor.Quote> q = quotes(940, 930);
		q.get(1601).highTime = NOW;
		q.get(1601).lowTime = NOW;
		final Map<Integer, TradeEngine.Series> series = new HashMap<>();
		series.put(1601, syntheticSeries(NOW, 60, 930, 990, 7));

		/* The numbers this fixture actually produces, checked rather than
		   assumed: the engine certifies a 979 sell, while the raw bid sits at
		   940. The OLD gate compared 940 against 972 x 0.99 = 962, fired, and
		   then printed max(979, 940) = 979 — a reprice UPWARDS, on an offer
		   that was filling. Guarded here so a fixture drift that stops
		   reproducing the bug fails loudly instead of passing vacuously. */
		final TradeEngine.Result eng = TradeEngine.compute(930, 940, NOW, NOW, series.get(1601), 1601);
		Assert.assertTrue("fixture must certify a target above the ask to be the bug at all",
			eng.viable && TradeEngine.sellTarget(eng.sell, 940) > 972);
		Assert.assertTrue("...and the raw print must be below it, or the old gate never fired",
			940 < Math.round(972 * 0.99));

		final List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(sellOffer(1601, "Diamond", 972));
		final List<Advisor.Suggestion> out = Advisor.advise(NOW, q, meta(), 0, new HashMap<>(), offers,
			new HashSet<>(), new HashSet<>(), 0, 0.01, 4, new HashMap<>(), series, 0);

		Assert.assertTrue("an ask the engine still rates at 979 is not stranded at 972",
			out.stream().noneMatch(s -> s.type == Advisor.Suggestion.Type.ADJUST_SELL));
	}

	/** The gate still fires when the target really has moved away — without a
	 *  series the target IS the raw print, so this is the old behaviour. */
	@Test
	public void aGenuinelyStrandedAskIsStillFlagged()
	{
		final Map<Integer, Advisor.Quote> q = quotes(500, 490);
		final List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(sellOffer(1601, "Diamond", 900));
		final List<Advisor.Suggestion> out = Advisor.advise(NOW, q, meta(), 0, new HashMap<>(), offers,
			new HashSet<>(), new HashSet<>(), 0, 0.01, 4, new HashMap<>(), new HashMap<>(), 0);
		final Advisor.Suggestion s = out.stream()
			.filter(x -> x.type == Advisor.Suggestion.Type.ADJUST_SELL).findFirst().orElse(null);
		Assert.assertNotNull("a 900 ask into a 500 bid is genuinely stranded", s);
		Assert.assertEquals(500, s.price);
	}

	// ---- the widen-retry ------------------------------------------------

	/**
	 * "Buy 40 Lobster pot for 1 gp ea", reported at a 344gp purse.
	 *
	 * The retry relaxed the volume floor and the profit floor together, to 0
	 * and to 1gp. Only the first of those is a reasonable response to an empty
	 * list: a quiet market is a reason to look further down the volume curve,
	 * and never a reason to call a 40gp trade an idea.
	 */
	@Test
	public void theWidenRetryNeverRelaxesTheProfitFloor()
	{
		final Map<Integer, Advisor.Quote> q = quotes(3, 1);
		final Map<Integer, Advisor.ItemMeta> m = meta();
		m.get(1601).limit = 40;
		m.get(1601).dailyVolume = 500L; // under every volume floor there is
		final List<Advisor.Suggestion> out = Advisor.advise(NOW, q, m, 344, new HashMap<>(),
			new ArrayList<>(), new HashSet<>(), new HashSet<>(), 250_000L, 0.01, 4,
			new HashMap<>(), new HashMap<>(), 0);
		Assert.assertTrue("an empty list says something true; a 40gp trade does not",
			out.stream().noneMatch(s -> s.type == Advisor.Suggestion.Type.BUY));
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

public class AnalystRatingTest
{
	private static Advisor.Quote quote(long low, long high)
	{
		Advisor.Quote q = new Advisor.Quote();
		q.low = low;
		q.high = high;
		return q;
	}

	private static AnalystRating.Average avg(long lo, long hi)
	{
		AnalystRating.Average a = new AnalystRating.Average();
		a.avgLowPrice = lo;
		a.avgHighPrice = hi;
		return a;
	}

	@Test
	public void atTypicalPriceIsHold()
	{
		AnalystRating.Grade g = AnalystRating.grade(quote(100, 100), avg(100, 100));
		Assert.assertEquals(AnalystRating.Label.HOLD, g.label);
		Assert.assertEquals(50, g.score);
	}

	@Test
	public void wellBelowTypicalIsStrongBuy()
	{
		AnalystRating.Grade g = AnalystRating.grade(quote(80, 80), avg(100, 100));
		Assert.assertEquals(AnalystRating.Label.STRONG_BUY, g.label);
		Assert.assertTrue(g.score >= 95);
	}

	@Test
	public void wellAboveTypicalIsStrongSell()
	{
		AnalystRating.Grade g = AnalystRating.grade(quote(120, 120), avg(100, 100));
		Assert.assertEquals(AnalystRating.Label.STRONG_SELL, g.label);
		Assert.assertTrue(g.score <= 5);
	}

	@Test
	public void scoreClampsAtBounds()
	{
		Assert.assertEquals(0, AnalystRating.grade(quote(1000, 1000), avg(100, 100)).score);
		Assert.assertEquals(100, AnalystRating.grade(quote(1, 1), avg(100, 100)).score);
	}

	@Test
	public void missingDataDegradesToNeutralHold()
	{
		Assert.assertEquals(AnalystRating.Label.HOLD, AnalystRating.grade(null, avg(100, 100)).label);
		Assert.assertEquals(AnalystRating.Label.HOLD, AnalystRating.grade(quote(100, 100), null).label);
	}
}

package com.pocketge.tracker;

import java.awt.BasicStroke;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.widgets.WidgetItem;
import org.junit.Assert;
import org.junit.Test;

/**
 * What the bank overlay actually PAINTS, recorded rather than eyeballed.
 *
 * The report was "diamonds are so highlighted I can't read them, double
 * border going on", and there were two reasons for it. A stroke is centred
 * on the path it follows, so the 2.5px ring laid straight along the slot
 * bounds put half its width outside the slot — a fat soft line hard against
 * the bank's own slot border, which is exactly what a doubled border looks
 * like. A second ring 3px further in made it three lines around a small pale
 * sprite. And the PocketGE mark was stamped on EVERY marked stack, so a bank
 * with nine sellable stacks wore nine icons: the thing meant to pick one slot
 * out of the crowd was on all of them.
 *
 * Counting rectangles is the only way to hold that down. "Looks fine now" is
 * how it got to three in the first place.
 *
 * The ring is four lines rather than one drawRect since the top edge had to
 * go see-through: the game prints the stack count along the top of the slot,
 * and a solid line there sat on the tops of the digits — "42,027" on a marked
 * inventory stack could not be read. So the recorder reassembles a ring from
 * the four lines that draw it, and the counting below is unchanged.
 */
public class BankHighlightOverlayTest
{
	private static final int SLOT = 36;

	/** Records the drawing calls that decide how busy a slot looks. */
	private static class Recorder
	{
		final List<Rectangle> rects = new ArrayList<>();
		final List<Float> strokes = new ArrayList<>();
		/** The stroke each ring's BODY was drawn at — the three solid sides.
		 *  Not the same as the last stroke seen: the faint top edge is drawn
		 *  after them and at 1px whatever the body weight is, so asserting on
		 *  the tail of {@link #strokes} would measure the wrong line. */
		final List<Float> ringStrokes = new ArrayList<>();
		/** Alpha of the colour each ring's TOP edge was drawn in. */
		final List<Integer> topAlphas = new ArrayList<>();
		int images;

		// -- reassembly ------------------------------------------------------

		/*
		 * The ring is drawn as a set of lines, and how MANY has already
		 * changed twice — four when the top edge went see-through, five when
		 * the left edge did too. So rings are counted by geometry rather than
		 * by line count: a rectangle has two vertical sides, so the number of
		 * DISTINCT x positions among the vertical lines is two per ring.
		 *
		 * That is exactly the property the "one ring, not two" rule is about.
		 * The bug it guards against was concentric rings a few pixels apart,
		 * which is two more distinct x values; splitting one edge into two
		 * segments at the same x is not.
		 */
		private final List<int[]> lines = new ArrayList<>();
		private float stroke = 1f;
		private java.awt.Color colour = java.awt.Color.WHITE;
		private final List<Float> lineStrokes = new ArrayList<>();
		private final List<Integer> lineAlphas = new ArrayList<>();

		void line(int x1, int y1, int x2, int y2)
		{
			lines.add(new int[]{x1, y1, x2, y2});
			lineStrokes.add(stroke);
			lineAlphas.add(colour.getAlpha());
		}

		/** Turn the recorded lines into the ring count and the ring's shape. */
		void finish()
		{
			final Set<Integer> verticalX = new LinkedHashSet<>();
			for (int[] l : lines)
			{
				if (l[0] == l[2])
				{
					verticalX.add(l[0]);
				}
			}
			final int count = verticalX.size() / 2;
			if (count == 0)
			{
				return;
			}
			Rectangle all = null;
			for (int[] l : lines)
			{
				final Rectangle seg = new Rectangle(Math.min(l[0], l[2]), Math.min(l[1], l[3]),
					Math.abs(l[2] - l[0]), Math.abs(l[3] - l[1]));
				all = all == null ? seg : all.union(seg);
			}
			for (int i = 0; i < count; i++)
			{
				rects.add(all);
				/* The BODY weight — the heaviest line in the ring. The faint
				   edges are drawn at 1px whatever the body is, so the minimum
				   would report 1 for every ring and the last-seen would
				   report whichever happened to be drawn last. */
				float body = 0f;
				for (Float f : lineStrokes)
				{
					body = Math.max(body, f);
				}
				ringStrokes.add(body);
				/* And the FAINTEST alpha, which is the see-through edge. */
				int faint = 255;
				for (Integer a : lineAlphas)
				{
					faint = Math.min(faint, a);
				}
				topAlphas.add(faint);
			}
		}
	}

	/** A Graphics2D that notes what it was asked to draw and does nothing. */
	private static Graphics2D recording(Recorder r)
	{
		final BufferedImage img = new BufferedImage(200, 200, BufferedImage.TYPE_INT_ARGB);
		return new java.awt.Graphics2D()
		{
			private final Graphics2D real = img.createGraphics();

			@Override
			public void drawRect(int x, int y, int w, int h)
			{
				r.rects.add(new Rectangle(x, y, w, h));
			}

			@Override
			public void setStroke(Stroke s)
			{
				if (s instanceof BasicStroke)
				{
					r.stroke = ((BasicStroke) s).getLineWidth();
					r.strokes.add(r.stroke);
				}
			}


			@Override
			public boolean drawImage(java.awt.Image i, int x, int y, java.awt.image.ImageObserver o)
			{
				r.images++;
				return true;
			}

			/* Everything else goes to a real off-screen Graphics2D, so the
			   overlay can set colours and hints without this class having to
			   stub out the whole of Graphics2D by hand. */
			@Override
			protected Object clone()
			{
				return this;
			}

			// --- delegation ------------------------------------------------
			@Override public void setRenderingHint(java.awt.RenderingHints.Key k, Object v) { real.setRenderingHint(k, v); }
			@Override public Object getRenderingHint(java.awt.RenderingHints.Key k) { return real.getRenderingHint(k); }
			@Override public void setColor(java.awt.Color c) { if (c != null) { r.colour = c; } real.setColor(c); }
			@Override public java.awt.Color getColor() { return real.getColor(); }
			@Override public Stroke getStroke() { return real.getStroke(); }
			@Override public java.awt.Font getFont() { return real.getFont(); }
			@Override public void setFont(java.awt.Font f) { real.setFont(f); }
			@Override public java.awt.FontMetrics getFontMetrics(java.awt.Font f) { return real.getFontMetrics(f); }
			@Override public java.awt.Rectangle getClipBounds() { return real.getClipBounds(); }
			@Override public void setClip(java.awt.Shape s) { real.setClip(s); }
			@Override public java.awt.Shape getClip() { return real.getClip(); }
			@Override public void setClip(int x, int y, int w, int h) { real.setClip(x, y, w, h); }
			@Override public void clipRect(int x, int y, int w, int h) { real.clipRect(x, y, w, h); }
