package com.pocketge.tracker;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Client;
import org.junit.Assert;
import org.junit.Test;

/**
 * The key beside the bank has a switch, and the switch works.
 *
 * "get rid of this your current suggestion / also worth selling. maybe hide
 * that in settings or off the ge bank menu. it covers the bank note" — after
 * it had already been moved once for covering the bank's tool row. The hover
 * tooltip on a marked slot says the same words, so the key became a setting.
 * Once its placement was fixed it went back on by default: "have it on by
 * default, the new location is fine".
 */
public class BankLegendSettingTest
{
	private static void set(Object o, String field, Object value) throws Exception
	{
		final Field f = o.getClass().getDeclaredField(field);
		f.setAccessible(true);
		f.set(o, value);
	}

	private static <T> T build(Class<T> cls) throws Exception
	{
		final Constructor<T> ctor = cls.getDeclaredConstructor();
		ctor.setAccessible(true);
		return ctor.newInstance();
	}

	/** A client that counts how often the legend went looking for the bank. */
	private static Client counting(AtomicInteger lookups)
	{
		return (Client) Proxy.newProxyInstance(
			Client.class.getClassLoader(),
			new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				if ("getWidget".equals(method.getName()))
				{
					lookups.incrementAndGet();
				}
				final Class<?> r = method.getReturnType();
				if (r == boolean.class)
				{
					return false;
				}
				if (r.isPrimitive())
				{
					return r == long.class ? 0L : 0;
				}
				return null;
			});
	}

	@Test
	public void drawsNothingUntilTurnedOn() throws Exception
	{
		final BankHighlightOverlay marks = build(BankHighlightOverlay.class);
		marks.setEnabled(true); // the marks themselves stay on by default
		final BankLegendOverlay legend = build(BankLegendOverlay.class);
		final AtomicInteger lookups = new AtomicInteger();
		set(legend, "client", counting(lookups));
		set(legend, "marks", marks);
		final Graphics2D g = new BufferedImage(10, 10, BufferedImage.TYPE_INT_ARGB).createGraphics();

		legend.render(g);
		Assert.assertEquals("off: the bank is not even looked for", 0, lookups.get());

		legend.setEnabled(true);
		legend.render(g);
		Assert.assertTrue("on: it goes looking for the bank to sit beside", lookups.get() > 0);
	}

	/** The setting's default, read from the source because the interface's
	 *  default method cannot be called without a running config manager. */
	@Test
	public void theSettingDefaultsOn() throws Exception
	{
		final String src = Files.readString(Path.of("src/main/java/com/pocketge/tracker/PocketGeTrackerConfig.java"));
		final int at = src.indexOf("default boolean bankLegend()");
		Assert.assertTrue("the setting exists", at > 0);
		final String body = src.substring(at, src.indexOf('}', at));
		Assert.assertTrue(body, body.contains("return true;"));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Method;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * The hover text on a marked bank stack.
 *
 * Reported twice as hard to read. The faults were structural rather than
 * cosmetic, so they are pinned here: the two marks laid the same facts out in
 * different orders, the one figure you came for was buried behind two words,
 * the per-unit line was painted a brown two shades off the tooltip
 * background, and the count that connects the two numbers was missing
 * entirely.
 */
public class BankTooltipTest
{
	private static String tip(Advisor.Suggestion s, boolean recommended) throws Exception
	{
		final Method m = BankHighlightOverlay.class
			.getDeclaredMethod("tooltipText", Advisor.Suggestion.class, boolean.class);
		m.setAccessible(true);
		return (String) m.invoke(null, s, recommended);
	}

	private static Advisor.Suggestion sell(long price, int qty, long gross, String whyNow)
	{
		final Advisor.Suggestion s = new Advisor.Suggestion(
			Advisor.Suggestion.Type.SELL, 1601, "Diamond", price, qty, gross, "reason");
		s.grossValue = gross;
		s.whyNow = whyNow;
		return s;
	}

	/** Both marks, same four lines, same order. */
	@Test
	public void bothMarksLayTheSameFactsOutTheSameWay()throws Exception
	{
		final Advisor.Suggestion s = sell(1_635, 18_608, 29_600_000L, "up 12% on what you paid");
		final List<String> mine = List.of(tip(s, true).split("</br>"));
		final List<String> also = List.of(tip(s, false).split("</br>"));
		Assert.assertEquals("same number of lines", mine.size(), also.size());
		Assert.assertEquals(4, mine.size());
		for (int i = 1; i < mine.size(); i++)
		{
			Assert.assertEquals("line " + (i + 1) + " is identical on both marks",
				mine.get(i), also.get(i));
		}
	}

	/** Line one names the mark in the legend's own words, so the player is
	 *  not matching two vocabularies for one colour. */
	@Test
	public void namesTheMarkTheWayTheLegendDoes() throws Exception
	{
		final Advisor.Suggestion s = sell(1_635, 18_608, 29_600_000L, null);
		Assert.assertTrue(tip(s, true).contains("Your current suggestion"));
		Assert.assertTrue(tip(s, false).contains("Also worth selling"));
		Assert.assertFalse("the old panel-speak is gone",
			tip(s, true).contains("This is the flip on your panel"));
	}

	/**
	 * The figure leads its line. "Worth selling: 29.6M gp" put two words in
	 * front of the only number the player opened the tooltip for.
	 */
	@Test
	public void theMoneyLeadsRatherThanFollowingALabel() throws Exception
	{
		final String t = tip(sell(1_635, 18_608, 29_600_000L, null), true);
		final String money = t.split("</br>")[1];
		Assert.assertFalse(money, money.contains("Worth selling"));
		Assert.assertTrue("the figure is first on its line",
			money.indexOf("29.6M gp") < money.indexOf("after tax"));
	}

	/**
	 * The count, which was missing. Claiming "29.6M gp" and "1,635 gp each"
	 * without the number between them left the headline uncheckable.
	 */
	@Test
	public void showsTheArithmeticItIsClaiming() throws Exception
	{
		final String t = tip(sell(1_635, 18_608, 29_600_000L, null), true);
		Assert.assertTrue(t, t.contains("18,608 at 1,635 gp each"));
	}

	/** Thousands separators, like everything else the plugin prints. */
	@Test
	public void separatesThousands() throws Exception
	{
		final String t = tip(sell(1_635, 18_608, 29_600_000L, null), true);
		Assert.assertFalse("no unseparated run of digits", t.contains("18608"));
		Assert.assertFalse(t.contains("1635"));
	}

	/**
	 * The unreadable brown is gone. 8a8274 sat two shades off the tooltip's
	 * own background, which is the line that came back in a screenshot as
	 * hard to read.
	 */
	@Test
	public void noLowContrastText() throws Exception
	{
		for (boolean rec : new boolean[]{true, false})
		{
			final String t = tip(sell(1_635, 18_608, 29_600_000L, "rated sell right now"), rec);
			Assert.assertFalse(t, t.contains("8a8274"));
		}
	}

	/** A recommended stack the suggestion map has no entry for still gets a
	 *  header, and must not throw or print a stray price. */
	@Test
	public void survivesAStackWithNoSuggestion() throws Exception
	{
		final String t = tip(null, true);
		Assert.assertTrue(t, t.contains("Your current suggestion"));
		Assert.assertFalse("nothing to price", t.contains("gp"));
	}

	/**
	 * One hue in the bank, and it is the SELL colour, because everything a
	 * bank square marks is something to sell. The live suggestion is picked
	 * out in white instead — the card's own LEAD_RIM, which is already how
	 * the sidebar says "this is the one you are acting on".
	 *
	 * Two earlier versions got this wrong: a hardcoded gold and the PROFIT
	 * green (which moved with nothing and made a claim about a stack the
	 * plugin had not valued), then the theme's buy/sell pair, which left one
	 * sell square painted in the BUY colour.
	 */
	@Test
	public void theBankSpeaksInTheThemesSellColourAndWhite() throws Exception
	{
		final PocketGeTrackerConfig.ColourTheme neon = PocketGeTrackerConfig.ColourTheme.NEON;
		BankHighlightOverlay.setTheme(neon.sell());
		try
		{
			final Advisor.Suggestion s = sell(1_635, 18_608, 29_600_000L, null);
			Assert.assertTrue("the live suggestion is white, like the card's lead box",
				tip(s, true).toLowerCase().contains("f2f2f2"));
			Assert.assertTrue("the rest are the theme's sell colour",
				tip(s, false).toLowerCase().contains("22e0ff"));
			Assert.assertFalse("never the buy colour — nothing here is a buy",
				tip(s, false).toLowerCase().contains("ff44b0"));
			Assert.assertFalse("and never the old hardcoded green",
				tip(s, false).toLowerCase().contains("1fb85c"));
		}
		finally
		{
			BankHighlightOverlay.setTheme(PocketGeTrackerConfig.ColourTheme.TERMINAL.sell());
		}
	}

	/**
	 * The stack's worth is proceeds, not profit, so it must not wear the
	 * profit colour. The sidebar spent three attempts learning that a figure
	 * in the profit green reads as profit however it is worded.
	 */
	@Test
	public void doesNotPaintProceedsAsProfit() throws Exception
	{
		final String t = tip(sell(1_635, 18_608, 29_600_000L, null), true);
		final String money = t.split("</br>")[1];
		Assert.assertFalse(money, money.toLowerCase().contains("1fb85c"));
	}

	/**
	 * Every colour in the tooltip moves with the theme, including the
	 * "why now" line.
	 *
	 * That one was a hardcoded 26a9ab — Terminal's teal — so it stayed teal
	 * under Neon, Cobalt and Orchid while the header and the square itself
	 * moved. A literal hex anywhere in this string is the bug.
	 */
	@Test
	public void noFrozenColourAnywhere() throws Exception
	{
		final PocketGeTrackerConfig.ColourTheme neon = PocketGeTrackerConfig.ColourTheme.NEON;
		BankHighlightOverlay.setTheme(neon.sell());
		try
		{
			final String t = tip(sell(1_635, 18_608, 29_600_000L, "rated sell right now"), false)
				.toLowerCase();
			Assert.assertFalse("Terminal's teal is frozen in", t.contains("26a9ab"));
			Assert.assertTrue("the why-now line is the theme's sell colour",
				t.contains("22e0ff"));
		}
		finally
		{
			BankHighlightOverlay.setTheme(PocketGeTrackerConfig.ColourTheme.TERMINAL.sell());
		}
	}

	/**
	 * What you paid, and on how many — asked for after the sidebar card grew
	 * the same line: "can we add hover over, paid x for x many, on bank stacks
	 * too i like that".
	 *
	 * The count is the half that cannot be dropped. A partly tracked stack is
	 * the ordinary case in a real bank, and a bare "Paid 1,141 gp each" on an
	 * 18,608 stack is a claim about all 18,608 when it is only true of 1,456.
	 */
	@Test
	public void saysWhatYouPaidAndOnHowManyOfThem() throws Exception
	{
		final Advisor.Suggestion s = sell(1_635, 18_608, 29_600_000L, null);
		s.unitCost = 1_141;
		s.trackedQty = 1_456;
		final String t = tip(s, true);
		Assert.assertTrue(t, t.contains("Paid 1,141 gp each on 1,456 of 18,608"));
	}

	/** A stack bought entirely through the plugin says so, rather than
	 *  printing "18,608 of 18,608" and leaving the reader to compare them. */
	@Test
	public void aFullyTrackedStackSaysAll() throws Exception
	{
		final Advisor.Suggestion s = sell(1_635, 18_608, 29_600_000L, null);
		s.unitCost = 1_141;
		s.trackedQty = 18_608;
		Assert.assertTrue(tip(s, true).contains("Paid 1,141 gp each on all 18,608"));
	}

	/**
	 * No tracked purchase, no line. An untracked stack has no honest "you
	 * paid" — and a dash or a zero in that slot is a worse answer than the
	 * absence of one.
	 */
	@Test
	public void saysNothingAboutCostItDoesNotHave() throws Exception
	{
		final Advisor.Suggestion s = sell(1_635, 18_608, 29_600_000L, null);
		s.hasTrackedCost = false;
		Assert.assertFalse(tip(s, true).contains("Paid"));
		s.unitCost = 1_141;
		s.trackedQty = 0;
		Assert.assertFalse("a price with nothing to apply it to", tip(s, true).contains("Paid"));
	}

	/** trackedQty can outrun the stack in the bank once part of it has been
	 *  withdrawn; "1,456 of 900" would be nonsense on a scoping line. */
	@Test
	public void neverScopesToMoreUnitsThanAreThere() throws Exception
	{
		final Advisor.Suggestion s = sell(1_635, 900, 1_400_000L, null);
		s.unitCost = 1_141;
		s.trackedQty = 1_456;
		Assert.assertTrue(tip(s, true).contains("Paid 1,141 gp each on all 900"));
	}

	/** Muted, like the count line it sits under — never the buy colour,
	 *  however much the word "paid" wants it. One hue in the bank. */
	@Test
	public void theCostLineDoesNotImportTheBuyColour() throws Exception
	{
		BankHighlightOverlay.setTheme(PocketGeTrackerConfig.ColourTheme.NEON.sell());
		try
		{
			final Advisor.Suggestion s = sell(1_635, 18_608, 29_600_000L, null);
			s.unitCost = 1_141;
			s.trackedQty = 1_456;
			String paid = "";
			for (String line : tip(s, true).split("</br>"))
			{
				if (line.contains("Paid"))
				{
					paid = line;
				}
			}
			Assert.assertTrue(paid, paid.contains("Paid"));
			Assert.assertTrue("muted, like the arithmetic above it", paid.contains("a5a5a5"));
			Assert.assertFalse("nothing here is a buy",
				paid.toLowerCase().contains("ff44b0"));
		}
		finally
		{
			BankHighlightOverlay.setTheme(PocketGeTrackerConfig.ColourTheme.TERMINAL.sell());
		}
	}

	/** "why doesnt tool tip say how much profit available as well? ...
	 *  should say -gp avaialble or + gp availabe": a marked stack you
	 *  bought says its gain as the card does, in the card's words. */
	@Test
	public void aMarkedStackYouBoughtSaysItsProfit() throws Exception
	{
		final Advisor.Suggestion s = new Advisor.Suggestion(
			Advisor.Suggestion.Type.SELL, 11230, "Dragon dart", 993, 6_193, 117_667L, "reason");
		s.grossValue = 6_193L * (993 - 19);
		s.unitCost = 955;
		s.trackedQty = 6_193;
		s.hasTrackedCost = true;
		final String t = tip(s, false);
		final String[] lines = t.split("</br>");
		/* "+117K" in the client; built with the formatter on the classpath,
		   as the hover is, so the stub's own rounding does not decide it. */
		Assert.assertTrue(lines[1], lines[1].contains("+"
			+ net.runelite.client.util.QuantityFormatter.quantityToStackSize(117_667L) + " gp profit available"));
		Assert.assertTrue("the card's green", lines[1].contains(Integer.toHexString(TipStyle.GOOD.getRGB() & 0xFFFFFF)));
		Assert.assertTrue("then what it fetches, plain", lines[2].contains("after tax"));
		Assert.assertTrue(t, t.contains("6,193 at 993 gp each"));

		s.hasTrackedCost = false;
		Assert.assertFalse("no cost, no profit claimed", tip(s, false).contains("profit"));
	}

	/** whyNow is optional, and its absence drops the line rather than
	 *  printing an empty one. */
	@Test
	public void dropsTheWhyLineWhenThereIsNoAnswer() throws Exception
	{
		final Advisor.Suggestion s = sell(1_635, 18_608, 29_600_000L, null);
		Assert.assertEquals(3, tip(s, true).split("</br>").length);
		s.whyNow = "up 12% on what you paid";
		Assert.assertEquals(4, tip(s, true).split("</br>").length);
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * A sell that has started selling: its hover says what it has made so far,
 * not only what the part still listed would add — "seee how i made 295k
 * emeralds. it should atleast say 295k of x amount total 85k left maybe?"
 */
public class BookedSoFarTest
{
	private static final int UNCUT_EMERALD = 1621;

	private static String words(String markup)
	{
		return markup.replaceAll("<[^>]*>", "").replaceAll("\\s+", " ").trim();
	}

	/** 7,950 bought at 317, listed at 372, 6,162 sold: 48 gp a unit after
	 *  the 7 gp tax, booked against the offer that sold them. */
	@Test
	public void anOfferKnowsWhatItsSalesBooked()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		final long now = System.currentTimeMillis();
		t.onOffer(now, 0, UNCUT_EMERALD, "Uncut emerald", true, 0, 0L, false);
		t.onOffer(now + 1_000, 0, UNCUT_EMERALD, "Uncut emerald", true, 7_950, 7_950L * 317, false);
		t.onOffer(now + 2_000, 1, UNCUT_EMERALD, "Uncut emerald", false, 0, 0L, false);
		t.onOffer(now + 3_000, 1, UNCUT_EMERALD, "Uncut emerald", false, 4_000, 4_000L * 372, false);
		t.onOffer(now + 4_000, 1, UNCUT_EMERALD, "Uncut emerald", false, 6_162, 6_162L * 372, false);

		final long[] booked = t.bookedBy(1);
		Assert.assertNotNull(booked);
		Assert.assertEquals("both fills, one trade", 6_162, booked[0]);
		Assert.assertEquals(6_162L * 48, booked[1]);
		Assert.assertNull("the buy booked nothing", t.bookedBy(0));
		Assert.assertNull("an empty slot booked nothing", t.bookedBy(5));

		/* Collected, and the slot takes a new sell: that offer has sold
		   nothing yet, whatever the last one made. */
		t.onOffer(now + 5_000, 1, 0, "", false, 0, 0L, true);
		t.onOffer(now + 6_000, 1, UNCUT_EMERALD, "Uncut emerald", false, 0, 0L, false);
		Assert.assertNull(t.bookedBy(1));
	}

	@Test
	public void theHoverSaysMadeSoFarAndWhatIsLeft()
	{
		final String box = words(GeOfferGridOverlay.moneyLine(false, 85_800L, 295_776L, 6_162, 6_162));
		Assert.assertTrue(box, box.startsWith("Made +295"));
		Assert.assertTrue(box, box.contains("so far, +85"));
		Assert.assertTrue(box, box.contains("to come (+381"));
		Assert.assertTrue(box, box.endsWith("in all)"));

		final GeSlotsPanel.SlotInfo s = new GeSlotsPanel.SlotInfo();
		s.buy = false;
		s.projectedProfit = 85_800L;
		s.bookedProfit = 295_776L;
		s.bookedUnits = 6_162;
		s.quantityFilled = 6_162;
		final String square = words(GeSlotsPanel.moneyLine(s));
		Assert.assertEquals("the square says what the box says", box, square);
	}

	/**
	 * Sold partly where the plugin could not book it — on mobile, between
	 * logins — the figure says what it covers and claims no total: 4,000
	 * sold unseen and 162 since read "Made +7.7K so far ... +189K in all"
	 * for an offer that had made about +200K.
	 */
	@Test
	public void aFigureBookedOnSomeOfTheSalesSaysSo()
	{
		final String box = words(GeOfferGridOverlay.moneyLine(false, 181_824L, 7_776L, 162, 4_162));
		Assert.assertTrue(box, box.contains("on 162 of 4,162 sold"));
		Assert.assertFalse(box, box.contains("in all"));
		Assert.assertFalse(box, box.contains("so far"));

		final GeSlotsPanel.SlotInfo s = new GeSlotsPanel.SlotInfo();
		s.projectedProfit = 181_824L;
		s.bookedProfit = 7_776L;
		s.bookedUnits = 162;
		s.quantityFilled = 4_162;
		Assert.assertEquals("the square says what the box says", box, words(GeSlotsPanel.moneyLine(s)));
	}

	/** Booked on the offer as it sells, so other slots' trading — the
	 *  flips list keeps only the newest 500 — cannot take it away, and it
	 *  survives a restart. */
	@Test
	public void theTotalSurvivesOtherTradingAndARestart()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		final long now = System.currentTimeMillis();
		t.onOffer(now, 0, UNCUT_EMERALD, "Uncut emerald", true, 0, 0L, false);
		t.onOffer(now + 1, 0, UNCUT_EMERALD, "Uncut emerald", true, 7_950, 7_950L * 317, false);
		t.onOffer(now + 2, 1, UNCUT_EMERALD, "Uncut emerald", false, 0, 0L, false);
		t.onOffer(now + 3, 1, UNCUT_EMERALD, "Uncut emerald", false, 6_000, 6_000L * 372, false);
		/* 600 flips of something else, in another slot. */
		t.onOffer(now + 10, 2, 565, "Blood rune", true, 0, 0L, false);
		t.onOffer(now + 11, 2, 565, "Blood rune", true, 600, 600L * 290, false);
		t.onOffer(now + 12, 2, 565, "Blood rune", true, 600, 600L * 290, true);
		t.onOffer(now + 13, 3, 565, "Blood rune", false, 0, 0L, false);
		for (int i = 1; i <= 600; i++)
		{
			t.onOffer(now + 100 + i, 3, 565, "Blood rune", false, i, i * 310L, false);
		}
		Assert.assertArrayEquals(new long[]{6_000, 6_000L * 48}, t.bookedBy(1));

		final FlipTracker after = new FlipTracker();
		after.restore(new com.google.gson.Gson().fromJson(new com.google.gson.Gson().toJson(t.snapshot()),
			FlipTracker.State.class));
		after.setAccountHash(42L);
		Assert.assertArrayEquals("through a restart", new long[]{6_000, 6_000L * 48}, after.bookedBy(1));
	}

	/** A sell already part-sold under a build that counted its total off
	 *  the flips list: after the upgrade, its total is the same. */
	@Test
	public void aSaveFromBeforeTheTotalIsSeededFromItsFlips()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		final long now = System.currentTimeMillis();
		t.onOffer(now, 0, UNCUT_EMERALD, "Uncut emerald", true, 0, 0L, false);
		t.onOffer(now + 1, 0, UNCUT_EMERALD, "Uncut emerald", true, 7_950, 7_950L * 317, false);
		t.onOffer(now + 2, 1, UNCUT_EMERALD, "Uncut emerald", false, 0, 0L, false);
		t.onOffer(now + 3, 1, UNCUT_EMERALD, "Uncut emerald", false, 6_162, 6_162L * 372, false);
		final FlipTracker.State saved = t.snapshot();
		/* As the earlier build wrote them: eight fields to a slot row. */
		for (java.util.Map<Integer, long[]> rows : saved.slotsByAccount.values())
		{
			rows.replaceAll((slot, row) -> java.util.Arrays.copyOf(row, 8));
		}
		final FlipTracker after = new FlipTracker();
		after.restore(new com.google.gson.Gson().fromJson(new com.google.gson.Gson().toJson(saved), FlipTracker.State.class));
		after.setAccountHash(42L);
		Assert.assertArrayEquals(new long[]{6_162, 6_162L * 48}, after.bookedBy(1));
		Assert.assertNull("the buy slot booked nothing", after.bookedBy(0));
	}

	/** Nothing sold yet, and a buy: the one line, as before. */
	@Test
	public void beforeTheFirstSaleItIsTheOneLine()
	{
		Assert.assertTrue(words(GeOfferGridOverlay.moneyLine(false, 85_800L, null, 0, 0)).startsWith("Profit: +"));
		Assert.assertTrue(words(GeOfferGridOverlay.moneyLine(true, 60_000L, null, 0, 0)).startsWith("Profit if it flips: +"));
		Assert.assertNull(GeOfferGridOverlay.moneyLine(false, null, null, 0, 0));

		final GeSlotsPanel.SlotInfo buy = new GeSlotsPanel.SlotInfo();
		buy.buy = true;
		buy.projectedProfit = 60_000L;
		Assert.assertEquals(words(GeOfferGridOverlay.moneyLine(true, 60_000L, null, 0, 0)), words(GeSlotsPanel.moneyLine(buy)));
	}

	/** A loss reads as one, in both places. */
	@Test
	public void aLossIsSigned()
	{
		final String box = words(GeOfferGridOverlay.moneyLine(false, -20_000L, 5_000L, 100, 100));
		Assert.assertTrue(box, box.contains(", -20"));
		Assert.assertTrue(box, box.contains("to come (-15"));
	}
}

package com.pocketge.tracker;

import java.awt.Color;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * The sidebar wears pocketge.com's colours, and keeps wearing them.
 *
 * The card had been the site's {@code --bg-panel} since it was built and
 * everything around it was RuneLite's stock grey, which reads as exactly what
 * it was: a warm brown panel in a grey box. Spotted from a screenshot — "im
 * not crazy right, that top section is brown? i like it alot, matches the
 * website".
 *
 * These values are copied from {@code app.css}. Nothing in this repo can read
 * that file, so the copy is pinned here against the custom property it came
 * from: a change on either side has to be made on both, deliberately.
 */
public class BrandTest
{
	/** Every surface colour, against the CSS custom property it was taken
	 *  from. Keep in step with app.css :root. */
	private static final Map<String, Color> FROM_APP_CSS = Map.of(
		"--bg-base", Brand.BG_BASE,
		"--bg-chart", Brand.BG_CHART,
		"--bg-panel", Brand.BG_PANEL,
		"--bg-input", Brand.BG_INPUT,
		"--border-main", Brand.BORDER_MAIN,
		"--border-light", Brand.BORDER_LIGHT,
		"--text-main", Brand.TEXT_MAIN,
		"--text-structural", Brand.TEXT_STRUCTURAL,
		"--text-muted", Brand.TEXT_MUTED,
		"--accent-bright", Brand.ACCENT_BRIGHT);

	private static final Map<String, String> EXPECTED = Map.of(
		"--bg-base", "0c0b09",
		"--bg-chart", "131110",
		"--bg-panel", "1b1815",
		"--bg-input", "282320",
		"--border-main", "2b2621",
		"--border-light", "3c352b",
		"--text-main", "d9d3c7",
		"--text-structural", "948a78",
		"--text-muted", "8a8274",
		"--accent-bright", "e5c158");

	private static String hex(Color c)
	{
		return String.format("%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}

	@Test
	public void everySurfaceIsTheWebsitesOwn()
	{
		for (Map.Entry<String, Color> e : FROM_APP_CSS.entrySet())
		{
			Assert.assertEquals("app.css " + e.getKey(),
				EXPECTED.get(e.getKey()), hex(e.getValue()));
		}
	}

	/**
	 * The card's own background is the same object the rest of the sidebar is
	 * laid out against — not a second copy of 1B1815 that can drift.
	 */
	@Test
	public void theCardAndTheBrandAgreeOnThePanelColour() throws Exception
	{
		final String src = Files.readString(
			Path.of("src/main/java/com/pocketge/tracker/AdvisorPanel.java"));
		Assert.assertTrue("OBSIDIAN_BG should come from Brand",
			src.contains("OBSIDIAN_BG = Brand.BG_PANEL"));
	}

	/**
	 * No panel reaches for a RuneLite grey any more.
	 *
	 * DARK/DARKER/MEDIUM_GRAY are neutral, and one of them left in a warm
	 * sidebar is a grey rectangle in a brown column — which is the defect
	 * this whole change is about, at the scale of a single widget.
	 *
	 * LIGHT_GRAY_COLOR is on the list too. It was the label colour on 34
	 * labels; the site paints those {@code --text-structural}, which is warm.
	 */
	@Test
	public void noSidebarPanelStillUsesARuneliteGrey() throws Exception
	{
		final List<String> panels = List.of(
			"AdvisorPanel", "FavoritesPanel", "FinderPanel", "GeSlotsPanel",
			"HistoryPanel", "MainPanel", "StatsHeaderPanel");
		for (String cls : panels)
		{
			final Path p = Path.of("src/main/java/com/pocketge/tracker/" + cls + ".java");
			if (!Files.exists(p))
			{
				continue;
			}
			final String src = stripComments(Files.readString(p));
			for (String grey : List.of("DARK_GRAY_COLOR", "DARKER_GRAY_COLOR",
				"MEDIUM_GRAY_COLOR", "LIGHT_GRAY_COLOR"))
			{
				Assert.assertFalse(cls + " still uses ColorScheme." + grey,
					src.contains("ColorScheme." + grey));
			}
		}
	}

	/**
	 * The label colour stays readable on the surfaces it is actually drawn on.
	 *
	 * Warm is not worth much if it cannot be read: {@code --text-structural}
	 * is a step darker than the neutral grey it replaced, and it sits on the
	 * two darkest surfaces in the plugin. WCAG AA for body text is 4.5:1.
	 */
	@Test
	public void theLabelColourClearsAaOnEverySurfaceItIsUsedOn()
	{
		for (Color bg : List.of(Brand.BG_BASE, Brand.BG_PANEL, Brand.BG_INPUT))
		{
			final double ratio = contrast(Brand.TEXT_STRUCTURAL, bg);
			Assert.assertTrue("structural text on " + hex(bg) + " is only "
				+ String.format("%.1f", ratio) + ":1", ratio >= 4.5);
		}
		Assert.assertTrue("and item names are brighter still",
			contrast(Brand.TEXT_MAIN, Brand.BG_PANEL)
				> contrast(Brand.TEXT_STRUCTURAL, Brand.BG_PANEL));
	}

	/**
	 * The buy and sell hues are NOT here.
	 *
	 * They are the player's, chosen in settings. A frozen copy in the brand
	 * palette would be a second, unthemed source for the two colours that
	 * carry the plugin's only real meaning — the drift the bank marks and the
	 * watchlist badges have each been fixed for once already.
	 */
	@Test
	public void theBrandDoesNotFreezeTheBuyAndSellColours() throws Exception
	{
		final String src = stripComments(Files.readString(
			Path.of("src/main/java/com/pocketge/tracker/Brand.java")));
		for (String themed : List.of("BUY", "SELL"))
		{
			Assert.assertFalse("Brand should not name a " + themed + " colour",
				src.contains("Color " + themed));
		}
		Assert.assertFalse("nor the default theme's values",
			src.toLowerCase().contains("0xe5, 0xb8, 0x42")
				|| src.toLowerCase().contains("0x26, 0xa9, 0xab"));
	}

	private static String stripComments(String s)
	{
		return s.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
	}

	/** WCAG relative luminance contrast ratio. */
	private static double contrast(Color a, Color b)
	{
		final double la = luminance(a);
		final double lb = luminance(b);
		return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
	}

	private static double luminance(Color c)
	{
		final double[] v = new double[3];
		final int[] raw = {c.getRed(), c.getGreen(), c.getBlue()};
		for (int i = 0; i < 3; i++)
		{
			final double s = raw[i] / 255d;
			v[i] = s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
		}
		return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2];
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.After;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * Who the local bridge will talk to.
 *
 * The hub submission said "requests from any other origin are refused", and
 * it was not true: CORS only stops a foreign page READING a reply, so a POST
 * from any site open in the same browser still landed and edited your
 * favourite lists. These pin the rule to the code — first as the pure rule,
 * then over a real socket.
 *
 * What the rule is FOR is other websites in the browser, which cannot fake
 * an Origin. A program on the same machine can send any header, and these
 * tests do not claim otherwise.
 */
public class BridgeAccessTest
{
	private static final String SITE = "https://pocketge.com";
	private static final int PORT = 8477;
	private static final String HOST = "127.0.0.1:" + PORT;

	// -- the rule ----------------------------------------------------------

	@Test
	public void servesThePocketGeSite()
	{
		Assert.assertNull(LocalBridgeServer.refusal("GET", SITE, HOST, null, PORT));
		Assert.assertNull(LocalBridgeServer.refusal("GET", "https://www.pocketge.com", HOST, null, PORT));
		Assert.assertNull(LocalBridgeServer.refusal("POST", SITE, HOST, "application/json", PORT));
		Assert.assertNull("charset is fine",
			LocalBridgeServer.refusal("POST", SITE, HOST, "application/json; charset=utf-8", PORT));
		Assert.assertNull("a preflight carries no body type",
			LocalBridgeServer.refusal("OPTIONS", SITE, HOST, null, PORT));
	}

	@Test
	public void refusesAnyOtherOrigin()
	{
		Assert.assertEquals("origin", LocalBridgeServer.refusal("GET", "https://evil.example", HOST, null, PORT));
		Assert.assertEquals("origin", LocalBridgeServer.refusal("GET", "http://pocketge.com", HOST, null, PORT));
		Assert.assertEquals("origin", LocalBridgeServer.refusal("GET", "https://pocketge.com.evil.example", HOST, null, PORT));
		Assert.assertEquals("origin", LocalBridgeServer.refusal("GET", "null", HOST, null, PORT));
	}

	/** No Origin at all is not the site's own fetch, which always carries
	 *  one. */
	@Test
	public void refusesNoOrigin()
	{
		Assert.assertEquals("origin", LocalBridgeServer.refusal("GET", null, HOST, null, PORT));
		Assert.assertEquals("origin", LocalBridgeServer.refusal("POST", null, HOST, "application/json", PORT));
	}

	/** DNS rebinding: a page that points its own name at 127.0.0.1 still
	 *  sends its own name as the Host. */
	@Test
	public void refusesAForeignHost()
	{
		Assert.assertEquals("host", LocalBridgeServer.refusal("GET", SITE, "evil.example:" + PORT, null, PORT));
		Assert.assertEquals("host", LocalBridgeServer.refusal("GET", SITE, "127.0.0.1:9999", null, PORT));
		Assert.assertEquals("host", LocalBridgeServer.refusal("GET", SITE, null, null, PORT));
		Assert.assertNull(LocalBridgeServer.refusal("GET", SITE, "localhost:" + PORT, null, PORT));
		Assert.assertNull(LocalBridgeServer.refusal("GET", SITE, "[::1]:" + PORT, null, PORT));
	}

	/** A write must say it is JSON — which is what makes the browser ask
	 *  first. A form post or text/plain is the shape a cross-site write
	 *  takes to avoid that question. */
	@Test
	public void refusesAWriteThatIsNotJson()
	{
		Assert.assertEquals("content-type", LocalBridgeServer.refusal("POST", SITE, HOST, "text/plain", PORT));
		Assert.assertEquals("content-type",
			LocalBridgeServer.refusal("POST", SITE, HOST, "application/x-www-form-urlencoded", PORT));
		Assert.assertEquals("content-type", LocalBridgeServer.refusal("POST", SITE, HOST, null, PORT));
	}

	// -- over a socket -------------------------------------------------------

	private LocalBridgeServer bridge;
	private final List<String> writes = new ArrayList<>();

	@Before
	public void start() throws Exception
	{
		bridge = new LocalBridgeServer(new Gson());
		bridge.start(0, () ->
		{
			final Map<String, Object> m = new HashMap<>();
			m.put("secret", "your flips");
			return m;
		}, HashMap::new,
			(listId, itemId, name, remove) -> writes.add(itemId + ":" + remove),
			new LocalBridgeServer.ListWriter()
			{
				@Override
				public String create(String name)
				{
					writes.add("create:" + name);
					return "l1";
				}

				@Override
				public void rename(String listId, String name)
				{
					writes.add("rename");
				}

				@Override
				public void delete(String listId)
				{
					writes.add("delete");
				}

				@Override
				public void reorder(String listId, List<Integer> itemIds)
				{
					writes.add("reorder");
				}
			});
	}

	@After
	public void stop()
	{
		bridge.stop();
	}

	/** Raw HTTP so the test controls Origin and Host, which Java's own
	 *  clients will not let a caller set. Returns the whole response. */
	private String send(String method, String path, String origin, String host, String type, String body)
		throws Exception
	{
		try (Socket s = new Socket(InetAddress.getLoopbackAddress(), bridge.port()))
		{
			s.setSoTimeout(5_000);
			final byte[] b = body == null ? new byte[0] : body.getBytes(StandardCharsets.UTF_8);
			final StringBuilder req = new StringBuilder();
			req.append(method).append(' ').append(path).append(" HTTP/1.1\r\n");
			req.append("Host: ").append(host).append("\r\n");
			if (origin != null)
			{
				req.append("Origin: ").append(origin).append("\r\n");
			}
			if (type != null)
			{
				req.append("Content-Type: ").append(type).append("\r\n");
			}
			req.append("Content-Length: ").append(b.length).append("\r\n");
			req.append("Connection: close\r\n\r\n");
			final OutputStream out = s.getOutputStream();
			out.write(req.toString().getBytes(StandardCharsets.UTF_8));
			out.write(b);
			out.flush();
			final InputStream in = s.getInputStream();
			final ByteArrayOutputStream got = new ByteArrayOutputStream();
			final byte[] buf = new byte[4096];
			int n;
			try
			{
				while ((n = in.read(buf)) > 0)
				{
					got.write(buf, 0, n);
				}
			}
			catch (java.net.SocketTimeoutException done)
			{
				// keep-alive despite Connection: close — what arrived is the answer
			}
			return got.toString(StandardCharsets.UTF_8);
		}
	}

	private String host()
	{
		return "127.0.0.1:" + bridge.port();
	}

	private static int status(String response)
	{
		return Integer.parseInt(response.substring(9, 12));
	}

	/** The portfolio over time, for the chart on the flip history page: to
	 *  the site, and to nobody else — it is as private as the ledger. */
	@Test
	public void servesThePortfolioToTheSiteOnly() throws Exception
	{
		bridge.setPortfolioSource(() ->
		{
			final Map<String, Object> m = new HashMap<>();
			m.put("points", java.util.Arrays.asList(new long[]{1_790_000_000_000L, 148_000_000L}));
			return m;
		});
		final String ok = send("GET", "/portfolio", SITE, host(), null, null);
		Assert.assertEquals(200, status(ok));
		Assert.assertTrue(ok, ok.contains("[[1790000000000,148000000]]"));
		Assert.assertEquals(403, status(send("GET", "/portfolio", "https://evil.example", host(), null, null)));
	}

	/** No source yet — the plugin has not sampled anyone — is an empty
	 *  answer, not an error the page has to tell apart from "too old". */
	@Test
	public void noPortfolioYetIsEmptyNotAnError() throws Exception
	{
		final String r = send("GET", "/portfolio", SITE, host(), null, null);
		Assert.assertEquals(200, status(r));
		Assert.assertTrue(r, r.endsWith("{}"));
	}

	@Test
	public void theSiteGetsItsData() throws Exception
	{
		final String r = send("GET", "/flips", SITE, host(), null, null);
		Assert.assertEquals(r, 200, status(r));
		Assert.assertTrue(r.contains("your flips"));
		Assert.assertTrue(r.toLowerCase().contains("access-control-allow-origin: " + SITE));
		Assert.assertTrue("a served poll counts as an open tab", bridge.lastPollAt() > 0);
	}

	@Test
	public void aCurlGetsNothing() throws Exception
	{
		final String r = send("GET", "/flips", null, host(), null, null);
		Assert.assertEquals(403, status(r));
		Assert.assertFalse(r.contains("your flips"));
		Assert.assertEquals("and does not count as a tab", 0, bridge.lastPollAt());
	}

	@Test
	public void anotherSiteGetsNothing() throws Exception
	{
		for (String path : new String[]{"/flips", "/history", "/status", "/nav?since=1"})
		{
			final String r = send("GET", path, "https://evil.example", host(), null, null);
			Assert.assertEquals(path, 403, status(r));
			Assert.assertFalse(path, r.toLowerCase().contains("access-control-allow-origin"));
		}
	}

	/** The one that mattered: the write used to land even though the
	 *  foreign page could not read the reply. */
	@Test
	public void anotherSiteCannotWrite() throws Exception
	{
		Assert.assertEquals(403, status(send("POST", "/favorites", "https://evil.example", host(),
			"application/json", "{\"id\":1601}")));
		Assert.assertEquals(403, status(send("POST", "/favoriteLists", "https://evil.example", host(),
			"application/json", "{\"action\":\"delete\",\"listId\":\"x\"}")));
		Assert.assertEquals("a text/plain post skips the preflight; it must not skip us",
			403, status(send("POST", "/favorites", "https://evil.example", host(), "text/plain", "{\"id\":1601}")));
		Assert.assertTrue("nothing was written: " + writes, writes.isEmpty());
	}

	@Test
	public void theSiteCanWrite() throws Exception
	{
		Assert.assertEquals(200, status(send("POST", "/favorites", SITE, host(),
			"application/json", "{\"id\":1601,\"name\":\"Diamond\"}")));
		Assert.assertEquals(List.of("1601:false"), writes);
	}

	@Test
	public void theSitesWritesMustBeJson() throws Exception
	{
		Assert.assertEquals(415, status(send("POST", "/favorites", SITE, host(), "text/plain", "{\"id\":1601}")));
		Assert.assertTrue(writes.isEmpty());
	}

	@Test
	public void aRebindingHostIsRefused() throws Exception
	{
		Assert.assertEquals(403, status(send("GET", "/flips", SITE, "evil.example:" + bridge.port(), null, null)));
	}

	/** The preflight is answered for the site — including Chrome's
	 *  private-network question — and refused for anyone else. */
	@Test
	public void preflightOnlyForTheSite() throws Exception
	{
		final String ok = send("OPTIONS", "/favorites", SITE, host(), null, null);
		Assert.assertEquals(204, status(ok));
		Assert.assertTrue(ok.toLowerCase().contains("access-control-allow-private-network: true"));
		Assert.assertEquals(403, status(send("OPTIONS", "/favorites", "https://evil.example", host(), null, null)));
	}
}

package com.pocketge.tracker;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseEvent;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import org.junit.Assert;
import org.junit.Test;

/**
 * The one-time card for someone with flips to see and the bridge off:
 * "unlinked people should be maybe encouraged wih a 1 time popup message
 * suggesting to link".
 */
public class BridgeNudgeTest
{
	private final List<String> calls = new ArrayList<>();

	private MainPanel panel()
	{
		final MainPanel.Actions actions = (MainPanel.Actions) Proxy.newProxyInstance(
			MainPanel.Actions.class.getClassLoader(), new Class<?>[]{MainPanel.Actions.class},
			(proxy, method, args) ->
			{
				calls.add(method.getName());
				final Class<?> t = method.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				if (t == int.class || t == long.class || t == double.class || t == float.class)
				{
					return 0;
				}
				return null;
			});
		return new MainPanel(null, actions);
	}

	private static JLabel label(Container root, String text)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof JLabel && text.equals(((JLabel) c).getText()))
			{
				return (JLabel) c;
			}
			if (c instanceof Container)
			{
				final JLabel in = label((Container) c, text);
				if (in != null)
				{
					return in;
				}
			}
		}
		return null;
	}

	private static void click(JLabel l)
	{
		l.dispatchEvent(new MouseEvent(l, MouseEvent.MOUSE_CLICKED, 0L, 0, 2, 2, 1, false, MouseEvent.BUTTON1));
	}

	/** Hidden until the plugin says so, and gone at once on either answer. */
	@Test
	public void itShowsOnceAndEitherAnswerEndsIt()
	{
		final MainPanel p = panel();
		final JLabel link = label(p, "Link it ↗");
		final JLabel later = label(p, "Not now");
		Assert.assertNotNull(link);
		Assert.assertNotNull(later);
		final Component card = link.getParent().getParent();
		Assert.assertFalse("not until asked for", card.isVisible());

		p.setBridgeNudge(true);
		Assert.assertTrue(card.isVisible());
		click(later);
		Assert.assertFalse(card.isVisible());
		Assert.assertTrue(calls.contains("dismissBridgeNudge"));

		p.setBridgeNudge(true);
		click(link);
		Assert.assertFalse(card.isVisible());
		Assert.assertTrue(calls.contains("linkWebsite"));
	}
}

package com.pocketge.tracker;

import java.io.FileInputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Properties;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Assert;
import org.junit.Test;

/** The version the plugin reports is the one the hub shows. */
public class BuildInfoTest
{
	@Test
	public void theVersionMatchesTheHubsAndGradles() throws Exception
	{
		final Properties p = new Properties();
		try (FileInputStream in = new FileInputStream("runelite-plugin.properties"))
		{
			p.load(in);
		}
		Assert.assertEquals("runelite-plugin.properties", p.getProperty("version"), BuildInfo.VERSION);
		final Matcher m = Pattern.compile("(?m)^version = '([^']+)'")
			.matcher(new String(Files.readAllBytes(Paths.get("build.gradle")), StandardCharsets.UTF_8));
		Assert.assertTrue("build.gradle has a version line", m.find());
		Assert.assertEquals("build.gradle", m.group(1), BuildInfo.VERSION);
	}

	/** Three plain numbers, the last moved on per update — what
	 *  tools/dev/bump-version.sh counts up. */
	@Test
	public void theVersionIsThreeNumbers()
	{
		Assert.assertTrue(BuildInfo.VERSION, BuildInfo.VERSION.matches("\\d+\\.\\d+\\.\\d+"));
	}

	/** Installed from the hub the class is in a jar: the stamp is that
	 *  entry's time, read from the jar file itself. */
	@Test
	public void aJarBuildReadsItsEntrysTime() throws Exception
	{
		final java.io.File jar = java.io.File.createTempFile("pocketge build", ".jar");
		jar.deleteOnExit();
		final long when = 1_790_000_000_000L;
		try (java.util.jar.JarOutputStream out = new java.util.jar.JarOutputStream(new java.io.FileOutputStream(jar)))
		{
			final java.util.jar.JarEntry e = new java.util.jar.JarEntry("com/pocketge/tracker/BuildInfo.class");
			e.setTime(when);
			out.putNextEntry(e);
			out.write(new byte[]{1, 2, 3});
			out.closeEntry();
		}
		final java.net.URL url = new java.net.URL("jar:" + jar.toURI() + "!/com/pocketge/tracker/BuildInfo.class");
		Assert.assertEquals("a space in the path is fine too", when / 2000, BuildInfo.jarEntryTime(url) / 2000);
		Assert.assertEquals("no such entry", 0, BuildInfo.jarEntryTime(
			new java.net.URL("jar:" + jar.toURI() + "!/nothing.class")));
		Assert.assertEquals("not a jar", 0, BuildInfo.jarEntryTime(jar.toURI().toURL()));
	}

	/**
	 * The plugin hub's scan refuses URL.openConnection, and HTTP that does
	 * not go through RuneLite's OkHttpClient ("URL::openConnection is not
	 * allowed, @Inject and use RuneLite's OkHttpClient instead" on the 0.7.2
	 * PR). Caught here rather than by a reviewer.
	 */
	@Test
	public void nothingOpensItsOwnConnection() throws Exception
	{
		final java.util.List<String> found = new java.util.ArrayList<>();
		try (java.util.stream.Stream<java.nio.file.Path> files = Files.walk(Paths.get("src/main/java")))
		{
			for (java.nio.file.Path f : (Iterable<java.nio.file.Path>) files.filter(x -> x.toString().endsWith(".java"))::iterator)
			{
				final String code = new String(Files.readAllBytes(f), StandardCharsets.UTF_8)
					.replaceAll("(?s)/\\*.*?\\*/", "").replaceAll("//[^\\n]*", "");
				if (code.matches("(?s).*\\.openConnection\\s*\\(.*") || code.contains("HttpURLConnection")
					|| code.contains("URLConnection"))
				{
					found.add(f.getFileName().toString());
				}
			}
		}
		Assert.assertEquals("connections that bypass OkHttp", java.util.List.of(), found);
	}

	/** Run from a classes directory, as the tests are: the stamp is there,
	 *  and in UTC like the report's own times. */
	@Test
	public void aDevBuildSaysWhenItWasBuilt()
	{
		Assert.assertTrue(BuildInfo.label(), BuildInfo.label().startsWith(BuildInfo.VERSION + ", built "));
		Assert.assertTrue(BuildInfo.label(), BuildInfo.label().endsWith(" UTC"));
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * "i just bought 25k and flipped them, and its still reccomending me that i
 * buy this flip, it should know im on cool down for 4h". The Exchange's buy
 * limit runs on a four-hour clock from the first purchase; what was bought
 * in it is taken off what the plugin will suggest buying.
 */
public class BuyLimitWindowTest
{
	private static final long H = 60L * 60 * 1000;
	private static final long T0 = 1_790_000_000_000L;
	private static final int BLOOD = 565;

	@Test
	public void theClockStartsAtTheFirstBuyAndRunsFourHours()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		t.noteBuyForLimit(BLOOD, 10_000, T0);
		t.noteBuyForLimit(BLOOD, 15_000, T0 + H);
		Assert.assertEquals(25_000, t.boughtTowardLimit(BLOOD, T0 + H));
		Assert.assertEquals("not from the later buy", T0 + 4 * H, t.limitResetsAt(BLOOD, T0 + 2 * H));
		Assert.assertEquals(25_000, t.boughtTowardLimit(BLOOD, T0 + 4 * H - 1));
		Assert.assertEquals("whole again", 0, t.boughtTowardLimit(BLOOD, T0 + 4 * H));
		Assert.assertEquals(0, t.limitResetsAt(BLOOD, T0 + 4 * H));

		t.noteBuyForLimit(BLOOD, 3_000, T0 + 5 * H);
		Assert.assertEquals("a new window from the next buy", 3_000, t.boughtTowardLimit(BLOOD, T0 + 5 * H));
		Assert.assertEquals(T0 + 9 * H, t.limitResetsAt(BLOOD, T0 + 5 * H));
		Assert.assertEquals("another item has its own", 0, t.boughtTowardLimit(1601, T0 + 5 * H));
	}

	@Test
	public void aBuyThroughAnOfferCountsAndASellDoesNot()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		final long now = System.currentTimeMillis();
		t.onOffer(now, 0, BLOOD, "Blood rune", true, 0, 0L, false);
		t.onOffer(now + 1_000, 0, BLOOD, "Blood rune", true, 25_000, 7_300_000L, false);
		Assert.assertEquals(25_000, t.boughtTowardLimit(BLOOD, now + 2_000));
		t.onOffer(now + 3_000, 1, BLOOD, "Blood rune", false, 0, 0L, false);
		t.onOffer(now + 4_000, 1, BLOOD, "Blood rune", false, 25_000, 7_600_000L, false);
		Assert.assertEquals("selling them back does not give the limit back", 25_000,
			t.boughtTowardLimit(BLOOD, now + 5_000));
	}

	/** Per character, as the game's limit is; and through a restart, as the
	 *  game's clock does not stop for one. */
	@Test
	public void eachCharacterHasItsOwnAndARestartKeepsIt()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		t.noteBuyForLimit(BLOOD, 25_000, T0);
		t.setAccountHash(77L);
		Assert.assertEquals("another character's limit is untouched", 0, t.boughtTowardLimit(BLOOD, T0 + H));
		t.setAccountHash(42L);

		final FlipTracker after = new FlipTracker();
		after.restore(new com.google.gson.Gson().fromJson(new com.google.gson.Gson().toJson(t.snapshot()),
			FlipTracker.State.class));
		after.setAccountHash(42L);
		Assert.assertEquals(25_000, after.boughtTowardLimit(BLOOD, T0 + H));
		Assert.assertEquals(T0 + 4 * H, after.limitResetsAt(BLOOD, T0 + H));

		final FlipTracker older = new FlipTracker();
		older.restore(new FlipTracker.State());
		older.setAccountHash(42L);
		Assert.assertEquals("a save from before this knows of no buys", 0, older.boughtTowardLimit(BLOOD, T0 + H));
	}

	/** Updating straight after buying the limit: a save from before limits
	 *  were tracked is seeded from its flips and open lots of the last four
	 *  hours, so the flip just made is not offered again. */
	@Test
	public void anOlderSaveIsSeededFromRecentBuys()
	{
		final long now = System.currentTimeMillis();
		final FlipTracker.State old = new FlipTracker.State();
		old.accountHash = 42L;
		old.flips = new ArrayList<>();
		old.flips.add(new Flip(1L, now - H, now - H / 2, BLOOD, "Blood rune", 25_000, 7_300_000L, 7_600_000L, 76_000L));
		old.flips.add(new Flip(2L, now - 5 * H, now - 4 * H, 1601, "Diamond", 100, 200_000L, 210_000L, 2_100L));
		old.openBuys = new HashMap<>();
		old.openBuys.put(1601, List.<long[]>of(new long[]{40, 80_000L, now - 2 * H}));
		final FlipTracker t = new FlipTracker();
		t.restore(old);
		Assert.assertEquals(25_000, t.boughtTowardLimit(BLOOD, now));
		Assert.assertEquals("from the open lot only; the old flip is past four hours", 40,
			t.boughtTowardLimit(1601, now));
		Assert.assertEquals(now - H + 4 * H, t.limitResetsAt(BLOOD, now));
	}

	/** Collected and re-placed while the client was not watching (mobile, or
	 *  shut): the new buy in the slot is a different offer, baselined rather
	 *  than booked — but the game counted it, so the limit does. */
	@Test
	public void aBuyThatReplacedTheSlotUnseenStillCounts()
	{
		final long now = System.currentTimeMillis();
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		t.onOffer(now, 0, 1601, "Diamond", false, 0, 0L, 3_000L, 100, false);
		t.markSlotsUnwatched();
		t.onOffer(now + H / 2, 0, BLOOD, "Blood rune", true, 25_000, 7_500_000L, 300L, 25_000, false);
		Assert.assertEquals(25_000, t.boughtTowardLimit(BLOOD, now + H / 2));
		t.onOffer(now + H, 0, BLOOD, "Blood rune", true, 25_000, 7_500_000L, 300L, 25_000, false);
		Assert.assertEquals("and only once", 25_000, t.boughtTowardLimit(BLOOD, now + H));
	}

	/** The same mismatch seen live is a misread, not a purchase: a slot
	 *  cannot change offers without an empty in between. */
	@Test
	public void aMismatchSeenLiveIsNotABuy()
	{
		final long now = System.currentTimeMillis();
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		t.onOffer(now, 0, 1601, "Diamond", false, 0, 0L, 3_000L, 100, false);
		t.onOffer(now + 1_000, 0, BLOOD, "Blood rune", true, 25_000, 7_500_000L, 300L, 25_000, false);
		Assert.assertEquals(0, t.boughtTowardLimit(BLOOD, now + 2_000));
	}

	private static List<Advisor.Suggestion> adjusts(int limitUsed)
	{
		final Advisor.Quote q = new Advisor.Quote();
		q.high = 304;
		q.low = 292;
		q.highTime = 1_000_000L;
		q.lowTime = 1_000_000L;
		final Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(BLOOD, q);
		final Advisor.ItemMeta m = new Advisor.ItemMeta();
		m.id = BLOOD;
		m.name = "Blood rune";
		m.limit = 25_000;
		m.limitUsed = limitUsed;
		m.dailyVolume = 50_000_000L;
		final Map<Integer, Advisor.ItemMeta> meta = new HashMap<>();
		meta.put(BLOOD, m);
		final Advisor.OfferView o = new Advisor.OfferView();
		o.slot = 0;
		o.itemId = BLOOD;
		o.itemName = "Blood rune";
		o.buy = true;
		o.price = 280;
		o.totalQuantity = 25_000;
		o.quantitySold = 20_000;
		o.active = true;
		final List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(o);
		final List<Advisor.Suggestion> out = new ArrayList<>();
		for (Advisor.Suggestion s : Advisor.advise(1_000_000L, quotes, meta, 100_000_000L, new HashMap<>(),
			offers, new HashSet<>(), new HashSet<>(), 0, 0.01, 4, new HashMap<>(), new HashMap<>(), 0))
		{
			if (s.type == Advisor.Suggestion.Type.ADJUST_BUY)
			{
				out.add(s);
			}
		}
		return out;
	}

	/** A bid stalled because the limit is used up fills no more at any
	 *  price: no "raise it". With some left, the raise is for what can fill. */
	@Test
	public void noRaiseForABidTheLimitHasStopped()
	{
		Assert.assertEquals("the market moved past the bid", 5_000, adjusts(20_000).get(0).quantity);
		Assert.assertEquals("only what is left can fill", 3_000, adjusts(22_000).get(0).quantity);
		Assert.assertTrue("used up: nothing to raise", adjusts(25_000).isEmpty());
	}

	private static Object[] watchlistCard(long potentialProfit, int bidQty) throws Exception
	{
		final AdvisorPanel.Actions actions = (AdvisorPanel.Actions) java.lang.reflect.Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(p, m, a) ->
			{
				final Class<?> t = m.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				return t.isPrimitive() ? (t == long.class ? (Object) 0L : (Object) 0) : null;
			});
		final AdvisorPanel panel = new AdvisorPanel(null, actions);
		final FavoritesPanel.Row r = new FavoritesPanel.Row();
		r.id = BLOOD;
		r.name = "Blood rune";
		r.targetBuy = 292;
		r.targetSell = 304;
		r.limit = 25_000;
		r.limitUsed = 25_000;
		r.limitResetsAt = System.currentTimeMillis() + 2 * H + 15 * 60_000;
		r.potentialProfit = potentialProfit;
		r.bidQty = bidQty;
		r.bidPrice = 290;
		final java.lang.reflect.Method recFor = AdvisorPanel.class.getDeclaredMethod("recFor", FavoritesPanel.Row.class);
		recFor.setAccessible(true);
		final AdvisorPanel.Rec rec = (AdvisorPanel.Rec) recFor.invoke(panel, r);
		final java.lang.reflect.Method cardFor = AdvisorPanel.class.getDeclaredMethod("cardFor", AdvisorPanel.Rec.class);
		cardFor.setAccessible(true);
		final Object card = cardFor.invoke(panel, rec);
		final java.lang.reflect.Field foot = card.getClass().getDeclaredField("footnote");
		final java.lang.reflect.Field warn = card.getClass().getDeclaredField("footnoteWarn");
		foot.setAccessible(true);
		warn.setAccessible(true);
		return new Object[]{rec, foot.get(card), warn.get(card)};
	}

	/** Clicked on the watchlist with the limit used up, the card buys
	 *  nothing and says when it can — whatever the margin, and over a bid. */
	@Test
	public void theWatchlistCardSaysWhenTheLimitIsBack() throws Exception
	{
		for (Object[] c : new Object[][]{watchlistCard(150_000, 0), watchlistCard(-5_000, 0), watchlistCard(150_000, 4_000)})
		{
			final AdvisorPanel.Rec rec = (AdvisorPanel.Rec) c[0];
			Assert.assertEquals("nothing to buy", 0, rec.quantity);
			Assert.assertEquals(0, rec.profit);
			Assert.assertTrue(String.valueOf(c[1]), String.valueOf(c[1]).matches("4h limit used, back in 2h 1[45]m"));
			Assert.assertEquals("warned", true, c[2]);
		}
	}

	private static List<Advisor.Suggestion> buys(int limitUsed)
	{
		final Advisor.Quote q = new Advisor.Quote();
		q.high = 304;
		q.low = 292;
		q.highTime = 1_000_000L;
		q.lowTime = 1_000_000L;
		final Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(BLOOD, q);
		final Advisor.ItemMeta m = new Advisor.ItemMeta();
		m.id = BLOOD;
		m.name = "Blood rune";
		m.limit = 25_000;
		m.limitUsed = limitUsed;
		m.dailyVolume = 50_000_000L;
		final Map<Integer, Advisor.ItemMeta> meta = new HashMap<>();
		meta.put(BLOOD, m);
		final List<Advisor.Suggestion> out = new ArrayList<>();
		for (Advisor.Suggestion s : Advisor.advise(1_000_000L, quotes, meta, 100_000_000L, new HashMap<>(),
			new ArrayList<>(), new HashSet<>(), new HashSet<>(), 0, 0.01, 4, new HashMap<>(), new HashMap<>(), 0))
		{
			if (s.type == Advisor.Suggestion.Type.BUY)
			{
				out.add(s);
			}
		}
		return out;
	}

	@Test
	public void theAdvisorBuysWhatIsLeftAndNothingOnceItIsGone()
	{
		Assert.assertEquals("the whole limit, fresh", 25_000, buys(0).get(0).quantity);
		Assert.assertEquals("what is left", 15_000, buys(10_000).get(0).quantity);
		Assert.assertTrue("used up: no buy at all", buys(25_000).isEmpty());
	}

	@Test
	public void untilReadsLikeAClock()
	{
		Assert.assertEquals("2h 14m", FlipTracker.untilText(2 * H + 14 * 60_000));
		Assert.assertEquals("38m", FlipTracker.untilText(38 * 60_000));
		Assert.assertEquals("under a minute", FlipTracker.untilText(20_000));
		Assert.assertEquals("under a minute", FlipTracker.untilText(-5));
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class CapitalPlannerTest
{
	private static CapitalPlanner.Candidate candidate(int id, String name, long unitBuy, long unitEdge,
		int limit, long dailyVolume)
	{
		CapitalPlanner.Candidate c = new CapitalPlanner.Candidate();
		c.id = id;
		c.name = name;
		c.unitBuy = unitBuy;
		c.unitEdge = unitEdge;
		c.limit = limit;
		c.dailyVolume = dailyVolume;
		return c;
	}

	private static long totalSpend(CapitalPlanner.Plan p)
	{
		long total = 0;
		for (CapitalPlanner.Position pos : p.positions)
		{
			total += pos.spend;
		}
		return total;
	}

	/** The bug this whole class exists to fix: Advisor.buildBuys sizes every
	 *  BUY against the full cash pile independently, so its suggestions can
	 *  collectively cost far more than you have. A plan must always be
	 *  affordable. */
	@Test
	public void neverPlansMoreThanYouCanAfford()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		for (int i = 1; i <= 30; i++)
		{
			// Each of these could individually absorb the entire 100m.
			pool.add(candidate(i, "Item " + i, 1_000_000, 50_000, 500, 5_000_000));
		}
		final long cash = 100_000_000L;
		CapitalPlanner.Plan plan = CapitalPlanner.plan(cash, 8, pool);

		Assert.assertTrue("plan must be affordable", totalSpend(plan) <= cash);
		Assert.assertEquals(totalSpend(plan), plan.cashDeployed);
		Assert.assertEquals(cash - plan.cashDeployed, plan.cashIdle);
		Assert.assertTrue(plan.cashIdle >= 0);
	}

	@Test
	public void neverUsesMoreSlotsThanAreFree()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		for (int i = 1; i <= 30; i++)
		{
			pool.add(candidate(i, "Item " + i, 10_000, 500, 100, 1_000_000));
		}
		CapitalPlanner.Plan plan = CapitalPlanner.plan(100_000_000L, 3, pool);
		Assert.assertTrue(plan.positions.size() <= 3);
		Assert.assertEquals(plan.positions.size(), plan.slotsUsed);
	}

	/**
	 * The slot-bound case, and the reason plain ROI-density greedy isn't
	 * good enough. With ONE slot and 100m: a 10%-edge item that can only
	 * absorb 100k earns 10k, while a 5%-edge item that can absorb the whole
	 * bank earns 5m. Density ranking prefers the first; the repair pass has
	 * to fix that.
	 */
	@Test
	public void prefersAbsorptionOverRoiWhenSlotsAreScarce()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		// 10% edge, but its limit caps it at 100 units x 1,000 gp = 100k.
		pool.add(candidate(1, "Tiny high ROI", 1_000, 100, 100, 10_000_000));
		// 5% edge and able to soak up the full 100m (100 x 1,000,000).
		pool.add(candidate(2, "Big absorber", 1_000_000, 50_000, 100, 10_000_000));

		CapitalPlanner.Plan plan = CapitalPlanner.plan(100_000_000L, 1, pool);

		Assert.assertEquals(1, plan.positions.size());
		Assert.assertEquals("should spend its only slot on the item that can actually take the cash",
			2, plan.positions.get(0).id);
		Assert.assertTrue(plan.expectedProfit > 1_000_000L);
	}

	/** With enough slots it should take BOTH — the high-ROI one first (it's
	 *  cheap and strictly better per gp), then the absorber for the rest. */
	@Test
	public void takesHighRoiAndAbsorberWhenSlotsAllow()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		pool.add(candidate(1, "Tiny high ROI", 1_000, 100, 100, 10_000_000));
		pool.add(candidate(2, "Big absorber", 1_000_000, 50_000, 100, 10_000_000));

		CapitalPlanner.Plan plan = CapitalPlanner.plan(100_000_000L, 2, pool);

		Assert.assertEquals(2, plan.positions.size());
		Assert.assertTrue(totalSpend(plan) <= 100_000_000L);
		// 10k from the small one + ~4.95m from the absorber on what's left.
		Assert.assertTrue(plan.expectedProfit > 4_000_000L);
	}

	/** Cash-bound regime: gp runs out long before slots do, so the plan
	 *  should be the density optimum and spend essentially everything. */
	@Test
	public void deploysNearlyAllCashWhenLimitsAllow()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		pool.add(candidate(1, "Deep item", 1_000, 100, 1_000_000, 100_000_000L));

		final long cash = 1_000_000L;
		CapitalPlanner.Plan plan = CapitalPlanner.plan(cash, 8, pool);

		Assert.assertEquals(1, plan.positions.size());
		Assert.assertEquals(1000, plan.positions.get(0).quantity); // 1m / 1,000gp
		Assert.assertEquals(cash, plan.cashDeployed);
		Assert.assertEquals(CapitalPlanner.IdleReason.NONE, plan.idleReason);
		Assert.assertEquals(CapitalPlanner.Bound.CASH, plan.positions.get(0).boundBy);
	}

	/** A big bank against small buy limits genuinely cannot be deployed —
	 *  say so rather than implying it's all invested. */
	@Test
	public void reportsLimitsAsTheReasonCashSitsIdle()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		for (int i = 1; i <= 10; i++)
		{
			// Each caps out at 8 units x 100k = 800k.
			pool.add(candidate(i, "Limited " + i, 100_000, 5_000, 8, 1_000_000));
		}
		CapitalPlanner.Plan plan = CapitalPlanner.plan(100_000_000L, 3, pool);

		Assert.assertEquals(CapitalPlanner.IdleReason.LIMITS_CAP_DEPLOYMENT, plan.idleReason);
		Assert.assertTrue(plan.cashIdle > 90_000_000L);
		Assert.assertEquals(CapitalPlanner.Bound.GE_LIMIT, plan.positions.get(0).boundBy);
	}

	@Test
	public void noFreeSlotsIsReportedNotSilentlyEmpty()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		pool.add(candidate(1, "Anything", 1_000, 100, 100, 1_000_000));

		CapitalPlanner.Plan plan = CapitalPlanner.plan(100_000_000L, 0, pool);

		Assert.assertTrue(plan.positions.isEmpty());
		Assert.assertEquals(CapitalPlanner.IdleReason.NO_FREE_SLOTS, plan.idleReason);
		Assert.assertEquals(100_000_000L, plan.cashIdle);
	}

	/** An unknown GE limit must not read as "unlimited" — otherwise one
	 *  unverified item swallows the whole bank. */
	@Test
	public void unknownBuyLimitIsCappedNotTreatedAsUnlimited()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		pool.add(candidate(1, "Unknown limit", 1_000, 100, 0, 100_000_000L));

		final long cash = 100_000_000L;
		CapitalPlanner.Plan plan = CapitalPlanner.plan(cash, 1, pool);

		Assert.assertEquals(1, plan.positions.size());
		Assert.assertTrue("must not deploy the whole bank into an item with no confirmed limit",
			plan.positions.get(0).spend < cash / 2);
		Assert.assertEquals(CapitalPlanner.Bound.LIMIT_UNKNOWN, plan.positions.get(0).boundBy);
	}

	@Test
	public void ignoresItemsWithNoEdgeOrUnaffordableUnitPrice()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		pool.add(candidate(1, "No edge", 1_000, 0, 100, 1_000_000));
		pool.add(candidate(2, "Negative edge", 1_000, -50, 100, 1_000_000));
		pool.add(candidate(3, "Too expensive", 50_000_000, 1_000_000, 100, 1_000_000));

		CapitalPlanner.Plan plan = CapitalPlanner.plan(1_000_000L, 3, pool);

		Assert.assertTrue(plan.positions.isEmpty());
		Assert.assertEquals(CapitalPlanner.IdleReason.NO_VIABLE_ITEMS, plan.idleReason);
	}

	@Test
	public void emptyCandidateListIsHandled()
	{
		CapitalPlanner.Plan plan = CapitalPlanner.plan(100_000_000L, 8, new ArrayList<>());
		Assert.assertTrue(plan.positions.isEmpty());
		Assert.assertEquals(CapitalPlanner.IdleReason.NO_VIABLE_ITEMS, plan.idleReason);

		CapitalPlanner.Plan nullPlan = CapitalPlanner.plan(100_000_000L, 8, null);
		Assert.assertTrue(nullPlan.positions.isEmpty());
	}

	/** Members get 8 slots against f2p's 3, so the same bank should deploy
	 *  at least as much and earn at least as much with more of them. */
	@Test
	public void moreSlotsNeverEarnLess()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		for (int i = 1; i <= 20; i++)
		{
			pool.add(candidate(i, "Item " + i, 100_000 + i * 1000, 4_000, 60, 2_000_000));
		}
		final long cash = 100_000_000L;
		CapitalPlanner.Plan f2p = CapitalPlanner.plan(cash, 3, pool);
		CapitalPlanner.Plan members = CapitalPlanner.plan(cash, 8, pool);

		Assert.assertTrue(members.expectedProfit >= f2p.expectedProfit);
		Assert.assertTrue(members.cashDeployed >= f2p.cashDeployed);
		Assert.assertTrue(totalSpend(members) <= cash);
	}

	@Test
	public void summaryFieldsAreSelfConsistent()
	{
		List<CapitalPlanner.Candidate> pool = new ArrayList<>();
		for (int i = 1; i <= 12; i++)
		{
			pool.add(candidate(i, "Item " + i, 250_000, 12_000, 40, 3_000_000));
		}
		CapitalPlanner.Plan plan = CapitalPlanner.plan(50_000_000L, 8, pool);

		long spend = 0;
		long profit = 0;
		for (CapitalPlanner.Position p : plan.positions)
		{
			Assert.assertEquals(p.quantity * p.unitBuy, p.spend);
			Assert.assertEquals(p.quantity * p.unitEdge, p.expectedProfit);
			spend += p.spend;
			profit += p.expectedProfit;
		}
		Assert.assertEquals(spend, plan.cashDeployed);
		Assert.assertEquals(profit, plan.expectedProfit);
		Assert.assertEquals(50_000_000L, plan.cashDeployed + plan.cashIdle);
		Assert.assertTrue(plan.deployedPct() >= 0 && plan.deployedPct() <= 100.0);
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * "after i have a rune dart trade in, the rune dart reccomendation trade
 * idea should automatically go to the next trade idea" — paused or not.
 */
public class CardAdvanceTest
{
	private static final int RUNE_DART = 811;
	private static final int STEAM_RUNE = 4694;
	private static final int BLOOD_RUNE = 565;

	/** What the card announced last: the item on screen. */
	private final List<Integer> shown = new ArrayList<>();

	private AdvisorPanel panel()
	{
		final AdvisorPanel.Actions actions = (AdvisorPanel.Actions) Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(proxy, method, args) ->
			{
				if ("onRecommendationShown".equals(method.getName()))
				{
					shown.add((Integer) args[0]);
				}
				final Class<?> t = method.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				if (t == int.class || t == long.class || t == double.class || t == float.class)
				{
					return 0;
				}
				return null;
			});
		return new AdvisorPanel(null, actions);
	}

	private static AdvisorPanel.Rec buy(int id, String name)
	{
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.itemId = id;
		r.name = name;
		r.sell = false;
		r.quantity = 1_000;
		r.unitPrice = 100;
		r.profit = 50_000;
		return r;
	}

	private static List<AdvisorPanel.Rec> list(AdvisorPanel.Rec... recs)
	{
		return new ArrayList<>(java.util.Arrays.asList(recs));
	}

	private Integer onScreen()
	{
		return shown.isEmpty() ? null : shown.get(shown.size() - 1);
	}

	private static void setIndex(AdvisorPanel p, int i) throws Exception
	{
		final Field f = AdvisorPanel.class.getDeclaredField("recIndex");
		f.setAccessible(true);
		f.setInt(p, i);
	}

	/** Paused on Rune dart, the rune darts go in: the pause lifts, and the
	 *  card moves to the next idea. */
	@Test
	public void placingThePausedCardsOfferMovesOn()
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(list(buy(RUNE_DART, "Rune dart"), buy(STEAM_RUNE, "Steam rune"), buy(BLOOD_RUNE, "Blood rune")));
		Assert.assertEquals(Integer.valueOf(RUNE_DART), onScreen());
		p.pauseButton().doClick();
		p.setRecommendations(list(buy(BLOOD_RUNE, "Blood rune"), buy(RUNE_DART, "Rune dart")));
		Assert.assertEquals("held while paused", Integer.valueOf(RUNE_DART), onScreen());

		p.offerPlaced(STEAM_RUNE, true);
		Assert.assertEquals("another item's offer leaves the hold alone", Integer.valueOf(RUNE_DART), onScreen());
		p.offerPlaced(RUNE_DART, false);
		Assert.assertEquals("a SELL of it is not the card's buy", Integer.valueOf(RUNE_DART), onScreen());

		p.offerPlaced(RUNE_DART, true);
		Assert.assertNotEquals("moved off the placed idea", Integer.valueOf(RUNE_DART), onScreen());
		Assert.assertTrue("and no longer paused", p.pauseButton().getToolTipText().contains("Pause the suggestions"));
	}

	/** Not paused: the refresh after the offer drops the idea, and the card
	 *  goes to the one after it rather than back to the first. */
	@Test
	public void anIdeaThatLeavesTheListGivesWayToTheNextOne() throws Exception
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(list(buy(BLOOD_RUNE, "Blood rune"), buy(RUNE_DART, "Rune dart"), buy(STEAM_RUNE, "Steam rune")));
		setIndex(p, 1);
		p.setRecommendations(list(buy(BLOOD_RUNE, "Blood rune"), buy(STEAM_RUNE, "Steam rune")));
		Assert.assertEquals(Integer.valueOf(STEAM_RUNE), onScreen());
		Assert.assertEquals("the same idea stays put",
			1, AdvisorPanel.placeOf(list(buy(1, "a"), buy(2, "b")), 1, list(buy(3, "c"), buy(2, "b"))));
		Assert.assertEquals("nothing left from there on: the first",
			0, AdvisorPanel.placeOf(list(buy(1, "a"), buy(2, "b")), 1, list(buy(3, "c"))));
	}

	/** Ending a pause by hand shows the newest list, not the one from
	 *  before it. */
	@Test
	public void unpausingShowsTheNewestList()
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(list(buy(RUNE_DART, "Rune dart")));
		p.pauseButton().doClick();
		p.setRecommendations(list(buy(BLOOD_RUNE, "Blood rune")));
		Assert.assertEquals(Integer.valueOf(RUNE_DART), onScreen());
		p.pauseButton().doClick();
		Assert.assertEquals(Integer.valueOf(BLOOD_RUNE), onScreen());
	}
}

package com.pocketge.tracker;

import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.swing.JButton;
import org.junit.Assert;
import org.junit.Test;

/**
 * "why it show 2/20 but i cant click to whatever 1/20 is" — the card had
 * moved on by itself, so nothing had been paged past, and Back stayed grey.
 */
public class CardBackTest
{
	private static final int A = 811;
	private static final int B = 4694;
	private static final int C = 565;
	private static final int X = 1601;

	/** What the card announced last: the item on screen. */
	private final List<Integer> shown = new ArrayList<>();

	private AdvisorPanel panel()
	{
		final AdvisorPanel.Actions actions = (AdvisorPanel.Actions) Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(proxy, method, args) ->
			{
				if ("onRecommendationShown".equals(method.getName()))
				{
					shown.add((Integer) args[0]);
				}
				final Class<?> t = method.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				if (t == int.class || t == long.class || t == double.class || t == float.class)
				{
					return 0;
				}
				return null;
			});
		return new AdvisorPanel(null, actions);
	}

	private static AdvisorPanel.Rec buy(int id)
	{
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.itemId = id;
		r.name = "Item " + id;
		r.sell = false;
		r.quantity = 1_000;
		r.unitPrice = 100;
		r.profit = 50_000;
		return r;
	}

	private static List<AdvisorPanel.Rec> list(int... ids)
	{
		final List<AdvisorPanel.Rec> out = new ArrayList<>();
		Arrays.stream(ids).forEach(id -> out.add(buy(id)));
		return out;
	}

	private Integer onScreen()
	{
		return shown.isEmpty() ? null : shown.get(shown.size() - 1);
	}

	/** The pager's Back square, as the card is drawn now. */
	private static JButton back(Container root)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof JButton)
			{
				final String tip = ((JButton) c).getToolTipText();
				if (tip != null && (tip.contains("previous suggestion") || tip.contains("Nothing to go back to")))
				{
					return (JButton) c;
				}
			}
			if (c instanceof Container)
			{
				final JButton found = back((Container) c);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static JButton next(Container root)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof JButton)
			{
				final String tip = ((JButton) c).getToolTipText();
				if (tip != null && tip.contains("Next suggestion"))
				{
					return (JButton) c;
				}
			}
			if (c instanceof Container)
			{
				final JButton found = next((Container) c);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	/** The card stays on its idea as a new one lands ahead of it: 2 of 4,
	 *  nothing paged past, and Back goes to the 1. */
	@Test
	public void backGoesToTheCardBeforeEvenWithNothingPagedPast()
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(list(A, B, C));
		Assert.assertEquals(Integer.valueOf(A), onScreen());
		Assert.assertFalse("1 of 3: nothing before it", back(p).isEnabled());

		p.setRecommendations(list(X, A, B, C));
		Assert.assertEquals("still on its idea, now 2 of 4", Integer.valueOf(A), onScreen());
		final JButton back = back(p);
		Assert.assertTrue("there is a 1 to go back to", back.isEnabled());
		back.doClick();
		Assert.assertEquals(Integer.valueOf(X), onScreen());
		Assert.assertFalse("and at 1, nothing before", back(p).isEnabled());
	}

	/** A card you paged past is still where Back goes first, wherever the
	 *  re-ranking has put it. */
	@Test
	public void aCardPagedPastIsStillWhereBackGoes()
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(list(A, B, C));
		next(p).doClick();
		Assert.assertEquals(Integer.valueOf(B), onScreen());
		p.setRecommendations(list(C, B, A));
		back(p).doClick();
		Assert.assertEquals("the one paged past, not whatever is first now", Integer.valueOf(A), onScreen());
	}
}

