package com.pocketge.tracker;

import java.awt.event.KeyEvent;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.swing.JPanel;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * The plugin writes to the chatbox input only when the player presses E.
 *
 * RuneLite rejects plugins that "programmatically insert text into the
 * user's chatbox input for any reason ... The only way text can get into the
 * chatbox is if the user is pressing keys themselves." 0.7.0 filled the GE
 * price box the moment it opened and typed prices, quantities and item names
 * on clicks; the hub description said "only from a click", which was not
 * true either. These hold the line in both directions: one write, behind the
 * key, and the key does nothing unless the chip naming it is on screen.
 */
public class ChatboxInputTest
{
	private static final String SRC = "src/main/java/com/pocketge/tracker/";

	private static String code(String cls) throws Exception
	{
		return Files.readString(Path.of(SRC + cls + ".java"))
			.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
	}

	private static final Pattern WRITE = Pattern.compile("setVarcStrValue\\(\\s*(?:[\\w.]*\\.)?VarClientID\\.MESLAYERINPUT");

	/** Exactly one write to the chatbox input in the whole plugin, and it is
	 *  the one the key listener calls. Reading it (is the search still
	 *  empty?) is not a write. */
	@Test
	public void oneWriteAndItIsTheKeys() throws Exception
	{
		int writes = 0;
		int setters = 0;
		for (String cls : new String[]{"PocketGeTrackerPlugin", "GeOfferPriceOverlay", "AdvisorPanel", "MainPanel"})
		{
			final Matcher m = WRITE.matcher(code(cls));
			while (m.find())
			{
				writes++;
			}
			final Matcher any = Pattern.compile("setVarcStrValue\\(").matcher(code(cls));
			while (any.find())
			{
				setters++;
			}
		}
		Assert.assertEquals("one write to MESLAYERINPUT", 1, writes);
		Assert.assertEquals("and no other chatbox string written", 1, setters);
		final String plugin = code("PocketGeTrackerPlugin");
		final int fill = plugin.indexOf("private void fillGePrompt(");
		final Matcher w = WRITE.matcher(plugin);
		Assert.assertTrue(w.find());
		final int write = w.start();
		final int next = plugin.indexOf("\n\tprivate ", fill + 1);
		Assert.assertTrue("the write is inside fillGePrompt", fill > 0 && write > fill && write < next);
		final String listener = plugin.substring(plugin.indexOf("fillKeyListener = "), plugin.indexOf("fillKeyListener = ") + 3000);
		Assert.assertTrue("and fillGePrompt is called from the key listener", listener.contains("fillGePrompt("));
	}

	/** The search pick is the game's: the plugin never runs a script or
	 *  types anything there. It fills the search's own result row, which
	 *  the game picks on the player's click or Enter, and the fill key is
	 *  handed on to the game as Enter. */
	@Test
	public void theSearchPickIsTheGamesOwn() throws Exception
	{
		final String plugin = code("PocketGeTrackerPlugin");
		Assert.assertFalse("no select script run by the plugin", plugin.contains("runScript(MESLAYER_MODE14_SELECT"));
		final int fill = plugin.indexOf("private void fillSearchRow(");
		final int next = plugin.indexOf("\n\tprivate ", fill + 1);
		final String body = plugin.substring(fill, next);
		Assert.assertTrue(body.contains("setOnOpListener(MESLAYER_MODE14_SELECT"));
		Assert.assertTrue(body.contains("setOnKeyListener(MESLAYER_MODE14_SELECT"));
		Assert.assertFalse("types nothing", body.contains("setVarcStrValue"));
		final String listener = plugin.substring(plugin.indexOf("fillKeyListener = "), plugin.indexOf("fillKeyListener = ") + 6000);
		Assert.assertTrue("the key goes on as Enter", listener.contains("e.setKeyCode(java.awt.event.KeyEvent.VK_ENTER)"));
	}

	/** With the row filled and nothing typed, E reaches the game as Enter
	 *  and its 'e' never lands; a letter typed first makes it a letter. */
	@Test
	public void eGoesOnAsEnterInAnUntouchedSearch() throws Exception
	{
		final Field c = PocketGeTrackerPlugin.class.getDeclaredField("client");
		c.setAccessible(true);
		c.set(plugin, chatbox("What would you like to buy?", ""));
		final Field row = PocketGeTrackerPlugin.class.getDeclaredField("searchRowItem");
		row.setAccessible(true);
		row.set(plugin, 1737);
		final Field a = GeOfferPriceOverlay.class.getDeclaredField("armed");
		a.setAccessible(true);
		final java.lang.reflect.Method item = GeOfferPriceOverlay.Armed.class.getDeclaredMethod("item", int.class);
		item.setAccessible(true);
		a.set(overlay, item.invoke(null, 1737));

		final KeyEvent e = real(KeyEvent.KEY_PRESSED, KeyEvent.VK_E, 'e');
		keys.keyPressed(e);
		Assert.assertFalse("handed on, not taken", e.isConsumed());
		Assert.assertEquals(KeyEvent.VK_ENTER, e.getKeyCode());
		final KeyEvent t = typed('e');
		keys.keyTyped(t);
		Assert.assertTrue("its 'e' never lands", t.isConsumed());
		final KeyEvent r = real(KeyEvent.KEY_RELEASED, KeyEvent.VK_E, 'e');
		keys.keyReleased(r);
		Assert.assertEquals("and lets go as Enter", KeyEvent.VK_ENTER, r.getKeyCode());
		Assert.assertEquals("the row is used up", 0, row.get(plugin));
		final KeyEvent next = real(KeyEvent.KEY_PRESSED, KeyEvent.VK_A, 'a');
		keys.keyPressed(next);
		Assert.assertTrue("typing straight on after a pick does not reach the chat", next.isConsumed());

		/* A letter first: E is a letter of the search. */
		final Field until = keys.getClass().getDeclaredField("afterPickUntil");
		until.setAccessible(true);
		until.set(keys, 0L);
		row.set(plugin, 1737);
		final KeyEvent b = real(KeyEvent.KEY_PRESSED, KeyEvent.VK_B, 'b');
		keys.keyPressed(b);
		Assert.assertFalse(b.isConsumed());
		Assert.assertEquals("typing gives the row back to the search", 0, row.get(plugin));
		final KeyEvent e2 = real(KeyEvent.KEY_PRESSED, KeyEvent.VK_E, 'e');
		keys.keyPressed(e2);
		Assert.assertEquals(KeyEvent.VK_E, e2.getKeyCode());
		Assert.assertFalse(e2.isConsumed());
	}

	/** Armed over a price box, the real E is taken, typed char and all. */
	@Test
	public void anArmedEIsTaken() throws Exception
	{
		final Field c = PocketGeTrackerPlugin.class.getDeclaredField("clientThread");
		c.setAccessible(true);
		c.set(plugin, null); // fillGePrompt's hop to the client thread is not under test
		arm(1_120);
		final KeyEvent e = real(KeyEvent.KEY_PRESSED, KeyEvent.VK_E, 'e');
		try
		{
			keys.keyPressed(e);
		}
		catch (NullPointerException expected)
		{
			// no client thread here: the press got as far as filling
		}
		Assert.assertTrue(e.isConsumed());
		final KeyEvent t = typed('e');
		keys.keyTyped(t);
		Assert.assertTrue(t.isConsumed());
	}

	/** Enter, Escape and Backspace are the boxes' own: as the fill key they
	 *  count as no key. */
	@Test
	public void theBoxesOwnKeysAreRefused()
	{
		Assert.assertTrue(PocketGeTrackerPlugin.usedByThePrompts(new net.runelite.client.config.Keybind(KeyEvent.VK_ENTER, 0)));
		Assert.assertTrue(PocketGeTrackerPlugin.usedByThePrompts(new net.runelite.client.config.Keybind(KeyEvent.VK_ESCAPE, 0)));
		Assert.assertTrue(PocketGeTrackerPlugin.usedByThePrompts(new net.runelite.client.config.Keybind(KeyEvent.VK_BACK_SPACE, 0)));
		Assert.assertFalse(PocketGeTrackerPlugin.usedByThePrompts(new net.runelite.client.config.Keybind(KeyEvent.VK_E, 0)));
		Assert.assertFalse("with a modifier it is not the box's",
			PocketGeTrackerPlugin.usedByThePrompts(new net.runelite.client.config.Keybind(KeyEvent.VK_ENTER, KeyEvent.CTRL_DOWN_MASK)));
	}

	/** The key is the setting's: another key works the same, and E is then
	 *  just E. */
	@Test
	public void theKeyIsTheSettings() throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField("fillKey");
		f.setAccessible(true);
		f.set(plugin, new net.runelite.client.config.Keybind(KeyEvent.VK_F, 0));
		arm(0);
		final KeyEvent e = press(KeyEvent.VK_E, 0);
		keys.keyPressed(e);
		Assert.assertFalse(e.isConsumed());
		final KeyEvent t = typed('e');
		keys.keyTyped(t);
		Assert.assertFalse(t.isConsumed());
		f.set(plugin, net.runelite.client.config.Keybind.NOT_SET);
		arm(1_120);
		final KeyEvent unset = press(KeyEvent.VK_E, 0);
		keys.keyPressed(unset);
		Assert.assertFalse("no key set: nothing is taken", unset.isConsumed());
		Assert.assertFalse(PocketGeTrackerPlugin.typedCharOf(net.runelite.client.config.Keybind.NOT_SET, typed('e')));
		Assert.assertTrue(PocketGeTrackerPlugin.typedCharOf(new net.runelite.client.config.Keybind(KeyEvent.VK_F, 0), typed('f')));
		Assert.assertFalse("a key with a modifier has no typed character of its own",
			PocketGeTrackerPlugin.typedCharOf(new net.runelite.client.config.Keybind(KeyEvent.VK_F, KeyEvent.CTRL_DOWN_MASK), typed('f')));
	}

	/** Nothing fills the price box when it opens. */
	@Test
	public void nothingHappensWhenThePromptOpens() throws Exception
	{
		Assert.assertFalse(code("PocketGeTrackerPlugin").contains("CHAT_PROMPT_INIT"));
	}

	// -- the key itself ----------------------------------------------------

	private PocketGeTrackerPlugin plugin;
	private GeOfferPriceOverlay overlay;
	private java.awt.event.KeyListener keys;

	@Before
	public void wire() throws Exception
	{
		plugin = new PocketGeTrackerPlugin();
		final Constructor<GeOfferPriceOverlay> ctor = GeOfferPriceOverlay.class
			.getDeclaredConstructor(net.runelite.api.Client.class, net.runelite.client.game.ItemManager.class);
		ctor.setAccessible(true);
		overlay = ctor.newInstance(null, null);
		final Field o = PocketGeTrackerPlugin.class.getDeclaredField("gePriceOverlay");
		o.setAccessible(true);
		o.set(plugin, overlay);
		final Field k = PocketGeTrackerPlugin.class.getDeclaredField("fillKeyListener");
		k.setAccessible(true);
		keys = (java.awt.event.KeyListener) k.get(plugin);
	}

	private void arm(long value) throws Exception
	{
		final Field a = GeOfferPriceOverlay.class.getDeclaredField("armed");
		a.setAccessible(true);
		a.set(overlay, value > 0 ? new GeOfferPriceOverlay.Armed(false, value) : null);
	}

	private static KeyEvent press(int code, int modifiers)
	{
		return new KeyEvent(new JPanel(), KeyEvent.KEY_PRESSED, 0L, modifiers, code, KeyEvent.CHAR_UNDEFINED);
	}

	/** A key event as AWT delivers it, with its extended key code set —
	 *  which RuneLite's Keybind matches on, and a synthetic event lacks. */
	private static KeyEvent real(int id, int code, char c) throws Exception
	{
		final KeyEvent e = new KeyEvent(new JPanel(), id, 0L, 0, code, c);
		final Field f = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
		f.setAccessible(true);
		final sun.misc.Unsafe unsafe = (sun.misc.Unsafe) f.get(null);
		unsafe.putLong(e, unsafe.objectFieldOffset(KeyEvent.class.getDeclaredField("extendedKeyCode")), code);
		return e;
	}

	private static KeyEvent typed(char c)
	{
		return new KeyEvent(new JPanel(), KeyEvent.KEY_TYPED, 0L, 0, KeyEvent.VK_UNDEFINED, c);
	}

	/** With no chip on screen, E is just E. */
	@Test
	public void anUnarmedEPassesThrough() throws Exception
	{
		arm(0);
		final KeyEvent e = press(KeyEvent.VK_E, 0);
		keys.keyPressed(e);
		Assert.assertFalse(e.isConsumed());
		final KeyEvent t = typed('e');
		keys.keyTyped(t);
		Assert.assertFalse(t.isConsumed());
	}

	/** Ctrl/Alt/Meta+E belong to whatever else is bound to them. */
	@Test
	public void aModifiedEPassesThrough() throws Exception
	{
		arm(1_120);
		for (int mod : new int[]{KeyEvent.CTRL_DOWN_MASK, KeyEvent.ALT_DOWN_MASK, KeyEvent.META_DOWN_MASK})
		{
			final KeyEvent e = press(KeyEvent.VK_E, mod);
			keys.keyPressed(e);
			Assert.assertFalse("modifier " + mod, e.isConsumed());
		}
	}

	/** Other keys are never touched, armed or not — the digits above all,
	 *  since they are how a player types their own price. */
	@Test
	public void otherKeysPassThrough() throws Exception
	{
		arm(1_120);
		for (int code : new int[]{KeyEvent.VK_1, KeyEvent.VK_K, KeyEvent.VK_ENTER, KeyEvent.VK_BACK_SPACE})
		{
			final KeyEvent e = press(code, 0);
			keys.keyPressed(e);
			Assert.assertFalse("key " + code, e.isConsumed());
		}
	}

	/** Shift+E too: the chips promise E "with any modifier" passes. */
	@Test
	public void shiftEPassesThrough() throws Exception
	{
		arm(1_120);
		final KeyEvent e = press(KeyEvent.VK_E, KeyEvent.SHIFT_DOWN_MASK);
		keys.keyPressed(e);
		Assert.assertFalse(e.isConsumed());
	}

	// -- which box is open --------------------------------------------------

	/** A chatbox showing {@code title} as the question and {@code typed} as
	 *  the input line (the game draws the input with a trailing "*"). */
	private static net.runelite.api.Client chatbox(String title, String typed)
	{
		final java.util.Map<Integer, String> text = new java.util.HashMap<>();
		text.put(net.runelite.api.gameval.InterfaceID.Chatbox.MES_TEXT, title);
		text.put(net.runelite.api.gameval.InterfaceID.Chatbox.MES_TEXT2, typed + "*");
		return (net.runelite.api.Client) java.lang.reflect.Proxy.newProxyInstance(
			net.runelite.api.Client.class.getClassLoader(), new Class<?>[]{net.runelite.api.Client.class},
			(proxy, method, args) ->
			{
				if ("getWidget".equals(method.getName()) && args != null && args.length == 1
					&& args[0] instanceof Integer && text.containsKey(args[0]))
				{
					final String t = text.get(args[0]);
					return java.lang.reflect.Proxy.newProxyInstance(
						net.runelite.api.widgets.Widget.class.getClassLoader(),
						new Class<?>[]{net.runelite.api.widgets.Widget.class},
						(p2, m2, a2) ->
						{
							if ("getText".equals(m2.getName()))
							{
								return t;
							}
							final Class<?> r = m2.getReturnType();
							if (r == boolean.class)
							{
								return false;
							}
							return r.isPrimitive() ? (r == long.class ? (Object) 0L : (Object) 0) : null;
						});
				}
				final Class<?> r = method.getReturnType();
				if (r == boolean.class)
				{
					return false;
				}
				return r.isPrimitive() ? (r == long.class ? (Object) 0L : (Object) 0) : null;
			});
	}

	@Test
	public void theExchangesOwnBoxesAreRecognised()
	{
		Assert.assertEquals(GeOfferPriceOverlay.NumberBox.PRICE,
			GeOfferPriceOverlay.openNumberBox(chatbox("Set a price for each item:", "")));
		Assert.assertEquals(GeOfferPriceOverlay.NumberBox.QUANTITY,
			GeOfferPriceOverlay.openNumberBox(chatbox("How many do you wish to buy?", "12")));
	}

	/**
	 * A private message is never mistaken for the price box — the bug this
	 * test is named for: typing "what price?" to a friend with the offer
	 * screen open armed E, and the next E replaced the message with a number.
	 */
	@Test
	public void aPrivateMessageIsNeverAPriceBox()
	{
		Assert.assertEquals(GeOfferPriceOverlay.NumberBox.NONE,
			GeOfferPriceOverlay.openNumberBox(chatbox("Enter message to send to Bob:", "what price do you want")));
		Assert.assertEquals(GeOfferPriceOverlay.NumberBox.NONE,
			GeOfferPriceOverlay.openNumberBox(chatbox("Enter message to send to Bob:", "how many have you got")));
		Assert.assertEquals("a friend's name is not the question either", GeOfferPriceOverlay.NumberBox.NONE,
			GeOfferPriceOverlay.openNumberBox(chatbox("Enter message to send to Iceprice:", "")));
	}

	/** Armed, the typed 'e' is swallowed so it does not land in the box. */
	@Test
	public void anArmedTypedEIsSwallowed() throws Exception
	{
		arm(1_120);
		final KeyEvent t = typed('e');
		keys.keyTyped(t);
		Assert.assertTrue(t.isConsumed());
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class ClearanceTest
{
	/** 10,787 ruby necklaces against a book printing 4,700 a side. */
	@Test
	public void measuresTheStackAgainstBothSidesOfTheBook()
	{
		final Clearance c = Clearance.of(10_787_000, 4_700_000, 4_700_000);
		Assert.assertNotNull(c);
		Assert.assertEquals("both sides, averaged", 4_700_000, c.flowPerDay);
		Assert.assertEquals(10_787_000 / 4_700_000d, c.days, 1e-9);
	}

	/**
	 * The defect that killed the scored version of this: the insta-buy side
	 * collapses in a bleed while the sell side swells, so a one-sided
	 * denominator spikes exactly when the price is falling. Averaging the two
	 * keeps the same total flow reading the same either way.
	 */
	@Test
	public void aLopsidedBookReadsTheSameAsABalancedOneOfTheSameSize()
	{
		final Clearance balanced = Clearance.of(5_000_000, 2_000_000, 2_000_000);
		final Clearance bleeding = Clearance.of(5_000_000, 400_000, 3_600_000);
		Assert.assertEquals("same total prints, same reading",
			balanced.days, bleeding.days, 1e-9);
	}

	/**
	 * A blue partyhat: 3 held, 8 insta-buys in a day. Arithmetically "0.4
	 * days of demand", which reads as a liquid position off a sample of
	 * eight. Silence is the only honest output.
	 */
	@Test
	public void saysNothingWhenThereIsNotEnoughEvidence()
	{
		Assert.assertNull(Clearance.of(3, 8, 11));
		Assert.assertNull("just under the print floor", Clearance.of(500_000, 50_000, 49_999));
		Assert.assertNotNull("and on it", Clearance.of(500_000, 50_000, 50_000));
	}

	@Test
	public void refusesTheCasesItCannotMeasure()
	{
		Assert.assertNull("nothing held", Clearance.of(0, 5_000_000, 5_000_000));
		Assert.assertNull("negative holding", Clearance.of(-1, 5_000_000, 5_000_000));
		Assert.assertNull("no prints at all", Clearance.of(100, 0, 0));
		Assert.assertNull("garbage volume", Clearance.of(100, -5, 5_000_000));
	}

	/** A stack far past the scale still says how far past. */
	@Test
	public void theTopEndIsNotCapped()
	{
		final Clearance c = Clearance.of(41_000_000, 1_000_000, 1_000_000);
		Assert.assertEquals(41.0, c.days, 1e-9);
		Assert.assertEquals("41 days of demand", c.label());
	}

	/**
	 * One form, not four. Flow of 2,000,000 a side throughout, so every
	 * fixture clears MIN_PRINTS and only the stack size moves.
	 */
	@Test
	public void alwaysReadsInDays()
	{
		Assert.assertEquals("2.3 days of demand", Clearance.of(4_600_000, 2_000_000, 2_000_000).label());
		Assert.assertEquals("1.0 days of demand", Clearance.of(2_000_000, 2_000_000, 2_000_000).label());
		Assert.assertEquals("9.9 days of demand", Clearance.of(19_800_000, 2_000_000, 2_000_000).label());
		Assert.assertEquals("15 days of demand", Clearance.of(30_000_000, 2_000_000, 2_000_000).label());
	}

	/**
	 * Anything that clears inside a day gets no line at all.
	 *
	 * The first cut printed one on everything it could measure, so nearly
	 * every sell read "under an hour of demand" — true, useless, and
	 * inconsistent between adjacent cards. A stack that clears in an hour is
	 * not a stack whose size you have to think about.
	 */
	@Test
	public void saysNothingAboutAStackThatClearsInsideADay()
	{
		Assert.assertNull("one unit of something liquid",
			Clearance.of(1, 20_000_000, 20_000_000));
		Assert.assertNull("half a day", Clearance.of(1_000_000, 2_000_000, 2_000_000));
		Assert.assertNull("just under a day", Clearance.of(1_999_999, 2_000_000, 2_000_000));
		Assert.assertNotNull("and exactly a day", Clearance.of(2_000_000, 2_000_000, 2_000_000));
	}

	/**
	 * The stack size is the numerator, so the number RISES with size. The
	 * opportunity-cost design was rejected for getting this backwards: its
	 * score fell as the stack grew, so it went quiet on the biggest, deadest
	 * position on the list.
	 */
	@Test
	public void aBiggerStackAlwaysReadsAsMoreDays()
	{
		double last = -1;
		for (long qty : new long[]{2_000_000, 4_000_000, 20_000_000, 200_000_000})
		{
			final double days = Clearance.of(qty, 2_000_000, 2_000_000).days;
			Assert.assertTrue("monotonic in stack size", days > last);
			last = days;
		}
	}

	/** Cost basis cannot reach the arithmetic — there is no parameter for it. */
	@Test
	public void theFactoryHasNoCostBasisParameter()
	{
		for (java.lang.reflect.Method m : Clearance.class.getDeclaredMethods())
		{
			if (m.getName().equals("of"))
			{
				Assert.assertEquals("of(qty, buySideVol, sellSideVol) and nothing else",
					3, m.getParameterCount());
				for (Class<?> p : m.getParameterTypes())
				{
					Assert.assertEquals(long.class, p);
				}
			}
		}
	}

	/**
	 * No fixed string this class can print may tell the player what the price
	 * is going to do, or what to do about it.
	 *
	 * RangePosition's class comment states the stance — the plugin reports
	 * measurements and refuses to imply a forecast — and until now nothing
	 * enforced it. A verdict word is one careless edit away at all times, so
	 * the words are banned in a test rather than in a comment.
	 */
	@Test
	public void neverTellsThePlayerWhatHappensNext()
	{
		final String[] banned = {
			"sell now", "dump", "peak", "bottom", "top out", "recover",
			"rebound", "crash", "should", "will ", "expect", "predict",
			"good time", "bad time", "act fast", "hurry",
		};
		final List<String> strings = new ArrayList<>();
		for (long[] c : new long[][]{
			{4_600_000, 2_000_000, 2_000_000}, {2_000_000, 2_000_000, 2_000_000},
			{30_000_000, 2_000_000, 2_000_000}, {41_000_000, 1_000_000, 1_000_000}})
		{
			final Clearance cl = Clearance.of(c[0], c[1], c[2]);
			strings.add(cl.label());
			strings.addAll(List.of(cl.tooltipLines()));
		}
		for (String s : strings)
		{
			final String lower = s.toLowerCase();
			for (String b : banned)
			{
				Assert.assertFalse("\"" + s + "\" contains forecast word \"" + b + "\"",
					lower.contains(b));
			}
		}
	}

	/**
	 * The assumption that most easily makes the number wrong for you has to
	 * be stated, not buried: two players each holding 2.3 days are between
	 * them 4.6 days of flow.
	 */
	@Test
	public void statesTheAssumptionThatCouldMakeItWrong()
	{
		final String all = String.join(" ", Clearance.of(4_600_000, 2_000_000, 2_000_000).tooltipLines());
		Assert.assertTrue(all, all.contains("only seller listing"));
		Assert.assertTrue(all, all.contains("both sides of the book"));
		Assert.assertTrue("refuses cost basis and direction out loud",
			all.contains("what you paid") && all.contains("where the price goes next"));
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * "i saw sharks sell but no green numkbers came up" / "oo you right i just
 * cooked these" / "yes add the gold coins pop": a sale with no buy on record
 * pops the coins it brought in, in gold. Never as profit.
 */
public class CoinPopsTest
{
	private static final int SHARK = 385;
	private static final long MAIN = 42L;

	private static long each(long price)
	{
		return price - FlipTracker.taxPerItem(price, SHARK);
	}

	/** Sharks listed in slot 3 at 900 that nothing on record paid for. */
	private static FlipTracker cooked()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(MAIN);
		t.onOffer(1_000, 3, SHARK, "Shark", false, 0, 0, 900, 2_000, false);
		return t;
	}

	private static void sold(FlipTracker t, long when, int units)
	{
		t.onOffer(when, 3, SHARK, "Shark", false, units, units * 900L, 900, 2_000, false);
	}

	private static FlipTracker restarted(FlipTracker t)
	{
		final Gson gson = new Gson();
		final FlipTracker after = new FlipTracker();
		after.restore(gson.fromJson(gson.toJson(t.snapshot()), FlipTracker.State.class));
		after.setAccountHash(MAIN);
		return after;
	}

	@Test
	public void cookedSharksWaitAsCoinsAfterTax()
	{
		final FlipTracker t = cooked();
		Assert.assertNull("nothing sold yet", t.unseenBy(3, SHARK));
		Assert.assertFalse(t.waiting(3));
		sold(t, 2_000, 500);
		Assert.assertTrue("taxed", each(900) < 900);
		Assert.assertArrayEquals(new long[]{500, 500 * each(900), FlipTracker.UNSEEN_COINS}, t.unseenBy(3, SHARK));
		Assert.assertTrue(t.waiting(3));
		Assert.assertNull("not profit: nothing booked", t.bookedBy(3));
		Assert.assertTrue("and no flip", t.getFlips().isEmpty());

		sold(t, 3_000, 800);
		Assert.assertArrayEquals("every batch, until shown", new long[]{800, 800 * each(900), FlipTracker.UNSEEN_COINS},
			t.unseenBy(3, SHARK));
		t.markShown(3);
		Assert.assertNull(t.unseenBy(3, SHARK));
		Assert.assertFalse(t.waiting(3));

		sold(t, 4_000, 1_000);
		Assert.assertArrayEquals("then only what is new", new long[]{200, 200 * each(900), FlipTracker.UNSEEN_COINS},
			t.unseenBy(3, SHARK));
		Assert.assertNull("only over that item's sell", t.unseenBy(3, 386));
	}

	/** 300 bought, 200 cooked, all 500 sold in one go: one figure, the
	 *  profit — and the coins go with it rather than popping after. */
	@Test
	public void profitKeepsTheSquareWhenBothWait()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(MAIN);
		t.onOffer(1_000, 0, SHARK, "Shark", true, 0, 0, 800, 300, false);
		t.onOffer(2_000, 0, SHARK, "Shark", true, 300, 300 * 800L, 800, 300, false);
		t.onOffer(3_000, 0, 0, "", false, 0, 0, 0, 0, true);
		t.onOffer(4_000, 3, SHARK, "Shark", false, 0, 0, 900, 500, false);
		t.onOffer(5_000, 3, SHARK, "Shark", false, 500, 500 * 900L, 900, 500, false);
		Assert.assertArrayEquals(new long[]{300, 300 * (each(900) - 800), FlipTracker.UNSEEN_PROFIT}, t.unseenBy(3, SHARK));
		final long[] row = t.snapshot().slotsByAccount.get(MAIN).get(3);
		Assert.assertArrayEquals("the 200 cooked are on the record all the same",
			new long[]{200, 200 * each(900), 0, 0}, java.util.Arrays.copyOfRange(row, row.length - 4, row.length));
		t.markShown(3);
		Assert.assertNull("the coins counted as shown with it", t.unseenBy(3, SHARK));
		final long[] shown = t.snapshot().slotsByAccount.get(MAIN).get(3);
		Assert.assertArrayEquals(new long[]{200, 200 * each(900), 200, 200 * each(900)},
			java.util.Arrays.copyOfRange(shown, shown.length - 4, shown.length));
	}

	/** The bought ones sell first, the cooked after: profit, then coins. */
	@Test
	public void aLaterSaleWithNothingLeftOnRecordPopsCoins()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(MAIN);
		t.onOffer(1_000, 0, SHARK, "Shark", true, 0, 0, 800, 300, false);
		t.onOffer(2_000, 0, SHARK, "Shark", true, 300, 300 * 800L, 800, 300, false);
		t.onOffer(3_000, 0, 0, "", false, 0, 0, 0, 0, true);
		t.onOffer(4_000, 3, SHARK, "Shark", false, 0, 0, 900, 500, false);
		t.onOffer(5_000, 3, SHARK, "Shark", false, 300, 300 * 900L, 900, 500, false);
		Assert.assertEquals(FlipTracker.UNSEEN_PROFIT, t.unseenBy(3, SHARK)[2]);
		t.markShown(3);
		t.onOffer(6_000, 3, SHARK, "Shark", false, 500, 500 * 900L, 900, 500, false);
		Assert.assertArrayEquals(new long[]{200, 200 * each(900), FlipTracker.UNSEEN_COINS}, t.unseenBy(3, SHARK));
	}

	/** Sold with the Exchange shut, then RuneLite restarted. */
	@Test
	public void survivesARestart()
	{
		final FlipTracker t = cooked();
		sold(t, 2_000, 500);
		final FlipTracker after = restarted(t);
		Assert.assertArrayEquals(new long[]{500, 500 * each(900), FlipTracker.UNSEEN_COINS}, after.unseenBy(3, SHARK));
		after.markShown(3);
		Assert.assertNull("shown, and not again after the next", restarted(after).unseenBy(3, SHARK));
	}

	/** Saved behind the pairs of units that were in a box at listing — and
	 *  both read back where they were written. */
	@Test
	public void savedAfterTheBoxedPairs()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(MAIN);
		/* 100 bought and still in slot 0's box when the sell is listed: the
		   sell cannot be those, so it is charged nothing. */
		t.onOffer(1_000, 0, SHARK, "Shark", true, 0, 0, 800, 100, false);
		t.onOffer(2_000, 0, SHARK, "Shark", true, 100, 100 * 800L, 800, 100, false);
		t.noteBox(0, SHARK, 100);
		t.onOffer(3_000, 3, SHARK, "Shark", false, 0, 0, 900, 2_000, false);
		sold(t, 4_000, 50);
		final long[] row = t.snapshot().slotsByAccount.get(MAIN).get(3);
		Assert.assertEquals("one boxed pair", 1, row[13]);
		Assert.assertEquals("then the coins", 14 + 2 + 4, row.length);

		final FlipTracker after = restarted(t);
		Assert.assertArrayEquals(new long[]{50, 50 * each(900), FlipTracker.UNSEEN_COINS}, after.unseenBy(3, SHARK));
		after.markShown(3);
		/* The pair still keeps the boxed lot out once collected: more sold
		   is coins again, not profit against it. */
		after.onOffer(5_000, 0, 0, "", false, 0, 0, 0, 0, true);
		after.onOffer(6_000, 3, SHARK, "Shark", false, 150, 150 * 900L, 900, 2_000, false);
		Assert.assertNull(after.bookedBy(3));
		Assert.assertArrayEquals(new long[]{100, 100 * each(900), FlipTracker.UNSEEN_COINS}, after.unseenBy(3, SHARK));
	}

	/** A save from before the coins: none of what it sold pops. */
	@Test
	public void anUpgradePopsNothingOld()
	{
		final FlipTracker t = cooked();
		sold(t, 2_000, 500);
		final FlipTracker.State saved = t.snapshot();
		saved.slotsByAccount.get(MAIN).replaceAll((slot, row) -> java.util.Arrays.copyOf(row, 14));
		final Gson gson = new Gson();
		final FlipTracker after = new FlipTracker();
		after.restore(gson.fromJson(gson.toJson(saved), FlipTracker.State.class));
		after.setAccountHash(MAIN);
		Assert.assertNull(after.unseenBy(3, SHARK));
		sold(after, 3_000, 700);
		Assert.assertArrayEquals("what sells after it does", new long[]{200, 200 * each(900), FlipTracker.UNSEEN_COINS},
			after.unseenBy(3, SHARK));
	}

	/** Collected on mobile and relisted on other terms: a new offer, with
	 *  only its own coins to show. */
	@Test
	public void aRelistStartsAtNothing()
	{
		final FlipTracker t = cooked();
		sold(t, 2_000, 500);
		final FlipTracker after = restarted(t);
		after.markSlotsUnwatched();
		after.onOffer(9_000, 3, SHARK, "Shark", false, 0, 0, 950, 1_000, false);
		Assert.assertNull(after.unseenBy(3, SHARK));
		after.onOffer(9_500, 3, SHARK, "Shark", false, 100, 95_000, 950, 1_000, false);
		Assert.assertArrayEquals(new long[]{100, 100 * each(950), FlipTracker.UNSEEN_COINS}, after.unseenBy(3, SHARK));
	}

	@Test
	public void markAllShownTakesTheCoinsToo()
	{
		final FlipTracker t = cooked();
		sold(t, 2_000, 500);
		t.setAccountHash(7L);
		t.markAllShown();
		t.setAccountHash(MAIN);
		Assert.assertNull(t.unseenBy(3, SHARK));
	}

	/* ── The figure ─────────────────────────────────────────────────── */

	@Test
	public void goldWithNoSign()
	{
		Assert.assertEquals("1,234 gp", ProfitPops.coinsText(1_234));
		Assert.assertEquals("20K gp", ProfitPops.coinsText(20_000));
		Assert.assertEquals("441,000 is not 441K-with-a-plus", "441K gp", ProfitPops.coinsText(441_000));
		Assert.assertEquals("cut as the sidebar's profit is", "24K", ProfitPops.shortText(new ProfitPops.Pop(0, 0, 24_100, true)));
		Assert.assertEquals("2.4K", ProfitPops.shortText(new ProfitPops.Pop(0, 0, 2_450, true)));
		Assert.assertEquals("200", ProfitPops.shortText(new ProfitPops.Pop(0, 0, 200, true)));
		Assert.assertEquals("+200", ProfitPops.shortText(new ProfitPops.Pop(0, 0, 200)));
		Assert.assertEquals("1,234 gp", ProfitPops.text(new ProfitPops.Pop(0, 0, 1_234, true)));
		Assert.assertEquals("+1,234 gp", ProfitPops.text(new ProfitPops.Pop(0, 0, 1_234)));
		Assert.assertEquals(ProfitPops.COINS, ProfitPops.colour(new ProfitPops.Pop(0, 0, 1_234, true)));
		Assert.assertEquals(ProfitPops.GAIN, ProfitPops.colour(new ProfitPops.Pop(0, 0, 1_234)));
	}

	@Test
	public void coinsAddToCoinsButNeverToProfit()
	{
		ProfitPops pops = new ProfitPops();
		pops.start(1, 1_000, true, 10_000);
		pops.start(1, 500, true, 10_600);
		List<ProfitPops.Pop> live = pops.running(10_700, s -> true);
		Assert.assertEquals(1, live.size());
		Assert.assertEquals(1_500, live.get(0).profit);
		Assert.assertTrue(live.get(0).coins);

		pops = new ProfitPops();
		pops.start(1, 2_000, false, 10_000);
		pops.start(1, 500, true, 10_600);
		live = pops.running(10_700, s -> true);
		Assert.assertEquals("profit keeps the square", 1, live.size());
		Assert.assertEquals(2_000, live.get(0).profit);
		Assert.assertFalse(live.get(0).coins);
		Assert.assertEquals("and is not restarted by the coins", 10_000, live.get(0).at);

		pops = new ProfitPops();
		pops.start(1, 500, true, 10_000);
		pops.start(1, 2_000, false, 10_600);
		live = pops.running(10_700, s -> true);
		Assert.assertEquals(1, live.size());
		Assert.assertEquals("profit takes it over, not added to", 2_000, live.get(0).profit);
		Assert.assertFalse(live.get(0).coins);

		pops = new ProfitPops();
		pops.start(1, 2_000, false, 10_000);
		pops.start(1, 500, true, 12_000);
		live = pops.running(12_100, s -> true);
		Assert.assertEquals("a later sale takes the square over", 1, live.size());
		Assert.assertTrue(live.get(0).coins);
	}

	@Test
	public void paintedInGold()
	{
		final Rectangle slot = new Rectangle(120, 40, 115, 110);
		final BufferedImage img = new BufferedImage(360, 200, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		ProfitPops.draw(g, slot, new ProfitPops.Pop(1, 0, 441_000, true), 400,
			new java.awt.Font(java.awt.Font.SANS_SERIF, java.awt.Font.BOLD, 16));
		g.dispose();
		Assert.assertTrue(count(img, ProfitPops.COINS) > 0);
		Assert.assertEquals(0, count(img, ProfitPops.GAIN));
	}

	static int count(BufferedImage img, Color c)
	{
		int n = 0;
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				final int rgb = img.getRGB(x, y);
				if ((rgb >>> 24) > 200 && Math.abs(((rgb >> 16) & 0xFF) - c.getRed()) < 12
					&& Math.abs(((rgb >> 8) & 0xFF) - c.getGreen()) < 12 && Math.abs((rgb & 0xFF) - c.getBlue()) < 12)
				{
					n++;
				}
			}
		}
		return n;
	}
}

package com.pocketge.tracker;

import net.runelite.api.Item;
import org.junit.Assert;
import org.junit.Test;

/**
 * What is waiting in a GE slot's collection box, on the sidebar square's
 * hover: "add how much money i have able to collect / how many additional
 * units have sold if any since last collect".
 */
public class CollectBoxTest
{
	private static final int MITHRIL_PLATEBODY = 1121;

	@Test
	public void eachSlotHasItsBox()
	{
		for (int slot = 0; slot < 6; slot++)
		{
			Assert.assertEquals(slot, PocketGeTrackerPlugin.collectSlot(518 + slot));
		}
		Assert.assertEquals(6, PocketGeTrackerPlugin.collectSlot(539));
		Assert.assertEquals(7, PocketGeTrackerPlugin.collectSlot(540));
		Assert.assertEquals("the offer containers are not the boxes", -1, PocketGeTrackerPlugin.collectSlot(526));
		Assert.assertEquals(-1, PocketGeTrackerPlugin.collectSlot(93));
	}

	@Test
	public void coinsAndTheOffersOwnItemAreCounted()
	{
		final long[] in = PocketGeTrackerPlugin.collectContents(
			new Item[]{new Item(995, 461_616), new Item(-1, 0), new Item(MITHRIL_PLATEBODY, 3)},
			MITHRIL_PLATEBODY, id -> id);
		Assert.assertArrayEquals(new long[]{461_616, 3}, in);
	}

	@Test
	public void anEmptyBoxIsZeroNotUnknown()
	{
		Assert.assertArrayEquals(new long[]{0, 0},
			PocketGeTrackerPlugin.collectContents(new Item[0], MITHRIL_PLATEBODY, id -> id));
	}

	/** Anything else in it and it is not the box we think it is: say nothing
	 *  rather than a wrong figure. */
	@Test
	public void aStrangerInTheBoxMeansItIsNotThisOffers()
	{
		Assert.assertNull(PocketGeTrackerPlugin.collectContents(
			new Item[]{new Item(995, 10), new Item(2359, 5)}, MITHRIL_PLATEBODY, id -> id));
	}

	/** A noted copy is the same item. */
	@Test
	public void notedCountsAsTheItem()
	{
		final long[] in = PocketGeTrackerPlugin.collectContents(
			new Item[]{new Item(1122, 40)}, MITHRIL_PLATEBODY, id -> id == 1122 ? MITHRIL_PLATEBODY : id);
		Assert.assertArrayEquals(new long[]{0, 40}, in);
	}

	private static GeSlotsPanel.SlotInfo sell(long coins, int items, int since)
	{
		final GeSlotsPanel.SlotInfo s = new GeSlotsPanel.SlotInfo();
		s.buy = false;
		s.collectCoins = coins;
		s.collectItems = items;
		s.sinceCollect = since;
		return s;
	}

	@Test
	public void theHoverSaysWhatIsWaiting()
	{
		Assert.assertEquals("To collect: 461,616 gp — 12 sold since you last collected",
			GeSlotsPanel.collectLine(sell(461_616, 0, 12)));
		Assert.assertEquals("To collect: 461,616 gp", GeSlotsPanel.collectLine(sell(461_616, 0, -1)));
		final GeSlotsPanel.SlotInfo buy = sell(1_200, 12_000, 12_000);
		buy.buy = true;
		Assert.assertEquals("To collect: 1,200 gp + 12,000 bought — 12,000 bought since you last collected",
			GeSlotsPanel.collectLine(buy));
	}

	@Test
	public void nothingWaitingOrNotSeenSaysNothing()
	{
		Assert.assertNull(GeSlotsPanel.collectLine(sell(0, 0, 0)));
		Assert.assertNull(GeSlotsPanel.collectLine(sell(-1, -1, -1)));
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.concurrent.Delayed;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import net.runelite.client.events.ConfigChanged;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * A write to the plugin's config group is not always a setting.
 *
 * The plugin keeps its own data in the same group — the trade state on every
 * offer update, the bank snapshot whenever the bank changes, the favourite
 * lists whenever the website stars an item. onConfigChanged used to restart
 * the advisor and the bridge on every one of them: an immediate round of
 * price requests to the wiki for a bank deposit, and the bridge's HTTP
 * server torn down from inside its own request handler.
 */
public class ConfigChangeTest
{
	private PocketGeTrackerPlugin plugin;
	private int bridgeStops;
	private int advisorCancels;

	private static void set(Object o, String field, Object value) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(o, value);
	}

	/** Every setting off, every number zero: enough for the sync methods to
	 *  run to completion without starting anything. */
	private static PocketGeTrackerConfig quietConfig()
	{
		return (PocketGeTrackerConfig) Proxy.newProxyInstance(
			PocketGeTrackerConfig.class.getClassLoader(),
			new Class<?>[]{PocketGeTrackerConfig.class},
			(proxy, method, args) ->
			{
				final Class<?> r = method.getReturnType();
				if (r == boolean.class)
				{
					return false;
				}
				if (r.isPrimitive())
				{
					return r == long.class ? 0L : 0;
				}
				return null;
			});
	}

	@Before
	public void wire() throws Exception
	{
		plugin = new PocketGeTrackerPlugin();
		set(plugin, "config", quietConfig());
		set(plugin, "bridge", new LocalBridgeServer(new Gson())
		{
			@Override
			public void stop()
			{
				bridgeStops++;
			}
		});
		armAdvisor();
	}

	/** syncAdvisor starts by cancelling the running schedule, so a counted
	 *  cancel is a restart. Re-armed after each, since it nulls the field. */
	private void armAdvisor() throws Exception
	{
		set(plugin, "advisorTask", new ScheduledFuture<Object>()
		{
			@Override
			public boolean cancel(boolean interrupt)
			{
				advisorCancels++;
				return true;
			}

			@Override
			public long getDelay(TimeUnit unit)
			{
				return 0;
			}

			@Override
			public int compareTo(Delayed o)
			{
				return 0;
			}

			@Override
			public boolean isCancelled()
			{
				return false;
			}

			@Override
			public boolean isDone()
			{
				return false;
			}

			@Override
			public Object get()
			{
				return null;
			}

			@Override
			public Object get(long timeout, TimeUnit unit)
			{
				return null;
			}
		});
	}

	private void write(String key)
	{
		final ConfigChanged e = new ConfigChanged();
		e.setGroup(PocketGeTrackerConfig.GROUP);
		e.setKey(key);
		plugin.onConfigChanged(e);
	}

	@Test
	public void theirOwnDataRestartsNothing()
	{
		for (String key : new String[]{"state", "bankMemory", "watchlistRows",
			"favoriteLists", "favorites", "activeFavoriteList",
			"priceAlerts", "reuseBrowserTab", "confirmBlock"})
		{
			write(key);
			Assert.assertEquals(key + " restarted the bridge", 0, bridgeStops);
			Assert.assertEquals(key + " restarted the advisor", 0, advisorCancels);
		}
	}

	@Test
	public void theBridgeSettingsRestartTheBridgeOnly()
	{
		write("localBridge");
		write("bridgePort");
		Assert.assertEquals(2, bridgeStops);
		Assert.assertEquals(0, advisorCancels);
	}

	@Test
	public void theAdvisorSettingsRestartTheAdvisorOnly() throws Exception
	{
		write("advisor");
		Assert.assertEquals(1, advisorCancels);
		armAdvisor();
		write("adjustInterval");
		Assert.assertEquals(2, advisorCancels);
		Assert.assertEquals(0, bridgeStops);
	}

	@Test
	public void anotherPluginsGroupIsIgnored()
	{
		final ConfigChanged e = new ConfigChanged();
		e.setGroup("someotherplugin");
		e.setKey("localBridge");
		plugin.onConfigChanged(e);
		Assert.assertEquals(0, bridgeStops);
		Assert.assertEquals(0, advisorCancels);
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.io.File;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import org.junit.Assert;
import org.junit.Test;

/**
 * "its remembering an old buy price. it thinks i paid 359 each for these, i
 * only paid 280 each. i lost money but i didnt lose that much money" — the
 * sale already booked, and the way to put it right: "Correct what I paid…"
 * on its row.
 */
public class CorrectPaidTest
{
	private static final int CATALYST = 30771;

	private static void set(Object o, String field, Object v) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(o, v);
	}

	private static Object get(Object o, String field) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		return f.get(o);
	}

	@Test
	public void theLedgerRewritesOnlyTheRowsItIsTold() throws Exception
	{
		final File file = new File(Files.createTempDirectory("pge-correct").toFile(), "flips.jsonl");
		final Gson gson = new Gson();
		final String other = gson.toJson(new Flip(7, 1, 2, 1603, "Ruby", 100, 180_000, 200_000, 4_000));
		final String wrong = gson.toJson(new Flip(9, 1, 5, CATALYST, "Aether catalyst", 13_418,
			4_817_062, 3_757_040, 67_090));
		Files.write(file.toPath(), (other + "\n" + "not a flip at all\n" + wrong + "\n")
			.getBytes(StandardCharsets.UTF_8));
		final FlipLedger ledger = new FlipLedger(file, gson);

		final int changed = ledger.rewrite(f -> f.offerId == 9
			? new Flip(f.offerId, f.openedAt, f.closedAt, f.itemId, f.itemName, f.quantity, f.quantity * 277L,
				f.sellGross, f.tax)
			: f);
		Assert.assertEquals(1, changed);
		final List<String> lines = Files.readAllLines(file.toPath(), StandardCharsets.UTF_8);
		Assert.assertEquals("the other row, byte for byte", other, lines.get(0));
		Assert.assertEquals("a line it cannot read, kept", "not a flip at all", lines.get(1));
		final Flip fixed = gson.fromJson(lines.get(2), Flip.class);
		Assert.assertEquals(13_418L * 277, fixed.buySpent);
		Assert.assertEquals(-26_836, fixed.profit);
		final String[] left = file.getParentFile().list((d, n) -> n.endsWith(".tmp"));
		Assert.assertEquals("no copy left beside it", 0, left == null ? 0 : left.length);
		Assert.assertEquals("nothing to change, nothing written", 0, ledger.rewrite(f -> f));
	}

	@Test
	public void whatYouTypeIsReadAsANumber()
	{
		Assert.assertEquals(277, HistoryPanel.parsePaid("277"));
		Assert.assertEquals(277, HistoryPanel.parsePaid(" 277 gp "));
		Assert.assertEquals(1_250, HistoryPanel.parsePaid("1,250"));
		Assert.assertEquals(0, HistoryPanel.parsePaid("abc"));
		Assert.assertEquals(0, HistoryPanel.parsePaid(""));
		Assert.assertEquals(0, HistoryPanel.parsePaid(null));
		Assert.assertEquals(0, HistoryPanel.parsePaid("-5"));
		Assert.assertEquals("the game's own shorthand", 1_200, HistoryPanel.parsePaid("1.2k"));
		Assert.assertEquals(45_000_000, HistoryPanel.parsePaid("45m"));
		Assert.assertEquals(2_100_000_000L, HistoryPanel.parsePaid("2.1b"));
		Assert.assertEquals(277, HistoryPanel.parsePaid("277GP"));
		Assert.assertEquals("past what a GE price can be", 0, HistoryPanel.parsePaid("3b"));
		Assert.assertEquals(0, HistoryPanel.parsePaid("0"));
		Assert.assertEquals(0, HistoryPanel.parsePaid("1.2.3"));
	}

	/**
	 * The whole thing: the sale as the old rule booked it, -1.12M, put right
	 * at 277 each — in the file, the cached list, the saved state and the
	 * totals — and another trade left alone.
	 */
	@Test
	public void aBookedSaleIsRepricedEverywhereItIsKept() throws Exception
	{
		final File file = new File(Files.createTempDirectory("pge-correct").toFile(), "flips.jsonl");
		final ScheduledThreadPoolExecutor ex = new ScheduledThreadPoolExecutor(1);
		try
		{
			final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
			set(plugin, "gson", new Gson());
			set(plugin, "executor", ex);
			final FlipTracker tracker = (FlipTracker) get(plugin, "tracker");
			final Gson gson = new Gson();
			final Flip ruby = new Flip(7, 1, 2, 1603, "Ruby", 100, 180_000, 200_000, 4_000);
			/* Booked in two fills of one offer, as a sale often is. */
			final Flip partA = new Flip(9, 1, 5, CATALYST, "Aether catalyst", 6_000, 6_000L * 359, 6_000L * 280, 6_000L * 5);
			final Flip partB = new Flip(9, 1, 6, CATALYST, "Aether catalyst", 7_418, 7_418L * 359, 7_418L * 280, 7_418L * 5);
			Files.write(file.toPath(), (gson.toJson(ruby) + "\n" + gson.toJson(partA) + "\n" + gson.toJson(partB) + "\n")
				.getBytes(StandardCharsets.UTF_8));
			plugin.openLedger(file);
			ex.submit(() -> { }).get(10, TimeUnit.SECONDS);

			final Flip trade = Flip.merge(List.of(partA, partB));
			Assert.assertEquals(13_418L * (280 - 5 - 359), trade.profit);
			final long lifetimeBefore = tracker.snapshot().lifetimeProfit;
			final java.util.concurrent.atomic.AtomicLong revision =
				(java.util.concurrent.atomic.AtomicLong) get(plugin, "historyRevision");
			final long revisionBefore = revision.get();

			plugin.correctPaid(trade, 277);
			ex.submit(() -> { }).get(10, TimeUnit.SECONDS);

			final List<Flip> onDisk = new FlipLedger(file, gson).readAll();
			Assert.assertEquals(3, onDisk.size());
			long catalyst = 0;
			for (Flip f : onDisk)
			{
				if (f.itemId == CATALYST)
				{
					Assert.assertEquals(f.quantity * 277L, f.buySpent);
					catalyst += f.profit;
				}
				else
				{
					Assert.assertEquals("the other trade untouched", ruby.profit, f.profit);
				}
			}
			Assert.assertEquals("the true result", 13_418L * (280 - 5 - 277), catalyst);
			@SuppressWarnings("unchecked")
			final List<Flip> cached = (List<Flip>) get(plugin, "ledgerFlips");
			Assert.assertEquals(catalyst, cached.stream().filter(f -> f.itemId == CATALYST).mapToLong(f -> f.profit).sum());
			Assert.assertEquals("lifetime moves by what the correction changed",
				lifetimeBefore + 13_418L * (359 - 277), tracker.snapshot().lifetimeProfit);
			Assert.assertEquals("the website is told to read it again", revisionBefore + 1, revision.get());

			/* Again at the same price: nothing left to change. */
			plugin.correctPaid(trade, 277);
			ex.submit(() -> { }).get(10, TimeUnit.SECONDS);
			Assert.assertEquals(revisionBefore + 1, revision.get());
			Assert.assertEquals(lifetimeBefore + 13_418L * (359 - 277), tracker.snapshot().lifetimeProfit);
		}
		finally
		{
			ex.shutdownNow();
		}
	}

	/** A row with no offer token names its fills only by inference: not
	 *  offered, and refused if asked. */
	@Test
	public void aRowWithoutAnOfferTokenIsLeftAlone() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		final ScheduledThreadPoolExecutor ex = new ScheduledThreadPoolExecutor(1);
		try
		{
			set(plugin, "executor", ex);
			final long before = ((java.util.concurrent.atomic.AtomicLong) get(plugin, "historyRevision")).get();
			plugin.correctPaid(new Flip(0, 1, 5, CATALYST, "Aether catalyst", 10, 3_590, 2_800, 50), 277);
			ex.submit(() -> { }).get(10, TimeUnit.SECONDS);
			Assert.assertEquals(before, ((java.util.concurrent.atomic.AtomicLong) get(plugin, "historyRevision")).get());
		}
		finally
		{
			ex.shutdownNow();
		}
	}

	/**
	 * A sale still selling, corrected between two of its fills, with the
	 * second fill's ledger write queued behind the correction: it lands
	 * corrected, the totals move once, and the slot's "Made" moves with it.
	 */
	@Test
	public void aFillQueuedBehindTheCorrectionIsWrittenCorrected() throws Exception
	{
		final File file = new File(Files.createTempDirectory("pge-correct").toFile(), "flips.jsonl");
		final ScheduledThreadPoolExecutor ex = new ScheduledThreadPoolExecutor(1);
		try
		{
			final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
			final Gson gson = new Gson();
			set(plugin, "gson", gson);
			set(plugin, "executor", ex);
			final FlipTracker tracker = (FlipTracker) get(plugin, "tracker");
			tracker.setAccountHash(42L);
			Files.write(file.toPath(), (gson.toJson(new Flip(7, 1, 2, 1603, "Ruby", 100, 180_000, 200_000, 4_000)) + "\n")
				.getBytes(StandardCharsets.UTF_8));
			plugin.openLedger(file);
			ex.submit(() -> { }).get(10, TimeUnit.SECONDS);

			/* Bought at 359 as far as the record knows; selling 1,000 at 280. */
			tracker.onOffer(1, 0, CATALYST, "Aether catalyst", true, 0, 0, 359, 1_000, false);
			tracker.onOffer(2, 0, CATALYST, "Aether catalyst", true, 1_000, 359_000, 359, 1_000, false);
			tracker.onOffer(3, 0, 0, "", false, 0, 0, 0, 0, true);
			tracker.onOffer(4, 1, CATALYST, "Aether catalyst", false, 0, 0, 280, 1_000, false);
			tracker.onOffer(5, 1, CATALYST, "Aether catalyst", false, 600, 600L * 280, 280, 1_000, false);
			ex.submit(() -> { }).get(10, TimeUnit.SECONDS);
			final Flip first = tracker.getFlips().get(tracker.getFlips().size() - 1);
			tracker.markShown(1); // the first 600's figure has popped
			final long lifetimeBefore = tracker.snapshot().lifetimeProfit;

			final java.util.concurrent.CountDownLatch hold = new java.util.concurrent.CountDownLatch(1);
			ex.execute(() ->
			{
				try
				{
					hold.await();
				}
				catch (InterruptedException ignore)
				{
				}
			});
			plugin.correctPaid(first, 277);
			tracker.onOffer(6, 1, CATALYST, "Aether catalyst", false, 1_000, 1_000L * 280, 280, 1_000, false);
			hold.countDown();
			ex.submit(() -> { }).get(10, TimeUnit.SECONDS);

			long onDisk = 0;
			int rows = 0;
			for (Flip f : new FlipLedger(file, gson).readAll())
			{
				if (f.itemId == CATALYST)
				{
					Assert.assertEquals("every fill at 277", f.quantity * 277L, f.buySpent);
					onDisk += f.profit;
					rows++;
				}
			}
			Assert.assertEquals(2, rows);
			final long truth = 1_000L * (280 - 5 - 277);
			Assert.assertEquals(truth, onDisk);
			Assert.assertEquals("lifetime moved once, to the truth", lifetimeBefore - first.profit + truth,
				tracker.snapshot().lifetimeProfit);
			Assert.assertArrayEquals("the slot's Made moved with it", new long[]{1_000, truth}, tracker.bookedBy(1));
			Assert.assertArrayEquals("the 400 not yet shown pop at their corrected figure, the correction itself not at all",
				new long[]{400, 400L * (280 - 5 - 277), FlipTracker.UNSEEN_PROFIT}, tracker.unseenBy(1, CATALYST));
		}
		finally
		{
			ex.shutdownNow();
		}
	}

	/** Another client's ledger writing the same file while a rewrite runs:
	 *  every row it appended is still there afterwards. */
	@Test
	public void aRewriteNeverLosesAnotherWritersRow() throws Exception
	{
		final File file = new File(Files.createTempDirectory("pge-correct").toFile(), "flips.jsonl");
		final Gson gson = new Gson();
		final FlipLedger a = new FlipLedger(file, gson);
		final FlipLedger b = new FlipLedger(file, gson);
		Assert.assertTrue(a.append(new Flip(9, 1, 5, CATALYST, "Aether catalyst", 10, 3_590, 2_800, 50)));
		final Thread writer = new Thread(() ->
		{
			for (int i = 0; i < 200; i++)
			{
				b.append(new Flip(1000 + i, 1, 10 + i, 1603, "Ruby", 1, 1_800, 2_000, 40));
			}
		});
		writer.start();
		for (int i = 0; i < 50; i++)
		{
			final long cost = 270 + (i % 2) * 7;
			a.rewrite(f -> f.offerId == 9 ? new Flip(9, 1, 5, CATALYST, "Aether catalyst", 10, 10 * cost, 2_800, 50) : f);
		}
		writer.join();
		final List<Flip> all = a.readAll();
		Assert.assertEquals("every appended row, and the corrected one", 201, all.size());
	}

	/** Right-clicking a row opens its menu and nothing else; a left click
	 *  still opens the chart. */
	@Test
	public void aRightClickDoesNotAlsoOpenTheChart()
	{
		final List<String> charts = new java.util.ArrayList<>();
		final HistoryPanel panel = new HistoryPanel(new HistoryPanel.Actions()
		{
			@Override
			public void openChart(String itemName)
			{
				charts.add(itemName);
			}
		});
		panel.update(List.of(new Flip(9, 1, System.currentTimeMillis(), CATALYST, "Aether catalyst", 10, 3_590, 2_800, 50)),
			FlipStats.Range.ALL);
		final javax.swing.JLabel name = find(panel, "Aether catalyst");
		Assert.assertNotNull(name);
		name.dispatchEvent(new java.awt.event.MouseEvent(name, java.awt.event.MouseEvent.MOUSE_CLICKED,
			System.currentTimeMillis(), java.awt.event.InputEvent.BUTTON3_DOWN_MASK, 5, 5, 1, false,
			java.awt.event.MouseEvent.BUTTON3));
		Assert.assertTrue("right click: no chart", charts.isEmpty());
		name.dispatchEvent(new java.awt.event.MouseEvent(name, java.awt.event.MouseEvent.MOUSE_CLICKED,
			System.currentTimeMillis(), java.awt.event.InputEvent.BUTTON1_DOWN_MASK, 5, 5, 1, false,
			java.awt.event.MouseEvent.BUTTON1));
		Assert.assertEquals("left click: the chart", List.of("Aether catalyst"), charts);
	}

	private static javax.swing.JLabel find(java.awt.Container root, String text)
	{
		for (java.awt.Component c : root.getComponents())
		{
			if (c instanceof javax.swing.JLabel && text.equals(((javax.swing.JLabel) c).getText()))
			{
				return (javax.swing.JLabel) c;
			}
			if (c instanceof java.awt.Container)
			{
				final javax.swing.JLabel f = find((java.awt.Container) c, text);
				if (f != null)
				{
					return f;
				}
			}
		}
		return null;
	}
}

package com.pocketge.tracker;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import org.junit.Assert;
import org.junit.Test;

/**
 * "plugin showing -19% on day sunfire splinters. but website is showing +3%
 * green 1day. which is true?" The website's. The watchlist badge measured the
 * live mid against the Wiki's /24h average, which is the last COMPLETE day's:
 * after a fall it still holds the day before. It now measures what the
 * website's 1D button does: the live mid against the mid 24 hours ago.
 */
public class DayChangeTest
{
	private static final long NOW = 1_800_000_000L;

	private static JsonObject hour(long ts, long low, long high)
	{
		final JsonObject o = new JsonObject();
		o.addProperty("timestamp", ts);
		if (high > 0)
		{
			o.addProperty("avgHighPrice", high);
		}
		if (low > 0)
		{
			o.addProperty("avgLowPrice", low);
		}
		return o;
	}

	/** Sunfire splinters: 330 two days ago, a fall to the 250s by a day
	 *  ago, 256/266 now. The day's change is about +3%, not -19%. */
	@Test
	public void theDaysChangeIsAgainstADayAgoNotYesterdaysAverage()
	{
		final JsonArray data = new JsonArray();
		for (int h = 48; h > 24; h--)
		{
			data.add(hour(NOW - h * 3600L, 325, 335)); // the day before: what /24h averaged
		}
		data.add(hour(NOW - 24 * 3600L + 600, 248, 258)); // the first hour of the day
		for (int h = 23; h >= 1; h--)
		{
			data.add(hour(NOW - h * 3600L, 240, 270));
		}
		final PriceExtremes ex = MarketClient.extremesFrom(data, NOW);
		Assert.assertEquals(253.0, ex.midDayBefore(NOW), 0.001);
		final double pct = ex.dayChangePct(266, 256, NOW);
		Assert.assertEquals((261.0 - 253.0) / 253.0 * 100, pct, 0.001);
		Assert.assertTrue("+3%, as the website says", pct > 3 && pct < 3.3);
	}

	/** A one-sided hour counts at the side there is, as app.js's pctChange
	 *  takes it; an hour with neither is skipped. */
	@Test
	public void theFirstPricedHourOfTheDay()
	{
		final JsonArray data = new JsonArray();
		data.add(hour(NOW - 23 * 3600L, 0, 0));
		data.add(hour(NOW - 22 * 3600L, 0, 300));
		data.add(hour(NOW - 21 * 3600L, 280, 290));
		Assert.assertEquals(300.0, MarketClient.extremesFrom(data, NOW).midDayBefore(NOW), 0.001);
	}

	/** Nothing a day ago, or no live price: no figure, not a made-up one. */
	@Test
	public void unknownIsNotAFigure()
	{
		final PriceExtremes none = MarketClient.extremesFrom(new JsonArray(), NOW);
		Assert.assertEquals(0.0, none.midDayBefore(NOW), 0.0);
		Assert.assertTrue(Double.isNaN(none.dayChangePct(266, 256, NOW)));
		Assert.assertTrue(Double.isNaN(new PriceExtremes().dayChangePct(266, 256, NOW)));
		final JsonArray data = new JsonArray();
		data.add(hour(NOW - 20 * 3600L, 248, 258));
		final PriceExtremes ex = MarketClient.extremesFrom(data, NOW);
		Assert.assertTrue(Double.isNaN(ex.dayChangePct(0, 0, NOW)));
		Assert.assertEquals("one live side is the mid", (266 - 253) / 253.0 * 100, ex.dayChangePct(266, 0, NOW), 0.001);
		Assert.assertEquals("and the other", (240 - 253) / 253.0 * 100, ex.dayChangePct(0, 240, NOW), 0.001);
	}

	/** The watchlist row, which drives the spike badge and the price alert,
	 *  takes the day's change — not the /24h average. Read from the source:
	 *  the row is built on a running client. */
	@Test
	public void theWatchlistRowTakesTheDaysChange() throws Exception
	{
		final String src = java.nio.file.Files.readString(
			java.nio.file.Path.of("src/main/java/com/pocketge/tracker/PocketGeTrackerPlugin.java"))
			.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
		final int at = src.indexOf("row.changePct =");
		Assert.assertTrue(at > 0);
		Assert.assertEquals("set in one place", at, src.lastIndexOf("row.changePct ="));
		final String before = src.substring(Math.max(0, at - 1400), at);
		/* By place in the list: the day's change for the first
		   MAX_EXTREME_FAVORITES, asked for when missing — never the /24h
		   figure in its place — and the /24h average, said as such, for the
		   rest. */
		final int reach = before.indexOf("if (dayReach.contains(f.id))");
		final int avg = before.indexOf("avgHighPrice");
		Assert.assertTrue(before, reach > 0 && avg > reach);
		final String inReach = before.substring(reach, avg);
		Assert.assertTrue(inReach, inReach.contains("day.dayChangePct(q.high, q.low, nowSec)"));
		Assert.assertTrue(inReach, inReach.contains("missingDay.add(f.id);"));
		Assert.assertTrue(inReach, inReach.endsWith("else if (q.high > 0 && avg != null && avg."));
		Assert.assertTrue(before.substring(avg), before.substring(avg).contains("row.changeVsAverage = true;"));
		Assert.assertTrue(src.contains("final Set<Integer> dayReach = dayChangeFavourites(activeList);"));
		Assert.assertTrue(src.contains("final Set<Integer> favIds = dayChangeFavourites(activeFavoriteList(loadFavoriteLists()));"));
		Assert.assertTrue("the missing are asked for", src.contains("requestDayExtremes(missingDay);"));
		/* Alerts for the watchlist only: the inspected item rides along. */
		final String after = src.substring(at, at + 200);
		Assert.assertTrue(after, after.matches("(?s)row\\.changePct = change;\\s*if \\(onList\\)\\s*\\{\\s*maybeAlertOnMove\\(row\\);.*"));
	}

	/** The first MAX_EXTREME_FAVORITES of the list, in its order, once each. */
	@Test
	public void theReachIsTheFirstOfTheList()
	{
		final FavoriteLists.FavoriteList list = new FavoriteLists.FavoriteList();
		list.items = new java.util.ArrayList<>();
		for (int i = 0; i < PocketGeTrackerPlugin.MAX_EXTREME_FAVORITES + 5; i++)
		{
			list.items.add(new Favorites.Fav(1000 + i, "item " + i));
		}
		list.items.add(1, new Favorites.Fav(1000, "a duplicate"));
		final java.util.Set<Integer> reach = PocketGeTrackerPlugin.dayChangeFavourites(list);
		Assert.assertEquals(PocketGeTrackerPlugin.MAX_EXTREME_FAVORITES, reach.size());
		Assert.assertEquals(Integer.valueOf(1000), reach.iterator().next());
		Assert.assertTrue(reach.contains(1000 + PocketGeTrackerPlugin.MAX_EXTREME_FAVORITES - 1));
		Assert.assertFalse(reach.contains(1000 + PocketGeTrackerPlugin.MAX_EXTREME_FAVORITES));
		Assert.assertTrue(PocketGeTrackerPlugin.dayChangeFavourites(null).isEmpty());
	}

	/** "A day ago" moves with the clock, not with the fetch. The day's
	 *  hours are kept, so six hours after the fetch the anchor is the first
	 *  priced hour from 18 hours before it — what a fresh fetch would give —
	 *  until the hours held no longer reach back a day: then no figure. */
	@Test
	public void aDayAgoMovesWithTheClock()
	{
		final JsonArray data = new JsonArray();
		data.add(hour(NOW - 30 * 3600L, 100, 110)); // older than a day: not kept
		for (int h = 24; h >= 1; h--)
		{
			data.add(hour(NOW - h * 3600L, 200 + h * 10, 210 + h * 10));
		}
		data.add(hour(NOW - 17 * 3600L - 1800, 0, 0)); // nothing traded: skipped
		final PriceExtremes ex = MarketClient.extremesFrom(data, NOW);
		Assert.assertEquals("at the fetch", 445.0, ex.midDayBefore(NOW), 0.001);
		Assert.assertEquals("six hours on", 385.0, ex.midDayBefore(NOW + 6 * 3600L), 0.001);
		Assert.assertEquals("between hours: the next one", 375.0, ex.midDayBefore(NOW + 6 * 3600L + 1), 0.001);
		Assert.assertEquals((255.0 - 385.0) / 385.0 * 100, ex.dayChangePct(260, 250, NOW + 6 * 3600L), 0.001);
		Assert.assertEquals("the last hour held", 215.0, ex.midDayBefore(NOW + 23 * 3600L), 0.001);
		Assert.assertEquals("past it", 0.0, ex.midDayBefore(NOW + 23 * 3600L + 1), 0.0);
		Assert.assertTrue(Double.isNaN(ex.dayChangePct(260, 250, NOW + 24 * 3600L)));
		Assert.assertEquals("stamped when built from a fetch", NOW,
			MarketClient.extremesFrom(new JsonArray(), NOW).fetchedAt);
	}

	/** Out of order, as nothing promises they arrive sorted: still the
	 *  earliest hour of the day. */
	@Test
	public void theEarliestHourWhateverTheOrder()
	{
		final JsonArray data = new JsonArray();
		data.add(hour(NOW - 2 * 3600L, 400, 410));
		data.add(hour(NOW - 20 * 3600L, 248, 258));
		data.add(hour(NOW - 30 * 3600L, 100, 110)); // older than a day: not in it
		Assert.assertEquals(253.0, MarketClient.extremesFrom(data, NOW).midDayBefore(NOW), 0.001);
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * When the live spread cannot clear the tax, the plugin stops quoting the
 * traded price.
 *
 * The report, for the third time and with the numbers to hand: the plugin
 * offered to sell Ruby at 779 while pocketge.com, on the same market at the
 * same moment, said 788. 779 was the insta-buy — the price rubies were
 * actually changing hands at — presented as a target.
 *
 * The cause was a gap in the port, not a bug in the engine. Ruby's live book
 * was insta-sell 767, insta-buy 779. Tax on 779 is 15, so buying at 767 and
 * selling at 779 nets MINUS THREE gp a unit: the spread is dead. TradeEngine
 * says so honestly, converging both targets on the live quote and reporting
 * viable=false — and every caller then fell back to the raw print.
 *
 * The website does one more thing, in computeViewTargets, which had never been
 * ported: when the live spread is dead it anchors to the DAY's recency-weighted
 * dip and peak instead, because prints all day at 758 and 788 are levels a
 * patient order actually reaches even though the current quote is not. It uses
 * that pair only when it clears the tax; otherwise it keeps the engine's honest
 * no-margin answer, because a fabricated margin is worse than no margin.
 */
public class DeadSpreadTargetsTest
{
	private static final int RUBY = 1603;
	private static final long NOW = 1_700_000_000L;

	/** The live book from the report: 767 / 779, which the tax eats whole. */
	private static final long LIVE_LOW = 767;
	private static final long LIVE_HIGH = 779;

	@Test
	public void theLiveRubySpreadGenuinelyCannotBeatTheTax()
	{
		final long tax = FlipTracker.taxPerItem(LIVE_HIGH, RUBY);
		Assert.assertEquals("2% of 779, floored", 15, tax);
		Assert.assertTrue("crossing the live spread loses money",
			LIVE_HIGH - tax - LIVE_LOW < 0);
	}

	/**
	 * The shape that actually produces this, which took two wrong fixtures to
	 * find.
	 *
	 * The engine's window is LIQUIDITY-SIZED. It walks newest to oldest and
	 * stops once it has TARGET_TRADES (2,000) with at least MIN_AGE (one hour)
	 * and eight usable buckets. Ruby trades 2.57M a day — roughly nine
	 * thousand a five-minute bucket — so two thousand trades is one bucket,
	 * and the window closes at the one-hour floor. The engine only ever sees
	 * the LAST HOUR.
	 *
	 * swingTargets reads the whole series. That is the entire difference, and
	 * it is why the website could show 788 while the plugin showed 779 with
	 * both running the same engine on the same market: an hour of flat book
	 * over a day that ranged.
	 *
	 * So: twelve recent buckets pinned at the live quote with an 8gp spread
	 * the 15gp tax eats whole, over a session that ranged from the mid-740s
	 * to the high 780s. Volume high enough that the engine's window really
	 * does stop at the hour.
	 *
	 * The two fixtures that failed first are worth recording, because both
	 * looked right: one gave every bucket a 22gp spread (the tax leaves 7, so
	 * the engine was viable and the test measured nothing), and one oscillated
	 * the whole day with a thin spread (the engine's own window still caught
	 * the range, because an hour of it was enough).
	 */
	private static TradeEngine.Series dayWithRange()
	{
		final int n = 120;                 // ten hours of 5m buckets
		final int flatTail = 12;           // the last hour, which is all the engine sees
		final TradeEngine.Series s = new TradeEngine.Series();
		s.labels = new long[n];
		s.low = new double[n];
		s.high = new double[n];
		s.lowVol = new double[n];
		s.highVol = new double[n];
		for (int i = 0; i < n; i++)
		{
			s.labels[i] = NOW - (long) (n - 1 - i) * 300L;
			if (i >= n - flatTail)
			{
				s.low[i] = LIVE_LOW;       // 767
				s.high[i] = LIVE_HIGH;     // 779 — 12 apart, tax is 15
			}
			else
			{
				final double swing = Math.sin(i / 9.0) * 20;
				s.low[i] = 763 + swing;
				s.high[i] = 775 + swing;
			}
			s.lowVol[i] = 4500;
			s.highVol[i] = 4500;
		}
		return s;
	}

	/**
	 * The engine, looking only at the last hour, correctly finds nothing —
	 * and its answer is the live quote, which is how the traded price ends up
	 * on the card presented as a target.
	 */
	@Test
	public void theEngineAloneSeesOnlyTheDeadHourAndQuotesTheLiveQuote()
	{
		final TradeEngine.Result engine =
			TradeEngine.compute(LIVE_LOW, LIVE_HIGH, NOW, NOW, dayWithRange(), RUBY);
		Assert.assertNotNull(engine);
		final long tax = FlipTracker.taxPerItem(engine.sell, RUBY);
		Assert.assertTrue("the engine's own pair does not clear the tax"
				+ " (buy " + engine.buy + ", sell " + engine.sell + ", tax " + tax + ")",
			engine.sell - engine.buy - tax <= 0);
		Assert.assertEquals("and its ask IS the traded price — the reported bug",
			LIVE_HIGH, engine.sell);
	}

	/**
	 * And the day it could not see really did have a range, or the fallback
	 * would have nothing to find and the test above would be the whole story.
	 */
	@Test
	public void theDayItCannotSeeHasARealRange()
	{
		final long[] day = TradeEngine.swingTargets(dayWithRange());
		Assert.assertNotNull("the whole session ranged", day);
		Assert.assertTrue("wide enough to clear the tax",
			day[1] - day[0] - FlipTracker.taxPerItem(day[1], RUBY) > 0);
	}

	/**
	 * The fix. viewTargets is the port of the website's own wrapper, and on
	 * this book it must produce a pair that actually makes money — and an ask
	 * ABOVE the traded price, not equal to it.
	 */
	@Test
	public void viewTargetsAnchorsToTheDayWhenTheSpreadIsDead()
	{
		final TradeEngine.Result t =
			TradeEngine.viewTargets(LIVE_LOW, LIVE_HIGH, NOW, NOW, dayWithRange(), RUBY);
		Assert.assertNotNull(t);
		Assert.assertTrue("it found a workable pair", t.viable);
		Assert.assertTrue("the ask is above the traded price, not equal to it — this is the bug",
			t.sell > LIVE_HIGH);
		Assert.assertTrue("and the bid is below the traded price", t.buy < LIVE_LOW);
		Assert.assertTrue("and the pair clears the tax",
			t.sell - t.buy - FlipTracker.taxPerItem(t.sell, RUBY) > 0);
	}

	/**
	 * The day is the site's day: the newest 24 hours, not the whole 5m
	 * response, which runs to about 30. Reported as the site and the plugin
	 * bidding 355 and 361 for the same Aether catalyst — a 7 gp spread on a
	 * 7 gp tax, so exactly this fallback — and on identical inputs the extra
	 * six hours moved this pair 1-3 gp in a third of cases.
	 */
	@Test
	public void theDayIsTheNewestTwentyFourHours()
	{
		final int n = 365;                 // what /timeseries?timestep=5m returns
		final TradeEngine.Series s = new TradeEngine.Series();
		s.labels = new long[n];
		s.low = new double[n];
		s.high = new double[n];
		s.lowVol = new double[n];
		s.highVol = new double[n];
		final TradeEngine.Series day = dayWithRange();
		final int dayStart = n - day.labels.length;
		for (int i = 0; i < n; i++)
		{
			s.labels[i] = NOW - (long) (n - 1 - i) * 300L;
			s.lowVol[i] = 4500;
			s.highVol[i] = 4500;
			if (i >= dayStart)
			{
				s.low[i] = day.low[i - dayStart];
				s.high[i] = day.high[i - dayStart];
			}
			else
			{
				// Yesterday, higher: in the response, outside the site's day.
				s.low[i] = i < 76 ? 820 : 763;
				s.high[i] = i < 76 ? 835 : 775;
			}
		}
		final TradeEngine.Series lastDay = TradeEngine.lastDay(s);
		Assert.assertEquals("24h of 5m buckets, both ends included", 289, lastDay.labels.length);
		Assert.assertNotEquals("the older hours do move the day's levels, so this tests something",
			java.util.Arrays.toString(TradeEngine.swingTargets(s)),
			java.util.Arrays.toString(TradeEngine.swingTargets(lastDay)));

		final TradeEngine.Result whole = TradeEngine.viewTargets(LIVE_LOW, LIVE_HIGH, NOW, NOW, s, RUBY);
		final TradeEngine.Result site = TradeEngine.viewTargets(LIVE_LOW, LIVE_HIGH, NOW, NOW, lastDay, RUBY);
		Assert.assertEquals(site.buy, whole.buy);
		Assert.assertEquals(site.sell, whole.sell);
	}

	/**
	 * The guard that stops this becoming wishful thinking: a genuinely flat
	 * item has no day range to fall back on, and must keep the engine's
	 * no-margin answer rather than being handed an invented one.
	 */
	@Test
	public void aTrulyFlatItemKeepsTheHonestNoMarginAnswer()
	{
		final int n = 120;
		final TradeEngine.Series flat = new TradeEngine.Series();
		flat.labels = new long[n];
		flat.low = new double[n];
		flat.high = new double[n];
		flat.lowVol = new double[n];
		flat.highVol = new double[n];
		for (int i = 0; i < n; i++)
		{
			flat.labels[i] = NOW - (long) (n - 1 - i) * 300L;
			flat.low[i] = 767;
			flat.high[i] = 779;
			flat.lowVol[i] = 400;
			flat.highVol[i] = 400;
		}

		final TradeEngine.Result t =
			TradeEngine.viewTargets(LIVE_LOW, LIVE_HIGH, NOW, NOW, flat, RUBY);
		Assert.assertNotNull(t);
		Assert.assertFalse("no day range, so no invented margin", t.viable);
	}

	/**
	 * And when the live spread IS alive, nothing changes at all — viewTargets
	 * has to be a pure extension, or every price in the plugin moves.
	 */
	@Test
	public void aLiveSpreadIsLeftExactlyAsTheEngineFoundIt()
	{
		final int n = 120;
		final TradeEngine.Series wide = new TradeEngine.Series();
		wide.labels = new long[n];
		wide.low = new double[n];
		wide.high = new double[n];
		wide.lowVol = new double[n];
		wide.highVol = new double[n];
		for (int i = 0; i < n; i++)
		{
			wide.labels[i] = NOW - (long) (n - 1 - i) * 300L;
			wide.low[i] = 1900 + Math.sin(i / 9.0) * 15;
			wide.high[i] = 2000 + Math.sin(i / 9.0) * 15;
			wide.lowVol[i] = 400;
			wide.highVol[i] = 400;
		}

		final TradeEngine.Result engine = TradeEngine.compute(1900, 2000, NOW, NOW, wide, 1601);
		final TradeEngine.Result view = TradeEngine.viewTargets(1900, 2000, NOW, NOW, wide, 1601);
		Assert.assertNotNull(view);
		Assert.assertTrue("this fixture has to be viable for the test to mean anything",
			engine.viable);
		Assert.assertEquals("same buy", engine.buy, view.buy);
		Assert.assertEquals("same sell", engine.sell, view.sell);
	}

	@Test
	public void aSeriesTooSparseToTrustYieldsNoDayPair()
	{
		Assert.assertNull("fewer than 8 prints a side", TradeEngine.swingTargets(null));
		final TradeEngine.Series thin = new TradeEngine.Series();
		thin.labels = new long[]{NOW - 600, NOW - 300, NOW};
		thin.low = new double[]{760, 761, 762};
		thin.high = new double[]{790, 791, 792};
		thin.lowVol = new double[]{1, 1, 1};
		thin.highVol = new double[]{1, 1, 1};
		Assert.assertNull(TradeEngine.swingTargets(thin));
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * How many 5-day extremes requests one advisor cycle may send.
 *
 * Each item is due an hour after its last fetch. Fifteen a cycle covers any
 * list within the hour on the short intervals, but on a two- or eight-hour
 * interval fifteen a cycle meant the same fifteen items every time and the
 * rest of the list never — so the cap has to grow with the interval.
 */
public class ExtremesPacingTest
{
	private static final long MIN = 60_000;

	@Test
	public void fifteenOnTheShortIntervals()
	{
		Assert.assertEquals(15, PocketGeTrackerPlugin.extremesPerCycle(100, MIN));
		Assert.assertEquals(15, PocketGeTrackerPlugin.extremesPerCycle(100, 5 * MIN));
	}

	@Test
	public void neverMoreThanTheListHolds()
	{
		Assert.assertEquals(4, PocketGeTrackerPlugin.extremesPerCycle(4, 5 * MIN));
		Assert.assertEquals(0, PocketGeTrackerPlugin.extremesPerCycle(0, 8 * 60 * MIN));
	}

	/** Thirty minutes: half the list a cycle, so all of it each hour. */
	@Test
	public void halfTheListOnHalfHourCycles()
	{
		Assert.assertEquals(50, PocketGeTrackerPlugin.extremesPerCycle(100, 30 * MIN));
	}

	/** An interval longer than the hour has to cover the whole list each
	 *  time, which is what the old single-timer pass always sent. */
	@Test
	public void theWholeListOnLongIntervals()
	{
		Assert.assertEquals(100, PocketGeTrackerPlugin.extremesPerCycle(100, 2 * 60 * MIN));
		Assert.assertEquals(100, PocketGeTrackerPlugin.extremesPerCycle(100, 8 * 60 * MIN));
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * Order sync between the in-game watchlist and the same list open on
 * pocketge.com. Both ends can edit at once, so every test here is really
 * asking the same question: can a reorder arriving from a browser that is
 * one poll behind ever lose a favorite?
 */
public class FavoriteListsTest
{
	private static FavoriteLists.FavoriteList list(int... ids)
	{
		FavoriteLists.FavoriteList l = new FavoriteLists.FavoriteList("id", "Favorites", "#E5C158");
		l.items = new ArrayList<>();
		for (int id : ids)
		{
			FavoriteLists.addItem(l, id, "Item " + id);
		}
		return l;
	}

	private static List<Integer> ids(FavoriteLists.FavoriteList l)
	{
		List<Integer> out = new ArrayList<>();
		for (Favorites.Fav f : l.items)
		{
			out.add(f.id);
		}
		return out;
	}

	@Test
	public void reorderTo_appliesTheGivenOrder()
	{
		FavoriteLists.FavoriteList l = list(1, 2, 3, 4);
		FavoriteLists.reorderTo(l, Arrays.asList(4, 2, 1, 3));
		Assert.assertEquals(Arrays.asList(4, 2, 1, 3), ids(l));
	}

	@Test
	public void reorderTo_keepsItemsTheCallerNeverMentioned()
	{
		// The browser is a poll behind and doesn't know about item 9 yet.
		// Dropping it would silently delete a favorite the player just
		// starred in game.
		FavoriteLists.FavoriteList l = list(1, 2, 9);
		FavoriteLists.reorderTo(l, Arrays.asList(2, 1));
		Assert.assertEquals(Arrays.asList(2, 1, 9), ids(l));
	}

	@Test
	public void reorderTo_ignoresItemsThatAreNoLongerOnTheList()
	{
		// The mirror case: the browser still shows item 7, which was
		// unfavorited in game a moment ago. It must not come back.
		FavoriteLists.FavoriteList l = list(1, 2);
		FavoriteLists.reorderTo(l, Arrays.asList(7, 2, 1));
		Assert.assertEquals(Arrays.asList(2, 1), ids(l));
	}

	@Test
	public void reorderTo_neverChangesMembership()
	{
		FavoriteLists.FavoriteList l = list(1, 2, 3);
		FavoriteLists.reorderTo(l, Arrays.asList(3, 99, 1));
		Assert.assertEquals("membership must be untouched by a reorder", 3, l.items.size());
		Assert.assertTrue(FavoriteLists.contains(l, 1));
		Assert.assertTrue(FavoriteLists.contains(l, 2));
		Assert.assertTrue(FavoriteLists.contains(l, 3));
		Assert.assertFalse(FavoriteLists.contains(l, 99));
	}

	@Test
	public void reorderTo_honoursADuplicatedIdOnce()
	{
		FavoriteLists.FavoriteList l = list(1, 2, 3);
		FavoriteLists.reorderTo(l, Arrays.asList(2, 2, 1));
		Assert.assertEquals(Arrays.asList(2, 1, 3), ids(l));
	}

	@Test
	public void reorderTo_nullAndEmptyAreNoOps()
	{
		FavoriteLists.FavoriteList l = list(1, 2, 3);
		FavoriteLists.reorderTo(l, null);
		Assert.assertEquals(Arrays.asList(1, 2, 3), ids(l));
		FavoriteLists.reorderTo(l, new ArrayList<>());
		Assert.assertEquals(Arrays.asList(1, 2, 3), ids(l));
		FavoriteLists.reorderTo(null, Arrays.asList(1));
	}

	@Test
	public void reorderTo_survivesANullIdInTheList()
	{
		// Gson will hand us a null for `[1, null, 2]` rather than refusing it.
		FavoriteLists.FavoriteList l = list(1, 2, 3);
		FavoriteLists.reorderTo(l, Arrays.asList(3, null, 1));
		Assert.assertEquals(Arrays.asList(3, 1, 2), ids(l));
	}

	@Test
	public void reorderTo_roundTripsThroughDragOrdering()
	{
		/* The in-game drag and the website reorder must agree on what
		   "position 0" means, or a drag in one place would visibly jump
		   somewhere else in the other. */
		FavoriteLists.FavoriteList l = list(1, 2, 3, 4);
		FavoriteLists.moveItemToIndex(l, 4, 0);
		final List<Integer> afterDrag = ids(l);
		Assert.assertEquals(Arrays.asList(4, 1, 2, 3), afterDrag);

		FavoriteLists.FavoriteList mirror = list(1, 2, 3, 4);
		FavoriteLists.reorderTo(mirror, afterDrag);
		Assert.assertEquals(afterDrag, ids(mirror));
	}
}

package com.pocketge.tracker;

import java.util.HashMap;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * "Filling, so priced fine" only for fills the plugin watched happen.
 *
 * A 317 bid that filled overnight, under a market that had since moved to
 * 341, read "Priced fine — leave it" for the first ten minutes after login:
 * units found already bought were taken as "filling now".
 */
public class FillGraceTest
{
	private static final long MIN = 60_000L;

	private static Object get(Object o, String field) throws Exception
	{
		final java.lang.reflect.Field f = o.getClass().getDeclaredField(field);
		f.setAccessible(true);
		return f.get(o);
	}

	@Test
	public void unitsFoundAlreadyBoughtAreNotAFillNow()
	{
		final Map<Integer, long[]> progress = new HashMap<>();
		Assert.assertFalse("first look, 7,950 already bought",
			PocketGeTrackerPlugin.filledRecently(progress, 0, 7_950, 1_000 * MIN));
		Assert.assertFalse("and still nothing new a minute later",
			PocketGeTrackerPlugin.filledRecently(progress, 0, 7_950, 1_001 * MIN));
	}

	@Test
	public void aFillWatchedHappeningQuietsTheNagForTenMinutes()
	{
		final Map<Integer, long[]> progress = new HashMap<>();
		PocketGeTrackerPlugin.filledRecently(progress, 0, 7_950, 1_000 * MIN);
		PocketGeTrackerPlugin.noteFill(progress, 0, 8_100, 1_002 * MIN); // the GE's fill event
		Assert.assertTrue(PocketGeTrackerPlugin.filledRecently(progress, 0, 8_100, 1_002 * MIN));
		Assert.assertTrue(PocketGeTrackerPlugin.filledRecently(progress, 0, 8_100, 1_011 * MIN));
		Assert.assertFalse("stalled since", PocketGeTrackerPlugin.filledRecently(progress, 0, 8_100, 1_013 * MIN));
	}

	/**
	 * Growth a pass finds with no fill event behind it is not dated. With
	 * the advisor off for 45 minutes, a sell that sold on and then stalled
	 * under the market read "Priced fine" for ten minutes after it came back
	 * on: the pass took the whole gap's fills as "now".
	 */
	@Test
	public void growthFoundAfterAGapIsNotAFillNow()
	{
		final Map<Integer, long[]> progress = new HashMap<>();
		PocketGeTrackerPlugin.filledRecently(progress, 3, 2_500, 1_000 * MIN);
		Assert.assertFalse(PocketGeTrackerPlugin.filledRecently(progress, 3, 4_000, 1_045 * MIN));
	}

	/** A first event is only recorded: a collect fires one too. */
	@Test
	public void aFirstEventIsOnlyRecorded()
	{
		final Map<Integer, long[]> progress = new HashMap<>();
		PocketGeTrackerPlugin.noteFill(progress, 0, 7_950, 1_000 * MIN);
		Assert.assertFalse(PocketGeTrackerPlugin.filledRecently(progress, 0, 7_950, 1_000 * MIN));
	}

	/**
	 * Fills watched while the box was grey count. They were only sampled
	 * once a slot was flagged, so the first flag on a sell filling steadily
	 * found no record and told it to re-list lower.
	 */
	@Test
	@SuppressWarnings("unchecked")
	public void fillsWatchedWhileGreyQuietTheFirstFlag() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		final java.lang.reflect.Method build = PocketGeTrackerPlugin.class.getDeclaredMethod("buildSlotViews",
			java.util.List.class, Map.class, Map.class, Map.class, Map.class);
		build.setAccessible(true);
		final Advisor.OfferView o = new Advisor.OfferView();
		o.slot = 3;
		o.itemId = 1601;
		o.itemName = "Diamond";
		o.buy = false;
		o.price = 972;
		o.totalQuantity = 11_000;
		o.active = true;
		final Map<Integer, Boolean> grey = new HashMap<>();
		grey.put(3, true);
		final Map<Integer, long[]> progress = (Map<Integer, long[]>) get(plugin, "slotProgress");
		long t = System.currentTimeMillis() - 3 * MIN;
		for (int sold : new int[]{2_500, 2_600, 2_767})
		{
			o.quantitySold = sold;
			PocketGeTrackerPlugin.noteFill(progress, 3, sold, t += MIN); // each fill's GE event
			build.invoke(plugin, java.util.List.of(o), grey, new HashMap<>(), new HashMap<>(), new HashMap<>());
		}
		final Map<Integer, Boolean> flagged = new HashMap<>();
		flagged.put(3, false);
		final Advisor.Suggestion adj = new Advisor.Suggestion(Advisor.Suggestion.Type.ADJUST_SELL, 1601, "Diamond", 955, 8_233, 0, "");
		adj.slot = 3;
		final Map<Integer, Advisor.Suggestion> bySlot = new HashMap<>();
		bySlot.put(3, adj);
		final Map<Integer, GeOfferGridOverlay.SlotView> views = (Map<Integer, GeOfferGridOverlay.SlotView>)
			build.invoke(plugin, java.util.List.of(o), flagged, new HashMap<>(), bySlot, new HashMap<>());
		Assert.assertFalse("it was seen filling a moment ago: leave it", views.get(3).needsAdjust);
	}

	/** A Leagues world's offers are not the tracker's to book, but a fill
	 *  there is still a fill: the grace is dated on every world. */
	@Test
	public void fillsAreDatedOnSeparateExchangeWorldsToo() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		final int[] sold = {2_500};
		final java.lang.reflect.Field c = PocketGeTrackerPlugin.class.getDeclaredField("client");
		c.setAccessible(true);
		c.set(plugin, java.lang.reflect.Proxy.newProxyInstance(net.runelite.api.Client.class.getClassLoader(),
			new Class<?>[]{net.runelite.api.Client.class}, (p, m, a) ->
			{
				switch (m.getName())
				{
					case "getGameState": return net.runelite.api.GameState.LOGGED_IN;
					case "getAccountHash": return 123L;
					case "getTickCount": return 100;
					case "getWorldType": return java.util.EnumSet.of(net.runelite.api.WorldType.SEASONAL);
					default:
						final Class<?> r = m.getReturnType();
						return r == boolean.class ? (Object) false : r.isPrimitive() ? (r == long.class ? (Object) 0L : (Object) 0) : null;
				}
			}));
		final java.lang.reflect.Field settled = PocketGeTrackerPlugin.class.getDeclaredField("geSettledTick");
		settled.setAccessible(true);
		settled.set(plugin, 0);
		final net.runelite.api.GrandExchangeOffer offer = (net.runelite.api.GrandExchangeOffer) java.lang.reflect.Proxy.newProxyInstance(
			net.runelite.api.GrandExchangeOffer.class.getClassLoader(), new Class<?>[]{net.runelite.api.GrandExchangeOffer.class},
			(p, m, a) -> m.getName().equals("getState") ? net.runelite.api.GrandExchangeOfferState.SELLING
				: m.getName().equals("getQuantitySold") ? (Object) sold[0]
				: m.getReturnType() == long.class ? (Object) 0L : m.getReturnType().isPrimitive() ? (Object) 0 : null);
		final net.runelite.api.events.GrandExchangeOfferChanged e = new net.runelite.api.events.GrandExchangeOfferChanged();
		e.setSlot(3);
		e.setOffer(offer);
		plugin.onGrandExchangeOfferChanged(e);
		sold[0] = 2_600;
		plugin.onGrandExchangeOfferChanged(e);
		@SuppressWarnings("unchecked")
		final Map<Integer, long[]> progress = (Map<Integer, long[]>) get(plugin, "slotProgress");
		Assert.assertTrue("the second event dated a fill", progress.get(3)[1] > 0);
	}

	/** Logging out forgets the clock, so the next login is a first look. */
	@Test
	public void aLogoutForgetsTheClock() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		final java.lang.reflect.Field c = PocketGeTrackerPlugin.class.getDeclaredField("client");
		c.setAccessible(true);
		c.set(plugin, java.lang.reflect.Proxy.newProxyInstance(net.runelite.api.Client.class.getClassLoader(),
			new Class<?>[]{net.runelite.api.Client.class}, (p, m, a) ->
			{
				final Class<?> r = m.getReturnType();
				return m.getName().equals("getGameState") ? net.runelite.api.GameState.LOGIN_SCREEN
					: r == boolean.class ? (Object) false : r.isPrimitive() ? (r == long.class ? (Object) 0L : (Object) 0) : null;
			}));
		final java.lang.reflect.Field f = PocketGeTrackerPlugin.class.getDeclaredField("slotProgress");
		f.setAccessible(true);
		@SuppressWarnings("unchecked")
		final Map<Integer, long[]> progress = (Map<Integer, long[]>) f.get(plugin);
		progress.put(0, new long[]{100, System.currentTimeMillis()});
		final net.runelite.api.events.GameStateChanged logout = new net.runelite.api.events.GameStateChanged();
		logout.setGameState(net.runelite.api.GameState.LOGIN_SCREEN);
		plugin.onGameStateChanged(logout);
		Assert.assertTrue(progress.isEmpty());
	}
}

package com.pocketge.tracker;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class FinderEngineTest
{
	private static Advisor.Quote quote(long high, long low)
	{
		Advisor.Quote q = new Advisor.Quote();
		q.high = high;
		q.low = low;
		return q;
	}

	private static AnalystRating.Average avg(long avgHigh, long avgLow, long hiVol, long loVol)
	{
		AnalystRating.Average a = new AnalystRating.Average();
		a.avgHighPrice = avgHigh;
		a.avgLowPrice = avgLow;
		a.highPriceVolume = hiVol;
		a.lowPriceVolume = loVol;
		return a;
	}

	@Test
	public void marginRows_splitsByVolumeTier()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1, quote(1100, 1000)); // margin ~78 after tax, high vol
		quotes.put(2, quote(2200, 2000)); // margin ~156 after tax, low vol
		Map<Integer, AnalystRating.Average> averages = new HashMap<>();
		averages.put(1, avg(1050, 1050, 10, 10));
		averages.put(2, avg(2100, 2100, 10, 10));
		Map<Integer, Long> volumes = new HashMap<>();
		volumes.put(1, 500_000L);  // high vol
		volumes.put(2, 5_000L);    // low vol

		List<FinderEngine.Row> highVol = FinderEngine.marginRows(quotes, averages, volumes, false);
		Assert.assertEquals(1, highVol.size());
		Assert.assertEquals(1, highVol.get(0).id);
		Assert.assertTrue(highVol.get(0).margin > 0);

		List<FinderEngine.Row> lowVol = FinderEngine.marginRows(quotes, averages, volumes, true);
		Assert.assertEquals(1, lowVol.size());
		Assert.assertEquals(2, lowVol.get(0).id);
	}

	@Test
	public void marginRows_requiresBothSidesRecentlyTraded()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1, quote(1100, 1000));
		Map<Integer, AnalystRating.Average> averages = new HashMap<>();
		averages.put(1, avg(1050, 1050, 0, 10)); // no high-side prints in the last 24h
		Map<Integer, Long> volumes = new HashMap<>();
		volumes.put(1, 500_000L);

		Assert.assertTrue(FinderEngine.marginRows(quotes, averages, volumes, false).isEmpty());
	}

	@Test
	public void loserRows_flagsAtLeastThreePercentDrop()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1, quote(970, 950));  // mid 960, down from avg mid 1000 -> -4%
		quotes.put(2, quote(995, 985));  // mid 990, down from avg mid 1000 -> -1%, shouldn't qualify
		Map<Integer, AnalystRating.Average> averages = new HashMap<>();
		averages.put(1, avg(1010, 990, 200_000, 200_000));
		averages.put(2, avg(1010, 990, 200_000, 200_000));
		Map<Integer, Long> volumes = new HashMap<>();
		volumes.put(1, 300_000L);
		volumes.put(2, 300_000L);

		List<FinderEngine.Row> out = FinderEngine.loserRows(quotes, averages, volumes);
		Assert.assertEquals(1, out.size());
		Assert.assertEquals(1, out.get(0).id);
		Assert.assertTrue(out.get(0).pct < -3);
	}

	@Test
	public void loserRows_ignoresThinVolume()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1, quote(970, 950));
		Map<Integer, AnalystRating.Average> averages = new HashMap<>();
		averages.put(1, avg(1010, 990, 500, 500)); // well under the 100k volume floor
		Map<Integer, Long> volumes = new HashMap<>();
		volumes.put(1, 1_000L);

		Assert.assertTrue(FinderEngine.loserRows(quotes, averages, volumes).isEmpty());
	}

	private static PriceExtremes extremes(long hi5d, long lo5d)
	{
		PriceExtremes ex = new PriceExtremes();
		ex.hi5d = hi5d;
		ex.lo5d = lo5d;
		return ex;
	}

	@Test
	public void extremeHighRows_flagsWithinBandOfFiveDayHigh()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1, quote(995, 985));  // high 995, 5D range 900-1000 -> 5% below the high, qualifies
		quotes.put(2, quote(950, 935));  // high 950, 5D range 900-1000 -> 50% below the high, doesn't qualify
		Map<Integer, PriceExtremes> ex = new HashMap<>();
		ex.put(1, extremes(1000, 900));
		ex.put(2, extremes(1000, 900));
		Map<Integer, Long> volumes = new HashMap<>();
		volumes.put(1, 200_000L);
		volumes.put(2, 200_000L);

		List<FinderEngine.Row> out = FinderEngine.extremeHighRows(quotes, ex, volumes);
		Assert.assertEquals(1, out.size());
		Assert.assertEquals(1, out.get(0).id);
		Assert.assertTrue(out.get(0).pct < 8);
	}

	@Test
	public void extremeLowRows_flagsWithinBandOfFiveDayLow()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1, quote(915, 905));  // low 905, 5D range 900-1000 -> 0.5% above the low, qualifies
		quotes.put(2, quote(960, 950));  // low 950, 5D range 900-1000 -> 50% above the low, doesn't qualify
		Map<Integer, PriceExtremes> ex = new HashMap<>();
		ex.put(1, extremes(1000, 900));
		ex.put(2, extremes(1000, 900));
		Map<Integer, Long> volumes = new HashMap<>();
		volumes.put(1, 200_000L);
		volumes.put(2, 200_000L);

		List<FinderEngine.Row> out = FinderEngine.extremeLowRows(quotes, ex, volumes);
		Assert.assertEquals(1, out.size());
		Assert.assertEquals(1, out.get(0).id);
	}

	@Test
	public void extremeRows_ignoreNearFlatItems()
	{
		// 5D range is only ~1% of the low — below EXTREME_MIN_RANGE_PCT, so
		// even a live price sitting exactly on the high shouldn't qualify.
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1, quote(1005, 1000));
		Map<Integer, PriceExtremes> ex = new HashMap<>();
		ex.put(1, extremes(1010, 1000));
		Map<Integer, Long> volumes = new HashMap<>();
		volumes.put(1, 200_000L);

		Assert.assertTrue(FinderEngine.extremeHighRows(quotes, ex, volumes).isEmpty());
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * The ledger is the only copy of history older than the 500-flip config
 * window, so what is tested here is durability rather than formatting: that a
 * crash costs one row, that a foreign file cannot be mistaken for history,
 * and that a ledger which cannot be written fails quietly instead of taking
 * the tracker down with it.
 */
public class FlipLedgerTest
{
	@Rule
	public final TemporaryFolder tmp = new TemporaryFolder();

	private final Gson gson = new Gson();

	private static Flip flip(long closedAt, int itemId, String name, int qty, long spent, long gross)
	{
		return new Flip(closedAt, itemId, name, qty, spent, gross, gross / 50);
	}

	private FlipLedger ledger() throws IOException
	{
		return new FlipLedger(new File(tmp.newFolder("led"), "flips.jsonl"), gson);
	}

	@Test
	public void appendsAndReadsBackEveryField() throws Exception
	{
		final FlipLedger l = ledger();
		Assert.assertTrue(l.append(flip(1_000L, 1592, "Sapphire necklace", 18000, 20_160_000L, 21_600_000L)));

		final List<Flip> back = l.readAll();
		Assert.assertEquals(1, back.size());
		final Flip f = back.get(0);
		Assert.assertEquals(1_000L, f.closedAt);
		Assert.assertEquals(1592, f.itemId);
		Assert.assertEquals("Sapphire necklace", f.itemName);
		Assert.assertEquals(18000, f.quantity);
		Assert.assertEquals(20_160_000L, f.buySpent);
		Assert.assertEquals(21_600_000L, f.sellGross);
		Assert.assertEquals(21_600_000L / 50, f.tax);
		Assert.assertEquals(21_600_000L - (21_600_000L / 50) - 20_160_000L, f.profit);
	}

	/** The whole point of the file: it keeps growing past the config cap. */
	@Test
	public void growsWellBeyondTheFiveHundredFlipConfigWindow() throws Exception
	{
		final FlipLedger l = ledger();
		for (int i = 0; i < 1200; i++)
		{
			l.append(flip(i, 100 + i, "Item " + i, 1, 10, 20));
		}
		Assert.assertEquals(1200, l.readAll().size());
		Assert.assertEquals(1200, l.count());
	}

	/** Appends accumulate across separate opens — a client restart is just a
	 *  new FlipLedger over the same file. */
	@Test
	public void survivesReopening() throws Exception
	{
		final File f = new File(tmp.newFolder("reopen"), "flips.jsonl");
		new FlipLedger(f, gson).append(flip(1, 10, "A", 1, 1, 2));
		new FlipLedger(f, gson).append(flip(2, 11, "B", 1, 1, 2));
		Assert.assertEquals(2, new FlipLedger(f, gson).readAll().size());
	}

	@Test
	public void readsOldestFirstEvenWhenAppendedOutOfOrder() throws Exception
	{
		final FlipLedger l = ledger();
		l.append(flip(300, 3, "C", 1, 1, 2));
		l.append(flip(100, 1, "A", 1, 1, 2));
		l.append(flip(200, 2, "B", 1, 1, 2));

		final List<Flip> back = l.readAll();
		Assert.assertEquals(100L, back.get(0).closedAt);
		Assert.assertEquals(200L, back.get(1).closedAt);
		Assert.assertEquals(300L, back.get(2).closedAt);
	}

	/** A client killed mid-append leaves a half-written final line. It must
	 *  cost that one flip and nothing else. */
	@Test
	public void aTornFinalLineCostsOneFlipNotTheHistory() throws Exception
	{
		final File file = new File(tmp.newFolder("torn"), "flips.jsonl");
		final FlipLedger l = new FlipLedger(file, gson);
		for (int i = 0; i < 10; i++)
		{
			l.append(flip(i, 100 + i, "Item " + i, 1, 10, 20));
		}
		Files.write(file.toPath(), "{\"closedAt\":99,\"itemId\":9".getBytes(StandardCharsets.UTF_8),
			StandardOpenOption.APPEND);

		Assert.assertEquals(10, l.readAll().size());
		// ...and the count agrees, so the site is never told to expect a row
		// that readAll will not hand over.
		Assert.assertEquals(10, l.count());
	}

	/** ...and writing continues correctly afterwards. */
	@Test
	public void appendingAfterATornLineDoesNotGlueTheLinesTogether() throws Exception
	{
		final File file = new File(tmp.newFolder("torn2"), "flips.jsonl");
		final FlipLedger l = new FlipLedger(file, gson);
		l.append(flip(1, 10, "A", 1, 1, 2));
		Files.write(file.toPath(), "{\"closedAt\":2,\"itemI".getBytes(StandardCharsets.UTF_8),
			StandardOpenOption.APPEND);
		l.append(flip(3, 12, "C", 1, 1, 2));

		final List<Flip> back = l.readAll();
		// The torn line swallows the next append's opening brace, so that one
		// is lost too — but only that one, and the history around it reads.
		Assert.assertTrue(back.size() >= 1);
		Assert.assertEquals(10, back.get(0).itemId);
	}

	@Test
	public void ignoresBlankAndForeignLines() throws Exception
	{
		final File file = new File(tmp.newFolder("junk"), "flips.jsonl");
		Files.write(file.toPath(), String.join("\n",
			"",
			"not json at all",
			"[1,2,3]",
			"{\"unrelated\":true}",
			gson.toJson(flip(5, 55, "Real", 1, 1, 2)),
			"").getBytes(StandardCharsets.UTF_8));

		final List<Flip> back = new FlipLedger(file, gson).readAll();
		Assert.assertEquals(1, back.size());
		Assert.assertEquals(55, back.get(0).itemId);
	}

	@Test
	public void isEmptyDrivesTheOneTimeSeed() throws Exception
	{
		final FlipLedger l = ledger();
		Assert.assertTrue("a ledger with no file yet is empty", l.isEmpty());

		final List<Flip> existing = new ArrayList<>();
		existing.add(flip(1, 10, "A", 1, 1, 2));
		existing.add(flip(2, 11, "B", 1, 1, 2));
		Assert.assertEquals(2, l.appendAll(existing));

		Assert.assertFalse("seeded once, so it never seeds again", l.isEmpty());
		Assert.assertEquals(2, l.readAll().size());
	}

	@Test
	public void anUnwritableLedgerFailsQuietly() throws Exception
	{
		// A path whose parent is a FILE, so the directory can never be made.
		final File blocker = tmp.newFile("not-a-directory");
		final FlipLedger l = new FlipLedger(new File(blocker, "flips.jsonl"), gson);

		Assert.assertFalse(l.append(flip(1, 10, "A", 1, 1, 2)));
		Assert.assertTrue(l.readAll().isEmpty());
		Assert.assertEquals(0, l.count());
		Assert.assertTrue(l.isEmpty());
	}

	@Test
	public void countMatchesReadAllWithoutParsing() throws Exception
	{
		final FlipLedger l = ledger();
		Assert.assertEquals(0, l.count());
		for (int i = 0; i < 37; i++)
		{
			l.append(flip(i, 100 + i, "Item " + i, 1, 10, 20));
		}
		Assert.assertEquals(37, l.count());
		Assert.assertEquals(l.readAll().size(), l.count());
	}

	/** Item names carry apostrophes and, in RuneScape, the odd non-ASCII
	 *  character — a newline or a broken encoding in one name would split or
	 *  corrupt a row. */
	@Test
	public void namesWithQuotesAndUnicodeSurviveTheRoundTrip() throws Exception
	{
		final FlipLedger l = ledger();
		l.append(flip(1, 10, "Verac's flail", 1, 1, 2));
		l.append(flip(2, 11, "Choc-ice — \"quoted\"", 1, 1, 2));

		final List<Flip> back = l.readAll();
		Assert.assertEquals(2, back.size());
		Assert.assertEquals("Verac's flail", back.get(0).itemName);
		Assert.assertEquals("Choc-ice — \"quoted\"", back.get(1).itemName);
	}

	/** A ledger line written before flips carried a buy time still reads —
	 *  and reports the hold as unknown rather than as instant. */
	@Test
	public void aLineWrittenBeforeHoldTimesStillReads() throws Exception
	{
		final File file = new File(tmp.newFolder("legacy"), "flips.jsonl");
		Files.write(file.toPath(), ("{\"closedAt\":1700000000000,\"itemId\":1601,"
			+ "\"itemName\":\"Diamond\",\"quantity\":100,\"buySpent\":180000,"
			+ "\"sellGross\":204082,\"tax\":4082,\"profit\":20000}\n")
			.getBytes(StandardCharsets.UTF_8));

		final List<Flip> back = new FlipLedger(file, gson).readAll();
		Assert.assertEquals(1, back.size());
		final Flip f = back.get(0);
		Assert.assertEquals(1601, f.itemId);
		Assert.assertEquals(20_000L, f.profit);
		Assert.assertEquals("no buy time in the old shape", 0L, f.openedAt);
		Assert.assertEquals("so the hold reads as nothing", -1L, f.holdMillis());
	}

	/** ...and a line written now carries it through the round trip. */
	@Test
	public void aHoldTimeSurvivesTheLedgerRoundTrip() throws Exception
	{
		final FlipLedger l = ledger();
		final long opened = 1_700_000_000_000L;
		final long closed = opened + 37 * 60_000L;
		l.append(new Flip(opened, closed, 1601, "Diamond", 100, 180_000L, 204_082L, 4_082L));

		final Flip f = l.readAll().get(0);
		Assert.assertEquals(opened, f.openedAt);
		Assert.assertEquals(closed, f.closedAt);
		Assert.assertEquals(37 * 60_000L, f.holdMillis());
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * The flip list under the stats shows the range picked above them: "if you
 * have 1h youd see the flips you made the last 1h. if you have all time,
 * then youd see all the flips youve ever made".
 */
public class FlipRangeTest
{
	private static final long HOUR = 3_600_000L;
	private static final long NOW = 1_000 * HOUR;

	private static Flip flip(long closedAt, long token)
	{
		return new Flip(token, closedAt - 60_000L, closedAt, 1621, "Uncut emerald", 100, 31_700, 33_400, 700);
	}

	private static List<Flip> flips()
	{
		final List<Flip> l = new ArrayList<>();
		l.add(flip(NOW - 40 * 24 * HOUR, 1)); // over a month ago
		l.add(flip(NOW - 3 * HOUR, 2));
		l.add(flip(NOW - 30 * 60_000L, 3));
		l.add(flip(NOW - 5 * 60_000L, 4));
		return l;
	}

	@Test
	public void eachRangeListsItsOwnFlips()
	{
		Assert.assertEquals(2, FlipStats.inRange(flips(), FlipStats.Range.H1, NOW, NOW - 2 * HOUR).size());
		Assert.assertEquals(3, FlipStats.inRange(flips(), FlipStats.Range.H4, NOW, NOW - 2 * HOUR).size());
		Assert.assertEquals("the session started two hours ago",
			2, FlipStats.inRange(flips(), FlipStats.Range.SESSION, NOW, NOW - 2 * HOUR).size());
		Assert.assertEquals("all of them", 4, FlipStats.inRange(flips(), FlipStats.Range.ALL, NOW, NOW - 2 * HOUR).size());
	}

	/** The list and the stats above it count the same flips. */
	@Test
	public void theListAndTheStatsAgree()
	{
		for (FlipStats.Range r : FlipStats.Range.values())
		{
			final List<Flip> all = flips();
			final FlipStats.Stats s = FlipStats.compute(all, r, NOW, NOW - 2 * HOUR, all.get(0).closedAt, 0);
			Assert.assertEquals(r.toString(), s.flipCount, Flip.byTrade(FlipStats.inRange(all, r, NOW, NOW - 2 * HOUR)).size());
		}
	}

	@Test
	public void theCountSaysWhichRange()
	{
		Assert.assertEquals("2 flips in the last hour", HistoryPanel.countText(2, FlipStats.Range.H1));
		Assert.assertEquals("1 flip this session", HistoryPanel.countText(1, FlipStats.Range.SESSION));
		Assert.assertEquals("4 flips recorded", HistoryPanel.countText(4, FlipStats.Range.ALL));
		Assert.assertEquals("No flips in the last 4 hours", HistoryPanel.countText(0, FlipStats.Range.H4));
		Assert.assertEquals("No flips recorded yet", HistoryPanel.countText(0, FlipStats.Range.ALL));
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * The plugin's flip score against the website's.
 *
 * Every expected value here was produced by running pocketge.com's own
 * recScoreParts()/recVerdict() (app.js) in node over the same inputs, not
 * by working the formula out by hand — so this pins the port to the site,
 * not to the porter's understanding of it. The first two rows are real
 * cards from the site: Demon tear at 2.14% edge on 16.38M/day scored 87
 * Prime; Adamant dart tip at 1.09% on 7.19M/day scored 70 Strong.
 */
public class FlipScoreTest
{
	private static void matches(double edgePct, long vol, boolean lowConf,
		double edge, double liq, double penalty, int total, String word, int color)
	{
		final TradeEngine.FlipScore s = TradeEngine.FlipScore.of(edgePct, vol, lowConf);
		Assert.assertEquals(20, s.base, 0);
		Assert.assertEquals("edge part", edge, s.edge, 0.001);
		Assert.assertEquals("liquidity part", liq, s.liq, 0.001);
		Assert.assertEquals("thin-tape penalty", penalty, s.penalty, 0.001);
		Assert.assertEquals("total", total, s.total);
		Assert.assertEquals("verdict", word, s.band.word);
		Assert.assertEquals("band colour", color, s.band.color);
	}

	@Test
	public void demonTearScoresPrime()
	{
		matches(0.0214, 16_380_000, false, 32.1, 35, 0, 87, "Prime Flip", 0xFFFFFF);
	}

	@Test
	public void adamantDartTipScoresStrong()
	{
		matches(0.0109, 7_190_000, false, 16.35, 33.3285, 0, 70, "Strong Flip", 0xFFEFC2);
	}

	@Test
	public void bothTermsMaxedIsAHundred()
	{
		matches(0.03, 10_000_000, false, 45, 35, 0, 100, "Prime Flip", 0xFFFFFF);
		final TradeEngine.FlipScore s = TradeEngine.FlipScore.of(0.03, 10_000_000, false);
		Assert.assertTrue(s.edgeMaxed);
		Assert.assertTrue(s.liqMaxed);
	}

	@Test
	public void edgeSaturatesAtThreePercent()
	{
		/* 11.8% and 3.0% bank the same 45: past the cap the score is all
		   liquidity, which is the thing the tooltip has to be able to say. */
		matches(0.118, 250_000, false, 45, 16.3093, 0, 81, "Strong Flip", 0xFFEFC2);
		Assert.assertEquals(
			TradeEngine.FlipScore.of(0.118, 250_000, false).edge,
			TradeEngine.FlipScore.of(0.03, 250_000, false).edge, 0);
	}

	@Test
	public void thinEdgeOnThinVolumeIsThin()
	{
		matches(0.005, 50_000, false, 7.5, 8.1547, 0, 36, "Thin Flip", 0xFF9F43);
	}

	@Test
	public void thinTapeTakesAFifthOff()
	{
		matches(0.02, 2_000_000, true, 30, 26.8453, 15.3691, 61, "Solid Flip", 0xFFD24D);
	}

	@Test
	public void engineClearedIsWorthTwentyOnItsOwn()
	{
		/* The floor: a viable pair with no edge to speak of and no volume
		   still scores 20, never 0 — the bands never say "don't". */
		matches(0.0, 1, false, 0, 0, 0, 20, "Thin Flip", 0xFF9F43);
		matches(0.015, 0, false, 22.5, 0, 0, 43, "Thin Flip", 0xFF9F43);
	}

	@Test
	public void bandEdgesAreInclusive()
	{
		Assert.assertEquals("Thin Flip", TradeEngine.FlipScore.verdict(54).word);
		Assert.assertEquals("Solid Flip", TradeEngine.FlipScore.verdict(55).word);
		Assert.assertEquals("Strong Flip", TradeEngine.FlipScore.verdict(70).word);
		Assert.assertEquals("Prime Flip", TradeEngine.FlipScore.verdict(85).word);
		Assert.assertEquals("Prime Flip", TradeEngine.FlipScore.verdict(100).word);
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class FlipStatsTest
{
	private static final long NOW = 1_000_000_000_000L; // arbitrary epoch millis

	@Test
	public void windowFiltersOutOlderFlips()
	{
		List<Flip> flips = new ArrayList<>();
		flips.add(new Flip(NOW - 2 * 3_600_000L, 1, "A", 10, 9_000, 10_200, 200));  // 2h ago, profit 1,000
		flips.add(new Flip(NOW - 10L * 24 * 3_600_000L, 2, "B", 10, 40_000, 45_500, 500)); // 10d ago, profit 5,000

		FlipStats.Stats h4 = FlipStats.compute(flips, FlipStats.Range.H4, NOW, NOW - 3_600_000L, NOW - 20L * 24 * 3_600_000L, 0);
		Assert.assertEquals(1, h4.flipCount);
		Assert.assertEquals(1_000L, h4.profit);

		FlipStats.Stats w1 = FlipStats.compute(flips, FlipStats.Range.W1, NOW, NOW - 3_600_000L, NOW - 20L * 24 * 3_600_000L, 0);
		Assert.assertEquals(1, w1.flipCount); // the 10-day-old flip falls outside a 1-week window

		FlipStats.Stats all = FlipStats.compute(flips, FlipStats.Range.ALL, NOW, NOW - 3_600_000L, NOW - 20L * 24 * 3_600_000L, 0);
		Assert.assertEquals(2, all.flipCount);
		Assert.assertEquals(6_000L, all.profit);
	}

	@Test
	public void roiIsProfitOverBuySpent()
	{
		List<Flip> flips = new ArrayList<>();
		flips.add(new Flip(NOW - 3_600_000L, 1, "A", 10, 9_000, 10_200, 200)); // profit 1,000 / spent 9,000
		FlipStats.Stats s = FlipStats.compute(flips, FlipStats.Range.H4, NOW, NOW, NOW, 0);
		Assert.assertEquals(1_000.0 / 9_000 * 100, s.roiPct, 0.0001);
	}

	@Test
	public void emptyWindowNeverDividesByZero()
	{
		FlipStats.Stats s = FlipStats.compute(new ArrayList<>(), FlipStats.Range.H1, NOW, NOW - 3_600_000L, NOW, 0);
		Assert.assertEquals(0.0, s.roiPct, 0.0);
		Assert.assertEquals(0, s.flipCount);
		Assert.assertEquals(0L, s.hourlyRate);
	}

	@Test
	public void unrealizedProfitPassesThroughUnchanged()
	{
		FlipStats.Stats s = FlipStats.compute(new ArrayList<>(), FlipStats.Range.ALL, NOW, NOW, NOW, -12_345L);
		Assert.assertEquals(-12_345L, s.unrealizedProfit);
	}

	@Test
	public void sessionRangeUsesSessionStart()
	{
		List<Flip> flips = new ArrayList<>();
		// one flip just before session start (shouldn't count), one just after (should)
		long sessionStart = NOW - 3_600_000L;
		flips.add(new Flip(sessionStart - 1_000L, 1, "Before", 1, 100, 200, 0));
		flips.add(new Flip(sessionStart + 1_000L, 2, "After", 1, 100, 300, 0));

		FlipStats.Stats s = FlipStats.compute(flips, FlipStats.Range.SESSION, NOW, sessionStart, NOW, 0);
		Assert.assertEquals(1, s.flipCount);
		Assert.assertEquals(200L, s.profit); // 300 - 0 - 100
	}
}

package com.pocketge.tracker;

import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class FlipTrackerTest
{
	/**
	 * This used to assert the opposite — that a half-filled offer seen for the
	 * first time books nothing. That was right while baselines lived only in
	 * memory, because then every login looked like a first sighting and
	 * counting one would have counted the same offer again on every relog.
	 * Baselines persist per character now, so a first sighting is genuinely
	 * the first, and the offer's own quantitySold and spent are exact history
	 * there is no reason to throw away.
	 */
	@Test
	public void aHalfFilledOfferSeenForTheFirstTimeIsCounted()
	{
		FlipTracker t = new FlipTracker();
		TradeFill f = t.onOffer(1L, 0, 1601, "Diamond", true, 500, 1_000_000L, false);
		Assert.assertNotNull(f);
		Assert.assertEquals(500, f.quantity);
		Assert.assertEquals(1_000_000L, f.spent);
	}

	/**
	 * Except straight after upgrading from a version that kept no baselines:
	 * its open lots may already cover part of the offer now sitting in the
	 * slot, so the first sighting after that upgrade baselines as the old
	 * version would have, and only the sighting after it books.
	 */
	@Test
	public void theUpgradeFromAVersionWithoutBaselinesDoesNotDoubleCount()
	{
		FlipTracker old = new FlipTracker();
		old.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, false);
		old.onOffer(2L, 0, 1601, "Diamond", true, 500, 1_000_000L, false);
		Assert.assertEquals(500L, old.getOpenBuyTotals().get(1601)[0]);

		// The state that version wrote carries lots but no slot baselines.
		FlipTracker.State legacy = old.snapshot();
		legacy.slots = null;
		legacy.slotsByAccount = null;
		legacy.accountHash = 0;

		FlipTracker t = new FlipTracker();
		t.restore(legacy);
		t.setAccountHash(9L);
		Assert.assertNull("the offer is still the one those lots came from",
			t.onOffer(3L, 0, 1601, "Diamond", true, 500, 1_000_000L, 2_000L, 1_000, false));
		Assert.assertEquals("not counted twice", 500L, t.getOpenBuyTotals().get(1601)[0]);

		// And it carries on measuring from there.
		/* A bid of 2,000 for fills at 2,000 each. This said 1,800, which the
		   Exchange cannot do — it never charges a buy over its bid — and
		   FlipTracker now refuses to book such a delta. */
		Assert.assertNotNull(t.onOffer(4L, 0, 1601, "Diamond", true, 700, 1_400_000L, 2_000L, 1_000, false));
		Assert.assertEquals(700L, t.getOpenBuyTotals().get(1601)[0]);
	}

	@Test
	public void witnessedGrowthBecomesFill()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, false);          // fresh offer placed
		TradeFill f = t.onOffer(2L, 0, 1601, "Diamond", true, 100, 180_000L, false);
		Assert.assertNotNull(f);
		Assert.assertEquals(100, f.quantity);
		Assert.assertEquals(180_000L, f.spent);
		Assert.assertEquals(1800L, f.unitPrice());
	}

	@Test
	public void fifoFlipProfitAfterTax()
	{
		FlipTracker t = new FlipTracker();
		// buy 100 @ 1,800
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 100, 180_000L, false);
		t.onOffer(3L, 0, 1601, "Diamond", true, 100, 180_000L, true);   // collected
		// sell 100 @ 2,000
		t.onOffer(4L, 1, 1601, "Diamond", false, 0, 0L, false);
		t.onOffer(5L, 1, 1601, "Diamond", false, 100, 200_000L, false);

		List<Flip> flips = t.getFlips();
		Assert.assertEquals(1, flips.size());
		Flip flip = flips.get(0);
		Assert.assertEquals(100, flip.quantity);
		Assert.assertEquals(180_000L, flip.buySpent);
		Assert.assertEquals(200_000L, flip.sellGross);
		// tax: floor(2000/50) = 40 gp/item -> 4,000 total
		Assert.assertEquals(4_000L, flip.tax);
		Assert.assertEquals(16_000L, flip.profit);
		Assert.assertEquals(16_000L, t.getSessionProfit());
	}

	@Test
	public void partialSellMatchesPartialLot()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 100, 180_000L, false);
		t.onOffer(3L, 1, 1601, "Diamond", false, 0, 0L, false);
