	/** A brand-new offer is watched from zero, so its fills are witnessed and
	 *  keep their real times — seeding must not swallow those into "unknown". */
	@Test
	public void aBrandNewOfferStillTimesItsOwnFills()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1_000L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 100, false); // placed, empty
		t.onOffer(2_000L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 100, false);
		t.onOffer(2_500L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 100, true);
		t.onOffer(3_000L, 1, 1601, "Diamond", false, 0, 0L, 2_000L, 100, false);
		t.onOffer(2_000L + 3_600_000L, 1, 1601, "Diamond", false, 100, 200_000L, 2_000L, 100, false);

		Assert.assertEquals(3_600_000L, t.getFlips().get(0).holdMillis());
	}

	/**
	 * A slot we already have a record for, now holding something else, still
	 * baselines rather than books. Replacement is the ambiguous case — part of
	 * the predecessor may already be counted — and only "no record at all" is
	 * unambiguous enough to seed from.
	 */
	@Test
	public void aReplacementIsBaselinedNotSeeded()
	{
		FlipTracker t = new FlipTracker();
		t.setAccountHash(7L);
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 1_000, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 300, 540_000L, 1_800L, 1_000, false);
		Assert.assertEquals(300L, t.getOpenBuyTotals().get(1601)[0]);

		t = restart(t);
		t.setAccountHash(7L);
		// Same item and direction, re-listed higher: a different offer.
		Assert.assertNull(t.onOffer(3L, 0, 1601, "Diamond", true, 800, 1_520_000L, 1_900L, 1_000, false));
		Assert.assertEquals("nothing added by the replacement", 300L, t.getOpenBuyTotals().get(1601)[0]);
	}

	/**
	 * One sell offer, filled by the Exchange in five chunks, is five booked
	 * flips and ONE trade. This is the case off the report: 549 + 2 + 8 +
	 * 7,558 + 15 adamantite bars listed as five rows where it was one sale.
	 */
	@Test
	public void theFillsOfOneOfferShareAnOfferId()
	{
		FlipTracker t = new FlipTracker();
		t.setAccountHash(3L);
		// Buy the stock first, in one go.
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_000L, 8_132, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 8_132, 8_132_000L, 1_000L, 8_132, false);
		t.onOffer(3L, 0, 1601, "Diamond", true, 8_132, 8_132_000L, 1_000L, 8_132, true);

		// One sell offer, filled in five chunks.
		t.onOffer(10L, 1, 1601, "Diamond", false, 0, 0L, 1_100L, 8_132, false);
		int sold = 0;
		long gross = 0;
		for (int chunk : new int[]{549, 2, 8, 7_558, 15})
		{
			sold += chunk;
			gross += chunk * 1_100L;
			t.onOffer(20L + sold, 1, 1601, "Diamond", false, sold, gross, 1_100L, 8_132, false);
		}

		final List<Flip> booked = t.getFlips();
		Assert.assertEquals("still one flip per fill under the hood", 5, booked.size());

		final long offer = booked.get(0).offerId;
		Assert.assertTrue("fills carry an offer id", offer != 0);
		for (Flip f : booked)
		{
			Assert.assertEquals("all five came from the same offer", offer, f.offerId);
		}

		final List<Flip> trades = Flip.byTrade(booked);
		Assert.assertEquals("one trade", 1, trades.size());
		Assert.assertEquals(8_132, trades.get(0).quantity);
		// The merged row's money is exactly the parts' money.
		long partProfit = 0;
		for (Flip f : booked)
		{
			partProfit += f.profit;
		}
		Assert.assertEquals(partProfit, trades.get(0).profit);
		Assert.assertEquals(gross, trades.get(0).sellGross);

		// And the stats count the trade, not the chunks.
		FlipStats.Stats s = FlipStats.compute(booked, FlipStats.Range.ALL, 1_000_000L, 0L, 0L, 0L);
		Assert.assertEquals(1, s.flipCount);
		Assert.assertEquals(partProfit, s.profit);
	}

	/** A second offer for the same item is a second trade, however similar. */
	@Test
	public void twoOffersAreTwoTrades()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_000L, 200, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 200, 200_000L, 1_000L, 200, false);
		t.onOffer(3L, 0, 1601, "Diamond", true, 200, 200_000L, 1_000L, 200, true);

		for (int round = 0; round < 2; round++)
		{
			t.onOffer(10L + round * 10, 1, 1601, "Diamond", false, 0, 0L, 1_100L, 100, false);
			t.onOffer(11L + round * 10, 1, 1601, "Diamond", false, 100, 110_000L, 1_100L, 100, false);
			t.onOffer(12L + round * 10, 1, 1601, "Diamond", false, 100, 110_000L, 1_100L, 100, true);
		}

		Assert.assertEquals(2, Flip.byTrade(t.getFlips()).size());
		Assert.assertEquals(2, FlipStats.compute(t.getFlips(), FlipStats.Range.ALL,
			1_000_000L, 0L, 0L, 0L).flipCount);
	}

	/**
	 * Rows from before offers were tokenised carry 0, and a shared 0 must
	 * never collapse them all into one giant "trade".
	 *
	 * Different items are different trades however close together they close,
	 * which is the case that a naive "group by offerId" would get catastrophically
	 * wrong.
	 */
	@Test
	public void untokenisedRowsOfDifferentThingsStayApart()
	{
		final List<Flip> old = List.of(
			new Flip(1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(2_000L, 561, "Nature rune", 10, 1_000L, 1_100L, 22L),
			new Flip(3_000L, 1603, "Ruby", 10, 20_000L, 22_000L, 440L));
		Assert.assertEquals(3, Flip.byTrade(old).size());
		Assert.assertEquals(3, FlipStats.compute(old, FlipStats.Range.ALL,
			1_000_000L, 0L, 0L, 0L).flipCount);
	}

	/**
	 * An untokenised ledger still groups its split fills.
	 *
	 * offerId arrived on 15 Sep 2026, so every row booked before it is in the
	 * ledger with a zero and had nothing to group by. A real ledger reported
	 * nineteen rows for six trades — "some sold in batches of like 1000 of
	 * 18000 and it counted that 18 times" — while the website beside it said
	 * six, because the website never had a token and matched on the trade's
	 * own terms instead. Same terms here: same item, same unit price both
	 * sides, inside the window.
	 */
	@Test
	public void untokenisedSplitFillsGroupOnTheirTerms()
	{
		final List<Flip> fills = List.of(
			new Flip(1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(2_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(3_000L, 1601, "Diamond", 30, 30_000L, 33_000L, 660L));
		final List<Flip> trades = Flip.byTrade(fills);
		Assert.assertEquals("one offer, three fills", 1, trades.size());
		Assert.assertEquals("quantity is the sum", 50, trades.get(0).quantity);
		Assert.assertEquals("and so is the money",
			11_000L + 11_000L + 33_000L - 220L - 220L - 660L - 50_000L,
			trades.get(0).profit);
		Assert.assertEquals(1, FlipStats.compute(fills, FlipStats.Range.ALL,
			1_000_000L, 0L, 0L, 0L).flipCount);
	}

	/**
	 * The price test is what keeps genuinely separate decisions apart.
	 *
	 * Same item, same minute, different prices: two trades, because you chose
	 * twice. Merging on item alone would turn a day of trading one item into a
	 * single row.
	 */
	@Test
	public void untokenisedRowsAtDifferentPricesAreDifferentTrades()
	{
		final List<Flip> fills = List.of(
			new Flip(1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(2_000L, 1601, "Diamond", 10, 12_000L, 13_000L, 260L));
		Assert.assertEquals(2, Flip.byTrade(fills).size());
	}

	/** And the window keeps a re-entry at the same price later on apart from
	 *  the trade it resembles. */
	@Test
	public void untokenisedRowsOutsideTheWindowAreDifferentTrades()
	{
		final long hours3 = 3 * 3_600_000L;
		final List<Flip> fills = List.of(
			new Flip(1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(1_000L + hours3, 1601, "Diamond", 10, 10_000L, 11_000L, 220L));
		Assert.assertEquals(2, Flip.byTrade(fills).size());
	}

	/**
	 * A token is a fact and an inference must not overrule it.
	 *
	 * Two tokenised offers with identical terms a second apart stay two rows,
	 * because the client watched them being placed separately.
	 */
	@Test
	public void theTermsFallbackNeverOverridesARealToken()
	{
		final List<Flip> fills = List.of(
			new Flip(7L, 0L, 1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(8L, 0L, 2_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L));
		Assert.assertEquals(2, Flip.byTrade(fills).size());
	}

	/** A merged hold time is unknown when ANY part's is — reporting the
	 *  earliest of the parts we happen to know would understate it. */
	@Test
	public void aMergedHoldIsUnknownIfAnyPartIs()
	{
		final List<Flip> parts = List.of(
			new Flip(7L, 0L, 5_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(7L, 1_000L, 6_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L));
		final Flip merged = Flip.merge(parts);
		Assert.assertEquals(-1L, merged.holdMillis());
		Assert.assertEquals(6_000L, merged.closedAt);
		Assert.assertEquals(20, merged.quantity);

		final List<Flip> known = List.of(
			new Flip(8L, 2_000L, 5_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(8L, 1_000L, 6_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L));
		Assert.assertEquals("earliest capital commitment", 5_000L, Flip.merge(known).holdMillis());
	}

	/** An empty save is not an upgrade with history behind it — there are no
	 *  lots to double count, so a first sighting books as normal. */
	@Test
	public void anEmptySaveStillSeeds()
	{
		FlipTracker t = new FlipTracker();
		t.restore(new FlipTracker.State());
		Assert.assertNotNull(t.onOffer(1L, 0, 1601, "Diamond", true, 900, 1_620_000L, 1_800L, 1_000, false));
		Assert.assertEquals(900L, t.getOpenBuyTotals().get(1601)[0]);
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import org.junit.After;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * "every time i list a new item in the ge, if i already have a pocket ge
 * window open ... can it automatically change the window from sapphire
 * necklaces to ruby necklaces when i switch to my next ge listing".
 */
public class FollowOfferTest
{
	private PocketGeTrackerPlugin plugin;
	private LocalBridgeServer bridge;
	private boolean follow = true;

	private Object get(String field) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private void set(String field, Object v) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, v);
	}

	@Before
	public void start() throws Exception
	{
		plugin = new PocketGeTrackerPlugin();
		bridge = new LocalBridgeServer(new Gson());
		bridge.start(0, HashMap::new, HashMap::new, null, null);
		set("bridge", bridge);
		set("config", Proxy.newProxyInstance(PocketGeTrackerConfig.class.getClassLoader(),
			new Class<?>[]{PocketGeTrackerConfig.class}, (p, m, a) ->
			{
				if (m.getName().equals("followGeOffer"))
				{
					return follow;
				}
				final Class<?> r = m.getReturnType();
				return r == boolean.class ? (Object) false : r.isPrimitive() ? (Object) 0 : null;
			}));
	}

	@After
	public void stop()
	{
		bridge.stop();
	}

	/** A tab that asked /nav a moment ago — the linked tab. */
	private void tabOpen() throws Exception
	{
		final Field f = LocalBridgeServer.class.getDeclaredField("lastNavPollAt");
		f.setAccessible(true);
		f.setLong(bridge, System.currentTimeMillis());
	}

	private LocalBridgeServer.NavRequest sent() throws Exception
	{
		return (LocalBridgeServer.NavRequest) get("pendingNav");
	}

	@Test
	public void theOpenTabFollowsToTheNextListing() throws Exception
	{
		tabOpen();
		plugin.followOfferScreen(1660, "Sapphire necklace");
		Assert.assertEquals("Sapphire necklace", sent().query);
		Assert.assertFalse("no ack wait: it opens nothing if the tab does not answer", sent().ack);
		final long first = sent().seq;

		plugin.followOfferScreen(1660, "Sapphire necklace");
		Assert.assertEquals("once per item, not on every screen update", first, sent().seq);

		plugin.followOfferScreen(1662, "Ruby necklace");
		Assert.assertEquals("Ruby necklace", sent().query);
	}

	@Test
	public void noTabNoMove() throws Exception
	{
		plugin.followOfferScreen(1660, "Sapphire necklace");
		Assert.assertNull("never opens one", sent());
	}

	@Test
	public void theSettingTurnsItOff() throws Exception
	{
		follow = false;
		tabOpen();
		plugin.followOfferScreen(1660, "Sapphire necklace");
		Assert.assertNull(sent());
	}
}

package com.pocketge.tracker;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.lang.reflect.Constructor;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import org.junit.Assert;
import org.junit.Test;

/**
 * The profit figure through the real overlay: "even if i missed it live, the
 * next time i load into this ge screen, it should have said +64kgp over rune
 * darts in that square but it didnt".
 */
public class GeOfferPopsTest
{
	private static final Rectangle SQUARE = new Rectangle(240, 60, 115, 106);
	private static final long T = 1_000_000L;

	/** What the fake client shows: the Exchange's slot screen open or not. */
	private boolean open;
	/** The fake plugin: unshown {units, profit} per slot, and what it was
	 *  told has been shown. */
	private final Map<Integer, long[]> unseen = new HashMap<>();
	private final List<Integer> shown = new ArrayList<>();
	private long now = T;

	private GeOfferGridOverlay overlay() throws Exception
	{
		final Widget square = (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(),
			new Class<?>[]{Widget.class}, (proxy, m, args) ->
				"getBounds".equals(m.getName()) ? new Rectangle(SQUARE) : defaults(m.getReturnType()));
		final Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, m, args) ->
			{
				if ("getWidget".equals(m.getName()) && args.length == 1)
				{
					return open && (Integer) args[0] == InterfaceID.GeOffers.INDEX_2 ? square : null;
				}
				return defaults(m.getReturnType());
			});
		final Constructor<GeOfferGridOverlay> k =
			GeOfferGridOverlay.class.getDeclaredConstructor(Client.class, TooltipManager.class);
		k.setAccessible(true);
		final GeOfferGridOverlay o = k.newInstance(client, new TooltipManager());
		o.clock = () -> now;
		o.setPopSource(new GeOfferGridOverlay.PopSource()
		{
			@Override
			public long[] unseen(int slot)
			{
				return unseen.get(slot);
			}

			@Override
			public void shown(int slot)
			{
				shown.add(slot);
				unseen.remove(slot);
			}
		});
		return o;
	}

	private static Object defaults(Class<?> t)
	{
		if (t == boolean.class)
		{
			return false;
		}
		if (t == int.class)
		{
			return 0;
		}
		if (t == long.class)
		{
			return 0L;
		}
		return null;
	}

	/** Green pixels the overlay painted — all of them inside the square. */
	private static int greenIn(GeOfferGridOverlay o)
	{
		final BufferedImage img = new BufferedImage(400, 200, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		o.render(g);
		g.dispose();
		int n = 0;
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				final int rgb = img.getRGB(x, y);
				final boolean green = (rgb >>> 24) > 200
					&& Math.abs(((rgb >> 16) & 0xFF) - ProfitPops.GAIN.getRed()) < 12
					&& Math.abs(((rgb >> 8) & 0xFF) - ProfitPops.GAIN.getGreen()) < 12
					&& Math.abs((rgb & 0xFF) - ProfitPops.GAIN.getBlue()) < 12;
				if (green)
				{
					Assert.assertTrue("only over its own square", SQUARE.contains(x, y));
					n++;
				}
			}
		}
		return n;
	}

	/** Over the Exchange: done boxed three pixels deep in green, a reprice
	 *  two in a softened white. */
	@Test
	public void doneIsBoxedHeavierThanAReprice() throws Exception
	{
		final GeOfferGridOverlay o = overlay();
		open = true;
		final GeOfferGridOverlay.SlotView v = new GeOfferGridOverlay.SlotView();
		v.itemName = "Shark";
		v.ready = true;
		o.setSlots(Map.of(2, v));
		BufferedImage img = new BufferedImage(400, 200, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		o.render(g);
		g.dispose();
		final int mid = SQUARE.x + SQUARE.width / 2;
		for (int i = 0; i < 3; i++)
		{
			Assert.assertEquals("green, row " + i, GeSlotsPanel.COLLECT_COLOR.getRGB(), img.getRGB(mid, SQUARE.y + i));
		}
		Assert.assertEquals("three deep, no more", 0, img.getRGB(mid, SQUARE.y + 3) >>> 24);

		v.ready = false;
		v.needsAdjust = true;
		img = new BufferedImage(400, 200, BufferedImage.TYPE_INT_ARGB);
		g = img.createGraphics();
		o.render(g);
		g.dispose();
		for (int i = 0; i < 2; i++)
		{
			final int rgb = img.getRGB(mid, SQUARE.y + i);
			Assert.assertEquals("white, row " + i, GeSlotsPanel.REPRICE_BOX.getRGB() & 0xFFFFFF, rgb & 0xFFFFFF);
			Assert.assertTrue("softened", (rgb >>> 24) < 0xFF);
		}
		Assert.assertEquals("two deep", 0, img.getRGB(mid, SQUARE.y + 2) >>> 24);
	}

	/** Cooked sharks, no buy on record: the coins they brought in, in gold
	 *  over their square, and nothing green — it is not profit. */
	@Test
	public void aSaleWithNoBuyOnRecordPopsGold() throws Exception
	{
		final GeOfferGridOverlay o = overlay();
		unseen.put(2, new long[]{500, 441_000, FlipTracker.UNSEEN_COINS});
		open = true;
		final BufferedImage img = new BufferedImage(400, 200, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		o.render(g);
		g.dispose();
		Assert.assertTrue("gold over the square", CoinPopsTest.count(img, ProfitPops.COINS) > 0);
		Assert.assertEquals("not green", 0, CoinPopsTest.count(img, ProfitPops.GAIN));
		Assert.assertEquals(List.of(2), shown);
	}

	/** Sold with the Exchange shut; opened ten minutes later — far past a
	 *  figure's three seconds — and there it is, once. */
	@Test
	public void soldWithTheExchangeShutPopsWhenItOpens() throws Exception
	{
		final GeOfferGridOverlay o = overlay();
		unseen.put(2, new long[]{7_132, 64_000});
		open = false;
		Assert.assertEquals("nothing while it is shut", 0, greenIn(o));
		now = T + 10 * 60_000;
		Assert.assertEquals(0, greenIn(o));
		Assert.assertTrue("and not counted as shown", shown.isEmpty());

		open = true;
		Assert.assertTrue("+64K gp over the Rune dart square", greenIn(o) > 0);
		Assert.assertEquals("shown, so it will not come back", List.of(2), shown);

		now += ProfitPops.LIFE_MS;
		Assert.assertEquals("over after its three seconds", 0, greenIn(o));
		open = false;
		open = true;
		Assert.assertEquals("not again on reopening", 0, greenIn(o));
	}

	@Test
	public void soldWithTheExchangeOpenPopsAtOnce() throws Exception
	{
		final GeOfferGridOverlay o = overlay();
		open = true;
		Assert.assertEquals(0, greenIn(o));
		unseen.put(2, new long[]{100, 2_000});
		Assert.assertTrue(greenIn(o) > 0);
	}

	/** Only a slot whose square is up is asked, so nothing is counted as
	 *  shown that was not. */
	@Test
	public void nothingIsShownThatWasNotOnScreen() throws Exception
	{
		final GeOfferGridOverlay o = overlay();
		unseen.put(5, new long[]{100, 2_000});
		open = true;
		Assert.assertEquals(0, greenIn(o));
		Assert.assertTrue(shown.isEmpty());
	}

	/** Switched off: the figure on screen goes too. */
	@Test
	public void clearTakesTheFigureOff() throws Exception
	{
		final GeOfferGridOverlay o = overlay();
		open = true;
		unseen.put(2, new long[]{100, 2_000});
		Assert.assertTrue(greenIn(o) > 0);
		o.clearPops();
		Assert.assertEquals(0, greenIn(o));
	}
}

package com.pocketge.tracker;

import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Assert;
import org.junit.Test;

/**
 * What the tracker does with one real offer's life: fills, a price change,
 * a logout and a hop.
 *
 * Written while chasing a sell card that read "PAID @ 1,025" for Mithril bars
 * bought at 876. The tracker was not at fault — that was the card's old
 * formula, since fixed (SellCardPaidTest) — but tracing every path an offer
 * can take found a real way to count a purchase twice, and these hold both.
 */
public class GeReplayTest
{
	private static final int MITHRIL_BAR = 2359;

	private static long[] totals(FlipTracker t)
	{
		return t.getOpenBuyTotals().get(MITHRIL_BAR);
	}

	/** First fills and later fills of one offer are one cost basis — the
	 *  first 173 are inside the 3,738, never on top of them. */
	@Test
	public void anOffersFillsAreOneCostBasisThroughAPriceChange()
	{
		final FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, MITHRIL_BAR, "Mithril bar", true, 0, 0L, 876, 10_000, false);
		t.onOffer(2L, 0, MITHRIL_BAR, "Mithril bar", true, 173, 173L * 876, 876, 10_000, false);
		t.onOffer(3L, 0, MITHRIL_BAR, "Mithril bar", true, 3_738, 3_738L * 876, 876, 10_000, false);
		// The price change: the rest re-listed at 871, nothing filled yet.
		t.onOffer(4L, 0, MITHRIL_BAR, "Mithril bar", true, 0, 0L, 871, 6_262, false);
		Assert.assertArrayEquals(new long[]{3_738, 3_738L * 876}, totals(t));
	}

	@Test
	public void abortCollectRelistKeepsTheLots()
	{
		final FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, MITHRIL_BAR, "Mithril bar", true, 0, 0L, 876, 10_000, false);
