	/** The same two snapshots watched live are a misread: nothing booked. */
	@Test
	public void watchedLiveTheyAreMisreads()
	{
		final FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, MITHRIL_BAR, "Mithril bar", true, 0, 0L, 876, 10_000, false);
		t.onOffer(2L, 0, MITHRIL_BAR, "Mithril bar", true, 10_000, 8_000_000L, 876, 10_000, false);
		Assert.assertNull(t.onOffer(3L, 0, MITHRIL_BAR, "Mithril bar", true, 10_000, 8_500_000L, 876, 10_000, false));
		Assert.assertNull(t.onOffer(4L, 0, MITHRIL_BAR, "Mithril bar", true, 10_000, 8_000_000L, 876, 10_000, false));
		Assert.assertArrayEquals(new long[]{10_000, 8_000_000L}, totals(t));
	}

	/** A save from 0.7.1, with Gson in between as the plugin does it. */
	private static FlipTracker upgraded(FlipTracker.State old)
	{
		final com.google.gson.Gson gson = new com.google.gson.Gson();
		final FlipTracker.State s = gson.fromJson(gson.toJson(old), FlipTracker.State.class);
		final FlipTracker t = new FlipTracker();
		t.restore(s);
		return t;
	}

	/**
	 * Upgrading from 0.7.1, which filed a negative-hash character's slots
	 * under whoever logged in before it. Its first login after the upgrade
	 * finds no record of its own, and without the migration every filled
	 * offer it has was booked a second time.
	 */
	@Test
	public void upgradingNeverRebooksANegativeHashCharactersOffers()
	{
		final long main = 123_456_789L;
		final long alt = -987_654_321L;
		// 0.7.1's save: the main's 3,000 and the alt's 1,000 (at 500 each)
		// both booked, and the slot row the alt's, filed under the main
		final FlipTracker.State old = new FlipTracker.State();
		old.accountHash = main;
		old.openBuys = new java.util.HashMap<>();
		old.openBuys.put(MITHRIL_BAR, new java.util.ArrayList<>(java.util.List.of(
			new long[]{3_000, 2_628_000L, 4L}, new long[]{1_000, 500_000L, 5L})));
		old.slotsByAccount = new java.util.HashMap<>();
		final java.util.Map<Integer, long[]> mainRows = new java.util.HashMap<>();
		mainRows.put(0, new long[]{MITHRIL_BAR, 1, 1_000, 500_000L, 876, 10_000, 1});
		old.slotsByAccount.put(main, mainRows);

		final FlipTracker t = upgraded(old);
		t.setAccountHash(alt);
		Assert.assertNull("the alt's login replay books nothing",
			t.onOffer(1L, 0, MITHRIL_BAR, "Mithril bar", true, 1_000, 500_000L, 876, 10_000, false));
		Assert.assertArrayEquals(new long[]{4_000, 3_128_000L}, totals(t));
		// and from then on the alt is measured against itself
		Assert.assertEquals(500, t.onOffer(2L, 0, MITHRIL_BAR, "Mithril bar", true, 1_500, 938_000L, 876, 10_000, false).quantity);

		// The main logs in to its own offer, measured against the alt's old
		// row: over the bid, so not that offer — and from an old save, so no
		// proof of a new one either. Re-baselined; its receipt not booked again.
		t.markSlotsUnwatched();
		t.setAccountHash(main);
		Assert.assertNull(t.onOffer(3L, 0, MITHRIL_BAR, "Mithril bar", true, 3_000, 2_628_000L, 876, 10_000, false));
		Assert.assertArrayEquals(new long[]{4_500, 3_566_000L}, totals(t));
	}

	/** Each negative-hash character gets the migration once, and it survives
	 *  a save — the alt may not log in until next week. */
	@Test
	public void theMigrationIsOncePerCharacterAndSurvivesASave()
	{
		final FlipTracker.State old = new FlipTracker.State();
		old.accountHash = 123_456_789L;
		old.lifetimeProfit = 1;
		final FlipTracker first = upgraded(old);
		final FlipTracker t = upgraded(first.snapshot()); // a session that never saw the alt
		t.setAccountHash(-5L);
		Assert.assertNull("placeholders: the first sighting only baselines",
			t.onOffer(1L, 0, MITHRIL_BAR, "Mithril bar", true, 100, 87_600L, 876, 10_000, false));
		t.onOffer(2L, 0, 0, "", false, 0, 0L, 0, 0, true); // collected; the alt's record is empty again
		final FlipTracker later = upgraded(t.snapshot());
		later.setAccountHash(-5L);
		Assert.assertNotNull("handled once already: a new offer's receipt books",
			later.onOffer(3L, 0, MITHRIL_BAR, "Mithril bar", true, 100, 87_600L, 876, 10_000, false));
	}

	/** A fresh install has nothing to migrate: a negative-hash character's
	 *  first sighting books, like anyone's. */
	@Test
	public void aFreshInstallHasNoMigration()
	{
		final FlipTracker t = upgraded(new FlipTracker.State());
		t.setAccountHash(-5L);
		Assert.assertNotNull(t.onOffer(1L, 0, MITHRIL_BAR, "Mithril bar", true, 100, 87_600L, 876, 10_000, false));
	}

	/** Forgetting drops one item's lots and nothing else; the slot keeps its
	 *  baseline, so the offer's next fill still books. */
	@Test
	public void forgettingDropsTheItemsLotsOnly()
	{
		final FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, MITHRIL_BAR, "Mithril bar", true, 0, 0L, 876, 10_000, false);
		t.onOffer(2L, 0, MITHRIL_BAR, "Mithril bar", true, 3_738, 3_738L * 876, 876, 10_000, false);
		t.onOffer(3L, 1, 1601, "Diamond", true, 0, 0L, 2_000, 10, false);
		t.onOffer(4L, 1, 1601, "Diamond", true, 10, 20_000L, 2_000, 10, false);

		final long[] record = t.getOpenBuyRecord(MITHRIL_BAR);
		Assert.assertArrayEquals(new long[]{3_738, 3_738L * 876}, t.forgetOpenBuys(MITHRIL_BAR, record[2]));
		Assert.assertNull(totals(t));
		Assert.assertNull(t.getOpenBuyTotal(MITHRIL_BAR));
		Assert.assertArrayEquals(new long[]{10, 20_000L}, t.getOpenBuyTotal(1601));
		Assert.assertNull("nothing left to forget", t.forgetOpenBuys(MITHRIL_BAR, record[2]));

		t.onOffer(5L, 0, MITHRIL_BAR, "Mithril bar", true, 3_800, 3_800L * 876, 876, 10_000, false);
		Assert.assertArrayEquals(new long[]{62, 62L * 876}, totals(t));
	}

	/** A fill booked while the forget prompt was open is not what the
	 *  player was shown, and survives the forget. */
	@Test
	public void forgettingKeepsLotsBookedAfterThePrompt()
	{
		final FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, MITHRIL_BAR, "Mithril bar", true, 0, 0L, 876, 10_000, false);
		t.onOffer(2L, 0, MITHRIL_BAR, "Mithril bar", true, 3_738, 3_738L * 876, 876, 10_000, false);
		final long[] shown = t.getOpenBuyRecord(MITHRIL_BAR);
		t.onOffer(3L, 0, MITHRIL_BAR, "Mithril bar", true, 4_238, 3_738L * 876 + 500L * 870, 876, 10_000, false);
		Assert.assertArrayEquals(new long[]{3_738, 3_738L * 876}, t.forgetOpenBuys(MITHRIL_BAR, shown[2]));
		Assert.assertArrayEquals(new long[]{500, 500L * 870}, totals(t));
	}
}

package com.pocketge.tracker;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import javax.swing.JLabel;
import org.junit.Assert;
import org.junit.Test;

/**
 * "may as well add a small chevron here like above for flip ideas incase
 * people want to collapse this": the eight squares fold to one line, and
 * that line still says which slots want you.
 */
public class GeSlotsFoldTest
{
	private static JLabel label(Container root, String text)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof JLabel && text.equals(((JLabel) c).getText()))
			{
				return (JLabel) c;
			}
			if (c instanceof Container)
			{
				final JLabel found = label((Container) c, text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static void click(Component c)
	{
		for (MouseListener l : c.getMouseListeners())
		{
			l.mouseClicked(new MouseEvent(c, MouseEvent.MOUSE_CLICKED, 0, 0, 1, 1, 1, false, MouseEvent.BUTTON1));
		}
	}

	private static GeSlotsPanel.SlotInfo slot(GeSlotsPanel.SlotState state, boolean skipped)
	{
		final GeSlotsPanel.SlotInfo s = new GeSlotsPanel.SlotInfo();
		s.state = state;
		s.adviceSkipped = skipped;
		return s;
	}

	@Test
	public void theChevronFoldsTheGridToOneLineAndBack()
	{
		final GeSlotsPanel p = new GeSlotsPanel(null, null);
		final int open = p.getPreferredSize().height;
		Assert.assertNull("folded line not shown while open", label(p, "GE slots hidden"));

		click(label(p, "▾"));
		Assert.assertNotNull(label(p, "GE slots hidden"));
		final int folded = p.getPreferredSize().height;
		Assert.assertTrue("one line, not a grid: " + folded + " vs " + open, folded > 0 && folded < open / 2);
		Assert.assertEquals("never a wide preferred width", 0, p.getPreferredSize().width);
		Assert.assertEquals(folded, p.getMaximumSize().height);

		click(label(p, "GE slots hidden"));
		Assert.assertEquals(open, p.getPreferredSize().height);
		Assert.assertNull(label(p, "GE slots hidden"));
	}

	/** "this chevron pushed everything left": the chevron sits on a row of
	 *  its own above the grid, so the grid keeps the panel's full width. */
	@Test
	public void theGridKeepsTheFullWidth()
	{
		final GeSlotsPanel p = new GeSlotsPanel(null, null);
		p.setSize(225, p.getPreferredSize().height);
		layout(p);
		Container grid = null;
		for (Component c : all(p))
		{
			if (c instanceof Container && ((Container) c).getLayout() instanceof java.awt.GridLayout)
			{
				grid = (Container) c;
			}
		}
		Assert.assertNotNull(grid);
		Assert.assertEquals("every column at full width", 225, grid.getWidth());
		final JLabel chevron = label(p, "▾");
		final java.awt.Rectangle at = javax.swing.SwingUtilities.convertRectangle(chevron.getParent(), chevron.getBounds(), p);
		Assert.assertTrue("the chevron is above the grid, not beside it", at.y + at.height <= grid.getY());
		Assert.assertTrue("at the right end", at.x + at.width >= 225 - 4);
	}

	private static void layout(Container c)
	{
		c.doLayout();
		for (Component k : c.getComponents())
		{
			if (k instanceof Container)
			{
				layout((Container) k);
			}
		}
	}

	private static java.util.List<Component> all(Container c)
	{
		final java.util.List<Component> out = new java.util.ArrayList<>();
		for (Component k : c.getComponents())
		{
			out.add(k);
			if (k instanceof Container)
			{
				out.addAll(all((Container) k));
			}
		}
		return out;
	}

	@Test
	public void theFoldedLineStillSaysWhatWantsYou()
	{
		final GeSlotsPanel p = new GeSlotsPanel(null, null);
		click(label(p, "▾"));
		p.update(new GeSlotsPanel.SlotInfo[]{
			slot(GeSlotsPanel.SlotState.READY_COLLECT, false),
			slot(GeSlotsPanel.SlotState.READY_COLLECT, true),
			slot(GeSlotsPanel.SlotState.ACTIVE_ADJUST, false),
			slot(GeSlotsPanel.SlotState.ACTIVE_LOSING, false),
			slot(GeSlotsPanel.SlotState.ACTIVE_ADJUST, true),
			slot(GeSlotsPanel.SlotState.ACTIVE_OK, false),
			null,
		});
		final JLabel ready = label(p, "2 ready");
		final JLabel reprice = label(p, "2 to reprice");
		Assert.assertNotNull("collectable even if you priced it yourself", ready);
		Assert.assertNotNull("a slot you price yourself is not counted", reprice);
		Assert.assertTrue(ready.isVisible() && reprice.isVisible());

		p.update(new GeSlotsPanel.SlotInfo[]{slot(GeSlotsPanel.SlotState.ACTIVE_OK, false)});
		Assert.assertFalse("nothing to say, nothing shown", label(p, "0 ready").isVisible());
		Assert.assertFalse(label(p, "0 to reprice").isVisible());
		Assert.assertEquals(0, GeSlotsPanel.readyCount(null));
		Assert.assertEquals(0, GeSlotsPanel.repriceCount(null));
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * The fill percentage on a GE slot tooltip. Every case here is a boundary,
 * which is the whole reason it is a pure static rather than a method buried
 * in a Swing component.
 */
public class GeSlotsPercentTest
{
	/** The case that prompted the change: a real fill against a five-figure
	 *  4-hour limit. As an integer this floored to "0", which says nothing
	 *  has happened about an offer that has genuinely started. */
	@Test
	public void aSmallFillAgainstABigLimitIsNotZero()
	{
		Assert.assertEquals("0.76", GeSlotsPanel.percentText(138, 18_000));
	}

	/** One item out of a huge limit is still a fill. It must not round away
	 *  to nothing — that is the same bug in a smaller number. */
	@Test
	public void aSingleItemNeverReportsAsZero()
	{
		Assert.assertEquals("0.01", GeSlotsPanel.percentText(1, 18_000));
		Assert.assertEquals("0.01", GeSlotsPanel.percentText(1, 1_000_000));
	}

	/** Nothing filled reads a flat 0 — "0.00%" for an offer that has not
	 *  moved is false precision. */
	@Test
	public void nothingFilledIsAFlatZero()
	{
		Assert.assertEquals("0", GeSlotsPanel.percentText(0, 18_000));
	}

	/** Whole numbers once there is a whole number to show. */
	@Test
	public void aboveOnePercentIsAWholeNumber()
	{
		Assert.assertEquals("1", GeSlotsPanel.percentText(180, 18_000));
		Assert.assertEquals("50", GeSlotsPanel.percentText(9_000, 18_000));
		Assert.assertEquals("33", GeSlotsPanel.percentText(6_000, 18_000));
	}

	/**
	 * Short of complete never reads 100. An offer 35,999 of 36,000 done is
	 * the one misreading that sends you to the GE for nothing.
	 */
	@Test
	public void almostDoneIsNeverAHundred()
	{
		Assert.assertEquals("99", GeSlotsPanel.percentText(35_999, 36_000));
		Assert.assertEquals("99", GeSlotsPanel.percentText(17_999, 18_000));
	}

	@Test
	public void completeIsAHundred()
	{
		Assert.assertEquals("100", GeSlotsPanel.percentText(18_000, 18_000));
		Assert.assertEquals("100", GeSlotsPanel.percentText(19_000, 18_000)); // over-fill clamps
	}

	/** Junk in, silence out — never a divide by zero or a negative. */
	@Test
	public void nonsenseInputsDoNotThrow()
	{
		Assert.assertEquals("0", GeSlotsPanel.percentText(5, 0));
		Assert.assertEquals("0", GeSlotsPanel.percentText(-5, 100));
		Assert.assertEquals("0", GeSlotsPanel.percentText(0, 0));
	}

	/** The crossover: just under 1% keeps decimals, exactly 1% does not. */
	@Test
	public void theCrossoverAtOnePercent()
	{
		Assert.assertEquals("0.99", GeSlotsPanel.percentText(99, 10_000));
		Assert.assertEquals("1", GeSlotsPanel.percentText(100, 10_000));
	}
}

package com.pocketge.tracker;

import java.util.HashMap;
import java.util.Map;
import net.runelite.client.util.QuantityFormatter;
import org.junit.Assert;
import org.junit.Test;

/**
 * "it cant remember 2 costs paid?" / "yes add that to the hover": the
 * batches behind a stack, as the hover lists them.
 */
public class HeldBatchesTest
{
	private static final int ITEM = 4151;
	private long now = 1_000_000L;

	/** One buy offer of {@code qty} at {@code price}, filled and collected. */
	private void buy(FlipTracker t, int qty, int price)
	{
		t.onOffer(now++, 0, ITEM, "Item", true, 0, 0, price, qty, false);
		t.onOffer(now++, 0, ITEM, "Item", true, qty, (long) qty * price, price, qty, false);
		t.onOffer(now++, 0, 0, "", false, 0, 0, 0, 0, true);
	}

	private static Map<Integer, Long> holding(long n)
	{
		final Map<Integer, Long> m = new HashMap<>();
		m.put(ITEM, n);
		return m;
	}

	private FlipTracker threeBatches()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		buy(t, 10_000, 349);
		buy(t, 10_000, 333);
		buy(t, 10_000, 329);
		return t;
	}

	@Test
	public void itRemembersEachBatchItWasBoughtIn()
	{
		final FlipTracker t = threeBatches();
		Assert.assertArrayEquals("oldest first, as bought",
			new long[]{10_000, 3_490_000, 10_000, 3_330_000, 10_000, 3_290_000},
			t.heldBatches(holding(30_000)).get(ITEM));
	}

	/** Selling 5K uses the newest batch first, and the rest is what is
	 *  listed: 10K @ 349, 10K @ 333, 5K @ 329. */
	@Test
	public void aSaleTakesFromTheNewest()
	{
		final FlipTracker t = threeBatches();
		t.onOffer(now++, 1, ITEM, "Item", false, 0, 0, 340, 5_000, false);
		t.onOffer(now++, 1, ITEM, "Item", false, 5_000, 5_000L * 340, 340, 5_000, false);
		Assert.assertArrayEquals(new long[]{10_000, 3_490_000, 10_000, 3_330_000, 5_000, 1_645_000},
			t.heldBatches(holding(25_000)).get(ITEM));
	}

	/** And it is the same stack the hover's "Paid" is worked out from. */
	@Test
	public void theBatchesAddUpToWhatThePaidLineSays()
	{
		final FlipTracker t = threeBatches();
		for (long held : new long[]{30_000, 25_000, 12_000})
		{
			final long[] b = t.heldBatches(holding(held)).get(ITEM);
			long q = 0, s = 0;
			for (int i = 0; i < b.length; i += 2)
			{
				q += b[i];
				s += b[i + 1];
			}
			final long[] paid = t.getHeldCost(holding(held)).get(ITEM);
			Assert.assertEquals("units at " + held, paid[0], q);
			Assert.assertEquals("gp at " + held, paid[1], s);
		}
	}

	/** One buy offer filled in several parts at different prices is one
	 *  batch, at its average. */
	@Test
	public void anOfferFilledInPartsIsOneBatch()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		t.onOffer(now++, 0, ITEM, "Item", true, 0, 0, 350, 9_000, false);
		t.onOffer(now++, 0, ITEM, "Item", true, 3_000, 3_000L * 345, 350, 9_000, false);
		t.onOffer(now++, 0, ITEM, "Item", true, 6_000, 3_000L * 345 + 3_000L * 348, 350, 9_000, false);
		t.onOffer(now++, 0, ITEM, "Item", true, 9_000, 3_000L * 345 + 3_000L * 348 + 3_000L * 350, 350, 9_000, false);
		/* Uncollected, the units are in the box and not in the stack you
		   hold; collected, they are. */
		Assert.assertNull(t.heldBatches(holding(9_000)).get(ITEM));
		t.onOffer(now++, 0, 0, "", false, 0, 0, 0, 0, true);
		Assert.assertArrayEquals(new long[]{9_000, 3_000L * (345 + 348 + 350)}, t.heldBatches(holding(9_000)).get(ITEM));
	}

	/** Older buys beyond what you hold (sold where the plugin did not see)
	 *  are not batches of the stack you hold. */
	@Test
	public void onlyTheBatchesOfWhatYouHold()
	{
		final FlipTracker t = threeBatches();
		Assert.assertArrayEquals(new long[]{10_000, 3_330_000, 10_000, 3_290_000}, t.heldBatches(holding(20_000)).get(ITEM));
		Assert.assertArrayEquals("part of a batch", new long[]{2_000, 2_000L * 329},
			t.heldBatches(holding(2_000)).get(ITEM));
	}

	@Test
	public void theHoverListsThemWhenThereIsMoreThanOne()
	{
		final String three = BankHighlightOverlay.batchesText(
			new long[]{10_000, 3_490_000, 10_000, 3_330_000, 10_000, 3_290_000});
		final String k = QuantityFormatter.quantityToStackSize(10_000);
		Assert.assertTrue(three, three.contains("Bought in batches, newest sells first:"));
		Assert.assertTrue(three, three.contains(k + " @ 349 · " + k + " @ 333 · " + k + " @ 329"));
		Assert.assertEquals("one batch: the Paid line says it", "",
			BankHighlightOverlay.batchesText(new long[]{10_000, 3_490_000}));
		Assert.assertEquals("", BankHighlightOverlay.batchesText(null));

		final String five = BankHighlightOverlay.batchesText(
			new long[]{100, 10_000, 100, 11_000, 100, 12_000, 100, 13_000, 100, 14_000});
		Assert.assertTrue(five, five.contains("+2 older · 100 @ 120 · 100 @ 130 · 100 @ 140"));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import org.junit.Assert;
import org.junit.Test;

/**
 * PAID @ is what you paid for the stack you HOLD.
 *
 * Reported: 13,418 Aether catalysts bought at 277 showed "PAID @ 330". The
 * tracker also had about 24,500 left over from an earlier stack at 359,
 * sold where it did not see — and the card averaged the two.
 */
public class HeldCostTest
{
	private static final int AETHER = 30771;

	/** An earlier stack at 359 the plugin never saw sold, then this one at 277. */
	private static FlipTracker withLeftovers()
	{
		final FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, AETHER, "Aether catalyst", true, 0, 0L, 359, 25_000, false);
		t.onOffer(2L, 0, AETHER, "Aether catalyst", true, 24_522, 24_522L * 359, 359, 25_000, false);
		t.onOffer(3L, 0, 0, "", false, 0, 0L, 0, 0, true);
		t.onOffer(4L, 1, AETHER, "Aether catalyst", true, 0, 0L, 277, 23_000, false);
		t.onOffer(5L, 1, AETHER, "Aether catalyst", true, 13_418, 13_418L * 277, 277, 23_000, false);
		return t;
	}

	private static Map<Integer, Long> holding(long n)
	{
		final Map<Integer, Long> m = new HashMap<>();
		m.put(AETHER, n);
		return m;
	}

	@Test
	public void theStackYouHoldIsPricedFromYourNewestBuys()
	{
		final long[] c = withLeftovers().getHeldCost(holding(13_418)).get(AETHER);
		Assert.assertArrayEquals(new long[]{13_418, 13_418L * 277, 24_522, 24_522L * 359}, c);
		Assert.assertEquals("PAID @ 277, not 330", 277, Math.round(c[1] / (double) c[0]));
	}

	@Test
	public void aStackReachingIntoAnOlderLotTakesPartOfIt()
	{
		final long[] c = withLeftovers().getHeldCost(holding(14_418)).get(AETHER);
		Assert.assertEquals(14_418, c[0]);
		Assert.assertEquals(13_418L * 277 + 1_000L * 359, c[1]);
		Assert.assertEquals(23_522, c[2]);
	}

	@Test
	public void holdingAllOfItOrNoneChangesNothing()
	{
		final FlipTracker t = withLeftovers();
		Assert.assertArrayEquals(new long[]{37_940, 13_418L * 277 + 24_522L * 359, 0, 0},
			t.getHeldCost(holding(50_000)).get(AETHER));
		Assert.assertArrayEquals("nothing held: plain totals",
			new long[]{37_940, 13_418L * 277 + 24_522L * 359, 0, 0}, t.getHeldCost(new HashMap<>()).get(AETHER));
	}

	/** Forgetting the older ones keeps the stack's cost, and the next sale
	 *  is matched against it — a profit, not a loss against 359. */
	@Test
	public void forgettingTheOlderBuysLeavesTheStackAndMatchesSalesToIt()
	{
		final FlipTracker t = withLeftovers();
		Assert.assertArrayEquals(new long[]{24_522, 24_522L * 359}, t.forgetOlderThan(AETHER, 13_418));
		Assert.assertArrayEquals(new long[]{13_418, 13_418L * 277}, t.getOpenBuyTotal(AETHER));
		Assert.assertNull("nothing older left", t.forgetOlderThan(AETHER, 13_418));
		t.onOffer(6L, 2, AETHER, "Aether catalyst", false, 0, 0L, 299, 13_418, false);
		t.onOffer(7L, 2, AETHER, "Aether catalyst", false, 13_418, 13_418L * 299, 299, 13_418, false);
		final Flip f = t.getFlips().get(t.getFlips().size() - 1);
		Assert.assertTrue("a profit at 299 on a 277 stack: " + f.profit, f.profit > 0);
	}

	@Test
	public void forgettingTrimsTheOldestLotAtTheBoundary()
	{
		final FlipTracker t = withLeftovers();
		Assert.assertArrayEquals(new long[]{23_522, 23_522L * 359}, t.forgetOlderThan(AETHER, 14_418));
		Assert.assertArrayEquals(new long[]{14_418, 13_418L * 277 + 1_000L * 359}, t.getOpenBuyTotal(AETHER));
	}

	@SuppressWarnings("unchecked")
	private static <T> T stub(Class<T> type)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (p, m, a) ->
		{
			final Class<?> r = m.getReturnType();
			return r == boolean.class ? (Object) false : r.isPrimitive() ? (r == long.class ? (Object) 0L : (Object) 0) : null;
		});
	}

	private static Object get(Object o, String field) throws Exception
	{
		final Field f = o.getClass().getDeclaredField(field);
		f.setAccessible(true);
		return f.get(o);
	}

	/** The card says the older ones are left out, and offers to forget them. */
	@Test
	public void theCardSaysSoAndOffersToForgetThem() throws Exception
	{
		final AdvisorPanel panel = new AdvisorPanel(null, stub(AdvisorPanel.Actions.class));
		final Map<Integer, long[]> older = new HashMap<>();
		older.put(AETHER, new long[]{24_522, 24_522L * 359});
		panel.setOlderBuys(older);
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.sell = true;
		r.itemId = AETHER;
		r.name = "Aether catalyst";
		r.quantity = 13_418;
		r.unitPrice = 299;
		r.unitCost = 277;
		r.hasTrackedCost = true;
		r.profit = 13_418L * (299 - 5 - 277);
		final Method cardFor = AdvisorPanel.class.getDeclaredMethod("cardFor", AdvisorPanel.Rec.class);
		cardFor.setAccessible(true);
		final Object card = cardFor.invoke(panel, r);
		Assert.assertEquals("24,522 older buys not counted", get(card, "footnote"));
		final JPopupMenu menu = (JPopupMenu) get(card, "contextMenu");
		boolean offered = false;
		for (java.awt.Component c : menu.getComponents())
		{
			offered |= c instanceof JMenuItem && "Forget the 24,522 older buys".equals(((JMenuItem) c).getText());
		}
		Assert.assertTrue("the right-click offers to forget them", offered);
	}

	/**
	 * "Older buys you no longer have" only when the bank has been read since
	 * the item last left a GE slot — Collect to bank puts it in the bank
	 * without the bank being open, and the snapshot then under-counts.
	 */
	@Test
	@SuppressWarnings("unchecked")
	public void olderBuysAreOnlyCalledThatWhenTheBankIsCurrent() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		final Field read = PocketGeTrackerPlugin.class.getDeclaredField("bankReadThisLoginAt");
		read.setAccessible(true);
		final Map<Integer, Long> collected = (Map<Integer, Long>) get(plugin, "collectedAt");
		final Method current = PocketGeTrackerPlugin.class.getDeclaredMethod("currentOlderBuys", Map.class);
		current.setAccessible(true);
		final Map<Integer, long[]> cost = new HashMap<>();
		cost.put(AETHER, new long[]{13_418, 13_418L * 277, 24_522, 24_522L * 359});

		Assert.assertTrue("bank not opened this login", ((Map<Integer, long[]>) current.invoke(plugin, cost)).isEmpty());
		read.set(plugin, 2_000L);
		Assert.assertTrue("bank read", ((Map<Integer, long[]>) current.invoke(plugin, cost)).containsKey(AETHER));
		collected.put(AETHER, 3_000L);
		Assert.assertTrue("collected since: maybe straight to the bank",
			((Map<Integer, long[]>) current.invoke(plugin, cost)).isEmpty());
		read.set(plugin, 4_000L);
		Assert.assertTrue("read again", ((Map<Integer, long[]>) current.invoke(plugin, cost)).containsKey(AETHER));
	}

	@Test
	public void onlyItemsWithOlderBuysAreReported()
	{
		final Map<Integer, long[]> cost = new HashMap<>();
		cost.put(AETHER, new long[]{13_418, 13_418L * 277, 24_522, 24_522L * 359});
		cost.put(1621, new long[]{100, 31_700, 0, 0});
		final Map<Integer, long[]> older = PocketGeTrackerPlugin.olderBuys(cost);
		Assert.assertArrayEquals(new long[]{24_522, 24_522L * 359}, older.get(AETHER));
		Assert.assertFalse(older.containsKey(1621));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * "thoughts on hover over also showing high alch profit ea alch?" and
 * "putting high alch ea profit on the flip trade idea cards too in this
 * area": what one cast on a stack makes, after a nature rune, against what
 * one cost — on the stack's hover and beside VALUE on its card.
 */
public class HighAlchTest
{
	private static final int KITESHIELD = 1201;
	private static final int BATTLEAXE = 1373;

	@Test
	public void oneCast()
	{
		Assert.assertEquals(797, HighAlch.perCast(32_400, 103, 31_500));
		Assert.assertEquals(-203, HighAlch.perCast(400, 103, 500));
		Assert.assertTrue(HighAlch.known(32_400, 103, 31_500));
		Assert.assertFalse("does not alch", HighAlch.known(0, 103, 31_500));
		Assert.assertFalse("no rune price", HighAlch.known(32_400, 0, 31_500));
		Assert.assertFalse("no cost", HighAlch.known(32_400, 103, 0));
	}

	@Test
	public void figures()
	{
		Assert.assertEquals("+797", HighAlch.signed(797));
		Assert.assertEquals("-24,247", HighAlch.signed(-24_247));
		Assert.assertEquals("+0", HighAlch.signed(0));
		Assert.assertEquals("+15", HighAlch.compact(15));
		Assert.assertEquals("-999", HighAlch.compact(-999));
		Assert.assertEquals("+1K", HighAlch.compact(1_000));
		Assert.assertEquals("+24.2K", HighAlch.compact(24_247));
		Assert.assertEquals("-12.3K", HighAlch.compact(-12_300));
		Assert.assertEquals("+999.9K", HighAlch.compact(999_949));
		Assert.assertEquals("+1M", HighAlch.compact(999_950));
		Assert.assertEquals("+1.5M", HighAlch.compact(1_500_000));
	}

	/* ── The hover ─────────────────────────────────────────────────────── */

	/** Bought at 31,500, alchs for 32,400, a rune at 103: +797 a cast, in
	 *  green, with the sum; and alching beats selling at 32,000 (31,360
	 *  after tax) by 937. */
	@Test
	public void theHoverOnAStackYouBought()
	{
		final String t = BankHighlightOverlay.alchText(KITESHIELD, new long[]{100, 100L * 31_500, 32_000}, 32_400, 103);
		Assert.assertTrue(t, t.startsWith(TipStyle.BREAK + TipStyle.state(TipStyle.GOOD, "+797 gp ea to high alch")));
		Assert.assertTrue(t, t.contains(TipStyle.muted(" (32,400 - 103 rune - 31,500 paid)")));
		Assert.assertTrue(t, t.endsWith(TipStyle.BREAK + TipStyle.state(TipStyle.GOOD, "Alching beats selling by 937 gp ea")));
	}

	/** No buy on record: against the price it sells at, the sale alching
	 *  gives up. */
	@Test
	public void theHoverWithNoBuyOnRecord()
	{
		final String t = BankHighlightOverlay.alchText(BATTLEAXE, new long[]{0, 0, 24_000}, 24_960, 103);
		Assert.assertTrue(t, t.startsWith(TipStyle.BREAK + TipStyle.state(TipStyle.GOOD, "+857 gp ea to high alch")
			+ TipStyle.muted(" (24,960 - 103 rune - 24,000 price)")));
	}

	/** "have it only show a high alch profit if there is one, dont have it
	 *  say negative": a cast that loses, or only breaks even, says nothing. */
	@Test
	public void nothingWhenItDoesNotPay()
	{
		Assert.assertEquals("", BankHighlightOverlay.alchText(BATTLEAXE, new long[]{0, 0, 25_600}, 24_960, 103));
		Assert.assertEquals("even", "", BankHighlightOverlay.alchText(BATTLEAXE, new long[]{0, 0, 24_857}, 24_960, 103));
		Assert.assertEquals("a loss on what you paid, though it beats selling", "",
			BankHighlightOverlay.alchText(BATTLEAXE, new long[]{10, 10L * 30_000, 20_000}, 24_960, 103));
	}

	/** Nothing to say: nothing. */
	@Test
	public void theHoverSaysNothingItCannotWorkOut()
	{
		Assert.assertEquals("", BankHighlightOverlay.alchText(BATTLEAXE, new long[]{0, 0, 25_600}, 0, 103));
		Assert.assertEquals("", BankHighlightOverlay.alchText(BATTLEAXE, new long[]{0, 0, 25_600}, 24_960, 0));
		Assert.assertEquals("", BankHighlightOverlay.alchText(BATTLEAXE, new long[]{0, 0, 0}, 24_960, 103));
	}

	/** Both hovers carry it — the plain one and a marked stack's — behind
	 *  its own switch. */
	@Test
	public void bothHoversCarryIt() throws Exception
	{
		final String src = java.nio.file.Files.readString(
			java.nio.file.Path.of("src/main/java/com/pocketge/tracker/BankHighlightOverlay.java"))
			.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
		Assert.assertTrue(src.contains("hoverText(itemId, widgetItem.getQuantity(), h)\n\t\t\t\t+ alchFor(itemId, h) + batchesText"));
		Assert.assertTrue(src.contains("text += alchFor(itemId, h);"));
		Assert.assertTrue(src.contains("return alchOn && h != null && value != null ? alchText(itemId, h, value, naturePrice) : \"\";"));
	}

	/* ── The card ──────────────────────────────────────────────────────── */

	private static AdvisorPanel panel()
	{
		final AdvisorPanel.Actions actions = (AdvisorPanel.Actions) Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(proxy, method, args) ->
			{
				final Class<?> t = method.getReturnType();
				return t == boolean.class ? false : t.isPrimitive() ? (t == long.class ? (Object) 0L : (Object) 0) : null;
			});
		final AdvisorPanel p = new AdvisorPanel(null, actions);
		p.setAlch(Map.of(KITESHIELD, 32_400, BATTLEAXE, 24_960), 103);
		return p;
	}

	private static AdvisorPanel.Rec sell(int id, long price, long paid)
	{
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.sell = true;
		r.itemId = id;
		r.quantity = 130;
		r.unitPrice = price;
		r.unitCost = paid;
		r.hasTrackedCost = paid > 0;
		return r;
	}

	@Test
	public void theCardsCell() throws Exception
	{
		final AdvisorPanel p = panel();
		final AdvisorPanel.Card.Stat bought = p.alchStat(sell(KITESHIELD, 32_000, 31_500));
		Assert.assertEquals("ALCH EA", bought.label);
		Assert.assertEquals("+797", bought.value);
		Assert.assertEquals(TipStyle.GOOD, bought.valueColor);
		Assert.assertTrue(bought.tip, bought.tip.contains("+797 gp a high alch") && bought.tip.contains("31,500 you paid"));
		final AdvisorPanel.Card.Stat untracked = p.alchStat(sell(BATTLEAXE, 24_000, 0));
		Assert.assertEquals("against its price", "+857", untracked.value);
		Assert.assertTrue(untracked.tip, untracked.tip.contains("24,000 it sells for"));
		Assert.assertNull("nothing when it does not pay", p.alchStat(sell(BATTLEAXE, 25_600, 0)));
		Assert.assertNull("or only breaks even", p.alchStat(sell(BATTLEAXE, 24_857, 0)));
		Assert.assertNull("an item with no alch value", p.alchStat(sell(4151, 1_500_000, 0)));
		final Field f = AdvisorPanel.class.getDeclaredField("settings");
		f.setAccessible(true);
		((AdvisorPanel.Settings) f.get(p)).alchProfit = false;
		Assert.assertNull("switched off", p.alchStat(sell(KITESHIELD, 32_000, 31_500)));
	}

	/** Beside QUANTITY and VALUE when it fits, a tighter gap with three
	 *  across; a quantity in the millions crowds it out. */
	@Test
	public void itGoesWhereItFits()
	{
		final List<AdvisorPanel.Card.Stat> row = new ArrayList<>();
		row.add(new AdvisorPanel.Card.Stat("QUANTITY", "130", null));
		row.add(new AdvisorPanel.Card.Stat("VALUE", "81.6K gp", null));
		Assert.assertEquals(16, AdvisorPanel.statGap(row));
		row.add(new AdvisorPanel.Card.Stat("ALCH EA", "+24.2K", null));
		Assert.assertEquals(12, AdvisorPanel.statGap(row));
		Assert.assertTrue(AdvisorPanel.statsFit(row));
		row.set(0, new AdvisorPanel.Card.Stat("QUANTITY", "12,345,678", null));
		row.set(1, new AdvisorPanel.Card.Stat("VALUE", "467.8M gp", null));
		Assert.assertFalse(AdvisorPanel.statsFit(row));
	}

	private static boolean showsLabel(java.awt.Container root, String text)
