package com.pocketge.tracker;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import org.junit.Assert;
import org.junit.Test;

/**
 * Everything Guice has to build, it can actually build.
 *
 * This exists because of a bug that took the whole plugin off the sidebar and
 * that nothing else here could have caught. A constant was added to
 * BankHighlightOverlay directly above its constructor:
 *
 *     &#64;Inject
 *     private static final int GE_INVENTORY_GROUP = 467;    // &lt;- new
 *     private BankHighlightOverlay() { ... }
 *
 * The annotation belonged to the constructor. The new field silently took it,
 * and both halves of that are fatal: Guice refuses an &#64;Inject on a final
 * field, and with the constructor no longer annotated it cannot build a class
 * whose only constructor is private. The injector dies at startup with a
 * CreationException, RuneLite drops the plugin, and the panel is simply gone.
 *
 * It compiles. It type-checks. Every unit test passes. Java is perfectly happy
 * to put an annotation on the wrong declaration, and the offline type-check
 * cannot run Guice at all — the one place the mistake shows up is a real
 * client, which is the slowest and most expensive place to find anything.
 *
 * So the rules Guice enforces at startup are enforced here instead, walking
 * the same graph Guice walks: start at the plugin, follow every &#64;Inject
 * into our own package, and check what it finds.
 */
public class InjectionWiringTest
{
	private static final String PKG = "com.pocketge.tracker.";

	/**
	 * The classes Guice is actually asked to construct — the transitive
	 * closure of our own types reachable through injection points, which is
	 * exactly the set whose wiring can break startup. A class nothing injects
	 * is not Guice's problem and is not checked.
	 */
	private static Set<Class<?>> injected()
	{
		final Set<Class<?>> seen = new LinkedHashSet<>();
		final Deque<Class<?>> queue = new ArrayDeque<>();
		queue.add(PocketGeTrackerPlugin.class);
		while (!queue.isEmpty())
		{
			final Class<?> c = queue.poll();
			if (c.isInterface() || c.isPrimitive() || !seen.add(c))
			{
				continue;
			}
			for (Field f : c.getDeclaredFields())
			{
				if (f.isAnnotationPresent(Inject.class) && ours(f.getType()))
				{
					queue.add(f.getType());
				}
			}
			for (Constructor<?> k : c.getDeclaredConstructors())
			{
				if (!k.isAnnotationPresent(Inject.class))
				{
					continue;
				}
				for (Class<?> p : k.getParameterTypes())
				{
					if (ours(p))
					{
						queue.add(p);
					}
				}
			}
		}
		return seen;
	}

	private static boolean ours(Class<?> c)
	{
		return c.getName().startsWith(PKG);
	}

	/**
	 * Guice: "Injected field cannot be final", and a static field is only
	 * injected on an explicit requestStaticInjection, which nothing here
	 * does. Either way the annotation is not doing what its author meant.
	 *
	 * This is the half of the bug that fires loudest — a CreationException
	 * naming the field — and the half that is hardest to read as a typo,
	 * because the field it names is not the declaration anyone touched.
	 */
	@Test
	public void noInjectedFieldIsStaticOrFinal()
	{
		final List<String> bad = new ArrayList<>();
		for (Class<?> c : injected())
		{
			for (Field f : c.getDeclaredFields())
			{
				if (!f.isAnnotationPresent(Inject.class))
				{
					continue;
				}
				if (Modifier.isStatic(f.getModifiers()))
				{
					bad.add(c.getSimpleName() + "." + f.getName() + " is static"
						+ " — did it steal the @Inject from the declaration below it?");
				}
				if (Modifier.isFinal(f.getModifiers()))
				{
					bad.add(c.getSimpleName() + "." + f.getName() + " is final"
						+ " — Guice refuses this and the injector dies at startup");
				}
			}
		}
		Assert.assertEquals(String.join("\n", bad), List.of(), bad);
	}

	/**
	 * And the quiet half: a class Guice must build needs either one &#64;Inject
	 * constructor or a zero-argument constructor it is allowed to call. Lose
	 * the annotation off a private constructor and there is nothing left —
	 * which is how the overlay stopped being constructible without a single
	 * line of its own code changing.
	 */
	@Test
	public void everyInjectedClassIsConstructible()
	{
		final List<String> bad = new ArrayList<>();
		for (Class<?> c : injected())
		{
			final Constructor<?>[] ctors = c.getDeclaredConstructors();
			int annotated = 0;
			boolean usableNoArg = false;
			for (Constructor<?> k : ctors)
			{
				if (k.isAnnotationPresent(Inject.class))
				{
					annotated++;
				}
				if (k.getParameterCount() == 0 && !Modifier.isPrivate(k.getModifiers()))
				{
					usableNoArg = true;
				}
			}
			if (annotated > 1)
			{
				bad.add(c.getSimpleName() + " has " + annotated + " @Inject constructors"
					+ " — Guice allows exactly one");
			}
			else if (annotated == 0 && !usableNoArg)
			{
				bad.add(c.getSimpleName() + " has no @Inject constructor and no callable"
					+ " zero-arg one — Guice cannot build it");
			}
		}
		Assert.assertEquals(String.join("\n", bad), List.of(), bad);
	}

	/**
	 * The walk has to actually reach things, or the two tests above pass by
	 * checking nothing — which is the failure mode of every test that scans
	 * for problems rather than asserting a value.
	 */
	@Test
	public void theWalkReachesTheOverlays()
	{
		final Set<Class<?>> seen = injected();
		Assert.assertTrue("the overlay that broke is in the set",
			seen.contains(BankHighlightOverlay.class));
		Assert.assertTrue("and the other two overlays",
			seen.contains(GeOfferGridOverlay.class) && seen.contains(GeOfferPriceOverlay.class));
		Assert.assertTrue("and the market client", seen.contains(MarketClient.class));
		Assert.assertTrue("and the bank legend, which is injected into nothing else",
			seen.contains(BankLegendOverlay.class));
	}

	/**
	 * The stub's @Inject must be RUNTIME or none of the above reads anything.
	 * It was CLASS-retention once, which is silent: the scans find no
	 * annotations, report no problems, and pass.
	 */
	@Test
	public void theAnnotationIsVisibleToReflection()
	{
		int found = 0;
		for (Field f : PocketGeTrackerPlugin.class.getDeclaredFields())
		{
			if (f.isAnnotationPresent(Inject.class))
			{
				found++;
			}
		}
		Assert.assertTrue("@Inject is not visible at runtime — these tests are inert", found > 5);
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * "it flipped its focus off dragonstone bolt tips on our pocketge inspect
 * for some reason to uncut diamonds while i was making my trade".
 */
public class InspectHoldTest
{
	private static final int BOLT_TIPS = 9193;
	private static final int UNCUT_DIAMOND = 1617;

	private final List<Integer> selectionChanges = new ArrayList<>();

	private AdvisorPanel panel()
	{
		final AdvisorPanel.Actions actions = (AdvisorPanel.Actions) Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(proxy, method, args) ->
			{
				if ("onSelectedItemChanged".equals(method.getName()))
				{
					selectionChanges.add((Integer) args[0]);
				}
				final Class<?> t = method.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				if (t == int.class || t == long.class || t == double.class || t == float.class)
				{
					return 0;
				}
				return null;
			});
		return new AdvisorPanel(null, actions);
	}

	private static FavoritesPanel.Row row(int id, String name)
	{
		final FavoritesPanel.Row r = new FavoritesPanel.Row();
		r.id = id;
		r.name = name;
		return r;
	}

	/** A refresh built before the click — so without the inspected item —
	 *  arriving after it does not end the inspection. */
	@Test
	public void aRefreshFromBeforeTheClickLeavesTheCardUp()
	{
		final AdvisorPanel p = panel();
		p.setSelectedItem(row(BOLT_TIPS, "Dragonstone bolt tips"));
		p.refreshSelectedFrom(Collections.singletonList(row(UNCUT_DIAMOND, "Uncut diamond")));
		Assert.assertTrue("still inspecting the bolt tips", p.inspecting(BOLT_TIPS));
		Assert.assertFalse("the plugin was not told to stop", selectionChanges.contains(null));

		final FavoritesPanel.Row priced = row(BOLT_TIPS, "Dragonstone bolt tips");
		priced.heldQty = 11_000;
		p.refreshSelectedFrom(Collections.singletonList(priced));
		Assert.assertTrue(p.inspecting(BOLT_TIPS));
		Assert.assertEquals("and the next refresh fills it in", Boolean.TRUE, p.inspectSwapTarget(BOLT_TIPS));
	}

	/** The ✕ still ends it. */
	@Test
	public void theCloseButtonStillEndsIt()
	{
		final AdvisorPanel p = panel();
		p.setSelectedItem(row(BOLT_TIPS, "Dragonstone bolt tips"));
		p.setSelectedItem(null);
		Assert.assertFalse(p.inspecting(BOLT_TIPS));
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.io.File;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import org.junit.Assert;
import org.junit.Test;

/**
 * The flip ledger gets each flip once. Three writers — the startup rescue,
 * a flip's own append, and the retry of a failed one — each used to decide
 * for itself what was already in the file, and between them wrote flips
 * twice; a duplicate on disk is counted twice in All time for good.
 */
public class LedgerWriteTest
{
	private static void set(Object o, String field, Object v) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(o, v);
	}

	private static Object get(Object o, String field) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		return f.get(o);
	}

	/** Buy 100 Ruby at 1,800, sell at 2,000 in slot 1: one flip. */
	private static void flipRuby(FlipTracker t)
	{
		t.onOffer(1L, 0, 1603, "Ruby", true, 0, 0L, 1_800, 100, false);
		t.onOffer(2L, 0, 1603, "Ruby", true, 100, 180_000L, 1_800, 100, false);
		t.onOffer(2L, 0, 0, "", false, 0, 0L, 0, 0, true); // collected: a box's units are in no sell
		t.onOffer(3L, 1, 1603, "Ruby", false, 0, 0L, 2_000, 100, false);
		t.onOffer(4L, 1, 1603, "Ruby", false, 100, 200_000L, 2_000, 100, false);
	}

	private static long rubyRows(File file) throws Exception
	{
		return Files.readAllLines(file.toPath(), StandardCharsets.UTF_8).stream()
			.filter(l -> l.contains("\"itemName\":\"Ruby\"")).count();
	}

	/**
	 * A flip booked while the startup read is still waiting: the read's
	 * rescue writes it, and its own queued append must then skip it.
	 */
	@Test
	public void aFlipBookedDuringTheStartupReadIsWrittenOnce() throws Exception
	{
		final File dir = Files.createTempDirectory("pge-ledger").toFile();
		final File file = new File(dir, "flips.jsonl");
		final ScheduledThreadPoolExecutor ex = new ScheduledThreadPoolExecutor(1);
		try
		{
			final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
			set(plugin, "gson", new Gson());
			set(plugin, "executor", ex);
			/* An earlier flip, so the file is not empty and is not seeded. */
			Files.write(file.toPath(), (new Gson().toJson(new Flip(9, 1, 2, 1601, "Diamond", 1, 1, 2, 0)) + "\n")
				.getBytes(StandardCharsets.UTF_8));
			final CountDownLatch hold = new CountDownLatch(1);
			ex.execute(() ->
			{
				try
				{
					hold.await();
				}
				catch (InterruptedException ignore)
				{
				}
			});
			plugin.openLedger(file);
			flipRuby((FlipTracker) get(plugin, "tracker")); // the sink queues its append behind the read
			hold.countDown();
			ex.shutdown();
			Assert.assertTrue(ex.awaitTermination(10, TimeUnit.SECONDS));
			Assert.assertEquals("one Ruby row on disk", 1, rubyRows(file));
			@SuppressWarnings("unchecked")
			final List<Flip> cached = (List<Flip>) get(plugin, "ledgerFlips");
			Assert.assertEquals("and once in memory", 1, cached.stream().filter(f -> f.itemId == 1603).count());
		}
		finally
		{
			ex.shutdownNow();
		}
	}

	/** A crash mid-write leaves a line with no newline; the next record
	 *  starts a line of its own rather than being glued onto it. */
	@Test
	public void anAppendAfterATornLineStartsItsOwn() throws Exception
	{
		final File file = new File(Files.createTempDirectory("pge-ledger").toFile(), "flips.jsonl");
		Files.write(file.toPath(), "{\"offerId\":2,\"itemId\":16".getBytes(StandardCharsets.UTF_8));
		final FlipLedger ledger = new FlipLedger(file, new Gson());
		Assert.assertTrue(ledger.append(new Flip(4, 7, 10, 1603, "Ruby", 100, 180_000, 200_000, 4_000)));
		final List<Flip> read = ledger.readAll();
		Assert.assertEquals(1, read.size());
		Assert.assertEquals(1603, read.get(0).itemId);
	}
}

package com.pocketge.tracker;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPopupMenu;
import org.junit.Assert;
import org.junit.Test;

/**
 * "make it so you can select the color of these lists": the switcher that
 * lists them carries the palette as dots, for the list it is showing.
 */
public class ListColourTest
{
	private static double luminance(Color c)
	{
		final double[] ch = {c.getRed() / 255.0, c.getGreen() / 255.0, c.getBlue() / 255.0};
		for (int i = 0; i < 3; i++)
		{
			ch[i] = ch[i] <= 0.03928 ? ch[i] / 12.92 : Math.pow((ch[i] + 0.055) / 1.055, 2.4);
		}
		return 0.2126 * ch[0] + 0.7152 * ch[1] + 0.0722 * ch[2];
	}

	@Test
	public void everyColourHasANameAndReadsOnThePanel()
	{
		Assert.assertEquals(FavoriteLists.PALETTE.length, FavoriteLists.PALETTE_NAMES.length);
		Assert.assertEquals("distinct", FavoriteLists.PALETTE.length,
			new HashSet<>(java.util.Arrays.asList(FavoriteLists.PALETTE)).size());
		final double bg = luminance(Brand.BG_PANEL);
		for (int i = 0; i < FavoriteLists.PALETTE.length; i++)
		{
			final double fg = luminance(Color.decode(FavoriteLists.PALETTE[i]));
			/* The list's name is written in its colour. Purple, one of the
			   original seven, is the floor at about 3.7:1. */
			Assert.assertTrue(FavoriteLists.PALETTE_NAMES[i] + " too dark",
				(fg + 0.05) / (bg + 0.05) >= 3.5);
		}
	}

	@Test
	public void theOriginalSevenAreWhereTheyWere()
	{
		/* New lists are dealt from the front of the palette, and the first
		   list ever made is PALETTE[0]: reordering would change what a fresh
		   install looks like. */
		final String[] before = {"#E5C158", "#26A69A", "#EF5350", "#42A5F5", "#AB47BC", "#66BB6A", "#FF9F43"};
		for (int i = 0; i < before.length; i++)
		{
			Assert.assertEquals(before[i], FavoriteLists.PALETTE[i]);
		}
	}

	private static void collect(Container root, List<JLabel> out)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof JLabel && ((JLabel) c).getIcon() instanceof FavoritesPanel.Swatch)
			{
				out.add((JLabel) c);
			}
			if (c instanceof Container)
			{
				collect((Container) c, out);
			}
		}
	}

	private static FavoritesPanel panel(List<String> calls)
	{
		final FavoritesPanel.Actions actions = (FavoritesPanel.Actions) Proxy.newProxyInstance(
			FavoritesPanel.Actions.class.getClassLoader(), new Class<?>[]{FavoritesPanel.Actions.class},
			(p, m, a) ->
			{
				if (m.getName().equals("recolorList") || m.getName().equals("selectList")
					|| m.getName().equals("deleteList"))
				{
					calls.add(m.getName() + ":" + java.util.Arrays.toString(a));
				}
				final Class<?> r = m.getReturnType();
				return r == boolean.class ? (Object) false : r.isPrimitive() ? (Object) 0 : null;
			});
		return new FavoritesPanel(null, actions);
	}

	private static FavoritesPanel.ListMeta list(String id, String name, String colour)
	{
		final FavoritesPanel.ListMeta l = new FavoritesPanel.ListMeta();
		l.id = id;
		l.name = name;
		l.color = colour;
		return l;
	}

	private static void release(Component c, int button, int x)
	{
		c.dispatchEvent(new MouseEvent(c, MouseEvent.MOUSE_PRESSED, 0,
			button == MouseEvent.BUTTON1 ? java.awt.event.InputEvent.BUTTON1_DOWN_MASK : java.awt.event.InputEvent.BUTTON3_DOWN_MASK,
			x, 4, 1, button == MouseEvent.BUTTON3, button));
		c.dispatchEvent(new MouseEvent(c, MouseEvent.MOUSE_RELEASED, 0, 0, x, 4, 1, false, button));
	}

	/** "make it so you can do it from here": in the switcher a left-click
	 *  still switches lists, and a right-click does not — it is the list's
	 *  own menu. */
	@Test
	public void aRightClickInTheSwitcherIsTheListsMenuNotASwitch()
	{
		final List<String> calls = new ArrayList<>();
		final FavoritesPanel panel = panel(calls);
		final FavoritesPanel.ListMeta members = list("m", "Members", FavoriteLists.PALETTE[1]);
		panel.updateLists(List.of(list("f", "Favorites", FavoriteLists.PALETTE[0]), members), "f");
		final JPopupMenu switcher = new JPopupMenu();
		final FavoritesPanel.ListItem item = panel.new ListItem(members, false, switcher);
		item.setSize(item.getPreferredSize());

		release(item, MouseEvent.BUTTON3, 4);
		Assert.assertTrue("a right-click switches nothing: " + calls, calls.isEmpty());

		release(item, MouseEvent.BUTTON1, 4);
		Assert.assertEquals(List.of("selectList:[m]"), calls);
		Assert.assertTrue(item.getToolTipText().contains("right-click"));
	}

	@Test
	public void theListsMenuRenamesRecoloursAndDeletes()
	{
		final List<String> calls = new ArrayList<>();
		final FavoritesPanel panel = panel(calls);
		final FavoritesPanel.ListMeta members = list("m", "Members", FavoriteLists.PALETTE[1]);
		panel.updateLists(List.of(list("f", "Favorites", FavoriteLists.PALETTE[0]), members), "f");
		final JPopupMenu menu = panel.listMenu(members);
		final List<String> labels = new ArrayList<>();
		javax.swing.JMenu colour = null;
		javax.swing.JMenuItem delete = null;
		for (Component c : menu.getComponents())
		{
			if (c instanceof javax.swing.JMenuItem)
			{
				final javax.swing.JMenuItem mi = (javax.swing.JMenuItem) c;
				labels.add(mi.getText());
				if (mi instanceof javax.swing.JMenu)
				{
					colour = (javax.swing.JMenu) mi;
				}
				else if (mi.getText().startsWith("Delete"))
				{
					delete = mi;
				}
			}
		}
		Assert.assertEquals(List.of("Rename list…", "Colour", "Delete list…"), labels);
		Assert.assertEquals(FavoriteLists.PALETTE.length, colour.getItemCount());
		colour.getItem(7).doClick();
		Assert.assertEquals(List.of("recolorList:[m, " + FavoriteLists.PALETTE[7] + "]"), calls);
		Assert.assertTrue("two lists, so either can go", delete.isEnabled());

		panel.updateLists(List.of(members), "m");
		javax.swing.JMenuItem only = null;
		for (Component c : panel.listMenu(members).getComponents())
		{
			if (c instanceof javax.swing.JMenuItem && ((javax.swing.JMenuItem) c).getText().startsWith("Delete"))
			{
				only = (javax.swing.JMenuItem) c;
			}
		}
		Assert.assertFalse("the last list stays", only.isEnabled());
	}

	@Test
	public void aDotRecoloursTheListShownAndMarksItsOwn()
	{
		final List<String> calls = new ArrayList<>();
		final FavoritesPanel.Actions actions = (FavoritesPanel.Actions) Proxy.newProxyInstance(
			FavoritesPanel.Actions.class.getClassLoader(), new Class<?>[]{FavoritesPanel.Actions.class},
			(p, m, a) ->
			{
				if (m.getName().equals("recolorList"))
				{
					calls.add(a[0] + "=" + a[1]);
				}
				final Class<?> r = m.getReturnType();
				return r == boolean.class ? (Object) false : r.isPrimitive() ? (Object) 0 : null;
			});
		final FavoritesPanel panel = new FavoritesPanel(null, actions);
		final FavoritesPanel.ListMeta members = new FavoritesPanel.ListMeta();
		members.id = "m";
		members.name = "Members";
		members.color = FavoriteLists.PALETTE[1];

		final JPopupMenu menu = new JPopupMenu();
		final Container row = panel.colourRow(members, menu);
		final List<JLabel> dots = new ArrayList<>();
		collect(row, dots);
		Assert.assertEquals(FavoriteLists.PALETTE.length, dots.size());
		for (int i = 0; i < dots.size(); i++)
		{
			Assert.assertEquals("only the list's own colour is ringed", i == 1,
				((FavoritesPanel.Swatch) dots.get(i).getIcon()).current());
			Assert.assertEquals(FavoriteLists.PALETTE_NAMES[i], dots.get(i).getToolTipText());
		}

		final JLabel pink = dots.get(7);
		pink.setSize(pink.getPreferredSize());
		for (MouseListener l : pink.getMouseListeners())
		{
			l.mouseReleased(new MouseEvent(pink, MouseEvent.MOUSE_RELEASED, 0, 0, 4, 4, 1, false, MouseEvent.BUTTON1));
		}
		Assert.assertEquals(List.of("m=" + FavoriteLists.PALETTE[7]), calls);

		/* A release that drifted off the dot is not a choice. */
		calls.clear();
		for (MouseListener l : pink.getMouseListeners())
		{
			l.mouseReleased(new MouseEvent(pink, MouseEvent.MOUSE_RELEASED, 0, 0, 400, 4, 1, false, MouseEvent.BUTTON1));
		}
		Assert.assertTrue(calls.isEmpty());
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * A buy offer that fills at a loss is flagged, with a bid that stops it.
 *
 * From a live screen: 10,000 Mithril bars bid at 876 while the price they
 * sell back at had fallen to 888 — 871 after tax. Every bar bought lost
 * 5 gp, the box said "Profit if it flips: -50K gp", and the slot stayed
 * green. "it should turn the box ... notifying me to adjust the price to a
 * price that makes this a profitable trade again ... or at least try that
 * price ... to make it at least +0".
 */
public class LosingBuyTest
{
	private static final int MITHRIL_BAR = 2359;
	private static final long NOW = 1_800_000_000L;

	private static Advisor.OfferView buy(long price, int total, int sold)
	{
		final Advisor.OfferView o = new Advisor.OfferView();
		o.slot = 0;
		o.itemId = MITHRIL_BAR;
		o.itemName = "Mithril bar";
		o.buy = true;
		o.price = price;
		o.totalQuantity = total;
		o.quantitySold = sold;
		o.active = true;
		return o;
	}

	private static Advisor.Quote quote(long low, long high)
	{
		final Advisor.Quote q = new Advisor.Quote();
		q.low = low;
		q.high = high;
		q.lowTime = NOW - 60;
		q.highTime = NOW - 60;
		return q;
	}

	/** The reported case, with no price series: the exit is the insta-buy,
	 *  and the most that can be bid for +0 is 888 less 17 tax. */
	@Test
	public void theMithrilBarBidIsFlaggedAndToldItsBreakEven()
	{
		final Advisor.Suggestion s = Advisor.losingBuy(buy(876, 10_000, 3_738), quote(870, 888), null, NOW);
		Assert.assertNotNull(s);
		Assert.assertTrue(s.losing);
		Assert.assertEquals(Advisor.Suggestion.Type.ADJUST_BUY, s.type);
		Assert.assertEquals(871, s.breakEven);
		Assert.assertEquals("with nothing better, the break-even", 871, s.price);
		Assert.assertEquals("on what is left to buy", 10_000 - 3_738, s.quantity);
		Assert.assertEquals(0, s.slot);
	}

	/** With the engine, its target buy wins when it still makes something:
	 *  the best price it can find, with break-even as the ceiling. */
	@Test
	public void theEnginesTargetBuyWinsWhenItStillProfits()
	{
		final TradeEngine.Result eng = new TradeEngine.Result(860, 888, true, "ok", 11, false);
		final Advisor.Suggestion s = Advisor.losingBuy(buy(876, 10_000, 0), quote(870, 900), eng, NOW);
		Assert.assertNotNull(s);
		Assert.assertEquals("measured against the engine's sell, not the insta-buy", 871, s.breakEven);
		Assert.assertEquals(860, s.price);
	}

	/** At the break-even it is +0 — the "at least" the player asked for —
	 *  and that is left alone. */
	@Test
	public void breakEvenIsLeftAlone()
	{
		Assert.assertNull(Advisor.losingBuy(buy(871, 10_000, 0), quote(870, 888), null, NOW));
		Assert.assertNull(Advisor.losingBuy(buy(860, 10_000, 0), quote(850, 888), null, NOW));
	}

	@Test
	public void sellsAreNotThisCheck()
	{
		final Advisor.OfferView o = buy(876, 10_000, 0);
		o.buy = false;
		Assert.assertNull(Advisor.losingBuy(o, quote(870, 888), null, NOW));
	}

	/** No series and a stale insta-buy: nothing honest to measure against. */
	@Test
	public void aStaleExitSaysNothing()
	{
		final Advisor.Quote q = quote(870, 888);
		q.highTime = NOW - 6 * 60 * 60;
		Assert.assertNull(Advisor.losingBuy(buy(876, 10_000, 0), q, null, NOW));
	}

	/** And advise() itself carries it, with the slot, so the box goes amber. */
	@Test
	public void adviseRaisesIt()
	{
		final java.util.Map<Integer, Advisor.Quote> quotes = new java.util.HashMap<>();
		quotes.put(MITHRIL_BAR, quote(870, 888));
		final java.util.List<Advisor.Suggestion> out = Advisor.advise(NOW, quotes, new java.util.HashMap<>(),
			0, new java.util.HashMap<>(), java.util.List.of(buy(876, 10_000, 3_738)),
			new java.util.HashSet<>(), new java.util.HashSet<>(), 0, 0.01, 0, null, null, 0);
		Assert.assertTrue(out.stream().anyMatch(s -> s.losing && s.slot == 0 && s.price == 871));
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * How long the plugin stays away from the wiki after being told to.
 *
 * Before this a refusal changed nothing: the next cycle asked again on
 * schedule and every per-item loop carried on through its list, each request
 * refused in turn. The OSRS Wiki has started naming tools whose traffic it
 * has to absorb, and a client that ignores "too many requests" is the kind it
 * names.
 */
public class MarketBackoffTest
{
	private static final long MIN = 60_000;

	/** A minute first, doubling with each refusal in a row. */
	@Test
	public void doublesFromAMinute()
	{
		Assert.assertEquals(MIN, MarketClient.backoffMs(0, null, 0));
		Assert.assertEquals(2 * MIN, MarketClient.backoffMs(1, null, 0));
		Assert.assertEquals(4 * MIN, MarketClient.backoffMs(2, null, 0));
		Assert.assertEquals(16 * MIN, MarketClient.backoffMs(4, null, 0));
	}

	/** And stops at half an hour, however long the refusals go on. */
	@Test
	public void capsAtHalfAnHour()
	{
		Assert.assertEquals(30 * MIN, MarketClient.backoffMs(5, null, 0));
		Assert.assertEquals(30 * MIN, MarketClient.backoffMs(40, null, 0));
		Assert.assertEquals("no overflow from a huge streak",
			30 * MIN, MarketClient.backoffMs(Integer.MAX_VALUE, null, 0));
	}

	/** The server's own number wins when it gives one in seconds. */
	@Test
	public void honoursRetryAfter()
	{
		Assert.assertEquals(120_000, MarketClient.backoffMs(0, "120", 0));
		Assert.assertEquals("even on a long streak", 5_000, MarketClient.backoffMs(9, " 5 ", 0));
	}

	/** Within reason: a Retry-After of a day is held to an hour. */
	@Test
	public void capsRetryAfterAtAnHour()
	{
		Assert.assertEquals(60 * MIN, MarketClient.backoffMs(0, "86400", 0));
	}

	/** An HTTP-date, a zero or garbage falls back to the doubling rather
	 *  than to no wait at all. */
	@Test
	public void unreadableRetryAfterStillWaits()
	{
		Assert.assertEquals(MIN, MarketClient.backoffMs(0, "Wed, 21 Oct 2026 07:28:00 GMT", 0));
		Assert.assertEquals(MIN, MarketClient.backoffMs(0, "0", 0));
		Assert.assertEquals(2 * MIN, MarketClient.backoffMs(1, "soon", 0));
	}

	/** Up to a fifth more at random, so clients refused together do not all
	 *  come back on the same second. Never less than the base. */
	@Test
	public void spreadsClientsOut()
	{
		Assert.assertEquals(MIN, MarketClient.backoffMs(0, null, 0));
		Assert.assertEquals(MIN + MIN / 10, MarketClient.backoffMs(0, null, 0.5));
		Assert.assertTrue(MarketClient.backoffMs(0, null, 0.999) < MIN + MIN / 5 + 1);
		Assert.assertEquals("a bad random number cannot shorten the wait",
			MIN, MarketClient.backoffMs(0, null, -3));
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.net.InetAddress;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Assert;
import org.junit.Test;

/**
 * A chart request sent to the open tab after RuneLite restarts.
 *
 * Reported as "right clicking in bank to open graph doesn't work. the
 * website doesn't open. it works if you click the graph button on the
 * inspect". The chat said the item was sent; the tab did nothing. The tab
 * had outlived the restart and remembered the old run's request number, and
 * the new run counted from 1 again, so everything it sent looked old.
 */
public class NavSeqTest
{
	private static long click(PocketGeTrackerPlugin plugin) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField("navSeq");
		f.setAccessible(true);
		return ((AtomicLong) f.get(plugin)).incrementAndGet();
	}

	/** A run's first request is above everything the run before it sent. */
	@Test
	public void aNewRunCountsOnFromTheLast() throws Exception
	{
		final PocketGeTrackerPlugin before = new PocketGeTrackerPlugin();
		long last = 0;
		for (int i = 0; i < 20; i++)
		{
			last = click(before);
		}
		Thread.sleep(30);
		final PocketGeTrackerPlugin after = new PocketGeTrackerPlugin();
		Assert.assertTrue(click(after) > last);
	}

	/** And the tab's wait for the next click, asked with the old run's
	 *  number, is answered by the new run's request. */
	@Test
	public void theOpenTabHearsTheNewRun() throws Exception
	{
		final PocketGeTrackerPlugin before = new PocketGeTrackerPlugin();
		final long tabRemembers = click(before);
		Thread.sleep(5);
		final PocketGeTrackerPlugin after = new PocketGeTrackerPlugin();

		final LocalBridgeServer bridge = new LocalBridgeServer(new Gson());
		bridge.start(0, HashMap::new, HashMap::new, null, null);
		try
		{
			final long seq = click(after);
			bridge.publishNav(new LocalBridgeServer.NavRequest(seq, "Ring of nature", 0, System.currentTimeMillis()));
			final long t0 = System.currentTimeMillis();
			final String got = get(bridge.port(), "/nav?since=" + tabRemembers);
			Assert.assertTrue(got, got.contains("Ring of nature"));
			Assert.assertTrue(got, got.contains("\"seq\":" + seq));
			Assert.assertTrue("answered at once, not after the 25s wait",
				System.currentTimeMillis() - t0 < 5_000);
		}
		finally
		{
			bridge.stop();
		}
	}

	private static String get(int port, String path) throws Exception
	{
		try (Socket s = new Socket(InetAddress.getLoopbackAddress(), port))
		{
			s.setSoTimeout(10_000);
			final String req = "GET " + path + " HTTP/1.1\r\n"
				+ "Host: 127.0.0.1:" + port + "\r\n"
				+ "Origin: https://pocketge.com\r\n"
				+ "Connection: close\r\n\r\n";
			final OutputStream out = s.getOutputStream();
			out.write(req.getBytes(StandardCharsets.UTF_8));
			out.flush();
			final InputStream in = s.getInputStream();
			final ByteArrayOutputStream got = new ByteArrayOutputStream();
			final byte[] buf = new byte[4096];
			int n;
			try
			{
				while ((n = in.read(buf)) > 0)
				{
					got.write(buf, 0, n);
					final String sofar = got.toString(StandardCharsets.UTF_8);
					if (sofar.contains("navRequest") && sofar.trim().endsWith("}"))
					{
						break;
					}
				}
			}
			catch (java.net.SocketTimeoutException done)
			{
				// what arrived is the answer
			}
			return got.toString(StandardCharsets.UTF_8);
		}
	}
}

package com.pocketge.tracker;

import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.swing.JButton;
import org.junit.Assert;
import org.junit.Test;

/**
 * "why sometimes flip rating and sometimes not": only the first few flip
 * ideas got a price series from the round, so the card after them showed
 * the last two prints and no rating. The panel hands on the two cards after
 * the one on screen as it changes, so their series are asked for before
 * they are paged to.
 */
public class NextCardTest
{
	private static final int A = 811;
	private static final int B = 4694;
	private static final int C = 565;
	private static final int X = 1601;

	/** Every handful of cards ahead handed on, in order. */
	private final List<List<Integer>> aheads = new ArrayList<>();

	private AdvisorPanel panel()
	{
		final AdvisorPanel.Actions actions = (AdvisorPanel.Actions) Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(proxy, method, args) ->
			{
				if ("onCardsAhead".equals(method.getName()))
				{
					@SuppressWarnings("unchecked")
					final List<Integer> ids = (List<Integer>) args[0];
					aheads.add(ids);
				}
				final Class<?> t = method.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				if (t == int.class || t == long.class || t == double.class || t == float.class)
				{
					return 0;
				}
				return null;
			});
		return new AdvisorPanel(null, actions);
	}

	private static AdvisorPanel.Rec buy(int id)
	{
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.itemId = id;
		r.name = "Item " + id;
		r.sell = false;
		r.quantity = 1_000;
		r.unitPrice = 100;
		r.profit = 50_000;
		return r;
	}

	private static List<AdvisorPanel.Rec> list(int... ids)
	{
		final List<AdvisorPanel.Rec> out = new ArrayList<>();
		Arrays.stream(ids).forEach(id -> out.add(buy(id)));
		return out;
	}

	private static JButton next(Container root)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof JButton)
			{
				final String tip = ((JButton) c).getToolTipText();
				if (tip != null && tip.contains("Next suggestion"))
				{
					return (JButton) c;
				}
			}
			if (c instanceof Container)
			{
				final JButton found = next((Container) c);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	/** The two cards after the one on screen, as the card moves — round to
	 *  the first from the last, where Next goes. */
	@Test
	public void theCardsAheadAreHandedOnAsTheCardMoves()
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(list(A, B, C, X));
		Assert.assertEquals(List.of(List.of(B, C)), aheads);
		next(p).doClick();
		next(p).doClick();
		next(p).doClick();
		Assert.assertEquals(List.of(List.of(B, C), List.of(C, X), List.of(X, A), List.of(A, B)), aheads);
	}

	/** As they change, with the card or under it: a round that re-ranks
	 *  what follows the card, or an idea ahead turned down, hands on the new
	 *  ones; a rebuild that changes nothing says nothing. */
	@Test
	public void wheneverTheyChange()
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(list(A, B, C, X));
		p.setRecommendations(list(A, B, C, X));
		Assert.assertEquals(List.of(List.of(B, C)), aheads);
		p.setRecommendations(list(A, C, X));
		Assert.assertEquals(List.of(List.of(B, C), List.of(C, X)), aheads);
	}

	/** Fewer cards, fewer ahead; none after the only one; the same item
	 *  twice (a buy and a sell) once. */
	@Test
	public void asManyAsThereAre()
	{
		Assert.assertEquals(List.of(B), AdvisorPanel.cardsAhead(list(A, B), 0));
		Assert.assertEquals(List.of(), AdvisorPanel.cardsAhead(list(A), 0));
		final List<AdvisorPanel.Rec> both = list(A, B, C);
		final AdvisorPanel.Rec sellB = buy(B);
		sellB.sell = true;
		both.add(2, sellB);
		Assert.assertEquals(List.of(B, C), AdvisorPanel.cardsAhead(both, 0));
		Assert.assertEquals("not the card itself", List.of(C, A), AdvisorPanel.cardsAhead(both, 1));
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * Reading the Grand Exchange's own "N coins" readouts.
 *
 * The gold ring walks price -> quantity -> Confirm by asking whether the
 * running total the screen shows is target x quantity. That test used to
 * strip every non-digit from the line and parse the remainder as one number,
 * which works on a buy and cannot work on a sell: the Exchange prints a
 * sell's total NET of the 2% tax and puts the gross and the rate in brackets
 * after it.
 *
 * So the ring reached Confirm on a buy and stuck on the quantity control on a
 * sell no matter how complete the offer was — "it should be highlighting the
 * confirm now in this example. i already selected price and quantity".
 */
public class OfferReadoutTest
{
	/** The string that broke it, verbatim from the offer screen. */
	private static final String SELL_TOTAL = "8,502,000 coins (8,658,000 - 2%)";

	@Test
	public void findsTheGrossOnASellTotal()
	{
		Assert.assertTrue("the gross, which is target x quantity",
			GeOfferPriceOverlay.textShowsValue(SELL_TOTAL, 8_658_000L));
	}

	/** The old rule's actual output, pinned so nobody reinvents it. */
	@Test
	public void doesNotConcatenateEveryDigitOnTheLine()
	{
		Assert.assertFalse("850200086580002 is not a number on this screen",
			GeOfferPriceOverlay.textShowsValue(SELL_TOTAL, 850_200_086_580_002L));
	}

	/** The net is on the line too, and is a real number on it. */
	@Test
	public void findsTheNetAsWell()
	{
		Assert.assertTrue(GeOfferPriceOverlay.textShowsValue(SELL_TOTAL, 8_502_000L));
	}

	/** A buy has no bracket and never did break. */
	@Test
	public void stillReadsAPlainBuyTotal()
	{
		Assert.assertTrue(GeOfferPriceOverlay.textShowsValue("8,658,000 coins", 8_658_000L));
		Assert.assertTrue(GeOfferPriceOverlay.textShowsValue("333 coins", 333L));
	}

	/** And it is exact: a total that merely contains the digits is not a
	 *  match, or the ring would advance on a number nobody entered. */
	@Test
	public void doesNotMatchASubstringOfANumber()
	{
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue("8,658,000 coins", 658L));
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue("8,658,000 coins", 8_658L));
	}

	@Test
	public void refusesTheDegenerateCases()
	{
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue(null, 100L));
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue("100 coins", 0L));
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue("100 coins", -5L));
		Assert.assertFalse("no digits at all",
			GeOfferPriceOverlay.textShowsValue("Enter price", 100L));
	}

	/**
	 * A run of digits far too long to be gp does not throw — it is skipped and
	 * the scan carries on to the numbers that matter.
	 */
	@Test
	public void survivesANumberTooBigForALong()
	{
		Assert.assertTrue(GeOfferPriceOverlay.textShowsValue(
			"99999999999999999999999 coins (333 - 2%)", 333L));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * The requests the sidebar makes on its own, between the advisor's rounds:
 * one per pick, an old series on the offer screen asked for afresh, and a
 * favourite's hourly series as soon as its row finds it missing.
 */
public class OnDemandFetchTest
{
	private PocketGeTrackerPlugin plugin;
	private boolean advisorOn = true;
	private boolean aheadOn = true;
	private final List<Runnable> queued = new ArrayList<>();
	private final List<Integer> fetched = new ArrayList<>();
	private final List<Integer> failing = new ArrayList<>();
	private boolean backOff;
	private int asked;

	private void set(String field, Object value) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private Object get(String field) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private void runQueued()
	{
		while (!queued.isEmpty())
		{
			queued.remove(0).run();
		}
	}

	private static String source() throws Exception
	{
		return java.nio.file.Files.readString(
			java.nio.file.Path.of("src/main/java/com/pocketge/tracker/PocketGeTrackerPlugin.java"))
			.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
	}

	@Before
	public void wire() throws Exception
	{
		plugin = new PocketGeTrackerPlugin();
		set("running", true);
		set("loggedIn", true);
		set("config", Proxy.newProxyInstance(PocketGeTrackerConfig.class.getClassLoader(),
			new Class<?>[]{PocketGeTrackerConfig.class}, (proxy, m, args) ->
			{
				if ("advisor".equals(m.getName()))
				{
					return advisorOn;
				}
				if ("priceNextCard".equals(m.getName()))
				{
					return aheadOn;
				}
				final Class<?> r = m.getReturnType();
				return r == boolean.class ? false : r.isPrimitive() ? 0 : null;
			}));
		set("executor", Proxy.newProxyInstance(ScheduledExecutorService.class.getClassLoader(),
			new Class<?>[]{ScheduledExecutorService.class}, (proxy, m, args) ->
			{
				if ("execute".equals(m.getName()))
				{
					queued.add((Runnable) args[0]);
				}
				final Class<?> r = m.getReturnType();
				return r == boolean.class ? false : r.isPrimitive() ? 0 : null;
			}));
		set("marketClient", new MarketClient(null, null)
		{
			@Override
			public TradeEngine.Series fetchTimeseries5m(int itemId)
			{
				fetched.add(itemId);
				return new TradeEngine.Series();
			}

			@Override
			public PriceExtremes fetchRecentExtremes(int itemId) throws java.io.IOException
			{
				asked++;
				if (backOff)
				{
					throw new MarketClient.BackingOff(60_000);
				}
				fetched.add(itemId);
				if (failing.contains(itemId))
				{
					throw new java.io.IOException("Wiki said no");
				}
				return new PriceExtremes();
			}
		});
		plugin.rebuildCards = () -> { };
		plugin.repriceOffer = id -> { };
	}

	/* ── One request per pick ─────────────────────────────────────────── */

	/** A pick from search, the finder or the GE slots calls
	 *  onSelectedItemChanged twice — inspectItem, then setSelectedItem — and
	 *  each sent its own request. It asks through the shared attempt clock
	 *  now, and asks for nothing else. */
	@Test
	public void aPickAsksThroughTheSharedClock() throws Exception
	{
		final String src = source();
		final int at = src.indexOf("public void onSelectedItemChanged(Integer itemId)");
		Assert.assertTrue(at > 0);
		final String body = src.substring(at, src.indexOf("@Override", at));
		Assert.assertTrue(body, body.contains("requestSharedSeries(itemId);"));
		Assert.assertFalse(body, body.contains("fetchTimeseries5m"));
		Assert.assertFalse(body, body.contains("execute("));
	}

	@Test
	public void twoAsksForOnePickSendOneRequest() throws Exception
	{
		final Method ask = PocketGeTrackerPlugin.class.getDeclaredMethod("requestSharedSeries", int.class);
		ask.setAccessible(true);
		ask.invoke(plugin, 4151);
		ask.invoke(plugin, 4151);
		runQueued();
		Assert.assertEquals(List.of(4151), fetched);
	}

	/** The cards ahead of the one on screen are asked for when the cards
	 *  have no series for them — and not when they do, or with the setting
	 *  off. */
	@Test
	public void theCardsAheadAreFetchedWhenTheCardsHaveNone() throws Exception
	{
		carded(4151, new TradeEngine.Series());
		plugin.noteCardsAhead(List.of(4151, 11802));
		runQueued();
		Assert.assertEquals(List.of(11802), fetched);
		Assert.assertTrue(((Map<?, ?>) get("selectedSeries")).containsKey(11802));
		aheadOn = false;
		plugin.noteShownCard(1, false); // a new card: a new budget
		plugin.noteCardsAhead(List.of(1513));
		plugin.noteCardsAhead(null);
		Assert.assertTrue("off: nothing asked", queued.isEmpty());
	}

	/** Two requests for each card shown, however the list changes under it:
	 *  ideas ahead turned down one after another asked again landing after
	 *  landing. A new card, a new two. */
	@Test
	public void twoForEachCardShown() throws Exception
	{
		plugin.noteShownCard(1, false);
		plugin.noteCardsAhead(List.of(11, 12));
		plugin.noteCardsAhead(List.of(13, 14)); // both turned down
		plugin.noteCardsAhead(List.of(16, 17)); // and those
		runQueued();
		Assert.assertEquals(List.of(11, 12), fetched);
		plugin.noteShownCard(13, false);
		plugin.noteCardsAhead(List.of(14, 15));
		runQueued();
		Assert.assertEquals(List.of(11, 12, 14, 15), fetched);
	}

	/** The round keeps them current after that; switching the setting on
	 *  asks for the ones ahead now. */
	@Test
	public void theRoundKeepsThemAndTheSwitchAsks() throws Exception
	{
		final String src = source();
		final int at = src.indexOf("final Integer shownSell = shownSellItemId;");
		Assert.assertTrue(src.substring(at, at + 900).matches("(?s).*if \\(config\\.priceNextCard\\(\\)\\)\\s*\\{\\s*ids\\.addAll\\(cardsAheadIds\\);"
			+ "\\s*final Integer shownCard = shownCardItemId;\\s*if \\(shownCard != null\\)\\s*\\{\\s*ids\\.add\\(shownCard\\);.*"));
		Assert.assertTrue(src.contains("case \"priceNextCard\":"));
		plugin.noteShownCard(1, false);
		aheadOn = false;
		plugin.noteCardsAhead(List.of(11, 12));
		aheadOn = true;
		final java.lang.reflect.Field budget = PocketGeTrackerPlugin.class.getDeclaredField("aheadBudgetCard");
		budget.setAccessible(true);
		budget.set(plugin, null);
		plugin.noteCardsAhead((List<Integer>) get("cardsAheadIds"));
		runQueued();
		Assert.assertEquals(List.of(11, 12), fetched);
	}

	/** The round, run for real: the card on screen and the two ahead of it
	 *  are among what it fetches with the setting on — a card ahead the
	 *  round priced went raw once it was paged to — and not with it off. */
	@Test
	public void theRoundFetchesTheCardOnScreenAndTheCardsAhead() throws Exception
	{
		final java.lang.reflect.Method round = PocketGeTrackerPlugin.class.getDeclaredMethod("refreshOfferSeries");
		round.setAccessible(true);
		plugin.noteShownCard(20011, false);
		plugin.noteCardsAhead(List.of(20012, 20013));
		queued.clear(); // their own fetches not landed: the round has nothing to reuse
		round.invoke(plugin);
		runQueued();
		Assert.assertEquals(new java.util.HashSet<>(List.of(20011, 20012, 20013)), new java.util.HashSet<>(fetched));
		fetched.clear();
		((Map<?, ?>) get("lastOfferSeries")).clear();
		((Map<?, ?>) get("offerSeriesFetchedAt")).clear();
		((Map<?, ?>) get("selectedSeries")).clear();
		set("selectedSeries", new java.util.HashMap<>());
		aheadOn = false;
		round.invoke(plugin);
		runQueued();
		Assert.assertTrue(fetched.toString(), fetched.isEmpty());
	}

	/** While a card is ahead it keeps the series it is priced from: read one
	 *  card for a quarter of an hour and the next went back to the last two
	 *  prints. Not one the cards had already dropped; and not once it is no
	 *  longer ahead. Nor is it evicted meanwhile. */
	@Test
	public void aCardAheadKeepsItsSeries() throws Exception
	{
		final Method pricing = PocketGeTrackerPlugin.class.getDeclaredMethod("pricingSeries", long.class);
		pricing.setAccessible(true);
		final TradeEngine.Series ahead = new TradeEngine.Series();
		held(11802, ahead, 20 * 60_000L);
		carded(11802, ahead);
		plugin.noteCardsAhead(List.of(11802));
		Assert.assertSame(ahead, ((Map<?, ?>) pricing.invoke(plugin, System.currentTimeMillis())).get(11802));
		carded(11802, null);
		Assert.assertNull("dropped before: not brought back",
			((Map<?, ?>) pricing.invoke(plugin, System.currentTimeMillis())).get(11802));
		carded(11802, ahead);
		plugin.noteCardsAhead(List.of());
		Assert.assertNull("no longer ahead",
			((Map<?, ?>) pricing.invoke(plugin, System.currentTimeMillis())).get(11802));
		final Method cache = PocketGeTrackerPlugin.class.getDeclaredMethod("cacheOnDemandSeries", int.class,
			TradeEngine.Series.class);
		cache.setAccessible(true);
		plugin.noteCardsAhead(List.of(997));
		cache.invoke(plugin, 997, new TradeEngine.Series());
		for (int id = 1; id <= 40; id++)
		{
			Thread.sleep(1);
			cache.invoke(plugin, id, new TradeEngine.Series());
		}
		Assert.assertTrue("not evicted while ahead", ((Map<?, ?>) get("selectedSeries")).containsKey(997));
	}

	/** An idea the engine turned down stays off the list once its series is
	 *  gone, rather than coming straight back raw as the card after the one
	 *  being read: the list under it flipped every few minutes. It does not
	 *  lapse back raw; past the hour its series is asked for — once an hour,
	 *  logged in only — and it stays off until that lands. A yes clears it. */
	@Test
	public void aTurnedDownIdeaStaysOffUntilJudgedAgain() throws Exception
	{
		final TradeEngine.Result no = new TradeEngine.Result(1000, 1010, false, "thin", 0, false);
		final TradeEngine.Result yes = new TradeEngine.Result(1000, 1100, true, "", 78, false);
		final long cash = 10_000_000;
		final long hour = PocketGeTrackerPlugin.TURNED_DOWN_MEMORY_MS;
		final long t0 = System.currentTimeMillis();
		Assert.assertFalse("never judged", plugin.turnedDownLately(20011, null, cash, t0));
		plugin.noteVerdict(20011, no, cash, t0);
		Assert.assertTrue("no series now, turned down a moment ago", plugin.turnedDownLately(20011, null, cash, t0 + 1));
		Assert.assertTrue("nothing asked yet", queued.isEmpty());
		Assert.assertTrue("past the hour: still off", plugin.turnedDownLately(20011, null, cash, t0 + hour));
		Assert.assertEquals("and asked for again", 1, queued.size());
		((Map<?, ?>) get("geSeriesAttemptAt")).clear(); // a minute on, on the shared clock's real time
		Assert.assertTrue(plugin.turnedDownLately(20011, null, cash, t0 + hour + 61_000));
		Assert.assertEquals("once an hour, not once a minute", 1, queued.size());
		((Map<?, ?>) get("geSeriesAttemptAt")).clear(); // the shared clock runs on real time: an hour on
		Assert.assertTrue(plugin.turnedDownLately(20011, null, cash, t0 + 2 * hour));
		Assert.assertEquals(2, queued.size());
		Assert.assertFalse("a series to judge it by", plugin.turnedDownLately(20011, no, cash, t0 + 1));
		plugin.noteVerdict(20011, yes, cash, t0 + 2);
		Assert.assertFalse("a yes clears it", plugin.turnedDownLately(20011, null, cash, t0 + 3));
		plugin.noteVerdict(20012, null, cash, t0);
		Assert.assertFalse("no series, no verdict to remember", plugin.turnedDownLately(20012, null, cash, t0 + 1));
		set("loggedIn", false);
		plugin.noteVerdict(20013, no, cash, t0);
		queued.clear();
		Assert.assertTrue(plugin.turnedDownLately(20013, null, cash, t0 + hour));
		Assert.assertTrue("logged out: nothing asked", queued.isEmpty());
	}

	/** Dropped for want of cash — the engine rates it, but its buy is more
	 *  than the cash free: off while the cash is still short of that buy,
	 *  back the moment it is not. Not remembered, it flipped on and off the
	 *  list every round. Asked for again hourly, as the hold on a no is: a
	 *  market that falls can bring the buy within the cash, and with every
	 *  slot busy nothing else would see it. */
	@Test
	public void shortOfCashHoldsWhileTheCashIsShort()
	{
		final TradeEngine.Result rated = new TradeEngine.Result(1_050_002, 1_149_987, true, "", 77_000, false);
		final long hour = PocketGeTrackerPlugin.TURNED_DOWN_MEMORY_MS;
		Assert.assertFalse("the engine's yes", PocketGeTrackerPlugin.engineTurnsDown(rated, 1));
		plugin.noteVerdict(20099, rated, 1_020_000, 0);
		Assert.assertTrue(plugin.turnedDownLately(20099, null, 1_020_000, 1));
		Assert.assertTrue("nothing asked inside the hour", queued.isEmpty());
		Assert.assertTrue("an hour on, still short", plugin.turnedDownLately(20099, null, 1_020_000, hour));
		Assert.assertEquals("and asked for again", 1, queued.size());
		Assert.assertFalse("the cash came in", plugin.turnedDownLately(20099, null, 1_060_000, 2));
		plugin.noteVerdict(20099, rated, 1_060_000, 3);
		Assert.assertFalse("and a yes it can afford clears it", plugin.turnedDownLately(20099, null, 1_020_000, 4));
	}

	/** The engine's own no: not certified, no pair, nothing after tax. */
	@Test
	public void theEnginesOwnNo()
	{
		Assert.assertTrue(PocketGeTrackerPlugin.engineTurnsDown(new TradeEngine.Result(1000, 1010, false, "thin", 0, false), 1));
		Assert.assertTrue("nothing after tax",
			PocketGeTrackerPlugin.engineTurnsDown(new TradeEngine.Result(1000, 1020, true, "", 0, false), 1));
		Assert.assertTrue(PocketGeTrackerPlugin.engineTurnsDown(new TradeEngine.Result(1000, 1000, true, "", 0, false), 1));
		Assert.assertFalse(PocketGeTrackerPlugin.engineTurnsDown(new TradeEngine.Result(1000, 1100, true, "", 78, false), 1));
	}

	/** Applied to the flip ideas and the plan's positions alike, before the
	 *  engine is asked: a freed slot put a turned-down idea up as the
	 *  headline card. */
	@Test
	public void theIdeasAndThePlanUseIt() throws Exception
	{
		final String src = source();
		Assert.assertTrue(src.matches("(?s).*final TradeEngine\\.Result verdict = engineVerdict\\(buy\\.itemId, quotes\\.get\\(buy\\.itemId\\), engineCache\\);"
			+ "\\s*final long verdictAt = System\\.currentTimeMillis\\(\\);\\s*if \\(turnedDownLately\\(buy\\.itemId, verdict, cash, verdictAt\\)\\)\\s*\\{\\s*continue;"
			+ "\\s*\\}\\s*noteVerdict\\(buy\\.itemId, verdict, cash, verdictAt\\);\\s*if \\(!applyEngineToBuy\\(rec, verdict, cash, .*"));
		Assert.assertTrue(src.matches("(?s).*final TradeEngine\\.Result posVerdict = engineVerdict\\(pos\\.id, quotes\\.get\\(pos\\.id\\), engineCache\\);"
			+ "\\s*final long posAt = System\\.currentTimeMillis\\(\\);\\s*if \\(turnedDownLately\\(pos\\.id, posVerdict, cash, posAt\\)\\)\\s*\\{\\s*continue;"
			+ "\\s*\\}\\s*noteVerdict\\(pos\\.id, posVerdict, cash, posAt\\);\\s*if \\(!applyEngineToBuy\\(rec, posVerdict, cash, pos\\.dailyVolume\\)\\).*"));
	}

	/* ── The offer screen ─────────────────────────────────────────────── */

	/** An old series is asked for afresh on the offer screen, as on the
	 *  cards: it went only when there was none, and one from forty minutes
	 *  back priced the screen while the cards had dropped it. */
	@Test
	public void theOfferScreenRefetchesAnOldSeries() throws Exception
	{
		final String src = source();
		final int at = src.indexOf("private void updateGeContextFromScreen(boolean fetch)");
