		bank.put(MITHRIL_BAR, 25_000);
		m.invoke(null, held, q, bank, lots, null);
		final long net350 = 350 - FlipTracker.taxPerItem(350, MITHRIL_BAR);
		Assert.assertEquals(25_000L * net350 - 25_000L * 359, held.heldProfit);
