package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.EnumSet;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.WorldType;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * What the plugin tells the overlay is waiting to be shown: the tracker's
 * unshown sale for the slot, for the character logged in, on the main
 * game's Exchange, for the sell the slot is showing.
 */
public class PopsWiringTest
{
	private static final int DART = 811;
	private static final long MAIN = 1111L;
	private static final long ALT = 2222L;

	private long account = MAIN;
	private EnumSet<WorldType> world = EnumSet.noneOf(WorldType.class);
	private boolean popsOn = true;
	private GrandExchangeOfferState slot2 = GrandExchangeOfferState.SOLD;

	private PocketGeTrackerPlugin plugin;
	private FlipTracker tracker;

	@Before
	public void setUp() throws Exception
	{
		final GrandExchangeOffer offer = (GrandExchangeOffer) Proxy.newProxyInstance(
			GrandExchangeOffer.class.getClassLoader(), new Class<?>[]{GrandExchangeOffer.class},
			(proxy, m, args) ->
			{
				switch (m.getName())
				{
					case "getItemId":
						return DART;
					case "getState":
						return slot2;
					default:
						return defaults(m.getReturnType());
				}
			});
		final Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, m, args) ->
			{
				switch (m.getName())
				{
					case "getAccountHash":
						return account;
					case "getWorldType":
						return world;
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getTickCount":
						return 100;
					case "getGrandExchangeOffers":
					{
						final GrandExchangeOffer[] all = new GrandExchangeOffer[8];
						all[2] = offer;
						return all;
					}
					default:
						return defaults(m.getReturnType());
				}
			});
		final PocketGeTrackerConfig config = (PocketGeTrackerConfig) Proxy.newProxyInstance(
			PocketGeTrackerConfig.class.getClassLoader(), new Class<?>[]{PocketGeTrackerConfig.class},
			(proxy, m, args) -> "profitPops".equals(m.getName()) ? popsOn : defaults(m.getReturnType()));
		plugin = new PocketGeTrackerPlugin();
		set("client", client);
		set("config", config);
		set("geSettledTick", 10);
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField("tracker");
		f.setAccessible(true);
		tracker = (FlipTracker) f.get(plugin);

		/* 7,132 Rune darts bought at 190, then sold in slot 2 at 200. */
		tracker.setAccountHash(MAIN);
		tracker.onOffer(1_000, 0, DART, "Rune dart", true, 0, 0, 190, 7_132, false);
		tracker.onOffer(2_000, 0, DART, "Rune dart", true, 7_132, 7_132L * 190, 190, 7_132, false);
		tracker.onOffer(3_000, 0, 0, "", false, 0, 0, 0, 0, true);
		tracker.onOffer(4_000, 2, DART, "Rune dart", false, 0, 0, 200, 7_132, false);
	}

	private void set(String field, Object value) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static Object defaults(Class<?> t)
	{
		if (t == boolean.class)
		{
			return false;
		}
		if (t == int.class)
		{
			return 0;
		}
		if (t == long.class)
		{
			return 0L;
		}
		return null;
	}

	/** The sale, booked as the plugin books one: onOffer, then noteSale. */
	private void sold(int units) throws Exception
	{
		tracker.onOffer(5_000, 2, DART, "Rune dart", false, units, units * 200L, 200, 7_132, false);
		noteSale();
	}

	private void noteSale() throws Exception
	{
		final Method m = PocketGeTrackerPlugin.class.getDeclaredMethod("noteSale", int.class);
		m.setAccessible(true);
		m.invoke(plugin, 2);
	}

	/** The other character sells darts its own record never bought: coins,
	 *  not profit, through the same path. */
	private void soldWithNoBuy(int units) throws Exception
	{
		tracker.onOffer(4_500, 2, 0, "", false, 0, 0, 0, 0, true);
		account = ALT;
		tracker.setAccountHash(ALT);
		tracker.onOffer(5_000, 2, DART, "Rune dart", false, 0, 0, 200, 1_000, false);
		tracker.onOffer(6_000, 2, DART, "Rune dart", false, units, units * 200L, 200, 1_000, false);
		noteSale();
	}

	@Test
	public void aSaleWithNoBuyWaitsAsCoins() throws Exception
	{
		soldWithNoBuy(1_000);
		final long[] u = plugin.unseenSale(2);
		Assert.assertNotNull(u);
		Assert.assertEquals(FlipTracker.UNSEEN_COINS, u[2]);
		Assert.assertTrue(GeOfferGridOverlay.coins(u));
		plugin.saleShown(2);
		Assert.assertNull(plugin.unseenSale(2));
	}

	/** Switched off, a sale that books nothing still counts as shown: no
	 *  backlog of coins when the figures come back on. */
	@Test
	public void switchedOffCoinsDoNotWait() throws Exception
	{
		popsOn = false;
		soldWithNoBuy(1_000);
		popsOn = true;
		Assert.assertNull(plugin.unseenSale(2));
	}

	@Test
	public void theWholeSaleIsWaitingUntilShown() throws Exception
	{
		sold(7_132);
		Assert.assertArrayEquals(new long[]{7_132, 7_132L * 6, FlipTracker.UNSEEN_PROFIT}, plugin.unseenSale(2));
		plugin.saleShown(2);
		Assert.assertNull(plugin.unseenSale(2));
	}

	@Test
	public void notForAnotherCharacter() throws Exception
	{
		sold(7_132);
		account = ALT;
		Assert.assertNull(plugin.unseenSale(2));
		account = MAIN;
		Assert.assertNotNull("still waiting for its own", plugin.unseenSale(2));
	}

	@Test
	public void notOnAWorldWithItsOwnExchange() throws Exception
	{
		sold(7_132);
		world = EnumSet.of(WorldType.SEASONAL);
		Assert.assertNull(plugin.unseenSale(2));
		world = EnumSet.noneOf(WorldType.class);
		Assert.assertNotNull(plugin.unseenSale(2));
	}

	/** The slot shows a buy of the same item now: not that sale's square. */
	@Test
	public void notOverABuy() throws Exception
	{
		sold(7_132);
		slot2 = GrandExchangeOfferState.BUYING;
		Assert.assertNull(plugin.unseenSale(2));
	}

	@Test
	public void notWhileTheLoginReplayIsSettling() throws Exception
	{
		sold(7_132);
		set("geSettledTick", -1);
		Assert.assertNull(plugin.unseenSale(2));
	}

	/** Sold with the figures on but never seen, then switched off: nothing
	 *  is left to pop when they come back on days later. */
	@Test
	public void switchingOffClearsWhatWasWaiting() throws Exception
	{
		sold(3_000);
		Assert.assertNotNull(plugin.unseenSale(2));
		popsOn = false;
		final net.runelite.client.events.ConfigChanged e = new net.runelite.client.events.ConfigChanged();
		e.setGroup(PocketGeTrackerConfig.GROUP);
		e.setKey("profitPops");
		plugin.onConfigChanged(e);
		popsOn = true;
		Assert.assertNull(plugin.unseenSale(2));
	}

	/** Sold with the figures switched off: shown as far as anyone cares, so
	 *  switching them on does not pop a backlog. */
	@Test
	public void switchedOffASaleDoesNotWait() throws Exception
	{
		popsOn = false;
		sold(7_132);
		Assert.assertNull(plugin.unseenSale(2));
		popsOn = true;
		Assert.assertNull(plugin.unseenSale(2));
	}
}

package com.pocketge.tracker;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * The portfolio's value over time, for pocketge.com's chart: "id like to see
 * my overal progress of bank value going up and down on a chart".
 */
public class PortfolioHistoryTest
{
	private static final long T0 = 1_790_000_000_000L;
	private static final long MIN = 60_000L;
	private static final long HOUR = 60 * MIN;
	private static final long DAY = 24 * HOUR;

	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	/** One sample per 15 minutes, however often the panel refreshes. */
	@Test
	public void aSampleEveryFifteenMinutes() throws Exception
	{
		final PortfolioHistory h = new PortfolioHistory(tmp.getRoot());
		Assert.assertTrue(h.record(42L, T0, 148_000_000L));
		Assert.assertFalse("a refresh, not a sample", h.record(42L, T0 + 5 * MIN, 149_000_000L));
		Assert.assertTrue(h.record(42L, T0 + 15 * MIN, 150_000_000L));
		Assert.assertFalse("nothing worth nothing", h.record(42L, T0 + HOUR, 0L));
		final List<long[]> s = h.series(42L, T0 + HOUR);
		Assert.assertEquals(2, s.size());
		Assert.assertEquals(148_000_000L, s.get(0)[1]);
		Assert.assertEquals(150_000_000L, s.get(1)[1]);
	}

	/** Each character has its own, and it survives a restart. */
	@Test
	public void perCharacterAndOnDisk() throws Exception
	{
		final PortfolioHistory h = new PortfolioHistory(tmp.getRoot());
		h.record(42L, T0, 100L);
		h.record(-7L, T0, 900L);
		final PortfolioHistory again = new PortfolioHistory(tmp.getRoot());
		Assert.assertEquals(100L, again.series(42L, T0).get(0)[1]);
		Assert.assertEquals(900L, again.series(-7L, T0).get(0)[1]);
		Assert.assertTrue(again.series(1L, T0).isEmpty());
	}

	/** A torn last line — a client killed mid-write — costs that one line. */
	@Test
	public void aTornLineIsSkipped() throws Exception
	{
		final PortfolioHistory h = new PortfolioHistory(tmp.getRoot());
		final File f = h.fileFor(42L);
		Files.write(f.toPath(), (T0 + ",100\n" + (T0 + HOUR) + ",200\n" + (T0 + 2 * HOUR) + ",3")
			.replace(",3", ",").getBytes(StandardCharsets.UTF_8));
		Assert.assertEquals(2, new PortfolioHistory(tmp.getRoot()).series(42L, T0 + 3 * HOUR).size());
		Assert.assertNull(PortfolioHistory.parse("garbage"));
		Assert.assertNull(PortfolioHistory.parse("-5,10"));
	}

	/** A sample from the future — a clock put back — does not stop the
	 *  next one; and a torn last line never merges into the next sample. */
	@Test
	public void theFutureAndATornLineDoNotStopRecording() throws Exception
	{
		final PortfolioHistory h = new PortfolioHistory(tmp.getRoot());
		Assert.assertTrue(h.record(42L, T0 + 7 * DAY, 100L));
		Assert.assertTrue("after a restart, with the clock back", new PortfolioHistory(tmp.getRoot()).record(42L, T0, 200L));

		Files.write(h.fileFor(7L).toPath(), (T0 + ",100\n1").getBytes(StandardCharsets.UTF_8));
		final PortfolioHistory again = new PortfolioHistory(tmp.getRoot());
		Assert.assertTrue(again.record(7L, T0 + HOUR, 150L));
		final List<long[]> s = new PortfolioHistory(tmp.getRoot()).series(7L, T0 + 2 * HOUR);
		Assert.assertEquals("the torn line stays one stray line, not a sample in the year 2500", 2, s.size());
		Assert.assertEquals(T0 + HOUR, s.get(1)[0]);
	}

	/** A PC clock that is behind — a reset date, a restored snapshot — must
	 *  not cost the samples it is behind, and what is recorded meanwhile
	 *  goes in time order rather than after them. */
	@Test
	public void aClockThatIsBehindKeepsEverySampleInOrder() throws Exception
	{
		final PortfolioHistory h = new PortfolioHistory(tmp.getRoot());
		final StringBuilder sb = new StringBuilder();
		for (int d = 0; d <= 20; d++)
		{
			sb.append(T0 + d * DAY).append(',').append(100 + d).append('\n');
		}
		Files.write(h.fileFor(42L).toPath(), sb.toString().getBytes(StandardCharsets.UTF_8));
		Assert.assertEquals("five days behind, nothing dropped", 21, h.series(42L, T0 + 15 * DAY).size());
		Assert.assertEquals("nor rewritten away", 21, Files.readAllLines(h.fileFor(42L).toPath()).size());

		Assert.assertTrue(h.record(42L, T0 + 15 * DAY + HOUR, 999L));
		final List<long[]> s = h.series(42L, T0 + 15 * DAY + HOUR);
		for (int i = 1; i < s.size(); i++)
		{
			Assert.assertTrue("oldest first", s.get(i)[0] > s.get(i - 1)[0]);
		}
		Assert.assertEquals(22, s.size());
	}

	/** Who the chart shows before anyone logs in: the last one sampled. */
	@Test
	public void theLatestCharacterIsTheLastWritten() throws Exception
	{
		final PortfolioHistory h = new PortfolioHistory(tmp.getRoot());
		Assert.assertNull(h.latestAccount());
		h.record(42L, T0, 100L);
		h.fileFor(42L).setLastModified(T0);
		h.record(-7L, T0, 100L);
		h.fileFor(-7L).setLastModified(T0 + HOUR);
		Assert.assertEquals(Long.valueOf(-7L), h.latestAccount());
	}

	/** Everything for 30 days, then hourly, then daily — and the file
	 *  shrinks to match, so years of play stay small. */
	@Test
	public void olderStretchesAreThinned() throws Exception
	{
		final List<long[]> pts = new ArrayList<>();
		final long now = T0 + 400 * DAY;
		for (long t = T0; t <= now; t += 15 * MIN)
		{
			pts.add(new long[]{t, t / MIN});
		}
		final List<long[]> thin = PortfolioHistory.thin(pts, now);
		long full = 0;
		long hourly = 0;
		long daily = 0;
		for (int i = 0; i < thin.size(); i++)
		{
			final long age = now - thin.get(i)[0];
			if (i > 0)
			{
				Assert.assertTrue("oldest first", thin.get(i)[0] > thin.get(i - 1)[0]);
			}
			if (age <= PortfolioHistory.FULL_FOR_MS)
			{
				full++;
			}
			else if (age <= PortfolioHistory.HOURLY_FOR_MS)
			{
				hourly++;
			}
			else
			{
				daily++;
			}
		}
		Assert.assertEquals("every sample of the last 30 days", 30 * 24 * 4 + 1, full);
		Assert.assertEquals("one an hour back to a year", 335 * 24, hourly, 2);
		Assert.assertEquals("one a day before that", 35, daily, 2);
		Assert.assertEquals("the newest is never dropped", now, thin.get(thin.size() - 1)[0]);

		final PortfolioHistory h = new PortfolioHistory(tmp.getRoot());
		final StringBuilder sb = new StringBuilder();
		for (long[] p : pts)
		{
			sb.append(p[0]).append(',').append(p[1]).append('\n');
		}
		Files.write(h.fileFor(9L).toPath(), sb.toString().getBytes(StandardCharsets.UTF_8));
		Assert.assertEquals(thin.size(), h.series(9L, now).size());
		Assert.assertEquals("rewritten thin", thin.size(), Files.readAllLines(h.fileFor(9L).toPath()).size());
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class PortfolioValuerTest
{
	private static Advisor.Quote quote(long low, long high)
	{
		Advisor.Quote q = new Advisor.Quote();
		q.low = low;
		q.high = high;
		return q;
	}

	/** netExit for the fixture quote(100, 110): the ask, less the 2% the
	 *  Exchange takes. 110 - 2 = 108. */
	private static final long NET_108 = 108;

	@Test
	public void cashAndItemsSumCorrectly()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, quote(100, 110));

		Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(1601, 50);

		PortfolioValuer.Result r = PortfolioValuer.value(1_000, holdings, new HashMap<>(), new ArrayList<>(), quotes);
		Assert.assertEquals(1_000L, r.cash);
		/* 50 x netExit, not 50 x low. Holdings used to be marked at the raw
		   bid with no tax — the wrong side of the book AND the wrong net,
		   which is not conservatism, just a different answer from the one the
		   sell card gives for the same stack. */
		Assert.assertEquals(50 * NET_108, r.itemsValue);
		Assert.assertEquals(0L, r.offersValue);
		Assert.assertEquals(1_000L + 50 * NET_108, r.total);
	}

	/**
	 * The property the whole netExit change exists for: what the header says
	 * a stack is worth and what the sell card offers for it are the same
	 * number.
	 *
	 * They were a full spread plus 2% apart, which on a thin book is easily
	 * enough to flip the sign — an unrealized loss in the header above a card
	 * promising a gain on the very same items. Asserted against the real
	 * Advisor rather than by re-deriving the arithmetic, so the two cannot
	 * drift apart again without this failing.
	 */
	@Test
	public void theHeaderAndTheSellCardAgreeOnWhatAStackIsWorth()
	{
		final Advisor.Quote q = quote(100, 110);
		q.highTime = 1_000_000L;
		q.lowTime = 1_000_000L;
		final Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, q);

		final Advisor.ItemMeta m = new Advisor.ItemMeta();
		m.id = 1601;
		m.name = "Diamond";
		m.limit = 10_000;
		m.dailyVolume = 1_000_000L;
		final Map<Integer, Advisor.ItemMeta> meta = new HashMap<>();
		meta.put(1601, m);

		final Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(1601, 5_000);

		final long headline = PortfolioValuer.value(0, holdings, new HashMap<>(), new ArrayList<>(), quotes).itemsValue;
		final Advisor.Suggestion card = Advisor.sellCandidates(1_000_000L, quotes, meta, holdings,
			new ArrayList<>(), new java.util.HashSet<>(), new java.util.HashSet<>(), null).get(0);

		Assert.assertEquals("the portfolio and the sell card price the same stack the same way",
			headline, card.grossValue);
		Assert.assertEquals(5_000 * NET_108, headline);
	}

	@Test
	public void unknownItemIsSkippedNotGuessed()
	{
		Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(999, 10); // no quote for this id
		PortfolioValuer.Result r = PortfolioValuer.value(0, holdings, new HashMap<>(), new ArrayList<>(), new HashMap<>());
		Assert.assertEquals(0L, r.itemsValue);
		Assert.assertEquals(0L, r.total);
	}

	@Test
	public void openBuyOfferCountsEscrowPlusFilledPortion()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, quote(100, 110));

		Advisor.OfferView buy = new Advisor.OfferView();
		buy.itemId = 1601;
		buy.buy = true;
		buy.price = 90;
		buy.totalQuantity = 100;
		buy.quantitySold = 40;
		buy.active = true;

		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(buy);

		PortfolioValuer.Result r = PortfolioValuer.value(0, new HashMap<>(), new HashMap<>(), offers, quotes);
		/* Unfilled 60 sits as gp in escrow at YOUR bid (60 x 90); the 40
		   already bought are items now, so they are worth what any other
		   stack of them is worth — netExit, like everything else. */
		Assert.assertEquals(60 * 90L + 40 * NET_108, r.offersValue);
	}

	/** Finished, or cancelled, and not collected: still money, in the slot
	 *  rather than the bank. Counted as nothing, the total dropped by a
	 *  whole offer until you collected — a dip the portfolio chart kept. */
	@Test
	public void anUncollectedOfferStillCounts()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, quote(100, 110));

		Advisor.OfferView bought = new Advisor.OfferView();
		bought.itemId = 1601;
		bought.buy = true;
		bought.price = 90;
		bought.totalQuantity = 100;
		bought.quantitySold = 100;
		bought.uncollected = true;

		Advisor.OfferView cancelled = new Advisor.OfferView();
		cancelled.itemId = 1601;
		cancelled.buy = true;
		cancelled.price = 90;
		cancelled.totalQuantity = 100;
		cancelled.quantitySold = 40;
		cancelled.uncollected = true;

		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(bought);
		offers.add(cancelled);
		PortfolioValuer.Result r = PortfolioValuer.value(0, new HashMap<>(), new HashMap<>(), offers, quotes);
		Assert.assertEquals("the items bought, and the cancelled one's refund",
			100 * NET_108 + 40 * NET_108 + 60 * 90L, r.offersValue);

		Advisor.OfferView neither = new Advisor.OfferView();
		neither.itemId = 1601;
		neither.totalQuantity = 100;
		neither.price = 90;
		Assert.assertEquals("an empty or unknown slot is nothing", 0,
			PortfolioValuer.value(0, new HashMap<>(), new HashMap<>(), java.util.Collections.singletonList(neither), quotes).offersValue);
	}

	/** With the collection box seen, what is really in it: a buy collected
	 *  item-side only is its refund coins, not the whole position again on
	 *  top of the items now in your inventory. */
	@Test
	public void theCollectionBoxIsWhatIsLeftInTheSlot()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, quote(100, 110));

		Advisor.OfferView bought = new Advisor.OfferView();
		bought.itemId = 1601;
		bought.buy = true;
		bought.price = 105;
		bought.totalQuantity = 10_000;
		bought.quantitySold = 10_000;
		bought.uncollected = true;
		bought.boxKnown = true;
		bought.boxCoins = 50_000;
		bought.boxUnits = 0;

		Advisor.OfferView working = new Advisor.OfferView();
		working.itemId = 1601;
		working.buy = true;
		working.price = 90;
		working.totalQuantity = 100;
		working.quantitySold = 40;
		working.active = true;
		working.boxKnown = true;
		working.boxUnits = 10; // 30 of the 40 collected already

		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(bought);
		offers.add(working);
		PortfolioValuer.Result r = PortfolioValuer.value(0, new HashMap<>(), new HashMap<>(), offers, quotes);
		Assert.assertEquals(50_000L + (60 * 90L + 10 * NET_108), r.offersValue);
	}

	@Test
	public void openSellOfferCountsUnsoldPlusProceedsAfterTax()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, quote(100, 110));

		Advisor.OfferView sell = new Advisor.OfferView();
		sell.itemId = 1601;
		sell.buy = false;
		sell.price = 120;
		sell.totalQuantity = 50;
		sell.quantitySold = 30;
		sell.active = true;

		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(sell);

		PortfolioValuer.Result r = PortfolioValuer.value(0, new HashMap<>(), new HashMap<>(), offers, quotes);
		long tax = FlipTracker.taxPerItem(120, 1601) * 30;
		/* The 20 unsold are still your items, at netExit. The 30 already sold
		   are gp at the price YOU listed at, less the tax already taken —
		   that leg is a settled fact, not a valuation. */
		long expected = 20L * NET_108 + (30L * 120 - tax);
		Assert.assertEquals(expected, r.offersValue);
	}

	@Test
	public void inactiveOffersAreIgnored()
	{
		Advisor.OfferView inactive = new Advisor.OfferView();
		inactive.itemId = 1601;
		inactive.buy = true;
		inactive.price = 100;
		inactive.totalQuantity = 10;
		inactive.quantitySold = 10;
		inactive.active = false; // BOUGHT/CANCELLED — already collected or gone

		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(inactive);

		PortfolioValuer.Result r = PortfolioValuer.value(0, new HashMap<>(), new HashMap<>(), offers, new HashMap<>());
		Assert.assertEquals(0L, r.offersValue);
	}

	/* ── heldPosition: the watchlist "profit available" tag ───────────────
	   Every test here exists because the alternative is a green number in
	   the player's sidebar telling them to go sell something, on a claim
	   that isn't true. */

	@Test
	public void heldPosition_holdingNothingReportsNothing()
	{
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(1601, 0, quote(100, 110), new long[]{5, 400});
		Assert.assertEquals(0, p.heldQty);
		Assert.assertEquals(0L, p.sellValue);
		Assert.assertFalse(p.hasCostBasis);
	}

	@Test
	public void heldPosition_noQuoteMeansNoClaim()
	{
		Assert.assertEquals(0L, PortfolioValuer.heldPosition(1601, 50, null, null).sellValue);
		Assert.assertEquals(0L, PortfolioValuer.heldPosition(1601, 50, quote(100, 0), null).sellValue);
	}

	@Test
	public void heldPosition_untrackedStackIsValuedButNeverCalledProfit()
	{
		// A stack owned before the plugin ever ran: worth something, but we
		// have no idea what it cost, so hasCostBasis must stay false and the
		// UI must not print "profit".
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(1601, 100, quote(1_000, 2_000), null);
		Assert.assertEquals(100, p.heldQty);
		// tax on 2000 = 2000/50 = 40; net 1960 each
		Assert.assertEquals(196_000L, p.sellValue);
		Assert.assertFalse(p.hasCostBasis);
		Assert.assertEquals(0L, p.heldProfit);
		Assert.assertEquals(0, p.pricedQty);
	}

	@Test
	public void heldPosition_trackedStackReportsGainAfterTax()
	{
		// Bought 100 at 1,500 each (150,000 spent), now bid 2,000.
		// net = 2000 - 40 = 1960 -> 196,000 proceeds - 150,000 = 46,000
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 100, quote(1_900, 2_000), new long[]{100, 150_000});
		Assert.assertTrue(p.hasCostBasis);
		Assert.assertEquals(100, p.pricedQty);
		Assert.assertEquals(196_000L, p.sellValue);
		Assert.assertEquals(46_000L, p.heldProfit);
	}

	@Test
	public void heldPosition_profitCoversOnlyTheUnitsStillHeld()
	{
		// Bought 1,000 and spent 150,000; used 400, so only 600 are left.
		// Claiming profit on all 1,000 would report gain on runes that are
		// gone. Cost of the 600 remaining = 150,000 * 0.6 = 90,000.
		// net = 2000 - 40 = 1960 -> 600 * 1960 = 1,176,000 - 90,000
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 600, quote(1_900, 2_000), new long[]{1_000, 150_000});
		Assert.assertEquals(600, p.heldQty);
		Assert.assertEquals(600, p.pricedQty);
		Assert.assertEquals(1_176_000L, p.sellValue);
		Assert.assertEquals(1_086_000L, p.heldProfit);
	}

	@Test
	public void heldPosition_profitCoversOnlyTheUnitsWeWatchedYouBuy()
	{
		// Held 500 but only ever saw 100 bought (400 pre-dated the plugin).
		// sellValue covers all 500; profit covers 100. Understating is the
		// only safe direction.
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 500, quote(1_900, 2_000), new long[]{100, 150_000});
		Assert.assertEquals(500, p.heldQty);
		Assert.assertEquals(100, p.pricedQty);
		Assert.assertEquals(980_000L, p.sellValue);        // 500 * 1960
		Assert.assertEquals(46_000L, p.heldProfit);        // 100 * 1960 - 150,000
	}

	@Test
	public void heldPosition_underwaterPositionReportsNegativeRatherThanZero()
	{
		// Bought 100 at 3,000 (300,000), now only bid 2,000. The panel
		// chooses not to SHOW this, but the number itself must be honest —
		// clamping here would hide a real loss from the inspection card too.
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 100, quote(1_900, 2_000), new long[]{100, 300_000});
		Assert.assertTrue(p.hasCostBasis);
		Assert.assertEquals(-104_000L, p.heldProfit);
	}

	@Test
	public void heldPosition_roundingNeverFlattersTheProfit()
	{
		// 3 of 7 units held, 100 gp spent on the 7. An average-cost-per-item
		// of 100/7 = 14 (integer truncation) would price the 3 at 42 and
		// claim 3 gp more profit than really exists. Ceil of 100*3/7 = 43.
		// Price is under the 50 gp tax floor, so net == high == 20.
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 3, quote(19, 20), new long[]{7, 100});
		Assert.assertEquals(3, p.pricedQty);
		Assert.assertEquals(60L, p.sellValue);
		Assert.assertEquals(17L, p.heldProfit); // 60 - 43, NOT 60 - 42
	}

	@Test
	public void heldPosition_zeroOrGarbageTrackedLotIsTreatedAsUntracked()
	{
		Assert.assertFalse(PortfolioValuer.heldPosition(1601, 50, quote(100, 200), new long[]{0, 0}).hasCostBasis);
		Assert.assertFalse(PortfolioValuer.heldPosition(1601, 50, quote(100, 200), new long[]{5, 0}).hasCostBasis);
		Assert.assertFalse(PortfolioValuer.heldPosition(1601, 50, quote(100, 200), new long[]{9}).hasCostBasis);
	}

	@Test
	public void heldPosition_taxExemptItemKeepsTheWholePrice()
	{
		// Chisel (1755) is on the tax-exempt list; net must equal the bid.
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(1755, 10, quote(900, 1_000), null);
		Assert.assertEquals(10_000L, p.sellValue);
	}

	/* ── cash vs stock ────────────────────────────────────────────────────
	   Platinum tokens are how anyone flipping at size holds their gp. Counted
	   as an item they inflate "stock" and vanish from liquid cash, so the
	   advisor sizes buys against a fraction of the real bankroll. */

	@Test
	public void cashValue_knowsBothDenominations()
	{
		Assert.assertEquals(5_000L, PortfolioValuer.cashValue(PortfolioValuer.COINS_ID, 5_000));
		Assert.assertEquals(500_000_000L,
			PortfolioValuer.cashValue(PortfolioValuer.PLATINUM_TOKEN_ID, 500_000));
		Assert.assertEquals("an ordinary item is not cash", 0L, PortfolioValuer.cashValue(1601, 10));
		Assert.assertEquals(0L, PortfolioValuer.cashValue(PortfolioValuer.COINS_ID, 0));
		Assert.assertEquals(0L, PortfolioValuer.cashValue(PortfolioValuer.COINS_ID, -5));
	}

	@Test
	public void isCash_coversCoinsAndPlatinumOnly()
	{
		Assert.assertTrue(PortfolioValuer.isCash(PortfolioValuer.COINS_ID));
		Assert.assertTrue(PortfolioValuer.isCash(PortfolioValuer.PLATINUM_TOKEN_ID));
		Assert.assertFalse(PortfolioValuer.isCash(1601));
	}

	@Test
	public void cashLeftInHoldingsIsNeverCountedTwice()
	{
		// The plugin strips cash from holdings, but if a stray stack ever got
		// through it must not be added on top of the `cash` argument — and
		// platinum especially must not be valued from a market quote.
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(PortfolioValuer.PLATINUM_TOKEN_ID, quote(1_050, 1_100)); // market != face
		quotes.put(PortfolioValuer.COINS_ID, quote(1, 1));
		quotes.put(1601, quote(100, 110));

		Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(PortfolioValuer.PLATINUM_TOKEN_ID, 1_000);
		holdings.put(PortfolioValuer.COINS_ID, 50_000);
		holdings.put(1601, 50); // the only genuine stock here

		PortfolioValuer.Result r = PortfolioValuer.value(
			1_050_000L, holdings, new HashMap<>(), new ArrayList<>(), quotes);
		Assert.assertEquals("only the real item counts as stock", 50 * NET_108, r.itemsValue);
		Assert.assertEquals(1_050_000L, r.cash);
		Assert.assertEquals(1_050_000L + 50 * NET_108, r.total);
	}
}

package com.pocketge.tracker;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * The offer-screen chart is a port of pocketge.com's, so its rules are
 * held to the site's: the tick steps, the axis labels, which buckets are
 * drawn, where the marks go, how volume is binned.
 */
public class PriceChartTest
{
	private static TradeEngine.Series series(long[] t, double[] lo, double[] hi)
	{
		final TradeEngine.Series s = new TradeEngine.Series();
		s.labels = t;
		s.low = lo;
		s.high = hi;
		s.lowVol = new double[t.length];
		s.highVol = new double[t.length];
		for (int i = 0; i < t.length; i++)
		{
			s.lowVol[i] = lo[i] > 0 ? 10 : 0;
			s.highVol[i] = hi[i] > 0 ? 20 : 0;
		}
		return s;
	}

	/** niceTicks snaps the step DOWN to 5, 2.5 (tens and up), 2 or 1 —
	 *  and never under 1 gp. */
	@Test
	public void ticksStepAsTheSitesDo()
	{
		Assert.assertEquals(5, PriceChart.tickStep(150, 182, 5), 0); // 6.4 -> 5
		Assert.assertEquals(25, PriceChart.tickStep(0, 140, 5), 0); // 28 -> 25
		Assert.assertEquals(2, PriceChart.tickStep(0, 11, 5), 0); // 2.2 (under 10) -> 2
		Assert.assertEquals(1, PriceChart.tickStep(100, 101, 5), 0); // 0.2 -> never under 1 gp
		Assert.assertEquals(List.of(150L, 155L, 160L, 165L, 170L, 175L, 180L), PriceChart.niceTicks(148.2, 182.4, 5));
	}

	@Test
	public void axisLabelsAsTheSitesAre()
	{
		Assert.assertEquals("1,267", PriceChart.fmtYAxis(1267, 100));
		Assert.assertEquals("12.5K", PriceChart.fmtYAxis(12_500, 500));
		Assert.assertEquals("12K", PriceChart.fmtYAxis(12_000, 1_000));
		Assert.assertEquals("1.25M", PriceChart.fmtYAxis(1_250_000, 50_000));
		Assert.assertEquals("2.4B", PriceChart.fmtYAxis(2_400_000_000L, 100_000_000));
		Assert.assertEquals("crosshair: two places, trailing zeros trimmed", "12.5K", PriceChart.fmtYAxis(12_500, 0));
		Assert.assertEquals("a billion-gp axis keeps its decimals", "1.80367B", PriceChart.fmtYAxis(1_803_668_250L, 250));
		Assert.assertEquals("1.45000B", PriceChart.fmtYAxis(1_450_000_000L, 500));
		Assert.assertEquals("rounded as toFixed rounds the double", "2.93915M", PriceChart.fmtYAxis(2_939_155, 1));
		Assert.assertEquals("2.93916M", PriceChart.fmtYAxis(2_939_156, 1));
	}

	/** Buckets with no print on either side are dropped, and only the range
	 *  back from the newest bucket is kept. */
	@Test
	public void preparedDataIsTheRangesPrintsOnly()
	{
		final long day = 86_400L;
		final TradeEngine.Series s = series(
			new long[]{0, day / 2, day, day + 300, 2 * day},
			new double[]{100, 0, 101, 0, 103},
			new double[]{110, 0, 0, 0, 112});
		final PriceChart.Data d = PriceChart.prepare(s, day);
		Assert.assertArrayEquals("all-empty buckets gone, a day back from the newest",
			new long[]{day, 2 * day}, d.t);
		Assert.assertEquals(5, PriceChart.prints(series(new long[]{1, 2, 3, 4, 5, 6},
			new double[]{1, 1, 1, 0, 1, 1}, new double[]{0, 0, 0, 0, 0, 0})));
		Assert.assertTrue(PriceChart.usable(series(new long[]{1, 2, 3, 4, 5},
			new double[]{1, 1, 1, 1, 1}, new double[5])));
		Assert.assertFalse(PriceChart.usable(series(new long[]{1, 2, 3, 4},
			new double[]{1, 1, 1, 1}, new double[4])));
	}

	@Test
	public void periodMarksTheWholeWindowAndRecentItsLastQuarter()
	{
		final long[] t = new long[8];
		for (int i = 0; i < 8; i++)
		{
			t[i] = i * 300L;
		}
		final PriceChart.Data d = PriceChart.prepare(series(t,
			new double[]{90, 95, 96, 97, 98, 99, 94, 93},
			new double[]{120, 110, 111, 112, 113, 114, 116, 115}), 86_400L);
		Assert.assertArrayEquals("period: highest high at 0, lowest low at 0", new int[]{0, 0}, PriceChart.extremes(d, 0));
		Assert.assertEquals(6, PriceChart.recentStart(8));
		Assert.assertArrayEquals("recent: from index 6 on", new int[]{6, 7}, PriceChart.extremes(d, 6));
	}

	/** The trend starts once both sides have printed, as the site's does:
	 *  never along one side's dots alone. */
	@Test
	public void trendWaitsForBothSides()
	{
		final long[] t = new long[30];
		final double[] lo = new double[30];
		final double[] hi = new double[30];
		for (int i = 0; i < 30; i++)
		{
			t[i] = i * 300L;
			lo[i] = 100;
			hi[i] = i < 4 ? 0 : 120;
		}
		final double[] ema = PriceChart.trend(PriceChart.prepare(series(t, lo, hi), 86_400L));
		for (int i = 0; i < 4; i++)
		{
			Assert.assertTrue("no line before the first high, at " + i, Double.isNaN(ema[i]));
		}
		Assert.assertEquals(110, ema[4], 1e-9);
		Assert.assertEquals(110, ema[29], 1e-9);
		final double[] oneSided = PriceChart.trend(PriceChart.prepare(series(t, lo, new double[30]), 86_400L));
		Assert.assertTrue("one side all window: no trend", java.util.Arrays.stream(oneSided).allMatch(Double::isNaN));
	}

	/** The tooltip names the mark under the cursor, a Period mark over a
	 *  Recent one, and shows a side that did not print as a dash. */
	@Test
	public void theTooltipNamesTheMarkAndBothSides()
	{
		final long[] t = new long[8];
		final double[] lo = {100, 98, 101, 102, 103, 104, 99, 105};
		final double[] hi = {110, 111, 120, 112, 113, 114, 0, 116};
		for (int i = 0; i < 8; i++)
		{
			t[i] = i * 300L;
		}
		final PriceChart.Data d = PriceChart.prepare(series(t, lo, hi), 86_400L);
		final List<String[]> low = PriceChart.tooltipRows(d, 1);
		Assert.assertEquals("Period Low", low.get(1)[0]);
		Assert.assertEquals("solid-buy", low.get(1)[1]);
		Assert.assertEquals("Period High", PriceChart.tooltipRows(d, 2).get(1)[0]);
		final List<String[]> recent = PriceChart.tooltipRows(d, 6);
		Assert.assertEquals("Recent Low", recent.get(1)[0]);
		Assert.assertEquals("hollow-buy", recent.get(1)[1]);
		Assert.assertEquals("Buy: 99", recent.get(2)[0]);
		Assert.assertEquals("a side with no print", "Sell: —", recent.get(3)[0]);
		Assert.assertEquals("Recent High", PriceChart.tooltipRows(d, 7).get(1)[0]);
		final List<String[]> plain = PriceChart.tooltipRows(d, 3);
		Assert.assertEquals("no mark: time, both sides, volume", 4, plain.size());
	}

	/** A tick per 40px of pane, but not five in a 100px one. */
	@Test
	public void ticksFitTheChatPane()
	{
		Assert.assertEquals(2, PriceChart.tickCount(96));
		Assert.assertEquals(5, PriceChart.tickCount(200));
		Assert.assertEquals(14, PriceChart.tickCount(900));
	}

	/** The chart keeps off its area's left, right and bottom edge — the
	 *  overlay panel's border — with no clip to lean on, short and tall and
	 *  at narrow and wide prices: the hover's pills end inside. And with no
	 *  volume bars, a series' volume shows only as the profile in the plot:
	 *  the axis and the left gutter are the same with it as without. */
	@Test
	public void theChartLaysOutInsideItsArea()
	{
		final double[][][] prices = {
			{{100, 101}, {110, 112}},
			{{50_000, 50_500}, {51_000, 51_200}},
			{{15_000_000, 15_050_000}, {15_100_000, 15_120_000}},
		};
		for (Rectangle area : new Rectangle[]{new Rectangle(150, 140, 519, 122), new Rectangle(150, 140, 519, 320),
			new Rectangle(150, 40, 519, 580), new Rectangle(150, 140, 519, 90)})
		{
			for (double[][] p : prices)
			{
				final TradeEngine.Series two = series(new long[]{0, 300}, p[0], p[1]);
				final BufferedImage img = new BufferedImage(800, 700, BufferedImage.TYPE_INT_ARGB);
				final Graphics2D g = img.createGraphics();
				for (java.awt.Point mouse : new java.awt.Point[]{null, new java.awt.Point(300, 240),
					new java.awt.Point(160, 238), new java.awt.Point(area.x + 460, area.y + 10)})
				{
					PriceChart.paint(g, area, PriceChart.prepare(two, 86_400L), new PriceChart.Style(), new PriceChart.Lines(), mouse);
				}
				g.dispose();
				for (int y = 0; y < img.getHeight(); y++)
				{
					for (int x = 0; x < img.getWidth(); x++)
					{
						final boolean inside = x > area.x && x < area.x + area.width - 1
							&& y >= area.y && y < area.y + area.height - 1;
						if (!inside)
						{
							Assert.assertEquals("painted on or past the area's edge at " + x + "," + y + " for " + p[0][0],
								0, img.getRGB(x, y) >>> 24);
						}
					}
				}
			}

			/* The axis column and the left gutter are the same with the
			   volume as without it. */
			final TradeEngine.Series two = series(new long[]{0, 300}, new double[]{100, 101}, new double[]{110, 112});
			final TradeEngine.Series quiet = series(two.labels, two.low, two.high);
			quiet.lowVol = new double[2];
			quiet.highVol = new double[2];
			final BufferedImage withVol = new BufferedImage(800, 700, BufferedImage.TYPE_INT_ARGB);
			final BufferedImage without = new BufferedImage(800, 700, BufferedImage.TYPE_INT_ARGB);
			final Graphics2D g1 = withVol.createGraphics();
			PriceChart.paint(g1, area, PriceChart.prepare(two, 86_400L), new PriceChart.Style(), new PriceChart.Lines(), null);
			g1.dispose();
			final Graphics2D g2 = without.createGraphics();
			PriceChart.paint(g2, area, PriceChart.prepare(quiet, 86_400L), new PriceChart.Style(), new PriceChart.Lines(), null);
			g2.dispose();
			final int axisFrom = area.x + 8 + (area.width - 8 - 45) + 2;
			int gutter = 0;
			for (int y = area.y; y < area.y + area.height; y++)
			{
				for (int x = axisFrom; x < area.x + area.width; x++)
				{
					Assert.assertEquals("volume reached the axis at " + x + "," + y, without.getRGB(x, y), withVol.getRGB(x, y));
				}
				for (int x = area.x + 1; x < area.x + 8; x++)
				{
					gutter += withVol.getRGB(x, y) != without.getRGB(x, y) ? 1 : 0;
				}
			}
			Assert.assertEquals("no volume bars in the left gutter", 0, gutter);
		}
	}

	/** The overlay clips to the chat box it covers: nothing at all lands
	 *  outside it. */
	@Test
	public void theChartStaysInsideItsBox()
	{
		final BufferedImage img = new BufferedImage(800, 400, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		final Rectangle box = new Rectangle(150, 120, 519, 142);
