package com.pocketge.tracker;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * The badge rules, pinned against pocketge.com's dayState(). Every threshold
 * here is one the website also enforces, so a change that quietly drifts the
 * plugin away from the site fails a test rather than showing the user two
 * different answers for the same item.
 */
public class PriceExtremesTest
{
	/** 1000-1200: a 20% range, comfortably past every range floor. */
	private static PriceExtremes fiveDay(long lo, long hi)
	{
		final PriceExtremes ex = new PriceExtremes();
		ex.lo5d = lo;
		ex.hi5d = hi;
		return ex;
	}

	@Test
	public void nothingAtAllWhenNoExtremesAreKnown()
	{
		assertEquals(PriceExtremes.Tier.NONE, new PriceExtremes().tier(1000, 990));
	}

	@Test
	public void topEightPercentOfTheFiveDayRangeIsAFiveDayHigh()
	{
		// Range 200 wide; 8% band = the top 16 gp, so 1184 and up.
		assertEquals(PriceExtremes.Tier.HIGH_5D, fiveDay(1000, 1200).tier(1184, 1100));
		assertEquals(PriceExtremes.Tier.NONE, fiveDay(1000, 1200).tier(1183, 1100));
	}

	@Test
	public void bottomEightPercentOfTheFiveDayRangeIsAFiveDayLow()
	{
		assertEquals(PriceExtremes.Tier.LOW_5D, fiveDay(1000, 1200).tier(1100, 1016));
		assertEquals(PriceExtremes.Tier.NONE, fiveDay(1000, 1200).tier(1100, 1017));
	}

	@Test
	public void aNearlyFlatItemNeverFlags()
	{
		/* 1000-1020 is a 2% range, under the 3% floor — without it, an item
		   that has not moved all week flags every time it ticks one gp. */
		final PriceExtremes flat = fiveDay(1000, 1020);
		assertEquals(PriceExtremes.Tier.NONE, flat.tier(1020, 1000));
	}

	@Test
	public void theDayTierNeedsThePriceToActuallyReachTheDaysExtreme()
	{
		final PriceExtremes ex = new PriceExtremes();
		ex.lo1d = 1000;
		ex.hi1d = 1100; // a 10% day range, past the 4% floor
		assertEquals(PriceExtremes.Tier.HIGH_1D, ex.tier(1100, 1050));
		assertEquals(PriceExtremes.Tier.HIGH_1D, ex.tier(1101, 1050)); // broke out
		assertEquals(PriceExtremes.Tier.NONE, ex.tier(1099, 1050));    // merely close
		assertEquals(PriceExtremes.Tier.LOW_1D, ex.tier(1050, 1000));
		assertEquals(PriceExtremes.Tier.NONE, ex.tier(1050, 1001));
	}

	@Test
	public void aQuietDayNeverFlagsEvenAtItsExactEdge()
	{
		final PriceExtremes ex = new PriceExtremes();
		ex.lo1d = 1000;
		ex.hi1d = 1030; // 3% — under the day tier's stricter 4% floor
		assertEquals(PriceExtremes.Tier.NONE, ex.tier(1030, 1000));
	}

	@Test
	public void aWiderWindowMakesTheBandEasierToLandIn_whichIsWhyThereIsNoThirtyDayTier()
	{
		/* This is the arithmetic that killed the 30-day badge, pinned so it
		   cannot be reintroduced by the same mistaken reasoning.

		   The band is 8% OF THE RANGE, so it scales WITH the range: a wide
		   window has a wide band and is EASIER to sit inside, not harder. A
		   price of 1,080 is inside the bottom band of the wide range and
		   nowhere near the narrow one, at the same instant, for the same
		   item. Stacked as a tier above 5-day it therefore fired on nearly
		   every row and buried the tier underneath it. */
		final PriceExtremes wide = fiveDay(1000, 2000);   // band = bottom 80gp
		final PriceExtremes narrow = fiveDay(1000, 1100); // band = bottom 8gp
		assertEquals(PriceExtremes.Tier.LOW_5D, wide.tier(1500, 1080));
		assertEquals(PriceExtremes.Tier.NONE, narrow.tier(1050, 1080));
	}

	@Test
	public void multiDayTiersOutrankTheDayTier()
	{
		final PriceExtremes ex = fiveDay(1000, 1200);
		ex.lo1d = 1000;
		ex.hi1d = 1190;
		// 1190 meets the day high AND sits in the 5-day top band.
		assertEquals(PriceExtremes.Tier.HIGH_5D, ex.tier(1190, 1100));
	}

	@Test
	public void anUnknownLivePriceCannotFlag()
	{
		/* A missing quote reads as 0, and 0 is below every low ever recorded.
		   Without the >0 guards that would badge the whole watchlist "at a
		   5-day low" the moment a price fetch came back empty. */
		final PriceExtremes ex = fiveDay(1000, 1200);
		ex.lo1d = 1000;
		ex.hi1d = 1100;
		assertEquals(PriceExtremes.Tier.NONE, ex.tier(0, 0));
	}

	@Test
	public void aMissingDayWindowDoesNotSuppressTheFiveDayAnswer()
	{
		/* The 1h fetch fills both windows at once, but a short series (a
		   newly tradeable item) can leave the day window empty. The 5-day
		   answer still has to come through. */
		final PriceExtremes ex = fiveDay(1000, 1200);
		ex.hi1d = 0;
		ex.lo1d = 0;
		assertEquals(PriceExtremes.Tier.HIGH_5D, ex.tier(1190, 1100));
	}

	@Test
	public void highAndLowAreJudgedOnTheirOwnSidesOfTheBook()
	{
		/* The insta-buy decides highs and the insta-sell decides lows, never
		   crossed. Each case puts exactly ONE side in its band and parks the
		   other mid-range, so a crossed comparison changes the answer. */
		final PriceExtremes ex = fiveDay(1000, 1200);
		assertEquals(PriceExtremes.Tier.HIGH_5D, ex.tier(1190, 1100));
		assertEquals(PriceExtremes.Tier.LOW_5D, ex.tier(1100, 1010));
	}

	@Test
	public void aWideSpreadTouchingBothEndsReadsAsAHigh()
	{
		/* An illiquid item can have an ask in the top band and a bid in the
		   bottom one at the same time. The website resolves that by testing
		   the high side first (app.js dayState), and the plugin has to agree
		   or the same item wears different badges in the two places. */
		final PriceExtremes ex = fiveDay(1000, 1200);
		assertEquals(PriceExtremes.Tier.HIGH_5D, ex.tier(1190, 1010));
	}
}

package com.pocketge.tracker;

import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * "if lets say rune darts sold. it would show +200gp or +2000gp or +20kgp
 * profit. for whatever batch just sold / how much profit over that square",
 * and "it also showed - red gp for when you lost money on somthing".
 */
public class ProfitPopsTest
{
	private static final Font FONT = new Font(Font.SANS_SERIF, Font.BOLD, 16);

	@Test
	public void saysWhatTheBatchMadeTheWayTheGameAbbreviates()
	{
		Assert.assertEquals("+200 gp", ProfitPops.text(200));
		Assert.assertEquals("+2,000 gp", ProfitPops.text(2_000));
		Assert.assertEquals("+20K gp", ProfitPops.text(20_000));
		Assert.assertEquals("-1,250 gp", ProfitPops.text(-1_250));
		Assert.assertEquals("-12K gp", ProfitPops.text(-12_000));
		Assert.assertEquals("+0 gp", ProfitPops.text(0));
		Assert.assertTrue(ProfitPops.text(Long.MIN_VALUE).startsWith("-"));
	}

	@Test
	public void greenForAGainRedForALoss()
	{
		Assert.assertEquals(ProfitPops.GAIN, ProfitPops.colour(1));
		Assert.assertEquals(ProfitPops.LOSS, ProfitPops.colour(-1));
		Assert.assertEquals(ProfitPops.EVEN, ProfitPops.colour(0));
	}

	/** Pops in a touch big, rises, fades, and is gone after its life. */
	@Test
	public void popsRisesAndFades()
	{
		Assert.assertTrue("starts small", ProfitPops.scale(0) < 1f);
		Assert.assertTrue("overshoots", ProfitPops.scale(100) > 1f);
		Assert.assertEquals("settles", 1f, ProfitPops.scale(400), 0f);
		Assert.assertEquals(0, ProfitPops.rise(0));
		Assert.assertTrue(ProfitPops.rise(1_000) < ProfitPops.rise(2_000));
		Assert.assertEquals(ProfitPops.RISE_PX, ProfitPops.rise(ProfitPops.LIFE_MS));
		Assert.assertEquals("solid at first", 1f, ProfitPops.alpha(500), 0f);
		Assert.assertTrue("fading late", ProfitPops.alpha(ProfitPops.LIFE_MS - 300) < 0.5f);
		Assert.assertEquals("gone", 0f, ProfitPops.alpha(ProfitPops.LIFE_MS), 0f);
		Assert.assertEquals("never before it happened", 0f, ProfitPops.alpha(-1), 0f);
	}

	/** Everything on screen. */
	private static List<ProfitPops.Pop> onScreen(ProfitPops pops, long now)
	{
		return pops.running(now, slot -> true);
	}

	/** Batches of one offer on back-to-back ticks read as one sale: the
	 *  figure adds up and pops again. Another slot's is its own. */
	@Test
	public void batchesTogetherAddUp()
	{
		final ProfitPops pops = new ProfitPops();
		pops.start(2, 1_000, 10_000);
		pops.start(3, -300, 10_100);
		/* A tick later, give or take the client's frame. */
		pops.start(2, 500, 10_630);
		final List<ProfitPops.Pop> live = onScreen(pops, 10_640);
		Assert.assertEquals(2, live.size());
		final ProfitPops.Pop two = live.stream().filter(p -> p.slot == 2).findFirst().get();
		Assert.assertEquals(1_500, two.profit);
		Assert.assertEquals("pops again from the bar", 10_630, two.at);
		Assert.assertEquals(-300, live.stream().filter(p -> p.slot == 3).findFirst().get().profit);
	}

	/**
	 * Never two figures on one slot. Each rises a line's height over its
	 * life, so two a second or so apart were drawn into each other — four
	 * "+2,000 gp" smeared together, from batches 600 ms apart.
	 */
	@Test
	public void neverTwoFiguresOnOneSlot()
	{
		final ProfitPops pops = new ProfitPops();
		final long[] at = {10_000, 10_610, 11_215, 11_830, 13_500, 16_000};
		for (long t : at)
		{
			pops.start(0, 2_000, t);
			Assert.assertEquals("one on the slot at " + t, 1, onScreen(pops, t).size());
		}
		final ProfitPops.Pop last = onScreen(pops, 16_000).get(0);
		Assert.assertEquals("a later batch is its own figure, not the run before it", 2_000, last.profit);
		Assert.assertEquals(16_000, last.at);
	}

	/** A figure whose square goes away runs out unseen; it is not drawn
	 *  off screen, and it does not start over when the square is back. */
	@Test
	public void aFigureRunsItsCourseOnceOnlyOverItsSquare()
	{
		final ProfitPops pops = new ProfitPops();
		pops.start(1, 5_000, 10_000);
		Assert.assertTrue(pops.running(10_500, slot -> false).isEmpty());
		Assert.assertEquals(1, onScreen(pops, 11_000).size());
		Assert.assertTrue(onScreen(pops, 10_000 + ProfitPops.LIFE_MS).isEmpty());
	}

	@Test
	public void clearTakesThemAllOff()
	{
		final ProfitPops pops = new ProfitPops();
		pops.start(0, 9_000, 1_000);
		pops.start(1, 9_000, 1_000);
		pops.clear();
		Assert.assertTrue(onScreen(pops, 1_000).isEmpty());
	}

	@Test
	public void goneOnceItsLifeIsOver()
	{
		final ProfitPops pops = new ProfitPops();
		pops.start(0, 1_000, 5_000);
		Assert.assertEquals(1, onScreen(pops, 5_000 + ProfitPops.LIFE_MS - 1).size());
		Assert.assertTrue(onScreen(pops, 5_000 + ProfitPops.LIFE_MS).isEmpty());
		pops.start(0, 1_000, 50_000);
		Assert.assertTrue("a clock set back does not leave it hanging", onScreen(pops, 40_000).isEmpty());
	}

	/** Past the guard, the oldest go and the newest stay, in order. */
	@Test
	public void aBurstKeepsTheNewest()
	{
		final ProfitPops pops = new ProfitPops();
		for (int i = 0; i < 40; i++)
		{
			pops.start(i, i, 1_000 + i);
		}
		final List<ProfitPops.Pop> live = onScreen(pops, 1_100);
		Assert.assertEquals(ProfitPops.MAX, live.size());
		Assert.assertEquals("the oldest gone", 40 - ProfitPops.MAX, live.get(0).slot);
		Assert.assertEquals("the newest kept", 39, live.get(live.size() - 1).slot);
	}

	/** Drawn over its own square, in its colour, and not once it is over. */
	@Test
	public void paintsOverItsSquareOnly()
	{
		final Rectangle slot = new Rectangle(120, 40, 115, 110);
		final ProfitPops.Pop gain = new ProfitPops.Pop(1, 0, 2_000);
		final BufferedImage img = paint(slot, gain, 400);
		Assert.assertTrue("green inside the square", count(img, slot, ProfitPops.GAIN) > 0);
		Assert.assertTrue("outlined in black, as the game's floating text is", count(img, slot, java.awt.Color.BLACK) > 0);
		Assert.assertEquals("nothing outside it", 0, count(img, outside(img, slot), ProfitPops.GAIN));

		final BufferedImage red = paint(slot, new ProfitPops.Pop(1, 0, -1_250), 400);
		Assert.assertTrue("a loss in red", count(red, slot, ProfitPops.LOSS) > 0);
		Assert.assertEquals(0, count(red, slot, ProfitPops.GAIN));

		final BufferedImage after = paint(slot, gain, ProfitPops.LIFE_MS);
		Assert.assertEquals("gone at the end", 0, count(after, new Rectangle(0, 0, img.getWidth(), img.getHeight()),
			ProfitPops.GAIN));
	}

	/** End to end through the tracker: a live sell's batches each pop what
	 *  they closed; a sell of something never seen bought pops the coins it
	 *  brought in, never as profit. */
	@Test
	public void eachBatchOfARealSellPopsItsProfit()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(42L);
		final int dart = 811;
		t.onOffer(1_000, 0, dart, "Rune dart", true, 0, 0, 100, 1_000, false);
		t.onOffer(2_000, 0, dart, "Rune dart", true, 1_000, 100_000, 100, 1_000, false);
		t.onOffer(3_000, 0, 0, "", false, 0, 0, 0, 0, true);
		t.onOffer(4_000, 1, dart, "Rune dart", false, 0, 0, 120, 1_000, false);

		t.onOffer(5_000, 1, dart, "Rune dart", false, 400, 48_000, 120, 1_000, false);
		/* 400 at 120 less the 2% tax (2 gp each), against 100 paid. */
		Assert.assertArrayEquals(new long[]{400, 400L * (120 - 2 - 100), FlipTracker.UNSEEN_PROFIT}, t.unseenBy(1, dart));
		t.markShown(1);

		t.onOffer(6_000, 1, dart, "Rune dart", false, 1_000, 120_000, 120, 1_000, false);
		Assert.assertArrayEquals(new long[]{600, 600L * (120 - 2 - 100), FlipTracker.UNSEEN_PROFIT}, t.unseenBy(1, dart));

		t.onOffer(7_000, 2, 565, "Blood rune", false, 0, 0, 400, 50, false);
		t.onOffer(8_000, 2, 565, "Blood rune", false, 50, 20_000, 400, 50, false);
		Assert.assertNull("never seen bought: nothing to call profit", t.bookedBy(2));
		Assert.assertArrayEquals("the coins it brought in, after tax",
			new long[]{50, 50L * (400 - 8), FlipTracker.UNSEEN_COINS}, t.unseenBy(2, 565));
	}

	private static BufferedImage paint(Rectangle slot, ProfitPops.Pop p, long now)
	{
		final BufferedImage img = new BufferedImage(360, 200, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		ProfitPops.draw(g, slot, p, now, FONT);
		g.dispose();
		return img;
	}

	private static Rectangle outside(BufferedImage img, Rectangle slot)
	{
		return new Rectangle(slot.x + slot.width, 0, img.getWidth() - slot.x - slot.width, img.getHeight());
	}

	/** Pixels in {@code area} that are {@code c}, near enough for antialiasing. */
	private static int count(BufferedImage img, Rectangle area, java.awt.Color c)
	{
		int n = 0;
		for (int y = Math.max(0, area.y); y < Math.min(img.getHeight(), area.y + area.height); y++)
		{
			for (int x = Math.max(0, area.x); x < Math.min(img.getWidth(), area.x + area.width); x++)
			{
				final int rgb = img.getRGB(x, y);
				if ((rgb >>> 24) > 200 && Math.abs(((rgb >> 16) & 0xFF) - c.getRed()) < 12
					&& Math.abs(((rgb >> 8) & 0xFF) - c.getGreen()) < 12 && Math.abs((rgb & 0xFF) - c.getBlue()) < 12)
				{
					n++;
				}
			}
		}
		return n;
	}
}

package com.pocketge.tracker;

import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/** The flip list's rolling window and its "Show all". */
public class RangeListTest
{
	private static final long HOUR = 3_600_000L;

	private static Flip flip(long closedAt)
	{
		return new Flip(closedAt, closedAt - 60_000L, closedAt, 1621, "Uncut emerald", 100, 31_700, 33_400, 700);
	}

	/** The list is redrawn when its oldest flip ages out of a rolling range. */
	@Test
	public void aRollingRangeKnowsWhenItsOldestFlipLeaves()
	{
		final List<Flip> in = List.of(flip(10 * HOUR), flip(10 * HOUR + 600_000L));
		Assert.assertEquals(11 * HOUR + 1, FlipStats.nextExpiry(in, FlipStats.Range.H1));
		Assert.assertEquals("session does not roll", 0, FlipStats.nextExpiry(in, FlipStats.Range.SESSION));
		Assert.assertEquals("nor does all time", 0, FlipStats.nextExpiry(in, FlipStats.Range.ALL));
		Assert.assertEquals("nothing listed, nothing to expire", 0, FlipStats.nextExpiry(List.of(), FlipStats.Range.H1));
	}

	/** The ledger never knows less than the tracker: a flip whose write
	 *  failed, or one booked on another computer, is still counted. */
	@Test
	public void theLedgerIsTopUpWithTheTrackersRecentFlips()
	{
		final Flip a = flip(10 * HOUR);
		final Flip b = flip(11 * HOUR);
		final Flip c = flip(12 * HOUR);
		final List<Flip> merged = PocketGeTrackerPlugin.mergeFlips(List.of(a, c), List.of(b, c));
		Assert.assertEquals(List.of(a, b, c), merged);
		Assert.assertEquals("nothing missing, nothing added", 2,
			PocketGeTrackerPlugin.mergeFlips(List.of(a, c), List.of(c)).size());
	}

	/** Two clients from one saved state mint the same offer tokens; their
	 *  flips of different items stay separate trades. */
	@Test
	public void aSharedTokenNeverJoinsTwoItems()
	{
		final Flip a = new Flip(2, HOUR, 2 * HOUR, 560, "Death rune", 100, 1_000, 2_000, 40);
		final Flip b = new Flip(2, HOUR, 2 * HOUR + 1, 2, "Steel cannonball", 100, 1_000, 2_000, 40);
		Assert.assertEquals(2, Flip.byTrade(List.of(a, b)).size());
	}

	/** A ledger read that failed partway is not taken as the whole file. */
	@Test
	public void aPartialLedgerReadIsNotTakenAsWhole() throws Exception
	{
		final java.io.File dir = java.nio.file.Files.createTempDirectory("pge-ledger").toFile();
		final FlipLedger ledger = new FlipLedger(new java.io.File(dir, "flips.jsonl"), new com.google.gson.Gson());
		Assert.assertNotNull("no file yet is a whole read of nothing", ledger.readAllOrNull());
		Assert.assertTrue(ledger.append(flip(HOUR)));
		Assert.assertEquals(1, ledger.readAllOrNull().size());
	}

	@Test
	public void theLatestFiveThenTheRestOnRequest()
	{
		Assert.assertEquals(5, HistoryPanel.shown(30, false));
		Assert.assertEquals("Show all 30", HistoryPanel.moreText(30, false));
		Assert.assertEquals(30, HistoryPanel.shown(30, true));
		Assert.assertEquals("Show fewer", HistoryPanel.moreText(30, true));
		Assert.assertEquals("nothing to toggle", "", HistoryPanel.moreText(4, false));
		Assert.assertEquals(HistoryPanel.SHOW_ALL_CAP, HistoryPanel.shown(5_000, true));
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

public class RangePositionTest
{
	private static RangePosition of(long lo, long hi, long opening)
	{
		final RangePosition r = new RangePosition();
		r.lo30 = lo;
		r.hi30 = hi;
		r.openingPrice = opening;
		return r;
	}

	/** The case that prompted the whole thing: Sapphire necklace, a real
	 *  30 gp spread, sitting at the top of a range it climbed 26% to reach. */
	@Test
	public void theSapphireNecklaceCaseReadsAsNearItsHigh()
	{
		final RangePosition r = of(426, 580, 452);
		Assert.assertTrue(r.usable());
		Assert.assertEquals(0.929, r.position(569), 0.002);
		Assert.assertEquals(25.9, r.runPct(569), 0.1);
		Assert.assertEquals("93% of 30d range · +26% in 30d", r.footnote(569));
	}

	/** Silence is the default. A card that says something about every item
	 *  says nothing about any of them. */
	@Test
	public void theMiddleOfTheRangeSaysNothing()
	{
		final RangePosition r = of(426, 580, 500);
		Assert.assertNull(r.footnote(500));
		Assert.assertNull(r.footnote(470));
		Assert.assertNull(r.footnote(530));
	}

	@Test
	public void theBottomOfTheRangeAlsoSpeaks()
	{
		final RangePosition r = of(426, 580, 560);
		Assert.assertEquals("7% of 30d range · -22% in 30d", r.footnote(437));
	}

	/**
	 * A flat item must not report "100% of its range".
	 *
	 * Arithmetically a 100-101 month puts 101 at the very top. It is also
	 * meaningless, and without this guard every stable item on the list would
	 * wear the loudest version of the badge.
	 */
	@Test
	public void anItemThatHasBarelyMovedHasNoUsableRange()
	{
		final RangePosition flat = of(100, 101, 100);
		Assert.assertFalse(flat.usable());
		Assert.assertEquals(-1, flat.position(101), 0.0001);
		Assert.assertNull(flat.footnote(101));
	}

	/** Exactly at the 5% floor is still too narrow; comfortably past it is not. */
	@Test
	public void theRangeFloorIsFivePercentOfTheHigh()
	{
		Assert.assertFalse("a 4.9% range is noise", of(951, 1000, 960).usable());
		Assert.assertTrue("a 10% range is real", of(900, 1000, 950).usable());
	}

	/**
	 * A live quote can legitimately sit above every completed bucket in the
	 * window — the range is history, the price is now.
	 */
	@Test
	public void aNewHighClampsToOneHundredPercentRatherThanOverflowing()
	{
		final RangePosition r = of(426, 580, 452);
		Assert.assertEquals(1.0, r.position(640), 0.0001);
		Assert.assertTrue(r.footnote(640).startsWith("100% of 30d range"));
	}

	/** "It did not move" and "we could not tell" are different claims. */
	@Test
	public void aMissingOpeningPriceIsNotAZeroPercentMove()
	{
		final RangePosition r = of(426, 580, 0);
		Assert.assertTrue(Double.isNaN(r.runPct(569)));
		Assert.assertEquals("no move to report, so the line carries only the position",
			"93% of 30d range", r.footnote(569));
	}

	/** A move too small to matter is left off rather than printed as +0%. */
	@Test
	public void aTinyMoveIsOmittedFromTheLine()
	{
		final RangePosition r = of(426, 580, 566);
		Assert.assertEquals("93% of 30d range", r.footnote(569));
	}

	@Test
	public void noDataMeansNoClaim()
	{
		final RangePosition empty = new RangePosition();
		Assert.assertFalse(empty.usable());
		Assert.assertNull(empty.footnote(569));
		Assert.assertEquals(-1, empty.position(569), 0.0001);
	}

	/* ── fromBuckets ─────────────────────────────────────────────────────── */

	@Test
	public void bucketsOutsideTheWindowAreIgnoredEntirely()
	{
		final long[] ts   = {100, 200, 300, 400};
		final long[] high = {900, 580, 560, 570};   // 900 is the stale one
		final long[] low  = {880, 426, 540, 560};
		final RangePosition r = RangePosition.fromBuckets(ts, high, low, 200);
		Assert.assertEquals("the pre-window 900 high must not widen the range", 580, r.hi30);
		Assert.assertEquals(426, r.lo30);
		Assert.assertEquals("opening is the first bucket INSIDE the window", 503, r.openingPrice);
	}

	/**
	 * A 6-hour bucket with no trades reports zero. That is an absence, not a
	 * price of nothing — treating it as a low would drag every range to 0 and
	 * make every item look like it was sitting on its high.
	 */
	@Test
	public void emptyBucketsDoNotDragTheRangeToZero()
	{
		final long[] ts   = {100, 200, 300};
		final long[] high = {580, 0, 570};
		final long[] low  = {520, 0, 540};
		final RangePosition r = RangePosition.fromBuckets(ts, high, low, 0);
		Assert.assertEquals(580, r.hi30);
		Assert.assertEquals(520, r.lo30);
	}

	@Test
	public void noBucketsYieldsNoClaim()
	{
		Assert.assertFalse(RangePosition.fromBuckets(null, null, null, 0).usable());
		Assert.assertFalse(RangePosition.fromBuckets(new long[0], new long[0], new long[0], 0).usable());
	}

	/** The line has to survive a 182px card. Longest realistic shape. */
	@Test
	public void theLineStaysShort()
	{
		final String longest = of(426, 580, 452).footnote(569);
		Assert.assertTrue("footnote was " + longest.length() + " chars: " + longest,
			longest.length() <= 32);
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * Which cards you page through first.
 *
 * Reported with 2,910 Mithril bars in the bank (2.66M, kept for use) and
 * gold free to flip with: twenty "sell from your bank" cards came before any
 * flip — "i keep finding myself clicking 15 pages back just to find 5
 * recommended flips".
 */
public class RecommendationOrderTest
{
	private static final long FLOOR = 2_000;
	private static final int MAX = 20;

	private static AdvisorPanel.Rec buy(String name, long profit, long capital)
	{
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.name = name;
		r.sell = false;
		r.profit = profit;
		r.capital = capital;
		return r;
	}

	private static AdvisorPanel.Rec sell(String name, long profit)
	{
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.name = name;
		r.sell = true;
		r.profit = profit;
		return r;
	}

	private static List<AdvisorPanel.Rec> buys(int n, long profit)
	{
		final List<AdvisorPanel.Rec> out = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			out.add(buy("flip " + i, profit, 700_000));
		}
		return out;
	}

	private static List<AdvisorPanel.Rec> sells(int n)
	{
		final List<AdvisorPanel.Rec> out = new ArrayList<>();
		out.add(sell("Mithril bar", 100_000));
		for (int i = 1; i < n; i++)
		{
			out.add(sell("stack " + i, 50_000));
		}
		return out;
	}

	private static List<AdvisorPanel.Rec> order(List<AdvisorPanel.Rec> buys, List<AdvisorPanel.Rec> sells)
	{
		final List<AdvisorPanel.Rec> out = new ArrayList<>();
		PocketGeTrackerPlugin.orderRecommendations(out, buys, sells, FLOOR, MAX);
		return out;
	}

	/** The reported bank: the flips come first, and the stacks still follow. */
	@Test
	public void flipsLeadABankWorthMoreThanTheCash()
	{
		final List<AdvisorPanel.Rec> out = order(buys(20, 20_000), sells(20));
		Assert.assertEquals(MAX, out.size());
		for (int i = 0; i < MAX - PocketGeTrackerPlugin.SELLS_KEPT_BEHIND_FLIPS; i++)
		{
			Assert.assertFalse("card " + (i + 1) + " is a flip", out.get(i).sell);
		}
		Assert.assertEquals("the best sell is still on the list", "Mithril bar",
			out.get(MAX - PocketGeTrackerPlugin.SELLS_KEPT_BEHIND_FLIPS).name);
	}

	/** Sells no longer use up the places before the buys are counted: the
	 *  five flips that used to be on pages 16-20 are pages 1-5. */
	@Test
	public void aFewFlipsAreNotPushedToTheEnd()
	{
		final List<AdvisorPanel.Rec> out = order(buys(5, 20_000), sells(30));
		for (int i = 0; i < 5; i++)
		{
			Assert.assertFalse(out.get(i).sell);
		}
		Assert.assertEquals(MAX, out.size());
		Assert.assertTrue(out.get(5).sell);
	}

	/** "Buy 40 Lobster pot for 1 gp ea" at a 344 gp purse: no real flip, so
	 *  the bank leads, as before. */
	@Test
	public void withNoRealFlipTheSellsLead()
	{
		final List<AdvisorPanel.Rec> out = order(List.of(buy("Lobster pot", 40, 40)), sells(3));
		Assert.assertTrue(out.get(0).sell);
		Assert.assertEquals("Lobster pot", out.get(out.size() - 1).name);
	}

	/** The adjust nudges a full board puts first stay first. */
	@Test
	public void whatIsAlreadyThereStaysFirst()
	{
		final List<AdvisorPanel.Rec> out = new ArrayList<>();
		out.add(sell("re-list your Rune bar", 5_000));
		PocketGeTrackerPlugin.orderRecommendations(out, buys(20, 20_000), sells(20), FLOOR, MAX);
		Assert.assertEquals("re-list your Rune bar", out.get(0).name);
		Assert.assertFalse(out.get(1).sell);
		Assert.assertEquals(MAX, out.size());
	}

	/** Few sells: the flips take every place the sells do not need. */
	@Test
	public void flipsFillWhatTheSellsDoNotNeed()
	{
		final List<AdvisorPanel.Rec> out = order(buys(25, 20_000), sells(2));
		Assert.assertEquals(MAX, out.size());
		Assert.assertEquals(18, out.stream().filter(r -> !r.sell).count());
	}

	/** The sell that finishes a flip you are in keeps its place behind the
	 *  flips, however many bigger stacks you held from before. */
	@Test
	public void aTrackedFlipsSellIsNotPushedOutByOldStacks()
	{
		final List<AdvisorPanel.Rec> sells = new ArrayList<>();
		for (String name : new String[]{"Mithril bar", "Coal", "Law rune", "Iron ore", "Nature rune", "Feather"})
		{
			final AdvisorPanel.Rec r = sell(name, 700_000);
			r.hasTrackedCost = false; // held from before: ranked on its whole value
			sells.add(r);
		}
		sells.add(sell("Yew logs", 34_000)); // bought through the plugin, ranked on profit
		final List<AdvisorPanel.Rec> out = order(buys(20, 5_000), sells);
		final int first = MAX - PocketGeTrackerPlugin.SELLS_KEPT_BEHIND_FLIPS;
		Assert.assertEquals("Yew logs", out.get(first).name);
		Assert.assertEquals("then the biggest of the rest, in rank order", "Mithril bar", out.get(first + 1).name);
	}

	/** A player's own Min profit raises the bar a flip has to clear to lead. */
	@Test
	public void theFloorIsThePlayersOwn()
	{
		final List<AdvisorPanel.Rec> out = new ArrayList<>();
		PocketGeTrackerPlugin.orderRecommendations(out, buys(3, 20_000), sells(3), 50_000, MAX);
		Assert.assertTrue(out.get(0).sell);
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import org.junit.Assert;
import org.junit.Test;

/**
 * The "Copy PocketGE report" text: the numbers no card shows, raw, and
 * nothing that identifies the player.
 *
 * Asked about after PAID @ 964 on Sapphire necklaces bought at 453-559 —
 * a figure that can only be checked against the buy lots and fills behind
 * it, which this prints.
 */
public class ReportTest
{
	private static final int SAPPHIRE_NECKLACE = 1656;
	private static final long ACCOUNT = 987_654_321_012L;

	private static void set(Object o, String field, Object v) throws Exception
	{
		final Field f = o.getClass().getDeclaredField(field);
		f.setAccessible(true);
		f.set(o, v);
	}

	@SuppressWarnings("unchecked")
	private static <T> T stub(Class<T> type, Map<String, Object> answers)
	{
		return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, (p, m, a) ->
		{
			if (answers.containsKey(m.getName()))
			{
				return answers.get(m.getName());
			}
			final Class<?> r = m.getReturnType();
			if (r == boolean.class)
			{
				return false;
			}
			return r.isPrimitive() ? (r == long.class ? (Object) 0L : (Object) 0) : null;
		});
	}

	private static String report() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		set(plugin, "client", stub(Client.class, Map.of("getGrandExchangeOffers", new GrandExchangeOffer[8])));
		set(plugin, "config", stub(PocketGeTrackerConfig.class, Map.of()));
		final Field tf = PocketGeTrackerPlugin.class.getDeclaredField("tracker");
		tf.setAccessible(true);
		final FlipTracker tracker = (FlipTracker) tf.get(plugin);
		tracker.setAccountHash(ACCOUNT);
		tracker.onOffer(1_000L, 0, SAPPHIRE_NECKLACE, "Sapphire necklace", true, 0, 0L, 453, 5_000, false);
		tracker.onOffer(2_000L, 0, SAPPHIRE_NECKLACE, "Sapphire necklace", true, 5_000, 5_000L * 453, 453, 5_000, false);
		return plugin.buildReport(SAPPHIRE_NECKLACE, "Sapphire necklace", "  verb SELL\n");
	}

	/** The 4-hour limit as the advisor sees it, so a report can say why an
	 *  item is or is not being suggested again. These fills are long past,
	 *  so the window is whole; a buy in the last four hours counts. */
	@Test
	public void itSaysWhereTheBuyLimitStands() throws Exception
	{
		Assert.assertTrue(report().contains("== 4h buy limit ==\n  limit unknown, bought toward it 0\n"));

		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		set(plugin, "client", stub(Client.class, Map.of("getGrandExchangeOffers", new GrandExchangeOffer[8])));
		set(plugin, "config", stub(PocketGeTrackerConfig.class, Map.of()));
		final Field tf = PocketGeTrackerPlugin.class.getDeclaredField("tracker");
		tf.setAccessible(true);
		final FlipTracker tracker = (FlipTracker) tf.get(plugin);
		tracker.setAccountHash(ACCOUNT);
		/* Half a minute short of an hour ago: the countdown rounds down, so
		   at exactly an hour a single millisecond before the report is built
		   read "2h 59m" and failed this on a busy machine. */
		tracker.noteBuyForLimit(SAPPHIRE_NECKLACE, 5_000, System.currentTimeMillis() - 60 * 60_000L + 30_000L);
		final String r = plugin.buildReport(SAPPHIRE_NECKLACE, "Sapphire necklace", null);
		Assert.assertTrue(r, r.contains("bought toward it 5000, whole again in 3h"));
	}

	@Test
	public void itShowsTheLotsAndFillsBehindPaid() throws Exception
	{
		final String r = report();
		Assert.assertTrue(r, r.contains("== open buy lots"));
		Assert.assertTrue(r, r.contains("5000 for 2265000 (453.0 each)"));
		Assert.assertTrue(r, r.contains("BUY  5000 for 2265000 (453 each)"));
		Assert.assertTrue("the card's own fields come through", r.contains("verb SELL"));
		Assert.assertTrue("every slot is listed", r.contains("slot 8: empty"));
	}

	/** The same lot twice is what an old build's hop re-booking left, and
	 *  more bought than held says the lots are wrong — both flagged. */
	@Test
	public void itFlagsALotBookedTwice() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		set(plugin, "client", stub(Client.class, Map.of("getGrandExchangeOffers", new GrandExchangeOffer[8])));
		set(plugin, "config", stub(PocketGeTrackerConfig.class, Map.of()));
		final Field tf = PocketGeTrackerPlugin.class.getDeclaredField("tracker");
		tf.setAccessible(true);
		final FlipTracker tracker = (FlipTracker) tf.get(plugin);
		final FlipTracker.State s = new FlipTracker.State();
		s.openBuys = new java.util.HashMap<>();
		s.openBuys.put(SAPPHIRE_NECKLACE, java.util.List.of(
			new long[]{5_000, 5_000L * 453, 1_000L}, new long[]{5_000, 5_000L * 453}));
		tracker.restore(s);
		final String r = plugin.buildReport(SAPPHIRE_NECKLACE, "Sapphire necklace", "");
		Assert.assertTrue(r, r.contains("(no time)  <- same total as the lots just before it"));
		Assert.assertTrue(r, r.contains("more than this character holds (bank + inventory + GE slots = 0)"));
	}

	/** An honest offline refill at the same bid matches the fills before
	 *  it too: the match is stated, but nothing says "more than you hold"
	 *  while the stack is all there. */
	@Test
	public void lotsInStepWithTheStackAreNotFlagged() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		set(plugin, "client", stub(Client.class, Map.of("getGrandExchangeOffers", new GrandExchangeOffer[8])));
		set(plugin, "config", stub(PocketGeTrackerConfig.class, Map.of()));
		final Field tf = PocketGeTrackerPlugin.class.getDeclaredField("tracker");
		tf.setAccessible(true);
		final FlipTracker tracker = (FlipTracker) tf.get(plugin);
		final FlipTracker.State s = new FlipTracker.State();
		s.openBuys = new java.util.HashMap<>();
		s.openBuys.put(SAPPHIRE_NECKLACE, java.util.List.of(
			new long[]{5_000, 5_000L * 453, 1_000L}, new long[]{5_000, 5_000L * 453}));
		tracker.restore(s);
		final Field bank = PocketGeTrackerPlugin.class.getDeclaredField("lastBank");
		bank.setAccessible(true);
		@SuppressWarnings("unchecked")
		final Map<Integer, Integer> lastBank = (Map<Integer, Integer>) bank.get(plugin);
		lastBank.put(SAPPHIRE_NECKLACE, 10_000);
		final String r = plugin.buildReport(SAPPHIRE_NECKLACE, "Sapphire necklace", "");
		Assert.assertTrue(r, r.contains("same total as the lots just before it"));
		Assert.assertFalse(r, r.contains("more than"));
	}

	/** Which lots look re-booked: a time-less lot equal to a run of the
	 *  lots before it. An offer filling in equal timed chunks is honest. */
	@Test
	public void aRebookIsTheSumOfTheFillsBeforeIt()
	{
		final java.util.List<long[]> watched = java.util.List.of(
			new long[]{173, 173L * 876, 1_000L}, new long[]{3_565, 3_565L * 876, 2_000L},
			new long[]{3_738, 3_738L * 876, 0L});
		Assert.assertTrue("173 + 3,565 re-booked as 3,738", PocketGeTrackerPlugin.repeatsEarlierLots(watched, 2));
		Assert.assertFalse(PocketGeTrackerPlugin.repeatsEarlierLots(watched, 1));

		final java.util.List<long[]> chunks = java.util.List.of(
			new long[]{1, 1_250_000L, 1_000L}, new long[]{1, 1_250_000L, 2_000L});
		Assert.assertFalse("one at a time at the bid", PocketGeTrackerPlugin.repeatsEarlierLots(chunks, 1));

		final java.util.List<long[]> unrelated = java.util.List.of(
			new long[]{100, 87_600L, 1_000L}, new long[]{250, 219_000L});
		Assert.assertFalse("no run of earlier lots adds up to it", PocketGeTrackerPlugin.repeatsEarlierLots(unrelated, 1));
	}

	@Test
	public void itSaysWhichBuild() throws Exception
	{
		Assert.assertTrue(report().contains("by PocketGE " + BuildInfo.VERSION));
	}

	@Test
	public void itNeverCarriesTheAccount() throws Exception
	{
		final String r = report();
		Assert.assertFalse(r, r.contains(String.valueOf(ACCOUNT)));
	}
}

package com.pocketge.tracker;

import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * A sale is charged against the stack you bought last — among what was
 * bought before the offer was listed — never against older buys the plugin
 * did not see leave.
 *
 * Reported: 13,418 Aether catalysts bought at 277 and sold at 280 (275
 * after tax) booked -1.12M, charged at 359 each against 24,500 left over
 * from an earlier stack sold where the plugin did not see it. The real
 * result was -26,836.
 */
public class SaleCostTest
{
	private static final int AETHER = 30771;
	private static final int ITEM = 561;
	private static final long MIN = 60_000L, HOUR = 60 * MIN, DAY = 24 * HOUR;
	private static final long NOW = 1_000 * DAY;

	private static void bought(FlipTracker t, int slot, int item, long price, int qty, long at)
	{
		t.onOffer(at - 1, slot, item, "x", true, 0, 0L, price, qty, false);
		t.onOffer(at, slot, item, "x", true, qty, qty * price, price, qty, false);
		t.onOffer(at + 1, slot, 0, "", false, 0, 0L, 0, 0, true); // collected
	}

	private static FlipTracker userCase()
	{
		final FlipTracker t = new FlipTracker();
		bought(t, 0, AETHER, 359, 24_500, NOW - 5 * DAY); // sold later where the plugin did not see
		bought(t, 1, AETHER, 277, 13_418, NOW - 2 * HOUR);
		t.onOffer(NOW - 30 * MIN, 2, AETHER, "Aether catalyst", false, 0, 0L, 280, 13_418, false);
		return t;
	}

	private static Flip last(FlipTracker t)
	{
		final List<Flip> f = t.getFlips();
		return f.get(f.size() - 1);
	}

	@Test
	public void theUsersSaleIsChargedAtWhatTheyPaidForThisStack()
	{
		final FlipTracker t = userCase();
		t.onOffer(NOW, 2, AETHER, "Aether catalyst", false, 13_418, 13_418L * 280, 280, 13_418, false);
		final Flip f = last(t);
		Assert.assertEquals(13_418L * 277, f.buySpent);
		Assert.assertEquals(67_090L, f.tax);
		Assert.assertEquals(-26_836L, f.profit);
		Assert.assertEquals("held two hours, not five days", 2 * HOUR, f.holdMillis());
		Assert.assertArrayEquals("the leftovers are untouched", new long[]{24_500, 24_500L * 359},
			t.getOpenBuyTotal(AETHER));
	}

	/** The same sale, filled while logged out and booked at the next login. */
	@Test
	public void soAcrossARestartAndALoginReplay()
	{
		final FlipTracker before = userCase();
		final FlipTracker t = new FlipTracker();
		t.restore(before.snapshot());
		t.onOffer(NOW + 8 * HOUR, 2, AETHER, "Aether catalyst", false, 13_418, 13_418L * 280, 280, 13_418, false);
		Assert.assertEquals(-26_836L, last(t).profit);
	}

	/** Buying and selling one item in two slots: what the buy fills after
	 *  the sell was listed is in the buy's box, not in the sell. */
	@Test
	public void aBuyFilledAfterTheSellWasListedIsNotWhatItSold()
	{
		final FlipTracker t = new FlipTracker();
		t.onOffer(NOW - 61 * MIN, 0, ITEM, "x", true, 0, 0L, 100, 3_000, false);
		t.onOffer(NOW - 60 * MIN, 0, ITEM, "x", true, 1_000, 100_000L, 100, 3_000, false);
		t.onOffer(NOW - 50 * MIN, 1, ITEM, "x", false, 0, 0L, 110, 1_000, false);       // listed
		t.onOffer(NOW - 40 * MIN, 0, ITEM, "x", true, 1_500, 150_000L, 100, 3_000, false); // after
		bought(t, 2, ITEM, 102, 500, NOW - 20 * MIN);                                       // after
		t.onOffer(NOW, 1, ITEM, "x", false, 1_000, 110_000L, 110, 1_000, false);
		final Flip f = last(t);
		Assert.assertEquals(100_000L, f.buySpent);
		Assert.assertEquals(60 * MIN, f.holdMillis());
	}

	/** ...and the bound is kept across a restart. */
	@Test
	public void theListingBoundSurvivesARestart()
	{
		final FlipTracker a = new FlipTracker();
		bought(a, 0, ITEM, 100, 1_000, NOW - 2 * HOUR);
		a.onOffer(NOW - HOUR, 1, ITEM, "x", false, 0, 0L, 110, 1_000, false);
		final FlipTracker t = new FlipTracker();
		t.restore(a.snapshot());
		bought(t, 0, ITEM, 130, 1_000, NOW - 30 * MIN); // after the listing, after the restart
		t.onOffer(NOW, 1, ITEM, "x", false, 1_000, 110_000L, 110, 1_000, false);
		Assert.assertEquals(100_000L, last(t).buySpent);
	}

	/** A save from before lots were numbered: everything on record may be in
	 *  a listed offer, and nothing bought after the restore can be. */
	@Test
	public void aSaveWithoutNumbersStillMatchesNewestFirst()
	{
		final FlipTracker.State s = new FlipTracker.State();
		s.flips = new java.util.ArrayList<>();
		s.openBuys = new java.util.HashMap<>();
		s.openBuys.put(ITEM, List.of(new long[]{1_000, 359_000L, NOW - 5 * DAY}, new long[]{1_000, 277_000L, NOW - HOUR}));
		s.slotsByAccount = new java.util.HashMap<>();
		final java.util.Map<Integer, long[]> rows = new java.util.HashMap<>();
		rows.put(2, new long[]{ITEM, 0, 0, 0, 280, 1_000, 7, 0, 0, 0, 0, 0}); // a listed sell, no bound
		s.slotsByAccount.put(0L, rows);
		s.slotsFormat = FlipTracker.SLOTS_FORMAT;
		s.nextOfferToken = 8;
		final FlipTracker t = new FlipTracker();
		t.restore(s);
		bought(t, 0, ITEM, 500, 1_000, NOW - MIN);
		t.onOffer(NOW, 2, ITEM, "x", false, 1_000, 280_000L, 280, 1_000, false);
		Assert.assertEquals(277_000L, last(t).buySpent);
	}

	/** A long-held stack keeps its own cost when the same item is flipped
	 *  on top of it: the flip is the 120s, held half an hour. */
	@Test
	public void aStackHeldForWeeksKeepsItsCostUnderAFlipOfTheSameItem()
	{
		final FlipTracker t = new FlipTracker();
		bought(t, 0, ITEM, 100, 5_000, NOW - 21 * DAY);
		bought(t, 1, ITEM, 120, 1_000, NOW - 30 * MIN);
		t.onOffer(NOW - 20 * MIN, 2, ITEM, "x", false, 0, 0L, 125, 1_000, false);
		t.onOffer(NOW, 2, ITEM, "x", false, 1_000, 125_000L, 125, 1_000, false);
		Assert.assertEquals(3_000L, last(t).profit);
		Assert.assertEquals(30 * MIN, last(t).holdMillis());
		Assert.assertArrayEquals(new long[]{5_000, 500_000L}, t.getOpenBuyTotal(ITEM));
	}

	/** Selling more than was bought since reaches the older lots, oldest of
	 *  them last, and the clock is the oldest it reached. */
	@Test
	public void aBiggerSaleReachesTheOlderLots()
	{
		final FlipTracker t = new FlipTracker();
		bought(t, 0, ITEM, 100, 1_000, NOW - 3 * HOUR);
		bought(t, 1, ITEM, 120, 1_000, NOW - HOUR);
		t.onOffer(NOW - 30 * MIN, 2, ITEM, "x", false, 0, 0L, 125, 1_500, false);
		t.onOffer(NOW, 2, ITEM, "x", false, 1_500, 187_500L, 125, 1_500, false);
		Assert.assertEquals(120_000L + 50_000L, last(t).buySpent);
		Assert.assertEquals(3 * HOUR, last(t).holdMillis());
		Assert.assertArrayEquals(new long[]{500, 50_000L}, t.getOpenBuyTotal(ITEM));
	}

	/** Lot numbers survive a save, so a forget prompt read before it still
	 *  drops exactly what it showed. */
	@Test
	public void lotNumbersSurviveASave()
	{
		final FlipTracker a = new FlipTracker();
		bought(a, 0, ITEM, 100, 1_000, NOW - HOUR);
		final long[] shown = a.getOpenBuyRecord(ITEM);
		final FlipTracker t = new FlipTracker();
		t.restore(new com.google.gson.Gson().fromJson(new com.google.gson.Gson().toJson(a.snapshot()), FlipTracker.State.class));
		bought(t, 0, ITEM, 120, 1_000, NOW);
		Assert.assertArrayEquals(new long[]{1_000, 100_000L}, t.forgetOpenBuys(ITEM, shown[2]));
		Assert.assertArrayEquals(new long[]{1_000, 120_000L}, t.getOpenBuyTotal(ITEM));
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * A sale is charged only to units that could be in it: this character's
 * buys, made before the offer was listed, and not waiting in a buy's
 * collection box at that moment. Newest first among those.
 */
public class SaleProvenanceTest
{
	private static final int AETHER = 30771, ITEM = 561;
	private static final long MIN = 60_000L, HOUR = 60 * MIN, DAY = 24 * HOUR, NOW = 1_000 * DAY;
	private static final long MAIN = 111L, ALT = 222L;
	private static final long TRUTH = 3_757_040L - 67_090L - 13_418L * 277; // -26,836

	private static void placeBuy(FlipTracker t, int slot, int item, long price, int qty, long at)
	{
		t.onOffer(at, slot, item, "x", true, 0, 0L, price, qty, false);
	}

	private static void fillBuy(FlipTracker t, int slot, int item, long price, int qty, int total, long at)
	{
		t.onOffer(at, slot, item, "x", true, qty, qty * price, price, total, false);
	}

	private static void collect(FlipTracker t, int slot, long at)
	{
		t.onOffer(at, slot, 0, "", false, 0, 0L, 0, 0, true);
	}

	private static void bought(FlipTracker t, int slot, int item, long price, int qty, long at)
	{
		placeBuy(t, slot, item, price, qty, at - 1);
		fillBuy(t, slot, item, price, qty, qty, at);
		collect(t, slot, at + 1);
	}

	private static void list(FlipTracker t, int slot, int item, long price, int qty, long at)
	{
		t.onOffer(at, slot, item, "x", false, 0, 0L, price, qty, false);
	}

	private static void sold(FlipTracker t, int slot, int item, long price, int qty, int total, long at)
	{
		t.onOffer(at, slot, item, "x", false, qty, (long) qty * price, price, total, false);
	}

	private static Flip last(FlipTracker t)
	{
		final List<Flip> f = t.getFlips();
		return f.isEmpty() ? null : f.get(f.size() - 1);
	}

	/** Holds 13,418@277; a 25,000@359 buy finishes into its box; the 13,418
	 *  are listed. FIFO got this right; plain newest-first booked -1.12M. */
	private static FlipTracker boxedAtListing(boolean boxSeen)
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(MAIN);
		bought(t, 0, AETHER, 277, 13_418, NOW - 5 * HOUR);
		placeBuy(t, 1, AETHER, 359, 25_000, NOW - 3 * HOUR);
		fillBuy(t, 1, AETHER, 359, 25_000, 25_000, NOW - 2 * HOUR);
		if (boxSeen)
		{
			t.noteBox(1, AETHER, 25_000);
		}
		list(t, 2, AETHER, 280, 13_418, NOW - HOUR);
		return t;
	}

	@Test
	public void unitsWaitingInABuysBoxAreNotWhatWasListed()
	{
		for (boolean seen : new boolean[]{true, false})
		{
			final FlipTracker t = boxedAtListing(seen);
			sold(t, 2, AETHER, 280, 13_418, 13_418, NOW);
			Assert.assertEquals("box seen " + seen, TRUTH, last(t).profit);
			Assert.assertArrayEquals(new long[]{25_000, 25_000L * 359}, t.getOpenBuyTotal(AETHER));
		}
	}

	/** Collecting the buy after the listing does not put its units in it. */
	@Test
	public void collectingTheBuyAfterTheListingChangesNothing()
	{
		final FlipTracker t = boxedAtListing(true);
		collect(t, 1, NOW - 30 * MIN);
		sold(t, 2, AETHER, 280, 13_418, 13_418, NOW);
		Assert.assertEquals(TRUTH, last(t).profit);
	}

	/** A running buy with part of it in the box: only the boxed part is out. */
	@Test
	public void aRunningBuysBoxedPartIsOutItsCollectedPartIsIn()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(MAIN);
		bought(t, 0, AETHER, 359, 24_500, NOW - 5 * DAY); // left unseen
		placeBuy(t, 1, AETHER, 277, 25_000, NOW - 3 * HOUR);
		fillBuy(t, 1, AETHER, 277, 13_418, 25_000, NOW - 2 * HOUR);
		t.noteBox(1, AETHER, 13_418);
		t.noteBox(1, AETHER, 0); // collected; the buy runs on
		list(t, 2, AETHER, 280, 13_418, NOW - HOUR);
		sold(t, 2, AETHER, 280, 13_418, 13_418, NOW);
		Assert.assertEquals(TRUTH, last(t).profit);
	}

	/** Login replay: a buy that finished offline into its box is read before
	 *  a sell listed and sold on mobile from the older stack. */
	@Test
	public void aReplayedFinishedBuyStillInItsBoxIsNotTheSale()
	{
		final FlipTracker a = new FlipTracker();
		a.setAccountHash(MAIN);
		bought(a, 0, AETHER, 277, 13_418, NOW - 10 * HOUR);
		placeBuy(a, 1, AETHER, 359, 25_000, NOW - 9 * HOUR);
		final FlipTracker t = new FlipTracker();
		t.restore(a.snapshot());
		t.setAccountHash(MAIN);
		fillBuy(t, 1, AETHER, 359, 25_000, 25_000, NOW);
		sold(t, 3, AETHER, 280, 13_418, 13_418, NOW);
		Assert.assertEquals(TRUTH, last(t).profit);
	}

	/** ...but a finished buy remembered from before the logout proves
	 *  nothing until its slot is seen again: collected on mobile and sold
	 *  there, its EMPTY waits out the login clear while the sale arrives. */
	@Test
	public void aBuyRememberedFromBeforeTheGapIsNotAssumedStillBoxed()
	{
		final FlipTracker a = new FlipTracker();
		a.setAccountHash(MAIN);
		bought(a, 0, AETHER, 359, 24_500, NOW - 5 * DAY); // left unseen
		placeBuy(a, 1, AETHER, 277, 25_000, NOW - 9 * HOUR);
		fillBuy(a, 1, AETHER, 277, 25_000, 25_000, NOW - 8 * HOUR);
		final FlipTracker t = new FlipTracker();
		t.restore(a.snapshot());
		t.setAccountHash(MAIN);
		sold(t, 4, AETHER, 300, 25_000, 25_000, NOW); // never-seen sell, in the replay
		collect(t, 1, NOW + 1);                        // the sweep, after the settle
		Assert.assertEquals(25_000L * 277, last(t).buySpent);
	}

	@Test
	public void aCharactersSaleIsChargedToItsOwnBuysInEitherOrder()
	{
		for (boolean altFirst : new boolean[]{true, false})
		{
			final FlipTracker t = new FlipTracker();
			t.setAccountHash(altFirst ? ALT : MAIN);
			bought(t, 0, AETHER, altFirst ? 277 : 359, altFirst ? 13_418 : 25_000, NOW - 5 * HOUR);
			t.setAccountHash(altFirst ? MAIN : ALT);
			bought(t, 0, AETHER, altFirst ? 359 : 277, altFirst ? 25_000 : 13_418, NOW - 3 * HOUR);
			t.setAccountHash(ALT);
			list(t, 1, AETHER, 280, 13_418, NOW - HOUR);
			sold(t, 1, AETHER, 280, 13_418, 13_418, NOW);
			Assert.assertEquals("alt first " + altFirst, TRUTH, last(t).profit);
			t.setAccountHash(MAIN);
			Assert.assertArrayEquals("main's stack untouched", new long[]{25_000, 25_000L * 359}, t.getOpenBuyTotal(AETHER));
		}
	}

	/** Bought on one character, sold on another: no cost on record for the
	 *  seller, so nothing is booked — unknown, never another's price. */
	@Test
	public void anotherCharactersBuysAreNeverCharged()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(ALT);
		bought(t, 0, ITEM, 100, 1_000, NOW - 2 * HOUR);
		t.setAccountHash(MAIN);
		list(t, 1, ITEM, 110, 1_000, NOW - HOUR);
		sold(t, 1, ITEM, 110, 1_000, 1_000, NOW);
		Assert.assertNull(last(t));
	}

	/** Lots from a save that did not record whose they were: any character. */
	@Test
	public void unattributedLotsFromAnOlderSaveServeAnyCharacter()
	{
		final FlipTracker.State s = new FlipTracker.State();
		s.flips = new java.util.ArrayList<>();
		s.openBuys = new HashMap<>();
		s.openBuys.put(ITEM, List.of(new long[]{1_000, 100_000L, NOW - DAY})); // 0.7.1 shape
		s.slotsFormat = FlipTracker.SLOTS_FORMAT;
		final FlipTracker t = new FlipTracker();
		t.restore(s);
		t.setAccountHash(ALT);
		list(t, 1, ITEM, 110, 1_000, NOW - HOUR);
		sold(t, 1, ITEM, 110, 1_000, 1_000, NOW);
		Assert.assertEquals(100_000L, last(t).buySpent);
	}

	/** What the slot's hover projects is what the sale then books. */
	@Test
	public void thePreviewIsTheBooking()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(MAIN);
		bought(t, 0, ITEM, 100, 5_000, NOW - 21 * DAY);
		bought(t, 1, ITEM, 120, 1_000, NOW - 30 * MIN);
		list(t, 2, ITEM, 125, 1_000, NOW - 20 * MIN);
		final long[] p = t.previewSale(2);
		sold(t, 2, ITEM, 125, 1_000, 1_000, NOW);
		Assert.assertArrayEquals(new long[]{1_000, 120_000L}, p);
		Assert.assertEquals(p[1], last(t).buySpent);
		final FlipTracker u = boxedAtListing(true);
		final long[] q = u.previewSale(2);
		sold(u, 2, AETHER, 280, 13_418, 13_418, NOW);
		Assert.assertEquals(q[1], last(u).buySpent);
	}

	/** The card prices the stack you can list, not the box beside it. */
	@Test
	public void paidAtLeavesOutWhatIsInABox()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(MAIN);
		bought(t, 0, AETHER, 277, 13_418, NOW - 5 * HOUR);
		placeBuy(t, 1, AETHER, 359, 25_000, NOW - 3 * HOUR);
		fillBuy(t, 1, AETHER, 359, 25_000, 25_000, NOW - 2 * HOUR);
		t.noteBox(1, AETHER, 25_000);
		final Map<Integer, Long> held = new HashMap<>();
		held.put(AETHER, 13_418L + 25_000L); // heldForCost counts the box
		Assert.assertArrayEquals(new long[]{13_418, 13_418L * 277, 0, 0}, t.getHeldCost(held).get(AETHER));
	}

	/** Owner, source and the listing's box snapshot survive a save. */
	@Test
	public void provenanceSurvivesASave()
	{
		final FlipTracker a = boxedAtListing(true);
		a.setAccountHash(ALT);
		bought(a, 0, AETHER, 300, 1_000, NOW - 90 * MIN);
		a.setAccountHash(MAIN);
		final Gson g = new Gson();
		final FlipTracker t = new FlipTracker();
		t.restore(g.fromJson(g.toJson(a.snapshot()), FlipTracker.State.class));
		t.setAccountHash(MAIN);
		collect(t, 1, NOW - 10 * MIN); // box state is not saved; the snapshot is
		sold(t, 2, AETHER, 280, 13_418, 13_418, NOW);
		Assert.assertEquals(TRUTH, last(t).profit);
	}

	/** A hold that reaches a lot with no fill time is unknown, as in merge —
	 *  even when that lot is the newer one: a receipt first seen today may
	 *  have been bought weeks ago. */
	@Test
	public void aHoldReachingAnUntimedLotIsUnknown()
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(MAIN);
		bought(t, 0, ITEM, 120, 1_000, NOW - HOUR);
		t.onOffer(NOW - 50 * MIN, 1, ITEM, "x", true, 1_000, 100_000L, 100, 1_000, false); // first sighting: untimed
		collect(t, 1, NOW - 50 * MIN + 1);
		list(t, 2, ITEM, 125, 2_000, NOW - 30 * MIN);
		sold(t, 2, ITEM, 125, 2_000, 2_000, NOW);
		Assert.assertEquals(-1L, last(t).holdMillis());
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/**
 * The chip on "What would you like to buy?". That search only ever buys —
 * a sell starts from the inventory — so it offers a buy: the card's own item
 * on a buy card, the next buy idea on a sell card, never the stack a sell
 * card is telling you to sell.
 */
public class SearchChipTest
{
	private static final int RUNE_DART = 811;
	private static final int STEAM_RUNE = 4694;
	private static final int BOLT_TIPS = 9193;
	private static final int BLOOD_RUNE = 565;

	/** Every item the chip was handed, in order. */
	private final List<Integer> chip = new ArrayList<>();

	private AdvisorPanel panel()
	{
		final AdvisorPanel.Actions actions = (AdvisorPanel.Actions) Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(proxy, method, args) ->
			{
				if ("onSearchItemShown".equals(method.getName()))
				{
					chip.add((Integer) args[0]);
				}
				final Class<?> t = method.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				if (t == int.class || t == long.class || t == double.class || t == float.class)
				{
					return 0;
				}
				return null;
			});
		return new AdvisorPanel(null, actions);
	}

	private static AdvisorPanel.Rec rec(int id, String name, boolean sell)
	{
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.itemId = id;
		r.name = name;
		r.sell = sell;
		r.quantity = 1_000;
		r.unitPrice = 100;
		r.profit = 50_000;
		return r;
	}

	private Integer chipNow()
	{
		return chip.isEmpty() ? null : chip.get(chip.size() - 1);
	}

	@Test
	public void aBuyCardOffersItsOwnItem()
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(new ArrayList<>(Arrays.asList(rec(RUNE_DART, "Rune dart", false), rec(STEAM_RUNE, "Steam rune", false))));
		Assert.assertEquals(Integer.valueOf(RUNE_DART), chipNow());
	}

	/** A sell card offers the next buy idea after it, not its own stack. */
	@Test
	public void aSellCardOffersTheNextBuyNotItsOwnStack() throws Exception
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(new ArrayList<>(Arrays.asList(rec(BLOOD_RUNE, "Blood rune", false),
			rec(BOLT_TIPS, "Dragonstone bolt tips", true), rec(RUNE_DART, "Rune dart", false))));
		final Field f = AdvisorPanel.class.getDeclaredField("recIndex");
		f.setAccessible(true);
		f.setInt(p, 1);
		p.setRecommendations(new ArrayList<>(Arrays.asList(rec(BLOOD_RUNE, "Blood rune", false),
			rec(BOLT_TIPS, "Dragonstone bolt tips", true), rec(RUNE_DART, "Rune dart", false))));
		Assert.assertEquals("the buy after it", Integer.valueOf(RUNE_DART), chipNow());
		Assert.assertFalse("never the stack it says to sell", chip.contains(BOLT_TIPS));
	}

	/** Only sells to show: nothing to offer, so nothing is offered. */
	@Test
	public void noBuyIdeaMeansNoChip()
	{
		final AdvisorPanel p = panel();
		p.setRecommendations(new ArrayList<>(Arrays.asList(rec(BOLT_TIPS, "Dragonstone bolt tips", true))));
		Assert.assertNull(chipNow());
		Assert.assertNull(p.searchItemFor(rec(BOLT_TIPS, "Dragonstone bolt tips", true)));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import org.junit.Assert;
import org.junit.Test;

/**
 * The inspected-item card for a stack you hold: what you paid, and what
 * selling makes.
 *
 * Reported from a real screen: 639 Mithril bars, 173 of them bought through
 * the plugin at 876 gp. The card said "PAID @ 3,252", "+1,038 gp profit" and
 * "Up -73% on what you paid", beside a SELL @ box of 896. The paid figure
 * divided the whole stack's proceeds by the 173 tracked units; the profit was
 * priced at the live insta-buy (900), not at the 896 the same card said to
 * sell at; and a negative change was printed after the word "Up".
 */
public class SellCardPaidTest
{
	private static final int MITHRIL_BAR = 2359;

	private static AdvisorPanel.Rec recFor(FavoritesPanel.Row row) throws Exception
	{
		final AdvisorPanel.Actions actions = (AdvisorPanel.Actions) Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(p, m, a) ->
			{
				final Class<?> t = m.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				return t.isPrimitive() ? (t == long.class ? (Object) 0L : (Object) 0) : null;
			});
		final AdvisorPanel panel = new AdvisorPanel(null, actions);
		final Method m = AdvisorPanel.class.getDeclaredMethod("recFor", FavoritesPanel.Row.class);
		m.setAccessible(true);
		return (AdvisorPanel.Rec) m.invoke(panel, row);
	}

	/** The Mithril bar stack exactly as it was held. */
	private static FavoritesPanel.Row mithril()
	{
		final FavoritesPanel.Row r = new FavoritesPanel.Row();
		r.id = MITHRIL_BAR;
		r.name = "Mithril bar";
		r.price = 889;
		r.targetSell = 896;
		final PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			MITHRIL_BAR, 639, quote(889, 900), new long[]{173, 173L * 876});
		r.heldQty = p.heldQty;
		r.sellValue = p.sellValue;
		r.hasCostBasis = p.hasCostBasis;
		r.pricedQty = p.pricedQty;
		r.pricedCost = p.costOfPriced;
		r.heldProfit = p.heldProfit;
		return r;
	}

	private static Advisor.Quote quote(long low, long high)
	{
		final Advisor.Quote q = new Advisor.Quote();
		q.low = low;
		q.high = high;
		return q;
	}

	@Test
	public void paidIsWhatTheTrackedUnitsCost() throws Exception
	{
		Assert.assertEquals(876, recFor(mithril()).unitCost);
	}

	/** At the card's own SELL @: 173 x (896 - 17 tax) - 173 x 876. */
	@Test
	public void theGainIsPricedAtTheCardsOwnSell() throws Exception
	{
		Assert.assertEquals(173L * (896 - 17) - 173L * 876, recFor(mithril()).profit);
	}

	@Test
	public void theUntrackedRestIsValuedAtTheSameSell() throws Exception
	{
		final AdvisorPanel.Rec rec = recFor(mithril());
		Assert.assertEquals(639 - 173, rec.untrackedQty);
		Assert.assertEquals((639L - 173) * (896 - 17), rec.untrackedValue);
	}

	/**
	 * The later screen: 3,738 bought this time, 639 still in the bank from
	 * before. The old formula loaded the bank bars' sale value onto the
	 * tracked ones and read PAID @ 1,025; it is what those 3,738 cost.
	 */
	@Test
	public void theBankBarsAreNotLoadedOntoTheTrackedOnes() throws Exception
	{
		final FavoritesPanel.Row r = new FavoritesPanel.Row();
		r.id = MITHRIL_BAR;
		r.name = "Mithril bar";
		r.price = 870;
		r.targetSell = 888;
		final PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			MITHRIL_BAR, 4_377, quote(870, 888), new long[]{3_738, 3_738L * 876});
		r.heldQty = p.heldQty;
		r.sellValue = p.sellValue;
		r.hasCostBasis = p.hasCostBasis;
		r.pricedQty = p.pricedQty;
		r.pricedCost = p.costOfPriced;
		r.heldProfit = p.heldProfit;
		final AdvisorPanel.Rec rec = recFor(r);
		Assert.assertEquals(876, rec.unitCost);
		Assert.assertEquals(639, rec.untrackedQty);
		Assert.assertEquals("-5 an item after tax, on the tracked 3,738",
			3_738L * (888 - 17) - 3_738L * 876, rec.profit);
	}

	private static final int AETHER_CATALYST = 30771;

	private static Advisor.OfferView offer(boolean buy, long price, int total, int sold)
	{
		final Advisor.OfferView o = new Advisor.OfferView();
		o.itemId = AETHER_CATALYST;
		o.itemName = "Aether catalyst";
		o.buy = buy;
		o.price = price;
		o.totalQuantity = total;
		o.quantitySold = sold;
		o.active = true;
		return o;
	}

	/** A row built the way the plugin builds it: offers first, then the
	 *  held position over bank + still-listed units. */
	private static FavoritesPanel.Row aether(int inBank, Advisor.OfferView... offers)
	{
		final FavoritesPanel.Row r = new FavoritesPanel.Row();
		r.id = AETHER_CATALYST;
		r.name = "Aether catalyst";
		r.price = 365;
		r.targetBuy = 353;
		r.targetSell = 371;
		r.limit = 25_000;
		PocketGeTrackerPlugin.fillOfferPosition(r, java.util.List.of(offers));
		final PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			AETHER_CATALYST, inBank + r.listedQty, quote(365, 372), new long[]{25_000, 8_975_000});
		r.heldQty = p.heldQty;
		r.sellValue = p.sellValue;
		r.hasCostBasis = p.hasCostBasis;
		r.pricedQty = p.pricedQty;
		r.pricedCost = p.costOfPriced;
		r.heldProfit = p.heldProfit;
		r.heldWhere = PocketGeTrackerPlugin.positionWhere(r.listedQty, inBank > 0 ? "from your bank" : null);
		return r;
	}

	/**
	 * "i have 25k of them in ge waiting to sell at 374 ... thats way more
	 * important than capped by the 4h buy limit". Bought at 359 (8,975,000
	 * for 25,000), listed at 374: the card is that position, priced at the
	 * listing — the same +200K the slot's own tooltip shows.
	 */
	@Test
	public void aStackListedForSaleIsShownAsYourPosition() throws Exception
	{
		final AdvisorPanel.Rec rec = recFor(aether(0, offer(false, 374, 25_000, 0)));
		Assert.assertTrue("a sell, not the buy pitch", rec.sell);
		Assert.assertEquals(25_000, rec.quantity);
		Assert.assertEquals("PAID @", 359, rec.unitCost);
		Assert.assertEquals("SELL @ is your listing", 374, rec.unitPrice);
		Assert.assertEquals(25_000L * (374 - 7) - 8_975_000L, rec.profit);
		Assert.assertEquals(200_000, rec.profit);
		Assert.assertEquals("listed in the Exchange", rec.heldWhere);
		Assert.assertEquals("Listed at 374 \u2014 0 of 25,000 sold", rec.listingNote);
	}

	/** Part sold, and more in the bank: both counted, and said. */
	@Test
	public void aPartSoldListingWithMoreInTheBank() throws Exception
	{
		final AdvisorPanel.Rec rec = recFor(aether(5_000, offer(false, 374, 20_000, 8_000)));
		Assert.assertEquals("12,000 still listed + 5,000 in the bank", 17_000, rec.quantity);
		Assert.assertEquals("listed in the Exchange, more in your bank", rec.heldWhere);
		Assert.assertEquals("Listed at 374 \u2014 8,000 of 20,000 sold", rec.listingNote);
	}

	/** Still buying it: the card says where that offer is. */
	@Test
	public void aBuyInProgressSaysWhereItIs() throws Exception
	{
		final AdvisorPanel.Rec rec = recFor(aether(0, offer(true, 359, 25_000, 12_000)));
		Assert.assertFalse(rec.sell);
		Assert.assertEquals("you're bidding 359 gp \u2014 12,000 of 25,000 bought", rec.note);
	}

	/**
	 * "if im in my bank and wanna know how much i could profit or lose on a
	 * stack, i may want to inspect it to see that trade rather than a new
	 * trade" — and the other way round. The card swaps; the item menu offers
	 * whichever view is not showing.
	 */
	@Test
	public void aHeldStackCanBeSwappedToTheTradeIdeaAndBack() throws Exception
	{
		final AdvisorPanel.Actions actions = (AdvisorPanel.Actions) Proxy.newProxyInstance(
			AdvisorPanel.Actions.class.getClassLoader(), new Class<?>[]{AdvisorPanel.Actions.class},
			(p, m, a) ->
			{
				final Class<?> t = m.getReturnType();
				if (t == boolean.class)
				{
					return false;
				}
				return t.isPrimitive() ? (t == long.class ? (Object) 0L : (Object) 0) : null;
			});
		final AdvisorPanel panel = new AdvisorPanel(null, actions);
		final FavoritesPanel.Row row = aether(25_000);
		final Method recFor = AdvisorPanel.class.getDeclaredMethod("recFor", FavoritesPanel.Row.class);
		recFor.setAccessible(true);

		javax.swing.SwingUtilities.invokeAndWait(() -> panel.setSelectedItem(row));
		Assert.assertTrue("held: the stack first", ((AdvisorPanel.Rec) recFor.invoke(panel, row)).sell);
		Assert.assertEquals("the item menu offers the trade idea", Boolean.TRUE, panel.inspectSwapTarget(AETHER_CATALYST));

		javax.swing.SwingUtilities.invokeAndWait(() -> panel.setInspectView(true));
		final AdvisorPanel.Rec idea = (AdvisorPanel.Rec) recFor.invoke(panel, row);
		Assert.assertFalse("swapped: a new trade", idea.sell);
		Assert.assertEquals(353, idea.unitPrice);
		Assert.assertEquals("and the menu offers the stack back", Boolean.FALSE, panel.inspectSwapTarget(AETHER_CATALYST));
		Assert.assertNull("no swap offered on another item", panel.inspectSwapTarget(MITHRIL_BAR));

		final FavoritesPanel.Row other = mithril();
		javax.swing.SwingUtilities.invokeAndWait(() -> panel.setSelectedItem(other));
		Assert.assertTrue("another item starts on its stack again", ((AdvisorPanel.Rec) recFor.invoke(panel, other)).sell);
	}

	/** The value the old formula leaned on is still there for the row's own
	 *  tooltip — this only changes what the CARD derives from it. */
	@Test
	public void theCostIsReportedAlongsideTheProfit()
	{
		final PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			MITHRIL_BAR, 639, quote(889, 900), new long[]{173, 173L * 876});
		Assert.assertEquals(173L * 876, p.costOfPriced);
		Assert.assertEquals(173, p.pricedQty);
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

/**
 * Every sell card the sidebar offers gets its price series fetched — not just
 * the first one.
 *
 * The plugin used to remember a single item id: whichever SELL Advisor.advise()
 * ranked top. But the sidebar does not show one sell, it shows the whole ranked
 * stack and lets you page through it — so card 1 was priced by TradeEngine and
 * cards 2..n were priced off the last insta-buy print, which is the
 * "quote the actively-traded price and call it a target" mistake the GE-context
 * path already had to be talked out of. Two cards in the same list, built by
 * two different methods, with nothing on either saying which one you got.
 *
 * Two things hold this closed. {@link #everySellCardOnTheBoardIsCovered} says
 * the selection is by rank and covers a board's worth rather than one item, and
 * {@link #aSeriesMovesTheAskOffTheRawPrint} says the coverage is worth having by
 * showing the two paths actually disagree.
 */
public class SellSeriesCoverageTest
{
	private static final long NOW = 1_700_000_000L;

	@Test
	public void everySellCardOnTheBoardIsCovered()
	{
		final List<AdvisorPanel.Rec> sells = new ArrayList<>();
		for (int i = 0; i < 20; i++)
		{
			final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
			r.sell = true;
			r.itemId = 1000 + i;
			sells.add(r);
		}

		final Set<Integer> ids = PocketGeTrackerPlugin.sellSeriesIds(sells);

		Assert.assertEquals("a board's worth, not one item",
			PocketGeTrackerPlugin.SELL_SERIES_CAP, ids.size());
		Assert.assertTrue("the top card is still in there", ids.contains(1000));
		Assert.assertTrue("and so is the one three pages down — this is the regression",
			ids.contains(1002));
		Assert.assertFalse("but not the twentieth: every id is an HTTP call per cycle",
			ids.contains(1019));
	}

	@Test
	public void aShortListIsCoveredWhole()
	{
		final List<AdvisorPanel.Rec> sells = new ArrayList<>();
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.sell = true;
		r.itemId = 1656;
		sells.add(r);

		Assert.assertEquals(new HashSet<>(java.util.Collections.singletonList(1656)),
			PocketGeTrackerPlugin.sellSeriesIds(sells));
	}

	@Test
	public void noSellsAsksForNothing()
	{
		Assert.assertTrue(PocketGeTrackerPlugin.sellSeriesIds(new ArrayList<>()).isEmpty());
	}

	/**
	 * The point of covering them: with a series the ask comes from the engine,
	 * without one it is the raw bid. If these ever coincide the test above is
	 * guarding nothing, so this asserts they differ.
	 */
	@Test
	public void aSeriesMovesTheAskOffTheRawPrint()
	{
		final Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		final Advisor.Quote q = new Advisor.Quote();
		/* The bid sits below the series' own range, so the engine's target
		   is not the raw print — without that this test would pass on a
		   plugin that had no engine at all. */
		q.high = 1990;
		q.low = 1900;
		q.highTime = NOW;
		q.lowTime = NOW;
		quotes.put(1601, q);

		final Map<Integer, Advisor.ItemMeta> meta = new HashMap<>();
		final Advisor.ItemMeta m = new Advisor.ItemMeta();
		m.id = 1601;
		m.name = "Diamond";
		m.limit = 10_000;
		m.dailyVolume = 500_000;
		meta.put(1601, m);

		final Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(1601, 1_000);

		final Advisor.Suggestion raw = Advisor.sellCandidates(NOW, quotes, meta, holdings,
			new ArrayList<>(), new HashSet<>(), new HashSet<>(), null, new HashMap<>()).get(0);
		Assert.assertEquals("uncovered: the last insta-buy print, verbatim", 1990, raw.price);

		final Map<Integer, TradeEngine.Series> seriesByItem = new HashMap<>();
		seriesByItem.put(1601, AdvisorTest.syntheticSeries(NOW, 200, 1900, 2000, 11));
		final Advisor.Suggestion priced = Advisor.sellCandidates(NOW, quotes, meta, holdings,
			new ArrayList<>(), new HashSet<>(), new HashSet<>(), null, seriesByItem).get(0);

		Assert.assertNotEquals("covered: the engine's own target, as the website shows it",
			raw.price, priced.price);
		Assert.assertEquals("the website's Target Sell, as it stands",
			TradeEngine.viewTargets(q.low, q.high, q.lowTime, q.highTime, seriesByItem.get(1601), 1601).sell,
			priced.price);
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * "website has a better sell price here ... id try to price at the website
 * price first for sure here not for 298": the sell card on screen fetches
 * its own price series, so it is priced as the website prices it wherever
 * it sits in the list.
 */
public class ShownSellSeriesTest
{
	private static final int ICE_SACK = 24607;
	private static final int OTHER = 4151;

	private PocketGeTrackerPlugin plugin;
	private boolean advisorOn = true;
	/** Executor work held until run(), as RuneLite's would hold it. */
	private final List<Runnable> queued = new ArrayList<>();
	private final List<Integer> fetched = new ArrayList<>();
	private int rebuilt;
	private final List<Integer> repriced = new ArrayList<>();

	private void set(String field, Object value) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private Object get(String field) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private void runQueued()
	{
		while (!queued.isEmpty())
		{
			queued.remove(0).run();
		}
	}

	private static TradeEngine.Series series()
	{
		final TradeEngine.Series s = new TradeEngine.Series();
		s.labels = new long[]{1_000, 1_300};
		s.low = new double[]{286, 288};
		s.high = new double[]{305, 310};
		s.lowVol = new double[]{10, 10};
		s.highVol = new double[]{10, 10};
		return s;
	}

	private boolean hasSeries(int itemId) throws Exception
	{
		final Method m = PocketGeTrackerPlugin.class.getDeclaredMethod("seriesFor", int.class);
		m.setAccessible(true);
		return m.invoke(plugin, itemId) != null;
	}

	@Before
	public void wire() throws Exception
	{
		plugin = new PocketGeTrackerPlugin();
		set("running", true);
		set("config", Proxy.newProxyInstance(PocketGeTrackerConfig.class.getClassLoader(),
			new Class<?>[]{PocketGeTrackerConfig.class}, (proxy, m, args) ->
			{
				if ("advisor".equals(m.getName()))
				{
					return advisorOn;
				}
				final Class<?> r = m.getReturnType();
				return r == boolean.class ? false : r.isPrimitive() ? 0 : null;
			}));
		set("executor", Proxy.newProxyInstance(ScheduledExecutorService.class.getClassLoader(),
			new Class<?>[]{ScheduledExecutorService.class}, (proxy, m, args) ->
			{
				if ("execute".equals(m.getName()))
				{
					queued.add((Runnable) args[0]);
				}
				final Class<?> r = m.getReturnType();
				return r == boolean.class ? false : r.isPrimitive() ? 0 : null;
			}));
		set("marketClient", new MarketClient(null, null)
		{
			@Override
			public TradeEngine.Series fetchTimeseries5m(int itemId)
			{
				fetched.add(itemId);
				return series();
			}
		});
		/* As recomputeAdvice does: the cards priced from everything in hand
		   as of now — a moment after, so a fetch in the same millisecond
		   reads as already in them. */
		plugin.rebuildCards = () ->
		{
			rebuilt++;
			try
			{
				set("cardsPricedAt", System.currentTimeMillis() + 1);
			}
			catch (Exception e)
			{
				throw new IllegalStateException(e);
			}
		};
		plugin.repriceOffer = repriced::add;
	}

	private void cache(int itemId) throws Exception
	{
		final Method m = PocketGeTrackerPlugin.class.getDeclaredMethod("cacheOnDemandSeries", int.class,
			TradeEngine.Series.class);
		m.setAccessible(true);
		m.invoke(plugin, itemId, series());
	}

	/** Card 20 of 20, no series: fetched as it is shown, and the cards
	 *  rebuilt from it — once. */
	@Test
	public void theSellCardOnScreenFetchesItsOwnSeries() throws Exception
	{
		Assert.assertFalse(hasSeries(ICE_SACK));
		plugin.noteShownCard(ICE_SACK, true);
		runQueued();
		Assert.assertEquals(List.of(ICE_SACK), fetched);
		Assert.assertTrue(hasSeries(ICE_SACK));
		Assert.assertEquals("the cards re-priced from it", 1, rebuilt);

		plugin.noteShownCard(OTHER, true);
		runQueued();
		plugin.noteShownCard(ICE_SACK, true);
		runQueued();
		Assert.assertEquals("back to it: already in hand, not asked again", List.of(ICE_SACK, OTHER), fetched);
		Assert.assertEquals(2, rebuilt);
	}

	/** A buy card is left to the advisor's own fetch: the engine can turn a
	 *  flip idea down and take its card away under you. */
	@Test
	public void notForABuyCard() throws Exception
	{
		plugin.noteShownCard(ICE_SACK, true);
		plugin.noteShownCard(OTHER, false);
		Assert.assertNull("a buy is not the sell on screen", get("shownSellItemId"));
		queued.clear();
		plugin.noteShownCard(OTHER, false);
		plugin.noteShownCard(null, false);
		runQueued();
		Assert.assertTrue(fetched.isEmpty());
		final Method m = PocketGeTrackerPlugin.class.getDeclaredMethod("refreshOfferSeries");
		m.setAccessible(true);
		m.invoke(plugin);
		Assert.assertTrue("nor kept current by the round", fetched.isEmpty());
	}

	/** Paged on before it landed: kept, and the cards, marks and hovers
	 *  rebuilt from it all the same — the stack's hover is priced from it
	 *  whether or not its card is the one up. */
	@Test
	public void pagedPastBeforeItLandsIsStillTakenUp() throws Exception
	{
		plugin.noteShownCard(ICE_SACK, true);
		plugin.noteShownCard(OTHER, false);
		runQueued();
		Assert.assertEquals(List.of(ICE_SACK), fetched);
		Assert.assertTrue(hasSeries(ICE_SACK));
		Assert.assertEquals(1, rebuilt);
	}

	@Test
	public void theAdvisorOffAsksNothing() throws Exception
	{
		advisorOn = false;
		plugin.noteShownCard(ICE_SACK, true);
		runQueued();
		Assert.assertTrue(fetched.isEmpty());
	}

	/** Failed or backing off: not asked again on every page back and forth —
	 *  the offer screen's attempt clock holds it for a minute. */
	@Test
	public void aFailedFetchIsNotRetriedAtOnce() throws Exception
	{
		set("marketClient", new MarketClient(null, null)
		{
			@Override
			public TradeEngine.Series fetchTimeseries5m(int itemId) throws java.io.IOException
			{
				fetched.add(itemId);
				throw new java.io.IOException("Wiki said no");
			}
		});
		plugin.noteShownCard(ICE_SACK, true);
		runQueued();
		plugin.noteShownCard(OTHER, false);
		plugin.noteShownCard(ICE_SACK, true);
		runQueued();
		Assert.assertEquals(List.of(ICE_SACK), fetched);
		Assert.assertEquals(0, rebuilt);
	}

	/** A series newer than the cards — one that came in some way that did
	 *  not rebuild them — is taken up when its card is shown, without
	 *  asking twice; and once they have it, showing it again rebuilds
	 *  nothing. */
	@Test
	public void aSeriesNewerThanTheCardsIsUsedWhenShown() throws Exception
	{
		plugin.rebuildCards.run(); // the cards as built before any of this
		rebuilt = 0;
		Thread.sleep(3);
		selectedSeriesAt(ICE_SACK); // in the cache, the cards not rebuilt
		Assert.assertEquals(0, rebuilt);
		plugin.noteShownCard(ICE_SACK, true);
		runQueued();
		Assert.assertTrue("not fetched", fetched.isEmpty());
		Assert.assertEquals("but the cards rebuilt from it", 1, rebuilt);
		plugin.noteShownCard(OTHER, false);
		plugin.noteShownCard(ICE_SACK, true);
		Assert.assertEquals("once: the cards have it now", 1, rebuilt);
	}

	/** A series put straight into the cache, as one restored or carried
	 *  over might be, without the landing that rebuilds the cards. */
	private void selectedSeriesAt(int itemId) throws Exception
	{
		@SuppressWarnings("unchecked")
		final Map<Integer, TradeEngine.Series> held = (Map<Integer, TradeEngine.Series>) get("selectedSeries");
		final Map<Integer, TradeEngine.Series> m = new java.util.HashMap<>(held);
		m.put(itemId, series());
		set("selectedSeries", m);
		@SuppressWarnings("unchecked")
		final Map<Integer, Long> at = (Map<Integer, Long>) get("selectedSeriesFetchedAt");
		at.put(itemId, System.currentTimeMillis());
	}

	/** Opened on the offer screen, or inspected, first — the cards, marks
	 *  and hovers are rebuilt as that series lands, and paging to the card
	 *  afterwards needs no more. The Astral rune hover said 114 under an
	 *  inspect card at 126 because only the shown sell card was rebuilt. */
	@Test
	public void aSeriesFetchedForAnythingRebuildsTheCards() throws Exception
	{
		plugin.rebuildCards.run();
		rebuilt = 0;
		Thread.sleep(3);
		cache(ICE_SACK);
		Assert.assertEquals("as it lands", 1, rebuilt);
		plugin.noteShownCard(ICE_SACK, true);
		runQueued();
		Assert.assertTrue(fetched.isEmpty());
		Assert.assertEquals("and not again for the card", 1, rebuilt);
	}

	/** Paging through a whole list of sells with no series: every card it
	 *  priced keeps its price, and the watchlist item being inspected keeps
	 *  its series. The cache used to start again at eight. */
	@Test
	public void pagingThroughTwentySellsKeepsEveryOnesSeries() throws Exception
	{
		set("selectedFavoriteItemId", 999);
		cache(999);
		for (int id = 1; id <= 20; id++)
		{
			plugin.noteShownCard(id, true);
			runQueued();
		}
		for (int id = 1; id <= 20; id++)
		{
			Assert.assertTrue("card " + id, hasSeries(id));
		}
		Assert.assertTrue("the inspected item", hasSeries(999));
		Assert.assertEquals(20, fetched.size());
	}

	/** Past the cap the oldest go — never what is on screen now. */
	@Test
	public void pastTheCapTheOldestGoNotWhatIsOnScreen() throws Exception
	{
		set("selectedFavoriteItemId", 999);
		set("geContextItemId", 998);
		cache(999);
		Thread.sleep(2);
		cache(998);
		Thread.sleep(2);
		set("shownSellItemId", 997);
		set("shownCardItemId", 997);
		cache(997);
		/* Fetched in the opposite order to the ids, so the oldest is not
		   whichever the map happens to list first. */
		for (int id = 40; id >= 1; id--)
		{
			Thread.sleep(1);
			cache(id);
		}
		Assert.assertTrue(hasSeries(999));
		Assert.assertTrue(hasSeries(998));
		Assert.assertTrue(hasSeries(997));
		for (int id = 1; id <= 21; id++)
		{
			Assert.assertTrue("among the newest: " + id, hasSeries(id));
		}
		Assert.assertFalse("the oldest", hasSeries(40));
		@SuppressWarnings("unchecked")
		final Map<Integer, TradeEngine.Series> held = (Map<Integer, TradeEngine.Series>) get("selectedSeries");
		Assert.assertTrue("bounded", held.size() <= 24);
	}

	/** The card's fetch holds the offer screen's own off for a minute, so
	 *  when it lands it re-prices an offer screen open for the item — the
	 *  screen a sell card leads to. And the chart's fetch still does. */
	@Test
	public void aCardsFetchRepricesTheOfferScreenItLeadsTo() throws Exception
	{
		plugin.noteShownCard(ICE_SACK, true);
		plugin.noteShownCard(null, false); // the offer screen takes the box
		runQueued();
		Assert.assertEquals(List.of(ICE_SACK), repriced);

		final Method m = PocketGeTrackerPlugin.class.getDeclaredMethod("requestSharedSeries", int.class);
		m.setAccessible(true);
		m.invoke(plugin, OTHER);
		runQueued();
		Assert.assertEquals(List.of(ICE_SACK, OTHER), repriced);
	}

	/** Already on screen when another caller's fetch brings its series —
	 *  the offer screen's, the chart's, a watchlist click's, or one that
	 *  held the attempt clock so the card's own was refused: taken up as it
	 *  lands. */
	@Test
	public void aCardAlreadyUpTakesUpASeriesAnotherCallerFetched() throws Exception
	{
		final Method req = PocketGeTrackerPlugin.class.getDeclaredMethod("requestSharedSeries", int.class);
		req.setAccessible(true);
		req.invoke(plugin, ICE_SACK); // the offer screen's chart, say
		plugin.noteShownCard(ICE_SACK, true); // refused: the clock is held
		Assert.assertEquals("one fetch queued, not two", 1, queued.size());
		runQueued();
		Assert.assertEquals(List.of(ICE_SACK), fetched);
		Assert.assertEquals("rebuilt as it landed", 1, rebuilt);

		cache(OTHER); // a watchlist click's: its hover is rebuilt from it too
		Assert.assertEquals(2, rebuilt);
	}

	/** A sell paged past long ago is not priced from its old series: an old
	 *  day's range would set its ask. Back on the live print until shown
	 *  again. */
	@Test
	public void anOldSeriesNoLongerPricesTheCards()
	{
		final long now = 10_000_000L;
		final Map<Integer, TradeEngine.Series> held = new java.util.HashMap<>();
		final Map<Integer, Long> at = new java.util.HashMap<>();
		held.put(1, series());
		at.put(1, now - PocketGeTrackerPlugin.ON_DEMAND_SERIES_MAX_AGE_MS);
		held.put(2, series());
		at.put(2, now - PocketGeTrackerPlugin.ON_DEMAND_SERIES_MAX_AGE_MS - 1);
		held.put(3, series()); // no time on record
		Assert.assertEquals(java.util.Set.of(1), PocketGeTrackerPlugin.recentSeries(held, at, now, List.of()).keySet());
	}

	/** But the card still on screen keeps its series, however long it has
	 *  been up — it is not "shown again" to ask afresh. Nor the open offer
	 *  or the inspected item. */
	@Test
	public void whatIsOnScreenKeepsItsSeriesPastTheBound()
	{
		final long now = 10_000_000L;
		final Map<Integer, TradeEngine.Series> held = new java.util.HashMap<>();
		final Map<Integer, Long> at = new java.util.HashMap<>();
		for (int id = 1; id <= 3; id++)
		{
			held.put(id, series());
			at.put(id, now - 60 * 60 * 1000L);
		}
		Assert.assertEquals(java.util.Set.of(1, 3),
			PocketGeTrackerPlugin.recentSeries(held, at, now, List.of(1, 3)).keySet());
	}

	/** And it is what the cards are built from. Read from the source:
	 *  recomputeAdvice needs a whole running client. */
	@Test
	public void theCardsAreBuiltFromTheRecentOnesOnly() throws Exception
	{
		final String src = java.nio.file.Files.readString(
			java.nio.file.Path.of("src/main/java/com/pocketge/tracker/PocketGeTrackerPlugin.java"))
			.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
		Assert.assertTrue("the cards", src.contains("cycleSeries = pricingSeries(cardsPricedAt);"));
		Assert.assertTrue("kept as the cards' snapshot", src.contains("cardsSeries = cycleSeries;"));
		Assert.assertTrue("the rows, the header and the portfolio total read that same snapshot",
			src.contains("pricing = cardsSeries;"));
		Assert.assertFalse("not one of their own", src.contains("pricingSeries(System.currentTimeMillis())"));
		final int inspect = src.indexOf("public void onSelectedItemChanged(Integer itemId)");
		Assert.assertTrue(inspect > 0);
		Assert.assertTrue("an inspected item with an old series asks afresh",
			src.substring(inspect, inspect + 700).contains("!wantsSeries(itemId)"));
		final int at = src.indexOf("private Map<Integer, TradeEngine.Series> pricingSeries(long now)");
		Assert.assertTrue(at > 0);
		final String body = src.substring(at, src.indexOf("\n\t}\n", at));
		Assert.assertTrue(body.contains("recentSeries(selectedSeries, selectedSeriesFetchedAt, now, onScreen)"));
		for (String id : new String[]{"shownCardItemId", "geContextItemId", "selectedFavoriteItemId", "lastActiveOfferItemIds"})
		{
			Assert.assertTrue("on screen: " + id, body.contains(id));
		}
	}

	/** One map for the cards and the rows: the advisor round's copy unless
	 *  an on-demand one is newer and still usable, never a stale on-demand
	 *  one over nothing. */
	@Test
	public void theRowsAndTheCardsReadOneMap() throws Exception
	{
		final Method pricing = PocketGeTrackerPlugin.class.getDeclaredMethod("pricingSeries", long.class);
		pricing.setAccessible(true);
		final long now = System.currentTimeMillis();
		@SuppressWarnings("unchecked")
		final Map<Integer, TradeEngine.Series> picked = (Map<Integer, TradeEngine.Series>) get("selectedSeries");
		@SuppressWarnings("unchecked")
		final Map<Integer, Long> pickedAt = (Map<Integer, Long>) get("selectedSeriesFetchedAt");
		@SuppressWarnings("unchecked")
		final Map<Integer, Long> roundAt = (Map<Integer, Long>) get("offerSeriesFetchedAt");
		final TradeEngine.Series round = series(), fresh = series(), old = series();
		final Map<Integer, TradeEngine.Series> sel = new java.util.HashMap<>(picked);
		sel.put(1, fresh);
		sel.put(2, old);
		sel.put(3, old);
		set("selectedSeries", sel);
		pickedAt.put(1, now - 60_000);
		pickedAt.put(2, now - PocketGeTrackerPlugin.ON_DEMAND_SERIES_MAX_AGE_MS - 60_000);
		pickedAt.put(3, now - PocketGeTrackerPlugin.ON_DEMAND_SERIES_MAX_AGE_MS - 60_000);
		final Map<Integer, TradeEngine.Series> rounds = new java.util.HashMap<>();
		rounds.put(1, round);
		rounds.put(2, round);
		set("lastOfferSeries", rounds);
		roundAt.put(1, now - 120_000);
		roundAt.put(2, now - 120_000);
		@SuppressWarnings("unchecked")
		final Map<Integer, TradeEngine.Series> map = (Map<Integer, TradeEngine.Series>) pricing.invoke(plugin, now);
		Assert.assertSame("the newer, still usable", fresh, map.get(1));
		Assert.assertSame("not a stale one over the round's", round, map.get(2));
		Assert.assertNull("nor a stale one alone", map.get(3));
	}

	/** Kept current by the advisor's own round while the card stays up. */
	@Test
	public void theAdvisorsRoundKeepsItCurrent() throws Exception
	{
		set("shownSellItemId", ICE_SACK);
		final Method m = PocketGeTrackerPlugin.class.getDeclaredMethod("refreshOfferSeries");
		m.setAccessible(true);
		m.invoke(plugin);
		Assert.assertEquals(List.of(ICE_SACK), fetched);
		@SuppressWarnings("unchecked")
		final Map<Integer, TradeEngine.Series> offerSeries = (Map<Integer, TradeEngine.Series>) get("lastOfferSeries");
		Assert.assertTrue(offerSeries.containsKey(ICE_SACK));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * A disabled plugin sends nothing.
 *
 * The executor every background task runs on is RuneLite's, shared by the
 * whole client, and it is not shut down when a plugin is. 0.7.1's price
 * retry rescheduled itself while the Wiki was unreachable, so a plugin
 * disabled during an outage kept asking for prices — once a minute offline,
 * every half hour against a Wiki that was refusing it — for as long as the
 * client stayed open.
 */
public class ShutdownQuietTest
{
	private PocketGeTrackerPlugin plugin;
	private final AtomicInteger scheduled = new AtomicInteger();

	private void set(String field, Object value) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private void retry() throws Exception
	{
		final Method m = PocketGeTrackerPlugin.class.getDeclaredMethod("scheduleBulkRetry");
		m.setAccessible(true);
		m.invoke(plugin);
	}

	@Before
	public void wire() throws Exception
	{
		plugin = new PocketGeTrackerPlugin();
		set("marketClient", new MarketClient(null, null));
		set("executor", Proxy.newProxyInstance(
			ScheduledExecutorService.class.getClassLoader(),
			new Class<?>[]{ScheduledExecutorService.class},
			(proxy, method, args) ->
			{
				if ("schedule".equals(method.getName()))
				{
					scheduled.incrementAndGet();
				}
				final Class<?> r = method.getReturnType();
				if (r == boolean.class)
				{
					return false;
				}
				return r.isPrimitive() ? 0 : null;
			}));
	}

	@Test
	public void aStoppedPluginSchedulesNoRetry() throws Exception
	{
		set("running", false);
		retry();
		Assert.assertEquals(0, scheduled.get());
	}

	@Test
	public void aRunningPluginSchedulesOneRetryAtATime() throws Exception
	{
		set("running", true);
		retry();
		retry();
		Assert.assertEquals("one pending retry, not a chain per caller", 1, scheduled.get());
	}

	/** shutDown has to flip the switch before anything else, so a task the
	 *  executor is about to run sees it. Read from the source: shutDown
	 *  needs a whole running client. */
	@Test
	public void shutDownStopsTheNetworkFirst() throws Exception
	{
		final String src = Files.readString(Path.of("src/main/java/com/pocketge/tracker/PocketGeTrackerPlugin.java"))
			.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
		final int at = src.indexOf("protected void shutDown()");
		Assert.assertTrue(at > 0);
		final String body = src.substring(src.indexOf('{', at) + 1).trim();
		Assert.assertTrue(body.substring(0, 40), body.startsWith("running = false;"));
		Assert.assertTrue("and cancels the pending retry",
			body.substring(0, 400).contains("retry.cancel(false)"));
	}
}

package com.pocketge.tracker;

import java.awt.Component;
