import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Assert;
import org.junit.Test;

/**
 * "thoughts on adding little green +$200gp or whatever profits / lossses as
 * well on these on side bar any time you dont have the grand exchange window
 * open so it doesnt double repeat".
 */
public class SidebarPopsTest
{
	private static final int DART = 811;
	private static final long T = 1_000_000L;

	@Test
	public void theSquaresFigureIsShort()
	{
		Assert.assertEquals("+200", ProfitPops.shortText(200));
		Assert.assertEquals("+2K", ProfitPops.shortText(2_000));
		Assert.assertEquals("+1.2K", ProfitPops.shortText(1_250));
		Assert.assertEquals("+64K", ProfitPops.shortText(64_000));
		Assert.assertEquals("+999K", ProfitPops.shortText(999_999));
		Assert.assertEquals("-1.1M", ProfitPops.shortText(-1_120_000));
		Assert.assertEquals("+0", ProfitPops.shortText(0));
		Assert.assertTrue(ProfitPops.shortText(Long.MIN_VALUE).startsWith("-"));
	}

	/* ── The square ─────────────────────────────────────────────────── */

	private static List<JComponent> cells(Container root)
	{
		final List<JComponent> out = new ArrayList<>();
		for (Component c : root.getComponents())
		{
			if (c.getClass().getSimpleName().equals("Cell"))
			{
				out.add((JComponent) c);
			}
			else if (c instanceof Container)
			{
				out.addAll(cells((Container) c));
			}
		}
		return out;
	}

	private static int green(JComponent cell)
	{
		cell.setSize(49, 40);
		final BufferedImage img = new BufferedImage(49, 40, BufferedImage.TYPE_INT_ARGB);
		final Graphics g = img.createGraphics();
		cell.paint(g);
		g.dispose();
		int n = 0;
		for (int y = 0; y < img.getHeight(); y++)
		{
			for (int x = 0; x < img.getWidth(); x++)
			{
				final int rgb = img.getRGB(x, y);
				if ((rgb >>> 24) > 200 && Math.abs(((rgb >> 16) & 0xFF) - ProfitPops.GAIN.getRed()) < 12
					&& Math.abs(((rgb >> 8) & 0xFF) - ProfitPops.GAIN.getGreen()) < 12
					&& Math.abs((rgb & 0xFF) - ProfitPops.GAIN.getBlue()) < 12)
				{
					n++;
				}
			}
		}
		return n;
	}

	@Test
	public void itRisesOffItsOwnSquareAndGoes()
	{
		final GeSlotsPanel p = new GeSlotsPanel(null, null);
		final long[] now = {T};
		p.clock = () -> now[0];
		p.update(new GeSlotsPanel.SlotInfo[8]);
		final List<JComponent> cells = cells(p);
		Assert.assertEquals(8, cells.size());
		Assert.assertEquals(0, green(cells.get(2)));

		p.pop(2, 2_000);
		Assert.assertTrue("+2K on the square", green(cells.get(2)) > 0);
		Assert.assertEquals("and only there", 0, green(cells.get(3)));
		now[0] += ProfitPops.LIFE_MS;
		Assert.assertEquals("gone after its time", 0, green(cells.get(2)));
	}

	/** Coins from a sale with no buy on record rise in gold. */
	@Test
	public void coinsRiseInGold()
	{
		final GeSlotsPanel p = new GeSlotsPanel(null, null);
		p.clock = () -> T;
		p.update(new GeSlotsPanel.SlotInfo[8]);
		p.pop(2, 24_100, true);
		final JComponent cell = cells(p).get(2);
		cell.setSize(49, 40);
		final BufferedImage img = new BufferedImage(49, 40, BufferedImage.TYPE_INT_ARGB);
		final Graphics g = img.createGraphics();
		cell.paint(g);
		g.dispose();
		Assert.assertTrue(CoinPopsTest.count(img, ProfitPops.COINS) > 0);
		Assert.assertEquals(0, green(cell));

		/* "24K", unsigned: the same gold pixels as drawing exactly that. */
		final BufferedImage want = new BufferedImage(49, 40, BufferedImage.TYPE_INT_ARGB);
		final java.awt.Graphics2D w = want.createGraphics();
		ProfitPops.draw(w, new java.awt.Rectangle(0, 0, 49, 40), new ProfitPops.Pop(2, T, 24_100, true), T,
			net.runelite.client.ui.FontManager.getRunescapeBoldFont(), "24K");
		w.dispose();
		for (int y = 0; y < 40; y++)
		{
			for (int x = 0; x < 49; x++)
			{
				Assert.assertEquals("gold at " + x + "," + y, gold(want.getRGB(x, y)), gold(img.getRGB(x, y)));
			}
		}
	}

	private static boolean gold(int rgb)
	{
		final java.awt.Color c = ProfitPops.COINS;
		return (rgb >>> 24) > 200 && Math.abs(((rgb >> 16) & 0xFF) - c.getRed()) < 12
			&& Math.abs(((rgb >> 8) & 0xFF) - c.getGreen()) < 12 && Math.abs((rgb & 0xFF) - c.getBlue()) < 12;
	}

	/** Switched off: the figure on the square goes with it. */
	@Test
	public void clearTakesItOff()
	{
		final GeSlotsPanel p = new GeSlotsPanel(null, null);
		p.clock = () -> T;
		p.update(new GeSlotsPanel.SlotInfo[8]);
		p.pop(2, 2_000);
		p.clearPops();
		Assert.assertEquals(0, green(cells(p).get(2)));
	}

	/**
	 * What counts as seen. A figure played on the sidebar is used up, so the
	 * squares have to be really in front of you: not scrolled away, not in a
	 * minimised client or one behind another window, not folded.
	 */
	@Test
	public void onlyWhatIsReallyInViewCountsAsSeen()
	{
		Assert.assertTrue(GeSlotsPanel.squaresSeen(true, true, true, false, 80, 80));
		Assert.assertTrue("half in view is enough", GeSlotsPanel.squaresSeen(true, true, true, false, 40, 80));
		Assert.assertFalse("scrolled mostly away", GeSlotsPanel.squaresSeen(true, true, true, false, 39, 80));
		Assert.assertFalse("scrolled right away", GeSlotsPanel.squaresSeen(true, true, true, false, 0, 80));
		Assert.assertFalse("folded", GeSlotsPanel.squaresSeen(false, true, true, false, 80, 80));
		Assert.assertFalse("another tab", GeSlotsPanel.squaresSeen(true, false, true, false, 80, 80));
		Assert.assertFalse("another window in front", GeSlotsPanel.squaresSeen(true, true, false, false, 80, 80));
		Assert.assertFalse("minimised", GeSlotsPanel.squaresSeen(true, true, true, true, 80, 80));
		Assert.assertFalse("not laid out", GeSlotsPanel.squaresSeen(true, true, true, false, 0, 0));
	}

	/** Out of the box, before anything has shown it, the squares are not
	 *  counted as seen. */
	@Test
	public void aPanelNeverShownIsNotSeen()
	{
		Assert.assertFalse(new GeSlotsPanel(null, null).squaresShowing());
	}

	/* ── Which place plays it ──────────────────────────────────────── */

	private boolean geOpen;
	/** The Exchange open on an offer's own screen: squares loaded, hidden. */
	private boolean offerScreen;
	private boolean popsOn = true;
	private PocketGeTrackerPlugin plugin;
	private FlipTracker tracker;
	private MainPanel panel;

	private void setUp() throws Exception
	{
		final Widget square = (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(),
			new Class<?>[]{Widget.class}, (proxy, m, args) -> defaults(m.getReturnType()));
		final Widget hiddenSquare = (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(),
			new Class<?>[]{Widget.class}, (proxy, m, args) ->
				"isHidden".equals(m.getName()) ? true : defaults(m.getReturnType()));
		final GrandExchangeOffer offer = (GrandExchangeOffer) Proxy.newProxyInstance(
			GrandExchangeOffer.class.getClassLoader(), new Class<?>[]{GrandExchangeOffer.class},
			(proxy, m, args) -> "getItemId".equals(m.getName()) ? DART
				: "getState".equals(m.getName()) ? GrandExchangeOfferState.SOLD : defaults(m.getReturnType()));
		final Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, m, args) ->
			{
				switch (m.getName())
				{
					case "getAccountHash":
						return 1111L;
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getTickCount":
						return 100;
					case "getWidget":
						if (args.length != 1 || (Integer) args[0] != InterfaceID.GeOffers.INDEX_2)
						{
							return null;
						}
						return geOpen ? square : offerScreen ? hiddenSquare : null;
					case "getGrandExchangeOffers":
					{
						final GrandExchangeOffer[] all = new GrandExchangeOffer[8];
						all[2] = offer;
						return all;
					}
					default:
						return defaults(m.getReturnType());
				}
			});
		final PocketGeTrackerConfig config = (PocketGeTrackerConfig) Proxy.newProxyInstance(
			PocketGeTrackerConfig.class.getClassLoader(), new Class<?>[]{PocketGeTrackerConfig.class},
			(proxy, m, args) -> "profitPops".equals(m.getName()) ? popsOn : defaults(m.getReturnType()));
		final MainPanel.Actions actions = (MainPanel.Actions) Proxy.newProxyInstance(
			MainPanel.Actions.class.getClassLoader(), new Class<?>[]{MainPanel.Actions.class},
			(proxy, m, args) -> defaults(m.getReturnType()));
		panel = new MainPanel(null, actions);
		plugin = new PocketGeTrackerPlugin();
		set(plugin, PocketGeTrackerPlugin.class, "client", client);
		set(plugin, PocketGeTrackerPlugin.class, "config", config);
		set(plugin, PocketGeTrackerPlugin.class, "geSettledTick", 10);
		set(plugin, PocketGeTrackerPlugin.class, "mainPanel", panel);
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField("tracker");
		f.setAccessible(true);
		tracker = (FlipTracker) f.get(plugin);
		tracker.setAccountHash(1111L);
		tracker.onOffer(1_000, 0, DART, "Rune dart", true, 0, 0, 190, 7_132, false);
		tracker.onOffer(2_000, 0, DART, "Rune dart", true, 7_132, 7_132L * 190, 190, 7_132, false);
		tracker.onOffer(3_000, 0, 0, "", false, 0, 0, 0, 0, true);
		tracker.onOffer(4_000, 2, DART, "Rune dart", false, 0, 0, 200, 7_132, false);
		tracker.onOffer(5_000, 2, DART, "Rune dart", false, 7_132, 7_132L * 200, 200, 7_132, false);
	}

	private static void set(Object target, Class<?> cls, String field, Object value) throws Exception
	{
		final Field f = cls.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static Object defaults(Class<?> t)
	{
		if (t == boolean.class)
		{
			return false;
		}
		if (t == int.class)
		{
			return 0;
		}
		if (t == long.class)
		{
			return 0L;
		}
		return null;
	}

	/** The sidebar's squares, as if the PocketGE tab were open. */
	private GeSlotsPanel squares(boolean showing) throws Exception
	{
		final Field fav = MainPanel.class.getDeclaredField("favoritesPanel");
		fav.setAccessible(true);
		final Field slots = FavoritesPanel.class.getDeclaredField("geSlots");
		slots.setAccessible(true);
		final GeSlotsPanel g = (GeSlotsPanel) slots.get(fav.get(panel));
		set(g, GeSlotsPanel.class, "squaresShowing", showing);
		return g;
	}

	private int running(GeSlotsPanel g) throws Exception
	{
		SwingUtilities.invokeAndWait(() -> { });
		final Field f = GeSlotsPanel.class.getDeclaredField("pops");
		f.setAccessible(true);
		return ((ProfitPops) f.get(g)).running(System.currentTimeMillis(), s -> true).size();
	}

	private void tick() throws Exception
	{
		final Method m = PocketGeTrackerPlugin.class.getDeclaredMethod("popInSidebar");
		m.setAccessible(true);
		m.invoke(plugin);
	}

	@Test
	public void theExchangeShutTheSidebarPlaysItOnce() throws Exception
	{
		setUp();
		final GeSlotsPanel g = squares(true);
		tick();
		Assert.assertEquals("+42.7K on the sidebar square", 1, running(g));
		Assert.assertNull("and shown, so the Exchange will not play it again", plugin.unseenSale(2));
	}

	@Test
	public void theExchangeOpenItIsLeftToTheExchange() throws Exception
	{
		setUp();
		final GeSlotsPanel g = squares(true);
		geOpen = true;
		tick();
		Assert.assertEquals(0, running(g));
		Assert.assertNotNull("still waiting for the Exchange's own square", plugin.unseenSale(2));
	}

	/** The Exchange open on an offer's own screen: its squares are hidden,
	 *  but it is open — the figure waits for the slot screen, not the
	 *  sidebar: "any time you dont have the grand exchange window open". */
	@Test
	public void theExchangeOnAnOffersScreenStillCountsAsOpen() throws Exception
	{
		setUp();
		final GeSlotsPanel g = squares(true);
		offerScreen = true;
		tick();
		Assert.assertEquals(0, running(g));
		Assert.assertNotNull(plugin.unseenSale(2));
	}

	@Test
	public void neitherOnScreenItWaits() throws Exception
	{
		setUp();
		final GeSlotsPanel g = squares(false);
		tick();
		Assert.assertEquals(0, running(g));
		Assert.assertNotNull(plugin.unseenSale(2));
	}

	@Test
	public void switchedOffNothing() throws Exception
	{
		setUp();
		final GeSlotsPanel g = squares(true);
		popsOn = false;
		tick();
		Assert.assertEquals(0, running(g));
	}
}

package com.pocketge.tracker;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.image.BufferedImage;
import org.junit.After;
import org.junit.Assert;
import org.junit.Test;

/**
 * What the eight sidebar squares say, and in which colours.
 *
 * A box only when the slot needs you, and the bar in the side's colour:
 * "i dont like the white boxes honestly ... boxes only appear for change?
 * the yellow box conflicts meaning with the theme". A grey box went round
 * every busy slot, and the yellow reprice box went round sells too, in a
 * theme whose yellow means buy.
 *
 * The sidebar and the in-game box agree about the same slot — including a
 * slot you are pricing yourself, which once muted one and not the other.
 */
public class SlotAccentTest
{
	private static GeSlotsPanel.SlotInfo slot(GeSlotsPanel.SlotState state, boolean buy, boolean skipped)
	{
		final GeSlotsPanel.SlotInfo s = new GeSlotsPanel.SlotInfo();
		s.state = state;
		s.buy = buy;
		s.adviceSkipped = skipped;
		return s;
	}

	@After
	public void backToTheDefault()
	{
		final PocketGeTrackerConfig.ColourTheme t = PocketGeTrackerConfig.ColourTheme.CONTRAST;
		GeSlotsPanel.setTheme(t.buy(), t.sell());
	}

	/** Working, empty, or no offer at all: no box. The square is its
	 *  picture and its bar. */
	@Test
	public void aWorkingSlotHasNoBox()
	{
		Assert.assertNull(GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.ACTIVE_OK, true, false)));
		Assert.assertNull(GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.ACTIVE_OK, false, false)));
		Assert.assertNull(GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.EMPTY, false, false)));
		Assert.assertNull(GeSlotsPanel.box(null));
	}

	/**
	 * A slot wanting a new price is boxed in white, the plugin's "act here",
	 * buy or sell and whatever the theme. In the buy colour it put the old
	 * yellow back round every buy in the default theme: "this yellow i think
	 * should be an ew color ... or white to match our theme actualy for
	 * directing the user". Losing at a bid is a reprice too.
	 */
	@Test
	public void aRepriceIsBoxedInWhiteWhateverTheTheme()
	{
		for (PocketGeTrackerConfig.ColourTheme t : PocketGeTrackerConfig.ColourTheme.values())
		{
			GeSlotsPanel.setTheme(t.buy(), t.sell());
			Assert.assertEquals(GeSlotsPanel.REPRICE_COLOR, GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.ACTIVE_ADJUST, true, false)));
			Assert.assertEquals(GeSlotsPanel.REPRICE_COLOR, GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, false)));
			Assert.assertEquals(GeSlotsPanel.REPRICE_COLOR, GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.ACTIVE_LOSING, true, false)));
		}
		Assert.assertEquals("one white, for act here", BankHighlightOverlay.RECOMMENDED_COLOR, GeSlotsPanel.REPRICE_COLOR);
	}

	/** The bar is the side's colour whatever the state. */
	@Test
	public void theBarIsTheSidesColour()
	{
		for (PocketGeTrackerConfig.ColourTheme t : PocketGeTrackerConfig.ColourTheme.values())
		{
			GeSlotsPanel.setTheme(t.buy(), t.sell());
			Assert.assertEquals(t + " buy", t.buy(), GeSlotsPanel.sideColour(true));
			Assert.assertEquals(t + " sell", t.sell(), GeSlotsPanel.sideColour(false));
		}
	}

	/** A slot you are pricing yourself is never boxed for a new price: the
	 *  plugin has nothing to say about it. */
	@Test
	public void aSlotYouArePricingYourselfHasNoBox()
	{
		Assert.assertNull(GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.ACTIVE_OK, true, true)));
		Assert.assertNull(GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, true)));
		Assert.assertNull(GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.ACTIVE_LOSING, true, true)));
	}

	/**
	 * But a collectable one always is. The flag outlives the offer it was
	 * set on, and hiding a slot that is ready to collect would hide the one
	 * state that actually wants a click.
	 */
	@Test
	public void aCollectableSlotIsAlwaysBoxedGreen()
	{
		Assert.assertEquals(GeSlotsPanel.COLLECT_COLOR,
			GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.READY_COLLECT, false, true)));
		Assert.assertEquals(GeSlotsPanel.COLLECT_COLOR,
			GeSlotsPanel.box(slot(GeSlotsPanel.SlotState.READY_COLLECT, true, false)));
		Assert.assertEquals(TipStyle.GOOD, GeSlotsPanel.COLLECT_COLOR);
	}

	/**
	 * Done is the game's green, and no theme's buy or sell colour is
	 * anywhere near it — so a green box can only mean one thing, whichever
	 * theme is on. Measured as a hue gap rather than equality: a theme green
	 * two shades off would mislead just as well. The nearest today is
	 * Terminal's teal sell, 37 degrees round from it with far more blue in
	 * it — and a done slot's bar is full besides.
	 */
	@Test
	public void noThemeColourIsTheDoneGreen()
	{
		final float green = hue(GeSlotsPanel.COLLECT_COLOR);
		for (PocketGeTrackerConfig.ColourTheme t : PocketGeTrackerConfig.ColourTheme.values())
		{
			for (Color c : new Color[]{t.buy(), t.sell()})
			{
				final float[] hsb = Color.RGBtoHSB(c.getRed(), c.getGreen(), c.getBlue(), null);
				final float gap = Math.min(Math.abs(hsb[0] - green), 1 - Math.abs(hsb[0] - green));
				Assert.assertTrue(t + " " + c + " reads as the done green",
					hsb[1] < 0.25f || gap > 0.08f);
			}
		}
	}

	private static float hue(Color c)
	{
		return Color.RGBtoHSB(c.getRed(), c.getGreen(), c.getBlue(), null)[0];
	}

	/**
	 * The painted square, not just the colour picked for it: a working sell
	 * shows no box colour on its edge and a sell-coloured bar; the same
	 * slot wanting a new price has the sell colour on its edge.
	 */
	@Test
	public void theSquareIsPaintedThatWay() throws Exception
	{
		final PocketGeTrackerConfig.ColourTheme t = PocketGeTrackerConfig.ColourTheme.CONTRAST;
		final GeSlotsPanel.SlotInfo working = slot(GeSlotsPanel.SlotState.ACTIVE_OK, false, false);
		working.quantityTotal = 10;
		working.quantityFilled = 10;
		final BufferedImage ok = paintCell(working);
		Assert.assertEquals("no box on a working slot", GeSlotsPanel.EMPTY_BORDER.getRGB(), ok.getRGB(ok.getWidth() / 2, 0));
		Assert.assertEquals("its bar in the sell colour", t.sell().getRGB(), ok.getRGB(ok.getWidth() / 2, ok.getHeight() - 1));
		Assert.assertEquals("on a grey tile", GeSlotsPanel.SLOT_FILL.getRGB(), ok.getRGB(3, 3));
		final BufferedImage empty = paintCell(slot(GeSlotsPanel.SlotState.EMPTY, false, false));
		Assert.assertEquals("an empty slot has none", 0, empty.getRGB(3, 3) >>> 24);

		final GeSlotsPanel.SlotInfo reprice = slot(GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, false);
		final BufferedImage boxed = paintCell(reprice);
		final java.awt.Color white = new java.awt.Color(boxed.getRGB(boxed.getWidth() / 2, 0));
		Assert.assertTrue("boxed in white: " + white, white.getRed() > 0xC0 && white.getGreen() > 0xC0 && white.getBlue() > 0xC0);
		Assert.assertTrue("a touch under full strength", white.getRed() < GeSlotsPanel.REPRICE_COLOR.getRed());
		Assert.assertEquals("one pixel of it", GeSlotsPanel.SLOT_FILL.getRGB(), boxed.getRGB(boxed.getWidth() / 2, 1));

		/* Done: boxed green, and the bar full in the side's own colour, so a
		   finished sale and a finished buy differ — "go with A". */
		final BufferedImage sold = paintCell(slot(GeSlotsPanel.SlotState.READY_COLLECT, false, false));
		final int w = sold.getWidth();
		final int h = sold.getHeight();
		Assert.assertEquals("boxed green", GeSlotsPanel.COLLECT_COLOR.getRGB(), sold.getRGB(w / 2, 0));
		/* "green should be more niciable than white": two pixels to the
		   white's one, at full strength. */
		Assert.assertEquals("two pixels of it", GeSlotsPanel.COLLECT_COLOR.getRGB(), sold.getRGB(w / 2, 1));
		Assert.assertEquals("down the side too", GeSlotsPanel.COLLECT_COLOR.getRGB(), sold.getRGB(1, 10));
		Assert.assertEquals("and no more", GeSlotsPanel.SLOT_FILL.getRGB(), sold.getRGB(w / 2, 2));
		for (int y = h - 3; y < h; y++)
		{
			Assert.assertEquals("a full bar in the sell colour", t.sell().getRGB(), sold.getRGB(w - 2, y));
		}
		final BufferedImage bought = paintCell(slot(GeSlotsPanel.SlotState.READY_COLLECT, true, false));
		Assert.assertEquals("boxed green", GeSlotsPanel.COLLECT_COLOR.getRGB(), bought.getRGB(w / 2, 0));
		for (int y = h - 3; y < h; y++)
		{
			Assert.assertEquals("a full bar in the buy colour", t.buy().getRGB(), bought.getRGB(w - 2, y));
		}
		Assert.assertNotEquals("so the two differ", t.buy().getRGB(), t.sell().getRGB());
	}

	/** Green once done, buy or sell; the side's colour until then. */
	@Test
	public void aFinishedSlotsBarKeepsItsSidesColour()
	{
		final PocketGeTrackerConfig.ColourTheme t = PocketGeTrackerConfig.ColourTheme.CONTRAST;
		GeSlotsPanel.setTheme(t.buy(), t.sell());
		for (boolean buy : new boolean[]{true, false})
		{
			Assert.assertEquals(GeSlotsPanel.sideColour(buy),
				GeSlotsPanel.barColour(slot(GeSlotsPanel.SlotState.READY_COLLECT, buy, false)));
			Assert.assertEquals(GeSlotsPanel.sideColour(buy),
				GeSlotsPanel.barColour(slot(GeSlotsPanel.SlotState.ACTIVE_OK, buy, false)));
			Assert.assertEquals(GeSlotsPanel.sideColour(buy),
				GeSlotsPanel.barColour(slot(GeSlotsPanel.SlotState.ACTIVE_ADJUST, buy, false)));
		}
	}

	/** One of the panel's squares, sized as the grid lays it out and
	 *  painted into an image. */
	/**
	 * Under a 125% or 150% UI scale the green is one solid band wherever the
	 * square sits. Drawn as two one-pixel rings it parted on some edges, at
	 * some offsets, into two green lines with the dark tile between.
	 */
	@Test
	public void theGreenIsSolidUnderAFractionalScale() throws Exception
	{
		final javax.swing.JComponent cell = cellFor(slot(GeSlotsPanel.SlotState.READY_COLLECT, false, false));
		for (double scale : new double[]{1.25, 1.5, 1.75})
		{
			for (int off = 0; off < 4; off++)
			{
				final BufferedImage img = new BufferedImage(120, 120, BufferedImage.TYPE_INT_ARGB);
				final java.awt.Graphics2D g = img.createGraphics();
				g.scale(scale, scale);
				g.translate(off, off);
				cell.paint(g);
				g.dispose();
				/* The device pixels wholly inside the band, down the left
				   edge and along the top, half way along each. */
				final int from = (int) Math.ceil(off * scale);
				final int to = (int) Math.floor((off + GeSlotsPanel.COLLECT_BOX_PX) * scale);
				final int midY = (int) ((off + 15) * scale);
				final int midX = (int) ((off + 24) * scale);
				for (int d = from; d < to; d++)
				{
					Assert.assertEquals("left, at " + scale + "x, offset " + off + ", x " + d,
						GeSlotsPanel.COLLECT_COLOR.getRGB(), img.getRGB(d, midY));
					Assert.assertEquals("top, at " + scale + "x, offset " + off + ", y " + d,
						GeSlotsPanel.COLLECT_COLOR.getRGB(), img.getRGB(midX, d));
				}
			}
		}
	}

	private static BufferedImage paintCell(GeSlotsPanel.SlotInfo info) throws Exception
	{
		final javax.swing.JComponent cell = cellFor(info);
		final BufferedImage img = new BufferedImage(cell.getWidth(), cell.getHeight(), BufferedImage.TYPE_INT_ARGB);
		final Graphics g = img.createGraphics();
		cell.paint(g);
		g.dispose();
		return img;
	}

	private static javax.swing.JComponent cellFor(GeSlotsPanel.SlotInfo info) throws Exception
	{
		final GeSlotsPanel panel = new GeSlotsPanel(null, null);
		panel.update(new GeSlotsPanel.SlotInfo[]{info, null, null, null, null, null, null, null});
		panel.setSize(225, 120);
		panel.doLayout();
		javax.swing.JComponent cell = null;
		for (java.awt.Component c : allOf(panel))
		{
			if (c.getClass().getSimpleName().equals("Cell"))
			{
				cell = (javax.swing.JComponent) c;
				break;
			}
		}
		Assert.assertNotNull("a Cell in the grid", cell);
		cell.setSize(49, 40);
		return cell;
	}

	private static java.util.List<java.awt.Component> allOf(java.awt.Container root)
	{
		final java.util.List<java.awt.Component> out = new java.util.ArrayList<>();
		for (java.awt.Component c : root.getComponents())
		{
			out.add(c);
			if (c instanceof java.awt.Container)
			{
				out.addAll(allOf((java.awt.Container) c));
			}
		}
		return out;
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Method;
import org.junit.Assert;
import org.junit.Test;

/**
 * The GE slot's hover says what to do, in a couple of words.
 *
 * It ran to six lines — item, "Buying N of M", projected profit, profit so
 * far, a diagnosis and an instruction. Every line was true and the whole was
 * no easier to read than the coloured border it existed to explain. The report
 * was "such a long hover tool tip … can't it just turn red and say something
 * like adjust price, or lower price, raise price, no margin".
 *
 * So: at most three lines, and the state line is a VERB. "Off the market"
 * named a problem and left you to go and find the number.
 */
public class SlotTooltipTest
{
	private static String tip(SlotShape shape) throws Exception
	{
		final Method m = GeOfferGridOverlay.class
			.getDeclaredMethod("tooltipText", GeOfferGridOverlay.SlotView.class);
		m.setAccessible(true);
		return (String) m.invoke(null, shape.view);
	}

	/** A slot, built by hand — SlotView is a plain data holder. */
	private static final class SlotShape
	{
		final GeOfferGridOverlay.SlotView view = new GeOfferGridOverlay.SlotView();

		SlotShape(boolean buy)
		{
			view.itemName = "Ruby";
			view.buy = buy;
			view.filled = 4_000;
			view.total = 12_328;
			view.offerPrice = 791;
		}

		SlotShape adjust(long target)
		{
			view.needsAdjust = true;
			view.targetPrice = target;
			return this;
		}

		SlotShape noMargin()
		{
			view.needsAdjust = true;
			view.noMargin = true;
			return this;
		}

		SlotShape skipped()
		{
			view.adviceSkipped = true;
			return this;
		}

		SlotShape profit(long p)
		{
			view.projectedProfit = p;
			return this;
		}
	}

	/** Lines, as the client counts them. */
	private static int lines(String tip)
	{
		return tip.split("</br>", -1).length;
	}

	@Test
	public void aMispricedSellSaysWhichWayToMoveAndToWhat() throws Exception
	{
		final String t = tip(new SlotShape(false).adjust(788).profit(145_000));
		Assert.assertTrue("names the direction: " + t, t.contains("Lower your ask to "));
		Assert.assertTrue("and the exact price, with separators", t.contains("788 gp"));
		Assert.assertTrue("and what you currently have in", t.contains("yours: 791"));
	}

	@Test
	public void aMispricedBuySaysTheOtherDirection() throws Exception
	{
		final String t = tip(new SlotShape(true).adjust(103).profit(80_000));
		Assert.assertTrue("a bid is always too LOW when it is wrong: " + t,
			t.contains("Raise to "));
		Assert.assertTrue("and the other answer — the new price may not be worth it: " + t,
			t.contains("or cancel"));
		Assert.assertFalse("never both", t.contains("Lower your ask"));
	}

	/**
	 * The green state now says something. It has always meant "not red",
	 * which is true and tells you nothing — reported as: I ignored the
	 * suggested price, typed my own, and the box stayed green, was it even
	 * listening? It was; the difference was inside the drift threshold.
	 */
	@Test
	public void aFineSlotSaysSoRatherThanJustNotBeingRed() throws Exception
	{
		final String t = tip(new SlotShape(false).profit(145_000));
		Assert.assertTrue("says it is fine: " + t, t.contains("Priced fine"));
		Assert.assertFalse("and does not ask for anything", t.contains("re-list"));
	}

	@Test
	public void noMarginSaysToWalkAwayRatherThanReprice() throws Exception
	{
		final String t = tip(new SlotShape(false).noMargin().profit(-4_000));
		Assert.assertTrue("no margin: " + t, t.contains("No margin left"));
		Assert.assertTrue("and what to do instead", t.contains("take a new flip"));
		Assert.assertFalse("repricing is the thing that does NOT help here",
			t.contains("Lower your ask"));
	}

	@Test
	public void aSlotYouArePricingYourselfSaysOnlyThat() throws Exception
	{
		final String t = tip(new SlotShape(false).skipped().profit(1));
		Assert.assertTrue(t.contains("You are pricing this one"));
		Assert.assertFalse("no instruction, because you turned them off",
			t.contains("Lower your ask") || t.contains("Priced fine"));
	}

	/** The whole point: it has to be SHORT. */
	@Test
	public void noShapeRunsPastThreeLines() throws Exception
	{
		Assert.assertTrue(lines(tip(new SlotShape(false).adjust(788).profit(145_000))) <= 3);
		Assert.assertTrue(lines(tip(new SlotShape(true).adjust(103).profit(80_000))) <= 3);
		Assert.assertTrue(lines(tip(new SlotShape(false).noMargin().profit(-4_000))) <= 3);
		Assert.assertTrue(lines(tip(new SlotShape(false).skipped().profit(1))) <= 3);
		Assert.assertTrue(lines(tip(new SlotShape(false).profit(145_000))) <= 3);
		/* And the one with no tracked cost, which is a different third line. */
		Assert.assertTrue(lines(tip(new SlotShape(false).adjust(788))) <= 3);
	}

	/**
	 * The lines that went, and must not creep back: the game already prints
	 * the quantity in the box, and "So far" is the same figure as the
	 * projection until an offer is part-filled.
	 */
	@Test
	public void theDuplicatedLinesAreGone() throws Exception
	{
		final SlotShape s = new SlotShape(false).adjust(788).profit(145_000);
		final String t = tip(s);
		Assert.assertFalse("the game prints this in the box itself: " + t, t.contains(" of "));
		Assert.assertFalse("a detail, not a verdict", t.contains("So far"));
	}

	/**
	 * A sell part-way sold says what it has made and what is to come, on the
	 * one money line, so the hover still keeps to three: "seee how i made
	 * 295k emeralds. it should atleast say 295k of x amount total 85k left".
	 */
	@Test
	public void aPartSoldSellSaysWhatItMadeOnOneLine() throws Exception
	{
		final SlotShape s = new SlotShape(false).profit(85_800);
		s.view.bookedProfit = 295_776L;
		s.view.bookedUnits = s.view.filled;
		final String t = tip(s);
		Assert.assertTrue(t, t.contains("so far"));
		Assert.assertTrue(t, t.contains("to come"));
		Assert.assertTrue(t, lines(t) <= 3);
	}

	/**
	 * A sell the plugin never watched being bought must not claim a profit
	 * measured from a cost of zero.
	 */
	@Test
	public void anUntrackedSellClaimsNoProfit() throws Exception
	{
		final String t = tip(new SlotShape(false).adjust(788));
		Assert.assertTrue("says why there is no figure: " + t, t.contains("Cost unknown"));
		Assert.assertFalse(t.contains("Profit:"));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * The slot hover on a sell: what it has made so far, and what the rest will
 * make, by the rule the sale books with.
 */
public class SlotViewSaleTest
{
	private static final int ITEM = 30771;

	private static FlipTracker tracker(PocketGeTrackerPlugin plugin) throws Exception
	{
		final Field f = PocketGeTrackerPlugin.class.getDeclaredField("tracker");
		f.setAccessible(true);
		return (FlipTracker) f.get(plugin);
	}

	@SuppressWarnings("unchecked")
	private static GeOfferGridOverlay.SlotView view(PocketGeTrackerPlugin plugin, Advisor.OfferView o,
		Map<Integer, long[]> openBuys) throws Exception
	{
		final Method build = PocketGeTrackerPlugin.class.getDeclaredMethod("buildSlotViews",
			List.class, Map.class, Map.class, Map.class, Map.class);
		build.setAccessible(true);
		return ((Map<Integer, GeOfferGridOverlay.SlotView>) build.invoke(plugin, List.of(o), new HashMap<>(), openBuys,
			new HashMap<>(), new HashMap<>())).get(o.slot);
	}

	private static Advisor.OfferView sell(int sold)
	{
		final Advisor.OfferView o = new Advisor.OfferView();
		o.slot = 1;
		o.itemId = ITEM;
		o.itemName = "Aether catalyst";
		o.buy = false;
		o.price = 300;
		o.totalQuantity = 2_000;
		o.quantitySold = sold;
		o.active = true;
		return o;
	}

	/** Bought 2,000 at 277, listed at 300, 1,000 sold: "Made +17K so far,
	 *  +17K to come". The first 0.7.6 dropped the "so far". */
	@Test
	public void aPartSoldSellKeepsWhatItHasMadeSoFar() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		final FlipTracker t = tracker(plugin);
		t.setAccountHash(42L);
		t.onOffer(1, 0, ITEM, "Aether catalyst", true, 0, 0, 277, 2_000, false);
		t.onOffer(2, 0, ITEM, "Aether catalyst", true, 2_000, 2_000L * 277, 277, 2_000, false);
		t.onOffer(3, 0, 0, "", false, 0, 0, 0, 0, true);
		t.onOffer(4, 1, ITEM, "Aether catalyst", false, 0, 0, 300, 2_000, false);
		t.onOffer(5, 1, ITEM, "Aether catalyst", false, 1_000, 300_000, 300, 2_000, false);

		final GeOfferGridOverlay.SlotView v = view(plugin, sell(1_000), new HashMap<>());
		final long each = 300 - FlipTracker.taxPerItem(300, ITEM) - 277;
		Assert.assertEquals("made so far", Long.valueOf(1_000 * each), v.bookedProfit);
		Assert.assertEquals(1_000, v.bookedUnits);
		Assert.assertEquals("to come, by the booking's own rule", Long.valueOf(1_000 * each), v.projectedProfit);
	}

	/** A record that nothing on file can be charged against: no profit
	 *  projected — not one priced from lots the sale will never touch. */
	@Test
	public void nothingTheSaleCanBeChargedMeansNoProjection() throws Exception
	{
		final PocketGeTrackerPlugin plugin = new PocketGeTrackerPlugin();
		final FlipTracker t = tracker(plugin);
		t.setAccountHash(42L);
		/* Listed from stock the plugin never saw bought, then a buy of the
		   same item after the listing: not in this offer. */
		t.onOffer(1, 1, ITEM, "Aether catalyst", false, 0, 0, 300, 2_000, false);
		t.onOffer(2, 0, ITEM, "Aether catalyst", true, 0, 0, 277, 1_000, false);
		t.onOffer(3, 0, ITEM, "Aether catalyst", true, 1_000, 277_000, 277, 1_000, false);
		t.onOffer(4, 0, 0, "", false, 0, 0, 0, 0, true);
		final Map<Integer, long[]> openBuys = new HashMap<>();
		openBuys.put(ITEM, new long[]{1_000, 277_000});

		final GeOfferGridOverlay.SlotView v = view(plugin, sell(0), openBuys);
		Assert.assertNull(v.projectedProfit);
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import org.junit.Assert;
import org.junit.Test;

/**
 * The sidebar square and the in-game GE box say the same words about the same
 * slot.
 *
 * There are two hovers, and both were long: the in-game one ran to six lines,
 * and the sidebar's was a single run-on sentence — "Selling Ruby — 4,000 of
 * 12,328 (32%) (needs a new price). The market moved to 788 gp; yours is at
 * 791 gp. Re-list at 788 gp — aborting keeps whatever already filled.
 * Right-click to stop being told to reprice it. Click to inspect it." Every
 * clause true, and nobody reads a paragraph off a 32px square.
 *
 * Both are three short lines now. The part worth a test is not the length but
 * the AGREEMENT: two surfaces describing the same eight slots, and a state
 * that is called one thing in the sidebar and another in the Exchange window
 * is worse than either wording on its own. Nothing in the compiler stops them
 * drifting, because they are different classes with different data holders.
 */
public class SlotWordingTest
{
	/** The verbs both surfaces have to use, for the states both can be in. */
	private static final String PRICED_FINE = "Priced fine";
	private static final String LOWER = "Lower your ask to ";
	private static final String RAISE = "Raise to ";
	private static final String NO_MARGIN = "No margin left";
	private static final String YOURS = "You are pricing this one";

	// ---- the in-game box ---------------------------------------------------

	private static String inGame(boolean buy, boolean adjust, boolean noMargin,
		boolean skipped, long target) throws Exception
	{
		final GeOfferGridOverlay.SlotView v = new GeOfferGridOverlay.SlotView();
		v.itemName = "Ruby";
		v.buy = buy;
		v.needsAdjust = adjust;
		v.noMargin = noMargin;
		v.adviceSkipped = skipped;
		v.targetPrice = target;
		v.offerPrice = 791;
		final Method m = GeOfferGridOverlay.class
			.getDeclaredMethod("stateLine", GeOfferGridOverlay.SlotView.class);
		m.setAccessible(true);
		return strip((String) m.invoke(null, v));
	}

	// ---- the sidebar square ------------------------------------------------

	private static String sidebar(boolean buy, GeSlotsPanel.SlotState state, boolean noMargin,
		boolean skipped, long target) throws Exception
	{
		final GeSlotsPanel.SlotInfo s = new GeSlotsPanel.SlotInfo();
		s.itemName = "Ruby";
		s.buy = buy;
		s.state = state;
		s.noMargin = noMargin;
		s.adviceSkipped = skipped;
		s.targetPrice = target;
		s.offerPrice = 791;

		/* The cell is a private inner class and its stateLine is an instance
		   method on it. Reached reflectively rather than widening either for
		   a test. */
		final Class<?> cell = Class.forName("com.pocketge.tracker.GeSlotsPanel$Cell");
		final Constructor<?> ctor = cell.getDeclaredConstructors()[0];
		ctor.setAccessible(true);
		final Object instance = alloc(cell);
		final Method m = cell.getDeclaredMethod("stateLine", GeSlotsPanel.SlotInfo.class);
		m.setAccessible(true);
		return strip((String) m.invoke(instance, s));
	}

	private static Object alloc(Class<?> c) throws Exception
	{
		final java.lang.reflect.Field f = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
		f.setAccessible(true);
		final sun.misc.Unsafe unsafe = (sun.misc.Unsafe) f.get(null);
		return unsafe.allocateInstance(c);
	}

	/** The in-game text carries RuneScape colour tags; the sidebar's does not.
	 *  Compare the words, not the markup. */
	private static String strip(String s)
	{
		return s.replaceAll("<[^>]*>", "").trim();
	}

	// ---- the agreement -----------------------------------------------------

	@Test
	public void bothCallAFineSlotTheSameThing() throws Exception
	{
		Assert.assertTrue(inGame(false, false, false, false, 0).startsWith(PRICED_FINE));
		Assert.assertTrue(
			sidebar(false, GeSlotsPanel.SlotState.ACTIVE_OK, false, false, 0).startsWith(PRICED_FINE));
	}

	@Test
	public void bothTellYouWhichWayToMoveASell() throws Exception
	{
		final String a = inGame(false, true, false, false, 788);
		final String b = sidebar(false, GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, false, 788);
		Assert.assertTrue("in-game: " + a, a.startsWith(LOWER) && a.contains("788"));
		Assert.assertTrue("sidebar: " + b, b.startsWith(LOWER) && b.contains("788"));
		Assert.assertTrue("both show what you have in now",
			a.contains("791") && b.contains("791"));
	}

	@Test
	public void bothTellYouWhichWayToMoveABuy() throws Exception
	{
		Assert.assertTrue(inGame(true, true, false, false, 103).startsWith(RAISE));
		Assert.assertTrue(
			sidebar(true, GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, false, 103).startsWith(RAISE));
	}

	@Test
	public void bothSayNoMarginRatherThanReprice() throws Exception
	{
		final String a = inGame(false, true, true, false, 0);
		final String b = sidebar(false, GeSlotsPanel.SlotState.ACTIVE_ADJUST, true, false, 0);
		Assert.assertTrue(a.startsWith(NO_MARGIN));
		Assert.assertTrue(b.startsWith(NO_MARGIN));
		Assert.assertFalse("repricing is the thing that does not help here", a.contains(LOWER));
		Assert.assertFalse(b.contains(LOWER));
	}

	@Test
	public void bothSayWhenYouHaveTakenTheSlotOver() throws Exception
	{
		Assert.assertTrue(inGame(false, true, false, true, 788).startsWith(YOURS));
		Assert.assertTrue(
			sidebar(false, GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, true, 788).startsWith(YOURS));
	}

	/**
	 * Only the sidebar has this one: the in-game overlay never draws a
	 * collected offer, because buildSlotViews drops inactive ones before it
	 * gets there. So it is checked on the surface that has it.
	 */
	@Test
	public void theSidebarNamesACollectableSlot() throws Exception
	{
		Assert.assertEquals("Ready to collect.",
			sidebar(false, GeSlotsPanel.SlotState.READY_COLLECT, false, false, 0));
	}

	/** And neither of them is a paragraph any more. */
	@Test
	public void everyStateLineIsOneShortSentence() throws Exception
	{
		final String[] all = {
			inGame(false, false, false, false, 0),
			inGame(false, true, false, false, 788),
			inGame(true, true, false, false, 103),
			inGame(false, true, true, false, 0),
			inGame(false, true, false, true, 788),
			sidebar(false, GeSlotsPanel.SlotState.ACTIVE_OK, false, false, 0),
			sidebar(false, GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, false, 788),
			sidebar(true, GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, false, 103),
			sidebar(false, GeSlotsPanel.SlotState.ACTIVE_ADJUST, true, false, 0),
			sidebar(false, GeSlotsPanel.SlotState.READY_COLLECT, false, false, 0),
		};
		for (String line : all)
		{
			Assert.assertTrue("still a paragraph (" + line.length() + "): " + line,
				line.length() <= 50);
		}
	}
}

package com.pocketge.tracker;

import java.awt.Color;
import java.awt.Insets;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import org.junit.Assert;
import org.junit.Test;

/**
 * Watchlist rows outlined for a price spike: stacked, they drew their
 * touching edges twice — "these bars when stacked get double thick
 * borders". The lower row leaves its top edge to the one above.
 */
public class SpikeBorderTest
{
	private static JPanel spikeRow()
	{
		final JPanel p = new JPanel();
		p.putClientProperty(FavoritesPanel.SPIKE_ROW, Boolean.TRUE);
		return p;
	}

	@Test
	public void aRowUnderAnOutlinedRowSharesItsEdge()
	{
		final JPanel rows = new JPanel();
		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		final JPanel plain = new JPanel();
		final JPanel first = spikeRow();
		final JPanel second = spikeRow();
		rows.add(plain);
		rows.add(first);
		rows.add(second);
		Assert.assertFalse("under a plain row: its own top edge", FavoritesPanel.outlinedAbove(rows, first));
		Assert.assertTrue("under an outlined row: shared", FavoritesPanel.outlinedAbove(rows, second));
		Assert.assertFalse("the first row has nothing above", FavoritesPanel.outlinedAbove(rows, plain));
		first.setVisible(false);
		Assert.assertFalse("a hidden row above draws nothing to share", FavoritesPanel.outlinedAbove(rows, second));
	}

	/** One line between them, 2px like every other edge, and no row changes height. */
	@Test
	public void theSharedEdgeIsOneLineAndTheRowKeepsItsHeight()
	{
		final JPanel probe = new JPanel();
		final Insets own = FavoritesPanel.spikeBorder(Color.RED, false).getBorderInsets(probe);
		final Insets shared = FavoritesPanel.spikeBorder(Color.RED, true).getBorderInsets(probe);
		Assert.assertEquals("same height either way", own.top + own.bottom, shared.top + shared.bottom);
		Assert.assertEquals(own.left, shared.left);
		Assert.assertEquals(own.right, shared.right);
		final javax.swing.border.CompoundBorder b = (javax.swing.border.CompoundBorder) FavoritesPanel.spikeBorder(Color.RED, true);
		Assert.assertEquals("no top line of its own", 0, b.getOutsideBorder().getBorderInsets(probe).top);
		Assert.assertEquals("and its bottom line still there", 2, b.getOutsideBorder().getBorderInsets(probe).bottom);
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.net.InetAddress;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.BooleanSupplier;
import org.junit.After;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;

/**
 * Whether the plugin believes a PocketGE tab is open, after it has closed.
 *
 * Reported as "it takes it over right away if there is already a tab open",
 * but with the tab just closed "it took 4 times doing that for it to finally
 * open a new tab". A closed tab's parked /nav could not be seen from the
 * plugin and counted as a listener for up to 25 seconds; the answer written
 * to it then counted as a fresh poll for 8 more. Every click in that window
 * was "sent to your open tab" — which no longer existed.
 */
public class TabHandoffTest
{
	private static final String SITE = "https://pocketge.com";
	private static final long FAR = Long.MAX_VALUE / 2; // a since no request reaches, so it parks

	private LocalBridgeServer bridge;
	private final List<Long> acks = new CopyOnWriteArrayList<>();

	@Before
	public void start() throws Exception
	{
		bridge = new LocalBridgeServer(new Gson());
		bridge.setAckListener(acks::add);
		bridge.start(0, HashMap::new, HashMap::new, null, null);
	}

	@After
	public void stop()
	{
		bridge.stop();
	}

	// -- a tab that closes -------------------------------------------------

	/** The browser hanging up does not reach a parked request. Its goodbye
	 *  does, and then nothing is counted as open. */
	@Test
	public void aClosedTabsGoodbyeEndsItsListener() throws Exception
	{
		final Socket tab = park("/nav?since=" + FAR + "&tab=111-1&ack=1");
		waitFor(bridge::hasParkedNavListener);
		Assert.assertTrue(bridge.hasConfirmingListener());

		tab.close();
		Thread.sleep(150);
		Assert.assertTrue("the plugin cannot see a hang-up — why the goodbye exists",
			bridge.hasParkedNavListener());

		Assert.assertEquals(204, status(get("/tab/closed?tab=111-1", SITE)));
		waitFor(() -> !bridge.hasParkedNavListener());
		Assert.assertFalse("nor does its last request count as a recent poll",
			bridge.hasNavListener(8_000));
		Assert.assertFalse(bridge.hasRecentClient(8_000));
		Assert.assertFalse(bridge.hasConfirmingListener());
	}

	/** The woken park is ANSWERED, not just dropped. A connection closed with
	 *  no reply is one Chromium resends the request on — which parked the
	 *  closed tab all over again. */
	@Test
	public void theWokenParkGetsAnAnswer() throws Exception
	{
		final Socket tab = park("/nav?since=" + FAR + "&tab=111-1&ack=1");
		waitFor(bridge::hasParkedNavListener);
		get("/tab/closed?tab=111-1", SITE);
		tab.setSoTimeout(3_000);
		final byte[] buf = new byte[256];
		final int n = tab.getInputStream().read(buf);
		Assert.assertTrue(n > 0);
		Assert.assertTrue(new String(buf, 0, n, StandardCharsets.UTF_8).startsWith("HTTP/1.1 204"));
		tab.close();
	}

	/** And if the browser does send the closed tab's /nav again, it is
	 *  answered at once and does not bring the tab back. */
	@Test
	public void aClosedTabsResentRequestDoesNotPark() throws Exception
	{
		get("/tab/closed?tab=111-1", SITE);
		final long t0 = System.currentTimeMillis();
		Assert.assertEquals(204, status(get("/nav?since=" + FAR + "&tab=111-1&ack=1", SITE)));
		Assert.assertTrue("answered, not parked", System.currentTimeMillis() - t0 < 2_000);
		Assert.assertFalse(bridge.hasNavListener(8_000));
		Assert.assertFalse(bridge.hasConfirmingListener());
	}

	/** One tab closing says nothing about the others. */
	@Test
	public void anotherTabStaysOpen() throws Exception
	{
		final Socket a = park("/nav?since=" + FAR + "&tab=111-1&ack=1");
		final Socket b = park("/nav?since=" + FAR + "&tab=222-2&ack=1");
		waitFor(() -> parked() == 2);
		a.close();
		get("/tab/closed?tab=111-1", SITE);
		waitFor(() -> parked() == 1);
		Assert.assertTrue(bridge.hasParkedNavListener());
		Assert.assertTrue(bridge.hasNavListener(8_000));
		b.close();
	}

	/** Closed between two of its polls, with nothing parked anywhere: that
	 *  was the last tab. */
	@Test
	public void aGoodbyeWithNothingParkedForgetsTheTab() throws Exception
	{
		ageNavPoll(0);
		Assert.assertTrue(bridge.hasNavListener(8_000));
		get("/tab/closed?tab=111-1", SITE);
		Assert.assertFalse(bridge.hasNavListener(8_000));
	}

	/** The Flip History page polls /flips and never takes a chart click, so
	 *  it is a page but not a listener: with only it open, every click was
	 *  "sent to your open tab" and went nowhere. */
	@Test
	public void aPageThatOnlyPollsFlipsIsNotAListener() throws Exception
	{
		get("/flips", SITE);
		Assert.assertTrue("it is a PocketGE page, for the panel's 'linked' line", bridge.hasRecentClient(8_000));
		Assert.assertFalse("but not one that can take a handoff", bridge.hasNavListener(8_000));
	}

	/** A timed-out handoff forgets what it disproved — the evidence from
	 *  before the click — and nothing newer. */
	@Test
	public void forgettingStopsAtTheClick() throws Exception
	{
		final Socket tab = park("/nav?since=" + FAR + "&tab=111-1&ack=1");
		waitFor(bridge::hasParkedNavListener);
		bridge.forgetClients(System.currentTimeMillis() - 60_000); // a click from before it asked
		Assert.assertTrue("a tab that asked after the click is still believed", bridge.hasConfirmingListener());
		bridge.forgetClients(Long.MAX_VALUE);
		Assert.assertTrue("and one parked right now still confirms", bridge.hasConfirmingListener());
		tab.close();
	}

	/** While a page from before the ack is listening, the plugin must not
	 *  wait for one: that page would take the click silently and the item
	 *  would open twice. */
	@Test
	public void anOldPageListeningMeansNoWait() throws Exception
	{
		final Socket fresh = park("/nav?since=" + FAR + "&tab=111-1&ack=1");
		final Socket old = park("/nav?since=" + FAR);
		waitFor(() -> parked() == 2);
		Assert.assertFalse(bridge.hasConfirmingListener());
		fresh.close();
		old.close();
	}

	/** A bridge switched off is not a tab. */
	@Test
	public void stoppingForgetsTheTab() throws Exception
	{
		get("/flips", SITE);
		ageNavPoll(0);
		bridge.stop();
		Assert.assertFalse(bridge.hasRecentClient(8_000));
		Assert.assertFalse(bridge.hasNavListener(8_000));
		bridge.start(0, HashMap::new, HashMap::new, null, null);
	}

	/** The end of a park is not a poll. A dead connection's park ends exactly
	 *  like a live one's, and refreshing lastPollAt there kept a closed tab
	 *  "recent" for the next several clicks. */
	@Test
	public void theEndOfAParkIsNotAPoll() throws Exception
	{
		final Socket tab = park("/nav?since=0&tab=111-1&ack=1");
		waitFor(bridge::hasParkedNavListener);
		tab.close();
		ageLastPoll(20_000); // it asked twenty seconds ago, as a closed tab's park would have

		bridge.publishNav(new LocalBridgeServer.NavRequest(5, "Ring of nature", 0, System.currentTimeMillis()));
		waitFor(() -> !bridge.hasParkedNavListener());
		Assert.assertFalse(bridge.hasRecentClient(8_000));
		Assert.assertFalse(bridge.hasNavListener(8_000));
	}

	// -- the ack ----------------------------------------------------------

	@Test
	public void aTabsAckReachesThePlugin() throws Exception
	{
		Assert.assertEquals(204, status(get("/tab/ack?seq=1800000000123", SITE)));
		Assert.assertEquals(List.of(1_800_000_000_123L), acks);
		Assert.assertTrue("a page answering is a page that is there", bridge.hasNavListener(8_000));
	}

	/** Same rule as every other endpoint: another website cannot speak for
	 *  the tab. */
	@Test
	public void anotherSitesAckIsRefused() throws Exception
	{
		Assert.assertEquals(403, status(get("/tab/ack?seq=7", "https://evil.example")));
		Assert.assertEquals(403, status(get("/tab/closed?tab=111-1", "https://evil.example")));
		Assert.assertTrue(acks.isEmpty());
	}

	/** A page from before the ack never makes the plugin wait for one. */
	@Test
	public void anOlderPageIsNotWaitedOn() throws Exception
	{
		final Socket old = park("/nav?since=" + FAR);
		waitFor(bridge::hasParkedNavListener);
		Assert.assertFalse(bridge.hasConfirmingListener());
		old.close();
	}

	@Test
	public void theRequestCarriesTheAckFlag()
	{
		final String json = new Gson().toJson(new LocalBridgeServer.NavRequest(9, "Ring of nature", 0, 1L, true));
		Assert.assertTrue(json, json.contains("\"ack\":true"));
	}

	@Test
	public void onlyTabIdsThePageMintsAreKept()
	{
		Assert.assertEquals("8231-1800000000000", LocalBridgeServer.tabId("8231-1800000000000"));
		Assert.assertNull(LocalBridgeServer.tabId("<script>"));
		Assert.assertNull(LocalBridgeServer.tabId(""));
		Assert.assertNull(LocalBridgeServer.tabId(null));
		Assert.assertNull(LocalBridgeServer.tabId("1".repeat(65)));
	}

	// -- plumbing ---------------------------------------------------------

	private int parked()
	{
		try
		{
			final Field f = LocalBridgeServer.class.getDeclaredField("parkedNavs");
			f.setAccessible(true);
			return ((java.util.concurrent.atomic.AtomicInteger) f.get(bridge)).get();
		}
		catch (ReflectiveOperationException e)
		{
			throw new AssertionError(e);
		}
	}

	private void ageLastPoll(long ms) throws Exception
	{
		for (String name : new String[]{"lastPollAt", "lastNavPollAt"})
		{
			final Field f = LocalBridgeServer.class.getDeclaredField(name);
			f.setAccessible(true);
			f.setLong(bridge, System.currentTimeMillis() - ms);
		}
	}

	/** As if a page running the /nav loop asked {@code ms} ago. */
	private void ageNavPoll(long ms) throws Exception
	{
		ageLastPoll(ms);
	}

	private static void waitFor(BooleanSupplier condition) throws Exception
	{
		final long until = System.currentTimeMillis() + 3_000;
		while (!condition.getAsBoolean())
		{
			if (System.currentTimeMillis() > until)
			{
				Assert.fail("timed out");
			}
			Thread.sleep(10);
		}
	}

	/** Send a request and leave it open, as a tab's parked /nav is. */
	private Socket park(String path) throws Exception
	{
		final Socket s = new Socket(InetAddress.getLoopbackAddress(), bridge.port());
		final OutputStream out = s.getOutputStream();
		out.write(request(path, SITE).getBytes(StandardCharsets.UTF_8));
		out.flush();
		return s;
	}

	private String request(String path, String origin)
	{
		return "GET " + path + " HTTP/1.1\r\n"
			+ "Host: 127.0.0.1:" + bridge.port() + "\r\n"
			+ "Origin: " + origin + "\r\n"
			+ "Connection: close\r\n\r\n";
	}

	private String get(String path, String origin) throws Exception
	{
		try (Socket s = new Socket(InetAddress.getLoopbackAddress(), bridge.port()))
		{
			s.setSoTimeout(3_000);
			final OutputStream out = s.getOutputStream();
			out.write(request(path, origin).getBytes(StandardCharsets.UTF_8));
			out.flush();
			final InputStream in = s.getInputStream();
			final ByteArrayOutputStream got = new ByteArrayOutputStream();
			final byte[] buf = new byte[4096];
			int n;
			try
			{
				while ((n = in.read(buf)) > 0)
				{
					got.write(buf, 0, n);
				}
			}
			catch (java.net.SocketTimeoutException done)
			{
				// what arrived is the answer
			}
			return got.toString(StandardCharsets.UTF_8);
		}
	}

	private static int status(String response)
	{
		return Integer.parseInt(response.substring(9, 12));
	}
}

package com.pocketge.tracker;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Assert;
import org.junit.Test;

/**
 * The two in-game tooltips speak one vocabulary.
 *
 * They did not. Each overlay wrote its own colours as hex literals inside the
 * markup, so the bank's tooltip was fixed and tested while the Exchange's kept
 * the exact brown the bank had just been rid of — {@code 8a8274}, two shades
 * off the tooltip's own background — on four of its lines.
 *
 * The test reads the sources, because that is where the defect lives: a hex
 * literal beside a {@link java.awt.Color} constant holding the same value is
 * the thing that let the border and the sentence explaining the border be
 * changed apart.
 */
public class TipStyleTest
{
	private static final List<String> OVERLAYS = List.of(
		"BankHighlightOverlay", "GeOfferGridOverlay");

	/**
	 * The class's CODE, with comments stripped.
	 *
	 * The comments name the colours that were removed, and are the record of
	 * why — deleting them to satisfy a grep would throw away the only account
	 * of a defect that has now been introduced twice.
	 */
	private static String source(String cls) throws IOException
	{
		final String raw = Files.readString(
			Path.of("src/main/java/com/pocketge/tracker/" + cls + ".java"));
		return raw.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
	}

	/**
	 * No colour is spelled out inside the markup any more.
	 *
	 * {@code <col=} followed by six hex digits is the whole bug class: it
	 * cannot be found by a compiler, cannot be moved with the theme, and reads
	 * as the same kind of thing whether it matches a constant or not.
	 */
	@Test
	public void noOverlayWritesAColourAsHex() throws Exception
	{
		final Pattern lit = Pattern.compile("<col=[0-9a-fA-F]{6}");
		for (String cls : OVERLAYS)
		{
			final Matcher m = lit.matcher(source(cls));
			Assert.assertFalse(cls + " still writes a colour into its markup: "
				+ (m.find() ? m.group() : ""), m.reset().find());
		}
	}

	/**
	 * The unreadable brown is gone from BOTH surfaces, not just the one that
	 * was reported.
	 */
	@Test
	public void theBrownIsGoneEverywhere() throws Exception
	{
		for (String cls : OVERLAYS)
		{
			Assert.assertFalse(cls + " still uses the 8a8274 brown",
				source(cls).toLowerCase().contains("8a8274"));
		}
		Assert.assertFalse("and the shared muted colour is not it",
			TipStyle.hex(TipStyle.MUTED).equals("8a8274"));
	}

	/**
	 * The near-gold that titled every Exchange tooltip is gone.
	 *
	 * e5c158 was not the theme's buy gold (E5B842), not the parchment the
	 * sidebar names items in, and not any other colour in the plugin — close
	 * enough to several to look deliberate and match none of them.
	 */
	@Test
	public void theNearMissGoldIsGone() throws Exception
	{
		Assert.assertFalse(source("GeOfferGridOverlay").toLowerCase().contains("e5c158"));
	}

	/** An item's name is parchment on every surface — the sidebar's TEXT_MAIN. */
	@Test
	public void namesTheSubjectInTheSameColourTheSidebarDoes()
	{
		Assert.assertEquals("d9d3c7", TipStyle.hex(TipStyle.SUBJECT));
		Assert.assertTrue(TipStyle.subject("Uncut ruby").contains("<col=d9d3c7>"));
	}

	/** The working is muted, and legibly so. */
	@Test
	public void mutesTheWorking()
	{
		Assert.assertEquals("a5a5a5", TipStyle.hex(TipStyle.MUTED));
	}

	/**
	 * Money keeps the sidebar's own green and red, and carries its sign.
	 *
	 * Same values as AdvisorPanel.POSITIVE and NEGATIVE, so a loss is the same
	 * red in the Exchange as on the card describing the same offer.
	 */
	@Test
	public void aGainAndALossWearTheSidebarsColours()
	{
		Assert.assertEquals(0x1FB85C, TipStyle.GOOD.getRGB() & 0xFFFFFF);
		Assert.assertEquals(0xEF5350, TipStyle.BAD.getRGB() & 0xFFFFFF);
		Assert.assertTrue(TipStyle.money(1_100_000).contains("+1.1M gp"));
		Assert.assertTrue(TipStyle.money(1_100_000).contains("1fb85c"));
		Assert.assertTrue(TipStyle.money(-250_000).contains("ef5350"));
		Assert.assertFalse("a loss needs no plus sign", TipStyle.money(-250_000).contains("+"));
	}

	/**
	 * A state line takes the colour of the mark it explains, from the caller.
	 *
	 * This is the one colour TipStyle refuses to choose. The bank's marks move
	 * with the theme and the Exchange's borders do not, and a tooltip that
	 * picked its own would be free to disagree with the square under the
	 * cursor — which is exactly how the bank ended up printing a frozen teal
	 * line under three themes that had moved.
	 */
	@Test
	public void aStateLineWearsTheMarksOwnColour()
	{
		final java.awt.Color neon = PocketGeTrackerConfig.ColourTheme.NEON.sell();
		Assert.assertTrue(TipStyle.state(neon, "up 12%").contains(TipStyle.hex(neon)));
	}

	/** Game markup, not HTML: the break is {@code </br>}. A {@code <br>} here
	 *  prints as four literal characters in the client. */
	@Test
	public void usesTheGamesOwnLineBreak()
	{
		Assert.assertEquals("</br>", TipStyle.BREAK);
		for (String cls : OVERLAYS)
		{
			try
			{
				Assert.assertFalse(cls + " uses an HTML break",
					source(cls).contains("\"<br>\""));
			}
			catch (IOException e)
			{
				throw new AssertionError(e);
			}
		}
	}
}

package com.pocketge.tracker;

import java.util.Random;
import org.junit.Assert;
import org.junit.Test;

public class TradeEngineTest
{
	private static TradeEngine.Series syntheticSeries(long now, int n, double baseLow, double baseHigh, long seed)
	{
		Random rnd = new Random(seed);
		TradeEngine.Series s = new TradeEngine.Series();
		s.labels = new long[n];
		s.low = new double[n];
		s.high = new double[n];
		s.lowVol = new double[n];
		s.highVol = new double[n];
		double low = baseLow, high = baseHigh;
		for (int i = 0; i < n; i++)
		{
			low += rnd.nextInt(3) - 1;
			high += rnd.nextInt(3) - 1;
			if (high < low + 40)
			{
				high = low + 40; // keep a real spread — 2% tax must stay clearable
			}
			s.labels[i] = now - (long) (n - 1 - i) * 300L;
			s.low[i] = low;
			s.high[i] = high;
			s.lowVol[i] = 50 + rnd.nextInt(200);
			s.highVol[i] = 50 + rnd.nextInt(200);
		}
		return s;
	}

	@Test
	public void nullSeriesFallsBackToRawQuote()
	{
		TradeEngine.Result r = TradeEngine.compute(836, 845, 1_000_000L, 1_000_000L, null, 1618);
		Assert.assertFalse(r.viable);
		Assert.assertEquals(836, r.buy);
		Assert.assertEquals(845, r.sell);
		Assert.assertTrue(r.lowConf);
	}

	@Test
	public void tooFewBucketsFallsBackToRawQuote()
	{
		TradeEngine.Series series = syntheticSeries(1_000_000L, 5, 800, 820, 42);
		TradeEngine.Result r = TradeEngine.compute(805, 815, 1_000_000L, 1_000_000L, series, 1618);
		Assert.assertFalse(r.viable);
		Assert.assertEquals(805, r.buy);
		Assert.assertEquals(815, r.sell);
	}

	@Test
	public void viableSeriesProducesSensibleFillableSpread()
	{
		int n = 200;
		long now = 1_000_000L;
		TradeEngine.Series series = syntheticSeries(now, n, 800, 850, 7);
		TradeEngine.Result r = TradeEngine.compute((long) series.low[n - 1], (long) series.high[n - 1], now, now, series, 1618);
		Assert.assertTrue(r.viable);
		Assert.assertTrue(r.buy > 0);
		Assert.assertTrue(r.sell > r.buy);
		Assert.assertTrue(r.edge >= TradeEngine.minEdge(r.buy));
	}

	@Test
	public void minEdgeScalesWithPriceAndHasAFloor()
	{
		Assert.assertEquals(2, TradeEngine.minEdge(100));
		Assert.assertTrue(TradeEngine.minEdge(1_000_000) > 2);
	}

	/* ── sellTarget / buyTarget: never quote the wrong side of the book ───
	   Regression cover for the live Yew logs case: insta-buy was 115, the
	   engine returned a 107/111 flip pair, and the offer screen told the
	   player to SELL at 111 — 4 gp under a standing bid, and disagreeing
	   with both pocketge.com and Flipping Copilot on the same screen. */

	@Test
	public void sellTarget_neverQuotesUnderTheStandingBid()
	{
		Assert.assertEquals(115L, TradeEngine.sellTarget(111L, 115L)); // the Yew logs case
	}

	@Test
	public void sellTarget_leavesAHigherAskAlone()
	{
		// Asking above the bid is the normal patient sell — not clamped down.
		Assert.assertEquals(120L, TradeEngine.sellTarget(120L, 115L));
		Assert.assertEquals(115L, TradeEngine.sellTarget(115L, 115L));
	}

	@Test
	public void sellTarget_withoutAQuoteChangesNothing()
	{
		Assert.assertEquals(111L, TradeEngine.sellTarget(111L, 0L));
		Assert.assertEquals(111L, TradeEngine.sellTarget(111L, -1L));
	}

	@Test
	public void buyTarget_neverBidsOverTheStandingAsk()
	{
		Assert.assertEquals(112L, TradeEngine.buyTarget(120L, 112L));
	}

	@Test
	public void buyTarget_leavesALowerBidAlone()
	{
		// Bidding under the ask is the normal patient buy — not clamped up.
		Assert.assertEquals(111L, TradeEngine.buyTarget(111L, 112L));
		Assert.assertEquals(112L, TradeEngine.buyTarget(112L, 112L));
	}

	@Test
	public void buyTarget_withoutAQuoteChangesNothing()
	{
		Assert.assertEquals(120L, TradeEngine.buyTarget(120L, 0L));
	}

	@Test
	public void clampedPairStillLeavesTheSpreadIntact()
	{
		// Whatever the engine picked, the clamped pair must never cross:
		// buy <= insta-sell <= insta-buy <= sell.
		final long rawLow = 112, rawHigh = 115;
		long b = TradeEngine.buyTarget(107L, rawLow);
		long s = TradeEngine.sellTarget(111L, rawHigh);
		Assert.assertTrue("buy " + b + " must not exceed insta-sell " + rawLow, b <= rawLow);
		Assert.assertTrue("sell " + s + " must not undercut insta-buy " + rawHigh, s >= rawHigh);
		Assert.assertTrue("clamped pair crossed: buy " + b + " >= sell " + s, b < s);
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import org.junit.Assert;
import org.junit.Test;

/**
 * What a slot's sell has booked and not yet shown, kept on the slot's saved
 * record: "even if i missed it live, the next time i load into this ge
 * screen, it should have said +64kgp over rune darts in that square".
 */
public class UnseenSaleTest
{
	private static final int DART = 811;
	private static final long MAIN = 42L;
	private static final long ALT = 43L;

	/** Bought 7,132 at 190, then listed in slot 2 at 200: 196 after tax,
	 *  6 each in all. */
	private static FlipTracker withASell(long account)
	{
		final FlipTracker t = new FlipTracker();
		t.setAccountHash(account);
		t.onOffer(1_000, 0, DART, "Rune dart", true, 0, 0, 190, 7_132, false);
		t.onOffer(2_000, 0, DART, "Rune dart", true, 7_132, 7_132L * 190, 190, 7_132, false);
		t.onOffer(3_000, 0, 0, "", false, 0, 0, 0, 0, true);
		t.onOffer(4_000, 2, DART, "Rune dart", false, 0, 0, 200, 7_132, false);
		return t;
	}

	private static void sell(FlipTracker t, long when, int sold)
	{
		t.onOffer(when, 2, DART, "Rune dart", false, sold, sold * 200L, 200, 7_132, false);
	}

	private static FlipTracker restarted(FlipTracker t, long account)
	{
		final Gson gson = new Gson();
		final FlipTracker after = new FlipTracker();
		after.restore(gson.fromJson(gson.toJson(t.snapshot()), FlipTracker.State.class));
		after.setAccountHash(account);
		return after;
	}

	@Test
	public void whatSoldWaitsUntilShownThenOnlyWhatIsNew()
	{
		final FlipTracker t = withASell(MAIN);
		Assert.assertNull("nothing sold yet", t.unseenBy(2, DART));
		sell(t, 5_000, 3_000);
		sell(t, 6_000, 7_132);
		Assert.assertArrayEquals("the whole sale, every batch", new long[]{7_132, 7_132L * 6, FlipTracker.UNSEEN_PROFIT}, t.unseenBy(2, DART));
		t.markShown(2);
		Assert.assertNull("shown", t.unseenBy(2, DART));
		Assert.assertTrue("and to be saved", t.takeSlotsDirty());
	}

	@Test
	public void onlyForTheSellOfThatItem()
	{
		final FlipTracker t = withASell(MAIN);
		sell(t, 5_000, 7_132);
		Assert.assertNull("another item", t.unseenBy(2, 565));
		Assert.assertNull("an empty slot", t.unseenBy(5, DART));
		Assert.assertNull("the buy slot's record, emptied", t.unseenBy(0, DART));
	}

	/** Sold with the Exchange shut, then RuneLite restarted — overnight, or
	 *  its weekly update — before the Exchange was opened. */
	@Test
	public void survivesARestart()
	{
		final FlipTracker t = withASell(MAIN);
		sell(t, 5_000, 7_132);
		final FlipTracker after = restarted(t, MAIN);
		Assert.assertArrayEquals(new long[]{7_132, 7_132L * 6, FlipTracker.UNSEEN_PROFIT}, after.unseenBy(2, DART));
		after.markShown(2);
		Assert.assertNull("and once shown, not again after the next", restarted(after, MAIN).unseenBy(2, DART));
	}

	/** Collected on mobile and the same item relisted in the slot on other
	 *  terms: a new offer, with nothing of its own to show. The old figure
	 *  used to land on it. */
	@Test
	public void aRelistOnOtherTermsStartsAtNothing()
	{
		final FlipTracker t = withASell(MAIN);
		sell(t, 5_000, 7_132);
		final FlipTracker after = restarted(t, MAIN);
		after.markSlotsUnwatched();
		after.onOffer(9_000, 2, DART, "Rune dart", false, 0, 0, 205, 5_000, false);
		Assert.assertNull(after.unseenBy(2, DART));
	}

	/** Switched off: every character's waiting sale counts as shown. */
	@Test
	public void markAllShownCoversEveryCharacter()
	{
		final FlipTracker t = withASell(MAIN);
		sell(t, 5_000, 3_000);
		t.setAccountHash(ALT);
		t.onOffer(6_000, 0, DART, "Rune dart", true, 0, 0, 190, 100, false);
		t.onOffer(6_100, 0, DART, "Rune dart", true, 100, 100L * 190, 190, 100, false);
		t.onOffer(6_200, 0, 0, "", false, 0, 0, 0, 0, true);
		t.onOffer(6_300, 4, DART, "Rune dart", false, 0, 0, 200, 100, false);
		t.onOffer(6_400, 4, DART, "Rune dart", false, 100, 100L * 200, 200, 100, false);
		Assert.assertNotNull(t.unseenBy(4, DART));
		t.takeSlotsDirty();
		t.markAllShown();
		Assert.assertTrue(t.takeSlotsDirty());
		Assert.assertNull(t.unseenBy(4, DART));
		t.setAccountHash(MAIN);
		Assert.assertNull(t.unseenBy(2, DART));
	}

	/** One character's figures are not another's. */
	@Test
	public void belongsToItsCharacter()
	{
		final FlipTracker t = withASell(MAIN);
		sell(t, 5_000, 7_132);
		t.setAccountHash(ALT);
		Assert.assertNull(t.unseenBy(2, DART));
		t.setAccountHash(MAIN);
		Assert.assertNotNull(t.unseenBy(2, DART));
	}

	/** A save from before figures existed: what it booked counts as shown,
	 *  so an upgrade does not pop every sale in progress. */
	@Test
	public void anUpgradePopsNothingOld()
	{
		final FlipTracker t = withASell(MAIN);
		sell(t, 5_000, 3_000);
		final FlipTracker.State saved = t.snapshot();
		for (java.util.Map<Integer, long[]> rows : saved.slotsByAccount.values())
		{
			rows.replaceAll((slot, row) -> java.util.Arrays.copyOf(row, 10));
		}
		final Gson gson = new Gson();
		final FlipTracker after = new FlipTracker();
		after.restore(gson.fromJson(gson.toJson(saved), FlipTracker.State.class));
		after.setAccountHash(MAIN);
		Assert.assertNotNull("booked kept", after.bookedBy(2));
		Assert.assertNull(after.unseenBy(2, DART));
		sell(after, 9_000, 4_000);
		Assert.assertArrayEquals("what sells after the upgrade does show", new long[]{1_000, 6_000, FlipTracker.UNSEEN_PROFIT}, after.unseenBy(2, DART));
	}

	/** Older still: rows with no booked totals, seeded from the flips. */
	@Test
	public void anOlderSaveSeededFromFlipsPopsNothingOld()
	{
		final FlipTracker t = withASell(MAIN);
		sell(t, 5_000, 3_000);
		final FlipTracker.State saved = t.snapshot();
		for (java.util.Map<Integer, long[]> rows : saved.slotsByAccount.values())
		{
			rows.replaceAll((slot, row) -> java.util.Arrays.copyOf(row, 8));
		}
		final Gson gson = new Gson();
		final FlipTracker after = new FlipTracker();
		after.restore(gson.fromJson(gson.toJson(saved), FlipTracker.State.class));
		after.setAccountHash(MAIN);
		Assert.assertArrayEquals(new long[]{3_000, 18_000}, after.bookedBy(2));
		Assert.assertNull(after.unseenBy(2, DART));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Proxy;
import java.util.EnumSet;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import org.junit.Assert;
import org.junit.Test;

/**
 * How many Grand Exchange slots a world lets you use.
 *
 * The number was right in the advice text and wrong in the slot overlay,
 * because only one of them asked. On a free world the client reports the
 * five members-only slots as EMPTY — present in the interface, just locked —
 * and the overlay walked all eight looking for the first empty one, so the
 * "start your offer here" ring landed on a slot the player could not open:
 * "its trying to tell me to use a ge slot i dont have".
 */
public class UsableGeSlotsTest
{
	/**
	 * A Client that answers getWorldType and nothing else, as a dynamic proxy.
	 *
	 * NOT {@code new Client(){ ... }}. The first version of this test did
	 * that, and it compiled against the offline stub — whose methods all had
	 * default bodies — and then failed the real Gradle build, where Client
	 * has several hundred abstract methods. BankHighlightOverlayTest had
	 * already hit and documented the identical mistake, in the same
	 * directory. The stub is abstract now, so the anonymous form no longer
	 * compiles anywhere; a proxy is shaped by the interface at runtime and
	 * cannot fall out of step with either version of it.
	 */
	private static Client world(EnumSet<WorldType> types)
	{
		return (Client) Proxy.newProxyInstance(
			Client.class.getClassLoader(),
			new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				if ("getWorldType".equals(method.getName()))
				{
					return types;
				}
				final Class<?> r = method.getReturnType();
				if (r == boolean.class)
				{
					return false;
				}
				if (r.isPrimitive())
				{
					return 0;
				}
				return null;
			});
	}

	private static Client free()
	{
		return world(EnumSet.noneOf(WorldType.class));
	}

	private static Client members()
	{
		return world(EnumSet.of(WorldType.MEMBERS));
	}

	@Test
	public void aFreeWorldHasThree()
	{
		Assert.assertEquals(3, PocketGeTrackerPlugin.usableGeSlots(free()));
	}

	@Test
	public void aMembersWorldHasEight()
	{
		Assert.assertEquals(8, PocketGeTrackerPlugin.usableGeSlots(members()));
	}

	/** Before the client knows what world it is on, assume the smaller
	 *  number — a ring on a slot you cannot use is worse than no ring. */
	@Test
	public void unknownWorldIsTreatedAsFree()
	{
		Assert.assertEquals(3, PocketGeTrackerPlugin.usableGeSlots(null));
		Assert.assertEquals(3, PocketGeTrackerPlugin.usableGeSlots(world(null)));
	}

	/** The two constants the rest of the plugin sizes against are the same
	 *  numbers this returns, so the advice and the overlay cannot disagree. */
	@Test
	public void agreesWithTheSizingConstants()
	{
		Assert.assertEquals(PocketGeTrackerPlugin.F2P_GE_SLOTS,
			PocketGeTrackerPlugin.usableGeSlots(free()));
		Assert.assertEquals(PocketGeTrackerPlugin.MEMBERS_GE_SLOTS,
			PocketGeTrackerPlugin.usableGeSlots(members()));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.border.CompoundBorder;
import javax.swing.border.MatteBorder;
import org.junit.Assert;
import org.junit.Test;

/**
 * "Every time i cook a shark, it flashes the colors on the side bar": each
 * inventory change rebuilt the watchlist, and a rebuilt row was painted bare
 * until its glow timer's first tick. Unchanged rows are now left alone, and
 * a rebuilt row wears its glow from its first frame.
 */
public class WatchlistFlickerTest
{
	private static FavoritesPanel panel()
	{
		final FavoritesPanel.Actions actions = (FavoritesPanel.Actions) Proxy.newProxyInstance(
			FavoritesPanel.Actions.class.getClassLoader(), new Class<?>[]{FavoritesPanel.Actions.class},
			(p, m, a) ->
			{
				final Class<?> r = m.getReturnType();
				return r == boolean.class ? (Object) false : r.isPrimitive() ? (Object) 0 : null;
			});
		final FavoritesPanel panel = new FavoritesPanel(null, actions);
		panel.setLoggedIn(true);
		return panel;
	}

	private static List<FavoritesPanel.Row> rows()
	{
		final List<FavoritesPanel.Row> out = new ArrayList<>();
		final int[] ids = {1607, 555, 1603};
		final String[] names = {"Sapphire", "Water rune", "Ruby"};
		for (int i = 0; i < ids.length; i++)
		{
			final FavoritesPanel.Row r = new FavoritesPanel.Row();
			r.id = ids[i];
			r.name = names[i];
			r.price = 100 + i;
			r.tier = i == 0 ? PriceExtremes.Tier.NONE : PriceExtremes.Tier.LOW_5D;
			r.changePct = i == 0 ? -17 : 0; // the sapphire's spike
			out.add(r);
		}
		return out;
	}

	private static JPanel rowsPanel(FavoritesPanel p) throws Exception
	{
		final Field f = FavoritesPanel.class.getDeclaredField("rows");
		f.setAccessible(true);
		return (JPanel) f.get(p);
	}

	@Test
	public void anUnchangedListIsLeftAlone() throws Exception
	{
		final FavoritesPanel p = panel();
		p.update(rows());
		final java.awt.Component[] before = rowsPanel(p).getComponents();
		p.update(rows()); // a shark cooked: the same rows, as new objects
		Assert.assertArrayEquals("the same row components, glows untouched", before, rowsPanel(p).getComponents());

		final List<FavoritesPanel.Row> moved = rows();
		moved.get(1).price = 999;
		p.update(moved);
		Assert.assertNotSame("a real change rebuilds", before[1], rowsPanel(p).getComponents()[1]);
		p.stopPulseTimers();
	}

	@Test
	public void aRebuiltRowGlowsFromItsFirstFrame() throws Exception
	{
		final FavoritesPanel p = panel();
		p.update(rows());
		final java.awt.Component[] built = rowsPanel(p).getComponents();
		Assert.assertFalse("the spike row's outline is on at once, not the bare padding",
			((JComponent) built[0]).getBorder() instanceof javax.swing.border.EmptyBorder);
		for (int i = 1; i < 3; i++)
		{
			final javax.swing.border.Border b = ((JComponent) built[i]).getBorder();
			Assert.assertTrue("the 5-day glow's accent is on at once, row " + i,
				b instanceof CompoundBorder && ((CompoundBorder) b).getOutsideBorder() instanceof MatteBorder);
		}
		Assert.assertTrue(FavoritesPanel.sameRows(rows(), rows()));
		final List<FavoritesPanel.Row> held = rows();
		held.get(2).heldQty = 5;
		Assert.assertFalse("what you hold counts too: the card reads it", FavoritesPanel.sameRows(rows(), held));
		p.stopPulseTimers();
	}

	/** A rebuild straight after typing in the item search keeps the search:
	 *  it stops the row glows, not the search's 200ms debounce. */
	@Test
	public void aRebuildDoesNotCancelATypedSearch() throws Exception
	{
		final java.util.concurrent.atomic.AtomicInteger searches = new java.util.concurrent.atomic.AtomicInteger();
		final FavoritesPanel.Actions actions = (FavoritesPanel.Actions) Proxy.newProxyInstance(
			FavoritesPanel.Actions.class.getClassLoader(), new Class<?>[]{FavoritesPanel.Actions.class},
			(px, m, a) ->
			{
				if ("searchItems".equals(m.getName()))
				{
					searches.incrementAndGet();
				}
				final Class<?> r = m.getReturnType();
				return r == boolean.class ? (Object) false : r.isPrimitive() ? (Object) 0 : null;
			});
		final FavoritesPanel p = new FavoritesPanel(null, actions);
		p.setLoggedIn(true);
		p.update(rows());
		final Field f = FavoritesPanel.class.getDeclaredField("searchField");
		f.setAccessible(true);
		final javax.swing.JTextField field = (javax.swing.JTextField) f.get(p);
		javax.swing.SwingUtilities.invokeAndWait(() -> field.setText("shark"));
		final List<FavoritesPanel.Row> changed = rows();
		changed.get(0).heldQty = 1; // a shark cooked: a real change, so a real rebuild
		javax.swing.SwingUtilities.invokeAndWait(() -> p.update(changed));
		Thread.sleep(600);
		Assert.assertTrue("the typed search still ran", searches.get() >= 1);
		p.stopPulseTimers();
	}

	/** Muted, no row glows — the badges stay, the spike's still in its
	 *  colours — and the row menu offers to unmute. */
	@Test
	public void mutedRowsKeepTheirBadgesButNotTheirBorders() throws Exception
	{
		final FavoritesPanel p = panel();
		p.setGlowEnabled(false);
		p.update(rows());
		for (java.awt.Component c : rowsPanel(p).getComponents())
		{
			Assert.assertTrue("no glow border", ((JComponent) c).getBorder() instanceof javax.swing.border.EmptyBorder);
			Assert.assertNull("not marked as an outlined row", ((JComponent) c).getClientProperty(FavoritesPanel.SPIKE_ROW));
		}
		final javax.swing.JLabel spike = findLabel(rowsPanel(p).getComponent(0), "%");
		Assert.assertNotNull("the spike's % badge is still there", spike);
		Assert.assertNotEquals("in its colours, not Swing's grey", new javax.swing.JLabel().getForeground(), spike.getForeground());
		Assert.assertEquals("Unmute glow borders", ((javax.swing.JMenuItem) p.rowMenu(rows().get(0)).getComponent(3)).getText());
		p.setGlowEnabled(true);
		Assert.assertEquals("Mute glow borders", ((javax.swing.JMenuItem) p.rowMenu(rows().get(0)).getComponent(3)).getText());
		Assert.assertFalse(((JComponent) rowsPanel(p).getComponent(0)).getBorder() instanceof javax.swing.border.EmptyBorder);
		p.stopPulseTimers();
	}

	private static javax.swing.JLabel findLabel(java.awt.Component c, String containing)
	{
		if (c instanceof javax.swing.JLabel && ((javax.swing.JLabel) c).getText() != null
			&& ((javax.swing.JLabel) c).getText().contains(containing))
		{
			return (javax.swing.JLabel) c;
		}
		if (c instanceof java.awt.Container)
		{
			for (java.awt.Component k : ((java.awt.Container) c).getComponents())
			{
				final javax.swing.JLabel l = findLabel(k, containing);
				if (l != null)
				{
					return l;
				}
			}
		}
		return null;
	}
}

