package net.runelite.client.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Insets;

/**
 * Stub of RuneLite's DynamicGridLayout: a GridLayout that sizes rows/columns
 * to each child's own preferred size rather than forcing a uniform cell.
 */
public class DynamicGridLayout extends GridLayout
{
	public DynamicGridLayout()
	{
		this(1, 0, 0, 0);
	}

	public DynamicGridLayout(int rows, int cols)
	{
		this(rows, cols, 0, 0);
	}

	public DynamicGridLayout(int rows, int cols, int hgap, int vgap)
	{
		super(rows, cols, hgap, vgap);
	}

	@Override
	public Dimension preferredLayoutSize(Container parent)
	{
		synchronized (parent.getTreeLock())
		{
			return layoutSize(parent, true);
		}
	}

	@Override
	public Dimension minimumLayoutSize(Container parent)
	{
		synchronized (parent.getTreeLock())
		{
			return layoutSize(parent, false);
		}
	}

	private Dimension layoutSize(Container parent, boolean preferred)
	{
		final Insets insets = parent.getInsets();
		final int ncomponents = parent.getComponentCount();
		int nrows = getRows();
		int ncols = getColumns();

		if (nrows > 0)
		{
			ncols = (ncomponents + nrows - 1) / nrows;
		}
		else
		{
			nrows = (ncomponents + ncols - 1) / ncols;
		}

		final int[] w = new int[ncols];
		final int[] h = new int[nrows];
		for (int i = 0; i < ncomponents; i++)
		{
			final int r = i / ncols;
			final int c = i % ncols;
			final Component comp = parent.getComponent(i);
			final Dimension d = preferred ? comp.getPreferredSize() : comp.getMinimumSize();
			if (w[c] < d.width)
			{
				w[c] = d.width;
			}
			if (h[r] < d.height)
			{
				h[r] = d.height;
			}
		}

		int nw = 0;
		for (int j = 0; j < ncols; j++)
		{
			nw += w[j];
		}
		int nh = 0;
		for (int i = 0; i < nrows; i++)
		{
			nh += h[i];
		}

		return new Dimension(insets.left + insets.right + nw + (ncols - 1) * getHgap(),
			insets.top + insets.bottom + nh + (nrows - 1) * getVgap());
	}

	@Override
	public void layoutContainer(Container parent)
	{
		synchronized (parent.getTreeLock())
		{
			final Insets insets = parent.getInsets();
			final int ncomponents = parent.getComponentCount();
			int nrows = getRows();
			int ncols = getColumns();

			if (ncomponents == 0)
			{
				return;
			}

			if (nrows > 0)
			{
				ncols = (ncomponents + nrows - 1) / nrows;
			}
			else
			{
				nrows = (ncomponents + ncols - 1) / ncols;
			}

			final int hgap = getHgap();
			final int vgap = getVgap();

			final Dimension pd = preferredLayoutSize(parent);
			final double sw = (1.0 * parent.getWidth()) / pd.width;
			final double sh = (1.0 * parent.getHeight()) / pd.height;

			final int[] w = new int[ncols];
			final int[] h = new int[nrows];
			for (int i = 0; i < ncomponents; i++)
			{
				final int r = i / ncols;
				final int c = i % ncols;
				final Component comp = parent.getComponent(i);
				final Dimension d = comp.getPreferredSize();
				d.width = (int) (sw * d.width);
				d.height = (int) (sh * d.height);
				if (w[c] < d.width)
				{
					w[c] = d.width;
				}
				if (h[r] < d.height)
				{
					h[r] = d.height;
				}
			}

			for (int c = 0, x = insets.left; c < ncols; c++)
			{
				for (int r = 0, y = insets.top; r < nrows; r++)
				{
					final int i = r * ncols + c;
					if (i < ncomponents)
					{
						parent.getComponent(i).setBounds(x, y, w[c], h[r]);
					}
					y += h[r] + vgap;
				}
				x += w[c] + hgap;
			}
		}
	}
}

